      }
      Math.max(cnt, n - cnt)
    }).max
  print(max)
}

object Main extends App {
  val Array(n, k) = io.StdIn.readLine().split(' ').map(_.toInt)
  val k2 = k * 2
  val squares = Array.fill(k2)(Array.fill(k2)(0))
  for (i <- 0 to n-1) {
    val Array(x, y, color) = io.StdIn.readLine().split(' ')
    squares(x.toInt % k2)((y.toInt + (if (color == "B") 0 else k)) % k2) += 1
  }
  for {
    i <- (0 to k2-1)
    j <- (1 to k2-1)
  } squares(i)(j) += squares(i)(j-1)
  for {
    j <- (0 to k2-1)
    i <- (1 to k2-1)
  } squares(i)(j) += squares(i-1)(j)
  val cnt =
    (squares(k-1)(k-1)) +
    (squares(k2-1)(k2-1) - squares(k-1)(k2-1) - squares(k2-1)(k-1) + squares(k-1)(k-1))
  var max = Math.max(cnt, n - cnt)
  for {
    i <- (0 to k-1)
    j <- (0 to k-1)
  } {
    val cnt = 
      (squares(i)(j)) +
      (squares(i+k)(j+k) - squares(i+k)(j) - squares(i)(j+k) + squares(i)(j)) +
      (squares(k2-1)(j) - squares(i+k)(j)) +
      (squares(i)(k2-1) - squares(i)(j+k)) +
      (squares(k2-1)(k2-1) - squares(k2-1)(j+k) - squares(i+k)(k2-1) + squares(i+k)(j+k))
    max = Math.max(Math.max(cnt, n - cnt), max)
  }
  print(max)
}

