/*
the operators regarding bit

     x1: 0000 0001 0010 0101 0110 0111
     x2: xxxx 0001 0011 0100 0101 1000
x1 & x2: 0000 0001 0010 0100 0100 0000

      x: 1001 1010  1100 1011 1101  1111
x & - x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

x << y is x * 2 ** y
x >> y is rep(i, y) x = x // 2 
*/

const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, k, x, y;
str c;
ll cnt[2][1005][2005];
ll cum[2][1005][2005];
ll e[6];

void solve(){
    ll k2 = 2 * k;
    rep(i, 2) rep(x, k) rep(y, 2 * k) cnt[i][x][y] = 0;
    rep(i, n){
        in3(x, y, c);
        if (c == "W") cnt[0][x % k][y % k2]++;
        else cnt[1][x % k][y % k2]++;
    }
    rep(i, 2) rep(x, k) cum[i][x + 1][0] = 0;
    rep(i, 2) rep(y, 2 * k + 1) cum[i][0][y] = 0;
    rep(i, 2) rep(x, k) rep(y, 2 * k) cum[i][x + 1][y + 1] = cum[i][x + 1][y] + cnt[i][x][y];
    rep(i, 2) rep(x, k) rep(y, 2 * k + 1) cum[i][x + 1][y] += cum[i][x][y];

    /*
    rep(i, 2) {
        prl("####");
        rep(y, 2 * k + 1){
            rep(x, k + 1){
                prs(cum[i][x][y]);
            }
            prl("");
        }
    }
    */

    rep(x, k) rep(y, 2 * k){
        if (x == 0 && (y == 0 || y == k)){
            if (y == 0) {e[0] = cum[0][k][k]; e[1] = cum[1][k][2 * k] - cum[1][k][k];}
            else {e[0] = cum[1][k][k]; e[1] = cum[0][k][2 * k] - cum[0][k][k];}
            answer = max(answer, e[0] + e[1]);
        }else if (x == 0){
            if (y < k) {
                e[0] = cum[0][k][k - y];
                e[1] = cum[1][k][2 * k - y] - cum[1][k][k - y];
                e[2] = cum[0][k][2 * k] - cum[0][k][2 * k - y];
            }else {
                e[0] = cum[1][k][y - k];
                e[1] = cum[0][k][y] - cum[0][k][y - k];
                e[2] = cum[1][k][2 * k] - cum[1][k][y];
            }
            answer = max(answer, e[0] + e[1] + e[2]);
        }else if (y == 0 || y == k){
            if (y == 0) {
                e[0] = cum[0][x + 1][k];
                e[1] = cum[1][x + 1][2 * k] - cum[1][x + 1][k];
                e[2] = cum[1][k][k] - cum[1][x + 1][k];
                e[3] = cum[0][k][2 * k] - cum[0][x + 1][2 * k] - cum[0][k][k] + cum[0][x + 1][k];
            }else {
                e[0] = cum[1][x + 1][k];
                e[1] = cum[0][x + 1][2 * k] - cum[0][x + 1][k];
                e[2] = cum[0][k][k] - cum[0][x + 1][k];
                e[3] = cum[1][k][2 * k] - cum[1][x + 1][2 * k] - cum[1][k][k] + cum[1][x + 1][k];
            }
            answer = max(answer, e[0] + e[1] + e[2] + e[3]);
        }else {
            if (y < k) {
                e[0] = cum[0][x + 1][k - y];
                e[1] = cum[1][x + 1][2 * k - y] - cum[1][x + 1][k - y];
                e[2] = cum[1][k][k - y] - cum[1][x + 1][k - y];
                e[3] = cum[0][k][2 * k - y] - cum[0][x + 1][2 * k - y] - cum[0][k][k - y] + cum[0][x + 1][k - y];
                e[4] = cum[0][x + 1][2 * k] - cum[0][x + 1][2 * k - y];
                e[5] = cum[1][k][2 * k] - cum[1][x + 1][2 * k] - cum[1][k][2 * k - y] + cum[1][x + 1][2 * k - y];
            }else {
                e[0] = cum[1][x + 1][y - k];
                e[1] = cum[0][x + 1][y] - cum[0][x + 1][y - k];
                e[2] = cum[0][k][y - k] - cum[0][x + 1][y - k];
                e[3] = cum[1][k][y] - cum[1][x + 1][y] - cum[1][k][y - k] + cum[1][x + 1][y - k];
                e[4] = cum[1][x + 1][2 * k] - cum[1][x + 1][y];
                e[5] = cum[0][k][2 * k] - cum[0][x + 1][2 * k] - cum[0][k][y] + cum[0][x + 1][y];
            }
            answer = max(answer, e[0] + e[1] + e[2] + e[3] + e[4] + e[5]);
        }
    }
    prl(answer);
}

int main(void){
    in2(n, k);
    solve();

    return 0;
}

