            if (i) cnt2 -= sum[i - 1][uy][1];
            if (i && j) cnt2 += 2 * sum[i - 1][j - 1][1];
            if (j) cnt2 += sum[2 * k - 1][j - 1][1] - sum[ux][j - 1][1];
            if (i) cnt2 += sum[i - 1][2 * k - 1][1] - sum[i - 1][uy][1];
            cnt2 += sum[2 * k - 1][2 * k - 1][1] - sum[2 * k - 1][uy][1] - sum[ux][2 * k - 1][1] + sum[ux][uy][1];
            ans = max(ans, max(cnt1 + b - cnt2, cnt2 + w - cnt1));
        }
    }
    printf("%d\n", ans);
    return 0;
}

