vector<vector<int>> make_imos(vector<vector<int>> p) 
{

	vector<vector<int>> imos(2 * K, vector<int>(2 * K, 0));

	REP(i, 2*K) {
		REP(j, 2 * K) {
			int y = i % K;
			int x = j % K;
			int cnt = (y != i ? 1 : 0) + (x != j ? 1 : 0);

			//一つだけ特殊な処理
			if (cnt % 2 == 0)imos[0][0] += p[i][j];

			//他は、2パターンは符号が逆転してるだけ
			int sub = (cnt % 2 == 0 ? 1 : -1)*p[i][j];

			//端点をプロットしていきます
			imos[0][x] -= sub;
			imos[0][x + K] += sub;
			imos[y][0] -= sub;
			imos[y][x] += 2 * sub;
			imos[y][x + K] -= 2 * sub;
			imos[y + K][0] += sub;
			imos[y + K][x] -= 2 * sub;
			imos[y + K][x + K] += 2 * sub;
			//show(imos, 2);
			//cout << "==========" << endl;
		}
	}
	return imos;
}

void paint_imos(vector<vector<int>>& imos)
{
	REP(i, 2 * K)REP(j, 2 * K - 1) {
		imos[i][j + 1] += imos[i][j];
	}
	REP(j, 2 * K)REP(i, 2 * K - 1) {
		imos[i + 1][j] += imos[i][j];
	}
}

int find_ans(vector<vector<int>> imos)
{
	int res = 0;
	REP(i, 2 * K)REP(j, 2 * K)res = max(res, imos[i][j]);
	return res;
}


//計算
void calc()
{
	auto imos = make_imos(place);
	paint_imos(imos);
	ans = find_ans(imos);
}


//出力
void output()
{
	cout << ans << endl;
}

//デバッグ
void debug()
{
	int N;
	cin>>N;
}


//メイン関数
int main()
{

	input();
	calc();
	output();
	debug();

	return 0;
}

