int N,K;
int sum[2002][2002][2]; // 0 : W , 1 : B

int get(int d,int l,int u,int r,int k){
    if(d>u or l>r) return 0;
    int ret = 0;
    ret += sum[u][r][k];
    if(d-1>=0 and l-1>=0) ret += sum[d-1][l-1][k];
    if(l-1>=0) ret -= sum[u][l-1][k];
    if(d-1>=0) ret -= sum[d-1][r][k];
    return ret;
}

