        if(cc == 'B')c[i] = 1;
        else c[i]=0;
        sum[xx][yy][c[i]]++;
    }

    for(int k=0;k<2;k++){
        for(int i=0;i<2*K;i++){
            for(int j=0;j<2*K;j++){
                sum[i][j+1][k] += sum[i][j][k];
            }
        }
        for(int j=0;j<2*K;j++){
            for(int i=0;i<2*K;i++){
                sum[i+1][j][k] += sum[i][j][k];
            }
        }
