using namespace std;
int n,k,mpb[1001][1001],mpw[1001][1001],tx,ty,verb[1001][1001],verw[1001][1001],ldb[1001][1001],rub[1001][1001],ldw[1001][1001],ruw[1001][1001],ans=0,sumb=0,sumw=0;
char c;
int main()
{
	cin>>n>>k;
	memset(mpb,0,sizeof(mpb));
	memset(mpw,0,sizeof(mpw));
	memset(verb,0,sizeof(verb));
	memset(verw,0,sizeof(verw));
	memset(ldb,0,sizeof(ldb));
	memset(rub,0,sizeof(rub));
	memset(ldw,0,sizeof(ldw));
	memset(ruw,0,sizeof(ruw));
	for(int i=1;i<=n;i++){
		cin>>tx>>ty>>c;
		if(c=='B'){
			mpb[tx%k][ty%k]+=1;
			sumb++;
		}
		else{
			mpw[tx%k][ty%k]+=1;
			sumw++;
		}
	}
	for(int i=0;i<k;i++){
		verb[0][i]=mpb[0][i];
		verw[0][i]=mpw[0][i];
	}
	for(int i=1;i<k;i++){
		for(int j=0;j<k;j++){
			verb[i][j]=verb[i-1][j]+mpb[i][j];
			verw[i][j]=verw[i-1][j]+mpw[i][j];
		}
	}
	for(int i=0;i<k;i++){
		ldb[i][0]=verb[i][0];
		ldw[i][0]=verw[i][0];
	}
	for(int i=0;i<k;i++){
		for(int j=1;j<k;j++){
			ldb[i][j]=ldb[i][j-1]+verb[i][j];
			ldw[i][j]=ldw[i][j-1]+verw[i][j];
		}
	}
	memset(verb,0,sizeof(verb));
	memset(verw,0,sizeof(verw));
	for(int i=0;i<k;i++){
		verb[k-1][i]=mpb[k-1][i];
		verw[k-1][i]=mpw[k-1][i];
	}
	for(int i=k-2;i>=0;i--){
		for(int j=k-1;j>=0;j--){
			verb[i][j]=verb[i+1][j]+mpb[i][j];
			verw[i][j]=verw[i+1][j]+mpw[i][j];
		}
	}
	for(int i=0;i<k;i++){
		rub[i][k-1]=verb[i][k-1];
		ruw[i][k-1]=verw[i][k-1];
	}
	for(int i=k-2;i>=0;i--){
		for(int j=k-1;j>=0;j--){
			rub[i][j]=rub[i][j+1]+verb[i][j];
			ldw[i][j]=ruw[i][j+1]+verw[i][j];
		}
	}
	for(int i=0;i<k;i++){
		for(int j=0;j<k;j++){
			int temp1=ldb[i][j]+rub[i+1][j+1];
			int temp2=ldw[i][j]+ruw[i+1][j+1];
			if(temp1+sumw-temp2>ans){
				ans=temp1+sumw-temp2;
			}
			if(temp2+sumb-temp1>ans){
				ans=temp2+sumb-temp1;
			}
		}
	}
	cout<<ans<<endl;
}

