int amount(int x1, int y1, int x2, int y2)
{
    if(x2 > 2 * k - 1 || y2 > 2 * k - 1)
        return 0;

    if(x1 < 0 || y1 < 0)
        return 0;

    x2 = max(0, x2);
    y2 = max(0, y2);
    x1 = min(2 * k - 1, x1);
    y1 = min(2 * k - 1, y1);


    return arr[y1][x1] - (x2 > 0 ? arr[y1][x2 - 1] : 0) - (y2 > 0 ? arr[y2 - 1][x1] : 0) + (y2 > 0 && x2 > 0 ? arr[y2 - 1][x2 - 1] : 0);
}

int main()
{
    ios_base::sync_with_stdio(false);
