    {
        if(c[i] == 'W')
        {
            x[i] += k;
            c[i] = 'B';
        }
    }

    for(int i = 1; i <= n; ++i)
    {
        x[i] %= 2 * k;
        y[i] %= 2 * k;

        ++arr[y[i]][x[i]];
    }


    for(int i = 1; i < 2 * k; ++i)
        arr[0][i] += arr[0][i - 1];


    for(int i = 1; i < 2 * k; ++i)
        arr[i][0] += arr[i - 1][0];

    for(int i = 1; i < 2 * k; ++i)
        for(int j = 1; j < 2 * k; ++j)
            arr[i][j] += arr[i - 1][j] + arr[i][j - 1] - arr[i - 1][j - 1];


    int answer = 0;

    for(int i = -k; i < 2 * k; ++i)
        for(int j = -k; j < 2 * k; ++j)
        {
            int temp = 0;

            temp += amount(i, j, i - k + 1, j - k + 1);

            temp += amount(i + k, j + k, i + 1, j + 1);

            temp += amount(i + 2 * k, j, i + k + 1, j - k + 1);

            temp += amount(i, j + 2 * k, i - k + 1, j + k + 1);

            temp += amount(i + 2 * k, j + 2 * k, i + k + 1, j + k + 1);

            answer = max(answer, temp);
        }


    cout << answer << '\n';
}

