vector<vector<int>> imos;

void setrect(int i, int j){
    if(i<0 || j < 0  ) return;

    imos[ max(0, i+1-K) ][ max(0, j+1-K) ]++;
    imos[ max(0, i+1-K) ][ min(2*K, j+1) ]--;
    imos[ min(2*K, i+1) ][ max(0, j+1-K) ]--;
    imos[ min(2*K, i+1) ][ min(2*K, j+1) ]++;
}

void setimos(int a){
    int i = y[a], j = x[a];
    setrect(i, j);
    setrect(i+2*K, j);
    setrect(i+K, j-K);
    setrect(i-K, j-K);
    setrect(i+K, j+K);
    setrect(i-K, j+K);
    setrect(i+2*K, j+2*K);
    setrect(i, j+2*K);
}

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    cin >> N >> K;
    x.resize(N);
    y.resize(N);
    c.resize(N);
    imos.resize(4*K, vector<int>(4*K, 0));
    rep(i, N) cin >> x[i] >> y[i] >> c[i];

    rep(i, N) if(c[i] == 'W') y[i] += K;
    rep(i, N) { x[i] %= 2*K; y[i] %= 2*K; }

    rep(i, N) setimos(i);

    rep(i, 2*K) repr(j, 1, 2*K) imos[i][j] += imos[i][j-1];
    rep(j, 2*K) repr(i, 1, 2*K) imos[i][j] += imos[i-1][j];
    int ans = 0;
    rep(i, 2*K) rep(j, 2*K) chmax(ans, imos[i][j]);
    cout << ans << endl;

}

