using namespace std;

int getAreaSum(int map[2001][2001], int x1, int y1, int x2, int y2 )
{
  return map[x2][y2] - map[x1][y2] - map[x2][y1] + map[x1][y1];
}

int main(void)
{
  int i, j, N, K;
  int x[100000] = { 0 };
  int y[100000] = { 0 };
  char c[100000] = { 0 };
  int npos[100000][2] = { 0 };
  int map[2001][2001] = {{ 0 }};
  int offset_x, offset_y;
  int a,b;
  int cnt, cnt_max;

  // scan number
  scanf("%d %d",&N,&K);

  // scan parameter
  for(i=0;i<N;i++)
  {
    scanf("%d %d %c",&x[i],&y[i],&c[i]);
  }

  // normalization to black
  for(i=0;i<N;i++)
  {
    if(c[i]=='B')
    {
      npos[i][0] = x[i]%(2*K);
      npos[i][1] = y[i]%(2*K);
    }
    else if(c[i]=='W')
    {
      npos[i][0] = (x[i]+K)%(2*K);
      npos[i][1] = y[i]%(2*K);
    }
    map[npos[i][0]+1][npos[i][1]+1] = 1;
  }

  /*printf("before\n");
  for(i=0;i<=2*K;i++)
  {
    for(j=0;j<=2*K;j++)
    {
      printf("%d ",map[i][j]);
    }
    printf("\n");
  }*/

  // sum
  for(i=1;i<=2*K;i++)
  {
    for(j=1;j<=2*K;j++)
    {
      map[i][j] += map[i][j-1] + map[i-1][j] - map[i-1][j-1];
    }
  }

  /*printf("after\n");
  for(i=0;i<=2*K;i++)
  {
    for(j=0;j<=2*K;j++)
    {
      printf("%d ",map[i][j]);
    }
    printf("\n");
  }*/

  cnt_max = 0;
  // BWB WBW
  // WBW BWB
  // BWB WBW
  for(offset_x=0;offset_x<K;offset_x++)
  {
    for(offset_y=0;offset_y<K;offset_y++)
    {
      cnt = 0;
      cnt += getAreaSum(map,0,0,offset_x,offset_y);
      cnt += getAreaSum(map,0,offset_y+K,offset_x,2*K);
      cnt += getAreaSum(map,offset_x,offset_y,offset_x+K,offset_y+K);
      cnt += getAreaSum(map,offset_x+K,0,2*K,offset_y);
      cnt += getAreaSum(map,offset_x+K,offset_y+K,2*K,2*K);
      if (max(cnt,N-cnt)>cnt_max)
      {
        cnt_max = max(cnt,N-cnt);
      }
    }
  }

  printf("%d",cnt_max);
}

