		if(y + k >= 2 * k) {
			masu[max(0ll,x - k + 1)][0]++;
			masu[x + 1][0]--;
			masu[max(0ll,x - k + 1)][y + k - 2 * k + 1]--;
			masu[x + 1][y + k - 2 * k + 1]--;
		}
		if(x - k + 1 < 0 && y + k >= 2 * k) {
			masu[2 * k + x - k + 1][0]++;
			masu[2 * k + x - k + 1][y + k - 2 * k + 1]--;
		}
	}

	REP(i,2 * k) {
		REP(j,2 * k) {
			if(0 < j) {
				masu[i][j] += masu[i][j - 1];
			}
		}
	}

	REP(i,2 * k) {
		REP(j,2 * k) {
			if(0 < j) {
				masu[j][i] += masu[j - 1][i];
			}
		}
	}

	ll ans = 0;

	REP(i,2 * k) {
		REP(j,2 * k) {
			ans = max(masu[i][j],ans);
		}
	}

	cout << ans << endl;

	return 0;
}

