template<typename T>
struct RectangleSum {
	vector<vector<T>>imos;

	RectangleSum(vector<vector<T>>in) :imos(in.size(), vector<T>(in.size(), 0)) {
		for (int i = 1; i < in.size(); i++) {
			for (int j = 1; j < in.size(); j++) {
				imos[i][j] = in[i][j] + imos[i - 1][j] + imos[i][j - 1] - imos[i - 1][j - 1];
			}
		}
	}

	////xy平面を見て(p1,p2)が右上
	T GetRectangle(T p1, T p2, T q1, T q2) {
		return imos[p1][p2] - imos[q1 - 1][p2] - imos[p2][q2 - 1] + imos[q1 - 1][q2 - 1];
	}
};

int main() {
	cin >> N >> K;
	vector<vector<int>>recb(K + 1, vector<int>(K + 1, 0));
	vector<vector<int>>recw(K + 1, vector<int>(K + 1, 0));
	for (int i = 0; i < N; i++) {
		int x, y;
		char c;
		cin >> x >> y >> c;
		if ((x / K + y / K) & 1) {
			if (c == 'B')recw[x%K + 1][y%K + 1]++;
			else recb[x % K + 1][y % K + 1]++;
		}
		else {
			if (c == 'B')recb[x%K + 1][y%K + 1]++;
			else recw[x%K + 1][y%K + 1]++;
		}
	}
	RectangleSum<int> b(recb);
	RectangleSum<int> w(recw);
	ans = max(b.GetRectangle(K, K, 1, 1), w.GetRectangle(K, K, 1, 1));
	for (int i = 1; i < K; i++) {
		ll tmp1 = b.GetRectangle(i, K, 1, 1) + w.GetRectangle(K, K, i + 1, 1);
		ll tmp2 = w.GetRectangle(i, K, 1, 1) + b.GetRectangle(K, K, i + 1, 1);
		ll tmp3 = b.GetRectangle(K, i, 1, 1) + w.GetRectangle(K, K, 1, i + 1);
		ll tmp4 = w.GetRectangle(K, i, 1, 1) + b.GetRectangle(K, K, 1, i + 1);
		ans = max(ans, max(max(tmp1, tmp2), max(tmp3, tmp4)));
	}
	for (int i = 1; i < K; i++) {
		for (int j = 1; j < K; j++) {
			ll tmp1 = b.GetRectangle(i, j, 1, 1) + b.GetRectangle(K, K, i + 1, j + 1) + w.GetRectangle(K, j, i + 1, 1) + w.GetRectangle(i, K, 1, j + 1);
			ll tmp2 = w.GetRectangle(i, j, 1, 1) + w.GetRectangle(K, K, i + 1, j + 1) + b.GetRectangle(K, j, i + 1, 1) + b.GetRectangle(i, K, 1, j + 1);
			ans = max(max(tmp1,tmp2), ans);
		}
	}
	cout << ans << endl;
}

