    put(1,x,y,K,map);
    put(-1,x+K,y,K,map);
    put(-1,x,y+K,K,map);
    put(1,x+K,y+K,K,map);
}

void mark(int x, int y, int K, int (*point)[MAX_K]){
    if((x<K) == (y<K)){
        int px=x%K,py=y%K;
        putsq(px+1,py+1,K,point);
        putsq(px+1-K,py+1-K,K,point);
        putsq(px+1-K,py+1+K,K,point);
        putsq(px+1-2*K,py+1,K,point);
    }else{
        int px=x,py=y;
        if(x<K){
            px+=K; py-=K;
        }
        putsq(px+1,py+1,K,point);
        putsq(px+1-K,py+1-K,K,point);
        putsq(px+1-K,py+1+K,K,point);
        putsq(px+1+K,py+1-K,K,point);
    }
}


