int main() {
    int n,k;
    scanf("%d%d",&n,&k);
    int a[n];
    int b[n];
    int c[k*2][k*2];
    int d[k*2][k*2];
    int dp[k*2][k*2];
    int ch[n*2]={};
    int dh[n*2]={};
    int cw[n*2]={};
    int dw[n*2]={};
    rep(i,k*2){
        rep(j,k*2){
            c[i][j]=0;
            d[i][j]=0;
            dp[i][j]=0;
        }
    }
    rep(i,n){
        scanf("%d%d",a[i],b[i]);
        a[i] = a[i] % k*2;
        b[i] = b[i] % k*2;
        string s;
        cin >> s;
        if(s[0] == 'B'){
            c[a[i]][b[i]]++;
            ch[b[i]]++;
            cw[a[i]]++;
        }else{
            d[a[i]][b[i]]++;
            dh[b[i]]++;
            dw[a[i]]++;
        }
    }

    int ans = 0;
    // 初期盤面スコア(黒白白黒)
    rep(i,k*2){
        rep(j,k*2){
            if(i<k){
                if(j<k){
                    ans+=c[i][j];
                }else{
                    ans+=d[i][j];
                }
            }else{
                if(j<k){
                    ans+=d[i][j];
                }else{
                    ans+=c[i][j];
                }
            }
        }
    }

    dp[0][0]=ans;
    srep(i,1,k*2){
        dp[0][i] = dp[0][i-1] + ch[(k-1+i)%k*2] - dh[(k-1+i)%k*2] + dh[i-1] - ch[i-1];
        maxs(ans,dp[0][i]);
    }

    srep(i,1,k*2){
        rep(j,k*2){
            dp[i][j] = dp[i-1][j] + cw[(k-1+i)%k*2] - dw[(k-1+i)%k*2] + dw[i-1] - cw[i-1];
            maxs(ans,dp[i][j]);
        }
    }




    cout << ans << endl;
    return 0;
}

