typedef long long ll;

ll count_rect(const vector<vector<ll>>& cs,
              ll x1, ll y1, ll x2, ll y2){
    x1 = min(max(x1, 0LL), (ll)cs.size() - 1LL);
    x2 = min(max(x2, 0LL), (ll)cs.size() - 1LL);
    y1 = min(max(y1, 0LL), (ll)cs.front().size() - 1LL);
    y2 = min(max(y2, 0LL), (ll)cs.front().size() - 1LL);
    ll ret = cs.at(x2).at(y2) - cs.at(x1).at(y2) - cs.at(x2).at(y1)
        + cs.at(x1).at(y1);
    assert(ret >= 0);
    return ret;
}

int main(){
    ll n, k;
    cin >> n >> k;
    const ll m = 2 * k;
    vector<vector<ll>> map(m, vector<ll>(m, 0LL));
    for(int i = 0; i < n; ++i){
        ll x, y;
        char c;
        cin >> x >> y >> c;
        if(c == 'W'){
            x += k;
        }
        map.at(x % m).at(y % m)++;
    }

    vector<vector<ll>> cs(m + 1, vector<ll>(m + 1, 0LL));
    for(int i = 1; i <= m; ++i){
        for(int j = 1; j <= m; ++j){
            cs.at(i).at(j) = 
                cs.at(i).at(j - 1) + cs.at(i - 1).at(j)
                - cs.at(i - 1).at(j - 1) + map.at(i - 1).at(j - 1);
        }
    }

    ll ans = 0;
    for(ll i = 0; i < m; ++i){
        for(ll j = 0; j < m; ++j){
            ll tmp = 0;
            for(ll u = -2; u <= 2; ++u){
                for(ll v = -2; v <= 2; ++v){
                    if((u + v) % 2){ continue; }
                    tmp += count_rect(
                        cs, i + u * k, j + v * k,
                        i + u * k + k, j + v * k + k);
                }
            }
            ans = max(ans, tmp);
        }
    }
    cout << ans << endl;
    return 0;
}

