using namespace std;

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n, k;
  cin >> n >> k;

  vector<vector<int>> black(k, vector<int>(k)), white(k, vector<int>(k));
  for (int i = 0; i < n; i++) {
    int x, y, z;
    char c;
    cin >> x >> y >> c;
    z = (c == 'B' ? 0 : 1);
    x %= 2 * k;
    y %= 2 * k;
    if (x >= k && y >= k) {
      x %= k;
      y %= k;
    }
    else if (x >= k || y >= k) {
      x %= k;
      y %= k;
      z ^= 1;
    }
    if (z == 0) black.at(x).at(y)++;
    else white.at(x).at(y)++;
  }

  for (int i = 0; i < k; i++) {
    for (int j = 1; j < k; j++) {
      black.at(i).at(j) += black.at(i).at(j - 1);
      white.at(i).at(j) += white.at(i).at(j - 1);
    }
  }
  for (int j = 0; j < k; j++) {
    for (int i = 1; i < k; i++) {
      black.at(i).at(j) += black.at(i - 1).at(j);
      white.at(i).at(j) += white.at(i - 1).at(j);
    }
  }

  int ans = 0;
  for (int i = 0; i < k; i++) {
    for (int j = 0; j < k; j++) {
      int keep1 = 0, keep2 = 0;
      keep1 += black[k - 1][k - 1] - black[i][k - 1] - black[k - 1][j] + 2 * black[i][j];
      keep1 += white[k - 1][j] + white[i][k - 1] - 2 * white[i][j];
      keep2 += white[k - 1][k - 1] - white[i][k - 1] - white[k - 1][j] + 2 * white[i][j];
      keep2 += black[k - 1][j] + black[i][k - 1] - 2 * black[i][j];
      ans = max({ans, keep1, keep2});
    }
  }

  cout << ans << '\n';
}

