int get(int x, int y) {
   x = max(0, x), y = max(0, y);
   int dx = max(0, x - K), dy = max(0, y - K);
   if (x > 2*K) x = 2*K;
   if (y > 2*K) y = 2*K;
   // printf("(%d, %d), (%d, %d)\n", x, y, dx, dy);
   int ans = B[x][y] - B[dx][y] - B[x][dy] + B[dx][dy];
   return ans;
}

