int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> K;

    for (int i = 1; i <= N; i++) {
        ll x, y;
        char c;
        cin >> x >> y >> c;
        if (c == 'W') {
            mod[x % (2 * K) + 1][(y + K) % (2 * K) + 1]++;
        } else {
            mod[x % (2 * K) + 1][y % (2 * K) + 1]++;
        }
    }

    for (int i = 0; i < 4 * K; i++) {
        for (int j = 0; j < 4 * K; j++) {
            mod[i + 1][j + 1] = mod[i % (2 * K) + 1][j % (2 * K) + 1];
        }
    }

    for (int i = 1; i <= 4 * K; i++) {
        for (int j = 1; j <= 4 * K; j++) {
            sum[i][j] = sum[i - 1][j] + sum[i][j - 1] - sum[i - 1][j - 1] + mod[i][j];
        }
    }

    ll ans = 0;
    for (int i = 1; i <= 2 * K; i++) {
        for (int j = 1; j <= 2 * K; j++) {
            ll res = 0;
            res += sum[i + 2 * K - 1][j + 2 * K - 1] - sum[i + K - 1][j + 2 * K - 1] - sum[i + 2 * K - 1][j + K - 1] + sum[i + K - 1][j + K - 1];
            res += sum[i + K - 1][j + K - 1] - sum[i + K - 1][j - 1] - sum[i - 1][j + K - 1] + sum[i - 1][j - 1];
            ans = max(res, ans);
        }
    }

