        rep(j,2*k){
            if(i==0&&j==0){
                continue;
            }else if(i==0){
                d[i][j]+=d[i][j-1];
            }else if(j==0){
                d[i][j]+=d[i-1][j];
            }else{
                d[i][j]+=d[i][j-1]+d[i-1][j]-d[i-1][j-1];
            }
        }
    }

    rep(y,k){
        rep(x,k){
            int can = 0;
            if(y==0&&x==0){
                can += d[y+k-1][x+k-1];
            }else if(y==0){
                can += d[y+k-1][x+k-1]-d[y+k-1][x-1];
            }else if(x==0){
                can += d[y+k-1][x+k-1]-d[y-1][x+k-1];
