            }
            can += d[2*k-1][2*k-1]-d[2*k-1][x+k-1]-d[y+k-1][2*k-1]+d[y+k-1][x+k-1];
            ans = max(ans,max(can,n-can));

        }
    }


    cout << ans<<endl;

    return 0;
}

