using namespace std;
int n, k;
int x[100100], y[100100];
char c[100100];
int xt, yt;
int point[2010][2010] = {};
int Sum[2010][2010];
int d[2010] = {};
int e[2010] = {};
int all = 0;
int Point = 0;
int Max = 0;
int Min = 0;

int main()
{
    cin >> n >> k;
    for(int i = 0; i < n; i++)
    {
        cin >> xt >> yt >> c[i];
        x[i] = xt % (2*k);
        if(c[i] == 'B')
        {
            y[i] = yt % (2*k);
        }
        else
        {
            y[i] = (yt + k) % (2*k);
        }
        point[x[i]][y[i]] = point[x[i]][y[i]] + 1;
    }
//    2k × 2kのマス目に数字がかかれていて、市松にしてポイントを最大化したい

    for(int i = 0; i < 2*k; i++)
    {
        for(int j = 0; j < 2*k; j++)
        {
            d[i] = d[i] + point[i][j];
            e[i] = e[i] + point[j][i];
        }
        all = all + d[i];
    }


    for(int i = 0; i < k; i++)
    {
        for(int j = 0; j < k; j++)
        {
            Point = Point + point[i][j] + point[i+k][j+k];
        }
    }

    for(int i = 0; i < k; i++)
    {
        if(i == 0)
        {
            Sum[0][0] = Point;
        }
        else
        {
            Sum[0][i] = Sum[0][i-1] - e[i+k-1] + e[i-1];
            for(int b = 0; b < k; b++)
            {
                Sum[0][i] = Sum[0][i] + 2*point[b][i+k-1] - 2*point[b][i-1];
            }
        }
        for(int j = 1; j < k; j++)
        {
            Sum[j][i] = Sum[j-1][i] - d[j+k-1] + d[j-1];
            for(int a = 0; a < k; a++)
            {
                Sum[j][i] = Sum[j][i] + 2*point[j+k-1][i+a] - 2*point[j-1][i+a];
            }
        }
    }


    for(int i = 0; i < k; i++)
    {
        for(int j = 0; j < k; j++)
        {
            Max = max(Max, Sum[i][j]);
            Min = min(Min, Sum[i][j]);
        }
    }

    cout << max(Max, all - Min) << endl;

}

