long count_w( long i0, long j0, long i1, long j1 )
{
    return sw[i1][j1] + sw[i0][j0] - sw[i1][j0] - sw[i0][j1];
}
long count_b( long i0, long j0, long i1, long j1 )
{
    return sb[i1][j1] + sb[i0][j0] - sb[i1][j0] - sb[i0][j1];
}

int main(int argc, char* argv[])
{
    long n,k;
    scanf("%ld%ld", &n, &k);

    long i,j;
    for(i=0; i<n; i++) {
        long x, y;
        char str[5]={0};
        scanf("%ld%ld%s", &x, &y, str);

        if(str[0]=='B') {
            if((x/k+y/k)%2==0) bb[x%k][y%k]++;
            else               ww[x%k][y%k]++;
        }
        else {
            if((x/k+y/k)%2==0) ww[x%k][y%k]++;
            else               bb[x%k][y%k]++;
        }
    }

    for(i=0; i<=k; i++) {
        sb[0][i]=sw[0][i]=0;
        sb[i][0]=sw[i][0]=0;
    }
    for(i=0; i<k; i++) {
        for(j=0; j<k; j++) {
            sb[i+1][j+1]=sb[i+1][j]+bb[i][j];
            sw[i+1][j+1]=sw[i+1][j]+ww[i][j];
        }
    }
    for(i=0; i<k; i++) {
        for(j=0; j<k; j++) {
            sb[i+1][j+1]+=sb[i][j+1];
            sw[i+1][j+1]+=sw[i][j+1];
        }
    }

    long max=0;
    for(i=0; i<k; i++) {
        for(j=0; j<k; j++) {
            long val = count_w(0,0,i,j) + count_w(i,j,k,k) + count_b(0,j,i,k) + count_b(i,0,k,j);
            if(max <val) {
                max = val;
            }

            val = count_b(0,0,i,j) + count_b(i,j,k,k) + count_w(0,j,i,k) + count_w(i,0,k,j);
            if(max <val) {
                max = val;
            }
        }
    }

    printf("%ld\n", max);

    return 0;
}

