    ll res=blacks[a+k][b+k]-blacks[a+k][b]-blacks[a][b+k]+blacks[a][b];
    return res;
  };


  ll ans=0;
  REP(i,2*k){
    REP(j,2*k)
      ans=max(ans,calcPoint(i,j)+calcPoint(i+k,j+k));
  }

  cout<<ans<<endl;

}

