/*
 * 解説に乗っ取ってやる
 * 計算量を落とす方法が多分imos法
 *		4K * 4Kに範囲を拡張して、
 *		i番目の条件を満たせるような左下マスの集合のうち、K*Kの正方形の区間になるものだけを貼って、+1する方針
 */



// 各条件について、条件を満たす左下マスの集合のうちK*Kの正方形になる区間を探す
int hidarisita(std::vector<std::vector<int>> v, int K){
	// i番目の要求が成立するような領域の左下を出す
	std::vector<std::vector<int>> xy;
	// 初期化
	xy.resize(4 * K);
	for (size_t i = 0; i < xy.size(); i++) {
		for (size_t j = 0; j < 4 * K; j++) {
			xy[i].push_back(0);
		}
	}

	// 重みの加算
	for (size_t i = 0; i < v.size(); i++) {
		// 全ての左下を求める
		for (size_t j = 0; j < 4 * K; j+=K) {
			for (size_t k = 0; k < 4 * K; k+=K) {
				int xx = v[i][0] % K + j + 1;
				int yy = v[i][1] % K + k + 1;
				if ((xx + yy) % (2 * K) == (v[i][0] + 1 + v[i][1] + 1) % (2 * K)) {
					// K * Kになるものだけを重みに加算する
					if (xx + K < 4 * K && yy + K < 4 * K) {
						xy[xx][yy]++;
						xy[xx][yy+K]--;
						xy[xx+K][yy]--;
						xy[xx+K][yy+K]++;
					}
				}
			}
		}
	}

	// 横方向への累積和
	for (size_t i = 0; i < xy.size(); i++) {
		for (size_t j = 1; j < xy[i].size(); j++) {
			xy[i][j] += xy[i][j-1];
		}
	}
	// 縦方向への累積和
	for (size_t i = 1; i < xy.size(); i++) {
		for (size_t j = 0; j < xy[i].size(); j++) {
			xy[i][j] += xy[i-1][j];
		}
	}

	// 最大値を調べる
	int banmax = -2000;
	for (size_t i = 0; i < xy.size(); i++) {
		for (size_t j = 0; j < xy[i].size(); j++) {
			banmax = max(banmax,xy[i][j]);
		}
	}

	return banmax;
}


int main(int argc, char const *argv[]) {
	int N,K;
	std::cin >> N >> K;
	std::vector<std::vector<int>> v;
	v.resize(N);
	for (size_t i = 0; i < N; i++) {
		int a,b;
		char c;
		std::cin >> a >> b >> c;
		v[i].push_back(a);
		v[i].push_back(b);
		if (c == 'B') {
			v[i].push_back(0);
		}
		else {
			v[i].push_back(1);
		}
	}

	// 入力条件を整える
	for (size_t i = 0; i < v.size(); i++) {
		// W を B に変換
		if (v[i][2] == 1) {
			v[i][2] = 0;
			v[i][1] += K;
		}
		// mod 2Kをとる
		v[i][0] %= (2*K);
		v[i][1] %= (2*K);
	}

	std::cout << hidarisita(v,K) << '\n';

	return 0;
}

