        data = vector<vector<T>>(H + 1, vector<T>(W + 1, T{}));
    }

    //0-index
    //original y
    //original x
    void add(T y, T x, T d) {
        y++;
        x++;
        if (y >= H + 1 || x >= W + 1) return;
        data[y][x] += d;
    }

    void build() {
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                data[i + 1][j + 1] += data[i + 1][j] + data[i][j + 1] - data[i][j];
