    REP(i, n) {
        cin >> x >> y >> c;
        if (c == 'W') {
            y += k;
        }
        y %= 2 * k;
        if (y >= k) {
            y -= k;
            x += k;
        }
        x %= 2 * k;
        s.add(x, y, 1);
        s.add((x + k) % (2 * k), y + k, 1);
    }
    // 二次元累積和
    s.build();
    // s.print();
    int maxv = 0;
    REP(x, k) {
        REP(y, k) {
            int t = s.query(x, y, x + k, y + k);
            maxv = max({maxv, t, n - t});
        }
    }
    cout << maxv << endl;
    return 0;
}

