ll nor(ll n) {
	return max(min(n, 2*K), 0LL);
}

void dplus(ll x, ll y) {
	ll le = nor(x), ri = nor(x+K), dw = nor(y), up = nor(y+K);
	d[le][dw]++;
	d[ri][dw]--;
	d[le][up]--;
	d[ri][up]++;
}

