int arr[N], tree[N*4];
void build(int node, int b, int e){
    if(b == e){
        tree[node] = arr[b];
        return;
    }
    int lft = node*2, rght = lft+1;
    int mid = (b+e)/2;
    build(lft, b, mid);
    build(rght, mid+1, e);
    tree[node] = __gcd(tree[lft], tree[rght]);
}
void update(int node, int b, int e, int pos){
    if(b == e){
        tree[node] = arr[b];
        return;
    }
    int lft = node*2, rght = lft+1;
    int mid = (b+e)/2;
    if(pos <= mid)
        update(lft, b, mid, pos);
    else
        update(rght, mid+1, e, pos);
    tree[node] = __gcd(tree[lft], tree[rght]);
}
int query(int node, int b, int e, int i, int j, int x){
    if(b > j || e < i)
        return inf;
    if(b >= i && e <= j){
        if(tree[node] % x == 0)
            return inf;
        else if(b == e)
            return b;
       // debug(b,e);
    }
    int lft = node*2, rght = lft+1;
    int mid = (b+e)/2;
    int p1 = query(lft, b, mid, i, j, x);
    if(p1 != inf)
        return p1;
    int p2 = query(rght, mid+1, e, i, j, x);
    return p2;
}
