            y[i] = y[i]%(2*k);
            a[y[i]][x[i]]++;
        }
    }
    REP(i,2*k){
        REP(j,2*k){
            s[i+1][j+1] = s[i+1][j]+s[i][j+1]-s[i][j]+a[i][j];
        }
    }
    int res=0;
    REP(i,k){
        REP(j,k){
            res = max(res,check(i,j));
            res = max(res,n-check(i,j));
        }
    }
    put(res);
    return 0;
}

