int tiles[2001][2001];
void vote(int x, int y, int x2, int y2) {
  tiles[x][y]++;
  tiles[x2][y]--;
  tiles[x][y2]--;
  tiles[x2][y2]++;
}

int main() {
  int n, k; cin >> n >> k;
  int x, y; char c;
  REP(i,n) {
    cin >> x >> y >> c;
    if (c == 'W') y += k;
    x %= 2*k; y %= 2*k;

    if ((x < k && y < k) || (x >= k && y >= k)) {
      x %= k; y %= k;
      vote(0, 0, x+1, y+1);
      vote(x+k+1, 0, 2*k, y+1);
      vote(0, y+k+1, x+1, 2*k);
      vote(x+k+1, y+k+1, 2*k, 2*k);
      vote(x+1, y+1, x+k+1, y+k+1);
    } else {
      x %= k; y %= k;
      vote(x+1, 0, x+k+1, y+1);
      vote(0, y+1, x+1, y+k+1);
      vote(x+1, y+k+1, x+k+1, 2*k);
      vote(x+k+1, y+1, 2*k, y+k+1);
      }
    }

    FOR(i,0,2*k+1) FOR(j,1,2*k+1) tiles[i][j] += tiles[i][j-1];
    FOR(i,1,2*k+1) FOR(j,0,2*k+1) tiles[i][j] += tiles[i-1][j];
  int ans = 0;
