typedef struct col{
	col(LL x, LL y, char c) : x(x), y(y), c(c) {};
	col() : x(0), y(0), c(0) {};
	LL x,y;
	char c;
} col;

int main(int argc, char const* argv[])
{
	int n,k;
	cin >> n>> k;
	vector<col> d(n);
	auto change_c = [](char c){if (c == 'W') return 'B'; else return 'W';};
	for (int i = 0; i < n; i++) {
		LL x,y;
		char c;
		cin >> x >> y >> c;
		x %= 2*k;
		y %= 2*k;
		x++;y++;
		if (x-k > 0) {
			x -= k;
			c = change_c(c);
		}
		if (y-k > 0) {
			y -= k;
			c = change_c(c);
		}
		d[i] = col(x,y,c);
	}
	VVL b(k+1, VL(k+1,0));
	VVL w(k+1, VL(k+1,0));
	for (int i = 0; i < n; i++) {
		if (d[i].c == 'W') {
			w[d[i].y][d[i].x] += 1;
		} else {
			b[d[i].y][d[i].x] += 1;
		}
	}
	for (int i = 0; i < k+1; i++) {
		for (int j = 0; j < k; j++) {
			w[i][j+1] += w[i][j];
			b[i][j+1] += b[i][j];
		}
	}
	for (int i = 0; i < k; i++) {
		for (int j = 0; j < k+1; j++) {
			w[i+1][j] += w[i][j];
			b[i+1][j] += b[i][j];
		}
	}
	LL ans = 0;
	for (int i = 0; i <= k; i++) {
		for (int j = 0; j <= k; j++) {
			// (j,i)は黒の右下とする
			LL tmp = 0;
			tmp += b[k][k] - b[i][k] - b[k][j] + 2*b[i][j];
			tmp += w[i][k] + w[k][j] - 2*w[i][j];
			ans = max(ans, tmp);
		}
	}
	cout << ans << endl;
	return 0;
}

