/*
the operators regarding bit

     x1: 0000 0001 0010 0101 0110 0111
     x2: xxxx 0001 0011 0100 0101 1000
x1 & x2: 0000 0001 0010 0100 0100 0000

      x: 1001 1010  1100 1011 1101  1111
x & - x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

x << y is x * 2 ** y
x >> y is rep(i, y) x = x // 2 
*/

const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, k, x, y;
char c;
ll cnt[2][2004][2004]; // 0 is white, 1 is black
ll sq[2][2004][2004];

ll calc_sum(ll x, ll y){
    ll val_black = sq[1][x][y];
    ll val_white = sq[0][2 * k][2 * k] - sq[0][x][y];
    if (x > k && y > k){
        val_black += sq[1][x - k][y - k];
        val_white -= sq[0][x - k][y - k];
    }else if (x > k){
        val_black += sq[1][x - k][y + k];
        val_white -= sq[0][x - k][y + k];
    }else if (y > k){
        val_black += sq[1][x + k][y - k];
        val_white -= sq[0][x + k][y - k];
    }else {
        val_black += sq[1][x + k][y + k];
        val_white -= sq[0][x + k][y + k];
    }

    return val_black + val_white;
}

void solve(){
    rep(i, 2) rep(x, 2 * k + 1) rep(y, 2 * k + 1) cnt[i][x][y] = 0; 
    rep(i, n){
        in3(x, y, c);
        if (c == 'W') cnt[0][x % (2 * k)][y % (2 * k)]++;
        else cnt[1][x % (2 * k) + 1][y % (2 * k) + 1]++;
    }

    rep(x, 2 * k) rep(y, 2 * k + 1){
        cnt[0][x + 1][y] += cnt[0][x][y];
        cnt[1][x + 1][y] += cnt[1][x][y];
    }

    rep(x, 2 * k + 1) rep(y, 2 * k){
        cnt[0][x][y + 1] += cnt[0][x][y];
        cnt[1][x][y + 1] += cnt[1][x][y];
    }

    For(x, 1, 2 * k + 1) For(y, 1, 2 * k + 1){
        if (x <= k && y <= k){
            sq[0][x][y] = cnt[0][x + k][y + k] - cnt[0][x + k][y - 1] - cnt[0][x - 1][y + k] + cnt[0][x - 1][y - 1];
            sq[1][x][y] = cnt[1][x + k][y + k] - cnt[1][x + k][y - 1] - cnt[1][x - 1][y + k] + cnt[1][x - 1][y - 1];
        }else if (x <= k){
            ll u1, u2; ll b1, b2;
            u1 = cnt[0][x + k][2 * k] - cnt[0][x + k][y - 1] - cnt[0][x - 1][2 * k] + cnt[0][x - 1][y - 1];
            u2 = cnt[1][x + k][2 * k] - cnt[1][x + k][y - 1] - cnt[1][x - 1][2 * k] + cnt[1][x - 1][y - 1];
            b1 = cnt[0][x + k][y - k] - cnt[0][x + k][0] - cnt[0][x - 1][y - k] + cnt[0][x - 1][0];
            b2 = cnt[1][x + k][y - k] - cnt[1][x + k][0] - cnt[1][x - 1][y - k] + cnt[1][x - 1][0];
            sq[0][x][y] = u1 + b1;
            sq[1][x][y] = u2 + b2;
        }else if (y <= k){
            ll u1, u2; ll b1, b2;
            u1 = cnt[0][2 * k][y + k] - cnt[0][2 * k][y - 1] - cnt[0][x - 1][y + k] + cnt[0][x - 1][y - 1];
            u2 = cnt[1][2 * k][y + k] - cnt[1][2 * k][y - 1] - cnt[1][x - 1][y + k] + cnt[1][x - 1][y - 1];
            b1 = cnt[0][x - k][y + k] - cnt[0][0][y + k] - cnt[0][x - k][y - 1] + cnt[0][0][y - 1];
            b2 = cnt[1][x - k][y + k] - cnt[1][0][y + k] - cnt[1][x - k][y - 1] + cnt[1][0][y - 1];
            sq[0][x][y] = u1 + b1;
            sq[1][x][y] = u2 + b2;
        }else{
            ll u1, u2; ll b1, b2; ll r1, r2; ll l1, l2;
            u1 = cnt[0][2 * k][2 * k] - cnt[0][2 * k][y - 1] - cnt[0][x - 1][2 * k] + cnt[0][x - 1][y - 1];
            u2 = cnt[1][2 * k][2 * k] - cnt[1][2 * k][y - 1] - cnt[1][x - 1][2 * k] + cnt[1][x - 1][y - 1];
            b1 = cnt[0][2 * k][y - k] - cnt[0][2 * k][0] - cnt[0][x - 1][y - k] + cnt[0][x - 1][0];
            b2 = cnt[1][2 * k][y - k] - cnt[1][2 * k][0] - cnt[1][x - 1][y - k] + cnt[1][x - 1][0];
            r1 = cnt[0][x - k][2 * k] - cnt[0][0][2 * k] - cnt[0][x - k][y - 1] + cnt[0][0][y - 1];
            r2 = cnt[1][x - k][2 * k] - cnt[1][0][2 * k] - cnt[1][x - k][y - 1] + cnt[1][0][y - 1];
            l1 = cnt[0][x - k][y - k] - cnt[0][x - k][0] - cnt[0][0][y - k] + cnt[0][0][0];
            l2 = cnt[1][x - k][y - k] - cnt[1][x - k][0] - cnt[1][0][y - k] + cnt[1][0][0];
            sq[0][x][y] = u1 + b1 + l1 + r1;
            sq[1][x][y] = u2 + b2 + l2 + r2;
        }
    }

    rep(x, 2 * k) rep(y, 2 * k) answer = max(answer, calc_sum(x, y));

    prl(answer);
}

int main(void){
    in2(n, k);
    // assert(n <= 999);
    solve();

    return 0;
}

