      bgrid[i][j] += bgrid[i-1][j];
      wgrid[i][j] += wgrid[i-1][j];
      bgrid[i][j] += bgrid[i][j-1];
      wgrid[i][j] += wgrid[i][j-1];
      bgrid[i][j] -= bgrid[i-1][j-1];
      wgrid[i][j] -= wgrid[i-1][j-1];
    }
  }
  auto area_sum = [&](int x, int y, bool black) {
    auto grid = black ? bgrid : wgrid;
    auto bx = x-k;
    auto by = y-k;
    x = min(x, 3*k-1);
    y = min(y, 3*k-1);
    int res = grid[x][y];
    if (bx>=0)
      res -= grid[bx][y];
    if (by>=0)
      res -= grid[x][by];
    if (bx>=0 and by>=0)
      res += grid[bx][by];
    return res;
