			x -= (x < 0) * (m - 1); y -= (y < 0) * (m - 1);
			if (abs((x / m) % 2) == abs((y / m) % 2)) {
				sum += (i == 0 ? 'B' : 'W') == want[l].color;
			} else {
				sum += (i == 1 ? 'B' : 'W') == want[l].color;
			}
		}
		ans = max(ans, sum);
	}
	cout << ans << endl;
	return 0;
}

