		cin >> X[i] >> Y[i] >> C[i];
	}
	for (int i = 0; i < N; i++) {
		if (C[i] == "W"){
			X[i] = X[i] + K;
		}
		X[i] = X[i] % (K * 2);
		Y[i] = Y[i] % (K * 2);

	}

	int top = 0;
	int bottom = 2 * K;
	int left = 2 * K;
	int right = 0;

	for (int i = 0; i < N; i++) {
		if (X[i] < left) {
			left = X[i];
		}
		if (Y[i] < bottom) {
			bottom = Y[i];
		}
	}
	for (int i = 0; i < N; i++) {

		X[i] = X[i] - left;
		Y[i] = Y[i] - bottom;

	}
	int maxpossibility = 0;
	for (int i = 0; i < K; i++) {
		for (int j = 0; j < K; j++) {
			for (int k = 0; k < N; k++) {
				if (X[k] > i && Y[k] > j) {
					X[k] = X[k] - K;
					Y[k] = Y[k] - K;
				}

			}
			for (int k = 0;k < N; k++) {
				if (X[k] < left) {
					left = X[k];
				}
				if (Y[k] < bottom) {
					bottom = Y[k];
				}
			}
			int impossible = 0;
			for (int k = 0; k < N; k++) {
				if ((X[k] - left >= K && Y[k] - bottom < K)
					|| (X[k] - left < K && Y[k] - bottom >= K)) {
					impossible++;
				}
			}
			int possibility = N - impossible;
			if (maxpossibility < possibility) {
				maxpossibility = possibility;
			}
		}
	}





	delete[] X;
	delete[] Y;
	delete[] C;
	cout << maxpossibility << endl;
	return 0;
}

