int main() {
  int n, k;
  vector<int> x, y;
  vector<string> c;
  cin >> n >> k;
  x.resize(n);
  y.resize(n);
  c.resize(n);
  for (int i = 0; i < n; ++i) {
    cin >> x[i] >> y[i] >> c[i];
  }

  // pre-aggregate with (2 * K) square
  const int grid = k * 2;
  vector<vector<int>> agg;
  for (int i = 0; i < grid; ++i) {
    vector<int> row;
    row.resize(grid);
    agg.emplace_back(std::move(row));
  }
  for (int i = 0; i < n; ++i) {
    if (c[i] == "W") {
      ++agg[y[i] % grid][x[i] % grid];
    } else {
      --agg[y[i] % grid][x[i] % grid];
    }
  }

  int max = 0;
  for (int i = 0; i < grid; ++i) {
    for (int j = 0; j < grid; ++j) {
      int score = 0;
      for (int dx = 0; dx < grid; ++dx) {
        for (int dy = 0; dy < grid; ++dy) {
          int posx = (dx + i) % grid;
          int posy = (dy + j) % grid;
          int color;
          if ((posx < k && posy < k) || (k <= posx && k <= posy)) {
            color = 1;
          } else {
            color = -1;
          }
          score += agg[dy][dx] * color;
        }
      }
      if (max < score) {
        max = score;
      }
    }
  }
  cout << max << "\n";
}

