inline unsigned count(
  const std::vector< std::vector<unsigned> > &sum,
  unsigned left, unsigned right, unsigned top, unsigned bottom 
)
{
  return sum[bottom][right]
       + sum[top][left]
       - sum[bottom][left]
       - sum[top][right];
}

int main(int argc, char **argv)
{
  unsigned N, K;
  std::cin >> N >> K;

  unsigned M = 2 * K;

  std::vector< std::vector<bool> > table(2 * K);
  for (unsigned m = 0; m < M; ++m) {
    table[m] = std::vector<bool>(2 * K, 0);
  }

  for (unsigned n = 0; n < N; ++n) {
    unsigned x, y;
    char color;
    std::cin >> x >> y >> color;

    if (color == 'B') {
      table[(y + 0) % M][x % M] = true;
    } else {
      table[(y + K) % M][x % M] = true;
    }
  }

  std::vector< std::vector<unsigned> > sum(M + 1);
  for (unsigned m = 0; m < M + 1; ++m) {
    sum[m] = std::vector<unsigned>(M + 1, 0);
  }

  for (unsigned y = 0; y < M; ++y) {
    for (unsigned x = 0; x < M; ++x) {
      sum[y + 1][x + 1] = (table[y][x] ? 1 : 0) 
                        + sum[y + 1][x] 
                        + sum[y][x + 1] 
                        - sum[y][x];
    }
  }

  unsigned max = 0;

  for (unsigned py = 0; py < K; ++py) {
    for (unsigned px = 0; px < K; ++px) {
      unsigned S = 0;

      S += count(sum, 0, px, py, py + K);
      S += count(sum, px, px + K, 0, py);
      S += count(sum, px, px + K, py + K, M - 1);
      S += count(sum, px + K, M - 1, py, py + K);

      max = std::max(max, N - S);
    }
  }

  std::cout << max << std::endl;

  return 0;
}

