int grid[2000][2000];
int n, k;

void init(int x, int y) {
  if (x < 0 || x >= 2*k) return;
  if (y < 0 || y >= 2*k) return;
  // 二次元累積和の前処理. 
  int lx = max(0, x-k+1);
  int uy = max(0, y-k+1);
  int rx = min(x+1, k);
  int dy = min(y+1, k);
  // cout << x << " " << y << " " << lx << " " << uy << " " << rx << " " << dy << endl;
  grid[uy][lx] += 1;
  grid[dy][rx] += 1;
  grid[dy][lx] -= 1;
  grid[uy][rx] -= 1;
}

int main() {
  cin >> n >> k;
  for (int i = 0; i < n; ++i) {
    int x, y;
    char c;
    cin >> x >> y >> c;
    if (c == 'W') x += k;
    x %= 2*k;
    y %= 2*k;
    init(x, y);
    init(x-k, y-k);
    init(x-k, y+k);
    init(x+k, y-k);
    init(x+k, y+k);
  }

  for (int y = 0; y < k; ++y) {
    for (int x = 1; x < k; ++x) {
      grid[y][x] += grid[y][x-1];
    }
  }
  for (int x = 0; x < k; ++x) {
    for (int y = 1; y < k; ++y) {
      grid[y][x] += grid[y-1][x];
    }
  }
  // for (int y = 0; y < k; ++y) {
