                ans = tmp;
                //cerr << "black:" << i << " " << j << endl;
            }
        }
    }

    ans = max(ans, white_imos[k - 1][k - 1]);


    if(false){

        int tmp = min(10,k + 1);

        rep(i, tmp){
            rep(j, tmp){
                cerr << white_imos[i][j] << " ";
            }
            cerr << endl;
        }

        cerr << endl;

        rep(i, tmp){
            rep(j,tmp){
                cerr << black_imos[i][j] << " ";
            }
            cerr << endl;
        }
    }

    cout << ans << endl;


    return 0; 
}

