int main()
{
	cin >> n >> k;
	ll X, Y;
	char C;
	ll sum = 0;
	ll white = 0;
	rep(i, 0, n) {
		cin >> X >> Y >> C;
		X = X % (2 * k);
		Y = Y % (2 * k);

		if (C == 'B') {
			s[X + 1][Y + 1]++; sum++;
		}
		else if (C == 'W') {
			s[X + 1][Y + 1]--; sum--; white++;
		}
	}

	repe(i, 1, 2 * k) repe(j, 1, 2 * k) s[i][j] += s[i][j - 1];
	repe(j, 1, 2 * k) repe(i, 1, 2 * k) s[i][j] += s[i - 1][j];

	ll maxV = -(1 << 25);
	rep(i, 0, k) {
		rep(j, 0, k) {
			ll a = s[i][j];
			ll b = s[i + k][j + k] - s[i + k][j] - s[i][j + k] + a;
			ll c = s[2 * k][j] - s[i + k][j];
			ll d = s[i][2 * k] - s[i][j + k];
			ll e = s[2 * k][2 * k] - s[2 * k][j + k] - s[i + k][2 * k] + s[i + k][j + k];
			ll tmp = a + b + c + d + e;
			maxV = max(maxV, max(tmp, sum - tmp));
		}
	}
	maxV += white;

	cout << maxV << endl;

	return 0;
}

#include <cstdio>
#include <cmath>
#include <cstdlib>
#include <iostream>
using namespace std;

int judge(int a, int b, int x, int y, int k){
  int dx = (2 * k + x - a) % (2 * k);
  int dy = (2 * k + y - b) % (2 * k);
  if (dx>=0 && dx<k && dy>=k && dy<(2*k)) return 1;
  if (dy>=0 && dy<k && dx>=k && dx<(2*k)) return 1;
  return 0;
}

int main(){
  int n, k;
  cin >> n >> k;

  int x[1000]; int y[1000];

  for (int i = 0; i < n; i++){
    char s[1];
    scanf("%d %d %c", &x[i], &y[i], s);
     x[i] = x[i] % (2*k);
     y[i] = y[i] % (2*k);
    if ((s[0] - 'B') != 0){
      y[i] = (y[i] + k) % (2*k);
    }
  }

  int ans = 0;

  for (int i = 0; i < 2 * k; i++){
    for (int j = 0; j < 2 * k; j++){
      int sum = 0;
      for (int u = 0; u < n; u++){
        sum += judge(i, j, x[u], y[u], k);
      }
      ans = max(ans, sum);
    }
  }

  printf("%d\n", ans);

  return 0;
}

