int main() {

  int N, K;
  cin >> N >> K;

  vector<int> x(N);
  vector<int> y(N);
  vector<char> c(N);

  // 黒か否か
  vector<bool> black(N);

  // 2 * K
  int KK = 2 * K;

  // 二次元累積和
  vector<vector<int>> table(KK + 1, vector<int>(KK + 1));

  for (int i = 0; i < N; i++) {
    cin >> x[i] >> y[i] >> c[i];

    // x を x % 2K、y を y % 2K に置き換える
    x[i] %= KK;
    y[i] %= KK;

    if (c[i] == 'B') {
      black[i] = true;
    } else {
      black[i] = false;
    }

    // 0 から K の間に (x, y) を集約させる
    if (K <= x[i]) {
      x[i] -= K;
      black[i] = !black[i];
    }
    if (K <= y[i]) {
      y[i] -= K;
      black[i] = !black[i];
    }

    // 二次元累積和の準備
    // K * k の左下を調査点とする
    if (black[i]) {
      table[0][0]++;
      table[0][y[i] + 1]--;
      table[x[i] + 1][0]--;
      table[x[i] + 1][y[i] + 1] += 2;
    } else {
      table[0][y[i] + 1]++;
      table[x[i] + 1][0]++;
      table[x[i] + 1][y[i] + 1] -= 2;
    }

  }

  // 二次元累積和（横の集計）
  for (int i = 0; i < K; i++) {
    for (int j = 1; j < K; j++) {
      table[i][j] += table[i][j - 1];
    }
  }

  // 二次元累積和（縦の集計）
  for (int i = 0; i < K; i++) {
    for (int j = 1; j < K; j++) {
      table[j][i] += table[j - 1][i];
    }
  }


  int answer = 0;

  // 答えを探す
  for (int i = 0; i < K; i++) {
    for (int j = 0; j < K; j++) {
      // 正しいマスの個数は、W が多い場合もある
      table[i][j] = max(table[i][j], N - table[i][j]);
      answer = max(answer, table[i][j]);
    }
  }

  cout << answer << endl;

  return 0;

}

