    int total_count = 0;
    int max_count = 0;
    for (int i = 0; i < 2*K; i++) {
        for (int j = 0; j < 2*K; j++) {
            zero.x = i;
            zero.y = j;
            zero.t = 1;

            total_count = 0;
            for (int k = 0; k < N; k++) {
                delay_x = input.at(k).x - zero.x;
