int k;
int sums[2000][2000][2] = {};

int getnum(int x1, int y1, int x2, int y2, int c) {
	int result = sums[x2][y2][c];
	if (x1 > 0) result -= sums[x1 - 1][y2][c];
	if (y1 > 0) result -= sums[x2][y1 - 1][c];
	if (x1 > 0 && y1 > 0) result += sums[x1 - 1][y1 - 1][c];
	return result;
}

int solve(int i, int j, int c) {
	int result = getnum(i, j, i + k - 1, j + k - 1, c);
	if (i > 0 && j > 0) result += getnum(0, 0, i - 1, j - 1, c);
	if (i > 0 && j < k - 1) result += getnum(0, j + k, i - 1, 2 * k - 1, c);
	if (i < k - 1 && j > 0) result += getnum(i + k, 0, 2 * k - 1, j - 1, c);
	if (i < k - 1 && j < k - 1)
		result += getnum(i + k, j + k, 2 * k - 1, 2 * k - 1, c);
	// cout << "\t" << result << endl;
	if (i > 0) result += getnum(0, j, i - 1, j + k - 1, !c);
	if (j < 0) result += getnum(i, 0, i + k - 1, j - 1, !c);
	if (i < k - 1) result += getnum(i + k, j, 2 * k - 1, j + k - 1, !c);
	if (j < k - 1) result += getnum(i, j + k, i + k - 1, 2 * k - 1, !c);
	// cout << "\t" << result << endl;
	return result;
}

