  for(i=1;i<=2*K;i++)
  {
    for(j=1;j<=2*K;j++)
    {
      map[i][j] += map[i][j-1] + map[i-1][j] - map[i-1][j-1];
    }
  }

  /*printf("after\n");
  for(i=0;i<=2*K;i++)
  {
    for(j=0;j<=2*K;j++)
    {
      printf("%d ",map[i][j]);
