			int x = a + D[i];
			int y = b + oD[i];
			B[x][y]++;
			B[x][y + K]--;
			B[x + K][y]--;
			B[x + K][y + K]++;
		}
	}
	for (int i = 0; i < K * 4; i++) {
		for (int j = 0; j < K * 4; j++) {
			B[i + 1][j] += B[i][j];
		}
	}

	for (int i = 0; i < K * 4; i++) {
		for (int j = 0; j < K * 4; j++) {
			B[i][j + 1] += B[i][j];
		}
	}
	for (int i = 1; i < K * 4; i++) {
		for (int j = 1; j < K * 4; j++) {
			ans = std::max(ans, B[i][j]);
		}
	}
	std::cout << ans << std::endl;
	return 0;
}

