int main() {
    int N, K;
    cin >> N >> K;
    vint R(N), C(N);
    vector<char> T(N);
    v2int field_black(2 * K, vint(2 * K, 0));
    v2int field_white(2 * K, vint(2 * K, 0));
    ll white_num = 0;
    rep(i, N) {
        cin >> C[i] >> R[i] >> T[i];

        int c = (C[i]) % (2 * K);
        int r = (R[i]) % (2 * K);

        if (T[i] == 'W') {
            field_white[r][c]++;
            white_num++;
        }
        else {
            field_black[r][c]++;
        }
    }
    v2ll Sb(2 * K + 1, vll(2 * K + 1, 0));
    v2ll Sw(2 * K + 1, vll(2 * K + 1, 0));

    REP(i, 1, 2 * K + 1) {
        REP(j, 1, 2 * K + 1) {
            Sb[i][j] = Sb[i - 1][j] + Sb[i][j - 1] - Sb[i - 1][j - 1] + field_black[i - 1][j - 1];
            Sw[i][j] = Sw[i - 1][j] + Sw[i][j - 1] - Sw[i - 1][j - 1] + field_white[i - 1][j - 1];
        }
    }

    ll count_b, count_w;
    ll max_score = 0;
    REP(i, 1, K + 1) {
        REP(j, 1, K + 1) {
            int Sr1 = i;
            int Sc1 = j;
            int Er1 = i + K - 1;
            int Ec1 = j + K - 1;
            count_b = Sb[Er1][Ec1] - Sb[Sr1 - 1][Ec1] - Sb[Er1][Sc1 - 1] + Sb[Sr1 - 1][Sc1 - 1];
            count_w = Sw[Er1][Ec1] - Sw[Sr1 - 1][Ec1] - Sw[Er1][Sc1 - 1] + Sw[Sr1 - 1][Sc1 - 1];


            int Sr2 = i + K;
            int Sc2 = j + K;
            int Er2 = min(Sr2 + K - 1, 2 * K);
            int Ec2 = min(Sc2 + K - 1, 2 * K);
            count_b += Sb[Er2][Ec2] - Sb[Sr2 - 1][Ec2] - Sb[Er2][Sc2 - 1] + Sb[Sr2 - 1][Sc2 - 1];
            count_w += Sw[Er2][Ec2] - Sw[Sr2 - 1][Ec2] - Sw[Er2][Sc2 - 1] + Sw[Sr2 - 1][Sc2 - 1];

            int Sr3 = 1;
            int Sc3 = 1;
            int Er3 = Sr1 - 1;
            int Ec3 = Sc1 - 1;
            if (Ec3 >= Sc3 && Er3 >= Sr3) {
                count_b += Sb[Er3][Ec3] - Sb[Sr3 - 1][Ec3] - Sb[Er3][Sc3 - 1] + Sb[Sr3 - 1][Sc3 - 1];
                count_w += Sw[Er3][Ec3] - Sw[Sr3 - 1][Ec3] - Sw[Er3][Sc3 - 1] + Sw[Sr3 - 1][Sc3 - 1];
            }

            int Sr4 = 1;
            int Sc4 = Sc2;
            int Er4 = Sr1 - 1;
            int Ec4 = 2 * K;
            if (Ec4 >= Sc4 && Er4 >= Sr4) {
                count_b += Sb[Er4][Ec4] - Sb[Sr4 - 1][Ec4] - Sb[Er4][Sc4 - 1] + Sb[Sr4 - 1][Sc4 - 1];
                count_w += Sw[Er4][Ec4] - Sw[Sr4 - 1][Ec4] - Sw[Er4][Sc4 - 1] + Sw[Sr4 - 1][Sc4 - 1];
            }

            ll score = count_b + (white_num - count_w);
            max_score = max(max_score, score);
        }
    }
    cout << max_score << endl;
    return 0;
}

