template<class T>
struct CumulativeSum2D{
  vector2d<T> cum;

  CumulativeSum2D(const vector2d<T>& data):cum(data.size(), vector<T>(data[0].size(),0)){
    cum[0][0]=data[0][0];
    for(int r=1;r<data.size();r++){
      cum[r][0]=cum[r-1][0]+data[r][0];
    }
    for(int c = 1; c < data[0].size(); ++c){
      cum[0][c]=cum[0][c-1]+data[0][c];
    }
    for(int r = 1; r < data.size(); ++r){
      for(int c = 1; c < data[0].size(); ++c){
        cum[r][c]=cum[r-1][c]+cum[r][c-1]-cum[r-1][c-1]+data[r][c];
      }
    }
  }


  /// \return 2頂点が(sr,sc)と(gr,gc)であるような矩形内の和(2頂点を含む)
  T Query(int sr, int sc, int gr, int gc){
    T result=cum[gr][gc];
    if(sr-1>=0){
      result-=cum[sr-1][gc];
    }
    if(sc-1>=0){
      result-=cum[gr][sc-1];
    }
    if(sr-1>=0&&sc-1>=0){
      result+=cum[sr-1][sc-1];
    }
    return result;
  }
};

int main(){
  cout << std::fixed << std::setprecision(16);
  cin.tie(nullptr);
  std::ios::sync_with_stdio(false);

  int n,k;
  cin>>n>>k;
  auto *wpos=new vector2d<int>(2*k,vector<int>(2*k,0)),*bpos=new vector2d<int>(2*k,vector<int>(2*k,0));
  int mod=2*k;
  for(int i = 0; i < n; ++i){
    lint x,y;
    char c;
    cin>>x>>y>>c;
    if(c=='W'){
      (*wpos)[x%mod][y%mod]++;
    }else{
      (*bpos)[x%mod][y%mod]++;
    }
  }

  vector2d<int> wposl(4*k,vector<int>(4*k,0)),bposl(4*k,vector<int>(4*k,0));
  for(lint r=0;r<mod;r++){
    for(lint c=0;c<mod;c++){
      wposl[r][c]=(*wpos)[r][c];
      wposl[r+mod][c+mod]=(*wpos)[r][c];
      wposl[r][c+mod]=(*wpos)[r][c];
      wposl[r+mod][c]=(*wpos)[r][c];
    }
  }
  for(lint r=0;r<mod;r++){
    for(lint c=0;c<mod;c++){
      bposl[r][c]=(*bpos)[r][c];
      bposl[r+mod][c+mod]=(*bpos)[r][c];
      bposl[r+mod][c]=(*bpos)[r][c];
      bposl[r][c+mod]=(*bpos)[r][c];
    }
  }

  delete bpos;
  delete wpos;

  CumulativeSum2D<int> wcum(wposl),bcum(bposl);

  int result=0;

  for(lint r=0;r<mod;r++){
    for(lint c=0;c<mod;c++){
      int tmp=wcum.Query(r,c,r+k-1,c+k-1)+wcum.Query(r+k,c+k,r+2*k-1,c+2*k-1)+bcum.Query(r+k,c,r+2*k-1,c+k-1)+bcum.Query(r,c+k,r+k-1,c+2*k-1);
      UpdateMax(result,tmp);
    }
  }
  cout<<result<<endl;

  return 0;
}

