ll areaW(ll x1,ll x2,ll y1,ll y2){
  if (x1>x2 or x2<0)return ll(0);
  if (y1>y2 or y2<0)return ll(0);

  ll a1=0,a2=0,a3=0,a4=0;
  a1=WC[x2][y2];
  if (y1>=1)a2=WC[x2][y1-1];
  if (x1>=1)a3=WC[x1-1][y2];
  if (x1>=1 and y1>=1)a4=WC[x1-1][y1-1];
  ll ans=a1-a2-a3+a4;
  return ans;

}

