vector<ll> g0(ll K, ll x) {
    x %= 2 * K;
    vector<ll> v(4);
    v[0] = -x;
    v[1] = K - x;
    v[2] = 2 * K - x;
    v[3] = 3 * K - x;

    return v;
}

vector<ll> g1(ll K, ll x) {
    x %= 2 * K;
    vector<ll> v(4);
    v[0] = K - x;
    v[1] = 2 * K - x;
    v[2] = 3 * K - x;
    v[3] = 4 * K - x;
    return v;
}

void setRect(vector<vector<ll>>& s, vector<ll> x, vector<ll> y, ll K) {
    rep(i, x.size()) x[i] += 2 * K;
    rep(i, y.size()) y[i] += 2 * K;

    s[y[0]][x[0]]++;
    s[y[0]][x[1]]--;
    s[y[0]][x[2]]++;
    s[y[0]][x[3]]--;

    s[y[1]][x[0]]--;
    s[y[1]][x[1]]++;
    s[y[1]][x[2]]--;
    s[y[1]][x[3]]++;

    s[y[2]][x[0]]++;
    s[y[2]][x[1]]--;
    s[y[2]][x[2]]++;
    s[y[2]][x[3]]--;

    s[y[3]][x[0]]--;
    s[y[3]][x[1]]++;
    s[y[3]][x[2]]--;
    s[y[3]][x[3]]++;
}

void Main()
{
    ll n, K;
    cin >> n >> K;

    vector<ll> x(n), y(n);
    vector<char> c(n);
    rep(i, n) cin >> x[i] >> y[i] >> c[i];

    vector<vector<ll> > s(7 * K, vector<ll>(7 * K));

    // 有効なdx,dyの範囲を(0 ~ 2K)^2の範囲で各点について求めて、すぬけ法で集計する
    // 重複の最大値が答え
    rep(i, n) {
        if (c[i] == 'W') {
            auto xs = g0(K, x[i]);
            auto ys = g0(K, y[i]);
            setRect(s, xs, ys, K);

            xs = g1(K, x[i]);
            ys = g1(K, y[i]);
            setRect(s, xs, ys, K);
        }
        else {
            auto xs = g0(K, x[i]);
            auto ys = g1(K, y[i]);
            setRect(s, xs, ys, K);

            xs = g1(K, x[i]);
            ys = g0(K, y[i]);
            setRect(s, xs, ys, K);
        }
    }

    rep(y, s.size()) {
        repi(x, s.size()) {
            s[y][x] = s[y][x-1] + s[y][x];
        }
    }

    rep(x, s.size()) {
        repi(y, s.size()) {
            s[y][x] = s[y-1][x] + s[y][x];
        }
    }

    ll res = 0;
    rep(x, s.size()) {
        rep(y, s.size()) {
            res = max(res, s[y][x]);
        }
    }

    put(res);
}
