#define DUMP(a, n) REP(_i, n) printf("%d%c", a[_i], _i + 1 == n ? '\n' : ' ')
#define DUMP2D(a, n, m) REP(_i, n) REP(_j, m) printf("%d%c", a[_i][_j], _j + 1 == m ? '\n' : ' '); puts("")

const int N_MAX = 1e5;
const int K_MAX = 1000;
const int X_I_MAX = 1e9;
const int Y_I_MAX = 1e9;

int N, K;
int x[N_MAX];
int y[N_MAX];
char c[N_MAX][1 + 1];

int b[K_MAX*2][K_MAX*2];
int w[K_MAX*2][K_MAX*2];
int bacc[K_MAX*4][K_MAX*3];
int wacc[K_MAX*4][K_MAX*3];

void solve() {
  int K2 = K * 2;
  int K3 = K * 3;
  int K4 = K * 4;
  REP(i, N) {
    if (c[i][0] == 'B') {
      b[x[i] % K2][y[i] % K2]++;
    } else {
      w[x[i] % K2][y[i] % K2]++;
    }
  }
  // DUMP2D(b, K2, K2);
  // DUMP2D(w, K2, K2);
  REP(i, K4 - 1) REP(j, K3 - 1) {
    bacc[i + 1][j + 1] = bacc[i][j + 1] + bacc[i + 1][j] - bacc[i][j] + b[i % K2][j % K2];
    wacc[i + 1][j + 1] = wacc[i][j + 1] + wacc[i + 1][j] - wacc[i][j] + w[i % K2][j % K2];
  }
  // DUMP2D(bacc, K4, K4);
  // DUMP2D(wacc, K4, K4);
  int ans = 0;
  REP(i, K2) REP(j, K) {
    int ok = 0;
    ok += bacc[i + K][j + K] - bacc[i][j + K] - bacc[i + K][j] + bacc[i][j];
    ok += bacc[i + K2][j + K2] - bacc[i + K][j + K2] - bacc[i + K2][j + K] + bacc[i + K][j + K];
    ok += wacc[i + K][j + K2] - wacc[i][j + K2] - wacc[i + K][j + K] + wacc[i][j + K];
    ok += wacc[i + K2][j + K] - wacc[i + K][j + K] - wacc[i + K2][j] + wacc[i + K][j];
    // printf("i:%d j:%d ok:%d\n", i, j, ok);
    ans = max(ans, ok);
  }
  printf("%d\n", ans);
}

void input() {
  scanf("%d%d", &N, &K);
  REP(i, N) scanf("%d%d%s", x + i, y + i, c[i]);
}

int main() {
  input();
  solve();
  return 0;
}

