        // Ambiguity : 2K * 2K
        if ( x[i] < 0 || x[i] >= 2 * K) {
            x[i] %= (2 * K);
        }
        if ( y[i] < 0 || y[i] >= 2 * K) {
            y[i] %= (2 * K);
        }
