#endif
    for (int orig_x = 0; orig_x < 2 * K; ++orig_x) // Search X-direction
    {
        for (int orig_y = 0; orig_y < 2 * K; ++orig_y) // Search Y-direction
        { 
            for (int k = 0; k < N; ++k) // Check requests
            {
                if (c[k] == 'B')
                {
                    if (is_in_black(x[k], y[k], orig_x, orig_y))
                    {
