bool is_in_black(int x, int y, int orig_x, int orig_y)
{
    if (((x >= 0 && x < orig_x) && // 1-1
         (y >= 0 && y < orig_y)) ||
        ((x >= 0 && x < orig_x) && // 1-3
         (y >= orig_y + K && y < orig_y + 2 * K)) ||
        ((x >= orig_x && x < orig_x + K) && // 2-2
         (y >= orig_y && y < orig_y + K)) ||
        ((x >= orig_x + K && x < orig_x + 2 * K) && // 3-1
         (y >= 0 && y < orig_y)) ||
        ((x >= orig_x + K && x < orig_x + 2 * K) && // 3-3
         (y >= orig_y + K && y < orig_y + 2 * K)))
    {
        return true;
    }
    return false;
}

