int main() {
  std::int_fast64_t n, k;
  std::cin >> n >> k;

  std::vector<std::vector<std::int_fast64_t>> dots(2 * k, std::vector<std::int_fast64_t>(2 * k, 0));
  for (std::int_fast64_t i = 0; i < n; ++i) {
    std::int_fast64_t x_i, y_i;
    char c_i;
    std::cin >> x_i >> y_i >> c_i;
    switch (c_i) {
    case 'B':
      ++dots[x_i % (2 * k)][y_i % (2 * k)];
      ++dots[(x_i + k) % (2 * k)][(y_i + k) % (2 * k)];
      break;
    case 'W':
      ++dots[x_i % (2 * k)][(y_i + k) % (2 * k)];
      ++dots[(x_i + k) % (2 * k)][y_i % (2 * k)];
      break;
    }
  }

  std::vector<std::vector<std::int_fast64_t>> cumsum(2 * k, std::vector<std::int_fast64_t>(2 * k, 0));
  for (std::int_fast64_t i = 0; i < 2 * k - 1; ++i) {
    for (std::int_fast64_t j = 0; j < 2 * k - 1; ++j) {
      cumsum[i + 1][j + 1] = cumsum[i][j + 1] + cumsum[i + 1][j] - cumsum[i][j] + dots[i][j];
    }
  }

  std::int_fast64_t answer = 0;
  for (std::int_fast64_t i = 0; i < k; ++i) {
    for (std::int_fast64_t j = 0; j < k; ++j) {
      const std::int_fast64_t captured = cumsum[i + k][j + k] - cumsum[i][j + k] - cumsum[i + k][j] + cumsum[i][j];
      const std::int_fast64_t complement = n - captured;
      answer = std::max(answer, std::max(captured, complement));
    }
  }

  std::cout << answer << std::endl;
  return 0;
}

