  vvi d = vv(2*k, k, 0, int);

  re(i, n){
    std::cin >> q[i][0] >> q[i][1];
    char t;std::cin >> t;
    //vector<string> tm = read_vec();
    //q[i][0] = stoll(tm[0]), q[i][1] = stoll(tm[1]);
    //char t = tm[2][0];
