    q[i][0] %= 2*k, q[i][1] %= 2*k;
    if(q[i][1]>=k) q[i][1]-=k, q[i][0]+=k;
    if(q[i][0]>=2*k) q[i][0] -= 2*k;
    d[q[i][0]][q[i][1]]++;
  }
  ll ans = 0;
  segtree seg(d);

  re(p, n){
    int i = q[p][0], j = q[p][1];
    if(i>=k) i-=k;
    ll n1 = seg.minimum(i, j, i+k, k) + seg.minimum(i+k, 0, 2*k, j) + seg.minimum(0, 0, i, j);
    ll n2 = seg.minimum(i, 0, i+k, j+1) + seg.minimum(i+k, j+1, 2*k, k)+seg.minimum(0, j+1, i, k);
    ll n3 = seg.minimum(i+1, 0, i+1+k, j) + seg.minimum(i+1+k, j, 2*k, k)+seg.minimum(0, j, i+1, k);
    ll n4 = seg.minimum(i+1, 0, i+1+k, j+1) + seg.minimum(i+1+k, j+1, 2*k, k)+seg.minimum(0, j+1, i+1, k);
    ans = max({ans,n1,n-n1,n2,n-n2,n3,n-n3,n4,n-n4});
  }
  std::cout << ans << '\n';
  return 0;
}

