int main() {
  cin >> N >> K;
  for (int i=0; i<N; i++) {
    cin >> x >> y >> c;
    if (c == 'W') {
      x += K;
    }
    x = x%(2*K);
    y = y%(2*K);
    sum[x+1][y+1]++;
  }

  for (int i=0; i<2*K+1; i++) {
    for (int j=1; j<2*K+1; j++) {
      sum[i][j] += sum[i][j-1];
    }
  }
  for (int j=0; j<2*K+1; j++) {
    for (int i=1; i<2*K+1; i++) {
      sum[i][j] += sum[i-1][j];
    }
