  for (int i=0; i<=K; i++) {
    for (int j=0; j<=K; j++) {
      int a = sum[i][j];
      int b = sum[i+K][j+K] - sum[i][j+K] - sum[i+K][j] + sum[i][j];
      int c = sum[2*K][2*K] - sum[2*K][j+K] - sum[i+K][2*K] + sum[i+K][j+K];
