using namespace std;

int N, K;
// vector<vector<int> > B(4020, vector<int>(4020, 0));
// vector<vector<int> > W(4020, vector<int>(4020, 0));
vector<vector<int> > memo(2020, vector<int>(2020, 0));

void imos(int x1, int y1, int x2, int y2) {
    memo[y1][x1]++;
    memo[y2][x1]--;
    memo[y1][x2]--;
    memo[y2][x2]++;
}

int main() {
    cin >> N >> K;
    int K2 = K * 2;
    for(int i = 0; i < N; i++) {
        int x, y;
        char c;
        cin >> x >> y >> c;
        x %= K2;
        y %= K2;
        // 黒の領域の累積和をいもす法で計算する
        if( ((x/K&1) ^ (y/K&1)) ^ (c=='B')) {
            /*
            黒の始点が左上か右下，白の始点が右上か左下にあれば以下の模様になる
            # # . . . . # #
            # # . . . . # #
            . . # # # # . .
            . . # # # # . .
            . . # # # # . .
            . . # # # # . .
            # # . . . . # #
            # # . . . . # #
            */
            int x00 = x % K + 1, y00 = y % K + 1;   // 中心位置にあるK*K矩形の左上
            int x11 = x00 + K, y11 = y00 + K;       // 中心位置にあるK*K矩形の右下

            imos(0, 0, x00, y00);
            imos(x11, 0, K2, y00);
            imos(x00, y00, x11, y11);
            imos(0, y11, x00, K2);
            imos(x11, y11, K2, K2);
        } else {
            /*
            それ以外は
            . . # # # # . .
            . . # # # # . .
            # # . . . . # #
            # # . . . . # #
            # # . . . . # #
            # # . . . . # #
            . . # # # # . .
            . . # # # # . .
            */
            int x00 = x % K + 1, y00 = y % K + 1;   // 中心位置にあるK*K矩形の左上
            int x11 = x00 + K, y11 = y00 + K;       // 中心位置にあるK*K矩形の右下

            imos(x00, 0, x11, y00);
            imos(0, y00, x00, y11);
            imos(x11, y00, K2, y11);
            imos(x00, y11, x11, K2);
        }
    }

    for(int y = 0; y < K2; y++) {
        for(int x = 1; x < K2; x++) {
            memo[y][x] += memo[y][x-1];
        }
    }

    for(int y = 1; y < K2; y++) {
        for(int x = 0; x < K2; x++) {
            memo[y][x] += memo[y-1][x];
        }
    }

    int ans = -1e9+1;
    for(int y = 0; y < K2; y++) {
        for(int x = 0; x < K2; x++) {
            ans = max(ans, memo[y][x]);
        }
    }

    cout << ans << endl;

    return 0;
}

#include <iostream>
#include <cmath>
#include <algorithm>
#include <vector>

struct Cond {
  int x, y;
  char c;
};

typedef std::vector<int> Board;

int main() {
  int n, k;
  std::cin >> n  >> k;
  const int k2 = k*2;

  Board board(k2*k2, 0);
  for( int i = 0; i < n; ++i ) {
    Cond c;
    std::cin >> c.x >> c.y >> c.c;
    c.x %= k2;
    c.y %= k2;

    for( size_t ry = 0; ry < k2; ++ry ) {
      for( size_t rx = 0; rx < k2; ++rx ) {
        const bool black = (rx < k) != (ry < k);
        const int x = (c.x + rx) % k2;
        const int y = (c.y + ry) % k2;

        if( black == (c.c == 'B') ) {
          board[ y * k2 + x ] += 1;
        }
      }
    }
  }

  int m = 0;
  for( size_t y = 0; y < k2; ++y ) {
    for( size_t x = 0; x < k2; ++x ) {
      m = std::max(m, board[ y * k2 + x ]);
    }
  }

  std::cout << m << std::endl;
}

