using namespace std;

void solve(long long N, long long K, std::vector<long long> x, std::vector<long long> y, std::vector<std::string> c) {
    vector<vector<LL>> tw(2 * K + 1, vector<LL>(2 * K + 1, 0)), tb(2 * K + 1, vector<LL>(2 * K + 1, 0));
    // initialize
    for (LL i = 0; i < N; i++) {
        if (c[i] == "W")
            tw[y[i] % (2 * K) + 1][x[i] % (2 * K) + 1]++;
        else
            tb[y[i] % (2 * K) + 1][x[i] % (2 * K) + 1]++;
    }
    // accumulate
    for (LL i = 0; i <= 2 * K; i++)
        for (LL j = 1; j <= 2 * K; j++) {
            tb[i][j] = tb[i][j] + tb[i][j - 1];
            tw[i][j] = tw[i][j] + tw[i][j - 1];
        }
    for (LL i = 1; i <= 2 * K; i++)
        for (LL j = 0; j <= 2 * K; j++) {
            tb[i][j] = tb[i][j] + tb[i - 1][j];
            tw[i][j] = tw[i][j] + tw[i - 1][j];
        }

    auto get_sum = [K](vector<vector<LL>> &tab, LL x1, LL y1, LL x2, LL y2){
        //if(x1>x2 || y1>y2)return 0LL;
        x1=max(x1, 1LL), y1=max(y1, 1LL);
        x2=min(x2, 2*K+1), y2=min(y2, 2*K+1);
        return tab[y2-1][x2-1]-tab[y2-1][x1-1]-tab[y1-1][x2-1]+tab[y1-1][x1-1];
    };
    LL ans=0;
    for(LL x1=1; x1<=K; x1++){
        for(LL y1=1; y1<=K; y1++){
            LL pb=0, pw=0;
            for(LL dx=0; dx<=2; dx++){
                for(LL dy=0; dy<=2; dy++){
                    if(((dx+dy)%2)==0){
                        pb += get_sum(tb, x1+K*(dx-1), y1+K*(dy-1), x1+K*dx, y1+K*dy);
                    }else{
                        pb += get_sum(tw, x1+K*(dx-1), y1+K*(dy-1), x1+K*dx, y1+K*dy);
                    }
                }
            }
            ans = max(ans, pb+pw);
        }
    }
    cout << ans << endl;
}

