int getSum(int color, int i, int j, int ii, int jj) {
  if (i > ii) {
    return getSum(color, 0, j, ii, jj) + getSum(color, i, j, 2 * k - 1, jj);
  }
  if (j > jj) {
    return getSum(color, i, 0, ii, jj) + getSum(color, i, j, ii, 2 * k - 1);
  }
  int result = sum[color][ii][jj];
  if (i > 0) {
    result -= sum[color][i - 1][jj];
  }
  if (j > 0) {
    result -= sum[color][ii][j - 1];
  }
  if (i > 0 && j > 0) {
    result += sum[color][i - 1][j - 1];
  }
  return result;
}

