using ld = long double;

int main() {
	ll n, k;
	cin >> n >> k;
	ll h = k * 2;
	vvll b(h * 2 + 1, vll(h * 2 + 1, 0));

	function<ll(ll, ll)> sums = [&](ll x, ll y) { return b[x][y] + b[x + k][y + k] - b[x + k][y] - b[x][y + k]; };

	ll ans = 0;
	ll defo = 0;
	rep(i, n) {
		ll a, g;
		char c;
		cin >> a >> g >> c;
		a %= h;
		g %= h;
		if(c == 'W') {
			b[a % (2 * k) + 1][g % h + 1]++;
			b[a + h + 1][g + 1]++;
			b[a + 1][g + h + 1]++;
			b[a + h + 1][g + 1 + h]++;
		} else {
			b[a % (2 * k) + 1][1 + g % h]--;
			defo++;
			b[a + h + 1][1 + g]--;
			b[a + 1][g + h + 1]--;
			b[a + h + 1][g + 1 + h]--;
		}
	}

	rep(i, h * 2 + 1) {
		rep(j, h * 2) { b[i][j + 1] += b[i][j]; }
	}
	rep(j, h * 2 + 1) {
		rep(i, h * 2) { b[i + 1][j] += b[i][j]; }
	}

	//[x][y],[x+a][y],[x][y+b],[x+a][y+b]
	// b[x+a][y+b]-b[x][y+b]-b[x+a][y]+b[x][y]

	//{x,y}=白を始める角
	rep(x, k) {
		rep(y, k) {
			ll res = defo;
			res += sums(x, y);
			res += sums(x + k, y + k);
			maxin(ans, res);
		}
	}
	cout << ans << endl;
}

