struct data1 {

    int x;
    int y;
    bool t;

    bool operator< (const data1& next_data) {

        if (x < next_data.x) return true;
        else if (x == next_data.x) {
            if (y < next_data.y) return true;
            else if (y == next_data.y) {
                if (t < next_data.t) return true;
                else return false;
            }
            return false;
        }
        return false;
    }

};
int main() {

    int N, K;
    string s;
    cin >> N >> K;
    vector<data1> input(N);

    int count = 0;
    data1 tmp_data;
    while (count < N) {

        cin >> tmp_data.x >> tmp_data.y;
        cin >> s;
        if (s == "W") tmp_data.t = 0;
        else   tmp_data.t = 1;

        input.at(count) = tmp_data;
        count++;
    }

    sort(input.begin(), input.end());
    //for (auto x : input) cout << x.x << " " << x.y << " " << x.t << endl;

    data1 zero;
    int delay_x, delay_y, color;

    int total_count = 0;
    int max_count = 0;
    for (int i = 0; i < K; i++) {
        for (int j = 0; j < K; j++) {
            zero.x = i;
            zero.y = j;
            zero.t = 1;

            total_count = 0;
            for (int k = 0; k < N; k++) {
                delay_x = input.at(k).x - zero.x;
                delay_y = input.at(k).y - zero.y;

                delay_x = abs(delay_x) % (K * 2);
                delay_y = abs(delay_y) % (K * 2);

                if (delay_x < K && delay_y < K) {
                    color = 1;
                }
                else if (delay_x >= K&& delay_y >= K) {
                    color = 1;
                }
                else if (delay_x >= K&& delay_y < K) {
                    color = 0;
                }
                else if (delay_x<K && delay_y>=K) {
                    color = 0;
                }
                if (input.at(k).x - zero.x < 0) color = !color;
                if (input.at(k).y - zero.y < 0) color = !color;

                if (color == input.at(k).t) total_count++;

            }

            if (total_count > max_count) max_count = total_count;


        }
    }
    cout << max_count;

}

