			bool color = (col + row) % 2;
			if(color == C[i]) {
				++counter0;
			} else {
				++counter1;
			}
		}
		ans = max(ans, max(counter0, counter1));
	}
	}
	// Output
	cout << ans << endl;
	return 0;
}

