/*
the operators regarding bit

     x1: 0000 0001 0010 0101 0110 0111
     x2: xxxx 0001 0011 0100 0101 1000
x1 & x2: 0000 0001 0010 0100 0100 0000

      x: 1001 1010  1100 1011 1101  1111
x & - x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

x << y is x * 2 ** y
x >> y is rep(i, y) x = x // 2 
*/

const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, k, x, y;
char c;
ll cnt[2][3004][3004]; // 0 is white, 1 is black
ll sq[2][2004][2004];

ll calc_sum(ll x, ll y){
    ll val_black = sq[1][x][y];
    ll val_white = cnt[0][2 * k][2 * k] - sq[0][x][y];
    ll x2 = x + k; ll y2 = y + k;
    if (x + k > 2 * k) x2 = x - k;
    if (y + k > 2 * k) y2 = y - k;

    val_black += sq[1][x2][y2];
    val_white -= sq[0][x2][y2];
    return val_black + val_white;
}

void solve(){
    rep(i, 2) rep(x, 3 * k + 1) rep(y, 3 * k + 1) cnt[i][x][y] = 0; 
    rep(i, n){
        in3(x, y, c);
        ll xi = x % (2 * k) + 1; ll yi = y % (2 * k) + 1;
        cnt[c == 'B'][xi][yi]++;
        if (xi <= k) cnt[c == 'B'][xi + 2 * k][yi]++;
        if (yi <= k) cnt[c == 'B'][xi][yi + 2 * k]++;
        if (xi <= k && yi <= k) cnt[c == 'B'][xi + 2 * k][yi + 2 * k]++;
    }

    rep(x, 3 * k) rep(y, 3 * k + 1){
        cnt[0][x + 1][y] += cnt[0][x][y];
        cnt[1][x + 1][y] += cnt[1][x][y];
    }

    rep(x, 3 * k + 1) rep(y, 3 * k){
        cnt[0][x][y + 1] += cnt[0][x][y];
        cnt[1][x][y + 1] += cnt[1][x][y];
    }

    For(x, 1, 2 * k + 1) For(y, 1, 2 * k + 1){
        sq[0][x][y] = cnt[0][x + k - 1][y + k - 1] - cnt[0][x + k - 1][y - 1] - cnt[0][x - 1][y + k - 1] + cnt[0][x - 1][y - 1];
        sq[1][x][y] = cnt[1][x + k - 1][y + k - 1] - cnt[1][x + k - 1][y - 1] - cnt[1][x - 1][y + k - 1] + cnt[1][x - 1][y - 1];
    }

    For(x, 1, 2 * k + 1) For(y, 1, 2 * k + 1) answer = max(answer, calc_sum(x, y));

    prl(answer);
}

int main(void){
    in2(n, k);
    // assert(n <= 999);
    solve();

    return 0;
}

