template< class T > struct CumulativeSum2D {
   //this library is created by ei1333.
  vector< vector< T > > data;

  CumulativeSum2D(int W, int H) : data(W + 1, vector< int >(H + 1, 0)) {}

  void add(int x, int y, T z) {
    ++x, ++y;
    if(x >= data.size() || y >= data[0].size()) return;
    data[x][y] += z;
  }

  void build() {
    for(int i = 1; i < data.size(); i++) {
      for(int j = 1; j < data[i].size(); j++) {
        data[i][j] += data[i][j - 1] + data[i - 1][j] - data[i - 1][j - 1];
      }
    }
  }

  T query(int sx, int sy, int gx, int gy) {
    return (data[gx][gy] - data[sx][gy] - data[gx][sy] + data[sx][sy]);
  }
};
int main(void){
   ll n,k;cin >> n >> k;
   CumulativeSum2D<int> C(2*k,2*k);
   rep(i,n){
      ll a,b;char c;cin >> a >> b >> c;
      a--;b--;
      if(c == 'W') a += k;

      a %= 2*k,b %= 2*k;
      C.add(a,b,1);
   }
   C.build();
   int ans = 0;

   for(int i = 0;i < k;i++)for(int j = 0;j < k;j++){
      int count = 0;

      count += C.query(i,j,i+k,j+k);
      count += C.query(i+k,j+k,2*k,2*k);
      count += C.query(0,0,i,j);
      count += C.query(i+k,0,2*k,j);
      count += C.query(0,j+k,i,2*k);

      maxs(ans,count);
   }
   cout << ans << endl;
}

