int main() {
  int n, k;
  cin>>n>>k;
  for (int i=0; i<2*k; i++) {
    for (int j=0; j<2*k; j++) {
      m[i][j] = 0;
    }
  }
  for (int i=0; i<n; i++) {
    int x, y;
    cin>>x>>y;
    char c;
    cin>>c;
    if (c == 'B') {
      y += k;
    }
    x = x % (2 * k);
    y = y % (2 * k);
    ++m[y][x];
  }
  for (int i=0; i<2*k+1; i++) {
    acc[i][0] = 0;
    acc[0][i] = 0;
  }
  for (int i=0; i<2*k; i++) {
    for (int j=0; j<2*k; j++) {
      acc[i+1][j+1] = acc[i+1][j] + acc[i][j+1] - acc[i][j] + m[i][j];
    }
  }

  int ans = 0;
  for (int i=0; i<k+1; i++) {
    for (int j=0; j<k+1; j++) {
      int cnt = 0;
      for (int s=0; s<3; s++) {
        for (int t=0; t<3; t++) {
          if ((s + t) % 2 == 1) {
            continue;
          }
          int y1 = min(i + s * k, 2 * k);
          int y2 = max(i + (s - 1) *k, 0);
          int x1 = min(j + t * k, 2 * k);
          int x2 = max(j + (t - 1) * k, 0);
          cnt += acc[y1][x1] - acc[y1][x2] - acc[y2][x1] + acc[y2][x2];
        }
      }
      ans = max(cnt, ans);
    }
  }
  cout<<ans<<endl;
}

