int satisfy(int n,int k,int i,int j,long x[],long y[],char c[])
{
    char draw[n];
    int p,s1=0,s2=0;

    for(p=0;p<n;p++)
        if(((x[p]+i)%(2*k)<k)^((y[p]+j)%(2*k)<k))
            draw[p]='B';
        else
            draw[p]='W';
    for(p=0;p<n;p++)
        if(draw[p]==c[p])
            s1++;
        else
            s2++;

    return s1>s2?s1:s2;
}

