	return a[x2][y2][t] - a[x1-1][y2][t] - a[x2][y1-1][t] + a[x1-1][y1-1][t];
}
int main() {
	int N, K, Max = 0, cnt = 0;
	scanf("%d%d",&N,&K);
	for(int i=1;i<=N;i++) {
		int x, y;char ch;
