int color(unsigned K, unsigned xoff, unsigned yoff, unsigned x, unsigned y)
{
  unsigned s = 0;
  if (x >= xoff) { unsigned px = (x - xoff) % (2 * K); s += (px >= K) ? 1 : 0; } else { ++s; }
  if (y >= yoff) { unsigned py = (y - yoff) % (2 * K); s += (py >= K) ? 1 : 0; } else { ++s; }
  return (s % 2 == 0) ? Color::Black : Color::White;
}

