template<typename T = int>
struct S2D {
    const int w, h;
    V<V<T>> f;

    S2D(int w, int h, T z) : f(h+1, V<T>(w+1,z)), w(w+1), h(h+1) {}

    void build() {
        for(int i = 1; i < h; i++) {
            for(int j = 1; j < w; j++) {
                f[i][j] = f[i][j] + f[i][j-1] + f[i-1][j] - f[i-1][j-1];
            }
        }
    }

    void add(int x, int y, T val) {
        x++; y++;
        if(x >= w || h <= y) return ;
        f[y][x] += val;
    }

    T query(int lx, int ly, int rx, int ry) {
        return f[ry][rx] - f[ly][rx] - f[ry][lx] + f[ly][lx];
    }
};

LL N, K;

