    }

    s2d.build();

    LL ans = 0;
    REP(i,K) {
        FOR(j,0,K) {
            int rx = i+K;
            int ry = j+K;
            LL cnt = s2d.query(i,j,rx,ry);
            cnt += s2d.query(0,0,i,j);
            cnt += s2d.query(rx,0,2*K+1,j);
            cnt += s2d.query(0,ry,i,2*K+1);
            cnt += s2d.query(rx,ry,2*K,2*K);
            if(cnt >= 0) {
                ans = std::max(ans, cnt);
                ans = std::max(ans, N-cnt);
            }
        }
    }
    cout << ans;
}

