	//if(x2 < x1 || y2 < y1) return 0;
	//cout << x1 << " " << y1 << " " << x2 << " " << y2 << endl;
	int a,b,c;
	if(x1 == 0 || y1 == 0) a = 0;
	else a = sum[y1-1][x1-1];
	if(x1 == 0) b = 0;
	else b = sum[y2][x1-1];
	if(y1 == 0) c = 0;
	else c = sum[y1-1][x2];
	return sum[y2][x2]-b-c+a;
}

int main() {
