		field[y%(2*K)][x%(2*K)]++;
	}


	for (int i = 0;i < 2*K;i++){
		for (int j = 0;j < 2*K;j++){
			int a,b,c;
			if(i-1 < 0 || j-1 < 0) a = 0;
			else a = sum[i-1][j-1];
			if(i-1 < 0) b = 0;
			else b = sum[i-1][j];
			if(j-1 < 0) c = 0;
			else c = sum[i][j-1];
			sum[i][j] = field[i][j]+c+b-a;
		}
	}

