template<typename T>
struct CumSum2D {
    int xnum, ynum;
    vector<vector<T>> data;
    vector<vector<T>> cumsum;

    CumSum2D(int xnum, int ynum) : xnum(xnum), ynum(ynum) {
        ndarray(data, xnum+1, ynum+1);
        ndarray(cumsum, xnum+1, ynum+1);
    }

    int add(int x, int y, T value) {
        //x,y 0~_num-1
        ++x;
        ++y;
        if (x > xnum || y > ynum) return -1;
        data[x][y] += value;
        return 0;
    }

    int add_imos(int startx, int starty, int endx, int endy) {
        //start_ 0~_num-1
        //end_ 1~_num
        if (add(endx, endy, (T) 1) == 1) return -1;
        if (add(startx, endy, (T) 1) == -1) return -1;
        if (add(endx, starty, (T) 1) == -1) return -1;
        if (add(startx, starty, (T) 1) == 1) return -1;
        return 0;
    }

    void build() {
        for (int i = 0; i < xnum; i++) {
            for (int j = 0; j < ynum; j++) {
                cumsum[i+1][j+1] = data[i+1][j+1] + cumsum[i+1][j] + cumsum[i][j+1] - cumsum[i][j];
            }
        }
    }

    T get(int startx, int starty, int endx, int endy) {
        //[(startx, starty) ~ (endx, endy))のdataの和を返す
        //start_ 0~_num-1
        //end_ 1~_num
        return (cumsum[endx][endy] - cumsum[endx][starty] - cumsum[startx][endy] - cumsum[startx][starty]);
    }

    void print() {
        std::cout << "cumsum" << std::endl;
        for (auto vec : cumsum) {
            for (auto val : vec) {
                std::cout << val << " ";
            }
            std::cout << std::endl;
        }
    }
    void print_data() {
        std::cout << "data" << std::endl;
        for (auto vec : data) {
            for (auto val : vec) {
                std::cout << val << " ";
            }
            std::cout << std::endl;
        }
    }
};

