using ll = long long;

int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);

  int n,k; cin>>n>>k;
  map<pair<int, int>, int> wb, ww;
  vector<vector<int>> bgrid(3*k, vector<int>(3*k, 0));
  vector<vector<int>> wgrid(3*k, vector<int>(3*k, 0));
  for (int i = 0; i < n; i++) {
    int x,y; cin>>x>>y;
    x=x%(2*k);
    y=y%(2*k);
    char c; cin>>c;
    if (c=='B') {
      bgrid[k+x][k+y]++;
    } else {
      wgrid[k+x][k+y]++;
    }
  }
  for (int i = k; i < 3*k; i++) {
    for (int j = k; j < 3*k; j++) {
      bgrid[i][j] += bgrid[i-1][j];
      wgrid[i][j] += wgrid[i-1][j];
      bgrid[i][j] += bgrid[i][j-1];
      wgrid[i][j] += wgrid[i][j-1];
      bgrid[i][j] -= bgrid[i-1][j-1];
      wgrid[i][j] -= wgrid[i-1][j-1];
    }
  }
  auto area_sum = [&](int x, int y, bool black) {
    auto grid = black ? bgrid : wgrid;
    auto bx = x-k;
    auto by = y-k;
    x = min(x, 3*k-1);
    y = min(y, 3*k-1);
    int res = grid[x][y];
    if (bx>=0)
      res -= grid[bx][y];
    if (by>=0)
      res -= grid[x][by];
    if (bx>=0 and by>=0)
      res += grid[bx][by];
    return res;
  };
  int ans = 0;
  for (int i = k; i < 2*k; i++) {
    for (int j = k; j < 2*k; j++) {
      for (int ltb = 0; ltb < 2; ltb++) {
        int res = 0;
        res += area_sum(i-1, j-1, !ltb);
        res += area_sum(i-1, j+2*k-1, !ltb);
        res += area_sum(i+k-1, j+k-1, !ltb);
        res += area_sum(i+2*k-1, j-1, !ltb);
        res += area_sum(i+2*k-1, j+2*k-1, !ltb);
        res += area_sum(i-1, j+k-1, ltb);
        res += area_sum(i+k-1, j-1, ltb);
        res += area_sum(i+k-1, j+2*k-1, ltb);
        res += area_sum(i+2*k-1, j+k-1, ltb);
        ans = max(ans, res);
//        cerr<<i<<j<<res<<endl;
      }
    }
  }
  cout << ans << endl;

  return 0;
}

