const int INF = 1000000000;


int cal(int x1, int y1, int x2, int y2, vector<vector<int> >& board)
{
  int ret = board[y2][x2] - board[y2][x1] - board[y1][x2] + board[y1][x1];
  // fprintf(stderr, "DEBUG: (x1, y1)=(%d, %d), (x2, y2)=(%d, %d), ret=%d\n", x1, y1, x2, y2, ret);
  return ret;
}

int main()
{
  int N, K;
  scanf("%d %d", &N, &K);
  vector<vector<int> > board(2 * K + 1, vector<int>(2 * K + 1, 0));
  for (int i = 0; i < N; ++i) {
    int x, y;
    char c;
    scanf("%d %d %c", &x, &y, &c);
    if (c == 'W') { x += K; }
    x %= (2 * K);
    y %= (2 * K);
    ++board[y + 1][x + 1];
  }

  // fprintf(stderr, "DEBUG: before cumsum\n");
  // for (int i = 1; i <= 2 * K; ++i) {
  //   for (int j = 1; j <= 2 * K; ++j) {
  //     printf("%3d ", board[i][j]);
  //   }
  //   printf("\n");
  // }
  // fprintf(stderr, "DEBUG: after cumsum\n");
  // for (int y = 1; y <= 2 * K; ++y) {
  //   for (int x = 1; x <= 2 * K; ++x) {
  //     board[y][x] += board[y][x - 1] + board[y - 1][x] - board[y - 1][x - 1];
  //   }
  // }

  // for (int i = 1; i <= 2 * K; ++i) {
  //   for (int j = 1; j <= 2 * K; ++j) {
  //     printf("%3d ", board[i][j]);
  //   }
  //   printf("\n");
  // }
  int ans = 0;
  for (int x = 1; x <= 2 * K; ++x) {
    for (int y = 1; y <= 2 * K; ++y) {
      int cnt = 0;
      // (x, y) is at the bottom-right cell.
      int x1 = max(0, x - K), y1 = max(0, y - K);
      // this square
      cnt += cal(x1, y1, x, y, board);
      // bottom-right1
      int x2 = min(x + K, 2 * K), y2 = min(y + K, 2 * K);
      cnt += cal(x, y, x2, y2, board);
      // right
      x1 = min(x + K, 2 * K); y1 = max(y - K, 0);
      x2 = min(x + K + K, 2 * K); y2 = y;
      cnt += cal(x1, y1, x2, y2, board);
      // bottom-right2
      x1 = min(x + K, 2 * K); y1 = min(y + K, 2 * K);
      x2 = 2 * K; y2 = 2 * K;
      cnt += cal(x1, y1, x2, y2, board);
      // left
      x1 = max(0, x - K); y1 = min(y + K, 2 * K);
      x2 = x; y2 = 2 * K;
      cnt += cal(x1, y1, x2, y2, board);
      // fprintf(stderr, "DEBUG: (x, y)=(%d, %d), cnt=%d\n", x, y, cnt);
      ans = max(ans, cnt);
    }
  }
  printf("%d\n", ans);

  return 0;
}

