	int anss=0;
	REP(i,K*2){
		FOR(j,1,2*K){
			ans[i][j]+=ans[i][j-1];
		}
	}
	REP(i,2*K){
		FOR(j,1,2*K){
			ans[j][i]+=ans[j-1][i];
		}
	}
	REP(i,2*K){
		REP(j,2*K)anss=max(anss,ans[i][j]);
	}

	cout<<anss<<endl;
	return 0;
}

