        }
    }

    for(int i = 1; i <= n; ++i)
    {
        x[i] %= 2 * k;
        y[i] %= 2 * k;

        ++arr[y[i]][x[i]];
    }


    for(int i = 1; i < 2 * k; ++i)
        arr[0][i] += arr[0][i - 1];


    for(int i = 1; i < 2 * k; ++i)
        arr[i][0] += arr[i - 1][0];

    for(int i = 1; i < 2 * k; ++i)
        for(int j = 1; j < 2 * k; ++j)
            arr[i][j] += arr[i - 1][j] + arr[i][j - 1] - arr[i - 1][j - 1];


    int answer = 0;

    for(int i = 0; i < 2 * k; ++i)
        for(int j = 0; j < 2 * k; ++j)
        {
            int temp = 0;

            temp += amount(i, j, i - k + 1, j - k + 1);//centr

            temp += amount(i + k, j + k, i + 1, j + 1);//prav niz

            temp += amount(i - k, j + k, i - 2 * k + 1, j + 1);//prav verh

            temp += amount(i - k, j - k, i - 2 * k + 1, j - 2 * k + 1); // lev verh

            temp += amount(i + k, j - k, i + 1, j - 2 * k + 1);//lev niz

            answer = max(answer, temp);
        }


    cout << answer << '\n';
}

