int sum[4040][4040];
int b[2020][2020];

int calc(int x,int y){
  return(sum[y+k][x+k]-sum[y+k][x]-sum[y][x+k]+sum[y][x]);
}

int main(){
  cin>>n>>k;
  for(int i=0;i<n;i++){
    int x,y;
    char c;
    cin>>x>>y>>c;
    if(c=='W') x+=k;
    x%=2*k;
    y%=2*k;
    b[y][x]++;
  }

  for(int i=0;i<4*k;i++){
    for(int j=0;j<4*k;j++){
      sum[i][j]=b[i%(2*k)][j%(2*k)];
    }
  }

  for(int i=0;i<4*k;i++){
    for(int j=1;j<4*k;j++){
      sum[i][j]+=sum[i][j-1];
    }
  }

  for(int i=1;i<4*k;i++){
    for(int j=0;j<4*k;j++){
      sum[i][j]+=sum[i-1][j];
    }
  }

  int ans=0;
  for(int i=0;i<2*k;i++){
    for(int j=0;j<2*k;j++){
      int tmp;
      tmp=calc(j,i)+calc(j+k,i+k);
      ans=max(ans,tmp);
    }
  }
  cout<<ans<<endl;

  return 0;
}

