int warr[N][N];
int barr[N][N];

int getW(int x, int y, int x2, int y2)
{
	if(x2 < x || y2 < y)return 0;
	int temp = warr[x2][y2] - warr[x2][y-1] - warr[x-1][y2];
	temp += warr[x-1][y-1];
	return temp;
}
int getB(int x, int y, int x2, int y2)
{
	if(x2 < x || y2 < y)return 0;
	int temp = barr[x2][y2] - barr[x2][y-1] - barr[x-1][y2];
	temp += barr[x-1][y-1];
	return temp;
}

int main()
{
	int n, k;
	cin>>n>>k;
	int k2 = 2*k;
	rep(i, 0, n)
	{
		int x, y;
		char ch;
		cin>>x>>y>>ch;
		x++, y++;
		while(x > k2) x -= k2;
		while(y > k2) y -= k2;
		if(ch == 'W')
			warr[x][y]++;
		else 
			barr[x][y]++;
	}
	repn(i, 1, k2)
	{
		repn(j, 1, k2)
		{
			warr[i][j] += warr[i-1][j] + warr[i][j-1] - warr[i-1][j-1];
			barr[i][j] += barr[i-1][j] + barr[i][j-1] - barr[i-1][j-1];
		}
	}
	int ans = 0;

	repn(i, 1, k)
	{
		repn(j, 1, k)
		{
			int tans = 0;
			tans += getW(i, j, i+k-1, j+k-1);
			tans += getW(1, 1, i-1, j-1);
			tans += getW(i+k, j+k, k2, k2);
			tans += getW(i+k, 1, k2, j-1);
			tans += getW(1, j+k, i-1, k2);
			tans += getB(i, 1, i+k-1, j-1);
			tans += getB(i+k, j, k2, j+k-1);
			tans += getB(1, j, i-1, j+k-1);
			tans += getB(i, j+k, i+k-1, k2);

			ans = max(ans, tans);
			tans = 0;
			tans += getB(i, j, i+k-1, j+k-1);
			tans += getB(1, 1, i-1, j-1);
			tans += getB(i+k, j+k, k2, k2);
			tans += getB(i+k, 1, k2, j-1);
			tans += getB(1, j+k, i-1, k2);
			tans += getW(i, 1, i+k-1, j-1);
			tans += getW(i+k, j, k2, j+k-1);
			tans += getW(1, j, i-1, j+k-1);
			tans += getW(i, j+k, i+k-1, k2);
			ans = max(ans, tans);
		}
	}
	cout<<ans<<endl;
}

