using namespace std;

typedef long long ll;
typedef pair<int, int> P;

int N, K;
int cum_sum[2001][2001];

int add(int x, int y, int d){
	x += 1;
	y += 1;
	cum_sum[y][x] += d;
}

void build(void){
	for (int i = 1; i <= 2*K; ++i){
		for (int j = 1; j <= 2*K; ++j){
			cum_sum[i][j] += cum_sum[i][j-1] + cum_sum[i-1][j] - cum_sum[i-1][j-1];
		} // end for
	} // end for
}

int count(int left, int right, int top, int bottom){
	int res = 0;
	res += cum_sum[bottom][right];
	res -= cum_sum[bottom][left];
	res -= cum_sum[top][right];
	res += cum_sum[top][left];
	return res;
}

int main()
{
	memset(cum_sum, 0, sizeof(cum_sum));
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	cin >> N >> K;
	for (int i = 0; i < N; ++i){
		int x, y; char c;
		cin >> x >> y >> c;
		if (c == 'W'){
			add(x % (2*K), (y + K) % (2*K), 1);
		}else{
			add(x % (2*K), y % (2*K), 1);
		} // end if
	} // end for

	build();
	int res = 0;
	for (int y = 0; y < K; ++y){
		for (int x = 0; x < K; ++x){
			int curr = 0;
			curr += count(0, x, 0, y);
			curr += count(0, x, y + K, 2*K);
			curr += count(x, x + K, y, y + K);
			curr += count(x + K, 2*K, 0, y);
			curr += count(x + K, 2*K, y + K, 2*K);
			res = max(res, curr);
			res = max(res, N - curr);
		} // end for
	} // end for

	cout << res << endl;

	return 0;
}

