        char c;
        cin >> c;
        if (c == 'W') y += k;
        x %= 2*k, y %= 2*k;
        acc[x+1][y+1]++;
    }

    for (int i = 0; i + 1 <= 2*k; i++) {
        for (int j = 0; j + 1 <= 2*k; j++) {
            acc[i+1][j+1] += acc[i][j+1] + acc[i+1][j] - acc[i][j];
        }
    }

    int ans = 0;
    vector<pair<int, int>> v = { { 0, 0 }, { -k, -k }, { -k, k }, { k, k }, { k, -k } };
    for (int i = 0; i <= k; i++) {
