		int x, y;
		char c;
		cin >> x >> y >> c;
		x %= 2 * k;
		y %= 2 * k;
		if (c == 'B')b[y + 1][x + 1]++;
		else w[y + 1][x + 1]++;
	}
	REP(i, 2 * k) {
		REP(j, 2 * k + 1) {
			b[i + 1][j] += b[i][j];
			w[i + 1][j] += w[i][j];
		}
	}
	REP(i, 2 * k + 1) {
		REP(j, 2 * k) {
			b[i][j + 1] += b[i][j];
			w[i][j + 1] += w[i][j];
		}
	}
	int ans = 0;
	REP(i, k) {
		REP(j, k) {
			int cntb, cntw;
			cntw = f(0, 0, i, j, w) + f(i, j, i + k, j + k, w) + f(0, j + k, i, 2 * k, w) + f(i + k, 0, 2 * k, i, w) + f(i + k, j + k, 2 * k, 2 * k, w);
			cntb = f(0, j, i, j + k, b) + f(i, 0, i + k, j, b) + f(i, j + k, i + k, 2 * k, b) + f(i + k, j, 2 * k, j + k, b);
			ans = max(ans, cntb + cntw);
			cntb = f(0, 0, i, j, b) + f(i, j, i + k, j + k, b) + f(0, j + k, i, 2 * k, b) + f(i + k, 0, 2 * k, i, b) + f(i + k, j + k, 2 * k, 2 * k, b);
			cntw = f(0, j, i, j + k, w) + f(i, 0, i + k, j, w) + f(i, j + k, i + k, 2 * k, w) + f(i + k, j, 2 * k, j + k, w);
			ans = max(ans, cntb + cntw);
		}
	}
