int OK[1001][1001], NG[1001][1001];

int main() {
  int N, K;
  cin >> N >> K;

  auto res = 0;

  for(auto i = 0; i < N; ++i) {
    int x, y; char c1;
    cin >> x >> y >> c1;
    x %= 2*K;
    y %= 2*K;
    auto c = (c1=='B') ? 0 : 1;
    for(auto j = 0; j < K; ++j) {
      auto f = 0;
      if(y < K || K <= y)   f ^= 1;
      auto t = f;
      if(x < j || j+K <= x) t ^= 1;
      if(t == c) ++OK[f][j], ++NG[f][j];
      else       ++NG[f][j], ++OK[f][j];
      res = max({res, OK[0][j], OK[1][j], NG[0][j], NG[1][j]});
    }
  }

  cout << res << endl;
}

