using vpr = vector<pr>;
using P = pair<int, int>;
template<class T> inline bool chmin(T& a, const T& b) { if (a > b) { a = b; return true; } else return false; }
template<class T> inline bool chmax(T& a, const T& b) { if (a < b) { a = b; return true; } else return false; }

// clang-format on
const int MX = 1010;
void answer() {
  int n, k;
  cin >> n >> k;
  vector<vector<int> > b(k + 1, vector<int>(2 * k + 1, 0));
  vector<vector<int> > w(k + 1, vector<int>(2 * k + 1, 0));
  rep(i, n) {
    int x, y;
    char c;
    cin >> x >> y >> c;
    int xd = 0;
    if (((x / k) + (y / k)) % 2) xd = k;
    if (c == 'B') {
      b[y % k + 1][x % k + xd + 1] = 1;
    } else {
      w[y % k + 1][x % k + xd + 1] = 1;
    }
  }
  rep(i, k) rep(j, 2 * k) {
    b[i + 1][j + 1] += b[i][j + 1] + b[i + 1][j] - b[i][j];
    w[i + 1][j + 1] += w[i][j + 1] + w[i + 1][j] - w[i][j];
  }
  int ans = 0;
  auto sum = [&](const vector<vector<int> >& v, int ni, int nj) {
    int mi = ni - k, mj = nj - k;
    chmin(ni, k);
    chmin(nj, 2 * k);
    chmax(mi, 0);
    chmax(mj, 0);
    return v[ni][nj] - v[ni][mj] - v[mi][nj] + v[mi][mj];
  };
  repc(i, k) repc(j, k) {
    int now = 0;
    now += sum(w, i, j);
    now += sum(w, i, j + k + k);
    now += sum(w, i + k, j + k);
    now += sum(b, i, j + k);
    now += sum(b, i + k, j);
    now += sum(b, i + k, j + k + k);
    chmax(ans, now);
  }
  cout << ans << '\n';
}
int main() {
  std::ios::sync_with_stdio(false);
  std::cin.tie(0);
  answer();
  return 0;
}

