void add(int x, int y, char c)
{
    int tx = x % k;
    int ty = y % k;
    int cx = x % (2 * k);
    int cy = y % (2 * k);

    char ini;
    if ((IN(0, k, cy) && IN(0, k, cx)) || (IN(k, 2 * k, cy) && IN(k, 2 * k, cx)))
    {
        ini = 'W';
    }
    else
    {
        ini = 'B';
    }

    if (ini == c)
    {
        ++s[ty + 1][tx + 1];
        ++s[ty + k + 1][tx + k + 1];
    }
    else
    {
        ++s[ty + k + 1][tx + 1];
        ++s[ty + 1][tx + k + 1];
    }
}

