i64 calc(int i1, int j1, int i2, int j2, bool black) {
  // cerr << i1 << " " << j1 << " " << i2 << " " << j2 << " -> ";
  if (black) {
    i64 ret = b[i2][j2] - b[i1][j2] - b[i2][j1] + b[i1][j1];
    // cerr << ret << endl;
    return ret;
  } else {
    i64 ret = w[i2][j2] - w[i1][j2] - w[i2][j1] + w[i1][j1];
    // cerr << ret << endl;
    return ret;
  }
}

i64 calcs(int i, int j, int k, bool black) {
  // cerr << "=" << endl;
  i32 i1 = i, j1 = j;
  i32 i2 = i + k, j2 = j + k;
  i32 k2 = 2 * k;
  i64 sum = 0;

  sum += calc(0, 0, i1, j1, black);
  sum += calc(i1, j1, i2, j2, black);
  sum += calc(i2, j2, k2, k2, black);
  sum += calc(0, j2, i1, k2, black);
  sum += calc(i2, 0, k2, j1, black);

  sum += calc(0, j1, i1, j2, !black);
  sum += calc(i2, 0, k2, j1, !black);
  sum += calc(i1, j2, i2, k2, !black);
  sum += calc(i2, j1, k2, j2, !black);

  return sum;
}

