    // x を x % 2K 、
    // y を y % 2K で考えていい
    x[i] %= KK;
    y[i] %= KK;
    if (c[i] == 'B') {
      black[i] = true;
    } else {
      black[i] = false;
    }
    if (K <= x[i]) {
      x[i] -= K;
      black[i] = !black[i];
    }
    if (K <= y[i]) {
      y[i] -= K;
      black[i] = !black[i];
    }  
    // 二次元累積和
    if (black[i]) {
      table[0][0]++;
      table[0][y[i] + 1]--;
      table[x[i] + 1][0]--;
      table[x[i] + 1][y[i] + 1] += 2;
    } else {
      table[0][y[i] + 1]++;
      table[x[i] + 1][0]++;
      table[x[i] + 1][y[i] + 1] -= 2;
    }
  }

  for (int i = 0; i < K; i++) {
    for (int j = 1; j < K; j++) {
      table[i][j] += table[i][j - 1];
    }
  }

  for (int i = 0; i < K; i++) {
    for (int j = 1; j < K; j++) {
      table[j][i] += table[j - 1][i];
    }
  }

  int answer = 0;

  for (int i = 0; i < K; i++) {
    for (int j = 0; j < K; j++) {
      table[i][j] = max(table[i][j], N - table[i][j]);
      answer = max(answer, table[i][j]);
    }
  }

  cout << answer << endl;

  return 0;

}

