int main(){
    ii(n); lint k; cin >> k;
    rep(i, n){
        lint x, y; cin >> x >> y; char c; cin >> c;
        if(c == 'B'){
            x %= 2*k; y %= 2*k;
        }
        else{
            x = (x+k)%(2*k); y %= 2*k;
        }
        if(x >= k && y < k){
            x -= k; y += k;
        }
        else if(x >= k && y >= k){
            x -= k; y -= k;
        }
        if(y < k){
            add(P(0,0),P(x,y));
            add(P(x+1, y+1), P(x+k, y+k));
            add(P(0, y+k+1), P(x, 2*k-1));
            add(P(x+k+1, 0), P(2*k-1, y));
            add(P(x+k+1, y+k+1), P(2*k-1, 2*k-1));
        }else{
            add(P(0, y-k+1), P(x, y));
            add(P(x+k+1, y-k+1), P(2*k-1, y));
            add(P(x+1, y+1), P(x+k, 2*k-1));
            add(P(x+1, 0), P(x+k, y-k));
        }
    }
    int res = 0;
    rep(i, 2*k) rep(j, 2*k){
        if(i == 0 && j == 0) continue;
        if(i == 0){
            sum[0][j] += sum[0][j-1]; continue;
        }
        if(j == 0){
            sum[i][0] += sum[i-1][0]; continue;
        }
        sum[i][j] += sum[i-1][j] + sum[i][j-1] - sum[i-1][j-1];
        res = max(res, sum[i][j]);
    }
    out(res);
}

