int main(){
    int n,k;
    cin>>n>>k;

    vector<vector<int>> B(2001,vector<int>(2001,0));
    vector<vector<int>> W(2001,vector<int>(2001,0));

    int h = 2*k;
    int w = 2*k;
    rep(i,n){
        int x,y;
        char ch;
        cin>>x>>y>>ch;

        if(ch=='B'){
            B[y%h][x%w] += 1;
        }else{
            W[y%h][x%w] += 1;
        }
    }


    auto f = [&](const vector<vector<int>> &v){
        vector<vector<int>> dp(h,vector<int>(w,0));
        rep(i,h){
            rep(j,w){
                if(i-1>=0)dp[i][j] += dp[i-1][j];
                if(j-1>=0)dp[i][j] += dp[i][j-1];
                if(i-1>=0&&j-1>=0)dp[i][j] -= dp[i-1][j-1];
                dp[i][j] += v[i][j];
            }
        }

        return dp;
    };


    vector<vector<int>> bb = f(B);
    vector<vector<int>> ww = f(W);

    auto g = [&](int y,int x,int yy,int xx, vector<vector<int>> &dp){
        if(yy-1<0||xx-1<0)return 0;
        xx = min(xx,w);
        yy = min(yy,h);
        x = max(0,min(x,w));
        y = max(0,min(y,h));
        int ret = dp[yy-1][xx-1];
        if(y-1>=0)ret-=dp[y-1][xx-1];
        if(x-1>=0)ret-=dp[yy-1][x-1];
        if(y-1>=0&&x-1>=0)ret+=dp[y-1][x-1];

        return ret;
    };

    int maxi = 0;
    rep(i,k){
        rep(j,k){
            int sum1 = 0, sum2 = 0;

            sum1 += g(0,0,i,j,bb) + g(0,j+k,i,w,bb) + g(i+k,0,h,j,bb) + g(i,j,i+k,j+k,bb) + g(i+k,j+k,h,w,bb);
            sum1 += g(0,j,i,j+k,ww) + g(i,0,i+k,j,ww) + g(i,j+k,i+k,w,ww) + g(i+k,j,h,j+k,ww);

            sum2 += g(0,0,i,j,ww) + g(0,j+k,i,w,ww) + g(i+k,0,h,j,ww) + g(i,j,i+k,j+k,ww) + g(i+k,j+k,h,w,ww);
            sum2 += g(0,j,i,j+k,bb) + g(i,0,i+k,j,bb) + g(i,j+k,i+k,w,bb) + g(i+k,j,h,j+k,bb);
            maxi = max(maxi,max(sum1,sum2));
        }
    }
    cout<<maxi<<endl;

}

