int sum[2001][2001];
int solve(int i, int j) {
    if(i >= 0 && j >= 0)
        return sum[i][j];
    else 
        return 0;
}

int main()
{
    int N, K;
    scanf("%d %d", &N, &K);
    int X[N+3], Y[N+3], C[N+3];
    char d;
    for(int i = 0; i < N; ++i) { 
        scanf("%d %d %c", &X[i], &Y[i], &d);
        C[i] = ((d == 'B') ? 1 : 0);
        if(C[i] == 0) {
            Y[i] += K; C[i] = 1;
        }
        X[i] %= 2*K, Y[i] %= 2*K;
    }

    for(int i = 0; i < N; ++i) sum[X[i]][Y[i]]++;


    for(int i = 0; i < 2*K; ++i) {
        for(int j = 0; j < 2*K; ++j) {
            //(0, 0)と(i, j)を頂点とする長方形内の黒点の数を累積和で求める
            if(i == 0 && j == 0) continue;

            if(i == 0) {
                sum[i][j] += sum[i][j-1];
                continue;
            } else if(j == 0) {
                sum[i][j] += sum[i-1][j];
                continue;
            } else {
                sum[i][j] += sum[i-1][j] + sum[i][j-1] - sum[i-1][j-1];
            }
        }
    }


    int ma = -1;
    for(int i = 0; i < K; ++i) {
        for(int j = 0; j < K; ++j) {
            int cnt = 0;
            cnt += solve(K-1+j, K-1+i) 
                    - solve(j-1, K-1+i) 
                    - solve(K-1+j, i-1) 
                    + solve(j-1, i-1);
            cnt += solve(2*K-1, 2*K-1)
                    - solve(K-1+j, 2*K-1)
                    - solve(2*K-1, K-1+i)
                    + solve(K-1+j, K-1+i);
            cnt += solve(j-1, i-1);
            cnt += solve(2*K-1, i-1) - solve(K-1+j, i-1);
            cnt += solve(j-1, 2*K-1) - solve(j-1, K-1+i);
            ma = max(ma, max(cnt, N - cnt));
            //全体の白黒を反転させれば、K<= j < 2K, K <= i < 2Kの場合の市松模様になり、
            //N - cntで求めることができる。
        }
    }

    cout << ma << endl;
    return 0;
}

