using namespace std;

int N;
int k;
int ssum[2001][2001];
int mmap[2000][2000];

int cot(int x1, int y1, int x2, int y2) {
	return ssum[x2+1][y2+1] - ssum[x1][y2+1] - ssum[x2+1][y1] + ssum[x1][y1];
}

int co(int x1, int y1, int x2, int y2) {
	if (x1 < x2 && y1 < y2) {
		return cot(x1, y1, x2, y2);
	} else if (x1 < x2) {
		return cot(x1, y1, x2, k) + cot(x1, 0, x2, y2);
	} else if (y1 < y2) {
		return cot(x1, y1, k, y2) + cot(0, y1, x2, y2);
	} else {
		return cot(x1, y1, k, k) + cot(0, 0, x2, y2);
	}
	return 0;
}

int main()
{
	cin >> N >> k;
	for (int i = 0; i < N; i++) {
		int a, b;
		char c;
		cin >> a >> b >> c;
		if (c == 'W') {
			a += k;
		}
		a = a % (2 * k);
		b = b % (2 * k);
		mmap[a][b]++;
	}
	for (int i = 1; i < 2 * k + 1; i++) {
		for (int j = 1; j < 2 * k + 1; j++) {
			ssum[i][j] = mmap[i-1][j-1] + ssum[i-1][j] + ssum[i][j-1] - ssum[i-1][j-1];
		}
	}
	int ma = 0;
	for (int i = 0; i < 2 * k; i++) {
		for (int j = 0; j < 2 * k; j++) {
			int x1 = i;
			int y1 = j;
			int x2 = (i + k - 1) % (2 * k);
			int y2 = (j + k - 1) % (2 * k);
			int x3 = (i + k) % (2 * k);
			int y3 = (j + k) % (2 * k);
			int x4 = (i + 2 * k - 1) % (2 * k);
			int y4 = (j + 2 * k - 1) % (2 * k);
			int t = co(x1, y1, x2, y2) + co(x3, y3, x4, y4);
			ma = max(ma, t);
		}
	}
	cout << ma << endl;
}

