int v[2001][2001];
int n,k;
int num(int x1,int y1,int x2,int y2){
    return v[x2][y2] - v[x2][y1] - v[x1][y2] + v[x1][y1];///前缀和 减去左边 下边和左下边的k宫格前缀和  容斥定理：左边和下边都包含了左下边 需要加上一个左下边
}
int main()
{
    int x,y;
    char ch;
    scanf("%d%d",&n,&k);
    for(int i = 1;i <= n;i ++){
        scanf("%d%d %c",&x,&y,&ch);
        x %= 2 * k;///把所有点都移动到 2k * 2k 的区域
        y %= 2 * k;
        x += k * (x == 'W');///x可以变成y W 也可以变成 B 这里白色都变成黑色的 如果转换后的黑色是满足的那么原来的白色也一定是满足的
        v[x % (2 * k) + 1][y % (2 * k) + 1] ++;///求前缀和要求从（1,1）开始
    }
    for(int i = 1;i <= 2 * k;i ++)///求前缀和
        for(int j = 1;j <= 2 * k;j ++)
            v[i][j] += v[i - 1][j] + v[i][j - 1] - v[i - 1][j - 1];///加上左边下边和左下角的和  容斥定理：左边和下边的都包含了左下边的  要减去一个左下边的
    int ans = 0,sum;
    for(int i = 1;i <= k;i++)///k * k个格子依次做为起点构成新的k宫格 也就是移动k宫格 看看有几个黑色点包含在内 （默认黑色 可互换）
        for(int j = 1;j <= k;j++)
        {
            ///斜对角的k宫格是相同颜色 2k * 2k区域最多有五个这样的区域
            sum = num(0,0,i,j) + num(i,j,k + i,k + j) + num(k + i,k + j,2 * k,2 * k) + num(k + i,0,2 * k,j) + num(0,k + j,i,2 * k);
            ans = max(ans,max(sum,n - sum));///黑白色可以互换
        }
    printf("%d\n",ans);
}

