int main()
{
    int N, K;
    cin >> N >> K;
    int D = K*2;
    vector<int> area(D*D);
    for (int i = 0; i < N; i++) {
        int x, y;
        char c;
        cin >> x >> y >> c;
        if (c == 'B') {
            area[D*(y%D)+(x%D)]++;
        } else {
            area[D*(y%D)+((x+3)%D)]++;
        }
    }
    vector<int> sum(2*D*2*D);
    auto sumget = [&](int x, int y) {
        if (x < 0 || y < 0) return 0;
        return sum[2*D*y+x];
    };
    auto sumset = [&](int x, int y, int val) {
        sum[2*D*y+x] = val;
    };
    auto sumarea = [&](int x1, int y1, int x2, int y2) {
        return sumget(x2, y2) - sumget(x1-1, y2) - sumget(x2, y1-1) + sumget(x1-1, y1-1);
    };
    for (int y = 0; y < 2*D; y++) {
        for (int x = 0; x < 2*D; x++) {
            sumset(x, y, sumget(x-1, y) + sumget(x, y-1) - sumget(x-1, y-1) + area[D*(y%D)+(x%D)]);
        }
    }
    int maxscore = 0;
    for (int y = 0; y < K; y++) {
        for (int x = 0; x < D; x++) {
            int score = sumarea(x, y, x+K-1, y+K-1) + sumarea(x+K, y+K, x+2*K-1, y+2*K-1);
            maxscore = max(maxscore, score);
        }
    }
    cout << maxscore << endl;
    return 0;
}

