ll solve(){
  ll ans = 1, now[2];
  rep(i,k)rep(j,k)rep(l,2){
    now[l] = memo[l][i][j];
    if(i != k-1 && j != k-1){
      now[l] += memo[l][k-1][k-1];
      now[l] -= memo[l][i][k-1];
      now[l] -= memo[l][k-1][j];
      now[l] += memo[l][i][j];
    }
    now[l] += memo[1-l][k-1][j] - memo[1-l][i][j];
    now[l] += memo[1-l][i][k-1] - memo[1-l][i][j];
    ans = max(ans, now[l]);
