    }
  }

  int d[2*k][2*k] = {};
  REP(i,n){
    d[x[i]][y[i]] += 1;
  }
  int dsum[2*k][2*k];
  REP(i,2*k){
    REP(j,2*k){
      if(i==0 && j==0){
        dsum[i][j] = d[i][j];
      }else if(i==0){
        dsum[i][j] = dsum[i][j-1] + d[i][j];
      }else if(j==0){
        dsum[i][j] = dsum[i-1][j] + d[i][j];
      }else{
        dsum[i][j] = dsum[i-1][j] + dsum[i][j-1] - dsum[i-1][j-1] + d[i][j];
      }
    }
  }

  int ans = 0;
  REP(i,k){
    REP(j,k){//黒を塗る場所の左上を一つ固定する
      int temp = 0;
      if(i==0 && j==0){
        temp += dsum[i+k-1][j+k-1];
      }else if(i==0){
        temp += dsum[i+k-1][j+k-1] - dsum[i+k-1][j-1];
      }else if(j==0){
