int query(int x1, int y1, int x2, int y2) {
    if (x1 > x2 || y1 > y2) return 0;
    return sum[x2][y2] - sum[x1 - 1][y2] - sum[x2][y1 - 1] + sum[x1 - 1][y1 - 1];
}

int main() {
    int n, k;
    cin >> n >> k;
    rep(i, n) {
        int x, y;
        char c;
        cin >> x >> y >> c;
        if (c == 'W') {
            y += k;
        }
        x %= 2 * k;
        y %= 2 * k;
        sum[x + 1][y + 1]++;
    }
    rep(i, 2 * k + 1) {
        rep(j, 2 * k) {
            sum[i][j + 1] += sum[i][j];
        }
    }
    rep(j, 2 * k + 1) {
        rep(i, 2 * k) {
            sum[i + 1][j] += sum[i][j];
        }
    }
    int ans = 0;
    rep(i, k + 1) {
        rep(j, k + 1) {
            // x o o o x x
            // x o o o x x
            // o x x x o o
            // o x x x o o
            // o x x x o o
            // x o o o x x
            int score = 0;
            score += query(1, 1, i, j);
            score += query(i + 1, j + 1, i + k, j + k);
            score += query(i + k + 1, j + k + 1, k * 2, k * 2);
            score += query(i + k + 1, 1, k * 2, j);
            score += query(1, j + k + 1, i, k * 2);
            ans = max(ans, score);
            ans = max(ans, n - score);
        }
    }
    cout << ans << endl;
}

