		}

		order.c = "W";
		order.x += K;
	}

	//for (auto order : orderList) {
	//	cout << order.x << " " << order.y << " " << order.c << endl;
	//}
	//cout << endl;

	//Wをまとめる
	for (auto& order : orderList) {
		//if ((order.x / K) % 2 == 0) {
		//	order.x = order.x % K;
		//}
		//else {
		//	order.x = order.x % K + K;
		//}

		//if ((order.y / K) % 2 == 0) {
		//	order.y = order.y % K;
		//}
		//else {
		//	order.y = order.y % K + K;
		//}

		order.x %= 2 * K;
		order.y %= 2 * K;
	}

	//for (auto order : orderList) {
	//	cout << order.x << " " << order.y << " " << order.c << endl;
	//}
	//cout << endl;

	//各パターンがいくつあるかをカウント
	map<Order, ULL> orderCounter;
	for (const auto& order : orderList) {
		orderCounter[order] = (orderCounter.count(order) == 0) ? 1 : ++orderCounter[order];
	}

	//for (const auto& count : orderCounter) {
	//	cout << count.first.x << " " << count.first.y << " " << count.second << endl;
	//}
	//cout << endl;

	//最大の個数になるパターンを調べる
	ULL maxCount = 0;
	//#TODO -K~ KにしてもWA
	for (int x = -K; x < K; x++) {
		for (int y = -K; y < K; y++) {

			ULL countSum = 0;

			for (const auto& orderAndCount : orderCounter) {
				const auto& order = orderAndCount.first;
				auto count = orderAndCount.second;

				if (IsIncludeClose((int)order.x, x, x + K - 1) && IsIncludeClose((int)order.y, y, y + K - 1)) {
					countSum += count;
				}
				else if (IsIncludeClose((int)order.x, x + K, x + K * 2 - 1) && IsIncludeClose((int)order.y, y + K, y + K * 2 - 1)) {
					countSum += count;
				}
				else if (IsIncludeClose((int)order.x, x + K, x + K * 2 - 1) && IsIncludeClose((int)order.y, y - K, y - 1)) {
					countSum += count;
				}
				else if (IsIncludeClose((int)order.x, x - K, x - 1) && IsIncludeClose((int)order.y, y + K, y + K * 2 - 1)) {
					countSum += count;
				}
				else if (IsIncludeClose((int)order.x, x - K, x - 1) && IsIncludeClose((int)order.y, y - K, y - 1)) {
					countSum += count;
				}
				else if (IsIncludeClose((int)order.x, x + 2 * K, x + K * 3 - 1) && IsIncludeClose((int)order.y, y, y + K - 1)) {
					countSum += count;
				}
				else if (IsIncludeClose((int)order.x, x, x + K - 1) && IsIncludeClose((int)order.y, y + 2 * K, y + 3 * K - 1)) {
					countSum += count;
				}
			}

			maxCount = max(maxCount, countSum);
		}
	}

	cout << maxCount;

	return 0;
}

