using namespace std;

int main() {
  ios::sync_with_stdio(false);
  int n, k;
  cin >> n >> k;
  int kk = 2*k;
  vector<vector<int>> l(2*kk, vector<int>(k, 0));
  for(int i = 0; i < n; i+=1) {
    int x, y;
    char ch;
    cin >> x >> y >> ch;
    if(ch == 'B') {
      x += k;
    }
    x %= kk;
    y %= kk;
    if(y >= k) {
      y -= k;
      if(x >= k) {
        x -= k;
      } else {
        x += k;
      }
    }
    l[x][y] += 1;
    l[x+kk][y] += 1;
  }
  vector<vector<int>> syl(2*kk, vector<int>(k,0));
  for(int i = 0; i < kk; i+=1) {
    for(int j = 0; j < k; j+=1) {
      syl[i][0] += l[i][j];
    }
    syl[i+kk][0] = syl[i][0];
    for(int j = 0; j < k-1; j+=1) {
      syl[i][j+1] = syl[i][j] - l[i][j] + l[i+k][j];
      syl[i+kk][j+1] = syl[i][j+1];
    }
  }
  int m = 0;
  for(int j = 0; j < k; j+=1) {
    int s = 0;
    for(int i = 0; i < k; i+=1) {
      s += syl[i][j];
    }
    if(m<s) {
      m = s;
    }
    for(int i = 0; i < kk-1; i+=1) {
      s = s - syl[i][j] + syl[i+k][j];
      if(m<s) {
        m = s;
      }
    }
  }
  cout << m << endl;
  return 0;
}

#include <iostream>

class Check {
    uint32_t **m;
    uint32_t k;
    std::string c;
public:
    Check(uint32_t k, const std::string &c) {
        this->c = c;
        this->k = k;
        this->m = new uint32_t *[k + 1];
        for (uint32_t i = 0; i < this->k + 1; ++i) {
            this->m[i] = new uint32_t[k + 1]();
        }
    }

    void inc(uint32_t xMin, uint32_t xMax, uint32_t yMin, uint32_t yMax) {
        for (uint32_t i = xMin; i < xMax; ++i) {
            for (uint32_t j = yMin; j < yMax; ++j) {
                this->m[i][j]++;
            }
        }
    }

    void addDesire(uint32_t x, uint32_t y, const std::string &c) {
        uint32_t cx = x + 1;
        uint32_t cy = y + 1;

        if (c == this->c) {
            this->inc(0, cx, 0, cy);
            this->inc(cx, this->k + 1, cy, this->k + 1);
        } else {
            this->inc(0, cx, cy, this->k + 1);
            this->inc(cx, this->k + 1, 0, cy);
        }
    }

    uint32_t getMax() {
        uint32_t _max = 0;
        for (uint32_t i = 0; i < this->k + 1; ++i) {
            for (uint32_t j = 0; j < this->k + 1; ++j) {
                if (this->m[i][j] > _max) {
                    _max = this->m[i][j];
                }
            }
        }

        return _max;
    }

    ~Check() {
        for (uint32_t i = 0; i < this->k + 1; ++i) {
            delete[](this->m[i]);
        }
        delete[](this->m);
    }
};

int main() {
    uint32_t n, k;
    std::cin >> n >> k;
    Check checkW = Check(k, "W");

    for (uint32_t i = 0; i < n; ++i) {
        uint32_t x, y;
        std::string c;
        std::cin >> x >> y >> c;

        x = x < 0 ? -1 * x + k - 1 : x;
        y = y < 0 ? -1 * y + k - 1 : y;

        uint32_t bigX = x / k;
        uint32_t bigY = y / k;

        uint32_t localX = x % k;
        uint32_t localY = y % k;
        std::string localC = c;

        if ((bigX + bigY) % 2 != 0) {
            localC = localC == "W" ? "B" : "W";
        }

        checkW.addDesire(localX, localY, localC);
    }

    std::cout << checkW.getMax() << std::endl;

    return 0;
}

