#define FOR(i, a, b) for (int i = a; i < b; ++i)
#define RFOR(i, a, b) for (int i = a; i > b; --i)
#define REP(i, n) for (int i = 0; i < n; ++i)

const int kMaxN = 100000;
const int kMaxK = 1000;

int N, K;
int x[kMaxN], y[kMaxN];
char c[kMaxN];
int ans = 0;

int grid[2*kMaxK+1][2*kMaxK+1];

int main() {
  cin >> N >> K;
  REP(i, N) { cin >> x[i] >> y[i] >> c[i]; }

  REP(i, N) {
    if (c[i] == 'W') { x[i] += K; }
    x[i] %= 2*K;
    y[i] %= 2*K;
  }

  REP(i, N) {
    if (x[i] >= K && y[i] >= K) {
      x[i] -= K;
      y[i] -= K;
    }
    if (x[i] < K && y[i] < K) {
      grid[0][0] += 1;
      grid[x[i]+1][0] -= 1;
      grid[x[i]+1+K][0] += 1;
      grid[0][y[i]+1] -= 1;
      grid[x[i]+1][y[i]+1] += 2;
      grid[x[i]+1+K][y[i]+1] -= 2;
      grid[0][y[i]+1+K] += 1;
      grid[x[i]+1][y[i]+1+K] -= 2;
      grid[x[i]+1+K][y[i]+1+K] += 2;
    }
    if (x[i] < K && y[i] >= K) {
      x[i] += K;
      y[i] -= K;
    }
    if (x[i] >= K && y[i] < K) {
      grid[x[i]-K+1][0] += 1;
      grid[x[i]+1][0] -= 1;
      grid[0][y[i]+1] += 1;
      grid[x[i]-K+1][y[i]+1] -= 2;
      grid[x[i]+1][y[i]+1] += 2;
      grid[0][y[i]+K+1] -= 1;
      grid[x[i]-K+1][y[i]+K+1] += 2;
      grid[x[i]+1][y[i]+K+1] -= 2;
    }
  }
  REP(j, 2*K+1) { FOR(i, 1, 2*K+1) { grid[i][j] += grid[i-1][j]; } }
  REP(i, 2*K+1) { FOR(j, 1, 2*K+1) { grid[i][j] += grid[i][j-1]; } }
  REP(i, 2*K) { REP(j, 2*K) { ans = max(ans, grid[i][j]); } }

  cout << ans << endl;
  return 0;
}

