			int x_ = x % K, y_ = y % K;

			imos(0, 0, x_ + 1, y_ + 1);
			imos(x_ + K + 1, 0, 2 * K, y_ + 1);

			imos(0, y_ + K + 1, x_ + 1, 2 * K);
			imos(x_ + K + 1, y_ + K + 1, 2 * K, 2 * K);

			imos(x_ + 1, y_ + 1, x_ + K + 1, y_ + K + 1);
		}
		else {
			int x_ = x % K, y_ = y % K;

			imos(x_ + 1, 0, x_ + K + 1, y_ + 1);
