		}
	}

	REP(i, 2001) {
		REP(j, 2001) {
			memo[i][j] += memo[i - 1][j];
		}
	}

	int max = 0;
	REP(i, 2 * K) {
		REP(j, 2 * K) {
			max = std::max(max, memo[i][j]);
		}
	}

	cout << max << endl;
	return 0;
}

