  }

  for (i = 1; i < N; ++i)
    for (j = 1; j < N; ++j)
      a[i][j] += a[i - 1][j] + a[i][j - 1] - a[i - 1][j - 1];

  for (i = k; i <= 2 * k; ++i)
    for (j = k; j <= 2 * k; ++j) {
