#include <boost/multi_array.hpp>

int main() {
	int N, K;
	int x, y;
	std::string col;
	int num, ans;


	std::cin >> N >> K;

	boost::multi_array<int, 2> data(boost::extents[N][2]);


	//入力
	for(int i = 0; i < N; i++) {
		std::cin >> x >> y >> col;
		//白ならxにKを加えて黒にする
		if (col == "W") {
			x += K;
		}
		//2Kでmodを取る
		x = x % (2*K);
		y = y % (2*K);

		//yがK以上なら、xに+K,yに-Kで下半分の同色に写す
		if (y >= K) {
			x = (x + K) % (2*K);
			y = y - K;
		}

		//下半分の同じ色に移した点を保存する
		data[i][0] = x;
		data[i][1] = y;
	}
	/*
	ここまでで、下半分に固まっているので、希望を最大化する黒の範囲では、
	0-2K, 0-Kの範囲で黒の左下はy=0にくると思いきや斜めの関係がある場合これではだめ
	したがって左下のxをforで回し、各点を判定すればO(NK)でいける
	*/

    ans = 0;
	for (int a = 0; a < 2*K; a++) {
		for (int b = 0; b < K; b++) {
		    num = 0;
		    for (int i = 0; i < N; i++) {
		    	if (((data[i][0] - a + 2*K) % (2*K) < K && (data[i][1] - b + 2*K) % (2*K) < K) ||
		    	 ((data[i][0] - a + 2*K) % (2*K) >= K && (data[i][1] - b + 2*K) % (2*K) >= K)){
		    		num += 1;
			    }
		    }
		    if (num > ans) {
			    ans = num;
			    if (num == N) {
				    break;
			    }
			}
		}
	}
	//答えの出力
	std::cout << ans << std::endl;

	return 0;
}

