    for (int i = 0; i < N; i++) {
        int x, y;
        char c;
        cin >> x >> y >> c;
        x %= 2 * K, y %= 2 * K;
        if (c == 'B') {
            cB[y][x]++;
            cB[y + 2 * K][x]++;
            cB[y][x + 2 * K]++;
            cB[y + 2 * K][x + 2 * K]++;
        } else {
            cW[y][x]++;
            cW[y + 2 * K][x]++;
            cW[y][x + 2 * K]++;
            cW[y + 2 * K][x + 2 * K]++;
        }
    }
    for (int i = 0; i < 4 * K; i++) {
        for (int j = 0; j < 4 * K; j++) {
            if (i && j) {
                sB[i][j] = sB[i - 1][j] + sB[i][j - 1] - sB[i - 1][j - 1] + cB[i][j];
                sW[i][j] = sW[i - 1][j] + sW[i][j - 1] - sW[i - 1][j - 1] + cW[i][j];
            } else if (i) {
                sB[i][j] = sB[i - 1][j] + cB[i][j];
                sW[i][j] = sW[i - 1][j] + cW[i][j];
            } else if (j) {
                sB[i][j] = sB[i][j - 1] + cB[i][j];
                sW[i][j] = sW[i][j - 1] + cW[i][j];
            } else {
                sB[0][0] = cB[0][0];
                sW[0][0] = cW[0][0];
            }
        }
    }
    auto cc = [&](int y, int x, int s[4000][4000]) {
        int res = s[y][x];
        if (y >= K) res -= s[y - K][x];
        if (x >= K) res -= s[y][x - K];
        if (y >= K && x >= K) res += s[y - K][x - K];
        return res;
    };
    int ans = 0;
    for (int i = 0; i < 2 * K; i++) {
        for (int j = 0; j < 2 * K; j++) {
            int cnt = 0;
            cnt += cc(i + K - 1, j + K - 1, sB) + cc(i + 2 * K - 1, j + 2 * K - 1, sB);
            cnt += cc(i + 2 * K - 1, j + K - 1, sW) + cc(i + K - 1, j + 2 * K - 1, sW);
            ans = max(ans, cnt);
        }
    }
    cout << ans << endl;
    return 0;
}

