}
//[x1, x2) × [y1, y2) の長方形区域の和
int get_sum(int x1, int x2, int y1, int y2) {
    return sum[y2][x2] - sum[y1][x2] - sum[y2][x1] + sum[y1][x1];
}

int main() {
