			x = x % K;
			y = y % K;
			Imos[x][0]++;
			Imos[x][y]--;
			Imos[x + K][0]--;
			Imos[x + K][y]++;
			Imos[0][y]++;
			Imos[0][y + K]--;
			Imos[x][y]--;
			Imos[x][y + K]++;
