			Imos[K * 2 - 1][y + K]++;
			Imos[x][y + K]++;
			Imos[x][K * 2 - 1]--;
			Imos[x + K][y + K]--;
			Imos[x + K][K * 2 - 1]++;
		}
	}
	Cum[0][0] = Imos[0][0];
	for (int i = 1; i < K * 2; i++) {
		Cum[0][i] = Cum[0][i - 1] + Imos[0][i];
