int N, K;
int acc[2010][2010];
int sum, white;


void makeAcc(){
	repe(i, 1, 2*K)
		repe(j, 1, 2*K) acc[i][j] += acc[i][j-1];
	repe(i, 1, 2*K)
		repe(j, 1, 2*K) acc[i][j] += acc[i-1][j];
}


int solve(){
	int ans = 0;
	repe(i, 0, K){
		repe(j, 0, K){
			int a = acc[i][j];
			int b = acc[i+K][j+K]-acc[i+K][j]-acc[i][j+K]+acc[i][j];
			int c = acc[2*K][j]-acc[i+K][j];
			int d = acc[i][2*K]-acc[i][j+K];
			int e = acc[2*K][2*K]-acc[2*K][j+K]-acc[i+K][2*K]+acc[i+K][j+K];
			int cnt = a+b+c+d+e;
			ans = max({ ans, cnt, sum-cnt });
		}
	}
	return ans+white;
}


