const int N = 1e5 + 5;
const int K = 2005;
int x[N], y[N];
int a[K][K], b[K][K];
int sum(int x1,int y1,int x2,int y2,int a[][K]){
	int ans = 0;
	x1--, y1--;
	ans += a[x2][y2];
	ans -= a[x1][y2];
	ans -= a[x2][y1];
	ans += a[x1][y1];
	return ans;
}
void solve(){
	int n, k;
	cin >> n >> k;
	fr(i, 1, n){
		cin >> x[i] >> y[i];
		char ch;
		cin >> ch;
		x[i] %= (2 * k), y[i] %= (2 * k);
		if(x[i] == 0) x[i] = 2 * k;
		if(y[i] == 0) y[i] = 2 * k;
		if(ch == 'B')
			a[x[i]][y[i]]++;
		else
			b[x[i]][y[i]]++;
	}
	fr(i, 1, 2 * k){
		fr(j, 1, 2 * k){
			a[i][j] += a[i - 1][j] + a[i][j - 1] - a[i - 1][j - 1];
			b[i][j] += b[i - 1][j] + b[i][j - 1] - b[i - 1][j - 1];
		}
	}
	int ans = 0;
	fr(i, 1, k){
		fr(j, 1, k){
			int val = 0;
			val += sum(1, 1, i, j, a);
			val += sum(1, j + 1, i, j + k, b);
			val += sum(1, j + k + 1, i, 2 * k, a);
			val += sum(i + 1, 1, k + i, j, b);
			val += sum(i + 1, j + 1, k + i, j + k, a);
			val += sum(i + 1, j + k + 1, k + i, 2 * k, b);
			val += sum(i + k + 1, 1, 2 * k, j, a);
			val += sum(i + k + 1, j + 1, 2 * k, j + k, b);
			val += sum(i + k + 1, j + k + 1, 2 * k, 2 * k, a);
			ans = max(ans, val);
			ans = max(ans, n - val);
		}
	}
	cout << ans;
}
