template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return true; } return false; }
template<class T> inline bool chmax(T& a, T b) { if (a < b) { a = b; return true; } return false; }


int main(){
    ll n,k; cin>>n>>k;
    vector<vector<ll>> cnt(4*k+1, vector<ll>(4*k+1,0));
    rep(i,n){
        ll x,y; char c; cin>>x>>y>>c;
        if(c=='W') x+=k;
        x%=(2*k); y%=(2*k);
        cnt[x+k+1][y+k+1]++;
        cnt[x+k+1][y+2*k+1]--;
        cnt[x+2*k+1][y+k+1]--;
        cnt[x+2*k+1][y+2*k+1]++;
    }

    rep(i, 4*k+1){
        rep(j, 4*k+1){
            if(j==0) continue;
            cnt[i][j]+=cnt[i][j-1];
        }
    }
    rep(i, 4*k+1){
        rep(j, 4*k+1){
            if(i==0) continue;
            cnt[i][j]+=cnt[i-1][j];
        }
    }
    for(ll i=2*k; i<4*k; i++){
        for(ll j=2*k; j<4*k; j++){
            cnt[i][j]+=cnt[i-2*k][j]+cnt[i][j-2*k]+cnt[i-2*k][j-2*k];
        }
    }
    for(ll i=2*k; i<4*k; i++){
        for(ll j=2*k; j<3*k; j++){
            if(i<3*k) cnt[i][j]+=cnt[i+k][j+k];
            else cnt[i][j]+=cnt[i-k][j+k];
        }
    }
    ll res=0;
    rep(i,2*k){
        rep(j,k){
            chmax(res, cnt[i+2*k][j+2*k]);
        }
    }
    cout<<res<<endl;
    return 0;
}

