#include <iostream>
#include <vector>
using namespace std;



int main()
{
    int N, K;
    cin >> N >> K;
    vector<int> x(N), y(N);
    // (x[i], y[i]) が黒であるようにデータを変形
    for( int i = 0; i < N; ++i ){
        char c;
        cin >> x[i] >> y[i] >> c;
        if( c == 'W' ) y[i] += K;
        x[i] %= 2*K;
        y[i] %= 2*K;
    }


    // 市松模様を黒い部分の左下で特徴付ける
    // 全ての i について、(x[i], y[i]) を黒として含むような塗り方の K*K 通りのマスを
    // +1 すると、その最大値が答えになる
    // 高速化するために、2次元累積和を用いる
    int numBlack[2001][2001] = {};
    for( int i = 0; i < N; ++i ){
        numBlack[x[i]][y[i]] += 1;
        if( x[i] < K and y[i] < K ){
            numBlack[x[i]+K][y[i]] -= 1;
            numBlack[x[i]][y[i]+K] -= 1;
            numBlack[x[i]+K][y[i]+K] += 1;
        }else if( x[i] < K and y[i] >= K ){
            numBlack[x[i]+K][y[i]] -= 1;

            numBlack[x[i]][0] += 1;
            numBlack[x[i]+K][0] -= 1;
            numBlack[x[i]][y[i]-K] -= 1;
            numBlack[x[i]+K][y[i]-K] += 1;
        }else if( x[i] >= K and y[i] < K ){
            numBlack[x[i]][y[i]+K] -= 1;

            numBlack[0][y[i]] += 1;
            numBlack[0][y[i]+K] -= 1;
            numBlack[x[i]-K][y[i]] -= 1;
            numBlack[x[i]-K][y[i]+K] += 1;
        }else{
            numBlack[0][0] += 1;
            numBlack[0][y[i]-K] -= 1;
            numBlack[x[i]-K][y[i]] -= 1;
            numBlack[x[i]-K][y[i]-K] += 1;
        }
    }

    // 2次元累積和
    for( int i = 0; i < 2*K; ++i ){
        for( int j = 0; j < 2*K; ++j ){
            numBlack[i+1][j] += numBlack[i][j];
        }
    }
    for( int i = 0; i < 2*K; ++i ){
        for( int j = 0; j < 2*K; ++j ){
            numBlack[i][j+1] += numBlack[i][j];
        }
    }

    // 最大値の探索
    int ans = 0;
    for( int i = 0; i < 2*K; ++i ){
        for( int j = 0; j < 2*K; ++j ){
            ans = max( ans, numBlack[i][j] );
        }
    }
    cout << ans << endl;

    return 0;
}

