class BIT_2D {
private:
  const int h, w;
  vector<vector<ll>> data;
public:
  BIT_2D(int h, int w): h(h), w(w), data(h+1, vector<ll>(w+1)) { }
  void add(int r, int c, ll v) {
    r++; c++;
    int c0 = c;
    for (; r <= h; r += r & -r)
      for (c = c0; c <= w; c += c & -c)
        data[r][c] += v;
  }
  // sum over [(0, 0), (r, c))
  ll sum(int r, int c) {
    ll res = 0;
    int c0 = c;
    for (; r > 0; r -= r & -r)
      for (c = c0; c > 0; c -= c & -c)
        res += data[r][c];
    return res;
  }
  // sum over [(r1, c1), (r2, c2))
  ll sum(int r1, int c1, int r2, int c2) {
    return sum(r1, c1) + sum(r2, c2) - sum(r1, c2) - sum(r2, c1);
  }
  void assign(int r, int c, ll v) {
    add(r, c, v - sum(r, c, r+1, c+1));
  }
  bool chmax(int r, int c, ll v) {
    if (sum(r, c, r+1, c+1) < v) {
      assign(r, c, v);
      return true;
    } else return false;
  }
};


int main() {
  int n = IN, k = IN;
  VI x(n), y(n); vector<string> c(n);
  rep(i, n) IN >> x[i] >> y[i] >> c[i];

  BIT_2D rsq(k, k+k);
  rep(i, n) {
    if (c[i] == "W"s) y[i] += k;
    y[i] %= k+k;
    if (y[i] >= k) y[i] -= k, x[i] += k;
    x[i] %= k+k;
    rsq.add(y[i], x[i], 1);
  }

  ll res = 0;
  rep(r, k) rep(c, k) {
    ll tmp = rsq.sum(r, c) + rsq.sum(r, c, k, c+k) + rsq.sum(0, c+k, r, k+k);
    chmax(res, max(tmp, n-tmp));
  }
  OUT(res);
}

