int d[2001][2001];

int fcn(int i, int j, int k, int l){
    return d[k][l]-d[k][j-1]-d[i-1][l]+d[i-1][j-1];
}

int main(){
    int n, k;
    cin >> n >> k;
    int x[n], y[n];
    for(int i=0; i<n; i++){
        char c;
        cin >> x[i] >> y[i] >> c;
        if(c=='W') x[i]+=k;
        x[i]%=2*k;
        y[i]%=2*k;
        x[i]++;
        y[i]++;
    }

    for(int i=0; i<n; i++){
        d[x[i]][y[i]]++;
    }
    for(int i=0; i<2*k+1; i++){
        for(int j=1; j<2*k+1; j++){
            d[i][j]+=d[i][j-1];
        }
    }
    for(int j=0; j<2*k+1; j++){
        for(int i=1; i<2*k+1; i++){
            d[i][j]+=d[i-1][j];
        }
    }

    int ans=0;
    for(int i=1; i<=k; i++){
        for(int j=1; j<=k; j++){
            int s=fcn(i, j, i+k-1, j+k-1);
            s+=fcn(i+k, j+k, 2*k, 2*k);
            s+=fcn(1, 1, i-1, j-1);
            s+=fcn(1, j+k, i-1, 2*k);
            s+=fcn(i+k, 1, 2*k, j-1);
            ans=max(ans, s);
        }
    }
    cout << ans << endl;
    return 0;
}

