using namespace std;
typedef long long ll;

ll cnt[2][1010][1010];
ll sumW[1010][1010];
ll sumB[1010][1010];
// sumW[x][y]は、[0,x)*[0,y)内の白点の個数、sumBも同様
ll preW_x[1010][1010]; ll preW_y[1010][1010];
ll preB_x[1010][1010]; ll preB_y[1010][1010];
// preW_x は i = x-1, 0 <= j < yにおける白点の個数　他も同様

int main(){ 

  int N,K; cin >> N >> K;

  for(int i = 0; i < N; i++){
    ll x,y; char c; cin >> x >> y >> c;
    int judge = 0;
    if( c == 'B'){ judge = 1;} //1で黒、0で白
    ll m = x/K; ll n = y/K;

    if( (m+n)%2 == 1){ //色が反転
      if(judge == 1){ judge = 0;}
      else{ judge = 1;}
    }

    cnt[judge][x%K][y%K]++;
  }

  //先に累積和で格子点(i,j)以下の白点の個数をsumW[i][j]と求めておく sumBも同様

  for(int x = 0; x <= K; x++){
    for(int y = 0; y <= K; y++){

      if(x-1>=0){ 
        preW_x[x][y+1] = preW_x[x][y]+cnt[0][x-1][y];
        preB_x[x][y+1] = preB_x[x][y]+cnt[1][x-1][y];
      }
      if(y-1>=0){
        preW_y[x+1][y] = preW_y[x][y]+cnt[0][x][y-1];
        preB_y[x+1][y] = preB_y[x][y]+cnt[1][x][y-1];
      }

    }
  }


  for(int x = 0; x <= K; x++){
    for(int y = 0; y <= K; y++){

      if(x+1 <= K){ 
       sumW[x+1][y] = sumW[x][y]+preW_x[x+1][y];
       sumB[x+1][y] = sumB[x][y]+preB_x[x+1][y];
      }
      if(y+1 <= K){
       sumW[x][y+1] = sumW[x][y]+preW_y[x][y+1];
       sumB[x][y+1] = sumB[x][y]+preB_y[x][y+1];
      }

    }
  }

  // ここまで問題なし


  ll ans = 0; 

  for(int x = 0; x <= K; x++){
    for(int y = 0; y <= K; y++){

      ll res1 = sumW[x][y]+(sumW[K][K]-sumW[x][K]-sumW[K][y]+sumW[x][y]);
      res1 += sumB[x][K]+sumB[K][y]-2*sumB[x][y];


      ll res2 = sumB[x][y]+(sumB[K][K]-sumB[x][K]-sumB[K][y]+sumB[x][y]);
      res2 += sumW[x][K]+sumW[K][y]-2*sumW[x][y];


      ans = max(ans, max(res1,res2)); 

    }
  }

  cout << ans << endl;

  return 0;
}

