int calc_sub(int x, int y) {
  // if (x+K-1<0 || y+K-1<0) return 0L;
  if (x < -K || y < -K) return 0L;
  int lx = max(0LL, x);
  int rx = min(2 * K - 1, x + K - 1);
  int by = max(0LL, y);
  int ty = min(2 * K - 1, y + K - 1);

  int ret = sum[rx][ty];
  if (0L < lx) ret -= sum[lx - 1][ty];
  if (0L < by) ret -= sum[rx][by - 1];
  if (0L < lx && 0L < by) ret += sum[lx - 1][by - 1];

  return ret;
}

int calc(int x, int y)
{
  // cout << "calc(" << x << "," << y << ")" << endl;
  int sum = 0;
  for (int xx=x-2*K, ix=0; xx<=x; xx+=K, ix++) {
    for (int yy=y-2*K, iy=0; yy<=y; yy+=K, iy++) {
      if ((ix + iy) % 2 == 0) {
        sum += calc_sub(xx, yy);
      }
    }
  }
  // if (sum == 6) {
  //   printf("x = %d, y = %d\n", x, y);
  // }
  return sum;
}

