  mat w(K+2,vec(K+2,0)),b(K+2,vec(K+2,0));
  string s;
  while(N--){
    cin>>i>>j>>s;
    res=i/K+j/K+(s[0]=='B');
    if(res%2) b[i%K+1][j%K+1]++;
    else w[i%K+1][j%K+1]++;
  }
  K++;
  rep1(i,K+1){
    rep1(j,K+1){
      b[i][j]+=b[i][j-1];
      w[i][j]+=w[i][j-1];
    }
