int main(){
    int N, K;
    cin >> N >> K;

    vector<vector<int> > grid(4*K,vector<int>(4*K,0));
    for(int i=0; i<N; i++){
        int x, y;
        char c;
        cin >> x >> y >> c;

        if(c=='B'){
            x=x%(2*K);
            y=y%(2*K);
        }else{
            x=(x%(2*K)+K)%(2*K);
            y=(y%(2*K))%(2*K);
        }
        for(int j=0; j<2*K; j++){
            if((y<=j && j<=y+K-1)||(y+K-1>=2*K && j<=(y+K-1)%(2*K))){
                grid[j][x]+=1;
                if(x+K>=2*K){
                    grid[j][0]+=1;
                    grid[j][(x+K)%(2*K)]+=-1;
                }else{
                    grid[j][x+K]+=-1;
                }
            }
        }
    }

    //cout_mat(grid);

    int ans = 0;
    for(int y=0; y<2*K; y++){
        for(int x=0; x<2*K-1; x++){
            grid[y][x+1]+=grid[y][x];
            ans=max(ans, grid[y][x+1]);
        }
    }

    //cout_mat(grid);

    cout << ans << endl;
}

