int main() {
  int n, k;
  cin >> n >> k;
  vector<vector<int>> tbl(2 * k, vector<int>(2 * k, 0));
  vector<vector<int>> sumtbl(4 * k + 1, vector<int>(4 * k + 1, 0));

  for (int i = 0; i < n; i++) {
    int x, y;
    char c;
    cin >> x >> y >> c;
    x %= (2 * k);
    y %= (2 * k);
    if (c == 'B')
      tbl[x][y]++;
    else if (c == 'W')
      tbl[x][y + k]++;
  }
  for (int i = 0; i < 4 * k; i++)
    for (int j = 0; j < 4 * k; j++) {
      sumtbl[i + 1][j + 1] = tbl[i % (2 * k)][j % (2 * k)];
    }
  for (int i = 0; i < 4 * k - 1; i++)
    for (int j = 0; j < 4 * k; j++) {
      sumtbl[i + 1][j] += sumtbl[i][j];
    }
  for (int i = 0; i < 4 * k; i++)
    for (int j = 0; j < 4 * k - 1; j++) {
      sumtbl[i][j + 1] += sumtbl[i][j];
    }

  int res = 0;
  for (int i = 0; i < 2 * k; i++) {
    for (int j = 0; j < 2 * k; j++) {
      int tmp = sumtbl[i + k][j + k] - sumtbl[i][j + k] - sumtbl[i + k][j] +
                sumtbl[i][j] + sumtbl[i + 2 * k][j + 2 * k] -
                sumtbl[i + k][j + 2 * k] - sumtbl[i + 2 * k][j + k] +
                sumtbl[i + k][j + k];
      res = max(res, tmp);
    }
  }
  cout << res << endl;
}

