void solve(){
  int N,K; cin >>N >>K;
  vector<ll> X(N),Y(N);
  vector<bool> black(N);
  rep(i, N){
    char c; cin >>X[i] >>Y[i] >>c; black[i] = c == 'B'; 
  }
  rep(i, N){ X[i] = X[i] % (2*K) + 2*K; Y[i] = Y[i] % (2*K) + 2*K; }
  vector<vector<ll>> field(6*K, vector<ll>(5*K, 0));
  // 黒の左上頂点がここなら条件がこれだけ叶うよー
  for (int i=0; i<N; i++){
    int hosei = 0;
    if (!black[i]) hosei = K;
    field[X[i]-K+1 + hosei][Y[i]-K+1]++;
    field[X[i]-K+1 + hosei][Y[i]+1]--;
    field[X[i]+1 + hosei][Y[i]-K+1]--;
    field[X[i]+1 + hosei][Y[i]+1]++;
  }
  // 累積和
  for (int x=0; x<field.size(); x++){
    for (int y=1; y<field[0].size(); y++){
      field[x][y] += field[x][y-1];
    }
  }
  for (int y=0; y<field[0].size(); y++){
    for (int x=1; x<field.size(); x++){
      field[x][y] += field[x-1][y];
    }
  }
  // 情報を2*N, 2*Nのアレにまとめる
  for (int x=0; x<field.size(); x++){
    for (int y=0; y<field[0].size(); y++){
      if (x < 2*K && y < 2*K) continue;
      field[x%(2*K)][y%(2*K)] += field[x][y];
      field[x][y] = 0;
    }
  }
  // 情報を2*N, N のアレにまとめる
  for (int x=0; x<2*K; x++){
    for (int y=0; y<2*K; y++){
      if (x < 2*K && y < K) continue;
      field[(x+K)%(2*K)][y-K] += field[x][y];
      field[x][y] = 0;
    }
  }
  ll res = 0;
  for (int x=0; x<2*K; x++){
    for (int y=0; y<K; y++){
      chmax(res, field[x][y]);
    }
  }
  cout <<res <<endl;
}

int main() {
  solve();
}

