  // for(int i = 0; i < 2 *K; i++){
  //   for(int j = 0; j < 2 *K; j++){
  //     cout << sum_b[i][j];
  //   }
  //   cout << endl;
  // }
  // for(int i = 0; i < 2 *K; i++){
  //   for(int j = 0; j < 2 *K; j++){
  //     cout << sum_w[i][j];
  //   }
  //   cout << endl;
  // }

  ll ans = 0;
  ll tmp_cnt_b;
  ll tmp_cnt_w;
  for(int i = 0; i <= K; i++){
    for(int j = 0; j <= K; j++){
      // 黒領域の中にある blackとwhiteの数をそれぞれ
      // 数える
      tmp_cnt_b = 0;
      tmp_cnt_w = 0;

      ll cnt_b_A = 0;
      ll cnt_b_B = 0;
      ll cnt_b_C = 0;
      ll cnt_b_D = 0;
      ll cnt_b_E = 0;
      ll cnt_b_F = 0;
      ll cnt_b_G = 0;
      ll cnt_b_H = 0;
      ll cnt_b_I = 0;

      ll cnt_w_A = 0;
      ll cnt_w_B = 0;
      ll cnt_w_C = 0;
      ll cnt_w_D = 0;
      ll cnt_w_E = 0;
      ll cnt_w_F = 0;
      ll cnt_w_G = 0;
      ll cnt_w_H = 0;
      ll cnt_w_I = 0;

      if(i-1 >= 0 && j-1 >= 0){
        cnt_b_A += sum_b[i-1][j-1];
        cnt_w_A += sum_w[i-1][j-1];
      }

      if(i-1 >= 0 && j-1+K < 2*K){
        cnt_b_B += sum_b[i-1][j-1+K];
        cnt_w_B += sum_w[i-1][j-1+K];
      }

      if(i-1>=0){
        cnt_b_C += sum_b[i-1][2*K-1];
        cnt_w_C += sum_w[i-1][2*K-1];
      }

      if(j-1 >= 0 && i-1+K  < 2*K){
        cnt_b_D += sum_b[i-1+K][j-1];
        cnt_w_D += sum_w[i-1+K][j-1];
      }

      if(j-1 >= 0){
        cnt_b_E += sum_b[2*K-1][j-1];
        cnt_w_E += sum_w[2*K-1][j-1];        
      }

      cnt_b_F += sum_b[i-1+K][j-1+K];
      cnt_w_F += sum_w[i-1+K][j-1+K];

      cnt_b_G += sum_b[i-1+K][2*K-1];
      cnt_w_G += sum_w[i-1+K][2*K-1];

      cnt_b_H += sum_b[2*K-1][j-1+K];
      cnt_w_H += sum_w[2*K-1][j-1+K];

      cnt_b_I += sum_b[2*K-1][2*K-1];
      cnt_w_I += sum_w[2*K-1][2*K-1];

      // 1.
      tmp_cnt_b += cnt_b_A;
      tmp_cnt_w += cnt_w_A;

      // 2.
      tmp_cnt_b += cnt_b_C - cnt_b_B;
      tmp_cnt_w += cnt_w_C - cnt_w_B;

      // 3.
      tmp_cnt_b += cnt_b_E - cnt_b_D;
      tmp_cnt_w += cnt_w_E - cnt_w_D;

      // 4.
      tmp_cnt_b += cnt_b_F - cnt_b_B - cnt_b_D + cnt_b_A;
      tmp_cnt_w += cnt_w_F - cnt_w_B - cnt_w_D + cnt_w_A;

      // 5.
      tmp_cnt_b += cnt_b_I - cnt_b_G - cnt_b_H + cnt_b_F;
      tmp_cnt_w += cnt_w_I - cnt_w_G - cnt_w_H + cnt_w_F;

      chmax(ans, tmp_cnt_b);

    }
  }

  cout << ans << endl;

  return 0;
}

