  for (int i = 0; i < K; i++) {
    for (int j = 0; j < K; j++) {
      int res = BR[i+1][j+1];
      res += BR[K][K] - BR[i+1][K] - BR[K][j+1] + BR[i+1][j+1];
      res += WR[K][j+1] - WR[i+1][j+1];
      res += WR[i+1][K] - WR[i+1][j+1];
      res = max(N-res,res);
      ans = max(ans,res);
    }
  }
  cout << ans << endl;
  return 0;
}

