int calc_accumulate(const vector<vector<vector<int>>> &f, int c, int x, int y, int k)
{
    int ret = 0;
    ret += f[c][x + k - 1][y + k - 1];
    if (x > 0)
    {
        ret -= f[c][x - 1][y + k - 1];
    }
    if (y > 0)
    {
        ret -= f[c][x + k - 1][y - 1];
    }
    if (x > 0 && y > 0)
    {
        ret += f[c][x - 1][y - 1];
    }
    return ret;
}

