        if(c == 'B') {
            if(n & 1) return 'W';
            else return 'B';
        }else if(c == 'W') {
            if(n & 1) return 'B';
            else return 'W';
        }
    };
    CumlativeSum2<ll> black(k,k), white(k,k);
    rep(i, n) {
        ll x, y; char c;
        cin >> x >> y >> c;
        ll p = x / k + y / k;
        if(get(c, p) == 'B') {
            black.add(x%k+1, y%k+1, 1);
        }else{
            white.add(x%k+1, y%k+1, 1);
        }
    }
    black.build();
    white.build();
    ll ans = 0;
    ll foo;
    repn(i, k) repn(j, k) {
        int now = white.q(0, 0, k, k);
        foo = now - white.q(0, 0, i, j) + black.q(0, 0, i, j) - white.q(i, j, k, k) + black.q(i, j, k, k);
        chmax(ans, max(n - foo, foo));
        foo = now - white.q(i, 0, k, j) + black.q(i, 0, k, j) - white.q(0, j, i, k) + black.q(0, j, i, k);
