    y = max(y, 1); y = min(y, 2*k);
    u = max(u, 1); u = min(u, 2*k);
    v = max(v, 1); v = min(v, 2*k);
    return w[u][v] - w[x-1][v] - w[u][y-1] + w[x-1][y-1];
}

