	for (int i = 0; i < k; i++)
	{
		for (int j = 0; j < 2 * k; j++)
		{
			if (((x + i) / k) % 2 == 0 && ((y + j) / k) % 2 == 0)
			{
				if (c == 'B')
					check[i][j]++;
			}
			else
			{
				if (c == 'W')
					check[i][j]++;
			}
		}
	}
}

int findMax(int check[][2000], int k)
{
	int max = 0;

	for (int i = 0; i < k; i++)
	{
		for (int j = 0; j < 2 * k; j++)
		{
			if (max < check[i][j])
				max = check[i][j];
		}
	}

	return max;
}

