int calc(int i, int j){
  int a, b, c, d;
  if(i > 0 && j > 0){
    a = posb[i-1][j-1];
    b = posb[i-1][j+k-1];
    c = posb[i+k-1][j-1];
    d = posb[i+k-1][j+k-1];
  }
  else{
    if(i <= 0 && j <= 0){
      a = 0;
      b = 0;
      c = 0;
    }
    else{
      if(j > 0){
        a = 0;
        b = 0;
        if(i > -1 * k)c = posb[i+k-1][j-1];
      }
      if(i > 0){
        a = 0;
        if(j > -1 * k)b = posb[i-1][j+k-1];
        c = 0;
      }
    }
  }
  if(i <= -1 * k || j <= -1 * k){
    a = 0;
    b = 0;
    c = 0;
    d = 0;
  }
  else d = posb[i+k-1][j+k-1];
  return d + a - b - c;
}

