#define ALL(obj) (obj).begin(), (obj).end()
#define ALLR(obj) (obj).rbegin(), (obj).rend()

int memo[20][20]; // x, y
int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, k;
    cin >> n >> k;
    REP(i, n) {
        int x, y;
        char c;
        cin >> x >> y >> c;
        if (c == 'B') {
            x += k;
        }
        x %= 2 * k;
        y %= 2 * k;
        memo[x][y]++;
    }

    vector<int> u1(2 * k), u2(2 * k);
    REP(i, k * 2) REP(j, k * 2) {
        u1[i] += memo[i][j];
        u2[j] += memo[i][j];
