        ans = max(ans, t);
    }
    t = 0;
    REP(i, k) t += u2[i];
    ans = max(ans, t);
    REP(i, 2 * k) {
        t += u2[(k + i) % (2 * k)] - u2[i];
        ans = max(ans, t);
    }
