            int w = (W[2 * K - i][2 * K] - W[K - i][2 * K]) + (W[2 * K][2 * K - j] - W[2 * K][K - j]) - (W[2 * K - i][2 * K - j] - W[2 * K - i][K - j] - W[K - i][2 * K - j] + W[K - i][K - j]);
