	vec2 wt(2 * k, 2 * k, 0), bt(2 * k, 2 * k, 0), wmt(2*k+1,2*k+1,0),bmt(2*k+1,2*k+1,0);

	rep(i, n)
	{
		lint x, y;
		char c;
		cin >> x >> y >> c;
		x %= (2 * k);
		y %= (2 * k);
		if (c == 'B')
		{
			bt[x][y]++;
		}
		else
		{
			wt[x][y]++;
		}
	}

	rep(i, 2 * k)
	{
		rep(j, 2 * k)
		{
			wmt[i + 1][j + 1] = wmt[i][j + 1] + wmt[i + 1][j] - wmt[i][j] + wt[i][j];
			bmt[i + 1][j + 1] = bmt[i][j + 1] + bmt[i + 1][j] - bmt[i][j] + bt[i][j];
		}
	}

	lint ans = 0;
	rep(i, 2 * k)
	{
		rep(j, 2 * k)
		{
			lint e = 0;
			for (lint xx = -1; xx*k+i < 2*k; xx++)
			{
				for (lint yy = -1; yy*k+j < 2*k; yy++)
				{
					lint x1 = mmax(0, mmin(2 * k, xx * k + i));
					lint y1 = mmax(0, mmin(2 * k, yy * k + j));
					lint x2 = mmin(2 * k, mmax(0, (xx+1)*k + i));
					lint y2 = mmin(2 * k, mmax(0, (yy+1)*k + j));
					if (abs(xx + yy) % 2 == 0)
					{
						e += wmt[x2][y2] - wmt[x1][y2] - wmt[x2][y1] + wmt[x1][y1];
					}
					else
					{
						e += bmt[x2][y2] - bmt[x1][y2] - bmt[x2][y1] + bmt[x1][y1];
					}
				}
			}

			ans = mmax(ans, e);
		}
	}

	cout << ans << endl;
	return 0;
}

