    //std::cin.rdbuf(in.rdbuf());

    int N, K;
    std::cin >> N >> K;
    int K2 = K * 2;
    CumSum2D<int> cs(K2, K2);

    //Wは+KでBに変換可能
    //mod 2*Kを取って良い

    //1.叶えられる希望の最大値 = 必要な塗り方の重なりの最大値：imos法
    //塗り方は黒の塊の左下位置Bを代表にとる
    //一つの希望に対し、黒は最大5つの範囲が存在するが、Bは2つの範囲のいずれかに属する
    //これを場合分けして各範囲で足す手もあるが、大変

    //2.Bを決め、その場合に含まれる希望の数を累積和で数える
    //場合分けの代わりに、もう一つの範囲分にもaddしておく
    //Bは(0,0)~(K-1,K-1)のみ考えれば十分
    //この方が場合分けが少なくて楽

    for (int i = 0; i < N; i++) {
        int x, y;
        std::cin >> x >> y;
        char c;
        std::cin >> c;
        if (c == 'W') x += K;
        x = x % K2;
        y = y % K;
        if(y >= K) {
            y -= K;
            x = (x + K) % K2;
        }
        if (cs.add(x, y, 1) == -1) return -1;
        if (cs.add((x+K) % K2, y+K, 1) == -1) return -1;
    }
    cs.build();
    //cs.print();

    int ans = 0;
    for (int i = 1; i <= K; i++) {
        for (int j = 1; j <= K; j++) {
            int b = cs.get(i, j, i+K-1, j+K-1);
            ans = std::max(ans, b);
            if (ans == N) {
                std::cout << ans << std::endl;
                return 0;
            }
        }
    }
    std::cout << ans << std::endl;

    return 0;
}

