int N,K;
int x[100000]={},y[100000]={};
bool c[100000]={}; //true::black false::white
int mastermap_b[2000][2000]={};
int mastermap_w[2000][2000]={};
void input(void){
    std::cin>>N>>K;
    char m1;
    for(int l1=0;l1<N;l1++){
        std::cin>>x[l1]>>y[l1]>>m1;
        if(m1=='B') c[l1]=true;
        else c[l1]=false;
    }
}
void create_mastermap(void){
    for(int l1=0;l1<N;l1++){
        int &x_now=x[l1],&y_now=y[l1];
        bool &c_now=c[l1];
        int x_pos=x_now%(2*K),y_pos=y_now%(2*K);
        if(!c_now){
            mastermap_w[x_pos][y_pos]++;
        }else{
            mastermap_b[x_pos][y_pos]++;
        }
    }
}

void solve(void){
    int ansmax=0;
    int ans=0;
    bool bwmap[2000][2000]={};
    for(int l1=0;l1<2000;l1++){
        for(int l2=0;l2<2000;l2++){
            bwmap[l1][l2]=true;
        }
    }
    for(int corner_x=0;corner_x<K;corner_x++){
        for(int corner_y=0;corner_y<K;corner_y++){
            //bwmap作成
            for(int l1=0;l1<K;l1++){
                for(int l2=0;l2<K;l2++){
                    bwmap[l1][l2]=false;
                }
            }
            for(int l1=corner_x-1;l1>=0;l1--){
                for(int l2=corner_y-1;l2>=0;l2--){
                    bwmap[l1][l2]=false;
                }
                for(int l2=corner_y+K;l2<K*2;l2++){
                    bwmap[l1][l2]=false;
                }
            }
            for(int l1=corner_x+K;l1<2*K;l1++){
                for(int l2=corner_y-1;l2>=0;l2--){
                    bwmap[l1][l2]=false;
                }
                for(int l2=corner_y+K;l2<K*2;l2++){
                    bwmap[l1][l2]=false;
                }
            }

            //answerを計算
            for(int l1=0;l1<2*K;l1++){
                for(int l2=0;l2<2*K;l2++){
                    if(bwmap[l1][l2]){
                        ans+=mastermap_b[l1][l2];
                    }else{
                        ans+=mastermap_w[l1][l2];
                    }
                }
            }

            if(ans>ansmax) ansmax=ans;
            ans=0;


        }
    }
    std::cout<<ansmax<<std::endl;
}

int main(void){
	input();
    create_mastermap();
    solve();
    return 0;
}

