int mat[3000][3000];

void mark(int sx, int sy, int K)
{
	int ex = min(sx + K, 2 * K);
	int ey = min(sy + K, 2 * K);
	sx = max(sx, 0);
	sy = max(sy, 0);
	++mat[sy][sx];
	--mat[ey][sx];
	--mat[sy][ex];
	++mat[ey][ex];
}

int main()
{
	int N, K;
	cin >> N >> K;
	memset(mat, 0, sizeof(mat));

	for (auto i = 0; i < N; ++i)
	{
		long long tempX, tempY;
		char c;
		cin >> tempX >> tempY >> c;

		if (c == 'W')
		{
			tempY += K;
		}

		auto x = (int)(tempX % (2 * K));
		auto y = (int)(tempY % (2 * K));

		for (auto j = -1; j < 2; ++j)
		{
			for (auto k = -1; k <= 2; ++k)
			{
				auto sx = x + 2 * K * j + 1;
				if (k % 2 == 0)
				{
					sx = x - K + 1 + 2 * K * j;
				}
				if (sx <= -K || sx >= 2 * K)
				{
					continue;
				}

				auto sy = y - K + 1 + K * k;
				if (sy <= -K || sy >= 2 * K)
				{
					continue;
				}

				mark(sx, sy, K);
			}
		}
	}

	for (auto i = 0; i <= 2 * K; ++i)
	{
		for (auto j = 1; j <= 2 * K; ++j)
		{
			mat[i][j] += mat[i][j - 1];
		}
	}

	for (auto i = 0; i <= 2 * K; ++i)
	{
		for (auto j = 1; j <= 2 * K; ++j)
		{
			mat[j][i] += mat[j - 1][i];
		}
	}

	auto result = 0;
	for (auto i = 0; i < 2 * K; ++i)
	{
		for (auto j = 0; j < 2 * K; ++j)
		{
			result = max(result, mat[i][j]);
		}
	}

	cout << result << endl;

	return 0;
}

