int judge(int x, int y, char c, int v){
    /// vは、(0,0)が(v%(2K),v/(2K))であるようなもの。
    /// 逆に、(-v%(2K),-v/(2K))が白左下になる。
    ///このときの(x, y)の色は?左下からの距離で決まる。

    char col;


    int ox = -v%(2*K);
    int oy = -v/(2*K);


    if(( ((x-ox)%(2*K)) < K && ((y-oy)%(2*K)) < K ) || (((x-ox)%(2*K)) >= K && ((y-oy)%(2*K)) >= K )) {
        col = 'W';
    }else col = 'B';

    return c == col;


}

