int calc(int x1, int y1, int x2, int y2, int z)
{
	int ans = cnt[x2][y2][z];
	if(x1 > 0) ans -= cnt[x1 - 1][y2][z];
	if(y1 > 0) ans -= cnt[x2][y1 - 1][z];
	if(x1 > 0 && y1 > 0) ans += cnt[x1 - 1][y1 - 1][z];
	return ans;
}

int main()
{
	int n, k;
	cin >> n >> k;
	for(int i = 0; i < n; i++){
		int x, y;
		char c;
		cin >> x >> y >> c;
		x %= 2 * k;
		y %= 2 * k;
		if(c == 'B'){
			cnt[x][y][0]++;
			cnt[x + 2 * k][y + 2 * k][0]++;
		}
		else {
			cnt[x][y][1]++;
			cnt[x + 2 * k][y + 2 * k][1]++;
		}
	}
	for(int j = 0; j < 4 * k; j++){
		for(int i = 1; i < 4 * k; i++){
			cnt[i][j][0] += cnt[i - 1][j][0];
			cnt[i][j][1] += cnt[i - 1][j][1];
		}
	}

	for(int i = 0; i < 4 * k; i++){
		for(int j = 1; j < 4 * k; j++){
			cnt[i][j][0] += cnt[i][j - 1][0];
			cnt[i][j][1] += cnt[i][j - 1][1];
		}
	}

	int ans = 0;
	for(int i = 0; i < 2 * k; i++){
		for(int j = 0; j < 2 * k; j++){
			int res = calc(i, j, i + k - 1, j + k - 1, 0);
			// cout << res << " ";
			res += calc(i + k, j + k, i + 2 * k - 1, j + 2 * k - 1, 0);
			// cout << res << " ";
			res += calc(i, j + k, i + k - 1, j + 2 * k - 1, 1);
			// cout << res << " ";
			res += calc(i + k, j, i + 2 * k - 1, j + k - 1, 1);
			// cout << res << endl;
			ans = max(ans, res);
		}
	}
	cout << ans << endl;
}

