int N,K;
int G[2005][2005];
int m[2005][2005],M[2005][2005];

int mat(int x1,int y1, int x2,int y2){

  int p,q,r;

  if(x1-1>=0){
    p=M[x1-1][y2];
  }
  else{
    p=0;
  }

  if(y1-1>=0){
    q=M[x2][y1-1];
  }
  else{
    q=0;
  }

  if(x1-1>=0&&y1-1>=0){
    r=M[x1-1][y1-1];
  }else{
    r=0;
  }

  return M[x2][y2]-q-p+r;

}

int cnt(int i,int j){
  int c0,c1,c2,c3,c4;
  c0=mat(i,j,i+K-1,j+K-1);
  if(i-1>=0&&j==0) c1=mat(0,j+K,i-1,j+2*K-1);
  else if(i-1>=0&&j>0) c1=mat(0,j+K,i-1,2*K-1);
  else c1=0;
  if(i-1>=0&&j-1>=0) c2=mat(0,0,i-1,j-1);
  else c2=0;
  if(i==0&&j==0) c3=mat(i+K,j+K,i+2*K-1,j+2*K-1);
  else c3=mat(i+K,j+K,2*K-1,2*K-1); 
  if(i==0&&j-1>=0) c4=mat(i+K,0,i+2*K-1,j-1);
  else if(i>0&&j-1>=0) c4=mat(i+K,0,2*K-1,j-1);
  else c4=0;

  return c0+c1+c2+c3+c4;

}

