    if(!black)black=-1;
    table[1][y+2]-=black;
    table[x+2][1]-=black;
    table[x+2][y+2]+=2*black;
  }
  int ans = 0;
  rep(x,K)rep(y,K){
    table[x+1][y+1] += table[x+1][y] + table[x][y+1] - table[x][y];
    ans = max(ans, max(table[x+1][y+1], N-table[x+1][y+1]));
  }
  cout << ans << endl;
  return 0;
}

