    posb[x[i]][y[i]]++;
    posb[x[i]+2*k][y[i]+2*k]++;
    posb[x[i]+2*k][y[i]]++;
    posb[x[i]][y[i]+2*k]++;
  }
  for(int i = 0 ; i < 4 * k ; i++){
    for(int j = 0 ; j < 4 * k - 1 ; j++){
      posb[j+1][i] += posb[j][i];
    }
