bool unite(rec r1, rec r2, rec &res){
    // rとvecの共通部分を求める　
    if(r1.maxx < r2.minx || r2.maxx < r1.minx ||
       r1.maxy < r2.miny || r2.maxy < r2.miny ) return false;
    res = rec{max(r1.minx, r2.minx), max(r1.miny, r2.miny), min(r1.maxx, r2.maxx), min(r1.maxy, r2.maxy)};
    return true;
}


