    }

    for(int i = 0; i < N; i++){
        int xx = xs[i] % K;
        int yy = ys[i] % K;

        int minx = xx;
        int maxx = xx + K*2-1;
        int miny = yy;
        int maxy = yy + K*2-1;

        vector<rec> v;
        if((((xs[i] / K) % 2 == 0) ^ ((ys[i] / K) % 2 == 0)) ^ (cs[i] == 'W')){
            rec res;
            for(int j = 0; j < 3; j++){
                for(int k = 0; k < 3; k++){
                    if(!((j % 2 == 0) ^ (k % 2 == 0))){
                        if(unite(rec{0 + k * K, 0 + j * K, k*K + K - 1, j*K + K - 1}, rec{minx, miny, maxx, maxy}, res)){
                            res.minx -= minx;
                            res.miny -= miny;
                            res.maxx -= minx;
                            res.maxy -= miny;
                            v.push_back(res);
                        }
                    }
                }
            }
        }
        else{
            rec res;
            for(int j = 0; j < 3; j++){
                for(int k = 0; k < 3; k++){
                    if(((j % 2 == 0) ^ (k % 2 == 0))){
                        if(unite(rec{0 + k * K, 0 + j * K, k*K + K - 1, j*K + K - 1}, rec{minx, miny, maxx, maxy}, res)){
                            res.minx -= minx;
                            res.miny -= miny;
                            res.maxx -= minx;
                            res.maxy -= miny;
                            v.push_back(res);
                        }
                    }
                }
            }
        }
        for(rec res : v){
            dp[res.minx][res.miny]++;
            dp[res.maxx+1][res.maxy+1]++;
            dp[res.minx][res.maxy+1]--;
            dp[res.maxx+1][res.miny]--;
        }
    }

    for(int i = 0; i < K*2; i++){
        for(int j = 0; j < K*2; j++){
            dp[i][j+1] += dp[i][j];
        }
    }
    for(int j = 0; j < K*2; j++){
        for(int i = 0; i < K*2; i++){
            dp[i+1][j] += dp[i][j];
        }
    }

    int ans = 0;
    for(int i = 0; i < K*2; i++){
        for(int j = 0; j < K*2; j++){
            ans = max(ans, dp[i][j]);
        }
    }

    cout << ans << endl;



    return 0;
}

