    for (int y = k - 1; y >= 0; --y) {
        for (int x = k - 1; x >= 0; --x) {
            long long s = default_white[x][y].w;
            if (y < k - 1) {
                s += white_sums[x][y + 1].w;
            }
            if (x < k - 1) {
                s += white_sums[x + 1][y].w;
            }
            if (x < k - 1 && y < k - 1) {
                s -= white_sums[x + 1][y + 1].w;
