            black_sums[x][y].w = s;

            s = default_black[x][y].b;
            if (y < k - 1) {
                s += black_sums[x][y + 1].b;
            }
            if (x < k - 1) {
                s += black_sums[x + 1][y].b;
            }
            if (x < k - 1 && y < k - 1) {
                s -= black_sums[x + 1][y + 1].b;
            }
            black_sums[x][y].b = s;
        }
    }

//    print_default(white_sums);
//    print_default(black_sums);

    int max_desires = white_sums[0][0].w + black_sums[0][0].b;
    for (int x = 0; x < k; ++x) {
        for (int y = 0; y < k; ++y) {
            int ws = white_sums[0][0].w;
            int bs = black_sums[0][0].b;
            if (x > 0) {
                ws -= white_sums[k - x][0].w;
                bs += white_sums[k - x][0].b;
            }
            if (y > 0) {
                ws -= white_sums[0][k - y].w;
                bs += white_sums[0][k - y].b;
            }
            if (x > 0 && y > 0) {
                ws += white_sums[k - x][k - y].w;
                bs -= white_sums[k - x][k - y].b;
            }

            if (x > 0) {
                bs -= black_sums[k - x][0].b;
                ws += black_sums[k - x][0].w;
            }
            if (y > 0) {
                bs -= black_sums[0][k - y].b;
                ws += black_sums[0][k - y].w;
            }
