                ws -= black_sums[k - x][k - y].w;
            }

//            std::cout << "x y: " << x << " " << y << "\n";
//            std::cout << ws << " " << bs << "\n";
            if (ws + bs > max_desires) {
                max_desires = ws + bs;
            }

            bs = white_sums[0][0].b;
