using namespace std;
const int K=3005;
int x[K][K];int n,k;
int getsize(int x1,int y1,int x2,int y2){
    return x[x2][y2]-x[x2][y1]-x[x1][y2]+x[x1][y1];
}
int main()
{
    scanf("%d%d",&n,&k);
    int a,b;
    char c;
    for(int i=1;i<=n;i++){
		scanf("%d%d %c",&a,&b,&c);
		a%=2*k,b%=2*k;
        if(c=='W')
			a+=k;
        x[a%(2*k)+1][b%(2*k)+1]++;
    }
    for(int i=1;i<=2*k;i++)
		for(int j=1;j<=2*k;j++)
			x[i][j]=x[i][j]+(x[i-1][j]+x[i][j-1]-x[i-1][j-1]);
	int ans=0,sum;
    for(int i=1;i<=k;i++)
		for(int j=1;j<=k;j++){
			sum=getsize(0,0,i,j);
			sum+=getsize(k+i,k+j,2*k,2*k);
			sum+=getsize(k+i,2*k,2*k,2*k);
			sum+=getsize(2*k,k+j,2*k,2*k);
			sum+=getsize(i,j,k+i,k+j);
			sum=max(n-sum,sum);
            ans=max(ans,sum);
		}
	printf("%d\n",ans);
}

#include<cstdio>
#include<cstring>
const int MAXN = 100000;
const int MAXK = 1000;
int x[MAXN + 5], y[MAXN + 5], c[MAXN + 5];
int y1[10 * MAXK + 5];
int main() {
	int N, K, Max = 0, cnt = 0;
	scanf("%d%d",&N,&K);
	for(int i=1;i<=N;i++) {
		char ch;
		scanf("%d%d %c",&x[i],&y[i],&ch);
		x[i] = x[i] % (2*K);
		y[i] = y[i] % (2*K);
		if( ch == 'W' ) c[i] = 1;
		else c[i] = 0;
	}
	for(int i=0;i<=K;i++) {
		cnt = 0;
		memset(y1,0,sizeof(y1));
		for(int j=1;j<=N;j++) {
			int p = ( i <= x[j] && x[j] < i+K );
			int q = ( 0 <= y[j] && y[j] < K );
			if( p ^ q == c[j] ){
				cnt++;
				y1[y[j]] ++;
			}
			else {
				y1[y[j]] --;
			}
		}
		for(int j=0;j<=K;j++) {
			if( cnt > Max ) Max = cnt;
			if( N - cnt > Max ) Max = N - cnt;
			if( j != K )
				cnt = cnt - y1[j] - y1[K+j];
		}
	}
	printf("%d\n",Max);
}

