#include<iostream>
#include<string>
#include<algorithm>

using namespace std;

int N, K;

long long int B[2001][2001], W[2001][2001];

long long int diff[2001][2001];
long long int sum_diff[2001][2001];

int main(void) {

	cin >> N >> K;
	long long int tmp_x, tmp_y;
	string str;
	for (int i = 1; i <= N; i++) {
		cin >> tmp_x; 
		cin >> tmp_y; 
		cin >> str; if (str == "B") { B[tmp_x % (2 * K)][tmp_y % (2 * K)]++; }
		else { W[tmp_x % (2 * K)][tmp_y % (2 * K)]++; }
	}

	/*for (int i = 0; i <= 2 * K - 1; i++) {
		for (int j = 0; j <= 2 * K - 1; j++) {
			W[i][j] = W[i % (2 * K)][j % (2 * K)];
			B[i][j] = B[i % (2 * K)][j % (2 * K)];
		}
	}*/

	//====== diff ============================//
	for (int i = 0; i <= 2 * K - 1; i++) {
		for (int j = 0; j <= 2 * K - 1; j++) {
			diff[i][j] = B[i][j] - W[i][j];
		}
	}

	//=== sum_diff ===============================//

	for (int i = 0; i <= 2* K ; i++) {
		sum_diff[i][2 * K] = 0;
	}
	for (int j = 0; j <= 2 * K; j++) {
		sum_diff[2*K][j] = 0;
	}

	for (int i = 2 * K - 1; i >= 0; i--) {
		for (int j = 2 * K - 1; j >= 0; j--) {
			sum_diff[i][j] = diff[i][j] + sum_diff[i + 1][j] + sum_diff[i][j + 1] - sum_diff[i+1][j+1];
		}
	}

	//==========================================//

