	long long int count_W = 0;
	for (int i = 0; i <= 2 * K - 1; i++) {
		for (int j = 0; j <= 2 * K - 1; j++) {
			count_W += W[i][j];
		}
	}
	//==========================================//

	long long int ans = 0;

	long long int count;

	for (int I = 0; I <= K-1; I++) {
		for (int J = 0; J <= 2*K-1; J++) {

			count = 0;

			if (J <= K) {
				count += sum_diff[0][0] - sum_diff[I][0] - sum_diff[0][J] + sum_diff[I][J];
				count += sum_diff[I + K][0] - sum_diff[I + K][J];
				count += sum_diff[0][J + K] - sum_diff[I][J + K];
				count += sum_diff[I][J] - sum_diff[I + K][J] - sum_diff[I][J + K] + sum_diff[I + K][J + K];
				count += sum_diff[I + K][J + K];
			}
			else {
				count += sum_diff[0][J - K] - sum_diff[I][J - K] - sum_diff[0][J] + sum_diff[I][J];
				count += sum_diff[I][0] - sum_diff[I + K][0] - sum_diff[I][J - K] + sum_diff[I + K][J - K];
				count += sum_diff[I][J] - sum_diff[I + K][J];
				count += sum_diff[I + K][J - K] - sum_diff[I + K][J];
			}

			count += count_W;

			ans = max(ans, count);
		}//J-loop fin
	}//I-loop

	cout << ans << endl;

//	system("pause");
	return 0;
}

