inline int cot(int x1, int y1, int x2, int y2) {
	return ssum[x2+1][y2+1] - ssum[x1][y2+1] - ssum[x2+1][y1] + ssum[x1][y1];
}

inline int co(int x1, int y1, int x2, int y2) {
	int kn = 2 * k - 1;
	if (x1 < x2 && y1 < y2) {
		return cot(x1, y1, x2, y2);
	} else if (x1 < x2) {
		return cot(x1, y1, x2, kn) + cot(x1, 0, x2, y2);
	} else if (y1 < y2) {
		return cot(x1, y1, kn, y2) + cot(0, y1, x2, y2);
	} else {
		return cot(x1, y1, kn, kn) + cot(0, 0, x2, y2);
	}
	return 0;
}

