#define MAX_K 1000

using namespace std;


void put(int val, int px, int py,int K, int (*map)[MAX_K]){
    int x=px,y=py;
    if(x>=2*K || y>=2*K) return;
    if(x<0) x=0;
    if(y<0) y=0;
    map[x][y]+=val;
}

void putsq(int x,int y,int K,int (*map)[MAX_K]){
    put(1,x,y,K,map);
    put(-1,x+K,y,K,map);
    put(-1,x,y+K,K,map);
    put(1,x+K,y+K,K,map);
}

void mark(int x, int y, int K, int (*point)[MAX_K]){
    if((x<K) == (y<K)){
        int px=x%K,py=y%K;
        putsq(px+1,py+1,K,point);
        putsq(px+1-K,py+1-K,K,point);
        putsq(px+1-K,py+1+K,K,point);
        putsq(px+1+K,py+1-K,K,point);
        putsq(px+1+K,py+1+K,K,point);;
    }else{
        int px=x,py=y;
        if(x<K){
            px+=K; py-=K;
        }
        putsq(px+1,py+1,K,point);
        putsq(px+1-K,py+1-K,K,point);
        putsq(px+1-K,py+1+K,K,point);
        putsq(px+1-2*K,py+1,K,point);
    }
}


int main(){
    int N,K;
    cin >> N >> K;

    int point[MAX_K][MAX_K];
    for(int i=0;i<2*K;i++){
        for(int j=0;j<2*K;j++){
            point[i][j]=0;
        }
    }

    for(int i=0;i<N;i++){
        int x,y;
        char c;
        cin >> x >> y >> c;
        if(c=='B') x+=K;
        x=x%(2*K);
        y=y%(2*K);

        mark(x,y,K,point);
    }

    for(int i=0;i<K;i++){
        for(int j=1;j<K;j++){
            point[i][j]+=point[i][j-1];
        }
    }
    for(int i=1;i<K;i++){
        for(int j=0;j<K;j++){
            point[i][j]+=point[i-1][j];
        }
    }

    int max=0;
    for(int i=0;i<2*K;i++){
        for(int j=0;j<2*K;j++){
            if(max<point[i][j]){
                max=point[i][j];
            }
        }
    }
    cout << max << endl;

    return 0;
}

