template< class T >
struct CumulativeSum2D {
    vector< vector< T > > data;

    CumulativeSum2D(int W, int H) : data(W + 1, vector< int >(H + 1, 0)) {}

    void add(int x, int y, T z) {
        ++x, ++y;
        if(x >= data.size() || y >= data[0].size()) return;
        data[x][y] += z;
    }

    void build() {
        for(int i = 1; i < data.size(); i++) {
            for(int j = 1; j < data[i].size(); j++) {
                data[i][j] += data[i][j - 1] + data[i - 1][j] - data[i - 1][j - 1];
            }
        }
    }

    T query(int sx, int sy, int gx, int gy) {
        return (data[gx][gy] - data[sx][gy] - data[gx][sy] + data[sx][sy]);
    }
};

signed main() {
    int N, K;
    cin >> N >> K;
    int baseK = 2 * K;
    auto B = CumulativeSum2D<int>(baseK * 2, baseK * 2);
    auto W = CumulativeSum2D<int>(baseK * 2, baseK * 2);
    for (int i = 0; i < N; i++) {
        int x, y;
        char c;
        cin >> x >> y >> c;
        if (c == 'W') {
            W.add(x % baseK, y % baseK, 1);
            W.add((x % baseK) + baseK, y % baseK, 1);
            W.add(x % baseK, (y % baseK) + baseK, 1);
            W.add((x % baseK) + baseK, (y % baseK) + baseK, 1);
        } else {
            B.add(x % baseK, y % baseK, 1);
            B.add((x % baseK) + baseK, y % baseK, 1);
            B.add(x % baseK, (y % baseK) + baseK, 1);
            B.add((x % baseK) + baseK, (y % baseK) + baseK, 1);
        }
    }
    B.build();
    W.build();
    int ans = -1;
    int blackBase = B.query(0, 0, baseK, baseK);
    for (int i = 0; i < baseK; i++) {
        for (int j = 0; j < baseK; j++) {
            int white = 0, black = blackBase;
            white += W.query(i, j, i + K, j + K);
            black -= B.query(i, j, i + K, j + K);
            white += W.query(i + K, j + K, i + 2 * K, j + 2 * K);
            black -= B.query(i + K, j + K, i + 2 * K, j + 2 * K);
            ans = max(ans, white + black);
        }
    }
    cout << ans << endl;
}

