inline long count(
  const std::vector< std::vector<long> > &sum,
  long left, long right, long top, long bottom 
)
{
  ++left;
  ++right;
  ++top;
  ++bottom;

  return sum[bottom][right]
       + sum[top][left]
       - sum[bottom][left]
       - sum[top][right];
}

int main(int argc, char **argv)
{
  long N, K;
  std::cin >> N >> K;

  long M = 2 * K;

  std::vector< std::vector<bool> > table(M);
  for (long m = 0; m < M; ++m) {
    table[m] = std::vector<bool>(M, 0);
  }

  for (long n = 0; n < N; ++n) {
    long x, y;
    char color;
    std::cin >> x >> y >> color;

    if (color == 'B') {
      table[(y + 0) % M][x % M] = true;
    } else {
      table[(y + K) % M][x % M] = true;
    }
  }

  std::vector< std::vector<long> > sum(M + 1);
  for (long m = 0; m < M + 1; ++m) {
    sum[m] = std::vector<long>(M + 1, 0);
  }

  for (long y = 0; y < M; ++y) {
    for (long x = 0; x < M; ++x) {
      sum[y + 1][x + 1] = (table[y][x] ? 1 : 0) 
                        + sum[y + 1][x] 
                        + sum[y][x + 1] 
                        - sum[y][x];
    }
  }

  long max = 0;

  for (long py = 0; py < K; ++py) {
    for (long px = 0; px < K; ++px) {
      long S = 0;

      S += count(sum, 0, px, py, py + K);
      S += count(sum, px, px + K, 0, py);
      S += count(sum, px, px + K, py + K, M - 1);
      S += count(sum, px + K, M - 1, py, py + K);

      max = std::max(max, std::max(S, N - S));
    }
  }

  std::cout << max << std::endl;

  return 0;
}

