int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  ll N, K;
  cin >> N >> K;

  ll x, y;
  string c;
  ll cnt_b = 0;
  ll cnt_w = 0;

  for(int i = 0; i < N; i++){
    cin >> x >> y >> c;
    x = x % (2*K);
    y = y % (2*K);
    if(c == "B"){
      dist_b[x][y] += 1;
      cnt_b++;
    }else{
      dist_w[x][y] += 1;
      cnt_w++;
    }
  }

  sum_b[0][0] = dist_b[0][0];
  sum_w[0][0] = dist_w[0][0];

  for(int i = 1; i < 2 * K; i++){
    sum_b[0][i] = sum_b[0][i-1] + dist_b[0][i];
  }
  for(int i = 1; i < 2 * K; i++){
    sum_b[i][0] = sum_b[i-1][0] + dist_b[i][0];
  }

  for(int i = 1; i < 2 * K; i++){
    sum_w[0][i] = sum_w[0][i-1] + dist_w[0][i];
  }
  for(int i = 1; i < 2 * K; i++){
    sum_w[i][0] = sum_w[i-1][0] + dist_w[i][0];
  }


  for(int i = 1; i < 2 * K; i++){
    for(int j = 1; j < 2 * K; j++){
      sum_b[i][j] = sum_b[i-1][j] + sum_b[i][j-1] - sum_b[i-1][j-1] + dist_b[i][j];
      sum_w[i][j] = sum_w[i-1][j] + sum_w[i][j-1] - sum_w[i-1][j-1] + dist_w[i][j];      
    }
  }



  // for debug
  // for(int i = 0; i < 2 *K; i++){
  //   for(int j = 0; j < 2 *K; j++){
  //     if(dist[i][j] == 1) cout << "B";
