using namespace std;

template <class T> struct CumulativeSum2D {
    vector<vector<T>> data;

    CumulativeSum2D(int W, int H) : data(W + 1, vector<T>(H + 1, 0)) {}

    void add(int x, int y, T z) {
        ++x, ++y;
        if (x >= data.size() || y >= data[0].size())
            return;
        data[x][y] += z;
    }

    void build() {
        for (int i = 1; i < data.size(); i++) {
            for (int j = 1; j < data[i].size(); j++) {
                data[i][j] +=
                    data[i][j - 1] + data[i - 1][j] - data[i - 1][j - 1];
            }
        }
    }

    T query(int sx, int sy, int gx, int gy) {
        return (data[gx][gy] - data[sx][gy] - data[gx][sy] + data[sx][sy]);
    }
    T query1(int sx, int sy, int gx, int gy) {
        return (data[gx][gy] - data[sx][gy] - data[gx][sy] + data[sx][sy] * 2);
    }
};

int main() {
    int N, K;
    cin >> N >> K;

    // while[x][y] = マス(x, y)を右上とした長方形に
    //               含まれている(白マス-黒マス)の総数
    CumulativeSum2D<int16_t> sum(K, K);

    // 黒マスを指定する条件の数
    int bnum = 0;
    // まずは2K * 2Kの範囲に絞る
    for (int i = 0; i < N; ++i) {
        int x, y, z;
        char sc;
        cin >> x >> y >> sc;
        x %= K * 2;
        y %= K * 2;
        z = (sc == 'W');
        // K * Kの範囲に絞る
        // 座標をKで割った値の偶奇で色が変わる
        z += x / K + y / K;
        z %= 2;
        x %= K;
        y %= K;
        sum.add(x, y, (z ? 1 : -1));
        if (z == 0)
            ++bnum;
    }
    sum.build();

    int ans = 0;
    for (int x = 0; x < K; ++x) {
        for (int y = 0; y < K; ++y) {
            // (x, y)を右上の頂点とした長方形を白く塗るパターン
            int w = sum.query1(x, y, K - 1, K - 1) + bnum;
            ans = max(ans, max(w, N - w));
        }
    }

    cout << ans << endl;
    return 0;
}

