int main() {
    int N, K;
    cin >> N >> K;
    v2int field_black(K, vint(2 * K, 0));
    v2int field_white(K, vint(2 * K, 0));
    int white_num = 0; 
    int black_num = 0;
    rep(i, N) {
        int c, r;
        char t;
        cin >> c >> r >> t;

        c = (c) % (2 * K);
        r = (r) % (2 * K);
        if (c < K && r < K) {

        }
        else if (c < K && r >= K) {
            r = r - K;
            c = c + K;
        }
        else if (c >= K && r < K) {

        }
        else {
            r = r - K;
            c = c - K;
        }

        if (t == 'W') {
            field_white[r][c]++;
            white_num++;
        }
        else {
            field_black[r][c]++;
            black_num++;
        }
    }
    v2int Sb(K + 1, vint(2 * K + 1, 0));
    v2int Sw(K + 1, vint(2 * K + 1, 0));

    REP(i, 1,  K + 1) {
        REP(j, 1, 2 * K + 1) {
            Sb[i][j] = Sb[i - 1][j] + Sb[i][j - 1] - Sb[i - 1][j - 1] + field_black[i - 1][j - 1];
            Sw[i][j] = Sw[i - 1][j] + Sw[i][j - 1] - Sw[i - 1][j - 1] + field_white[i - 1][j - 1];
        }
    }

    int count_b, count_w;
    int max_score = 0;
    REP(i, 1, K + 2) {
        REP(j, 1, K + 2) {
            int Or = i - 1;
            int Er = min(i + K - 1, K);
            int Ec = min(j + K - 1, 2 * K);
            count_b = Sb[Er][Ec] - Sb[i - 1][Ec] - Sb[Er][j - 1] + Sb[i - 1][j - 1];
            count_w = Sw[Er][Ec] - Sw[i - 1][Ec] - Sw[Er][j - 1] + Sw[i - 1][j - 1];
            count_b += Sb[Or][j - 1];
            count_w += Sw[Or][j - 1];
            count_b += Sb[Or][2 * K] - Sb[0][2 * K] - Sb[Or][K + j - 1] + Sb[0][K + j - 1];
            count_w += Sw[Or][2 * K] - Sw[0][2 * K] - Sw[Or][K + j - 1] + Sw[0][K + j - 1];

            int score1 = count_b + (white_num - count_w);
            int score2 = count_w + (black_num - count_b);
            max_score = max(max(max_score, score1), score2);
        }
    }
    cout << max_score << endl;
    return 0;
}

