const int MAX = 100005;
const int SIZE = 1000;

int main() {
	int N, K;
	int w[SIZE][SIZE] = { {0} };
	int b[SIZE][SIZE] = { {0} };
	int wt[SIZE][SIZE] = { {0} };
	int bt[SIZE][SIZE] = { {0} };

	int ans = 0;
	int wn = 0;
	int bn = 0;

	cin >> N >> K;
	for (int i = 0; i < N; i++) {
		int x, y;
		char c;
		cin >> x >> y >> c;

		if ((x / K % 2 == 0) ^ (y / K % 2 == 0)) c = c == 'W' ? 'B' : 'W';

		if (c == 'W') {
			w[y % K][x % K] += 1;
			wn++;
		}
		else {
			b[y % K][x % K] += 1;
			bn++;
		}
	}

	ans = max(wn, max(ans, bn));

	for (int i = 0; i < SIZE; i++) {
		for (int j = 0; j < SIZE; j++) {
			if (i != 0) {
				wt[i][j] += wt[i - 1][j];
				bt[i][j] += bt[i - 1][j];
			}
			if (j != 0) {
				wt[i][j] += wt[i][j - 1];
				bt[i][j] += bt[i][j - 1];
			}
			if (i != 0 && j != 0) {
				wt[i][j] -= wt[i - 1][j - 1];
				bt[i][j] -= bt[i - 1][j - 1];
			}
			wt[i][j] += w[i][j];
			bt[i][j] += b[i][j];
		}
	}

	for (int i = 0; i < K; i++) {
		for (int j = 0; j < K; j++) {
			int w1 = wt[i][j];
			int w2 = wt[K - 1][K - 1] - ((wt[K - 1][j] - w1) + (wt[i][K - 1] - w1)) - w1;
			int b1 = bt[K - 1][j] - bt[i][j];
			int b2 = bt[i][K - 1] - bt[i][j];

