	int up = inrange(xl - 1, 0, 2 * k - 1) && inrange(yr, 0, 2 * k - 1) >= 0 ? mos[xl - 1][yr] : 0;
	int corner = inrange(xl - 1, 0, 2 * k - 1) && inrange(yl - 1, 0, 2 * k - 1) ? mos[xl - 1][yl - 1] : 0;
	int body = inrange(xr, 0, 2 * k - 1) && inrange(yr, 0, 2 * k - 1) ? mos[xr][yr] : 0;
	return body - left - up + corner;
