            ((x >= 0 && x < orig_x - K) && // 1-2
             (y >= orig_y && y < orig_y + K)) ||
            ((x >= orig_x && x < 2 * K) && // 3-2
             (y >= orig_y && y < orig_y + K)) ||
            ((x >= orig_x - K && x < orig_x ) && // 2-3
             (y >= orig_y + K && y < 2 * K)))
        {
            return true;
        }
    case HIGH_LEFT:
        if (((x >= orig_x && x < orig_x + K) && // 2-1
             (y >= 0 && y < orig_y - K)) ||
            ((x >= 0 && x < orig_x) && // 1-2
             (y >= orig_y - K && y < orig_y)) ||
            ((x >= orig_x + K && x < 2 * K) && // 3-2
             (y >= orig_y - K && y < orig_y)) ||
            ((x >= orig_x + K && x < orig_x + K) && // 2-3
             (y >= orig_y && y < 2 * K)))
        {
            return true;
        }
    case HIGH_RIGHT:
        if (((x >= 0 && x < orig_x - K) && // 1-1
             (y >= 0 && y < orig_y - K)) ||
            ((x >= 0 && x < orig_x - K) && // 1-3
             (y >= orig_y && y < 2 * K)) ||
            ((x >= orig_x - K && x < orig_x) && // 2-2
             (y >= orig_y - K && y < orig_y)) ||
            ((x >= orig_x && x < 2 * K) && // 3-1
             (y >= 0 && y < orig_y - K)) ||
            ((x >= orig_x && x < 2 * K) && // 3-3
             (y >= orig_y && y < 2 * K)))
        {
            return true;
        }
    default:
        break;
    }
    return false;
}
