    V<pair<ll, ll>> paint(N);
    REP(i, N) {
        ll x, y;
        char c;
        cin >> x >> y >> c;
        if (c == 'W') {
            paint[i] = mp((x + K) % (K * 2), y % (K * 2));
        } else {
            paint[i] = mp(x % (K * 2), y % (K * 2));
        }
    }

    V<V<ll>> score(K + 1, V<ll>(K + 1));
    REP(i, N) {
        ll x = paint[i].fst, y = paint[i].snd;

        ll lx = max(0LL, x - K);
        ll ly = max(0LL, y - K);

        ll ux = min(K, x);
        ll uy = min(K, y);

        score[lx][ly]++;
        score[ux][ly]--;
        score[lx][uy]--;
        score[ux][uy]++;
    }

    REP(i, K + 1) {
        ll sum = 0;
        REP(j, K + 1) {
            sum += score[i][j];
            score[i][j] = sum;
        }
    }

    REP(j, K + 1) {
        ll sum = 0;
        REP(i, K + 1) {
            sum += score[i][j];
            score[i][j] = sum;
        }
    }

    ll ans = 0;
    REP(i, K) {
        REP(j, K) {
            ans = max(ans, max(N - score[i][j], score[i][j]));
        }
    }

    cout << ans << endl;
    return 0;
}

