            v[x+1][k*2]--;
            v[k][0]--;
            v[k][y-k+1]++;
            v[k][y+1]--;
            v[k][k*2]++;
        } else {
            v[x+1][y-k+1]++;
            v[x+1][y+1]--;
            v[k][y-k+1]--;
            v[k][y+1]++;

            v[0][0]++;
            v[0][y-k+1]--;
            v[0][y+1]++;
            v[0][k*2]--;
            v[x+1][0]--;
            v[x+1][y-k+1]++;
