/*
 * 解説に乗っ取ってやる
 * 計算量を落とす方法が多分imos法
 *		4K * 4Kに範囲を拡張して、
 *		i番目の条件を満たせるような左下マスの集合のうち、K*Kの正方形の区間になるものだけを貼って、+1する方針
 */



// 各条件について、条件を満たす左下マスの集合のうちK*Kの正方形になる区間を探す
int hidarisita(std::vector<std::vector<int>> v, int K){
	// i番目の要求が成立するような領域の左下を出す
	std::vector<std::vector<int>> xy;
	// 初期化
	xy.resize(4 * K);
	for (size_t i = 0; i < xy.size(); i++) {
		for (size_t j = 0; j < 4 * K; j++) {
			xy[i].push_back(0);
		}
	}

	// 重みの加算
	for (size_t i = 0; i < v.size(); i++) {
		// 全ての左下を求める
		std::vector<int> x;
		std::vector<int> y;
		//for (size_t j = (v[i][0] + 1) % K; j < 4 * K; j+=K) {
			//x.push_back(j);
		//}
		//for (size_t j = (v[i][1] + 1) % K; j < 4 * K; j+=K) {
			//y.push_back(j);
		//}
        for (size_t j = (v[i][0] + 1); j < 4 * K; j+=K) {
            x.push_back(j);
        }
        for (size_t j = (v[i][1] + 1); j < 4 * K; j+=K) {
            y.push_back(j);
        }
		// K * Kになるものだけを重みに加算する
		for (size_t j = 0; j < x.size(); j++) {
			for (size_t k = 0; k < (y.size()+1)/2; k++) {
                int xx = x[j];
                int yy = y[k*2+k%2];
				xy[xx][yy]++;
				if (yy + K < 4 * K) {
					xy[xx][yy+K]--;
				}
				if (xx + K < 4 * K) {
					xy[xx+K][yy]--;
				}
				if (xx + K < 4 * K && yy + K < 4 * K) {
					xy[xx+K][yy+K]++;
				}
			}
		}
	}

    //for(int i=0;i<4*K;i++){
        //for(int j=0;j<4*K;j++){
            //cout << xy[i][j] << " ";
        //}
        //cout << endl;
    //}


	// 横方向への累積和
	for (size_t i = 0; i < xy.size(); i++) {
		for (size_t j = 1; j < xy[i].size(); j++) {
			xy[i][j] += xy[i][j-1];
		}
	}
	// 縦方向への累積和
	for (size_t i = 1; i < xy.size(); i++) {
		for (size_t j = 0; j < xy[i].size(); j++) {
			xy[i][j] += xy[i-1][j];
		}
	}

    //cout << endl << endl;

    //for(int i=0;i<4*K;i++){
        //for(int j=0;j<4*K;j++){
            //cout << xy[i][j] << " ";
        //}
        //cout << endl;
    //}

	// 最大値を調べる
	int banmax = -2000;
	for (size_t i = 0; i < xy.size(); i++) {
		for (size_t j = 0; j < xy[i].size(); j++) {
			banmax = max(banmax,xy[i][j]);
		}
	}

	return banmax;
}


