            checker[x][y]++;
            checker[x][k]--;
            checker[k][y]--;
            checker[k][k]++;
        } else {
            checker[0][y]++;
            checker[0][k]--;
            checker[x][y]--;
            checker[x][k]++;
            checker[x][0]++;
            checker[k][0]--;
            checker[x][y]--;
            checker[k][y]++;
        }
    }

    REP(i,k) REP(j,k) checker[i][j+1] += checker[i][j];
    REP(i,k) REP(j,k) checker[i+1][j] += checker[i][j];
    int mini = n;
    int maxi = 0;
    REP(i,k) { REP(j,k){
        mini = min(mini,checker[i][j]);
        maxi = max(maxi,checker[i][j]);
    } }
    cout << max(maxi,n-mini) << endl;
}

