int main() {
  int N, K;
  cin >> N >> K;
  vector<int> x(N), y(N);
  REP(i, N) {
    char c;
    cin >> x[i] >> y[i] >> c;
    if (c == 'W') {
      x[i] += K;
    }
    x[i] = x[i]%(2*K);
    y[i] = y[i]%(2*K);
    if (y[i] >= K) {
      x[i] += K;
      y[i] += K;
      x[i] = x[i]%(2*K);
      y[i] = y[i]%(2*K);
    }
  }

  vector<vector<int>> v(2*K+1, vector<int>(K+1, 0));
  REP(i, N) {
    v[x[i]][y[i]]++;
    v[x[i]][min(y[i]+K, K)]--;
    v[min(x[i]+K, 2*K)][y[i]]--;
    v[min(x[i]+K, 2*K)][min(y[i]+K, K)]++;

    if (x[i] <= K-1) {
      if (x[i] != 0 && y[i] != 0) {
        v[0][0]++;
        v[0][y[i]]--;
        v[x[i]][0]--;
        v[x[i]][y[i]]++;
      }
      if (y[i] != 0) {
        v[x[i]+K][0]++;
        v[x[i]+K][y[i]]--;
        v[2*K][0]--;
        v[2*K][y[i]]++;
      }
    } else {
      if (y[i] != 0) {
        v[x[i]-K][0]++;
        v[x[i]-K][y[i]]--;
        v[x[i]][0]--;
        v[x[i]][y[i]]++;
      }
      if (x[i] != K) {
        v[0][y[i]]++;
        v[0][K]--;
        v[x[i]-K][y[i]]--;
        v[x[i]-K][K]++;
      }
    }
  }

  FOR(j, 0, K+1) {
    FOR(i, 1, 2*K+1) {
      v[i][j] += v[i-1][j];
    }
  }

  FOR(i, 0, 2*K+1) {
    FOR(j, 1, K+1) {
      v[i][j] += v[i][j-1];
    }
  }

  int result = 0;
  REP(i,2*K) {
    REP(j, K) {
      if (result < v[i][j]) {
        result = v[i][j];
      }
    }
  }

  cout << result << endl;

  return 0;
}

