		B[i].resize(K);
		W[i].resize(K);
	}
	for (int i = 0; i < K + 1; ++i) {
		sumB[i].resize(K + 1);
		sumW[i].resize(K + 1);
	}
	for (int i = 0; i < N; ++i) {
		int x, y;
		char c;
		cin >> x >> y >> c;
		int flag = 0;
		x %= 2 * K;
		y %= 2 * K;
		if (K <= y) {
			y -= K;
			flag = 1 - flag;
		}
		if (K <= x) {
			x -= K;
			flag = 1 - flag;
		}
		if (flag != 0) {
			if (c == 'B') {
				c = 'W';
			}
			else {
				c = 'B';
			}
		}
		if (c == 'B') {
			B[x][y] += 1;
		}
		else {
			W[x][y] += 1;
		}
	}
	for (int x = 0; x < K + 1; ++x) {
		for (int y = 0; y < K + 1; ++y) {
			if (x == 0 || y == 0) {
				sumB[x][y] = 0;
				sumW[x][y] = 0;
			}
			else {
				sumB[x][y] = B[x - 1][y - 1] + sumB[x - 1][y] + sumB[x][y - 1] - sumB[x - 1][y - 1];
				sumW[x][y] = W[x - 1][y - 1] + sumW[x - 1][y] + sumW[x][y - 1] - sumW[x - 1][y - 1];
			}
		}
	}
	int res = 0;
	for (int x = 0; x < K + 1; ++x) {
		for (int y = 0; y < K + 1; ++y) {
			int nB0 = sumB[K][K] - sumB[K][y] - sumB[x][K] + sumB[x][y];
			int nB1 = sumB[K][y] + sumB[x][K] - sumB[x][y];
			int nW0 = sumW[K][K] - sumW[K][y] - sumW[x][K] + sumW[x][y];
			int nW1 = sumW[K][y] + sumW[x][K] - sumW[x][y];
			//
			MAX(res, nB0 + nW1);
			MAX(res, nB1 + nW0);
		}
	}

	cout << res << endl;
}

