typedef struct{
	int x;
	int y;
}Pt;


int main(void){

	int n, k;
	std::cin >> n >> k;

	std::vector<Pt> bPoints;
	bPoints.resize(n);

	int tmpX, tmpY;
	char tmpC;
	for(int i = 0; i < n; i++){
		std::cin >> tmpX >> tmpY >> tmpC;

		// 入力を全て黒への希望に変換する
		// この変換には[y][x]の白は[y+K][x]の黒と同じであることを利用している
		if(tmpC == 'W'){
			tmpY += k;
		}

		// [y][x]の色と[y+2k][x]、[y][x+2k]の色は一致するので
		// 0 <= x,y <= 2kの間に座標を変換できる
		bPoints[i].y = tmpY % (2 * k);
		bPoints[i].x = tmpX % (2 * k);
	}

	int maxWish = 0;
	int wish;
	Pt diff;

	// 市松模様の黒い部分の左下マスが[0,2k)×[0,2k)の中に含まれる全てのパターンを試す
	for(int y = 0; y < 2 * k; y++){
		for(int x = 0; x < 2 * k; x++){

//			std::cout << "Next = " << x << " : " << y << std::endl;

			wish = 0;
			for(int i = 0; i < n; i++){
				diff.x = bPoints[i].x - x;
				diff.y = bPoints[i].y - y;

				// いるエリアの左下に移動
				diff.x -= (diff.x >= 0) ? (diff.x % k) : ((k - (std::abs(diff.x) % k)) % k);
				diff.y -= (diff.y >= 0) ? (diff.y % k) : ((k - (std::abs(diff.y) % k)) % k);

				diff.x = std::abs(diff.x) % (2 * k);
				diff.y = std::abs(diff.y) % (2 * k);
//				std::cout << diff.x << " : " << diff.y << std::endl;
				if(diff.x == 0 && diff.y == 0 ||
				   diff.x == k && diff.y == k){
					wish++;
				}
			}
//			std::cout << "Wish = " << wish << std::endl << std::endl;

			if(maxWish < wish){
				maxWish = wish;
			}
		}
	}

	std::cout << maxWish << std::endl;

	return 0;
}

