    P.push_back({x % (2*K), y % (2*K), (c=='B') ? 0 : 1});
  }

  vector<vector<int>> OK(K, vector<int>(K)), NG = OK;
  for(auto p: P) {
    for(auto i = 0; i < K; ++i) for(auto j = 0; j < K; ++j) {
      auto c = 0;
      if(p.y < i || i+K <= p.y) c ^= 1;
      if(p.x < j || j+K <= p.x) c ^= 1;
      if(p.c == c) ++OK[i][j];
      else         ++NG[i][j];
    }
  }

  auto res = 0;
  for(auto i = 0; i < K; ++i) for(auto j = 0; j < K; ++j) res = max({res, OK[i][j], NG[i][j]});
