int main(){
    int n, k;
    cin >> n >> k;

    vector<vector<int>> grid(3*k, vector<int>(3*k));
    for(int i=0; i<n; i++){
        int x, y;
        char c;
        cin >> x >> y >> c;

        if(c == 'W') y += k;
        x %= 2*k;
        y %= 2*k;

        // RU corner of black squares containing (x,y)
        grid[x][y]     += 1;
        grid[x+k][y]   -= 1;
        grid[x][y+k]   -= 1;
        grid[x+k][y+k] += 1;
    }

    // cumulative sum
    for(int i=0; i<3*k; i++){
        for(int j=0; j<3*k-1; j++){
            grid[i][j+1] += grid[i][j];
        }
    }
    for(int j=0; j<3*k; j++){
        for(int i=0; i<3*k-1; i++){    
            grid[i+1][j] += grid[i][j];
        }
    }

    vector<vector<int>> grid_resize(2*k, vector<int>(2*k));
    for(int i=0; i<3*k; i++){
        for(int j=0; j<3*k; j++){
            grid_resize[i%(2*k)][j%(2*k)] += grid[i][j];
        }
    }

    int ans = 0;
    for(int i=0; i<2*k; i++){
        for(int j=0; j<2*k; j++){
            ans = max(ans, grid_resize[i][j] + grid_resize[(i+k)%(2*k)][(j+k)%(2*k)]);
        }
    }
    cout << ans << endl;
    return 0;
}

