int main() {
    ll n, k;
    cin >> n >> k;
    vvl black(2 * k, vl(2 * k, 0));
    ll nw = 0;
    // vvl white(2 * k, vl(2 * k, 0));
    for (int i = 0; i < n; ++i) {
        ll x, y;
        char c;
        cin >> x >> y >> c;
        bool flip = (x / k + y / k) % 2 == 1;
        if ((flip && c == 'B') || (!flip && c == 'W')) {
            nw++;
            black[y % k][x % k]--;
        } else
            black[y % k][x % k]++;
    }
    for (int i = 1; i < 2 * k; ++i) {
        for (int j = 0; j < 2 * k; ++j) {
            // white[i][j] += white[i - 1][j];
            black[i][j] += black[i - 1][j];
        }
    }
    for (int i = 1; i < 2 * k; ++i) {
        for (int j = 0; j < 2 * k; ++j) {
            // white[j][i] += white[j][i - 1];
            black[j][i] += black[j][i - 1];
        }
    }
    ll ret = 0;
    for (int i = 0; i < k; ++i) {
        for (int j = 0; j < k; ++j) {
            ll temp = nw;
            temp += black[i + k - 1][j + k - 1];
            if (i > 0)
                temp -= black[i - 1][j + k - 1];
            if (j > 0)
                temp -= black[i + k - 1][j - 1];
            if (i > 0 && j > 0)
                temp += 2 * black[i - 1][j - 1];
            ll temp2 = n - nw - temp;
            chmax(ret, temp);
            chmax(ret, temp2);
        }
    }
    cout << ret << "\n";
    return 0;
}

