using namespace std;
typedef long long ll;

ll count_rect(const vector<vector<ll>>& cs,
              ll x1, ll y1, ll x2, ll y2){
    x1 = min(max(x1, 0LL), (ll)cs.size() - 1LL);
    x2 = min(max(x2, 0LL), (ll)cs.size() - 1LL);
    y1 = min(max(y1, 0LL), (ll)cs.front().size() - 1LL);
    y2 = min(max(y2, 0LL), (ll)cs.front().size() - 1LL);
    ll ret = cs.at(x2).at(y2) - cs.at(x1).at(y2) - cs.at(x2).at(y1)
        + cs.at(x1).at(y1);
    assert(ret >= 0);
    return ret;
}

int main(){
    ll n, k;
    cin >> n >> k;
    const ll m = 2 * k;
    vector<vector<ll>> map[2];
    map[0].resize(m, vector<ll>(m, 0LL));
    map[1].resize(m, vector<ll>(m, 0LL));
    for(int i = 0; i < n; ++i){
        ll x, y;
        char c;
        cin >> x >> y >> c;
        if(c == 'W'){
            map[0].at(x % m).at(y % m)++;
        }else{
            map[1].at(x % m).at(y % m)++;
        }
    }

    vector<vector<ll>> cs[2];
    cs[0].resize(m + 1, vector<ll>(m + 1, 0LL));
    cs[1].resize(m + 1, vector<ll>(m + 1, 0LL));
    for(int c = 0; c < 2; ++c){
        for(int i = 1; i <= m; ++i){
            for(int j = 1; j <= m; ++j){
                cs[c].at(i).at(j) = 
                    cs[c].at(i).at(j - 1) + cs[c].at(i - 1).at(j)
                    - cs[c].at(i - 1).at(j - 1) + map[c].at(i - 1).at(j - 1);
            }
        }
    }

    ll ans = 0;
    for(ll c = 0; c < 2; ++c){
        for(ll i = 0; i <= m; ++i){
            for(ll j = 0; j <= m; ++j){
                ll tmp = 0;
                tmp += count_rect(cs[c], i, j, i + k, j + k);
                tmp += count_rect(cs[c], i + k, j + k, i + 2 * k, j + 2 * k);
                tmp += count_rect(cs[c], i - k, j - k, i, j);
                tmp += count_rect(cs[c], i + k, j - k, i + 2 * k, j);
                tmp += count_rect(cs[c], i - k, j + k, i, j + 2 * k);

                tmp += count_rect(cs[1 - c], i - k, j, i, j + k);
                tmp += count_rect(cs[1 - c], i, j - k, i + k, j);
                tmp += count_rect(cs[1 - c], i, j + k, i + k, j + 2 * k);
                tmp += count_rect(cs[1 - c], i + k, j, i + k, j + 2 * k);
                ans = max(ans, tmp);
            }
        }
    }
    cout << ans << endl;
    return 0;
}

