int N, K;
int acc[2010][2010];


void makeAcc(){
	repe(i, 1, 2*K)
		repe(j, 1, 2*K) acc[i][j] += acc[i][j-1];
	repe(i, 1, 2*K)
		repe(j, 1, 2*K) acc[i][j] += acc[i-1][j];
}


int solve(){
	int ans = 0;
	repe(i, 0, K){
		repe(j, 0, K){
			int a = acc[i][j];
			int b = acc[i+K][j+K]-acc[i+K][j]-acc[i][j+K]+acc[i][j];
			int c = acc[2*K][j]-acc[i+K][j];
			int d = acc[i][2*K]-acc[i][j+K];
			int e = acc[2*K][2*K]-acc[2*K][j+K]-acc[i+K][2*K]+acc[i+K][j+K];
			int cnt = a+b+c+d+e;
			ans = max(ans, cnt);
		}
	}
	return ans;
}


signed main(){
	cin >> N >> K;
	rep(i, 0, N){
		int x, y;
		char c;
		cin >> x >> y >> c;
		if(c == 'W') y += K;
		acc[y%(2*K)+1][x%(2*K)+1]++;
	}

	makeAcc();

	cout << solve() << endl;

	return 0;
}

#include <bits/stdc++.h>

using namespace std;
typedef long long ll;
typedef pair<ll,ll> P;

ll N,K;
ll w[1010][1010];
ll b[1010][1010];

void sets(ll x, ll y, char c){
    int f = 1;
    if(c == 'B') f *= -1;
    if((x / K)%2 == 1) f *= -1;
    x %= K;
    if((y / K)%2 == 1) f *= -1;
    y %= K;
    if(f > 0) w[x][y]++;
    else b[x][y]++;
}

ll W(ll a, ll bb, ll c, ll d){
    if(a > c || bb > d) return 0;
    ll ret = w[c][d];
    if(a > 0) ret -= w[a-1][d];
    if(bb > 0) ret -= w[c][bb-1];
    if(a>0 && bb>0) ret += w[a-1][bb-1];
    return ret;
}

ll B(ll a, ll bb, ll c, ll d){
    if(a > c || bb > d) return 0;
    ll ret = b[c][d];
    if(a > 0) ret -= b[a-1][d];
    if(bb > 0) ret -= b[c][bb-1];
    if(a>0 && bb>0) ret += b[a-1][bb-1];
    return ret;
}

ll get(ll x, ll y){
    return W(0,0,x-1,y-1) + W(x,y,K-1,K-1) + B(0,y,x-1,K-1) + B(x,0,K-1,y-1);
}

int main(){
    cin >> N >> K;
    for(int i=0;i<N;i++){
        ll x,y;
        char c;
        cin >> x >> y >> c;
        sets(x,y,c);
    }

    for(int i=0;i<K;i++){
        for(int j=0;j<K;j++){
            if(i>0){
                w[i][j] += w[i-1][j];
                b[i][j] += b[i-1][j];
            }
            if(j>0){
                w[i][j] += w[i][j-1];
                b[i][j] += b[i][j-1];
            }
            if(i>0 && j>0){
                w[i][j] -= w[i-1][j-1];
                b[i][j] -= b[i-1][j-1];
            }
        }
    }

    ll max_v = 0;
    for(int i=0;i<K;i++){
        for(int j=0;j<K;j++){
            max_v = max(max_v, get(i,j));
        }
    }
    max_v = max(max_v, B(0,0,K-1,K-1));
    cout << max_v << endl;
    return 0;
}

