            sum += get_sum(B, i + K, j, size, j + K);
            sum += get_sum(B, i, j + K, i + K, size);
            chmax(ans, sum);
        }
    }
    for (int i = 0; i <= K; i++) {
        for (int j = 0; j <= K; j++) {
            int sum = 0;
