int getSquare(int x, int y, int xx, int yy) {
  if (xx < 0 || yy < 0) return 0;
  int ans = a[xx][yy];
  if (x > 0) ans -= a[x - 1][yy];
  if (y > 0) ans -= a[xx][y - 1];
  if (x > 0 && y > 0) ans += a[x - 1][y - 1];
  return ans;
}

int main() {
  ios_base::sync_with_stdio(0);

  cin >> n >> k;
  for (i = 1; i <= n; ++i) {
    cin >> x >> y >> c;
    if (c == 'B') y += k;
    x %= 2 * k;
    y %= 2 * k;
    ++a[x + 1][y + 1];
  }

  for (i = 1; i < N; ++i)
    for (j = 1; j < N; ++j)
      a[i][j] += a[i - 1][j] + a[i][j - 1] - a[i - 1][j - 1];

  for (i = 1; i <= 2 * k; ++i)
    for (j = 1; j <= 2 * k; ++j) {
      int aux = getSquare(i - k + 1, j - k + 1, i, j);
      aux += getSquare(i - 2 * k + 1, j - 2 * k + 1, i - k, j - k);
      aux += getSquare(i - 2 * k + 1, j + 1, i - k, j + k);
      aux += getSquare(i + 1, j - 2 * k + 1, i + k, j - k);
      aux += getSquare(i + 1, j + 1, i + k, j + k);
      rs = max(rs, aux);
    }

  cout << rs << '\n';

  return 0;
}

