template< typename T >
struct imos2D {
	vector< vector< T > > data;
	int _H, _W;

	imos2D(int H, int W) {
		_H = H; _W = W;
		data.assign(H + 1, vector< T >(W + 1, 0));
	}

	void add(int y, int x, int value = 1) {
		data[y + 1][x + 1] += value;
	}

	void build() {
		for (int i = 0; i <= _H; i++) {
			for (int j = 0; j < _W; j++) {
				data[i][j + 1] += data[i][j];
			}
		}
		for (int j = 0; j <= _W; j++) {
			for (int i = 0; i < _H; i++) {
				data[i + 1][j] += data[i][j];
			}
		}
	}

	///x1 - x2, y1 - y2
	T query(int x1, int y1, int x2, int y2) {
		return data[y2][x2] - data[y1][x2] - data[y2][x1] + data[y1][x1];
	}
};

