			lint curr = 0;
			curr += dt.query(0, 0, i, j);
			curr += dt.query(i + K, 0, 2 * K, j);
			curr += dt.query(0, j + K, i, 2 * K);
			curr += dt.query(i, j, i + K, j + K);
			curr += dt.query(i + K, j + K, 2 * K, 2 * K);
			chmax(maxv, max(N - curr, curr));
		}
	}
	cout << maxv << endl;
}

