int fcn(int x1, int y1, int x2, int y2){
    if(x1==0 && y1==0) return d[x2][y2];
    if(x1>0 && y1==0) return d[x2][y2]-d[x1-1][y2];
    if(x1==0 && y1>0) return d[x2][y2]-d[x2][y1-1];
    return d[x2][y2]-d[x2][y1-1]-d[x1-1][y2]+d[x1-1][y1-1];
}

int main(){
    int n, k;
    cin >> n >> k;
    ll x[n], y[n];
    for(int i=0; i<n; i++){
        char c;
        cin >> x[i] >> y[i] >> c;
        if(c=='W') x[i]+=k;
        x[i]%=2*k;
        y[i]%=2*k;
    }

    for(int i=0; i<n; i++){
        d[x[i]][y[i]]++;
    }
    for(int i=0; i<2*k; i++){
        for(int j=1; j<2*k; j++){
            d[i][j]+=d[i][j-1];
        }
    }
    for(int j=0; j<2*k; j++){
        for(int i=1; i<2*k; i++){
            d[i][j]+=d[i-1][j];
        }
    }

    int ans=0;
    for(int i=0; i<=k; i++){
        for(int j=0; j<=k; j++){
            int s=fcn(i, j, i+k-1, j+k-1);
            if(i<k && j<k) s+=fcn(i+k, j+k, 2*k-1, 2*k-1);
            if(i>0 && j>0) s+=fcn(0, 0 , i-1, j-1);
            if(i>0 && j<k) s+=fcn(0, j+k, i-1, 2*k-1);
            if(i<k && j>0) s+=fcn(i+k, 0, 2*k-1, j-1);
            ans=max(ans, s);
        }
    }
    cout << ans << endl;
    return 0;
}

