#include <bits/stdc++.h>
using namespace std;

class ruiseki2D
{
private:
  vector< vector< int > > data;
public:
  ruiseki2D(int W, int H)
  {
      data = vector<vector<int>>(W+1,std::vector<int>(H + 1,0));
  };

  void add(int x, int y, int z)
  {
    ++x, ++y;
    if(x >= data.size() || y >= data[0].size()) return;
    data[x][y] += z;
  }

  void build()
  {
    for(int i = 1; i < data.size(); i++) {
      for(int j = 1; j < data[i].size(); j++) {
        data[i][j] += data[i][j - 1] + data[i - 1][j] - data[i - 1][j - 1];
      }
    }
  }

  int query(int sx, int sy, int gx, int gy)
  {
    return (data[gx][gy] - data[sx][gy] - data[gx][sy] + data[sx][sy]);
  }
};
int main()
{
    int N,K;cin >> N >> K;
    ruiseki2D rui(3*K,3*K);
    for(int a = 0;a < N;a++){
        int b,c;cin >> b >> c;
        char w;cin >> w;
        if((b/K + c/K)%2 == 0){
            if(w == 'B'){
                rui.add(b%K,c%K+K,1);
            }else{
                rui.add(b%K,c%K,1);
            }
        }else{
            if(w == 'W'){
                rui.add(b%K,c%K+K,1);
            }else{
                rui.add(b%K,c%K,1);
            }
        }
    }
    rui.build();
    int ans = -1;
    for(int a = 0;a <= K;a++){
        for(int b = 0;b <= K;b++){
            ans = max(ans, rui.query(a,b,a+K,b+K) + rui.query(max(0,a-K),max(0,b-K),a,b));
        }
    }
    cout<<ans<<endl;
    return 0;
}

