const int N=(int)2e3+5;
const int mod=(int)1e9+7;
int black[N][N], white[N][N];
pii solve(int I, int J, int i, int j){

    int b = black[I][J]-black[max(i-1,0)][J]-black[I][max(j-1,0)]+black[max(i-1,0)][max(j-1,0)];
    int w = white[I][J]-white[max(i-1,0)][J]-white[I][max(j-1,0)]+white[max(i-1,0)][max(j-1,0)];
    return m_p(b,w);
}
int main()
{
    ios_base::sync_with_stdio(false); cout.setf(ios::fixed); cout.precision(100); cout.tie(nullptr); cin.tie(nullptr);
    #ifdef shaft
        freopen("in.txt","r",stdin);
        //freopen("out.txt","w",stdout);
    #endif ///shaft
    int n, k;
    while(cin >> n >> k){
        clr(black);
        clr(white);
        int black_tot = 0, white_tot = 0;
        int K = k+k;
        for(int i = 0; i < n; i++){
            int x, y, X, Y;
            char ch;
            cin >> x >> y >> ch;
            if(ch == 'W'){
                x %= K; y %= K;
                x += 1; y += 1;
                white[x][y] += 1;
                white_tot += 1;
                continue;
            }
            x %= K; y %= K;
            x += 1; y += 1;
            black[x][y] += 1;
            black_tot += 1;
        }
        for(int i = 1; i <= K; i++){
            for(int j = 1; j <= K; j++){
                int x = black[i-1][j] + black[i][j-1] - black[i-1][j-1];
                int y = white[i-1][j] + white[i][j-1] - white[i-1][j-1];
                black[i][j] += x;
                white[i][j] += y;
            }
        }
        int res = 0;
        for(int i = 1; i <= k+1; i++){
            for(int j = 1; j <= k+1 ; j++){
                int I = i+k-1, J = j+k-1;
                int b = black[I][J]-black[i-1][J]-black[I][j-1]+black[i-1][j-1];
                int w = white[I][J]-white[i-1][J]-white[I][j-1]+white[i-1][j-1];
                pii dan = solve(K,J,I+1,j);
                pii bam = solve(i-1,J,1,j);
                pii upor = solve(I,K,i,J+1);
                pii nich = solve(I,j-1,i,1);
                int temp_b = b+dan.ss+bam.ss+upor.ss+nich.ss + (black_tot-b-dan.ff-bam.ff-upor.ff-nich.ff);
                int temp_w = w+dan.ff+bam.ff+upor.ff+nich.ff + (white_tot-w-dan.ss-bam.ss-upor.ss-nich.ss);
                //cout << i <<" "<<j<<" "<<I<<" "<<J<<" "<<b<<" "<<w <<endl;
                int temp = max(temp_b,temp_w);
                res = res < temp ? temp : res;
            }
        }
        cout << res << endl;
    }
    return 0;
}

