void prepare() {
    rep(i, K * 2 + 3) {
        rep(j, K * 2 + 3) {
            sum[i+1][j+1] = dots[i+1][j+1] + sum[i][j+1] + sum[i+1][j] - sum[i][j];
        }
    }
}

int query(int x1, int y1, int x2, int y2) {
    if (x1 > x2 || y1 > y2) return 0;
    else return sum[x2][y2] - sum[x1-1][y2] - sum[x2][y1-1] + sum[x1-1][y1-1];
}

int main(void)
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N >> K;
    int x, y;
    char c;
    rep(i, N) {
        cin >> x >> y >> c;
        if (c == 'W') x += K;
        x %= K * 2;
        y %= K * 2;

        dots[x+1][y+1]++;
    }
    prepare();
    /*
