            cout << sum[j][i];
        }
        cout << endl;
    }
    */

    int ans = 0;
    int tmp;
    REP(x, 1, K) {
        REP(y, 1, K) {
            tmp =   query(x    , y    , x+K-1, y+K-1)
                  + query(x + K, y + K, K * 2, K * 2)
                  + query(1    , 1    , x - 1, y - 1)
                  + query(x + K, 1    , K * 2, y - 1)
                  + query(1    , y + K, x - 1, K * 2);
            //dump(tmp);
            ans = max(ans, max(tmp, N-tmp));
        }
    }
    cout << ans << endl;

    return 0;
}

