int get(int lx,int ly,int rx,int ry){
	if(lx>rx || ly>ry) return 0;
	return sum[rx][ry]-sum[rx][ly-1]-sum[lx-1][ry]+sum[lx-1][ly-1];
}
int main(){
	ios_base::sync_with_stdio(0);
	cin>>n>>k;
	for(int i=1;i<=n;i++){
		cin>>x[i]>>y[i]>>c[i];
