			sum[i][j]=sum[i-1][j]+sum[i][j-1]-sum[i-1][j-1]+fl[i][j];
		}
	}
	for(int i=1;i<=k;i++){
		for(int j=1;j<=k;j++){
			int val=get(1,1,i,j)+get(i+k+1,1,2*k,j)+get(1,j+k+1,i,2*k)+get(i+1,j+1,i+k,j+k);
			ans=max(ans,max(val,n-val));
			//cout<<val<<" ";
		}
		//cout<<endl;
	}
	cout<<ans;
}

