int main(){
    INT(N);INT(K);
    int table[1000][1000] = {};

    if(K == 1) while(1){}

    REP1(i, N){
        char c;
        INT(x);INT(y);INPUT(c);

        if((x % (2*K) >= K && y % (2*K) < K ) || (y % (2*K) >= K && x % (2*K) < K )){
            c = (c == 'W')? 'B': 'W';
        }

        x %= K;
        y %= K;

        if(c == 'W'){

            table[y][0]++;
            if(x+1 != K){
                table[y][x+1] -= 2;
                table[K-1][x+1]++;
            }
        }else{
            table[K-1][0]++;

            table[y][0]--;
            if(x+1 != K){
                table[y][x+1] += 2;
                table[K-1][x+1]--;
            }
        }
    }

    //累積和
    REP1(i,K){
        REP1(j,K-1){
            table[i][j+1] += table[i][j];
        }
    }
    REP1(j,K){
        RREP1(i,K-1){
            table[i][j] += table[i+1][j];
        }
    }

    int maxx = 0;

    REP1(i,K){
        REP1(j,K){
            maxx = max(table[i][j], maxx);
        }
    }

    cout << maxx << endl;

    return 0;
}

