            int bla=calb(i-k+1,j-k+1,i,j)+calb(1,1,i-k,j-k)+calb(1,j+1,i-k,2*k)+calb(i+1,1,2*k,j-k)+calb(i+1,j+1,2*k,2*k);
            ans=max(ans,whi+black-bla);
            ans=max(ans,bla+white-whi);
        }
    }
    printf("%d\n",ans);
    return 0;
}

