int getB(int x, int y, int u, int v) {
    if (x > u || y > v) return 0;
    if (isOutside(x, y) && isOutside(u, v)) return 0;
    x = max(x, 1); x = min(x, 2*k);
    y = max(y, 1); y = min(y, 2*k);
    u = max(u, 1); u = min(u, 2*k);
    v = max(v, 1); v = min(v, 2*k);
    return b[u][v] - b[x-1][v] - b[u][y-1] + b[x-1][y-1];
}

int getW(int x, int y, int u, int v) {
    if (x > u || y > v) return 0;
    if (isOutside(x, y) && isOutside(u, v)) return 0;
    x = max(x, 1); x = min(x, 2*k);
    y = max(y, 1); y = min(y, 2*k);
    u = max(u, 1); u = min(u, 2*k);
    v = max(v, 1); v = min(v, 2*k);
    return w[u][v] - w[x-1][v] - w[u][y-1] + w[x-1][y-1];
}

