int b_acc[2001][2001], w_acc[2001][2001];
int main() {
  int n, k;
  cin>>n>>k;
  int x[n], y[n];
  char c[n];
  for (int i=0; i<n; i++) cin>>x[i]>>y[i]>>c[i];
  for (int i=0; i<2*k; i++) {
    for (int j=0; j<2*k; j++) {
      b[i][j] = 0;
      w[i][j] = 0;
    }
  }
  for (int i=0; i<n; i++) {
    if (c[i] == 'W') {
      ++w[x[i]%(2*k)][y[i]%(2*k)];
    } else {
      ++b[x[i]%(2*k)][y[i]%(2*k)];
    }
  }
  for (int i=0; i<2*k; i++) {
    b_acc[i][0] = 0;
    w_acc[i][0] = 0;
    b_acc[0][i] = 0;
    w_acc[0][i] = 0;
  }
  for (int i=0; i<2*k; i++) {
    for (int j=0; j<2*k; j++) {
      b_acc[i+1][j+1] = b_acc[i+1][j] + b_acc[i][j+1] - b_acc[i][j] + b[i][j];
      w_acc[i+1][j+1] = w_acc[i+1][j] + w_acc[i][j+1] - w_acc[i][j] + w[i][j];
    }
  }

  int ans = 0;
  for (int i=k-1; i<2*k; i++) {
    for (int j=k-1; j<2*k; j++) {
      int cnt = b_acc[2*k][2*k];
      cnt += w_acc[i][j] - w_acc[max(i-k+1, 0)][j] - w_acc[i][max(j-k+1, 0)] + w_acc[max(i-k+1, 0)][max(j-k+1, 0)];
      cnt -= b_acc[i][j] - b_acc[max(i-k+1, 0)][j] - b_acc[i][max(j-k+1, 0)] + b_acc[max(i-k+1, 0)][max(j-k+1, 0)];

      cnt += w_acc[min(i+k, 2*k)][min(j+k, 2*k)] - w_acc[min(i+k, 2*k)][j+1] - w_acc[i+1][min(j+k, 2*k)] + w_acc[i+1][j+1];
      cnt -= b_acc[min(i+k, 2*k)][min(j+k, 2*k)] - b_acc[min(i+k, 2*k)][j+1] - b_acc[i+1][min(j+k, 2*k)] + b_acc[i+1][j+1];

      if (i - k > 0) {
        cnt += w_acc[i-k][min(j+k, 2*k)] - w_acc[max(i-2*k+1, 0)][j+1] - w_acc[i-k][min(j+k, 2*k)] + w_acc[max(i-2*k+1, 0)][j+1];
        cnt -= b_acc[i-k][min(j+k, 2*k)] - b_acc[max(i-2*k+1, 0)][j+1] - b_acc[i-k][min(j+k, 2*k)] + b_acc[max(i-2*k+1, 0)][j+1];
      }
      if (j - k > 0) {
        cnt += w_acc[min(i+k, 2*k)][j-k] - w_acc[i+1][j-k] - w_acc[i+1][max(j-2*k+1, 0)] + w_acc[i+1][max(j-2*k, 0)];
        cnt -= b_acc[min(i+k, 2*k)][j-k] - b_acc[i+1][j-k] - b_acc[i+1][max(j-2*k+1, 0)] + b_acc[i+1][max(j-2*k, 0)];
      }
      if (i - k > 0 && j - k > 0) {
        cnt += w_acc[i-k][j-k] - w_acc[max(i-2*k+1, 0)][j-k] - w_acc[i-k][max(j-2*k+1, 0)] + w_acc[max(i-2*k+1, 0)][max(j-2*k+1, 0)];
        cnt -= b_acc[i-k][j-k] - b_acc[max(i-2*k+1, 0)][j-k] - b_acc[i-k][max(j-2*k+1, 0)] + b_acc[max(i-2*k+1, 0)][max(j-2*k+1, 0)];
      }
      ans = max(cnt, ans);
    }
  }
  cout<<ans<<endl;
}

