template <class T> vector<T> make_v(size_t size, const T& init) { return vector<T>(size, init); }
template <class... Ts> auto make_v(size_t size, Ts... rest) { return vector<decltype(make_v(rest...))>(size, make_v(rest...)); }
/* clang-format on */

int getSum(const vec<int, 2>& sum, int y, int x, int K, int parity) {
  int ys[3] = {y, y + K, 2 * K};
  int xs[3] = {x, x + K, 2 * K};
  int res = 0;
  for (int i = 0; i < 3; i++) {
    for (int j = 0; j < 3; j++) {
      if ((i + j) % 2 == parity) {
        int cnt = sum[ys[i]][xs[j]];
        if (i > 0) cnt -= sum[ys[i - 1]][xs[j]];
        if (j > 0) cnt -= sum[ys[i]][xs[j - 1]];
        if (i > 0 && j > 0) cnt += sum[ys[i - 1]][xs[j - 1]];
        res += cnt;
      }
    }
  }
  return res;
}

void sum2d(vec<int, 2>& sum) {
  int H = sum.size(), W = sum[0].size();
  for (int i = 1; i < H; i++)
    for (int j = 1; j < W; j++)
      sum[i][j] += sum[i - 1][j] + sum[i][j - 1] - sum[i - 1][j - 1];
}

int main() {
  int N, K;
  while (cin >> N >> K) {
    vec<int, 2> sumB = make_v(2 * K + 1, 2 * K + 1, 0);
    vec<int, 2> sumW = make_v(2 * K + 1, 2 * K + 1, 0);
    for (int i = 0; i < N; i++) {
      int x, y;
      char c;
      cin >> x >> y >> c;
      x %= 2 * K;
      y %= 2 * K;
      if (c == 'B') {
        ++sumB[x + 1][y + 1];
      } else {
        ++sumW[x + 1][y + 1];
      }
    }
    sum2d(sumB);
    sum2d(sumW);
    int res = 0;
    for (int y = 0; y <= K; y++) {
      for (int x = 0; x <= K; x++) {
        int score1 = getSum(sumB, y, x, K, 0) + getSum(sumW, y, x, K, 1);
        res = max(res, score1);
        int score2 = getSum(sumW, y, x, K, 0) + getSum(sumB, y, x, K, 1);
        res = max(res, score2);
      }
    }
    cout << res << endl;
  }
  return 0;
}

