    for (int j = 1; j <= 2 * k; ++j) {
      a[i][j] += a[i - 1][j] + a[i][j - 1] - a[i - 1][j - 1];
    }
  }

  int ans = 0;
  for (int i = 0; i <= k; ++i) {
    for (int j = 0; j <= k; ++j) {
      chmax(ans, max(n - query(i, j), query(i, j)));
    }
  }

  cout << ans << endl;
}

