ll N, K;

/* ------------- Functions -------------- */

void paint(ll x, ll y, V<V<ll>>& score) {
    ll lx = max(0LL, x - K + 1);
    ll ly = max(0LL, y - K + 1);

    ll ux = min(K, x + 1);
    ll uy = min(K, y + 1);

    score[lx][ly]++;
    score[ux][ly]--;
    score[lx][uy]--;
    score[ux][uy]++;
}

/* ----------- Main Function ------------ */

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N >> K;

    V<pair<ll, ll>> black(N);
    REP(i, N) {
        ll x, y;
        char c;
        cin >> x >> y >> c;
        if (c == 'W') {
            x += K;
        }
        black[i] = mp(x % (K * 2), y % (K * 2));
    }

    V<V<ll>> score(K + 1, V<ll>(K + 1));
    REP(i, N) {
        ll x = black[i].fst, y = black[i].snd;
        paint(x, y, score);
        paint((x + K) % (2 * K), (y + K) % (2 * K), score);
    }

    REP(i, K + 1) {
        ll sum = 0;
        REP(j, K + 1) {
            sum += score[i][j];
            score[i][j] = sum;
        }
    }

    REP(j, K + 1) {
        ll sum = 0;
        REP(i, K + 1) {
            sum += score[i][j];
            score[i][j] = sum;
        }
    }

    ll ans = 0;
    REP(i, K) {
        REP(j, K) {
            ans = max(ans, max(N - score[i][j], score[i][j]));
        }
    }

    cout << ans << endl;
    return 0;
}

