#include <bits/stdc++.h>

int main() {
  int64_t n, k;
  std::cin >> n >> k;
  std::vector<std::vector<int64_t>>
  b(2 * k, std::vector<int64_t>(2 * k, 0)),
  w(2 * k, std::vector<int64_t>(2 * k, 0));

  for (int64_t i = 0; i < n; i++) {
    int64_t x, y;
    char c;
    std::cin >> x >> y >> c;

    if (c == 'B') {
      b[x % (2 * k)][y % (2 * k)]++;
    } else {
      w[x % (2 * k)][y % (2 * k)]++;
    }
  }

  for (int i = 0; i < 2 * k; i++) {
    for (int j = 1; j < 2 * k; j++) {
      b[i][j] += b[i][j - 1];
      w[i][j] += w[i][j - 1];
    }
  }

  for (int i = 0; i < 2 * k; i++) {
    for (int j = 1; j < 2 * k; j++) {
      b[j][i] += b[j - 1][i];
      w[j][i] += w[j - 1][i];
    }
  }

  int64_t count = 0;

  auto calc_b = [&](auto x1, auto y1, auto x2, auto y2) -> int64_t {
    if (x2 < 0 || y2 < 0) {
      return 0;
    }
    if (2 * k - 1 <= x1 || 2 * k - 1 <= y1) {
      return 0;
    }
    x2 = std::min<int64_t>(x2, 2 * k - 1);
    y2 = std::min<int64_t>(y2, 2 * k - 1);
    auto val = b[x2][y2];
    if (0 <= x1) {
      val -= b[x1][y2];
    }
    if (0 <= y1) {
      val -= b[x2][y1];
    }
    if (0 <= x1 && 0 <= y1) {
      val += b[x1][y1];
    }
    return val;
  };
  auto calc_w = [&](auto x1, auto y1, auto x2, auto y2) -> int64_t {
    if (x2 < 0 || y2 < 0) {
      return 0;
    }
    if (2 * k - 1 <= x1 || 2 * k - 1 <= y1) {
      return 0;
    }
    x2 = std::min<int64_t>(x2, 2 * k - 1);
    y2 = std::min<int64_t>(y2, 2 * k - 1);
    auto val = w[x2][y2];
    if (0 <= x1) {
      val -= w[x1][y2];
    }
    if (0 <= y1) {
      val -= w[x2][y1];
    }
    if (0 <= x1 && 0 <= y1) {
      val += w[x1][y1];
    }
    return val;
  };

  for (int i = 0; i < 2 * k; i++) {
    for (int j = 0; j < 2 * k; j++) {
      auto b_c = calc_b(i - 1, j - 1, i + k - 1, j + k - 1);
      auto w_c = calc_w(i - 1, j - 1, i + k - 1, j + k - 1);
      b_c += calc_b(i - 1 - k, j - 1 - k, i - 1, j - 1);
      w_c += calc_w(i - 1 - k, j - 1 - k, i - 1, j - 1);
      b_c += calc_b(i - 1 - k, j + k - 1, i - 1, j + 2 * k - 1);
      w_c += calc_w(i - 1 - k, j + k - 1, i - 1, j + 2 * k - 1);

      b_c += calc_b(i + k - 1, j - 1 - k, i + 2 * k - 1, j - 1);
      w_c += calc_w(i + k - 1, j - 1 - k, i + 2 * k - 1, j - 1);
      b_c += calc_b(i + k - 1, j + k - 1, i + 2 * k - 1, j + 2 * k - 1);
      w_c += calc_w(i + k - 1, j + k - 1, i + 2 * k - 1, j + 2 * k - 1);

      b_c += calc_b(i - 2 * k - 1, j - 1, i - k - 1, j + k - 1);
      w_c += calc_w(i - 2 * k - 1, j - 1, i - k - 1, j + k - 1);

      b_c += calc_b(i - 1, j - 2 * k - 1, i + k - 1, j - k - 1);
      w_c += calc_w(i - 1, j - 2 * k - 1, i + k - 1, j - k - 1);
      count = std::max(count, b_c + w[2 * k - 1][2 * k - 1] - w_c);
    }
  }

  std::cout << count << std::endl;
  return 0;
}

