using ulong = unsigned long int;

class Check {
    ulong **m;
    ulong k;
    std::string c;
public:
    Check(ulong k, const std::string &c) {
        this->c = c;
        this->k = k;
        this->m = new ulong *[k + 1];
        for (ulong i = 0; i < this->k + 1; ++i) {
            this->m[i] = new ulong[k + 1]();
        }
    }

    void inc(ulong xMin, ulong xMax, ulong yMin, ulong yMax) {
        for (ulong i = xMin; i < xMax; ++i) {
            for (ulong j = yMin; j < yMax; ++j) {
                this->m[i][j]++;
            }
        }
    }

    void addDesire(ulong x, ulong y, const std::string &c) {
        ulong cx = x + 1;
        ulong cy = y + 1;

        if (c == this->c) {
            this->inc(0, cx, 0, cy);
            this->inc(cx, this->k + 1, cy, this->k + 1);
        } else {
            this->inc(0, cx, cy, this->k + 1);
            this->inc(cx, this->k + 1, 0, cy);
        }
    }

    ulong getMax() {
        ulong _max = 0;
        for (ulong i = 0; i < this->k + 1; ++i) {
            for (ulong j = 0; j < this->k + 1; ++j) {
                if (this->m[i][j] > _max) {
                    _max = this->m[i][j];
                }
            }
        }

        return _max;
    }

    ~Check() {
        for (ulong i = 0; i < this->k + 1; ++i) {
            delete[](this->m[i]);
        }
        delete[](this->m);
    }
};

int main() {
    ulong n, k;
    std::cin >> n >> k;
    Check checkW = Check(k, "W");

    for (ulong i = 0; i < n; ++i) {
        ulong x, y;
        std::string c;
        std::cin >> x >> y >> c;

        x = x < 0 ? -1 * x + k - 1 : x;
        y = y < 0 ? -1 * y + k - 1 : y;

        ulong bigX = x / k;
        ulong bigY = y / k;

        ulong localX = x % k;
        ulong localY = y % k;
        std::string localC = c;

        if ((bigX + bigY) % 2 != 0) {
            localC = localC == "W" ? "B" : "W";
        }

        checkW.addDesire(localX, localY, localC);
    }

    std::cout << checkW.getMax() << std::endl;

    return 0;
}

