      ll tmp=sum[i+k][j+k]+sum[i][j]-sum[i][j+k]-sum[i+k][j];
      tmp+=sum[2*k][2*k]+sum[i+k][j+k]-sum[i+k][2*k]-sum[2*k][j+k];
