template <typename T>
struct ruiseki2d{
    vector <vector<int>> s;
    int h,w;
    ruiseki2d(vector <vector<int>> &a){
        h = a.size(), w = a[0].size();
        vector <vector<int>> tmp(h+1,vector <int>(w+1));
        s = tmp;
        rep(i,h)rep(j,h) s[i+1][j+1] = s[i][j+1] + s[i+1][j] - s[i][j] + a[i][j];
    }
    T get(int y1, int x1, int y2, int x2){
        chmin(y1, h); chmax(y1,0LL);
        chmin(y2, h); chmax(y2,0LL);
        chmin(x1, w); chmax(x1,0LL);
        chmin(x2, w); chmax(x2,0LL);
        return s[x2][y2] - s[x1][y2] - s[x2][y1] + s[x1][y1];
    }
};
signed main(void) { cin.tie(0); ios::sync_with_stdio(false);
    int n,k; cin>>n>>k;
