    rep(i,n){
        int a,b; char c; cin>>a>>b>>c;
        if(c=='B') bl[a%(2*k)][b%(2*k)]++;
        else wh[a%(2*k)][b%(2*k)]++;
    }
    struct ruiseki2d <int> rb(bl);
    struct ruiseki2d <int> rw(wh);
    int ans = 0;
    rep(i,2*k){
        rep(j,2*k){
            int b = rb.get(0,0,i,j) + rb.get(i,j,i+k,j+k)+rb.get(i+k,j+k,INF,INF)
            + rb.get(0,j+k, i,INF) + rb.get(i+k,0,INF,j);
            int w = rw.get(0,0,INF,INF) - (rw.get(0,0,i,j) + rw.get(i,j,i+k,j+k)+rw.get(i+k,j+k,INF,INF)
            + rw.get(0,j+k, i,INF) + rw.get(i+k,0,INF,j));
            chmax(ans, b+w);
        }
    }
    cout<<ans<<endl;
}

