int rec(vector<vector<int>> &mos, int k, int xl, int yl, int xr, int yr) {
	if (xl < 0 || xl >= 2 * k || yl < 0 || yl >= 2 * k || xr < 0 || xr >= 2 * k || yr < 0 || yr >= 2 * k) return 0;
	int left = yl - 1 >= 0 ? mos[xr][yl - 1] : 0;
	int up = xl - 1 >= 0 ? mos[xl - 1][yr] : 0;
	int corner = xl - 1 >= 0 && yl - 1 >= 0 ? mos[xl - 1][yl - 1] : 0;
	return mos[xr][yr] - left - up + corner;
}
int main() {
	ll n, k;
	cin >> n >> k;
	auto t = mat(int, 2 * k, 2 * k, 0);
	rep(i, n) {
		int x, y;
		string c;
		cin >> x >> y >> c;
		if (c == "B") t[x % (2 * k)][y % (2 * k)]++;
		else t[(x + k) % (2 * k)][y % (2 * k)]++;
	}
	auto mos = t;
	rep(i, 2 * k)rep(j, 2 * k - 1)mos[i][j + 1] += mos[i][j];
	rep(i, 2 * k)rep(j, 2 * k - 1)mos[j + 1][i] += mos[j][i];
	int ma = 0;
	rep(i, k)rep(j, k) {
		int xl = i;
		int xr = i + k - 1;
		int yl = j;
		int yr = j + k - 1;
		int center = rec(mos, k, xl, yl, xr, yr);
		int upleft = rec(mos, k, 0, 0, xl - 1, yl - 1);
		int upright = rec(mos, k, 0, yr + 1, xl - 1, 2 * k - 1);
		int lowleft = rec(mos, k, xr + 1, 0, 2 * k - 1, yl - 1);
		int lowright = rec(mos, k, xr + 1, yr + 1, 2 * k - 1, 2 * k - 1);
		ma = max(ma, center + upleft + upright + lowleft + lowright);
	}
	cout << ma;
	return 0;

}

