		sum += count(pt[cpt].r, pt[cpt].c, 0, coff, pt[cpt].black);
		DEBUG("cpt %lld %lld %lld\n", pt[cpt].r, pt[cpt].c, sum);
		cpt++;
	}
	ll hcptcnt = 0;
	while (hcptcnt++ < N && pt[hcpt].c == ((K - coff) + 2 * K) % (2 * K)) {
		DEBUG("hcpt %lld %lld %lld\n", pt[hcpt].r, pt[hcpt].c, sum);
		sum -= count(pt[hcpt].r, pt[hcpt].c, 0, coff - 1, pt[hcpt].black);
		sum += count(pt[hcpt].r, pt[hcpt].c, 0, coff, pt[hcpt].black);
		DEBUG("hcpt %lld %lld %lld\n", pt[hcpt].r, pt[hcpt].c, sum);
		hcpt = (hcpt + 1) % N;
	}

  	for (ll r = 2 * K - 1; r >= 0; --r) {
  		DEBUG("r: %lld\n", r);

  		ll roff = 2 * K  - r;
  		while (rpt < N && pt2[rpt].r >= r) {
			DEBUG("rpt %lld %lld %lld\n", pt2[rpt].r, pt2[rpt].c, sum);
  			sum -= count(pt2[rpt].r, pt2[rpt].c, roff - 1, coff, pt2[rpt].black);
  			sum += count(pt2[rpt].r, pt2[rpt].c, roff, coff, pt2[rpt].black);
			DEBUG("rpt %lld %lld %lld\n", pt2[rpt].r, pt2[rpt].c, sum);
  			rpt++;
  		}
		ll hrptcnt = 0;
		DEBUG("HRPT: %lld %lld , %lld\n", pt2[hrpt].r, pt2[hrpt].c, ((K - roff) + 2 * K) % (2 * K));
		while (hrptcnt++ < N && pt2[hrpt].r == ((K - roff) + 2 * K) % (2 * K)) {
			DEBUG("hrpt %lld %lld %lld\n", pt2[hrpt].r, pt2[hrpt].c, sum);
			sum -= count(pt2[hrpt].r, pt2[hrpt].c, roff - 1, coff, pt2[hrpt].black);
			sum += count(pt2[hrpt].r, pt2[hrpt].c, roff, coff, pt2[hrpt].black);
			DEBUG("hrpt %lld %lld %lld\n", pt2[hrpt].r, pt2[hrpt].c, sum);
			hrpt = (hrpt + 1) % N;
		}

  		max = std::max(sum, max);
  	}
  }
  printf("%lld\n", max);
}

