      w[x % K][y % K]++;
    }
  }

  std::vector<std::vector<int> > b0 = Imos2D(b), w0 = Imos2D(w);

  //cerr << "OK" << endl;

  for (int i = 0; i < K; ++i) {
    for (int j = 0; j < K; ++j) {
      ans = std::max(ans, sum(b0, 0, 0, i, j) + sum(b0, i, j, K - i, K - j) + sum(w0, i, 0, K - i, j) + sum(w0, 0, j, i, K - j));
      ans = std::max(ans, sum(w0, 0, 0, i, j) + sum(w0, i, j, K - i, K - j) + sum(b0, i, 0, K - i, j) + sum(b0, 0, j, i, K - j));
