using namespace std;
typedef long long lint;

const int MAXK = 2020;
int whiteBoard[MAXK][MAXK];
int blackBoard[MAXK][MAXK];
int whiteSumBoard[MAXK][MAXK];
int blackSumBoard[MAXK][MAXK];

void calcSumBoard(int board[MAXK][MAXK], int sumBoard[MAXK][MAXK], const int K) {
    for (int i = 0; i < K; i++) {
        for (int j = 0; j < K; j++) {
            sumBoard[i+1][j+1] = sumBoard[i+1][j] + sumBoard[i][j+1] - sumBoard[i][j] + board[i][j];
        }
    }
}

// [left, right), [bottom, upper)
int calcSum(int left, int right, int bottom, int upper, int sumBoard[MAXK][MAXK]) {
    return sumBoard[upper][right] - sumBoard[upper][left] - sumBoard[bottom][right] + sumBoard[bottom][left];
}

int main() {
    int N, K;
    cin >> N >> K;
    for (int i = 0; i < N; i++) {
        int x, y;
        char c;
        cin >> x >> y >> c;
        x %= 2*K;
        y %= 2*K;
        if (c == 'B') {
            blackBoard[y][x]++;
        } else {
            whiteBoard[y][x]++;
        }
    }
    calcSumBoard(whiteBoard, whiteSumBoard, 2*K);
    calcSumBoard(blackBoard, blackSumBoard, 2*K);
    int ans = 0;
    for (int y = 0; y <= K; y++) {
        for (int x = 0; x <= K; x++) {
            int tmp = 0;
            tmp += calcSum(0, x, 0, y, whiteSumBoard);
            tmp += calcSum(0, x, y, y+K, blackSumBoard);
            tmp += calcSum(0, x, y+K, 2*K, whiteSumBoard);
            tmp += calcSum(x, x+K, 0, y, blackSumBoard);
            tmp += calcSum(x, x+K, y, y+K, whiteSumBoard);
            tmp += calcSum(x, x+K, y+K, 2*K, blackSumBoard);
            tmp += calcSum(x+K, 2*K, 0, y, whiteSumBoard);
            tmp += calcSum(x+K, 2*K, y, y+K, blackSumBoard);
            tmp += calcSum(x+K, 2*K, y+K, 2*K, whiteSumBoard);
            ans = max(ans, tmp);
        }
    }
    cout << ans << endl;
}

