	// マス(i,j)とマス(i j + k)の色も異なる
	// すべて左端に寄せる

	int sum = 0;

	vector<vector<ll>> wNum(2 * k + 1, vector<ll>(2 * k + 1, 0));
	int black = 0;

	rep(i, n) {
		if (x[i] >= 2 * k) {
			x[i] %= 2 * k;
		}
		if (y[i] >= 2 * k) {
			y[i] %= 2 * k;
		}
