			int e = wNum[2 * k][2 * k] - wNum[2 * k][j + k]
				- wNum[i + k][2 * k] + wNum[i + k][j + k];
			tmp = a + b + c + d + e;
			ans = max(ans, black + max(tmp, sum - tmp));
		}
	}

