		// +---+---+---+---+---+---+
		// |   |   |///|///|///|   |
		// +---+---+---+---+---+---+
		// |   |   |///|///|///|   |
		// +---+---+---+---+---+---+ y+K
		// |/C/|///|   |   |   |/E/|
		// +---+---+---+---+---+---+
		// |///|///|   |   |   |///|
		// +---+---+---+---+---+---+ 2K
		int a = query(0,     0,     x,     y);
		int b = query(x+K+1, 0,     k2,    y);
		int c = query(0,     y+K+1, x,     k2);
		int d = query(x,     y,     x+K+1, y+K+1);
		int e = query(x+K+1, y+K+1, k2,    k2);
		int w = a + b + c + d + e;
		ans = max(ans, w);
	}
	}
	// Output
	cout << ans << endl;
	return 0;
}

