void solve(){
    ll n,k;
    cin >> n >> k;
    matrix bl(2*k,Vi(2*k,0)),wh(2*k,Vi(2*k,0));
    rp(i,n){
        ll x,y;
        char c;
        cin >> x >> y >> c;
        if(c=='B'){
            bl[x%(2*k)][y%(2*k)]++;
        }else{
            wh[x%(2*k)][y%(2*k)]++;
        }
    }
    matrix syn(2*k,Vi(2*k));
    ll base=0;
    rp(i,2*k){
        rp(j,2*k){
            syn[i][j]=bl[i][j]-wh[i][j];
            base+=bl[i][j]+wh[i][j];
        }
    }
    ll start=0;
    Vi vsumsyn(2*k,0),hsumsyn(2*k,0);
    rp(i,2*k){
        rp(j,2*k){
            if(i>=k&&j>=k||i<k&&j<k) {
                start+=syn[i][j];
                vsumsyn[i]+=syn[i][j];
                hsumsyn[j]+=syn[i][j];
            }
            else {
                start-=syn[i][j];
                vsumsyn[i]-=syn[i][j];
                hsumsyn[j]-=syn[i][j];
            }
        }
    }
    ll score=-100000000;
    rp(i,2*k){
        if(i>0){
            rp(j,2*k){
                if(i<=k){
                    vsumsyn[j]-=syn[j][i-1]*2+syn[j][i+k-1]*2;
                    start-=syn[j][i-1]*2+syn[j][i+k-1]*2;
                }else{
                    vsumsyn[j]+=syn[j][i-1]*2+syn[j][(i+k-1)%(2*k)]*2;
                    start+=syn[j][i-1]*2+syn[j][(i+k-1)%(2*k)]*2;
                }
            }
        }
        ll cur=start;
        rp(j,2*k){
            if(j==0){
                chmax(score,start);
                continue;
            }
            if(j<=k){
                cur-=vsumsyn[j-1]*2;
                cur-=vsumsyn[j+k-1]*2;
            }else{
                cur+=vsumsyn[j-1]*2;
                cur+=vsumsyn[(j+k-1)%(2*k)]*2;
            }
            chmax(score,cur);
        }
    }

    print((base+score)/2);
    return;
}
int main(){
    cin.tie(0);ios::sync_with_stdio(false);
    std::cout<<std::fixed<<std::setprecision(30);
    solve();
    return 0;
}

