#define REP(i, n) for (int i = 0; i < n; i++)
#define REPR(i, n) for (int i = n - 1; i >= 0; i--)
#define FOR(i, m, n) for (int i = m; i < n; i++)
#define ALL(obj) (obj).begin(), (obj).end()
#define ALLR(obj) (obj).rbegin(), (obj).rend()

int memo[2000][2000]; // x, y
int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, k;
    cin >> n >> k;
    REP(i, n) {
        int x, y;
        char c;
        cin >> x >> y >> c;
        if (c == 'B') {
            x += k;
        }
        x %= 2 * k;
        y %= 2 * k;
        memo[x][y]++;
    }

    vector<int> u1(2 * k), u2(2 * k);
    REP(i, k * 2) REP(j, k * 2) {
        u1[i] += memo[i][j];
        u2[j] += memo[i][j];
    }
    // REP(i, k * 2) cout << u1[i] << endl;

    int t = 0;
    REP(i, k) t += u1[i];
    int ans = t;
    REP(i, 2 * k) {
        t += u1[(k + i) % (2 * k)] - u1[i];
        ans = max(ans, t);
    }
    t = 0;
    REP(i, k) t += u2[i];
    ans = max(ans, t);
    REP(i, 2 * k) {
        t += u2[(k + i) % (2 * k)] - u2[i];
        ans = max(ans, t);
    }
    cout << ans << endl;

    return 0;
}

#include "bits/stdc++.h"
using namespace std;

int main() {
	int N, K;
	static long Imos[2010][2010] = {}, Cum[2000][2000] = {}, ans = 0;
	cin >> N >> K;
	for (int i = 0; i < N; i++) {
		int x, y;
		char c;
		cin >> x >> y >> c;
		if (c == 'B') {
			x = x % (K * 2);
			y = y % (K * 2);
		}
		else {
			x = (x + K) % (K * 2);
			y = y % (K * 2);
		}
		if (x < K == y < K) {
			x = x % K;
			y = y % K;
			Imos[0][0]++;
			Imos[0][y]--;
			Imos[x][0]--;
			Imos[x][y]++;
			Imos[x][y]++;
			Imos[x][y + K]--;
			Imos[x + K][y]--;
			Imos[x + K][y + K]++;
			Imos[x + K][0]++;
			Imos[x + K][y]--;
			Imos[K * 2 - 1][0]--;
			Imos[K * 2 - 1][y]++;
			Imos[0][y + K]++;
			Imos[0][K * 2 - 1]--;
			Imos[x][y + K]--;
			Imos[x][K * 2 - 1]++;
			Imos[x + K][y + K]++;
			Imos[x + K][K * 2 - 1]--;
			Imos[K * 2 - 1][y + K]--;
			Imos[K * 2 - 1][y + K]++;
		}
		else {
			x = x % K;
			y = y % K;
			Imos[x][0]++;
			Imos[x][y]--;
			Imos[x + K][0]--;
			Imos[x + K][y]++;
			Imos[0][y]++;
			Imos[0][y + K]--;
			Imos[x][y]--;
			Imos[x][y + K]++;
			Imos[x + K][y]++;
			Imos[x + K][y + K]--;
			Imos[K * 2 - 1][y]--;
			Imos[K * 2 - 1][y + K]++;
			Imos[x][y + K]++;
			Imos[x][K * 2 - 1]--;
			Imos[x + K][y + K]--;
			Imos[x + K][K * 2 - 1]++;
		}
	}
	Cum[0][0] = Imos[0][0];
	ans = Cum[0][0];
	for (int i = 1; i < K * 2; i++) {
		Cum[0][i] = Cum[0][i - 1] + Imos[0][i];
		Cum[i][0] = Cum[i - 1][0] + Imos[i][0];
		ans = max(ans, Cum[0][i]);
		ans = max(ans, Cum[i][0]);
	}
	for (int i = 1; i < K * 2; i++) {
		for (int j = 1; j < K * 2; j++) {
			Cum[i][j] = Cum[i][j - 1] + Cum[i - 1][j] - Cum[i - 1][j - 1] + Imos[i][j];
			ans = max(ans, Cum[i][j]);
		}
	}
	for (int i = 0; i < K * 2; i++) {
		for (int j = 0; j < K * 2; j++) {
			cout << Cum[i][j] << " ";
		}
		cout << endl;
	}
	cout << ans << endl;
}

