    REP(i, 0, 2 * n)
    REP(j, 0, 2 * n) ru[k][i + 1][j + 1] = ru[k][i + 1][j] + b[k][i][j];
    REP(k, 0, 2)
    REP(j, 0, 2 * n) REP(i, 0, 2 * n) ru[k][i + 1][j + 1] += ru[k][i][j + 1];
    int ans = 0;
    REP(i, 0, k) REP(j, 0, k) {
