        cw += ru[0][i][j] - ru[0][0][0];
        cw += ru[0][i + k][j + k] + ru[0][i][j] - ru[0][i + k][j] -
              ru[0][i][j + k];
        cw += ru[0][2 * k][2 * k] + ru[0][i + k][j + k] - ru[0][2 * k][j + k] -
              ru[0][i + k][2 * k];
        cw += ru[0][i][2 * k] - ru[0][i][j + k];
