    if(y2 >= 2*K) y2 = 2*K-1;

    ret = d[y2][x2];    //累積和で計算
    if(y1-1 >= 0) ret -= d[y1-1][x2];
    if(x1-1 >= 0) ret -= d[y2][x1-1];
    if(y1-1 >= 0 && x1-1 >= 0) ret += d[y1-1][x1-1];

    return ret;
}

