int main() {
    cin>>N>>K;
    REP(i,0,N){
        cin>>x>>y>>c;
        x %= (2*K);
        y %= (2*K);
        if(c == 'W'){
            y = (y + K) % (2*K);
        }
        d[y][x]++;
    }

    //２次元累積和の準備
    REP(i,0,2*K+1){
        REP(j,0,2*K+1){
            d[i][j+1] += d[i][j];
        }
    }
    REP(j,0,2*K){
        REP(i,0,2*K){
            d[i+1][j] += d[i][j];
        }
    }

    int ans = 0;

    //塗り方を全通り試す
//    REP(i,0,2*K){
//        REP(j,0,2*K){
    REP(i,0,K+1){
        REP(j,0,K+1){
            //各塗り方で黒い部分に含まれる点を数える（二次元累積和）
            int t = cal(i,j,i+K-1, j+K-1) +
                    cal(i-K,j-K,i-1, j-1) +
                    cal(i-K,j+K,i-1, j+2*K-1) +
                    cal(i+K,j-K,i+2*K-1, j-1) +
                    cal(i+K,j+K,i+2*K-1, j+2*K-1);
            ans = max(ans, t);
        }
    }

    cout<<ans<<endl;

    return 0;
}

