class TwoDCumulativeSum {
public:
	ll H, W;
	vector<vector<ll>> data;
	vector<vector<ll>> rui;

	TwoDCumulativeSum(vector<vector<ll>> &data) : H(data.size()), W(data[0].size()), data(data) {
		rui.assign(H+1, vector<ll>(W+1, 0));
		for (ll i = 0; i < H; ++i)
			for (ll j = 0; j < W; ++j)
				rui[i+1][j+1] = rui[i][j+1] + rui[i+1][j] - rui[i][j] + data[i][j];
	}

	// クエリ [x1, x2) × [y1, y2) の長方形区域の和を返す
	ll query(ll x1, ll x2, ll y1, ll y2) {
		return rui[x2][y2] - rui[x1][y2] - rui[x2][y1] + rui[x1][y1];
	}
};
