int Square(int x1,int y1,int x2,int y2,bool B)
{
	int ret=0;
	int a,b,c;
	if(B==true)
	{
		if(y1>0)
		{
			a = black[x2][y1-1];
		}else{
			a=0;
		}
		if(x1>0)
		{
			b=black[x1-1][y2];
		}else{
			b=0;
		}
		if(y1>0&&x1>0)
		{
			c=black[x1-1][y1-1];
		}else{
			c=0;
		}
		ret = black[x2][y2]-a-b+c;
	}else{
		if(y1>0)
		{
			a = white[x2][y1-1];
		}else{
			a=0;
		}
		if(x1>0)
		{
			b=white[x1-1][y2];
		}else{
			b=0;
		}
		if(y1>0&&x1>0)
		{
			c=white[x1-1][y1-1];
		}else{
			c=0;
		}
		ret = white[x2][y2]-a-b+c;
	}
	return ret;
}

