  int h = a.size(), w = a[0].size();
  std::vector<std::vector<T>> s(h + 1, std::vector<T>(w + 1, 0));
  rep(i, h) rep(j, w) s[i + 1][j + 1] = a[i][j];
  rep(i, h + 1) rep(j, w) s[i][j + 1] += s[i][j];
  rep(i, h) rep(j, w + 1) s[i + 1][j] += s[i][j];
  return s;
