	cin >> N >> K;
	twodimBIT<int> hope(3*K+3,3*K+3);
	FOR(i,0,N){
		int x,y;
		char c;
		cin >> x >> y >> c;
		if(c=='W')y+=K;
		x %= 2*K;
		y %= 2*K;
		if(x<0)x += 2*K;
		if(y<0)y += 2*K;
		hope.add(x+1,y+1,1);
	}
	int ans = 0;
	FOR(i,1,K+2){
		FOR(j,1,K+2){
			int t = hope.sum(i,j,i+K-1,j+K-1);
			t += hope.sum(i+K,j+K,min(i+2*K-1,2*K),min(j+2*K-1,2*K));
			t += hope.sum(max(1,i-K),max(1,j-K),i-1,j-1);
			t += hope.sum(max(1,i-K),j+K,i-1,j+2*K-1);
			t += hope.sum(i+K,max(j-K,1),i+2*K-1,j-1);
			ans = max( ans , t );
		}
	}
	cout << ans << endl;
}

