    if(y1>KK){
        rect(x0,x1,y0,KK);
        rect(x0,x1,0,y1-KK);
        return;
    }
    mp[x0][y0]++;
    mp[x0][y1]--;
    mp[x1][y0]--;
    mp[x1][y1]++;

