    auto get_accum = [&](int start_x,int start_y,int end_x,int end_y){
        LL ret = accum[end_x][end_y];
        if(start_x>=1 && start_y>=1){
            ret -= accum[start_x-1][end_y];
            ret -= accum[end_x][start_y-1];
            ret += accum[start_x-1][start_y-1];
        }else if(start_x>=1){
            ret -= accum[start_x-1][end_y];
        }else if(start_y>=1){
            ret -= accum[end_x][start_y-1];
        }
        return ret;
    };

    auto get_accum_rec = [&](int start_x,int start_y,int end_x,int end_y){
        if(start_x<=end_x && start_y<=end_y) return get_accum(start_x,start_y,end_x,end_y);
        if(start_x>end_x && start_y<=end_y) return get_accum(start_x,start_y,2*K-1,end_y)+get_accum(0,start_y,end_x,end_y);
        if(start_x<=end_x && start_y>end_y) return get_accum(start_x,start_y,end_x,2*K-1)+get_accum(start_x,0,end_x,end_y);
        LL ret = 0;
        ret += get_accum(start_x,start_y,2*K-1,2*K-1);
        ret += get_accum(0,0,end_x,end_y);
        ret += get_accum(0,start_y,end_x,2*K-1);
        ret += get_accum(start_x,0,2*K-1,end_y);
        return ret;
    };

    for(int start_y=0;start_y<2*K;start_y++){
        for(int start_x=0;start_x<2*K;start_x++){
            LL middle_x = (start_x+K-1)%(2*K);
            LL middle_y = (start_y+K-1)%(2*K);
            LL next_x = (middle_x+1)%(2*K);
            LL next_y = (middle_y+1)%(2*K);
            LL end_x = (next_x+K-1)%(2*K);
            LL end_y = (next_y+K-1)%(2*K);
            LL num = 0;
            num += get_accum_rec(start_x,start_y,middle_x,middle_y);
            num += get_accum_rec(next_x,next_y,end_x,end_y);
            ans = max(ans,num);
            ans = max(ans,N-num);
        }
    }
}

int main(){
    cin >> N >> K;
    for(int i=0;i<N;i++) cin >> X[i] >> Y[i] >> C[i];

    solve();

    cout << ans << endl;
    return 0;
}

