int N, K;
int blackPointSumTable[1000][1000];
int whitePointSumTable[1000][1000];
int maxPoint = 0;

void updateMaxPoint(int point)
{
	if (point < N - point)
	{
		point = N - point;
	}
	if (point > maxPoint)
	{
		maxPoint = point;
	}
}

int getBlackPointSum(int x, int y)
{
	if (x >= 0 && y >= 0) { return blackPointSumTable[x][y]; }
	else { return 0; }
}

int getWhitePointSum(int x, int y)
{
	if (x >= 0 && y >= 0) { return whitePointSumTable[x][y]; }
	else { return 0; }
}

int calc(int x0, int y0, int x1, int y1)
{
	return getBlackPointSum(x1, y1)
	 - getBlackPointSum(x0 - 1, y1)
	 - getBlackPointSum(x1, y0 - 1) 
	 + getBlackPointSum(x0 - 1, y0 - 1)
	 + getWhitePointSum(K - 1, K - 1)
	 - (getWhitePointSum(x1, y1)
	 - getWhitePointSum(x0 - 1, y1)
	 - getWhitePointSum(x1, y0 - 1) 
	 + getWhitePointSum(x0 - 1, y0 - 1));
}

int main() {
	cin >> N >> K;
	int blackPointTable[1000][1000];
	int whitePointTable[1000][1000];
	for (int i = 0; i < K; ++i)
	{
		for (int j = 0; j < K; ++j)
		{
			blackPointTable[i][j] = 0;
			blackPointSumTable[i][j] = 0;
			whitePointTable[i][j] = 0;
			whitePointSumTable[i][j] = 0;
		}
	}

	for (int i = 0; i < N; ++i)
	{
		char c;
		int x, y;
		cin >> x >> y >> c;
		if ((((x / K) + (y / K)) % 2 == 0) == (c == 'B'))
		{
			++blackPointTable[x % K][y % K];
		}
		else
		{
			++whitePointTable[x % K][y % K];
		}
	}

	blackPointSumTable[0][0] = blackPointTable[0][0];
	whitePointSumTable[0][0] = whitePointTable[0][0];
	for (int i = 1; i < K; ++i)
	{
		blackPointSumTable[0][i] = blackPointSumTable[0][i - 1] + blackPointTable[0][i];
		blackPointSumTable[i][0] = blackPointSumTable[i - 1][0] + blackPointTable[i][0];
		whitePointSumTable[0][i] = whitePointSumTable[0][i - 1] + whitePointTable[0][i];
		whitePointSumTable[i][0] = whitePointSumTable[i - 1][0] + whitePointTable[i][0];
	}

	for (int x = 1; x < K; ++x)
	{
		for (int y = 1; y < K; ++y)
		{
			blackPointSumTable[x][y] = 
			 blackPointSumTable[x - 1][y]
			 + blackPointSumTable[x][y - 1]
			 - blackPointSumTable[x - 1][y - 1]
			 + blackPointTable[x][y];
			whitePointSumTable[x][y] = 
			 whitePointSumTable[x - 1][y]
			 + whitePointSumTable[x][y - 1]
			 - whitePointSumTable[x - 1][y - 1]
			 + whitePointTable[x][y];
		}
	}

	for (int x = 0; x < K; ++x)
	{
		for (int y = 0; y < K; ++y)
		{
			int point = calc(0, 0, x, y);
			updateMaxPoint(point);
			point = calc(x, 0, K - 1, y);
			updateMaxPoint(point);
			point = calc(0, y, x, K - 1);
			updateMaxPoint(point);
			point = calc(x, y, K - 1, K - 1);
			updateMaxPoint(point);
		}
	}
	cout << maxPoint << endl;

	return 0;
}

