			bk += cnt[i + k][j + k] - cnt[i][j + k] - cnt[i + k][j] + cnt[i][j];
			bk += cnt[2 * k][2 * k] - cnt[2 * k][j + k] - cnt[i + k][2 * k] + cnt[i + k][j + k];
			chmax(max, bk);
		}
	}
	cout << max;
	return 0;
}

