int main() {

    int n, k;
    cin >> n >> k;

    vector<int> x(n, 0), y(n, 0);

    int s = k * 2;

    for (int i = 0; i < n; i++) {
        char c;
        cin >> x[i] >> y[i] >> c;
        x[i] %= s;
        y[i] = ((ll)y[i] + (c == 'B' ? k : 0)) % s;
    }

    vector<vector<int>> imos(s + 1, vector<int>(s + 1, 0));
    for (int i = n; i--;) {
        imos[x[i] + 1][y[i] + 1]++;
    }
    for (int v = 1; v <= s; v++) {
        for (int u = 1; u <= s; u++) {
            imos[u][v] += imos[u-1][v];
        }
    }
    for (int u = 1; u <= s; u++) {
        for (int v = 1; v <= s; v++) {
            imos[u][v] += imos[u][v-1];
        }
    }

    int ans = 0;
    for (int u = 0; u < s; u++) {
        for (int v = 0; v < s; v++) {
            int cand = 0;
            for (int q = -1; q <= 1; q++) {
                for (int w = -1; w <= 1; w++) {
                    if (((q + w) % 2 + 2) % 2 == 1) continue;
                    int us = min(s, max(0, u + q * k));
                    int vs = min(s, max(0, v + w * k));
                    int ue = min(s, max(0, u + (q + 1) * k));
                    int ve = min(s, max(0, v + (w + 1) * k));
                    if (ue != us && ve != vs) {
                        cand += imos[ue][ve] - imos[us][ve] - imos[ue][vs] + imos[us][vs];
                    }
                }
            }
            if (cand > ans) ans = cand;
        }
    }

    cout << ans << endl;

}

