// 二次元累積和
template <typename T> struct RectangleSum {
    vector<vector<T>> sum;
    T getsum(int left, int right, int top,
             int bottom) { //[left, right], [top, bottom]
        T res = sum[bottom][right];
        if (left > 0)
            res -= sum[bottom][left - 1];
        if (top > 0)
            res -= sum[top - 1][right];
        if (left > 0 && top > 0)
            res += sum[top - 1][left - 1];
        return res;
    }
    void init(const vector<vector<T>> &s, int h, int w) {
        sum = vector<vector<T>>(h, vector<T>(w));
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                sum[y][x] = s[y][x];
                if (y > 0)
                    sum[y][x] += sum[y - 1][x];
                if (x > 0)
                    sum[y][x] += sum[y][x - 1];
                if (y > 0 && x > 0)
                    sum[y][x] -= sum[y - 1][x - 1];
            }
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, k;
    cin >> n >> k;
    vector<vector<int>> sum(2 * k, vector<int>(2 * k));
    REP(i, n) {
        int x, y;
        char c;
        cin >> x >> y >> c;
        if (c == 'B')
            y += k;
        x %= 2 * k;
        y %= 2 * k;
        sum[x][y] = 1;
        sum[(x + k) % (2 * k)][(y + k) % (2 * k)] = 1;
    }
    RectangleSum<int> rsum;
    rsum.init(sum, 2 * k, 2 * k);
    int maxv = 0;
    REP(i, k) REP(j, k) {
        maxv = max(maxv, rsum.getsum(i, i + k - 1, j, j + k - 1));
    }

    cout << maxv << endl;

    return 0;
}

