int sb[2010][2010];
int b[2010][2010];

int calc(int i, int j, int i2, int j2) {
    if (i == 0 && j == 0) {
        return sb[i2][j2];
    }
    else if (i == 0) {
        return sb[i2][j2] - sb[i2][j - 1];
    }
    else if (j == 0) {
        return sb[i2][j2] - sb[i - 1][j2];
    }
    else {
        return sb[i2][j2] - sb[i2][j - 1] - sb[i - 1][j2] + sb[i - 1][j - 1];
    }
}

int main() {
    imfor(i, 2000) {
        imfor(j, 2000) {
            b[i][j] = 0;
        }
    }
    int n, k;
    cin >> n >> k;
    imfor(i, n) {
        int x, y;
        char c;
        cin >> x >> y >> c;
        if (c == 'W') {
            y += k;
        }
        x = x % (2 * k);
        y = y % (2 * k);
        b[x][y]++;
    }
    sb[0][0] = b[0][0];
    for (int i = 1; i < 2 * k; i++) {
        sb[0][i] = sb[0][i - 1] + b[0][i];
    }
    for (int i = 1; i < 2 * k; i++) {
        for (int j = 0; j < 2 * k; j++) {
            if (j == 0) {
                sb[i][j] = sb[i - 1][j] + b[i][j];
            }
            else {
                sb[i][j] = sb[i][j - 1] + sb[i - 1][j] - sb[i - 1][j - 1] + b[i][j];
            }
        }
    }
    int ans = 0;
    imfor(i, 2 * k) {
        imfor(j, 2 * k) {
            int tmp = 0;
            //0
            tmp += calc(i, j, max(i + k - 1, (2 * k) - 1), max(j + k - 1, (2 * k) - 1));
            //1

            //2
            if (i + k <= (2 * k) - 1 && j + k <= (2 * k) - 1) {
                tmp += calc(i + k, j + k, max(i + k - 1 + k, (2 * k) - 1), max(j + k - 1 + k, (2 * k) - 1));
            }
            //3

            //4
            if (i - 1 >= 0 && j + k <= (2 * k) - 1) {
                tmp += calc(max(i - k, 0), j + k, i - 1, max(j + k - 1, (2 * k) - 1));
            }
            //5
            if (i - k - 1 >= 0) {
                tmp += calc(0, j, i - k - 1, max(j + k - 1, (2 * k) - 1));
            }
            //6
            if (i - 1 >= 0 && j - 1 >= 0) {
                tmp += calc(max(i - k, 0), max(j - k, 0), i - 1, j - 1);
            }
            //7
            if (j - k - 1 >= 0) {
                tmp += calc(i, 0, max(i + k - 1, (2 * k) - 1), j - k - 1);
            }
            //8
            if (i + k <= (2 * k) - 1 && j - 1 >= 0) {
                tmp += calc(i + k, max(j - k, 0), max(i + k - 1 + k, (2 * k) - 1), j - 1);
            }
            ans = max(ans, tmp);
        }
    }
    cout << ans << endl;
}

