						x = (n - 1) - i;
						y = (n - 1) - j;
					}
					else
					{
						dx = v[0][0] - v[k][0];
						dy = v[k][1] - v[0][1];
						x = (n - 1) - i;
						y = j;
					}
				}
				else
				{
