void fill_square(int left, int bottom, int width, int height, vector<vector<int>> &accum) {
    accum[left][bottom] += 1;
    accum[left + width][bottom] -= 1;
    accum[left][bottom + height] -= 1;
    accum[left + width][bottom + height] += 1;
}


int process_accum(vector<vector<int>> &accum) {
    for (int i = 0; i < accum.size(); i++) {
        int now = 0;
        for (int j = 0; j < accum[i].size(); j++) {
            now += accum[i][j];
            accum[i][j] = now;
        }
    }
    int maxx = 0;
    for (int i = 0; i < accum[0].size(); i++) {
        int now = 0;
        for (int j = 0; j < accum.size(); j++) {
            now += accum[j][i];
            accum[j][i] = now;
            maxx = max(maxx, now);
        }
    }
    return maxx;

}

int main() {
    int n, k;
    cin >> n >> k;

    vector<int> x(n), y(n);

    for (int i = 0; i < n; i++) {
        char c;
        cin >> x[i] >> y[i] >> c;
        // 全部黒の条件だけで考えます
        if (c == 'W')
            x[i] += k;

        x[i] %= (2 * k);
        y[i] %= (2 * k);
    }
    vector<vector<int>> accum(2 * k+1, vector<int>(2 * k+1, 0));

    for (int i = 0; i < n; i++) {
        if (x[i] < k && y[i] < k) {
            fill_square(x[i], y[i], k, k, accum);
            fill_square(x[i] + k, y[i] + k, k - x[i], k - y[i], accum);
            fill_square(x[i] + k, 0, k - x[i], y[i], accum);
            fill_square(0, y[i] + k, x[i], k - y[i], accum);
            fill_square(0, 0, x[i], y[i], accum);
        }
        else if (x[i] < k) {
            fill_square(x[i], y[i], k, 2 * k - y[i], accum);
            fill_square(x[i] + k, y[i] - k, k - x[i], k, accum);
            fill_square(x[i], 0, k, y[i] - k, accum);
            fill_square(0, y[i] - k, x[i], k, accum);
        }
        else if (y[i] < k) {
            fill_square(x[i], y[i], 2 * k - x[i], k, accum);
            fill_square(x[i] - k, 0, k, y[i], accum);
            fill_square(0, y[i], x[i] - k, k, accum);
            fill_square(x[i] - k, y[i] + k, k, k - y[i], accum);
        }
        else {
            fill_square(x[i], y[i], 2 * k - x[i], 2 * k - y[i], accum);
            fill_square(x[i], 0, 2 * k - x[i], y[i] - k, accum);
            fill_square(0, 0, x[i] - k, y[i] - k, accum);
            fill_square(0, y[i], x[i] - k, 2 * k - y[i], accum);
            fill_square(x[i] - k, y[i] - k, k, k, accum);
        }
    }

    int ret = process_accum(accum);
    cout << ret << endl;


    return 0;
}

