/*==================================================*/
/*function*/
int cal(int x1, int y1, int x2, int y2){
    int ret = 0;

    if(x1 >= 2*K || y1 >= 2*K || x2 < 0 || y2 < 0) return ret;  //全くの範囲外

    if(x1 < 0) x1 = 0;  //はみ出しをカット
    if(y1 < 0) y1 = 0;
    if(x2 >= 2*K) x2 = 2*K-1;
    if(y2 >= 2*K) y2 = 2*K-1;

    ret = d[y2][x2];    //累積和で計算
    if(y1-1 >= 0) ret -= d[y1-1][x2];
    if(x1-1 >= 0) ret -= d[y2][x1-1];
    if(y1-1 >= 0 && x1-1 >= 0) ret += d[y1-1][x1-1];

    return ret;
}

