        cin >> x[i] >> y[i] >> c;
        if (c == 'W') {
            x[i] += K;
        }
        x[i] %= 2 * K;
        y[i] %= 2 * K;
    }

    //累積和を計算
    vector<vector<int>> sum(2 * K, vector<int>(2 * K, 0));
    for (int i = 0; i < N; i++) {
        sum[y[i]][x[i]]++;
    }
    for (int i = 0; i < 2 * K; i++) {
        for (int j = 1; j < 2 * K; j++) {
            sum[i][j] += sum[i][j - 1];
        }

        if (i == 0) {
            continue;
        }

        for (int j = 0; j < 2 * K; j++) {
            sum[i][j] += sum[i - 1][j];
        }
    }

    int ans = 0;
    for (int i = 0; i < K; i++) {
        for (int j = 0; j < K; j++) {
            int tmp = 0;
            tmp += sum[i][j];
            tmp += sum[i][2 * K - 1] - sum[i][j + K];
            tmp += sum[2 * K - 1][j] - sum[i + K][j];

            int center = sum[i + K][j + K] - sum[i + K][j] - sum[i][j + K] + sum[i][j];
            tmp += center;

            tmp += sum[2 * K - 1][2 * K - 1] - sum[2 * K - 1][j + K] - sum[i + K][2 * K - 1] + center;

            ans = max(ans, tmp);
            ans = max(ans, N - tmp);
        }
    }

    cout << ans << endl;
}

