ll cntMat(mat &M, pa tl, pa br)
{
  if (tl.first == 0 && tl.second == 0)
  {
    return M[br.first][br.second];
  }
  else if (tl.first == 0)
  {
    return M[br.first][br.second] - M[br.first][tl.second - 1];
  }
  else if (tl.second == 0)
  {
    return M[br.first][br.second] - M[tl.first - 1][br.second];
  }
  else
    return M[br.first][br.second] - M[tl.first - 1][br.second] - M[br.first][tl.second - 1] + M[tl.first - 1][tl.second - 1];
}

