int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, k;
    cin >> n >> k;
    int K = k*2;
    vector<P> X(n);
    string c;
    rep(i, n) {
        char cc;
        cin >> X[i] >> cc;
        c += cc;
    }

    int jj = int(2e9)/K*K;
    vvi fieldb(K, vi(K)), fieldw(K, vi(K));
    rep(i, n) {
        if(X[i].first < 0) {
            X[i].first += jj;
        } 
        if(X[i].second < 0) {
            X[i].second += jj;
        }
        X[i].first %= K;
        X[i].second %= K;
        fieldb[X[i].first][X[i].second] = (c[i] == 'B');
        fieldw[X[i].first][X[i].second] = (c[i] == 'W');
    }

    vi di(K);
    rep(i, K) {
        di[i] = i;
    }

    int ans = 0;
    vvi sumb(K+1, vi(K+1)), sumw(K+1, vi(K+1));
    rep(i, K) rep(j, K) {
        sumb[i+1][j+1] = sumb[i][j+1] + sumb[i+1][j] - sumb[i][j] + fieldb[i][j];
        sumw[i+1][j+1] = sumw[i][j+1] + sumw[i+1][j] - sumw[i][j] + fieldw[i][j];
    }
    rep(i, k) rep(j, k) {
        vi x(4), y(4);
        x[1] = i;
        y[1] = j;
        x[2] = i+k;
        y[2] = j+k;
        x[3] = y[3] = K;
        int now = 0;
        now += 2*sumb[i][j] + 2*sumb[x[2]][y[2]] - 2*sumb[i][y[2]] - 2*sumb[x[2]][j] + sumb[i][K] + sumb[K][j] + sumb[K][K] - sumb[x[2]][K] - sumb[K][y[2]];
        now -= 2*sumw[i][j] + 2*sumw[x[2]][y[2]] - 2*sumw[i][y[2]] - 2*sumw[x[2]][j] + sumw[i][K] + sumw[K][j] - sumw[x[2]][K] - sumw[K][y[2]];
        ans = max(ans, now);
        now = 0;
        now += 2*sumw[i][j] + 2*sumw[x[2]][y[2]] - 2*sumw[i][y[2]] - 2*sumw[x[2]][j] + sumw[i][K] + sumw[K][j] + sumw[K][K] - sumw[x[2]][K] - sumw[K][y[2]];
        now -= 2*sumb[i][j] + 2*sumb[x[2]][y[2]] - 2*sumb[i][y[2]] - 2*sumb[x[2]][j] + sumb[i][K] + sumb[K][j] - sumb[x[2]][K] - sumb[K][y[2]];
        ans = max(ans, now);
    }

    cout << ans << endl;
}

