void solve(){
  int n, k; cin >> n >> k;
  k *= 2;
  V3<int> hope(2,V2<int>(k, V<int>(k,0) ) );// b w


  FOR(i,0,n){
    ll x, y; char c; cin >> x >> y >> c;
    int nt = ((c=='W')?1:0);
    x %= k;
    y %= k;
    hope[nt][x][y]++;
  }

  V3<int> sum(2,V2<int>(k+2, V<int>(k+2,0) ) );
  FOR(r,0,2){
    FOR(i,0,k){
      FOR(j,0,k){
        sum[r][i+1][j+1] = sum[r][i+1][j] + hope[r][i][j];
      }
    }
  }
  FOR(r,0,2){
    FOR(i,0,k){
      FOR(j,0,k){
        sum[r][j+1][i+1] += sum[r][j][i+1];
      }
    }
  }
  int ans = 0;
  auto f = [&](int mode, int x1, int y1, int x2, int y2){
    int ret = sum[mode][x2][y2] + sum[mode][x1][y1] - sum[mode][x1][y2] - sum[mode][x2][y1];
    return ret;
  };
  FOR(i,0,k/2){
    FOR(j,0,k/2){
      int g0 = 0, g1 = 0;
      //g0 = f(0,0,0,i,j)+f(0,i,j,k,k)+f(1,i,0,k,j)+f(1,0,j,i,k);
      g0 = f(0,i,j,i+k/2,j+k/2) + f(0,i+k/2,j+k/2,k,k) + f(0,0,0,i,j);
      g1 = f(1,i,j,i+k/2,j+k/2) + f(1,i+k/2,j+k/2,k,k) + f(1,0,0,i,j);
      g1 = sum[1][k][k]-g1;
      g0 += g1;
      g1 = n - g0;
      ans = max(g0,ans);
      ans = max(g1,ans);
    }
  }
  /*
  FOR(r,0,2){
    FOR(i,0,k+1){
      FOR(j,0,k+1){
        couts(sum[r][j][i]);
      }
      coutn("");
    }
    coutn("");
  }
  FOR(r,0,2){
    FOR(i,0,k){
      FOR(j,0,k){
        couts(hope[r][j][i]);
      }
      coutn("");
    }
    coutn("");
  }*/

  cout<<ans;
}



