inline int countwhite(int x1,int y1, int x2,int y2){
    int ans=kouhow[x1][y1]-kouhow[x1][y2-1]-kouhow[x2-1][y1]+kouhow[x2-1][y2-1];
    return ans;
}
inline int countblack(int x1,int y1, int x2,int y2){
    int ans=kouhob[x1][y1]-kouhob[x1][y2-1]-kouhob[x2-1][y1]+kouhob[x2-1][y2-1];
    return ans;
}
signed main() {
    cin>>n>>k;
    rep(i,n){
        scanf("%lld %lld %c",&x[i],&y[i],&c[i]);
        x[i]%=(k*2);
        y[i]%=(k*2);
        if (!x[i]) {
            x[i]=k*2;
        }
        if (!y[i]) {
            y[i]=k*2;
        }
        if (c[i]=='B') {
            kouhob[x[i]][y[i]]++;
            black++;
        }else{
            kouhow[x[i]][y[i]]++;
            white++;
        }
    }
    REP(i,k*2){
        REP(j,k*2){
            kouhob[i][j]+=kouhob[i][j-1];
            kouhow[i][j]+=kouhow[i][j-1];
        }
        REP(j,k*2){
            kouhob[i][j]+=kouhob[i-1][j];
            kouhow[i][j]+=kouhow[i-1][j];
        }
    }
    rep(i,k+1){
        rep(j,k+1){
//            cout<<i<<' '<<j<<endl;

            int w=countwhite(i+k, j+k, i+1, j+1);
            w+=countwhite(i, j, 1, 1);
            w+=countwhite(i, k*2, 1, j+k+1);
            w+=countwhite(k*2, j, i+k+1, 1);
            w+=countwhite(k*2, k*2, i+k+1, j+k+1);

            int b=countblack(i+k, j+k, i+1, j+1);
            b+=countblack(i, j, 1, 1);
            b+=countblack(i, k*2, 1, j+k+1);
            b+=countblack(k*2, j, i+k+1, 1);
            b+=countblack(k*2, k*2, i+k+1, j+k+1);

            chmax(ans, w+black-max(0ll,b));
            chmax(ans, b+white-max(0ll,w));
//                cout<<w<<' '<<b<<endl;

        }
    }
    printf("%lld\n",ans);
}

