  std::ios::sync_with_stdio(false);
  std::cin.tie(0);

  int N, K;
  cin >> N >> K;
  vector<int> x(N), y(N);
  vector<char> c(N);
  rep(i, N) {
    cin >> x[i] >> y[i] >> c[i];
    x[i] %= 2 * K;
    y[i] %= 2 * K;
  }

  vector<vector<int>> black(2 * K, vector<int>(2 * K, 0));
  vector<vector<int>> white(2 * K, vector<int>(2 * K, 0));
  rep(i, N) {
    if (c[i] == 'B') black[y[i]][x[i]]++;
    else white[y[i]][x[i]]++;
  }

  // row
  for (int i = 0; i < 2 * K; i++) {
    for (int j = 1; j < 2 * K; j++) {
      black[i][j] += black[i][j - 1];
      white[i][j] += white[i][j - 1];
    }
  }
  // col
  for (int j = 0; j < 2 * K; j++) {
    for (int i = 1; i < 2 * K; i++) {
      black[i][j] += black[i - 1][j];
      white[i][j] += white[i - 1][j];
    }
  }

  // [i1, i2) * [j1, j2)
  auto sum2d = [](int i1, int j1, int i2, int j2, const vector<vector<int>>& v) {
    return v[i2 - 1][j2 - 1]
      - (j1 > 0 ? v[i2 - 1][j1 - 1] : 0)
      - (i1 > 0 ? v[i1 - 1][j2 - 1] : 0)
      + (i1 > 0 && j1 > 0 ? v[i1 - 1][j1 - 1] : 0);
  };

  int ans = 0;
  for (int h = 1; h <= K; h++) {
    for (int w = 1; w <= K; w++) {
      for (int bw = 0; bw < 2; bw++) {
        const auto& board1 = bw ? black : white;
        const auto& board2 = bw ? white : black;
        int s = 0;
        s += sum2d(0, 0, h, w, board1);
        s += sum2d(h, 0, h + K, w, board2);
        s += sum2d(h + K, 0, 2 * K, w, board1);
        s += sum2d(0, w, h, w + K, board2);
        s += sum2d(h, w, h + K, w + K, board1);
        s += sum2d(h + K, w, 2 * K, w + K, board2);
        s += sum2d(0, w + K, h, 2 * K, board1);
        s += sum2d(h, w + K, h + K, 2 * K, board2);
        s += sum2d(h + K, w + K, 2 * K, 2 * K, board1);
        ans = max(ans, s);
      }
    }
  }

  cout << ans << endl;

  return 0;
}

