      t1[x + j * k][y + j * k + k]--;
      t1[x + j * k + k][y + j * k + k]++;
    }
  }
  for (int i = 0; i < 4 * k; i++) {
    for (int j = 1; j < 4 * k; j++) {
      t1[i][j] += t1[i][j - 1];
    }
  }
  for (int i = 1; i < 4 * k; i++) {
    for (int j = 0; j < 4 * k; j++) {
      t1[i][j] += t1[i - 1][j];
    }
  }
  for (int i = 0; i < 4 * k; i++) {
    for (int j = 0; j < 4 * k; j++) {
      t2[i % (2 * k)][j % (2 * k)] += t1[i][j];
    }
  }
  for (int i = 0; i < 2 * k; i++) {
    for (int j = 0; j < 2 * k; j++) {
      ans = max(ans, t2[i][j]);
    }
  }
  cout << ans << endl;
}

