    m[x[i] + K][y[i] + K]++;
  }

  FOR(y, 0, m.size()) FOR(x, 1, m.size()) { m[y][x] += m[y][x - 1]; }
  FOR(y, 1, m.size()) FOR(x, 0, m.size()) { m[y][x] += m[y - 1][x]; }

  /*
  cout << " black map " << endl;
  REP(i, mb.size()) {
