    cout << endl;
  }
  cout << endl;

  cout << " white map " << endl;
  REP(i, mw.size()) {
    REP(j, mw.size()) { cout << mw[i][j] << " "; }
    cout << endl;
  }
  cout << endl;
  */

  int ans = 0;
  REP(i, 2 * K) REP(j, 2 * K) { ans = max(ans, m[i][j]); }
  cout << ans << endl;

  return 0;
}

#include <iostream>
#include <cmath>
#include <string>
#include <boost/multi_array.hpp>

int main() {
	int N, K;
	int x, y;
	std::string col;
	int num, ans;

	std::cin >> N >> K;

	int grid[2*K+1][2*K+1] = {};
	/*
	速度を上げる必要がある　評価回数を削減するには「累積和」に帰着させたい
	このような格子パターンではimos法が有効
	条件iを満たす領域の端っこに+1,その対角線側の一歩外に+1を置き、
	grid[a+1][b+1] += -grid[a][b]+grid[(a+1)][b]+grid[a][(b+1)]する

	評価は累積和K^2、+-1を置くのにNでO(N+K^2)
	*/
	for (int i = 0; i < N; i++) {
		std::cin >> x >> y >> col;
		//白ならxにKを加えて黒にする
		if (col == "W") {
			x += K;
		}
		//2Kでmodを取る
		x = x % (2*K);
		y = y % (2*K);
		int ldx = (x+1)%(2*K);
		int ldy = (y+1)%(2*K);
		grid[ldx][ldy] += 1;
	}
	//テスト出力
	if (false) {
		for (int a = 0; a < 2*K; a++) {
			for (int b = 0; b < 2*K; b++) {
				std::cout << grid[a][b] << " ";
			}
			std::cout << std::endl;
		}
	}
	//累積和
	for (int a = 0; a < 2*K; a++) {
		for (int b = 0; b < 2*K; b++) {
			grid[a+1][b+1] += -grid[a][b]+grid[(a+1)][b]+grid[a][(b+1)];
		}
	}
	//テスト出力
	if (false) {
		for (int a = 0; a < 2*K; a++) {
			for (int b = 0; b < 2*K; b++) {
				std::cout << grid[a][b] << " ";
			}
			std::cout << std::endl;
		}
	}
	ans = 0;
	int sum;
	for (int a = 0; a < K; a++) {
		for (int b = 0; b < K; b++) {
			sum = grid[a][b] - grid[a][0] - grid[0][b] + grid[0][0];
			sum += grid[a+K][b+K] - grid[a+K][b] - grid[a][b+K] + grid[a][b];
			sum += grid[2*K][b] - grid[2*K][0] - grid[a+K][b] + grid[a+K][0];
			sum += grid[a][2*K] - grid[a][b+K] - grid[0][2*K] + grid[0][b+K];
			sum = std::max(sum, N-sum);
			ans = std::max(ans, sum);
			//std::cout << sum << " ";
		}
		std::cout << std::endl;
	}

	//答えの出力
	std::cout << ans << std::endl;

	return 0;
}

