        scanf("%d %d %c", &x, &y, &c);
        if (c == 'W') {
            c = 'B';
            x += k;
        }
        x %= dk;
        y %= dk;
        v[x   ][y   ]++;
        v[x+k ][y   ]--;
        v[x   ][y+k ]--;
        v[x+k ][y+k ]+=2;
        v[x+dk][y+k ]--;
        v[x+k ][y+dk]--;
        v[x+dk][y+dk]++;
    }

    re(i, 0, 4 * k) {
        re(j, 0, 4 * k) {
            if (i == 0 && j == 0) {
                continue;
            } else if (i == 0 && j != 0) {
                v[i][j] += v[i][j - 1] + 0 - 0;
            } else if (i != 0 && j == 0) {
                v[i][j] += 0 + v[i - 1][j] - 0;
            } else {
                v[i][j] += v[i][j - 1] + v[i - 1][j] - v[i - 1][j - 1];
            }
        }
