int cometrue(int x, int y, char c, int offset_x, int offset_y, int K)
{
  char this_is_in;

  int amari_x = ((x-offset_x) % (2*K));
  if (amari_x < 0) {
    amari_x += 2*K;
  }
  int amari_y = ((y-offset_y) % (2*K));
  if (amari_y < 0) {
    amari_y += 2*K;
  }
  // cerr << "x-offset_x: " << (x-offset_x) << endl;
  // cerr << "(x-offset_x) % " << 2*K << ": "  << (x-offset_x)%(2*K) << endl;
  // cerr << "amari_x: " << amari_x << endl;
  // cerr << "amari_y: " << amari_y << endl;

  int xorr = ( ( amari_x < K) ^ (amari_y < K));

  if (xorr) {
    this_is_in = 'B';
  } else 
    this_is_in = 'W';
  return (this_is_in==c);
}

