    x %= k << 1, y %= k << 1;
    if (x / k + y / k == 1) {
      if (c == 'W')
        cnt[x % k][y % k] += 1;
      else
        cnt[x % k][y % k] -= 1;
    } else {
      if (c == 'B')
        cnt[x % k][y % k] += 1;
      else
        cnt[x % k][y % k] -= 1;
    }
  }

  vector<vector<int>> s1(k, vector<int>(k)), s2(k, vector<int>(k));
  for (int i = 0; i < k; ++i)
    for (int j = 0; j < k; ++j) {
      int ii = k - i - 1, jj = k - j - 1;
      s1[i][j] = cnt[i][j], s2[ii][jj] = cnt[ii][jj];
      if (i) {
        s1[i][j] += s1[i - 1][j];
        s2[ii][jj] += s2[ii + 1][jj];
      }
      if (j) {
        s1[i][j] += s1[i][j - 1];
        s2[ii][jj] += s2[ii][jj + 1];
      }
      if (i && j) {
        s1[i][j] -= s1[i - 1][j - 1];
        s2[ii][jj] -= s2[ii + 1][jj + 1];
      }
    }

  int d = 0;
  for (int i = 0; i < k; ++i)
    for (int j = 0; j < k; ++j) {
      int u;
      if (i && j)
        u = s1[i - 1][j - 1] + s2[i][j];
      else
        u = s2[i][j];
      d = max(d, abs(u * 2 - s2[0][0]));
    }
  printf("%d\n", (n + d) >> 1);

  return 0;
}

