int main()
{
  int N, K;
  cin >> N >> K;
  vector<vector<int>> imos(K * 6, vector<int>(K * 6));
  while (N--) {
    int x, y;
    char c;
    cin >> x >> y >> c;
    if (c == 'B') y += K;
    x %= K * 2;
    y %= K * 2;
    if (x >= K and y >= K) x -= K, y -= K;
    FOR(i, -1, 4) FOR(j, -1, 4) if (abs(i + j) % 2 == 0) {
      int X = x + i * K, Y = y + j * K;
      if (X < 0 or Y < 0) continue;
      imos[X][Y]++;
      imos[X + K][Y]--;
      imos[X][Y + K]--;
      imos[X + K][Y + K]++;
    }
  }

  REP(i, imos.size()) REP(j, imos[0].size() - 1) imos[i][j + 1] += imos[i][j];
  REP(i, imos.size() - 1) REP(j, imos[0].size()) imos[i + 1][j] += imos[i][j];
  int ret = 0;
  for (auto v : imos) for (auto x : v) ret = max(ret, x);
  cout << ret << endl;
  return 0;
}

