int cal(int x1, int y1, int x2, int y2, vector<vector<int> >& board)
{
  int ret = board[y2][x2] - board[y2][x1] - board[y1][x2] + board[y1][x1];
  return ret;
}

int main()
{
  int N, K;
  scanf("%d %d", &N, &K);
  vector<vector<int> > board(4 * K + 1, vector<int>(4 * K + 1, 0));
  for (int i = 0; i < N; ++i) {
    int x, y;
    char c;
    scanf("%d %d %c", &x, &y, &c);
    if (c == 'W') { x += K; }
    x %= (2 * K);
    y %= (2 * K);
    ++board[y + 1][x + 1];
  }

  for (int y = 1; y <= 4 * K; ++y) {
    for (int x = 1; x <= 4 * K; ++x) {
      board[y][x] += board[y][x - 1] + board[y - 1][x] - board[y - 1][x - 1];
    }
  }
  // fprintf(stderr, "DEBUG: after cumulative summing\n");
  // for (int i = 0; i <= 2 * K; ++i) {
  //   for (int j = 0; j <= 2 * K; ++j) {
  //     fprintf(stderr, "%3d |", board[i][j]);
  //   }
  //   fprintf(stdout, "\n");
  // }
  int ans = 0;
  for (int x = 0; x <= K; ++x) {
    for (int y = 0; y <= K; ++y) {
      int x0 = 0, y0 = 0;
      int x1 = max(0, x - K), y1 = max(0, y - K);
      int x2 = x, y2 = y;
      int x3 = min(x + K, 2 * K), y3 = min(y + K, 2 * K);
      int x4 = 2 * K, y4 = 2 * K;
      int cnt = cal(x0, y0, x1, y1, board) +
        cal(x2, y0, x3, y1, board) +
        cal(x1, y1, x2, y2, board) +
        cal(x3, y1, x4, y2, board) +
        cal(x0, y2, x1, y3, board) +
        cal(x2, y2, x3, y3, board) +
        cal(x1, y3, x2, y4, board) +
        cal(x3, y3, x4, y4, board);
      // fprintf(stderr, "DEBUG: (x, y)=(%d, %d), cnt=%d\n", x, y, cnt);
      ans = max(ans, cnt);
    }
  }
  printf("%d\n", ans);

  return 0;
}

