        else black_cnt[(x + k) % (2 * k)][y % (2 * k)]++;
    }

    vector<VI> cnt_sum(2 * k + 1, VI(2 * k + 1, 0));
    FOR(i, 1, 2 * k)FOR(j, 1, 2 * k) cnt_sum[i][j] = black_cnt[i - 1][j - 1];
    FOR(i, 1, 2 * k)FOR(j, 0, 2 * k) cnt_sum[i][j] += cnt_sum[i - 1][j];
    FOR(i, 0, 2 * k)FOR(j, 1, 2 * k) cnt_sum[i][j] += cnt_sum[i][j - 1];

