        cnt += sub_sum(0, j + k, i, 2 * k, cnt_sum);
        cnt += sub_sum(i + k, 0, 2 * k, j, cnt_sum);
        ans = max(ans, cnt);
    }
    cout << ans << endl;
    return 0;
}

