        int cx = std::min(std::max(0, X[i]), kk);
        int cy = std::min(std::max(0, Y[i]), kk);
        int dx = std::min(std::max(0, X[i] + k), kk);
        int dy = std::min(std::max(0, Y[i] + k), kk);
        r += w[dy][dx] - w[cy][dx] - w[dy][cx] + w[cy][cx];
      }
      if (r > ans) ans = r;
    }
  }
  printf("%d", ans);
  return 0;
}

