int calcBlack(int x1,int y1,int x2,int y2){
    int res = 0;
    if(0<x1 && 0<y1) res+=sumBrack[x1-1][y1-1];
    if(0<x1)         res-=sumBrack[x1-1][y2];
    if(0<y1)         res-=sumBrack[x2][y1-1];
    res+=sumBrack[x2][y2];
    return res;
}

int calcWhite(int x1,int y1,int x2,int y2){
    int res = 0;
    if(0<x1 && 0<y1) res+=sumWhite[x1-1][y1-1];
    if(0<x1)         res-=sumWhite[x1-1][y2];
    if(0<y1)         res-=sumWhite[x2][y1-1];
    res+=sumWhite[x2][y2];
    return res;
}

