            sumBrack[x][y+2*K]++;
            sumBrack[x+2*K][y+2*K]++;
        }else{
            sumWhite[x][y]++;
            sumWhite[x+2*K][y]++;
            sumWhite[x][y+2*K]++;
            sumWhite[x+2*K][y+2*K]++;
        }
