        arr[0][i] += arr[0][i - 1];


    for(int i = 1; i < 2 * k; ++i)
        arr[i][0] += arr[i - 1][0];

    for(int i = 1; i < 2 * k; ++i)
        for(int j = 1; j < 2 * k; ++j)
            arr[i][j] += arr[i - 1][j] + arr[i][j - 1] - arr[i - 1][j - 1];


