        for(int j = -2 * k; j < 2 * k; ++j)
        {
            int temp = 0;

            temp += amount(i, j, i - k + 1, j - k + 1);

            temp += amount(i + k, j + k, i + 1, j + 1);

            temp += amount(i + 2 * k, j, i + k + 1, j - k + 1);

            temp += amount(i, j + 2 * k, i - k + 1, j + k + 1);

            temp += amount(i + 2 * k, j + 2 * k, i + k + 1, j + k + 1);

            answer = max(answer, temp);
