	rep(i, 0, N){
		int x, y;
		char c;
		cin >> x >> y >> c;
		if(c == 'W') y += K;
		acc[y%(2*K)+1][x%(2*K)+1]++;
	}

	makeAcc();

	cout << solve() << endl;

	return 0;
}

