// while[x][y] = マス(x, y)を右上とした長方形に
//               含まれている(白マス-黒マス)の総数
int16_t white[1000][1000];
int main() {
    int N, K;
    cin >> N >> K;

    // 黒マスを指定する条件の数
    int bnum = 0;
    // まずは2K * 2Kの範囲に絞る
    for (int i = 0; i < N; ++i) {
        int x, y, z;
        char sc;
        cin >> x >> y >> sc;
        x %= K * 2;
        y %= K * 2;
        z = (sc == 'W');
        // K * Kの範囲に絞る
        // 座標をKで割った値の偶奇で色が変わる
        z += x / K + y / K;
        z %= 2;
        x %= K;
        y %= K;
        white[x][y] += (z ? 1 : -1);
        if (z == 0)
            ++bnum;
    }

    // 2次元imosの要領で展開
    for (int x = 0; x < K; ++x) {
        for (int y = 1; y < K; ++y) {
            white[x][y] += white[x][y - 1];
        }
    }

    for (int x = 1; x < K; ++x) {
        for (int y = 0; y < K; ++y) {
            white[x][y] += white[x - 1][y];
        }
    }

    int ans = 0;
    for (int x = 0; x < K; ++x) {
        for (int y = 0; y < K; ++y) {
            // (x, y)を右上の頂点とした長方形を白く塗るパターン
            int w = white[K - 1][K - 1] - white[x][K - 1] - white[K - 1][y] +
                    white[x][y] * 2 + bnum;

            ans = max(ans, max(w, N - w));
        }
    }

    cout << ans << endl;
    return 0;
}

