			t=calb(1,1,k,k)+calb(k+1,k+1,k+k,k+k)+calb(-k+1,-k+1,0,0)+calb(-k+1,k+1,0,k+k)+calb(k+1,-k+1,2*k,0)+calw(k+1,1,2*k,k)+calw(1,k+1,k,2*k)+calw(1,-k+1,k,0)+calw(-k+1,1,0,k);
			ans=max(t,ans);
