typedef long long int ll;
typedef unsigned long long int ull;
#define BIG_NUM 2000000000
#define HUGE_NUM 1000000000000000000
#define MOD 1000000007
#define EPS 0.000000001
using namespace std;


#define SIZE 2005

int N,K;
int table[SIZE][SIZE],table2[SIZE][SIZE];

int calc(int x1,int y1,int x2,int y2){

	int base = table[x2][y2];
	if(y1 > 0){
		base -= table[x2][y1-1];
	}
	if(x1 > 0){

		base -= table[x1-1][y2];
	}
	if(x1 > 0 && y1 > 0){

		base += table[x1-1][y1-1];
	}

	return base;
}

int calc2(int x1,int y1,int x2,int y2){

	int base = table2[x2][y2];
	if(y1 > 0){
		base -= table2[x2][y1-1];
	}
	if(x1 > 0){

		base -= table2[x1-1][y2];
	}
	if(x1 > 0 && y1 > 0){

		base += table2[x1-1][y1-1];
	}

	return base;
}


int main(){

	scanf("%d %d",&N,&K);

	for(int x = 0; x < 2*K; x++){
		for(int y = 0; y < 2*K; y++){

			table[x][y] = 0;
			table2[x][y] = 0;
		}
	}

	int tmp_x,tmp_y;
	char buf[2];

	int num_black = 0,num_white = 0;

	for(int i = 0; i < N; i++){

		scanf("%d %d %s",&tmp_x,&tmp_y,buf);

		if(buf[0] == 'B'){
			num_black++;
			table[tmp_x%(2*K)][tmp_y%(2*K)]++;
		}else{
			num_white++;
			table2[tmp_x%(2*K)][tmp_y%(2*K)]++;
		}
	}

	int ans = 0;

	//まずは横に累積和
	for(int y = 0; y < 2*K; y++){
		for(int x = 1; x < 2*K; x++){
			table[x][y] += table[x-1][y];
			table2[x][y] += table2[x-1][y];
		}
	}

	//次に縦に累積和
	for(int x = 0; x < 2*K; x++){
		for(int y = 1; y < 2*K; y++){

			table[x][y] += table[x][y-1];
			table2[x][y] += table2[x][y-1];
		}
	}

	for(int sx = 0; sx <= K; sx++){
		for(int sy = 0; sy <= K; sy++){

			int sum = 0;
			int minus = 0;

			//左上
			if(sx > 0 && sy > 0){
				tmp_x = sx-1;
				tmp_y = sy-1;

				sum += calc(max(0,tmp_x-(K-1)),max(0,tmp_y-(K-1)),tmp_x,tmp_y);
				minus += calc2(max(0,tmp_x-(K-1)),max(0,tmp_y-(K-1)),tmp_x,tmp_y);
			}
			//右上
			if(sx+K-1 < 2*K-1 && sy > 0){

				tmp_x = sx+K;
				tmp_y = sy-1;

				sum += calc(tmp_x,max(0,tmp_y-(K-1)),min(2*K-1,tmp_x+K-1),tmp_y);
				minus += calc2(tmp_x,max(0,tmp_y-(K-1)),min(2*K-1,tmp_x+K-1),tmp_y);
			}

			//自分
			sum += calc(sx,sy,sx+K-1,sy+K-1);
			minus += calc2(sx,sy,sx+K-1,sy+K-1);

			//左下
			if(sx > 0 && sy+K-1 < 2*K-1){

				tmp_x = sx-1;
				tmp_y = sy+K;

				sum += calc(max(0,tmp_x-(K-1)),tmp_y,tmp_x,min(2*K-1,tmp_y+K-1));
				minus += calc2(max(0,tmp_x-(K-1)),tmp_y,tmp_x,min(2*K-1,tmp_y+K-1));
			}
			//右下
			if(sx+K-1 < 2*K-1 && sy+K-1 < 2*K-1){

				tmp_x = sx+K;
				tmp_y = sy+K;

				sum += calc(tmp_x,tmp_y,min(2*K-1,tmp_x+K-1),min(2*K-1,tmp_y+K-1));
				minus += calc2(tmp_x,tmp_y,min(2*K-1,tmp_x+K-1),min(2*K-1,tmp_y+K-1));
			}

			ans = max(ans,sum+num_white-minus); //選択領域を黒
			ans = max(ans,num_black-sum+minus); //選択領域を白
		}
	}

	printf("%d\n",ans);

	return 0;
}

