int safe(int x, int T) {
    return max(0, min(x, T));
}

void fill(vector<vector<int>> &v, int x, int y, int K) {
    int right = safe(x + 1, 2*K);
    int left = safe(x + 1 - K, 2*K);
    int top = safe(y + 1, 2*K);
    int bot = safe(y + 1 - K, 2*K);

    v[right][top]++;
    v[left][bot]++;
    v[left][top]--;
    v[right][bot]--;
}

int main() {
    int N, K;
    cin >> N >> K;
    vector<vector<int>> diff(2*K + 1, vector<int>(2*K + 1, 0));

    REP(i, N) {
        int x, y;
        char c;
        cin >> x >> y >> c;
        if(c == 'W') {
            x += K;
        }
        x %= 2*K;
        y %= 2*K;
        FOR(s, -2, 3) {
            FOR(t, -2, 3) {
                if((s + t + 334)%2 == 0) {
                    fill(diff, x + s*K, y + t*K, K);
                }
            }
        }
    }
    vector<vector<int>> s(2*K + 1, vector<int>(2*K + 1, 0));
    s[0][0] = diff[0][0];
    int res = s[0][0];
    FOR(i, 1, 2*K + 1) {
        s[i][0] = diff[i][0] + s[i - 1][0];
        s[0][i] = diff[0][i] + s[0][i - 1];
        res = max({res, s[i][0], s[0][i]});
    }

    FOR(i, 1, 2*K + 1) {
        FOR(j, 1, 2*K + 1) {
            s[i][j] = diff[i][j] + s[i - 1][j] + s[i][j - 1] - s[i - 1][j - 1];
            res = max(res , s[i][j]);
        }
    }
    cout << res << endl;
    return 0;
}

