  reps(i, 2005) reps(j, 2005) w[i][j] += w[i - 1][j];
  reps(i, 2005) reps(j, 2005) w[i][j] += w[i][j - 1];
  i64 ans = 0;
  rep(i, k + 1) rep(j, k + 1) {
    amax(ans, calcs(i, j, k, true));
    amax(ans, calcs(i, j, k, false));
  }
  cout << ans << endl;
  return 0;
}

