   }
   C.build();
   int ans = 0;

   for(int i = 0;i <= k;i++)for(int j = 0;j <= k;j++){
      int count = 0;

      count += C.query(i,j,i+k,j+k);
      count += C.query(i+k,j+k,2*k,2*k);
      count += C.query(0,0,i,j);
      count += C.query(i+k,0,2*k,j);
      count += C.query(0,j+k,i,2*k);

      maxs(ans,count);
   }
   cout << ans << endl;
}

