    for(int i = 0;i < n;i ++)
    {
        scanf("%d %d %c",&s[i].x,&s[i].y,&ch);
        s[i].x %= k * 2;///通过移位（每次移动2k）都可以在这个2k*2k的图里进行操作 不改变原来的意义 也就是当前坐标和原坐标涂的颜色肯定是相同的
        s[i].y %= k * 2;
        s[i].no = (ch == 'W' ? 1 : 0);///颜色转为数字
    }
    for(int i = 0;i < k;i ++)///y轴移动 x坐标边界改变
    {
        sum = 0;
        memset(v,0,sizeof(v));///初始化
        for(int j = 0;j < n;j ++)
        {
            int p = s[j].x >= i && s[j].x < i + k;///x坐标在i 到 i + k为一个区域
            int q = s[j].y >= 0 && s[j].y < k;///y坐标先不改变 默认 0 到 k - 1
            if(p ^ q ^ s[j].no)sum ++,v[s[j].y] ++;///先选定一种情况 满足的话 sum ++  y坐标对应对应的 v ++
            else v[s[j].y] --;///不满足的话 就是不满足 0 到 k - 1 的划分 在v中对应y坐标位置进行标记
        }
        for(int j = 0;j < k;j ++)
        {
            sum -= v[j] + v[j + k];///y坐标在 j 到j + k 区域  去掉
            ans = max(ans,max(sum,n - sum));///更新最大值，sum 和 n - sum 是黑白互换的不同结果（原来黑色的地方可以变白色，那么白色的变黑色）
        }
    }
    printf("%d",ans);
}

