int query(int i1,int j1,int i2,int j2){
    if(i1<=0) i1=1;
    if(j1<=0) j1=1;
    return S[i2][j2]-S[i1-1][j2]-S[i2][j1-1]+S[i1-1][j1-1];
}

int main(){
