    }
    for(int i=1;i<=3*K+2;i++){
        for(int j=1;j<=3*K+2;j++){
            S[i][j]=C[i][j]+S[i-1][j]+S[i][j-1]-S[i-1][j-1];

        }
    }
    int ans=-1;
    for(int i=1;i<=K;i++){
        for(int j=1;j<=K;j++){
            int temp=query(i-K+1,j-K+1,i,j)+query(i+1,j+1,i+K,j+K)
                    +query(i+K+1,j+K+1,i+2*K,j+2*K)+query(i-K+1,j+K+1,i,j+2*K)
                    +query(i+K+1,j-K+1,i+2*K,j);
