int judge(int a, int b, int x, int y, int k){
  int dx = (2 * k + x - a) % (2 * k);
  int dy = (2 * k + y - b) % (2 * k);
  if (dx>=0 && dx<k && dy>=k && dy<(2*k)) return 1;
  if (dy>=0 && dy<k && dx>=k && dx<(2*k)) return 1;
  return 0;
}

