int main(void) {
	int N,K;
	cin >> N >>K;
	int* X = new int[N + 1];
	int* Y = new int[N + 1];
	string* C = new string[N + 1];
	for (int i = 0; i < N; i++) {
		cin >> X[i] >> Y[i] >> C[i];
	}
	for (int i = 0; i < N; i++) {
		if (C[i] == "B") {
			X[i] = X[i] % (K * 2);
			Y[i] = Y[i] % (K * 2);
		}
	}
	for (int i = 0; i < N; i++) {
		if (C[i] == "B") {
			if (X[i] > K) {
				X[i] = X[i] - K;
				Y[i] = Y[i] - K;
			}
		}else if (C[i] == "W") {
			if (X[i] > K) {
				X[i] = X[i] - K;
			}
			else if (Y[i] > K) {
				Y[i] = Y[i] - K;
			}
		}
	}

	int top = 0;
	int bottom = 2 * K;
	int left = 2 * K;
	int right = 0;

	for (int i = 0; i < N; i++) {
		if (X[i] < left) {
			left = X[i];
		}
		if (X[i] > right) {
			right = X[i];
		}
		if (Y[i] < bottom) {
			bottom = Y[i];
		}
		if (Y[i] > top) {
			top = Y[i];
		}
	}
	int impossible = 0;
	for (int i = 0; i < N; i++) {
		if (X[i] - left > K || Y[i] - bottom  > K) {
			impossible++;
		}
	}
	int possibility = N - impossible;
	cout << possibility << flush;
	delete[] X;
	delete[] Y;
	delete[] C;
	return 0;
}

