void imos(int x0, int y0, int x1, int y1, vector<vector<int>> &memo) {
    ++memo.at(x0).at(y0);
    --memo.at(x1+1).at(y0);
    --memo.at(x0).at(y1+1);
    ++memo.at(x1+1).at(y1+1);
}

void solve() {
    int n, k;
    cin >> n >> k;
    vector<pair<int, int>> xy(n);
    for (int i=0; i<n; ++i) {
        char c;
        cin >> xy.at(i).first >> xy.at(i).second >> c;
        if (c == 'B') xy.at(i).first += k;
        xy.at(i).first %= 2 * k;
        xy.at(i).second %= 2 * k;
    }

    vector<vector<int>> memo(2*k+1, vector<int>(2*k+1));
    for (int i=0; i<n; ++i) {
        ll x = xy.at(i).first, y = xy.at(i).second;
        if (x/k == y/k) {
            x = x%k, y = y%k;
            imos(0, 0, x, y, memo);
            imos(x+1, y+1, x+k, y+k, memo);
            imos(x+k+1, 0, 2*k-1, y, memo);
            imos(0, y+k+1, x, 2*k-1, memo);
            imos(x+k+1, y+k+1, 2*k-1, 2*k-1, memo);
        } else {
            x = x%k, y = y%k;
            imos(x+1, 0, x+k, y, memo);
            imos(0, y+1, x, y+k, memo);
            imos(x+1, y+k+1, x+k, 2*k-1, memo);
            imos(x+k+1, y+1, 2*k-1, y+k, memo);
        }
    }
    for (int i=0; i<2*k+1; ++i) {
        for (int j=0; j<2*k+1; ++j) {
            if (i > 0) memo.at(i).at(j) += memo.at(i-1).at(j);
            if (j > 0) memo.at(i).at(j) += memo.at(i).at(j-1);
            if (i > 0 && j > 0) memo.at(i).at(j) -= memo.at(i-1).at(j-1);
        }
    }
    int res = 0;
    for (int i=0; i<2*k; ++i) for (int j=0; j<2*k; ++j) chmax(res, memo.at(i).at(j));
    cout << res << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(20);

    solve();

    return 0;
}

