	int ans=0,cnt=0;
	for(i=1;i<=m;i++)for(j=1;j<=m;j++){
		cnt=f(a,0,0,i,j)
		+f(b,i,0,i+m,j)
		+f(a,i+m,0,m+m,j)
		+f(b,0,j,i,j+m)
		+f(a,i,j,i+m,j+m)
		+f(b,i+m,j,m+m,j+m)
		+f(a,0,j+m,i,m+m)
		+f(b,i,j+m,i+m,m+m)
		+f(a,i+m,j+m,m+m,m+m);
		ans=max(ans,cnt);
		cnt=f(b,0,0,i,j)
		+f(a,i,0,i+m,j)
		+f(b,i+m,0,m+m,j)
		+f(a,0,j,i,j+m)
		+f(b,i,j,i+m,j+m)
		+f(a,i+m,j,m+m,j+m)
		+f(b,0,j+m,i,m+m)
		+f(a,i,j+m,i+m,m+m)
		+f(b,i+m,j+m,m+m,m+m);
		ans=max(ans,cnt);
	}
	cout<<ans;
	return 0;
}

