ll barr[N][N];

ll getW(int x, int y, int x2, int y2)
{
	if(x2 < x || y2 < y)return 0;
	ll temp = warr[x2][y2] - warr[x2][y-1] - warr[x-1][y2];
	temp += warr[x-1][y-1];
	return temp;
}
ll getB(int x, int y, int x2, int y2)
{
	if(x2 < x || y2 < y)return 0;
	ll temp = barr[x2][y2] - barr[x2][y-1] - barr[x-1][y2];
	temp += barr[x-1][y-1];
	return temp;
}

