	for(int i=0;i <= 4*K;i++){
		for(int j=0;j < 4*K;j++){
			imosu[i][j+1] += imosu[i][j];
		}
	}
	for(int j=0;j <= 4*K;j++){
		for(int i=0;i < 4*K;i++){
			imosu[i+1][j] += imosu[i][j];
		}
	}

