int get(int x, int y, vector<Point> &a) {
    int answ = 0, ansb = 0;
    for (int i = 0; i < n; ++i) {
        int tmpx = (a[i].x - abs(abs(a[i].x - x) - k) % k);
        int tmpy = (a[i].y - abs(abs(a[i].y - y) - k) % k);
        /*if (x == 0 && y == 1 && c == 'W') {
            cout << (abs(x - tmpx) % k + abs(y - tmpy) % k) _ tmpx _ tmpy << endl;
        }*/
        if ((abs(x - tmpx) / k + abs(y - tmpy) / k) % 2 == 0) {
            if (a[i].col == 'W') {
                answ++;
            } else {
                ansb++;
            }
        } else {
            if (a[i].col != 'W') {
                ++answ;
            } else {
                ansb++;
            }
        }
    }
    //if (x == 0 && y == 1 && c == 'W') cout << ans << endl;
    return max(answ, ansb);
}

void solve() {
    cin >> n >> k;
    vector<Point> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i].x >> a[i].y >> a[i].col;
    }
