#include <bits/stdc++.h>
using namespace std;
int N, K;

void add(int x, int y, vector<vector<int>> &A) {
    A[x][y] += 1;
    A[x][y + K] -= 1;
    A[x + K][y] -= 1;
    A[x + K][y + K] += 1;
}

int main() {
    cin >> N >> K;
    vector<vector<int>> A(4*K, vector<int>(4*K, 0));
    for(int i=0; i<N; ++i) {
        int x, y; char c;
        cin >> x >> y >> c;
        if(c == 'W') x += K;
        x %= (2 * K); y %= (2 * K);
        add(x, y, A);
        add(x + K, y + K, A);
    }

    for(int i=0; i<4*K; ++i) {
        for(int j=1; j<4*K; ++j) {
            A[i][j] += A[i][j - 1];
        }
    }
    for(int i=0; i<4*K; ++i) {
        for(int j=1; j<4*K; ++j) {
            A[j][i] += A[j - 1][i];
        }
    }

    int res = 0;
    for(int i=0; i<4*K; ++i) {
        for(int j=0; j<4*K; ++j) {
            res = max(res, A[i][j]);
        }
    }
    cout << res << endl;
}

