	whitePointSumTable[0][0] = whitePointTable[0][0];
	for (int i = 1; i < K; ++i)
	{
		blackPointSumTable[0][i] = blackPointSumTable[0][i - 1] + blackPointTable[0][i];
		blackPointSumTable[i][0] = blackPointSumTable[i - 1][0] + blackPointTable[i][0];
		whitePointSumTable[0][i] = whitePointSumTable[0][i - 1] + whitePointTable[0][i];
		whitePointSumTable[i][0] = whitePointSumTable[i - 1][0] + whitePointTable[i][0];
	}

