int geta(int x,int y){
    return a[x][y-1]+a[x-1][y]-a[x-1][y-1];	
}
int getb(int x,int y){
	return b[x][y-1]+b[x-1][y]-b[x-1][y-1];
}
int getaa(int x1,int y1,int x2,int y2){
	if(x1>x2)return 0;
	if(y1>y2)return 0;
	return a[x2][y2]-a[x1-1][y2]-a[x2][y1-1]+a[x1-1][y1-1];
}
int getbb(int x1,int y1,int x2,int y2){
	if(x1>x2)return 0;
	if(y1>y2)return 0;
	return b[x2][y2]-b[x1-1][y2]-b[x2][y1-1]+b[x1-1][y1-1];
}
int main() {
    scanf("%d%d",&n,&k);
    for(int i=1;i<=n;i++){
    	scanf("%d%d",&x,&y);cin>>c;
