			a[i][j]+=geta(i,j);
			b[i][j]+=getb(i,j);
		}
	}
	for(int i=1;i<=k;i++){
		for(int j=1;j<=k;j++){
           tmp=getaa(1,1,i,j);
           tmp+=getbb(1,j+1,i,j+k)+getbb(i+1,1,i+k,j)+getaa(i+1,j+1,i+k,j+k);
           tmp+=getaa(1,j+k+1,i,2*k)+getaa(i+k+1,1,2*k,j)+getbb(i+k+1,j+1,2*k,j+k+1);
           tmp+=getbb(i+1,j+k+1,i+k+i,2*k)+getaa(i+k+1,2*k,j+k+1,2*k);
           ans=max(ans,tmp);
           tmp=getbb(1,1,i,j);
           tmp+=getaa(1,j+1,i,j+k)+getaa(i+1,1,i+k,j)+getbb(i+1,j+1,i+k,j+k);
           tmp+=getaa(1,j+k+1,i,2*k)+getbb(i+k+1,1,2*k,j)+getaa(i+k+1,j+1,2*k,j+k+1);
           tmp+=getaa(i+1,j+k+1,i+k+i,2*k)+getbb(i+k+1,2*k,j+k+1,2*k);
           ans=max(ans,tmp);           
		}
	}
	printf("%d\n",ans);
