			sum1[i][j] += sum1[i][j - 1] + sum1[i - 1][j] - sum1[i - 1][j - 1];
			sum2[i][j] += sum2[i][j - 1] + sum2[i - 1][j] - sum2[i - 1][j - 1];
		}
	}
	int ans = 0;
	for (int i = k * 2; i <= 4 * k; i++)
	{
		for (int j = k * 2; j <= 4 * k; j++)
		{
			int tot = getsum(sum1, i, j) + getsum(sum1, i - k, j - k)
				+ getsum(sum2, i - k, j) + getsum(sum2, i, j - k);
			ans = max(ans, tot);
		}
	}
	cout << ans << endl;
	return 0;
}

