		int  ans=0,ct,ct2;
		for(int sx=0; sx<k; sx++) {
			for(int sy=0; sy<k; sy++) {
				ct=0,ct2=0;
				for(int i=0; i<n; i++) {
					int dx=abs(xx[i]-sx)%(2*k);
					int dy=abs(yy[i]-sy)%(2*k);
					if((c0[i]=='W'&&((dx<k&&dy<k)||(dx>=k&&dy>=k)))||(c0[i]=='B'&&((dx>=k&&dy<k)||(dx<k&&dy>=k)))) {
						ct++;
					}
					if((c0[i]=='B'&&((dx<k&&dy<k)||(dx>=k&&dy>=k)))||(c0[i]=='W'&&((dx>=k&&dy<k)||(dx<k&&dy>=k)))) {
						ct2++;
					}
				}
				ans=max(ans,max(ct,ct2));
			}
		}
		printf("%d\n",ans);
		return 0;
	}
	return 0;
}

