/*
市松始点のバリエーション
(0,0) ~ (0,2K-1)
 ~          ~
(2K-1,0) ~ (2K-1,2K-1)

黒ならxだけに+Kして
2Kで剰余を取る

すると同時にいくつの(0~2K-1)内N個の点を白に染められるか

結局、正方形内に入れられる点の最大値となるのではないか


(u,v)を始点にしたとき、
白マス...((x-u)/K + (y-v)/K) % 2 == 0
黒    ...((x-u)/K + (y-v)/K) % 2 == 1

xi,yiが白であることを可能にする始点
u = (xi/K + 0...K-1) % K
v = (xi/K + 0...K-1) % K と

u = (xi/K + 0...K-1) % K+K
v = (xi/K + 0...K-1) % K+K
*/
char rev(char a) {
    if (a == 'W') return 'B';
    return 'W';
}

int main() {
    int N,K; cin >> N >> K;
    vector<int> x(N), y(N);
    vector<vector<int> > B(K, vector<int>(K, 0));
    vector<vector<int> > W(K, vector<int>(K, 0));
    vector<vector<int> > SB(K+1, vector<int>(K+1, 0));
    vector<vector<int> > SW(K+1, vector<int>(K+1, 0));
    int black = 0, white = 0;
    for (int i = 0; i < N; i++) {
        char tmp;
        cin >> x[i] >> y[i] >> tmp;
        int tx = x[i] % (2*K),ty = y[i] % (2*K);
        if (tx >= K && ty >= K) {tx -= K; ty -= K;}
        if (tx >= K) {
            tx -= K; tmp = rev(tmp);
        }
        if (ty >= K) {
            ty -= K; tmp = rev(tmp);
        }
        if (tmp == 'B') {
            black++;
            B[tx][ty]++;
        } else {
            white++;
            W[tx][ty]++;
        }
    }
    for (int i = 0; i < K; i++) {
        for (int j = 0; j < K; ++j) {
            SW[i+1][j+1] = SW[i][j+1] + SW[i+1][j] - SW[i][j] + W[i][j];
            SB[i+1][j+1] = SB[i][j+1] + SB[i+1][j] - SB[i][j] + B[i][j];
        }
    }

