      BTSum[i][j] = BT[i - 1][j - 1] + BTSum[i - 1][j] + BTSum[i][j - 1] -
                    BTSum[i - 1][j - 1];
      WTSum[i][j] = WT[i - 1][j - 1] + WTSum[i - 1][j] + WTSum[i][j - 1] -
                    WTSum[i - 1][j - 1];
    }
  }
  int ans = 0;

  //  DEBUG(BTSum[K][K]);
  //  DEBUG(WTSum[K][K]);

  FORS(i, 0, K / 2) {
    FORS(j, 0, K / 2) {
      int dxx[4] = {0, i, i + K / 2, K};
      int dyy[4] = {0, j, j + K / 2, K};
      int tmpans[2] = {0, 0};
      REP(k, 2) {
        REP(ii, 3) {
          REP(jj, 3) {
            int a0 = dxx[ii];
            int a1 = dyy[jj];
            int a2 = dxx[ii + 1];
            int a3 = dyy[jj + 1];
            if ((k + ii + jj) % 2 == 0)
              tmpans[k] +=
                  BTSum[a2][a3] - BTSum[a2][a1] - BTSum[a0][a3] + BTSum[a0][a1];
            if ((k + ii + jj) % 2 == 1)
              tmpans[k] +=
                  WTSum[a2][a3] - WTSum[a2][a1] - WTSum[a0][a3] + WTSum[a0][a1];
          }
        }
      }

      chmax(ans, tmpans[0]);
      chmax(ans, tmpans[1]);
    }
  }
  print(ans);
}

