        }
        for(int i = 1; i < 4*k; i ++){
            for(int j = 0; j < 4*k; j ++){
                if (j == 0) cnt[color][i][j] += cnt[color][i-1][j];
                else cnt[color][i][j] += cnt[color][i][j-1] + cnt[color][i-1][j] - cnt[color][i-1][j-1];
            }
        }
    }
    int ans = 0;
    for(int i = 0; i < 2*k; i ++){
        for(int j = 0; j < k; j ++){
            int a = getCount(i+k-1, j+k-1, i, j, 1);
            int b = getCount(i+k-1, j+2*k-1, i, j+k, 0);
            int c = getCount(i+2*k-1, j+k-1, i+k, j, 0);
            int d = getCount(i+2*k-1, j+2*k-1, i+k, j+k, 1);
            ans = max(ans, a+b+c+d);
        }
    }
    printf("%d\n", ans);

}

