template<typename T>
class Array2d {
public:
  Array2d();
  ~Array2d();
  // define copy constructor and overload assignment operator so both do deep copies.
  Array2d<T> &operator= (const Array2d<T> &t);

  // public functions to allocate/deallocate memory
  void NewArray2d(int nx2, int nx1);
  void DeleteArray2d();

  // overload operator() to access 
  T &operator() (const int n, const int i) { 
    return pdata_[i + nx1_*n]; }
  T operator() (const int n, const int i) const { 
    return pdata_[i + nx1_*n]; }

private:
  T *pdata_;
  int nx1_, nx2_;
};

//constructor
template<typename T>
Array2d<T>::Array2d()
  : pdata_(0), nx1_(0), nx2_(0)
{
}

// destructor
template<typename T>
Array2d<T>::~Array2d()
{
  DeleteArray2d();
}


//----------------------------------------------------------------------------------------
//! \fn
//  \brief 2d data allocation
template<typename T>
void Array2d<T>::NewArray2d(int nx2, int nx1)
{
  nx1_ = nx1;
  nx2_ = nx2;
  pdata_ = new T[nx1*nx2](); // allocate memory and initialize to zero
}

//----------------------------------------------------------------------------------------
//! \fn
//  \brief  free memory allocated for data array
template<typename T>
void Array2d<T>::DeleteArray2d()
{
  delete[] pdata_;
} 





