			cnt2+=sum[2*k-1][2*k-1][1]-sum[2*k-1][uc][1]-sum[ur][2*k-1][1]+sum[ur][uc][1];

			ans=max({ans,cnt1+bl-cnt2,cnt2+wh-cnt1});
