int getSum(const vec<int, 2>& sum, int i, int j, int K) {
  int b1 = sum[i][j];
  int b2 = sum[i][2 * K] - sum[i][j + K];
  int b3 = sum[i + K][j + K] - sum[i + K][j] - sum[i][j + K] + sum[i][j];
  int b4 = sum[2 * K][j] - sum[i + K][j];
  int b5 = sum[2 * K][2 * K] - sum[2 * K][j + K] - sum[i + K][2 * K] +
           sum[i + K][j + K];
  return b1 + b2 + b3 + b4 + b5;
}

void sum2d(vec<int, 2>& sum) {
  int H = sum.size(), W = sum[0].size();
  for (int i = 1; i < H; i++)
    for (int j = 1; j < W; j++)
      sum[i][j] += sum[i - 1][j] + sum[i][j - 1] - sum[i - 1][j - 1];
}

