	}

	void add(int y, int x, int value) {
		data[y + 1][x + 1] += value;
	}

	void build() {
		for (int i = 0; i <= _H; i++) {
			for (int j = 0; j < _W; j++) {
				data[i][j + 1] += data[i][j];
			}
		}
		for (int j = 0; j <= _W; j++) {
			for (int i = 0; i < _H; i++) {
				data[i + 1][j] += data[i][j];
			}
		}
	}

	///x1 - x2, y1 - y2
	T query(int x1, int y1, int x2, int y2) {
		return data[y2][x2] - data[y1][x2] - data[y2][x1] + data[y1][x1];
	}
};

int main() {
	cin.tie(0); ios_base::sync_with_stdio(false);
	cin >> N >> K;
	REP(i, N) {
		cin >> X[i] >> Y[i] >> c;
		if (c == 'B') Y[i] += K;
		X[i] %= 2 * K;
		Y[i] %= 2 * K;
	}
	imos2D<lint> dt(K * 2, K * 2);
	REP(i, N) dt.add(Y[i], X[i], 1);
	dt.build();

	lint maxv = 0;
	REP(i, K + 1) {
		REP(j, K + 1) {
			lint curr = 0;
			curr += dt.query(0, 0, i, j);
			curr += dt.query(i + K, 0, 2 * K, j);
			curr += dt.query(0, j + K, i, 2 * K);
			curr += dt.query(i, j, i + K, j + K);
			curr += dt.query(i + K, j + K, 2 * K, 2 * K);
			chmax(maxv, max(N - curr, curr));
		}
	}
	cout << maxv << endl;
}

