			return ib[y2][x2]-ib[y2][x1-1];
		}
		else{
			return ib[y2][x2];
		}
	}
}

int rw(int y1,int x1,int y2,int x2){
	if(y1<0||x1<0||y2<0||x2<0) return 0;
	if(y1>0){
		if(x1>0){
			return iw[y2][x2]-iw[y2][x1-1]-iw[y1-1][x2]+iw[y1-1][x1-1];
		}
		else{
			return iw[y2][x2]-iw[y1-1][x2];
		}
	}
	else{
		if(x1>0){
			return iw[y2][x2]-iw[y2][x1-1];
		}
		else{
			return iw[y2][x2];
		}
	}
}

int calc(int Y,int X){
	int res1=0,res2=0;
	res1+=rb(Y,X,K-1,min(X+K-1,2*K-1));
	res1+=rb(0,0,Y-1,X-1);
	if(X<K) res1+=rb(0,X+K,Y-1,2*K-1);
	res2+=rw(Y,0,K-1,X-1);
	res2+=rw(0,X,Y-1,min(X+K-1,2*K-1));
	if(X<K) res2+=rw(Y,X+K,K-1,2*K-1);
	return res1+res2;
}

