        if (lx1 > ux1 && ly1 > uy1) {
            ++imos[lx1][ly1];
            --imos[lx1][2 * K];
            --imos[2 * K][ly1];
            ++imos[2 * K][2 * K];

            ++imos[0][0];
            --imos[0][uy1];
            --imos[ux1][0];
            ++imos[ux1][uy1];

            ++imos[0][ly1];
            --imos[0][2 * K];
            --imos[ux1][ly1];
            ++imos[ux1][2 * K];

            ++imos[lx1][0];
            --imos[lx1][uy1];
            --imos[2 * K][0];
            ++imos[2 * K][uy1];
        }
        else if (lx1 > ux1) {
            ++imos[lx1][ly1];
            --imos[lx1][uy1];
            --imos[2 * K][ly1];
            ++imos[2 * K][uy1];

            ++imos[0][ly1];
            --imos[0][uy1];
            --imos[ux1][ly1];
            ++imos[ux1][uy1];
        }
        else if (ly1 > uy1) {
            ++imos[lx1][ly1];
            --imos[lx1][2 * K];
            --imos[ux1][ly1];
            ++imos[ux1][2 * K];

            ++imos[lx1][0];
            --imos[lx1][uy1];
            --imos[ux1][0];
            ++imos[ux1][uy1];
        }
        else {
            ++imos[lx1][ly1];
            --imos[lx1][uy1];
            --imos[ux1][ly1];
            ++imos[ux1][uy1];
        }
    }

    for (ll i = 0; i < 2 * K; i++) {
        for (ll j = 0; j <= 2 * K; j++) {
            imos[i + 1][j] += imos[i][j];
        }
    }
    for (ll i = 0; i <= 2 * K; i++) {
        for (ll j = 0; j < 2 * K; j++) {
            imos[i][j + 1] += imos[i][j];
        }
    }

    // for (ll i = 0; i < 2 * K + 1; i++) {
    //     for (ll j = 0; j < 2 * K + 1; j++) {
    //         cout << imos[i][j] << " ";
    //     }
    //     cout << "\n";
    // }
    // cout << "\n";

    ll ans = 0;
    for (ll i = 0; i < 2 * K; i++) {
        for (ll j = 0; j < 2 * K; j++) {
            ans = max(ans, imos[i][j]);
        }
    }

    cout << ans << "\n";

    return 0;
}

