			G[x + K][y + K]++;
		}
		if (x + K < 2 * K && y - K >= 0) {
			G[x + K][y - K]++;
		}
		if (x - K >= 0 && y + K < 2 * K) {
			G[x - K][y + K]++;
		}
		if (x - K >= 0 && y - K >= 0) {
			G[x - K][y - K]++;
		}
	}

	//二次元累積和
	vector<vector<Int>> S(2*K+1, vector<Int>(2*K+1));
	for (Int i = 0; i < 2*K; i++) {
		for (Int j = 0; j < 2*K; j++) {
			S[i + 1][j + 1] = S[i][j + 1] + S[i + 1][j] - S[i][j] + G[i][j];
