  auto get = [&](int bx, int by, int tx, int ty){
    int cur = cell[tx][ty];
    if(bx > 0) cur -= cell[bx - 1][ty];
    if(by > 0) cur -= cell[tx][by - 1];
    if(bx > 0 && by > 0) cur += cell[bx - 1][by - 1];

    return cur;
  };

