  }

  for(int r = 0; r < 2 * k; ++r){
    for(int c = 0; c < 2 * k; ++c){
      cell[r][c] += (r > 0 ? cell[r - 1][c] : 0)
                  + (c > 0 ? cell[r][c - 1] : 0)
                  - (r * c > 0 ? cell[r - 1][c - 1] : 0);
    }
  }

  for(int r = 0; r < k; ++r){
    for(int c = 0; c < k; ++c){
      int cur = 0;
      cur += get(0, 0, r, c)
           + get(r + 1, c + 1, r + k, c + k)
           + get(r + k + 1, c + k + 1, 2 * k - 1, 2 * k - 1)
           + get(r + k + 1, 0, 2 * k - 1, c)
           + get(0, c + k + 1, r, 2 * k - 1);
      best = max({best, cur, N - cur});
    }
  }

  cout << best << "\n";
  return 0;
}

