int solve(){
    int ans = 0;
    int inf = 0;
    for (int i = 0; i < 2*K; i++)
    {
        for (int j = 0; j < 2*K; j++)
        {
            int m = min(KK[i][j].first, KK[i][j].second);
            inf += m;
            KK[i][j].first -= m;
            KK[i][j].second -= m;
        }
    }
    int Max = N-inf;

    for (int x = 0; x < 2*K; x++)
    {
        for (int y = 0; y < 2*K; y++)
        {
            if(KK[x][y].first) Cs.emplace_back(x,y,KK[x][y].first,0);
            if(KK[x][y].second) Cs.emplace_back(x,y,0,KK[x][y].second);
        }
    }
    N = Cs.size();


    for (int i = 0; i < K; i++)
    {
        for (int j = 0; j < K; j++)
        {
            // (i,j)とW0を対応させる。
            int tmp = 0;
            // for (int x = 0; x < 2*K; x++)
            // {
            //     for (int y = 0; y < 2*K; y++)
            //     {
            //         int col = (x+i)/K+(y+j)/K;
            //         if(col%2) tmp += KK[x][y].first;
            //         else tmp += KK[x][y].second;
            //     }
            // }


            for (int k = 0; k < N; k++)
            {
                int col = (Cs[k].x+i)/K+(Cs[k].y+j)/K;
                if(col%2) tmp += Cs[k].f;
                else tmp += Cs[k].s;
            }
            ans = max(ans,tmp);
            ans = max(ans,Max-tmp);
        }
    }
    cout << ans+inf << endl;
    return 0;
}   

