		{
			int nx=x % k,ny=y % k;
			Add(0,0,nx+1,ny+1);
			Add(nx+k+1,0,2*k,ny+1);
			Add(0,ny+k+1,nx+1,2*k);
			Add(nx+k+1,ny+k+1,2*k,2*k);
			Add(nx+1,ny+1,nx+k+1,ny+k+1);
		}
		else
		{
			int nx=x % k,ny=y % k;
			Add(nx+1,0,nx+k+1,ny+1);
			Add(nx+1,ny+k+1,nx+k+1,2*k);
			Add(0,ny+1,nx+1,ny+k+1);
