// [x1, x2), [y1, y2)
int query(int x1, int y1, int x2, int y2)
{
    return s[x2][y2] - s[x1][y2] - s[x2][y1] + s[x1][y1];
}

void Main()
{
    int n, k;
    cin >> n >> k;
    rep(i, n)
    {
        int x, y;
        char c;
        cin >> x >> y >> c;
        if (c == 'W')
        {
            y += k;
        }
        x %= k * 2;
        y %= k * 2;
        ++table[x][y];
    }

    rep(x, 2 * k) rep(y, 2 * k)
    {
        s[x + 1][y + 1] = s[x][y + 1] + s[x + 1][y] - s[x][y] + table[x][y];
    }

    int ans = 0;
    rep(i, k) rep(j, k)
    {
        int ra = query(0, 0, i, j);
        int rb = query(i + k, 0, 2 * k, j);
        int rc = query(i, j, i + k, j + k);
        int rd = query(0, j + k, i, 2 * k);
        int re = query(i + k, j + k, 2 * k, 2 * k);
        ans = max(ra + rb + rc + rd + re, ans);
    }
    cout << ans << endl;
}

