            } else if (i == 1) {
                int x = sum[i + K - 1][j + K - 1] - sum[i - 1][j + K - 1];
                x += sum[i - 1][2 * K] - sum[i - 1][j + K - 1];
                x += sum[2 * K][2 * K] - sum[i + K - 1][2 * K] - sum[2 * K][j + K - 1] + sum[i + K - 1][j + K - 1];
                if (x > N) continue;
                int y = N - x;
                ans = max(ans, max(x, y));
