// cout << "i: " << i << ", j: " << j << ", x: " << x << ", y: " << y << endl;
            } else {
                int x = sum[2 * K][2 * K];
                x -= sum[i - 1][j + K - 1] - sum[i - 1][j - 1];
                x -= sum[i + K - 1][j - 1] - sum[i - 1][j - 1];
                x -= sum[i + K - 1][j + K] - sum[i + K - 1][j + K - 1] - sum[i - 1][j + K];
