int solve(){
    int ans = 0;
    vector<vector<int> > BS(K+1,vector<int>(K+1,0));
    vector<vector<int> > WS(K+1,vector<int>(K+1,0));

    for (int i = 0; i < K; i++)
    {
        for (int j = 0; j < K; j++)
        {
            BS[i+1][j+1] = BS[i][j+1] + BS[i+1][j] - BS[i][j] + Black[i][j];
            WS[i+1][j+1] = WS[i][j+1] + WS[i+1][j] - WS[i][j] + White[i][j];
        }        
    }


    for (int x = 0; x < K; x++)
    {
        for (int y = 0; y < K; y++)
        {
            int tmp = 0;
            tmp += BS[K][K]-BS[x][K]-BS[K][y]+BS[x][y];
            tmp += BS[x][y]-BS[x][0]-BS[0][y]+BS[0][0];

            tmp += WS[K][y]-WS[K][0]-WS[x][y]+WS[x][0];
            tmp += WS[x][K]-WS[x][y]-WS[0][K]+WS[0][y];

            ans = max(ans,tmp);
            ans = max(ans,N-tmp);
        }
    }
    DBG(BS)
    DBG(WS)

    cout << ans << endl;    
    return 0;
}   

