        if(col[i]) white[ x[i]+1 ][ y[i]+1 ]++;
        else       black[ x[i]+1 ][ y[i]+1 ]++;
    }

    for(int i=0; i<MAXK; i++) {
        for(int j=0; j<MAXK; j++) {
            white[i][j+1] += white[i][j];
            black[i][j+1] += black[i][j];
        }
    }
    for(int j=0; j<MAXK; j++) {
        for(int i=0; i<MAXK; i++) {
            white[i+1][j] += white[i][j];
            black[i+1][j] += black[i][j];
        }
    }

    // 黒四角の左上を固定
    long long int ans = 0;
    for(int i=0; i<=K; i++) {
        for(int j=0; j<=K; j++) {
            long long int sum = 0;
            sum += getSum(black, 0  , 0  , i  , j  );
            sum += getSum(black, i+K, 0  , 2*K, j  );
            sum += getSum(black, i  , j  , i+K, j+K);
            sum += getSum(black, 0  , j+K, i  , 2*K);
            sum += getSum(black, i+K, j+K, 2*K, 2*K);

            sum += getSum(white, 0  , j  , i  , j+K);
            sum += getSum(white, i  , 0  , i+K, j  );
            sum += getSum(white, i+K, j  , 2*K, j+K);
            sum += getSum(white, i  , j+K, i+K, 2*K);

            ans = max({ans, sum, N - sum});
        }
    }
    cout << ans << endl;
    return 0;
}

