using namespace std;


int main() {
    int n, k, x, y;
    char c;
    vector<vector<int>> v(4100, vector<int>(4100, 0));
    scanf("%d %d", &n, &k);
    int dk = 2 * k;
    r(i, 0, n) {
        scanf("%d %d %c", &x, &y, &c);
        if (c == 'W') {
            c = 'B';
            x += k;
        }
        x %= dk;
        y %= dk;
        v[x+1   ][y+1   ]++;
        v[x+1+k ][y+1   ]--;
        v[x+1   ][y+1+k ]--;
        v[x+1+k ][y+1+k ]+=2;
        v[x+1+dk][y+1+k ]--;
        v[x+1+k ][y+1+dk]--;
        v[x+1+dk][y+1+dk]++;
    }

    r(i, 0, 4 * k) {
        r(j, 0, 4 * k) {
            if (i == 0 && j == 0) {
                continue;
            } else if (i == 0 && j != 0) {
                v[i][j] += v[i][j - 1] + 0 - 0;
            } else if (i != 0 && j == 0) {
                v[i][j] += 0 + v[i - 1][j] - 0;
            } else {
                v[i][j] += v[i][j - 1] + v[i - 1][j] - v[i - 1][j - 1];
            }
        }
    }

    r(i, 0, 4 * k) {
        r(j, 0, 4 * k) {
            if (i < dk && j < dk) {
                continue;
            } else if (dk <= i && j < dk) {
                v[i%dk][j] += v[i][j];
            } else if (i < dk && dk <= j) {
                v[i][j%dk] += v[i][j];
            } else {
                v[i%dk][j%dk] += v[i][j];
            }
        }
    }

    int max_count = 0;
    r(i, 0, 4 * k) {
        r(j, 0, 4 * k) {
            int val = v[i][j];
            if (max_count < val) {
                max_count = val;
            }
        }
    }

    printf("%d", max_count);

    return 0;
}

