template< class T >
struct CumulativeSum2D {
  vector< vector< T > > data;

  CumulativeSum2D(int W, int H) : data(W + 1, vector< int >(H + 1, 0)) {}

  void add(int x, int y, T z) {
    ++x, ++y;
    if(x >= data.size() || y >= data[0].size()) return;
    data[x][y] += z;
  }

  void build() {
    for(int i = 1; i < data.size(); i++) {
      for(int j = 1; j < data[i].size(); j++) {
        data[i][j] += data[i][j - 1] + data[i - 1][j] - data[i - 1][j - 1];
      }
    }
  }

  T query(int sx, int sy, int gx, int gy) {
    return (data[gx][gy] - data[sx][gy] - data[gx][sy] + data[sx][sy]);
  }
};

int main(){
    int N, K; cin >> N >> K;
    CumulativeSum2D<int> S0(4 * K, 4 * K), S1(4*K, 4*K);
    rep(i, 0, N){
        int x, y; cin >> x >> y;
        char c; cin >> c;
        x%=2 * K; y%=2*K;
        if(c == 'B') S0.add(x,y,1), S0.add(x + 2 * K, y, 1), S0.add(x, y + 2 * K, 1), S0.add(x + 2 * K, y + 2 * K, 1);
        else S1.add(x,y,1), S1.add(x + 2 * K, y, 1), S1.add(x, y + 2 * K, 1), S1.add(x + 2 * K, y + 2 * K, 1);
    }
    S0.build();
    S1.build();
    int ans = 0;

    rep(i, 0, 2 * K) rep(j, 0, 2 * K){
        ans = max(ans , S0.query(i, j, i + K, j + K) + S0.query(i + K, j + K, i + 2 * K, j + 2 * K) 
        + S1.query(i + K, j, i + 2 * K, j + K) + S1.query(i, j + K, i + K, j + 2 * K ) );
    }
    cout << ans << endl;

}

