struct CumulativeSum2D{
    vector<vector<int> > data;
    CumulativeSum2D(int H, int W) : data(H + 1, vector<int>(W + 1, 0)) {}
    //要素(x,y)に値zを加える
    void add(int x, int y, int z){
        ++x, ++y;
        if(x >= data.size() || y >= data[0].size()) return;
        data[x][y] += z;
    }
    void build(){
        for(int i = 1; i < data.size(); i++) {
        for(int j = 1; j < data[i].size(); j++) {
            data[i][j] += data[i][j - 1] + data[i - 1][j] - data[i - 1][j - 1];
            }
        }
    }
    //左上[sy, sx], 右下(gx, gy)の矩形内の和を求める(半開区間) (0-index)
    int query(int sx, int sy, int gx, int gy){
        return (data[gx][gy] - data[sx][gy] - data[gx][sy] + data[sx][sy]);
    }
};

signed main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n, k;
    cin >> n >> k;
    int h = 2 * k, w = 2 * k;
    int nb = 0, nw = 0;
    CumulativeSum2D csblack(h, w), cswhite(h, w);
    rep(i, 0, n){
        int y, x;
        char c;
        cin >> y >> x >> c;
        y %= h; x %= w;
        if(c == 'B'){
            csblack.add(y, x, 1);
            nb++;
        }
        if(c == 'W'){
            cswhite.add(y, x, 1);
            nw++;
        }
    }
    cswhite.build();
    csblack.build();
    int ans = 0;
    for(int i = 0; i <= k; i++){
        for(int j = 0; j <= k; j++){
            int numblack = csblack.query(0, 0, i, j) + csblack.query(i, j, i + k, j + k) + csblack.query(i + k, j + k, h, w) + csblack.query(0, j + k, i, w) + csblack.query(i + k, 0, h, j);
            int numwhite = cswhite.query(0, 0, i, j) + cswhite.query(i, j, i + k, j + k) + cswhite.query(i + k, j + k, h, w) + cswhite.query(0, j + k, i, w) + cswhite.query(i + k, 0, h, j);
            ans = max(ans, numblack + nw - numwhite);
            ans = max(ans, numwhite + nb - numblack);
            // cout << i << ' ' << j << ' ' << numblack << ' ' << numwhite << endl;
        }
    }
    cout << ans << endl;
}

