int N, K;
int b[4010][4010], w[4010][4010];

template <int n, int m>
inline int safeAt(int (&a)[n][m], int x, int y, int d){
    if(0 <= x && x < m && 0 <= y && y <= n){
        return a[y][x];
    }
    return d;
}

// (x, y)を右下に持つ1辺Kの正方形内の値の和
int sum(int (&a)[4010][4010], int y, int x){
    int x1 = x - 1, y1 = y - 1, x2 = x1 + K, y2 = y1 + K;

    return safeAt(a, x2, y2, 0) - safeAt(a, x1, y2, 0) - safeAt(a, x2, y1, 0) + safeAt(a, x1, y1, 0);
}

int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    std::cin >> N >> K;
    int L = 2 * K;

    for(int i=0;i<N;++i){
        int x, y;
        char c;
        std::cin >> x >> y >> c;

        x %= L;
        y %= L;

        if(c == 'W'){
            for(int j=0;j<2;++j){
                for(int k=0;k<2;++k){
                    ++w[y + L * j][x + L * k];
                }
            }
        }else{
            for(int j=0;j<2;++j){
                for(int k=0;k<2;++k){
                    ++b[y + L * j][x + L * k];
                }
            }
        }
    }

    for(int i=0;i<2*L;++i){
        for(int j=0;j+1<2*L;++j){
            w[i][j+1] += w[i][j];
            b[i][j+1] += b[i][j];
        }
    }

    for(int j=0;j<2*L;++j){
        for(int i=0;i+1<2*L;++i){
            w[i+1][j] += w[i][j];
            b[i+1][j] += b[i][j];
        }
    }

    int res = 0;
    for(int i=0;i<L;++i){
        for(int j=0;j<L;++j){
            int x = sum(b, i, j) + sum(b, i + K, j + K) + sum(w, i + K, j) + sum(w, i, j + K);
            // std::cout << i << ", " << j << ", " << x << std::endl;
            res = max(res, x);
        }
    }

    std::cout << res << std::endl;
}

