using namespace std;

int n, k;

#include <boost/numeric/ublas/matrix.hpp>
using boost::numeric::ublas::matrix;
template <typename T>
class CumulativeSum2D {
	public:
		matrix<T> sum;
		CumulativeSum2D (int h, int w) : sum(matrix<T>(h + 1, w + 1)) {}

		void add(int x, int y, int num) {
			x++;
			y++;
			sum(x, y) += num;
		}

		void build() {
			for (int i = 1; i < sum.size1(); i++) {
				for (int j = 1; j < sum.size2(); j++) {
					sum(i, j) += sum(i, j - 1) + sum(i - 1, j) - sum(i - 1, j - 1);
				}
			}
		}

		T query(int sx, int sy, int gx, int gy) {
			return (sum(gx, gy) - sum(sx, gy) - sum(gx, sy) + sum(sx, sy));
		}
};

int main() {
	cin >> n >> k;
	CumulativeSum2D<int> pear(4 * k, 4 * k);
	rep (i, n) {
		int x, y;
		char c;
		cin >> x >> y >> c;
		if (c == 'W') y += k;
		pear.add(x % (2 * k), y % (2 * k), 1);
	}
	range (i, 1, 2 * k + 1) range (j, 1, 2 * k + 1) {
		pear.sum(i, j + 2 * k) = pear.sum(i, j);
		pear.sum(i + 2 * k, j) = pear.sum(i, j);
		pear.sum(i + 2 * k, j + 2 * k) = pear.sum(i, j);
	}
	pear.build();
	int macs = 0;
	rep (i, 2 * k) rep (j, 2 * k) {
		int sum = 0;
		sum += pear.query(i, j, i + k, j + k);
		sum += pear.query(i + k, j + k, i + 2 * k, j + 2 * k);
		macs = max(macs, sum);
	}
	cout << macs << endl;
	return 0;
}

