int main(void)
{
	int n, K;
	int x, y;
	char c;
	int res = 0;
	int dx, dy, color;
	vector <vector<int>> v;

	cin.tie(0);
	ios::sync_with_stdio(false);
	cin >> n >> K;
	for (int i = 0; i < n; i++)
	{
		cin >> x >> y >> c;
		if (c == 'B')
		{
			v.push_back({ x,y,0 });
		}
		else
		{
			v.push_back({ x,y,1 });
		}
	}

	for (int i = 0; i < K; i++)
	{
		for (int j = 0; j < K; j++)
		{
			int count = 0;
			for (int k = 0; k < n; k++)
			{
				if (v[k][0] < v[0][0])
				{
					if (v[k][1] < v[0][1])
					{
						dx = v[0][0] - v[k][0];
						dy = v[0][1] - v[k][1];
						x = (K - 1) - i;
						y = (K - 1) - j;
					}
					else
					{
						dx = v[0][0] - v[k][0];
						dy = v[k][1] - v[0][1];
						x = (K - 1) - i;
						y = j;
					}
				}
				else
				{
					if (v[k][1] < v[0][1])
					{
						dx = v[k][0] - v[0][0];
						dy = v[0][1] - v[k][1];
						x = i;
						y = (K - 1) - j;
					}
					else
					{
						dx = v[k][0] - v[0][0];
						dy = v[k][1] - v[0][1];
						x = i;
						y = j;
					}
				}
				dx %= (2 * K);
				dy %= (2 * K);

				if (dx <= x || dx>x+K)
				{
					color = v[0][2];
				}
				else 
				{
					color = 1 - v[0][2];
				}

				if (dy <= y || dy> y + K)
				{
					color = color;
				}
				else
				{
					color = 1 - color;
				}

				if (color == v[k][2])
				{
					count++;
				}
			}
			res = max(res, count);
		}
	}

	cout << res << '\n';
	return 0;
}

