    int sum=0;
    REP(i,N){
        int x,y;
        char c;
        cin>>x>>y>>c;
        if((x/K+y/K)%2==1){
            if(c=='B') c='W';
            else c='B';
        }
        x%=K;y%=K;
        if(c=='B') B[x][y]++;
        else W[x][y]++;
    }
    int ans=0;
    vector<vector<int>> SB(K+1,vector<int>(K+1,0)),SW=SB;
    REP(i,K) REP(j,K){
        SB[i+1][j+1]=SB[i+1][j]+SB[i][j+1]-SB[i][j]+B[i][j];
        SW[i+1][j+1]=SW[i+1][j]+SW[i][j+1]-SW[i][j]+W[i][j];
    }
    REP(i,2*K+1) REP(j,2*K+1){
        int tmp;
        if(i-K<=0&&j-K<=0)tmp=SB[i][j]+SW[K][K]-SW[i][j];
        else if(i-K<=0) tmp=SB[i][K]-SB[i][j-K-1]+SW[K][K]-SW[i][K]+SW[i][j-K-1];
        else if(j-K<=0) tmp=SB[K][j]-SB[i-K-1][j]+SW[K][K]-SW[K][j]+SW[i-K-1][j];
