template <class T> struct CumulativeSum2D {
    vector<vector<T>> data;

    CumulativeSum2D(int W, int H) : data(W + 1, vector<int>(H + 1, 0)) {}

    void add(int x, int y, T z) {
        ++x, ++y;
        if (x >= data.size() || y >= data[0].size())
            return;
        data[x][y] += z;
    }

    void build() {
        for (int i = 1; i < data.size(); i++) {
            for (int j = 1; j < data[i].size(); j++) {
                data[i][j] +=
                    data[i][j - 1] + data[i - 1][j] - data[i - 1][j - 1];
            }
        }
    }

    T query(int sx, int sy, int gx, int gy) {
        return (data[gx][gy] - data[sx][gy] - data[gx][sy] + data[sx][sy]);
    }

    void print() {
        for (auto &x : data) {
            for (auto &y : x) {
                cout << y << " ";
            }
            cout << endl;
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int N, K;
    cin >> N >> K;
    CumulativeSum2D<int> sum(4 * K, 4 * K);
    REP(i, N) {
        int x, y;
        char c;
        cin >> x >> y >> c;
        if (c == 'B')
            y += K;
        x %= 2 * K;
        y %= 2 * K;
        sum.add(x, y, 1);
        sum.add(x, y + 2 * K, 1);
        sum.add(x + 2 * K, y, 1);
        sum.add(x + 2 * K, y + 2 * K, 1);
    }
    sum.build();
    int maxv = 0;
    REP(x, 2 * K) REP(y, 2 * K) {
        maxv = max(maxv, sum.query(x, y, x + K, y + K));
    }

    cout << maxv << endl;

    return 0;
}

