                cval[h][w + 1][c] = cval[h][w][c] + val[h][w][c];
            }
        }
    }
    for1 (w, K * 2 + 1) {
        for1 (h, K * 2) {
            for1 (c, 2) {
                imos[h + 1][w][c] = imos[h][w][c] + cval[h][w][c];
            }
