    auto calc = [&](ll y1, ll x1, ll y2, ll x2, ll c) {
        ll ret = 0;
        ret += imos[y2 + 1][x2 + 1][c];
        ret -= imos[y2 + 1][x1][c];
        ret -= imos[y1][x2 + 1][c];
        ret += imos[y1][x1][c];
        return ret;
    };
    // bwwb
    // wbbw
    // wbbw
    // bwwb
    for1 (h1, K) {
        for1 (w1, K) {
            ll h2 = h1 + K - 1;
            ll w2 = w1 + K - 1;
            for1 (c, 2) {
                ll ans1 = 0;
                ans1 = calc(0, 0, K2 - 1, K2 - 1, c);
                ans1 -= calc(h2 + 1, w2 + 1, K2 - 1, K2 - 1, c);
                ans1 -= calc(h2 + 1, 0, K2 - 1, w1 - 1, c);
                ans1 -= calc(0, w2 + 1, h1 - 1, K2 - 1, c);
                ans1 -= calc(0, 0, h1 - 1, w1 - 1, c);
                ans1 -= calc(h1, w1, h2, w2, c);
                ll ans2 = 0;
                ans1 += calc(h2 + 1, w2 + 1, K2 - 1, K2 - 1, 1 - c);
                ans1 += calc(h2 + 1, 0, K2 - 1, w1 - 1, 1 - c);
                ans1 += calc(0, w2 + 1, h1 - 1, K2 - 1, 1 - c);
                ans1 += calc(0, 0, h1 - 1, w1 - 1, 1 - c);
                ans1 += calc(h1, w1, h2, w2, 1 - c);
                chmax(ans, ans1 + ans2);
            }
        }
    }
    print(ans);
}
