            // printf("[step2] x=%lld, y=%lld, bcnt=%lld, wcnt=%lld\n", x, y, bcnt, wcnt);
            wcnt += wdp[x][k - y] - wdp[x][0] - wdp[0][k - y] + wdp[0][0];
            // printf("[step3] x=%lld, y=%lld, bcnt=%lld, wcnt=%lld\n", x, y, bcnt, wcnt);
            wcnt += wdp[k][k] - wdp[k][k - y] - wdp[x][k] + wdp[x][k - y];
            // printf("[step4] x=%lld, y=%lld, bcnt=%lld, wcnt=%lld\n", x, y, bcnt, wcnt);
            ans = max(ans, bcnt + wcnt);
            bcnt = 0, wcnt = 0;
            wcnt += wdp[x][k] - wdp[x][k - y] - wdp[0][k] + wdp[0][k - y];
            // printf("[step1] x=%lld, y=%lld, bcnt=%lld, wcnt=%lld\n", x, y, bcnt, wcnt);
            wcnt += wdp[k][k - y] - wdp[k][0] - wdp[x][k - y] + wdp[x][0];
            // printf("[step2] x=%lld, y=%lld, bcnt=%lld, wcnt=%lld\n", x, y, bcnt, wcnt);
            bcnt += bdp[x][k - y] - bdp[x][0] - bdp[0][k - y] + bdp[0][0];
            // printf("[step3] x=%lld, y=%lld, bcnt=%lld, wcnt=%lld\n", x, y, bcnt, wcnt);
            bcnt += bdp[k][k] - bdp[k][k - y] - bdp[x][k] + bdp[x][k - y];
            // printf("[step4] x=%lld, y=%lld, bcnt=%lld, wcnt=%lld\n", x, y, bcnt, wcnt);
            ans = max(ans, bcnt + wcnt);
        }
    }
    cout << ans << endl;
    return 0;
}

