int main(void){
    using namespace std;
    constexpr int KMAX = 1000;
    static int s[KMAX+1][2*KMAX+1];
    char c;
    int n, k, x, y;
    scanf("%d %d\n", &n, &k);
    for(int i=0; i<n; i++){
        gc(&x);
        gc(&y);
        c=getchar_unlocked();
        getchar_unlocked();
        y %= 2*k;
        if(c=='W'){
            if(y>=k){
                y-=k;
            }else{
                x+=k;
            }
        }else{
            if(y>=k){
                y-=k;
                x+=k;
            }
        }
        x %= 2*k;
        s[y+1][x+1]++;
    }
    for(int y=0; y<k; y++){
        for(int x=0; x<2*k; x++){
            s[y+1][x+1] += s[y][x+1] + s[y+1][x] - s[y][x];
        }
    }
    int max = 0;
    int v = s[0][0] - s[0][2*k];
    for(int y=0; y<k; y++){
        int u = v - s[y][0] + s[y][2*k];
        for(int x=0; x<k; x++){
            int t = u - s[0][x] - s[k][x] + s[0][x+k] + s[k][x+k] + 2*s[y][x] - 2*s[y][x+k];
            t = t<n/2 ? n-t : t;
            max = t>max ? t : max;
        }
    }
    printf("%d", max);
    return 0;
}

