int memo[2][1005][1005] = {0};
char c;
int x, y, bw, n, k;

int solve();

int main() {
  int i, j, l;
  cin >> n >> k;
  for(i = 0; i < n; ++i) {
    cin >> x >> y >> c;
    if(c == 'B')
      bw = 1;
    else
      bw = 0;
    ++memo[(x / k + y / k + bw) % 2][x % k][y % k];
  }
  for(l = 0; l < 2; ++l)
    for(i = 0; i < k; ++i)
      for(j = 0; j < k; ++j) {
        if(j != 0) memo[l][i][j] += memo[l][i][j - 1];
        if(i != 0) memo[l][i][j] += memo[l][i - 1][j];
        if(i != 0 && j != 0)
          memo[l][i][j] -= memo[l][i - 1][j - 1];
      }

  cout << solve() << endl;
  return 0;
}

int solve() {
  int ans = 0, now[2];
  for(int i = 0; i < k; ++i)
    for(int j = 0; j < k; ++j)
      for(int l = 0; l < 2; ++l) {
        now[l] = 0;
        now[l] += memo[l][i][j];
        if(i != k - 1 && j != k - 1) {
          now[l] += memo[l][k - 1][k - 1];
          now[l] -= memo[l][i][k - 1];
          now[l] -= memo[l][k - 1][j];
          now[l] += memo[l][i][j];
        }
        if(j != k - 1)
          now[l] +=
              memo[1 - l][k - 1][j] - memo[1 - l][i][j];
        if(i != k - 1)
          now[l] +=
              memo[1 - l][i][k - 1] - memo[1 - l][i][j];
        ans = max(ans, now[l]);
      }
  return ans;
}

