void imos2d(int a1, int b1, int a2, int b2) {
    ++imos[a1][b1];
    --imos[a1][b2];
    --imos[a2][b1];
    ++imos[a2][b2];
}

void writeimos(int lx, int ux, int ly, int uy) {
    if (lx > ux && ly > uy) {
        imos2d(lx, ly, 2 * K, 2 * K);
        imos2d(0, 0, ux, uy);
        imos2d(0, ly, ux, 2 * K);
        imos2d(lx, 0, 2 * K, uy);
    }
    else if (lx > ux) {
        imos2d(lx, ly, 2 * K, uy);
        imos2d(0, ly, ux, uy);
    }
    else if (ly > uy) {
        imos2d(lx, ly, ux, 2 * K);
        imos2d(lx, 0, ux, uy);
    }
    else {
        imos2d(lx, ly, ux, uy);
    }
}

