    scanf("%d%d", &n, &k);
    for (int i = 0; i < n; i++)
    {
        int x, y;
        char c;
        scanf("%d%d %c", &x, &y, &c);
        int y_rem = y % k, y_quo = y / k;
        int x_rem = (x + ((c == 'B') + y_quo % 2) * k) % (2 * k); 
        table[y_rem + 1][x_rem + 1]++;
        table[y_rem + k + 1][x_rem + k + 1]++;
        table[y_rem + 1][x_rem + 2 * k + 1]++;
        table[y_rem + k + 1][x_rem + 3 * k + 1]++;
    }
    for (int i = 1; i <= 2 * k; i++)
    {
        for (int j = 2; j <= 4 * k; j++)
        {
            table[i][j] += table[i][j - 1];
        }
    }
    for (int i = 1; i <= 4 * k; i++)
    {
        for (int j = 2; j <= 2 * k; j++)
        {
            table[j][i] += table[j - 1][i];
        }
    }
    for (int white_y = 0; white_y < k; white_y++)
    {
        for (int white_x = 0; white_x < k * 2; white_x++)
        {
            int tmp = table[white_y + k][white_x + k] + table[white_y][white_x]
                    - (table[white_y + k][white_x] + table[white_y][white_x + k]);
            if (tmp > max) max = tmp;
        }
    }

    printf("%d\n", max);
    return 0;
}

