using namespace std;

int n, k;
int posb[4001][4001] = {};

int calc(int i, int j){
  int a, b, c, d;
  if(i <= -1 * k || j <= -1 * k){
    a = 0;
    b = 0;
    c = 0;
    d = 0;
  }
  else{
    d = posb[i+k-1][j+k-1];
    if(i > 0 && j > 0){
      a = posb[i-1][j-1];
      b = posb[i-1][j+k-1];
      c = posb[i+k-1][j-1];
    }
    else{
      a = 0;
      if(i <= 0 && j <= 0){
        b = 0;
        c = 0;
      }
      else{
        if(j > 0){
          b = 0;
          c = posb[i+k-1][j-1];
        }
        else{
          b = posb[i-1][j+k-1];
          c = 0;
        }
      }
    }
  }
  return d + a - b - c;
}

int main(){
  cin >> n >> k;
  int x[100001];
