    if(c == 'B'){
      x[i] = a % (2 * k);
      y[i] = b  % (2 * k);
    }
    else{
      x[i] = (a) % (2 * k);
      y[i] = (b + k) % (2 * k);
    }
  }
  for(int i = 0 ; i < n ; i++){
    posb[x[i]][y[i]]++;
  }
  for(int i = 0 ; i < 4 * k ; i++){
    for(int j = 0 ; j < 4 * k - 1 ; j++){
      posb[j+1][i] += posb[j][i];
    }
  }

  for(int i = 0 ; i < 4 * k ; i++){
    for(int j = 0 ; j < 4 * k - 1 ; j++){
      posb[i][j+1] += posb[i][j];
    }
  }

  int ans = 0;
  for(int i = 0 ; i < 2*k ; i++){
    for(int j = 0 ; j < 2*k ; j++){
      int tmp = calc(i, j) + calc(i + k, j + k) + calc(i - k, j + k) + calc(i + k, j - k) + calc(i - k, j - k);
//      cout << tmp << endl;
      if(ans < tmp) ans = tmp;
    }
  }
  cout << ans << endl;
}

