// //(Y, X)
template <int H, int W> struct Sum2D {
    int sum[H][W];
    void set(int y, int x, int c) { sum[y][x] += c; }
    void build() {
        for (int y = 0; y < H; ++y) {
            for (int x = 0; x < W; ++x) {
                if (0 < y) sum[y][x] += sum[y-1][x];
                if (0 < x) sum[y][x] += sum[y][x-1];
                if (0 < y and 0 < x) sum[y][x] -= sum[y-1][x-1];
            }
        }
    }
    int get(int sy, int sx, int ty, int tx) {
        assert(sx <= tx and sy <= ty);
        int tmp = sum[ty][tx];
        if (0 < sx) tmp -= sum[ty][sx-1];
        if (0 < sy) tmp -= sum[sy-1][tx];
        if (0 < sx and 0 < sy) tmp += sum[sy-1][sx-1];
        return tmp;
    }
    int get(int length, int sy, int sx) {
        int tmp = sum[sy+length-1][sx+length-1];
        if (0 < sx) tmp -= sum[sy+length-1][sx-1];
        if (0 < sy) tmp -= sum[sy-1][sx+length-1];
        if (0 < sx and 0 < sy) tmp += sum[sy-1][sx-1];
        return tmp;
    }
    int get_rect(int h, int w, int sy, int sx) {
        int tmp = sum[sy+h-1][sx+w-1];
        if (0 < sx) tmp -= sum[sy+h-1][sx-1];
        if (0 < sy) tmp -= sum[sy-1][sx+w-1];
        if (0 < sx and 0 < sy) tmp += sum[sy-1][sx-1];
        return tmp;
    }
};

