inline long calc(const vector<long>& s, long M, long x, long y, long w, long h){
    return s[(x+w)+(y+h)*M] - s[(x+w)+y*M] - s[x+(y+h)*M] + s[x+y*M];
}

int main(void){
    long n, k;
    cin >> n >> k;
    vector<long> b(2*k*k, 0);
    for(long i=0; i<n; i++){
        long x, y;
        char c;
        cin >> x >> y >> c;
        y %= 2*k;
        if(c=='W'){
            x += k;
        }
        if(y>=k){
            y-=k;
            x+=k;
        }
        x %= 2*k;
        b[x+y*2*k]++;
    }
    /*
    for(long y=0; y<2*k; y++){
        for(long x=0; x<2*k; x++){
            cout << b[x+y*2*k] << " ";
        }
        cout << endl;
    }
    cout << endl;
    */
    const long M = 2*k+1;
    vector<long> s((k+1)*M, 0);
    s[1+1*M] = b[0];
    for(long i=1; i<2*k; i++){
        s[(i+1)+1*M] = s[(i-1+1)+1*M] + b[i];
    }
    for(long i=1; i<k; i++){
        s[1+(i+1)*M] = s[1+(i-1+1)*M] + b[2*k*i];
    }
    for(long x=1; x<2*k; x++){
        for(long y=1; y<k; y++){
            s[x+1+(y+1)*M] = b[x+y*2*k] + s[(x-1+1)+(y+1)*M] + s[x+1+(y-1+1)*M] - s[(x-1+1)+(y-1+1)*M];
        }
    }
    /*
    for(long y=1; y<M; y++){
        for(long x=1; x<M; x++){
            cout << s[x+y*M] << " ";
        }
        cout << endl;
    }
    cout << endl;
    */
    long max = 0;
    for(long x=0; x<k; x++){
        for(long y=0; y<k; y++){
            long t = calc(s, M, x, y, k, k-y);
            t += calc(s, M, 0, 0, x, y);
            t += calc(s, M, x+k, 0, k-x, y);
            t = t<n/2 ? n-t : t;
            //printf("%ld %ld %ld\n", x, y, t);
            max = t>max ? t : max;
        }
