    for (int i = 0; i < n; ++i) {
        int x, y;
        char c;
        cin >> x >> y >> c;
        if (c == 'B')
            ++black[y % (2 * k)][x % (2 * k)];
        else
            ++all_req_white, ++white[y % (2 * k)][x % (2 * k)];
    }

    for (int i = 0; i < 2 * k; ++i) {
        for (int j = 1; j < 2 * k; ++j) {
            black[i][j] += black[i][j - 1];
            white[i][j] += white[i][j - 1];
        }
    }
    for (int j = 0; j < 2 * k; ++j) {
        for (int i = 1; i < 2 * k; ++i) {
            black[i][j] += black[i - 1][j];
            white[i][j] += white[i - 1][j];
        }
    }

    int ans = 0;
    for (int i = 0; i < 2 * k; ++i) {
        for (int j = 0; j < 2 * k; ++j) {
            int req_black = request_num(black, i, j);
