/*二次元累積和
    add(x,y,z)=(x,y)に値zを加える
    build()=累積和を構築する
    query(sx,sy,gx,gy)=左下が(sx,sy),右上が(gx,gy)の矩形和を求める
    (半開区間であり列gxと行gyは含まないこと)
*/

template<typename T>
struct  CumulativeSum2D{
    vector<vector< T > >data;

    CumulativeSum2D(int w,int h):data(w+1,vector< T >(h+1,0)){}

    void add(int x,int y,T z){
        ++x;++y;
        if(x >= data.size() || y >= data[0].size())return;
        data[x][y] += z;
    }

    void build(){
        for(int i=1;i<data.size();i++){
            for(int j=1;j<data[i].size();j++){
                data[i][j] += data[i][j-1] + data[i-1][j] - data[i-1][j-1];
            }
        }
    }

    T query(int sx, int sy, int gx, int gy){
        return data[gx][gy]-data[sx][gy]-data[gx][sy]+data[sx][sy];
    }
};

int main(){
    ll n,k;
    cin >> n >> k;
    ll k2 = k*2;
    CumulativeSum2D<ll>black(k2,k2),white(k2,k2);
    rep(i,n){
        ll x,y;
        char c;
        cin >> x >> y >> c;
        if(c=='B'){
            black.add(x%k2,y%k2,1);
        }
        else{
            white.add(x%k2,y%k2,1);
        }
    }
    black.build();
    white.build();
    ll ans = 0;
    rep(i,k){
        rep(j,k){
            //Case1
            ll now = 0;
            //left
            now += black.query(0,0,i,j);
            now += white.query(i,0,i+k,j);
            now += black.query(i+k,0,k2,j);
            //middle
            now += white.query(0,j,i,j+k);
            now += black.query(i,j,i+k,j+k);
            now += white.query(i+k,j,k2,j+k);
            //right
            now += black.query(0,j+k,i,k2);
            now += white.query(i,j+k,i+k,k2);
            now += black.query(i+k,j+k,k2,k2);
            chmax(ans,now);

            //Case2
            now = 0;
            //left
            now += white.query(0,0,i,j);
            now += black.query(i,0,i+k,j);
            now += white.query(i+k,0,k2,j);
            //middle
            now += black.query(0,j,i,j+k);
            now += white.query(i,j,i+k,j+k);
            now += black.query(i+k,j,k2,j+k);
            //right
            now += white.query(0,j+k,i,k2);
            now += black.query(i,j+k,i+k,k2);
            now += white.query(i+k,j+k,k2,k2);
            chmax(ans,now);
        }
    }
    cout << ans << endl;

    return 0;
}

