	{
		for (int j = 0; j < K; ++j)
		{
			blackPointTable[i][j] = 0;
			blackPointSumTable[i][j] = 0;
			whitePointTable[i][j] = 0;
			whitePointSumTable[i][j] = 0;
		}
	}

	for (int i = 0; i < N; ++i)
	{
		char c;
