		if ((((x / K) + (y / K)) % 2 == 0) == (c == 'B'))
		{
			++blackPointTable[x % K][y % K];
		}
		else
		{
			++whitePointTable[x % K][y % K];
		}
	}

	blackPointSumTable[0][0] = blackPointTable[0][0];
	whitePointSumTable[0][0] = whitePointTable[0][0];
	for (int i = 1; i < K; ++i)
	{
		blackPointSumTable[0][i] = blackPointSumTable[0][i - 1] + blackPointTable[0][i];
		blackPointSumTable[i][0] = blackPointSumTable[i - 1][0] + blackPointTable[i][0];
		whitePointSumTable[0][i] = whitePointSumTable[0][i - 1] + whitePointTable[0][i];
		whitePointSumTable[i][0] = whitePointSumTable[i - 1][0] + whitePointTable[i][0];
	}

	for (int x = 1; x < K; ++x)
	{
		for (int y = 1; y < K; ++y)
		{
			blackPointSumTable[x][y] = 
			 blackPointSumTable[x - 1][y]
			 + blackPointSumTable[x][y - 1]
			 - blackPointSumTable[x - 1][y - 1]
			 + blackPointTable[x][y];
			whitePointSumTable[x][y] = 
			 whitePointSumTable[x - 1][y]
			 + whitePointSumTable[x][y - 1]
			 - whitePointSumTable[x - 1][y - 1]
			 + whitePointTable[x][y];
		}
	}

	int maxPoint = 0;
	for (int x = 0; x < K; ++x)
	{
		for (int y = 0; y < K; ++y)
		{
			int point = (whitePointSumTable[K - 1][K - 1] - whitePointSumTable[x][y]) 
			+ blackPointSumTable[x][y];
			if (point < N - point)
			{
				point = N - point;
			}
			if (point > maxPoint)
			{
				maxPoint = point;
			}
		}
	}
	cout << maxPoint << endl;

	return 0;
}

