template<typename T>
void fin(T const& t){ std::cout << t << std::endl; exit(0); }

template<typename T>
std::vector<std::vector<T>> mk2d(size_t s1, size_t s2, T const& val) {
  std::vector<T> tmp(s2, val);
  return std::vector<std::vector<T>>(s1, tmp);
}

int main() {
  std::cin.tie(0); std::ios::sync_with_stdio(false);
  int N, K; std::cin >> N >> K;
  auto reduce = [&](int x, int y) {
    x %= K+K; y %= K+K;
    if(y >= K) {
      y -= K;
      (x += K) %= K+K;
    }
    return std::make_pair(x, y);
  };
  auto w = mk2d<int>(K+K+1, K+1, 0);
  auto b = mk2d<int>(K+K+1, K+1, 0);
  for(int i = 0; i < N; ++i) {
    int x, y; char c; std::cin >> x >> y >> c;
    auto p = reduce(x, y);
    if(c == 'B') ++b[p.first+1][p.second+1];
    else         ++w[p.first+1][p.second+1];
  }
  // sumup
  for(int x = 1; x <= K+K; ++x) for(int y = 0; y < K; ++y) {
    w[x][y+1] += w[x][y];
    b[x][y+1] += b[x][y];
  }
  for(int y = 1; y <= K; ++y) for(int x = 0; x < K+K; ++x) {
    w[x+1][y] += w[x][y];
    b[x+1][y] += b[x][y];
  }

  int ans = 0;
  for(int x = 0; x < K; ++x) for(int y = 0; y < K; ++y) {
    // [0,x)x[0,y) + [x,x+K)x[y,K) + [x+K,K+K)x[0,y)
    int b1 = b[x+K][K] + b[K+K][y] - b[x][K] - 2*b[x+K][y] + 2*b[x][y];
    int b2 = b[K+K][K] - b1;
    int w1 = w[x+K][K] + w[K+K][y] - w[x][K] - 2*w[x+K][y] + 2*w[x][y];
    int w2 = w[K+K][K] - w1;
    ans = std::max(ans, std::max(b1+w2, b2+w1));
  }
  fin(ans);
  return 0;
}

