int main(void) {
  ll i, j, k, n, x, y, ans = 0;
  char c;
  scanf("%lld%lld", &n, &k);
  ll w[k][k], b[k][k];
  for(i = 0; i < k; ++i) for(j = 0; j < k; ++j) w[i][j] = 0, b[i][j] = 0;
  for(i = 0; i < n; i++) {
    bool s = false;
    scanf("%lld %lld %c", &x, &y, &c);
    if(c == 'B') s = true;
    x %= 2 * k;
    y %= 2 * k;
    if(x >= k) s = !s, x -= k;
    if(y >= k) s = !s, y -= k;
    if(s) b[y][x]++;
    else w[y][x]++;
  }
  for(i = 0; i < k; ++i) {
    for(j = 0; j < k; ++j) {
      if(i) b[i][j] += b[i - 1][j], w[i][j] += w[i - 1][j];
      if(j) b[i][j] += b[i][j - 1], w[i][j] += w[i][j - 1];
      if(i && j) b[i][j] -= b[i - 1][j - 1], w[i][j] -= w[i - 1][j - 1];
    }
  }
  for(i = 0; i <= k; ++i) {
    for(j = 0; j <= k; ++j) {
      int num = 0;
      if(i && j) {
        num = 2 * b[i - 1][j - 1] + w[k - 1][j - 1] + w[i - 1][k - 1] - 2 * w[i - 1][j - 1] + b[k - 1][k - 1] - b[i - 1][k - 1] - b[k - 1][j - 1];
      } else if(i) {
        num = w[i - 1][k - 1] + b[k - 1][k - 1] - b[i - 1][k - 1];
      } else if(j) {
        num = w[k - 1][j - 1] + b[k - 1][k - 1] - b[k - 1][j - 1];
      } else {
        num = w[k - 1][k - 1];
      }
      if(num > ans) ans = num;
    }
  }
  printf("%lld", ans);
  return 0;
}

