// 市松模様は[0,2k)*[0,2k)のどこを黒い部分の左下にするかという情報で一意に定まる（全単射）ので、そのように表す
// imos[i][j] := (i,j)が黒い部分の左下になるような市松模様を塗った時に叶えられる希望の数
vector<vector<int>> imos(4020, vector<int>(4020, 0));

// (x,y)∈[x-k+1, x]*[y-k+1, y]の範囲でimos[i][j]+=1と累積されるように値をセットする
void set_square(int x, int y){
    if(x<0 || y<0) return;
    imos[ max(0, x-k+1) ][ max(0, y-k+1) ] += 1;
    imos[ max(0, x-k+1) ][y+1] -= 1;
    imos[x+1][ max(0, y-k+1) ] -= 1;
    imos[x+1][y+1] += 1;
}

void set_imos(int x, int y, int k, vector<vector<int>> &imos){
    set_square(x, y);
    set_square(x+k, y-k);
    set_square(x-k, y-k);
    set_square(x+k, y+k);
    set_square(x-k, y+k);
    set_square(x, y+2*k);
}

