class CumulativeSum {

public:
    vector<vector<int>> memo;

    // boardの累積和を作成
    CumulativeSum(const vector<vector<int>> &board) {
        int height = board.size();
        int width = board[0].size();
        this->memo = vector<vector<int>>(height + 1, vector<int>(width + 1, 0));

        for (int y = 0; y < height; ++y) {
            for (int x = 0; x < width; ++x) {
                memo[y + 1][x + 1] = board[y][x] + memo[y + 1][x];
            }
            for (int x = 0; x < width; ++x) {
                memo[y + 1][x + 1] += memo[y][x + 1];
            }
        }
    }

    /*
    (y1, x1)から(y2, x2)の合計を返す．(y2, x2)は含まない
    座標はmemoを作成したboard準拠
    (ex, sum(0, 0, 2, 2)なら(0, 0), (0, 1), (1, 0), (1, 1)の合計を返す)
    */
    int sum(int y1, int x1, int y2, int x2) {
        return this->memo[y2][x2] - this->memo[y2][x1] - this->memo[y1][x2] + this->memo[y1][x1];
    }

};

void solve(long long N, long long K, vector<long long> &X, vector<long long> &Y, vector<char> &C){
    vector<vector<int>> black(2 * K, vector<int>(2 * K, 0));
    FOR(i, 0, N) {
        LL x = X[i];
        LL y = Y[i];
        char c = C[i];

        if (c == 'W') {
            y += K;
        }
        int a = y % (2 * K);
        int b = x % (2 * K);
        black[a][b] += 1;

    }

    CumulativeSum cl(black);

    LL ans = 0;
    FOR(y, 0, 2 * K) {
        FOR(x, 0, 2 * K) {
            int y1 = min<int>(y + K, 2 * K);
            int x1 = min<int>(x + K, 2 * K);
            LL a = cl.sum(0, 0, y, x);
            LL b = cl.sum(y, x, y1, x1);
            LL c = cl.sum(y1, 0, 2 * K, x);
            LL d = cl.sum(0, x1, y, 2 * K);
            LL e = cl.sum(y1, x1, 2 * K, 2 * K);

            ans = max(ans, a + b + c + d + e);
        }
    }


    print(ans);

}

