int Square(int xl,int xr,int yd,int yu,bool B)
{
	int ret=0;
	int a,b,c;
	if(B==true)
	{
		if(yu>0)
		{
			a = black[xr][yu-1];
		}else{
			a=0;
		}
		if(xl>0)
		{
			b=black[xl-1][yd];
		}else{
			b=0;
		}
		if(yu>0&&xl>0)
		{
			c=black[xl-1][yu-1];
		}else{
			c=0;
		}
		ret = black[xr][yd]-a-b+c;
	}else{
		if(yu>0)
		{
			a = white[xr][yu-1];
		}else{
			a=0;
		}
		if(xl>0)
		{
			b=white[xl-1][yd];
		}else{
			b=0;
		}
		if(yu>0&&xl>0)
		{
			c=white[xl-1][yu-1];
		}else{
			c=0;
		}
		ret = white[xr][yd]-a-b+c;
	}
	return ret;
}

int main()
{
	int n,k;
	int M=0;
	int cnt=0;
	int xl,xr,yd,yu;

	cin>>n>>k;
	for(int i=0;i<2001;i++)
	{
		for(int j=0;j<2001;j++)
