		x[i]%=(2*k);
		y[i]%=(2*k);
		if(c[i]=='B')
		{
			black[x[i]][y[i]]++;
		}else if(c[i]=='W'){
			white[x[i]][y[i]]++;
		}
	}
	//x方向の累積和
	for(int i=0;i<2*k;i++)
	{
		for(int j=1;j<2*k;j++)
		{
			black[j][i]=black[j][i]+black[j-1][i];
			white[j][i]=white[j][i]+white[j-1][i];
		}
	}
	//y方向の累積和
	for(int j=0;j<2*k;j++)
	{
		for(int i=1;i<2*k;i++)
		{
			black[j][i]=black[j][i]+black[j][i-1];
			white[j][i]=white[j][i]+white[j][i-1];
		}
	}
	//累積和チェック
	/*
	for(int j=0;j<2*k;j++)
	{
		for(int i=0;i<2*k;i++)
		{
			cerr<<black[i][j]<<" ";
		}
		cerr<<endl;
	}*/
	//x
	for(xl=0;xl<k;xl++)
	{
		//y
		for(yd=0;yd<k;yd++)
		{
			cnt=0;
			//初期位置白
			//白の数え上げ
			cnt += Square(xl,xl+k-1,yd+k-1,yd,false)+Square(xl+k,2*k-1,2*k-1,yd+k,false);
			if(xl>0)
			{
				cnt += Square(0,xl-1,2*k-1,yd+k,false);
			}
			if(yd>0)
			{
				cnt += Square(xl+k,2*k-1,yd-1,0,false);
			}
			if(xl>0&&yd>0)
			{
				cnt += Square(0,xl-1,yd-1,0,false);
			}
			//黒の数え上げ
			cnt += Square(xl+k,2*k-1,yd+k-1,yd,true)+Square(xl,xl+k-1,2*k-1,yd+k,true);
			if(xl>0)
			{
				cnt += Square(0,xl-1,yd+k-1,yd,true);
			}
			if(yd>0)
			{
				cnt += Square(xl,xl+k-1,yd-1,0,true);
			}
			//cerr<<"("<<xl<<","<<yd<<") ... "<<cnt<<endl;
			if(M<cnt)
			{
				M=cnt;
			}
			//初期位置黒
			cnt = n-cnt;
			if(M<cnt)
			{
				M=cnt;
			}
		}
	}
	cout<<M<<endl;
	return 0;
}

