vvll ruiseki(vvll v, ll h, ll w) {
	vvll res(h + 1, vll(w + 1, 0));
	rep(i, h) {
		rep(j, w) { res[i + 1][j + 1] = v[i][j]; }
	}
	rep(i, h + 1) {
		rep(j, w) { res[i][j + 1] += res[i][j]; }
	}
	rep(i, h) {
		rep(j, w + 1) { res[i + 1][j] += res[i][j]; }
	}
	return res;
}

