Int cumulative[2'010][2'010];

/* Return number of poInts in
 * [(lx,ly)..(hx..hy))
 * lx/ly: low x/y
 * hx/hy: high x/y
 */
Int query(Int lx, Int ly, Int hx, Int hy) {
	if(lx > hx || ly > hy) return 0;
	return cumulative[hx][hy]
			- cumulative[lx][hy]
			- cumulative[hx][ly]
			+ cumulative[lx][ly];
}

int main() {
	// Input
	Int N;
	Int K;
	cin >> N >> K;
	const Int k2 = 2 * K;
	// ... and Preparation
	for(Int i = 0; i < N; ++i) {
		Int x, y;
		char c;
		cin >> x >> y >> c;
		if(c == 'B') x += K;
		x %= k2;
		y %= k2;
		++plane[x][y];
	}
	// Preparation
	for(Int x = 1; x <= k2; ++x) {
	for(Int y = 1; y <= k2; ++y) {
		cumulative[x][y] = cumulative[x-1][y]
							+ cumulative[x][y-1]
							- cumulative[x-1][y-1]
							+ plane[x-1][y-1];
	}
	}
	// Calculation
	Int ans = 0;
	for(Int x = 0; x < K; ++x) {
	for(Int y = 0; y < K; ++y) {
		Int w = query(x, y, x+K+1, y+K+1);
		ans = max(ans, w);
	}
	}
	// Output
	cout << ans << endl;
	return 0;
}

