int Sum(int x1,int x2,int y1,int y2,int t) {
	return a[x2][y2][t] - a[x1-1][y2][t] - a[x2][y1-1][t] + a[x1-1][y1-1][t];
}
int main() {
	int N, K, Max = 0, cnt = 0;
	scanf("%d%d",&N,&K);
	for(int i=1;i<=N;i++) {
		int x, y;char ch;
		scanf("%d%d %c",&x,&y,&ch);
		x = x % (2*K) + 1;y = y % (2*K) + 1;
		if( ch == 'W' ) a[x][y][0]++;
		else a[x][y][1]++;
	}
	for(int i=1;i<=2*K;i++) {
		for(int j=1;j<=2*K;j++) {
			a[i][j][0] += a[i][j-1][0] + a[i-1][j][0] - a[i-1][j-1][0];
			a[i][j][1] += a[i][j-1][1] + a[i-1][j][1] - a[i-1][j-1][1];
		}
	}
	for(int i=1;i<=K+1;i++) {
		for(int j=1;j<=K+1;j++) {
			int ii = i+K-1, jj = j+K-1;
			int cntb = 0, cntw = 0;
			if( i != 1 ) {
				if( j != 1 )
					cntb += Sum(1,i-1,1,j-1,1);
				cntw += Sum(1,i-1,j,jj,0);
				if( j != K+1 )
					cntb += Sum(1,i-1,jj+1,2*K,1);
			}
			if( j != 1 )
				cntw += Sum(i,ii,1,j-1,0);
			cntb += Sum(i,ii,j,jj,1);
			if( j != K+1 )
				cntw += Sum(i,ii,jj+1,2*K,0);
			if( i != K+1 ) {
				if( j != 1 )
					cntb += Sum(ii+1,2*K,1,j-1,1);
				cntw += Sum(ii+1,2*K,j,jj,0);
				if( j != K+1 )
					cntb += Sum(ii+1,2*K,jj+1,2*K,1);
			}
			if( cntw + cntb > Max ) Max = cntw + cntb;
			if( N - cntw - cntb > Max ) Max = N - cntw - cntb;
		}
	}
	printf("%d\n",Max);
}

