using namespace std;


int main() {
	int N, K;

	cin >> N >> K;
	vector<vector<int>> map(3 * K, vector<int>(3 * K, 0));
	vector<vector<int>> sum(3 * K, vector<int>(3 * K, 0));

	for (int i = 0; i < N; i++)
	{
		int x, y;
		char c;
		cin >> x >> y >> c;
		if (c == 'B') {
			y += K;
		}
		map[y % (2 * K)][x % (2 * K)]++;
		y += K; x += K;
		map[y % (2 * K)][x % (2 * K)]++;

	}

	//2K*2Kの盤面を3K*3Kに拡張
	for (int i = 0; i < 3 * K; i++) {
		for (int j = 0; j < 3 * K; j++)
		{
			map[i][j] = map[i % (2 * K)][j % (2 * K)];
		}
	}


	//累積和計算
	for (int i = 0; i < 3 * K; i++) {
		for (int j = 0; j < 3 * K; j++) {
			sum[i][j] = map[i][j];
			if (i - 1 >= 0) sum[i][j] += sum[i - 1][j];
			if (j - 1 >= 0) sum[i][j] += sum[i][j - 1];
			if (i - 1 >= 0 && j - 1 >= 0) sum[i][j] -= sum[i - 1][j - 1];
		}
	}

	int ans = 0;

	//白端点指定
	for (int i = 0; i < 2 * K; i++)
	{
		int tmp;
		for (int j = 0; j < 2 * K; j++)
		{
			tmp = sum[i + K - 1][j + K - 1];
			if (i - 1 >= 0) tmp -= sum[i - 1][j + K - 1];
			if (j - 1 >= 0) tmp -= sum[i + K - 1][j - 1];
			if (i - 1 >= 0 && j - 1 >= 0) tmp += sum[i - 1][j - 1];
			ans = max(tmp, ans);
		}
	}

	cout << ans << endl;

	return 0;
}

