    vector<vector<int>> acc(2 * k + 1, vector<int>(2 * k + 1, 0));
    forin(i, 0, 2 * k) forin(j, 0, 2 * k) {
        acc[i][j] = acc[i][j + 1] + acc[i + 1][j] - acc[i][j] + bb[i][j];
