#define BLACK 'B'
#define WHITE 'W'

// x : [left, right)
// y : [top, bottom)
int calc(int left, int top, int right, int bottom, const vector<vector<int>>& table)
{
	int a = table[top][left];
	int b = table[top][right];
	int c = table[bottom][left];
	int d = table[bottom][right];

	return d - c - b + a;
}

int main(void)
{
	int N, K;
	cin >> N >> K;

	const int k2 = 2 * K;
	const int size = 4*K + 10;
	vector<vector<int>> table(size, vector<int>(size, 0));
	for(int i=0; i<N; i++){
		int x, y;
		char c;
		cin >> x >> y >> c;
		if(c == WHITE)
			x += K;

		x %= k2;
		y %= k2;

		table[y][x]++;
		table[y][x+2*K]++;
		table[y+2*K][x]++;
		table[y+2*K][x+2*K]++;
	}

	vector<vector<int>> imos(size, vector<int>(size, 0));
	for(int i=0; i<size-1; i++){
		for(int j=0; j<size-1; j++){
			imos[i+1][j+1] += table[i][j] + imos[i+1][j];
		}
	}
	for(int i=0; i<size-1; i++){
		for(int j=0; j<size; j++){
			imos[i+1][j] += imos[i][j];
		}
	}

	int ret = 0;
	for(int i=0; i<2*K; i++){
		for(int j=0; j<2*K; j++){
			int sum = 0;

			sum += calc(j, i, j+K, i+K, imos);
			sum += calc(j+K, i+K, j+k2, i+k2, imos);

			ret = max(ret, sum);
		}
	}

	cout << ret << endl;

	return 0;
}

