Int INF = 1LL << 60;
const Int MOD = 1000000000 + 7;

int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	Int N, K;
	cin >> N >> K;

	vector<vector<Int>> G(4*K, vector<Int>(4*K));//0～2K-1までのグリッド
	Int x, y;
	char c;
	for (Int i = 0; i < N; i++) {
		cin >> x >> y >> c;
		if (c=='W') {
			y += K;
		}
		x %= 2 * K;
		y %= 2 * K;
		G[x][y]++;

		//チェッカーにおける五カ所の累積和を求める代わりに以下の点もインクリメント
		//左上、左下、右下の点を全て右上に移動

		//http://tsutaj.hatenablog.com/entry/2018/03/09/225829   ←←五カ所の累積和を求めてもいいけど、場合分けがしんどそう
		G[x + 2 * K][y]++;
		G[x][y + 2 * K]++;
		G[x+2*K][y + 2 * K]++;
	}

	//二次元累積和
	vector<vector<Int>> S(4*K+1, vector<Int>(4*K+1));
	for (Int i = 0; i < 4*K; i++) {
		for (Int j = 0; j < 4*K; j++) {
			S[i + 1][j + 1] = S[i][j + 1] + S[i + 1][j] - S[i][j] + G[i][j];
		}
	}

	Int ans = -INF;
	Int temp;
	for (Int i = 0; i <= 2*K; i++) {//正方形の左下の座標
		for (Int j = 0; j <= 2*K; j++) {
			temp = S[i + K][j + K] - S[i][j + K] - S[i + K][j] + S[i][j];
			temp += S[i + 2 * K][j + 2 * K] - S[i + K][j + 2 * K] - S[i + 2 * K][j + K] + S[i + K][j + K];
			ans = max(ans, temp);
		}
	}

	cout << ans << "\n";

}

