int query(int x1, int y1, int x2, int y2) {
  return dp[y2][x2] - dp[y1][x2] - dp[y2][x1] + dp[y1][x1];
}
int main() {
  int N,K,answer=0,x,y;
  char c;
  cin >> N >> K;
  for (int i = 0; i < N; dp[y+1][x+1]++, i++) {
    cin >> x >> y >> c;
    if (c == 'B') {
      y += K;
    }
    x %= 2*K;
    y %= 2*K;
  }
  for (int i = 0; i <= 2*K; i++) {
    for (int j = 0; j < 2*K; j++) {
      dp[i][j+1] += dp[i][j];
    }
  }
  for (int j = 0; j <= 2*K; j++) {
    for (int i = 0; i < 2*K; i++) {
      dp[i+1][j] += dp[i][j];
    }
  }
  for (int i = 0; i <= K; i++) {
    for (int j = 0, k = 0; j <= K; j++, k = 0) {
      k += query(0, 0, i, j);
	  k += query(i + K, 0, 2 * K, j);
	  k += query(0, j + K, i, 2 * K);
	  k += query(i, j, i + K, j + K);
	  k += query(i + K, j + K, 2 * K, 2 * K);
      answer = max(answer,max(k,N-k));
    }
  }
  cout << answer;
}

