using namespace std;
using ll = long long;

const char Black = 'B';
const char White = 'W';

int n, k;

struct stus {
    ll x, y;
    char c;
    void cast() {
        x %= 2 * k;
        if (c == White) y += k;
        c = Black;
        y %= 2 * k;
    }
};

int acc[2001][2001];

int sumb(int dx, int dy, int dtx, int dty) {
    return acc[dx][dy] + acc[dtx][dty] - acc[dx][dty] - acc[dtx][dy];
}

int main() {
    cin >> n >> k;
    stus s[n];
    forin(i, 0, n) {
        auto &st = s[i];
        cin >> st.x >> st.y >> st.c;
        st.cast();
    }
    vector<vector<int>> bb(2 * k, vector<int>(2 * k, 0));
    for (auto &st : s) {
        bb[st.x][st.y]++;
    }
    forin(i, 0, 2 * k) forin(j, 0, 2 * k) {
        acc[i + 1][j + 1] = acc[i][j + 1] + acc[i + 1][j] - acc[i][j] + bb[i][j];
    }
    auto maxDreams = 0;
    forin(dx, 0, 2 * k) {
        forin(dy, 0, k) {
            auto dtx = (dx + k) % k, dty = (dy + k) % k;
            auto numb = sumb(dx, dy, dtx, dty);
            numb += sumb(0, 0, dx, dy);
            numb += sumb(0, dty, dx, 2 * k);
            numb += sumb(dtx, 0, 2 * k, dy);
            numb += sumb(dtx, dty, 2 * k, 2 * k);
            maxDreams = max(numb, maxDreams);
        }
    }
    cout << maxDreams << endl;
}

