typedef long long lint;

const int MAXN = 110000;
const int MAXK = 2100;
int X[MAXN], Y[MAXN];
char C[MAXN];
int N, k, K;
int whiteBoard[MAXK][MAXK];
int blackBoard[MAXK][MAXK];

int main() {
    cin >> N >> k;
    K = 2*k;
    for (int i = 0; i < N; i++) {
        cin >> X[i] >> Y[i] >> C[i];
        const int y = Y[i] % K, x = X[i] % K;
        blackBoard[y][x] += (C[i] == 'B' ? 1 : 0);
        whiteBoard[y][x] += (C[i] == 'W' ? 1 : 0);
    }
    vector<int> whiteSumColumn(K), blackSumColumn(K);
    for (int x = 0; x < K; x++) {
        for (int y = 0; y < K; y++) {
            whiteSumColumn[x] += whiteBoard[y][x];
            blackSumColumn[x] += blackBoard[y][x];
        }
    }
    vector<int> whiteUpper = whiteSumColumn, whiteBottom(K), blackUpper = blackSumColumn, blackBottom(K);
    int ans = 0;
    for (int y = 0; y < K; y++) {
        // 初期解
        int tmp = 0;
        for (int x = 0; x < k; x++) {
            tmp += whiteUpper[x] + blackBottom[x];
        }
        // x 軸方向に動かして答えを求める
        for (int x = 0; x < K; x++) {
            ans = max(ans, tmp);
            // 更新
            tmp -= whiteUpper[K-x-1] + blackBottom[K-x-1];
            tmp += blackUpper[K-x-1] + whiteBottom[K-x-1];
        }
        ans = max(ans, tmp);
        // y 軸方向に動かして whiteUpper とかを更新
        // K-y-1 行目を upper から消して K-y-1 行目を bottom に追加
        for (int x = 0; x < K; x++) {
            whiteUpper[x] -= whiteBoard[K-y-1][x];
            blackUpper[x] -= blackBoard[K-y-1][x];
            whiteBottom[x] += whiteBoard[K-y-1][x];
            blackBottom[x] += whiteBoard[K-y-1][x];
        }
    }
    cout << ans << endl;
}

