    else
      bw = 0;
    ++memo[(x / k + y / k + bw) % 2][x % k][y % k];
  }
  for(l = 0; l < 2; ++l)
    for(i = 0; i < k; ++i)
      for(j = 0; j < k; ++j) {
        if(j != 0) memo[l][i][j] += memo[l][i][j - 1];
        if(i != 0) memo[l][i][j] += memo[l][i - 1][j];
        if(i != 0 && j != 0)
          memo[l][i][j] -= memo[l][i - 1][j - 1];
      }

  cout << solve() << endl;
  return 0;
}

int solve() {
  int ans = 0, now[2];
  for(int i = 0; i < k; ++i)
    for(int j = 0; j < k; ++j)
      for(int l = 0; l < 2; ++l) {
        now[l] = 0;
        now[l] += memo[l][k - 1][k - 1];
        if(j != k - 1) now[l] -= memo[1 - l][k - 1][j];
        if(i != k - 1) now[l] -= memo[1 - l][i][k - 1];
        if(i != k - 1 && j != k - 1)
          now[l] += memo[1 - l][i][j];
        ans = max(ans, now[l]);
      }
  return ans;
}

