struct cond
{
    bool color;
    int x;
    int y;
};

typedef std::vector<cond> cond_seq;

struct cmap
{
    cmap(int K, cond_seq &cs)
    {
        int K2 = 2*K;
        map_w.resize(K2*K2);
        map_b.resize(K2*K2);
        map_wx.resize(K2);
        map_wy.resize(K2);
        map_bx.resize(K2);
        map_by.resize(K2);
        for(auto &v : cs)
        {
            int x = v.x % (K2);
            int y = v.y % (K2);
            if(v.color)
            {   // White
                map_w[y*K2 + x] += 1;
                map_wx[x] += 1;
                map_wy[y] += 1;
            }
            else
            {   // Black
                map_b[y*K2 + x] += 1;
                map_bx[x] += 1;
                map_by[y] += 1;
            }
        }

    }
    int get_w(int x, int y, int K) const {x=x%(2*K); y=y%(2*K); return map_w[y*2*K + x];}
    int get_b(int x, int y, int K) const {x=x%(2*K); y=y%(2*K); return map_b[y*2*K + x];}
    int get_wx(int x, int K) const {x=x%(2*K); return map_wx[x];}
    int get_bx(int x, int K) const {x=x%(2*K); return map_bx[x];}
    int get_wy(int y, int K) const {y=y%(2*K); return map_wy[y];}
    int get_by(int y, int K) const {y=y%(2*K); return map_by[y];}
    std::vector<int> map_w;
    std::vector<int> map_b;
    std::vector<int> map_wx, map_wy, map_bx, map_by;
};

int sum_matched_color(int x_offset, int y_offset, cmap &c, int K)
{
    int count = 0;
    int K2 = 2*K;
    // White
    for(int y=y_offset; y<K+y_offset; ++y)
    {
        for(int x=x_offset; x<K+x_offset; ++x)
        {
            count += c.get_w(x, y, K);
        }
    }
    for(int y=y_offset+K; y<K2+y_offset; ++y)
    {
        for(int x=x_offset+K; x<K2+x_offset; ++x)
        {
            count += c.get_w(x, y, K);
        }
    }
    // Black
    for(int y=y_offset; y<K+y_offset; ++y)
    {
        for(int x=x_offset+K; x<K2+x_offset; ++x)
        {
            count += c.get_b(x, y, K);
        }
    }
    for(int y=y_offset+K; y<K2+y_offset; ++y)
    {
        for(int x=x_offset; x<K+x_offset; ++x)
        {
            count += c.get_b(x, y, K);
        }
    }
    return count;
}

int shift_x(int count, int x_offset, int y_offset, cmap &c, int K)
{
    int K2 = 2*K;
    // White
    if(c.get_wx(x_offset-1, K) != 0)
    {
        for(int y=y_offset; y<K+y_offset; ++y)
            count -= c.get_w(x_offset-1, y, K);
    }
    if(c.get_wx(x_offset+K-1, K) != 0)
    {
        for(int y=y_offset; y<K+y_offset; ++y)
            count += c.get_w(x_offset+K-1, y, K);
        for(int y=y_offset+K; y<K2+y_offset; ++y)
            count -= c.get_w(K+x_offset-1, y, K);
    }
    if(c.get_wx(x_offset+K2-1, K) != 0)
    {
        for(int y=y_offset+K; y<K2+y_offset; ++y)
            count += c.get_w(x_offset+K2-1, y, K);
    }
    // Black
    if(c.get_bx(x_offset-1, K) != 0)
    {
        for(int y=y_offset+K; y<K2+y_offset; ++y)
            count -= c.get_b(x_offset-1, y, K);
    }
    if(c.get_bx(x_offset+K-1, K) != 0)
    {
        for(int y=y_offset; y<K+y_offset; ++y)
            count -= c.get_b(x_offset+K-1, y, K);
        for(int y=y_offset+K; y<K2+y_offset; ++y)
            count += c.get_b(x_offset+K-1, y, K);
    }
    if(c.get_bx(x_offset+K2-1, K) != 0)
    {
        for(int y=y_offset; y<K+y_offset; ++y)
            count += c.get_b(x_offset+K2-1, y, K);
    }
    return count;
}

int shift_y(int count, int x_offset, int y_offset, cmap &c, int K)
{
    int K2 = 2*K;
    // White
    if(c.get_wy(y_offset-1, K) != 0)
    {
        for(int x=x_offset; x<K+x_offset; ++x)
            count -= c.get_w(x, y_offset-1, K);
    }
    if(c.get_wy(y_offset+K-1, K) != 0)
    {
        for(int x=x_offset; x<K+x_offset; ++x)
            count += c.get_w(x, y_offset+K-1, K);
        for(int x=x_offset+K; x<K2+x_offset; ++x)
            count -= c.get_w(x, y_offset+K-1, K);
    }
    if(c.get_wy(y_offset+K2-1, K) != 0)
    {
        for(int x=x_offset+K; x<K2+x_offset; ++x)
            count += c.get_w(x, y_offset+K2-1, K);
    }
    // Black
    if(c.get_by(y_offset-1, K) != 0)
    {
        for(int x=x_offset+K; x<x_offset+K2; ++x)
            count -= c.get_b(x, y_offset-1, K);
    }
    if(c.get_by(y_offset+K-1, K) != 0)
    {
        for(int x=x_offset; x<x_offset+K; ++x)
            count -= c.get_b(x, y_offset+K-1, K);
        for(int x=x_offset+K; x<x_offset+K2; ++x)
            count += c.get_b(x, y_offset+K-1, K);
    }
    if(c.get_by(y_offset+K2-1, K) != 0)
    {
        for(int x=x_offset; x<x_offset+K; ++x)
            count += c.get_b(x, y_offset+K2-1, K);
    }
    return count;
}

