using namespace std;

void solve(long long N, long long K, std::vector<long long> x, std::vector<long long> y, std::vector<std::string> c) {
    vector<vector<LL>> tw(2 * K + 1, vector<LL>(2 * K + 1, 0)), tb(2 * K + 1, vector<LL>(2 * K + 1, 0));
    // initialize
    for (LL i = 0; i < N; i++) {
        if (c[i] == "W")
            tw[y[i] % (2 * K) + 1][x[i] % (2 * K) + 1]++;
        else
            tb[y[i] % (2 * K) + 1][x[i] % (2 * K) + 1]++;
    }
    // accumulate
    for (LL i = 0; i <= 2 * K; i++)
        for (LL j = 1; j <= 2 * K; j++) {
            tb[i][j] = tb[i][j] + tb[i][j - 1];
            tw[i][j] = tw[i][j] + tw[i][j - 1];
        }
    for (LL i = 1; i <= 2 * K; i++)
        for (LL j = 0; j <= 2 * K; j++) {
            tb[i][j] = tb[i][j] + tb[i - 1][j];
            tw[i][j] = tw[i][j] + tw[i - 1][j];
        }

    auto get_sum = [K](vector<vector<LL>> &tab, LL x1, LL y1, LL x2, LL y2){
        if(x1>x2 || y1>y2)return 0LL;
        x1=max(x1, 1LL), y2=max(y2, 1LL);
        x2=min(x2, 2*K), y2=min(y2, 2*K);
        return tab[y2][x2]-tab[y2][x1-1]-tab[y1-1][x2]+tab[y1-1][x1-1];
    };
    LL ans=0;
    for(LL x1=1; x1<2*K; x1++){
        for(LL y1=1; y1<2*K; y1++){
            auto pb = get_sum(tb, 1, 1, x1-1, y1-1)
                    + get_sum(tb, x1+K, 1, 2*K, y1-1)
                    + get_sum(tb, x1, y1, x1+K-1, y1+K-1)
                    + get_sum(tb, 1, y1+K, x1-1, 2*K)
                    + get_sum(tb, x1+K, y1+K, 2*K, 2*K);
            auto pw = get_sum(tw, x1, 1, x1+K-1, y1-1)
                    + get_sum(tw, 1, y1, x1-1, y1+K-1)
                    + get_sum(tw, x1+K, y1, 2*K, y1+K-1)
                    + get_sum(tw, x1, y1+K, x1+K-1, 2*K);
            ans = max(ans, pb+pw);
        }
    }
    cout << ans << endl;
}

