    int ans = 0;
    for(int dy = 0; dy <= k; dy++){
        for (int dx = 0; dx <= k; dx++)
        {
            int ans0 = 0;
            for (auto q : ds)
            {
                auto x = q.x + dx, y = q.y + dy;
                x /= k, y /= k;
                ans0 += ( ((x + y) % 2 == 1) && q.c == 'B' ) ? 1 : 0;
