int main() {
	int N, K;
	cin >> N >> K;

	vector<pii> ps;
	vector<bool> cs;

	REP(i, N) {
		int x, y;
		char c;
		cin >> x >> y >> c;

		// どんなに遠くにあるやつも(2K x 2K)の範囲内と等価
		x %= 2 * K;
		y %= 2 * K;

		ps.push_back(pii({ x, y }));

		if (c == 'B') cs.push_back(false);
		else if (c == 'W') cs.push_back(true);
	}

	int max = 0;
	REP(i, 2 * K) {
		REP(j, 2 * K) {
			int count = 0;

			REP(n, N) {
				pii p = pii({ps[n].first - i, ps[n].second - j});

				// 白をベースに考える
				bool check = true;

				if (p.first >= K || p.first < -K) {
					check = !check;
				}

				if (p.second >= K || p.second < -K) {
					check = !check;
				}

				if (check == cs[n]) count++;
			}

			if (count > max) {
				max = count;
			}
		}
	}

	cout << max << endl;
	return 0;
}

