// x : [left, right)
// y : [top, bottom)
int calc(int left, int top, int right, int bottom, const vector<vector<int>>& table)
{
	return table[bottom][right] - table[bottom][left-1] - table[top-1][right] + table[top-1][left-1];
}

int main(void)
{
	int N, K;
	cin >> N >> K;

	const int size = 4 * K + 2;
	vector<vector<int>> table(size, vector<int>(size, 0));
	for(int i=0; i<N; i++){
		int x, y;
		char c;
		cin >> x >> y >> c;

		if(c == WHITE)
			x += K;

		x %= 2*K;
		y %= 2*K;

		x++;
		y++;

		table[y][x]++;
		table[y][x+2*K]++;
		table[y+2*K][x]++;
		table[y+2*K][x+2*K]++;
	}

	for(int i=0; i<size-1; i++){
		for(int j=0; j<size-1; j++){
			table[i][j+1] += table[i][j];
		}
	}
	for(int i=0; i<size-1; i++){
		for(int j=0; j<size-1; j++){
			table[i+1][j] += table[i+1][j];
		}
	}

	int ret = 0;
	for(int i=0; i<2*K; i++){
		for(int j=0; j<2*K; j++){
			int sum = 0;

			int x = i + 1;
			int y = j + 1;
			sum += calc(x, y, x+K, y+K, table);
			sum += calc(x+K, y+K, x+2*K, y+2*K, table);

			ret = max(ret, sum);
		}
	}

	cout << ret << endl;

	return 0;
}

