// 2K * 2K で考えても良いが、4K * 4K にすると
// 累積和を2回計算するだけで良くなり楽になる
int numBlack[201][201] = {};  


int main()
{
    int N, K;
    cin >> N >> K;
    vector<int> x(N), y(N);
    // (x[i], y[i]) を黒に塗るという条件にデータを変形
    for( int i = 0; i < N; ++i ){
        char c;
        cin >> x[i] >> y[i] >> c;
        if( c == 'W' ) y[i] += K;
        x[i] %= 2*K;
        y[i] %= 2*K;
    }


    // 市松模様を黒い部分の左下で特徴付ける
    // 全ての i について、(x[i], y[i]) を黒として含むような塗り方の K*K 通りのマスを
    // +1 すると、その最大値が答えになる
    // 高速化するために、2次元累積和を用いる

    // 2次元累積和 
    for( int i = 0; i < N; ++i ) numBlack[x[i]][y[i]] += 1;
    for( int i = 0; i < 2*K; ++i ){
        for( int j = 0; j < 2*K; ++j ){
            numBlack[i+1][j] += numBlack[i][j];
        }
    }
    for( int i = 0; i < 2*K; ++i ){
        for( int j = 0; j < 2*K; ++j ){
            numBlack[i][j+1] += numBlack[i][j];
        }
    }

    // 最大値の探索
    int ans = 0;
    for( int i = 0; i < K; ++i ){
        for( int j = 0; j < K; ++j ){
            int a = numBlack[i][j];
            int b = numBlack[i][j] - numBlack[i+K][j] - numBlack[i][j+K] + numBlack[i+K][j+K];
            int c = numBlack[2*K-1][j] - numBlack[i+K][j];
            int d = numBlack[i][2*K-1] - numBlack[i][j+K];
            int e = numBlack[i+K][j+K] - numBlack[2*K-1][j+K] - numBlack[i+K][2*K-1] + numBlack[2*K-1][2*K-1];
            ans = max( ans, a+b+c+d+e );
        }
    }
    cout << ans << endl;

    return 0;
}

