int main() {
    cin.tie(0); ios::sync_with_stdio(false);

    int n, k;
    cin >> n >> k;

    vector<vector<int>> b(k + 2, vector<int>(k + 2));
    vector<vector<int>> w(k + 2, vector<int>(k + 2));
    for (int i = 0, x, y; i < n; ++i) {
        char c;
        cin >> x >> y >> c;

        int p = (((x - (x % k)) / k) + (( y - (y % k)) / k)) % 2;
        if (p) c = (c == 'B' ? 'W' : 'B');
        x = (x % k) + 1;
        y = (y % k) + 1;
        if (c == 'B') ++b[y][x];
        else ++w[y][x];
    }

    for (int y = 1; y <= k + 1; ++y) {
        for (int x = 1; x <= k + 1; ++x) {
            b[y][x] += (b[y - 1][x] + b[y][x - 1] - b[y - 1][x - 1]);
            w[y][x] += (w[y - 1][x] + w[y][x - 1] - w[y - 1][x - 1]);
        }
    }

    int ans = 0;
    for (int y = 1; y <= k; ++y) {
        for (int x = 1; x <= k; ++x) {
            // black
            int cnt_b = b[y][x] + (b[k][k] - b[y][k] - b[k][x] + b[y][x]);
            cnt_b += (w[y][k] - w[y][x] + w[k][x] - w[y][x]);

            // white
            int cnt_w = w[y][x] + (w[k][k] - w[y][k] - w[k][x] + w[y][x]);
            cnt_w += (b[y][k] - b[y][x] + b[k][x] - b[y][x]);

            ans = max({ans, cnt_b, cnt_w});
        }
    }

    cout << ans << endl;

    return 0;
}

