int sum(int x, int y)
{
    if(x<0 || y<0)
        return 0;
    return matW[x][y];
}

int dodaj(int x2, int y2)
{
    int x1=x2-k+1;
    int y1=y2-k+1;
    if(x2<0 || x1>=2*k)
        return 0;
    if(y2<0 || y1>=2*k)
        return 0;

    if(x2>=2*k)
        x2=2*k-1;
    if(y2>=2*k)
        y2=2*k-1;

    if(x1<0)
        x1=0;
    if(y1<0)
        y1=0;

    return sum(x2,y2)-sum(x2,y1-1)-sum(x1-1,y2)+sum(x1-1,y1-1);
}

int solve(int xc, int yc)
{
    int suma=0;
    suma+=dodaj(xc,yc);
    suma+=dodaj(xc+2*k,yc);
    suma+=dodaj(xc+k,yc+k);
    suma+=dodaj(xc,yc+2*k);
    suma+=dodaj(xc+2*k,yc+2*k);
    suma+=dodaj(xc-k,yc+k);
    //cout<<"*"<<suma<<"   "<<xc<<" "<<yc<<endl;
    return suma;
}

