const ll N=2e3+10;
mat b(N,vec(N,0));
ll n,k,kk;

ll area(ll x,ll y) {
  ll tmp=0;
  if(x+k-1<=kk) {
    if(y+k-1<=kk) {
      tmp+=b[x+k-1][y+k-1];
      tmp+=b[x-1][y-1];
      tmp-=b[x-1][y+k-1];
      tmp-=b[x+k-1][y-1];
    }
    else {
      tmp+=b[x+k-1][kk];
      tmp-=b[x+k-1][y-1];
      tmp-=b[x-1][kk];
      tmp+=b[x-1][y-1];
      tmp+=b[x+k-1][y+k-1-kk];
      tmp-=b[x-1][y+k-1-kk];
    }
  }
  else {
    if(y+k-1<=kk) {
      tmp+=b[kk][y+k-1];
      tmp-=b[x-1][y+k-1];
      tmp-=b[kk][y-1];
      tmp+=b[x-1][y-1];
      tmp+=b[x+k-1-kk][y+k-1];
      tmp-=b[x+k-1-kk][y-1];
    }
    else {
      tmp+=b[kk][kk];
      tmp-=b[x-1][kk];
      tmp-=b[kk][y-1];
      tmp+=b[x-1][y-1];
      tmp+=b[x+k-1-kk][y+k-1-kk];
    }
  }
  return tmp;
}

int main() {
  cin >> n >> k;
  kk=2*k;
  for(ll i=0;i<n;i++) {
    ll x,y;
    char c;
    cin >> x >> y >> c;
    if(c=='B') b[x%kk+1][y%kk+1]++;
    else b[(x+k)%kk+1][(y+k)%kk+1]++;
  }
  for(ll i=0;i<kk;i++) {
    for(ll j=0;j<=kk;j++) {
      b[i+1][j]+=b[i][j];
    }
  }
  for(ll i=0;i<=kk;i++) {
    for(ll j=0;j<kk;j++) {
      b[i][j+1]+=b[i][j];
    }
  }
  ll ans=0;
  for(ll i=1;i<=kk;i++) {
    for(ll j=1;j<=kk;j++) {
      ll tmp=0;
      tmp+=area(i,j);
      tmp+=area((i+k-1)%kk+1,(j+k-1)%kk+1);
      ans=max(ans,tmp);
    }
  }
  cout << ans << endl;
}

