int N, K;
int x[100010], y[100010];
char c[100010];
int w[4010][4010], b[4010][4010];

int calcW(int p, int q, int r, int s) {
  int res = w[r][s];
  if (p != 0 && q != 0) res += w[p-1][q-1];
  if (p != 0) res -= w[p-1][s];
  if (q != 0) res -= w[r][q-1];
  return res;
}
int calcB(int p, int q, int r, int s) {
  int res = b[r][s];
  if (p != 0 && q != 0) res += b[p-1][q-1];
  if (p != 0) res -= b[p-1][s];
  if (q != 0) res -= b[r][q-1];
  return res;
}

int main() {
  cin.tie(0);
  ios_base::sync_with_stdio(false);
  cout << fixed << setprecision(10);

  cin >> N >> K;
  int K2 = K*2;
  for (int i = 0; i < N; i++) {
    cin >> x[i] >> y[i] >> c[i];
    x[i] %= K2;
    y[i] %= K2;
    if (c[i] == 'W') {
      w[y[i]][x[i]]++;
      w[y[i]+K2][x[i]]++;
      w[y[i]][x[i]+K2]++;
      w[y[i]+K2][x[i]+K2]++;
    } else {
      b[y[i]][x[i]]++;
      b[y[i]+K2][x[i]]++;
      b[y[i]][x[i]+K2]++;
      b[y[i]+K2][x[i]+K2]++;
    }
  }
  for (int i = 0; i < 2*K2; i++) {
    for (int j = 1; j < 2*K2; j++) {
      w[i][j] += w[i][j-1];
      b[i][j] += b[i][j-1];
    }
  }
  for (int j = 0; j < 2*K2; j++) {
    for (int i = 1; i < 2*K2; i++) {
      w[i][j] += w[i-1][j];
      b[i][j] += b[i-1][j];
    }
  }
  int ans = 0;
  for (int i = 0; i < K2; i++) {
    for (int j = 0; j < K2; j++) {
      ans = max(ans, calcW(i, j, i+K-1, j+K-1) + calcW(i+K, j+K, i+2*K-1, j+2*K-1) + calcB(i+K, j, i+2*K-1, j+K-1) + calcB(i, j+K, i+K-1, j+2*K-1));
    }
  }
  cout << ans << endl;

  return 0;
}

