LL tb[2010][2010] = {};
LL s[2010][2010] = {};

//累積和の取得[y1,y2)×[x1,x2)
LL get(LL y2, LL x2, LL y1, LL x1) {
	return s[y2][x2] - s[y2][x1] - s[y1][x2] + s[y1][x1];
}

int main() {

	LL n, k; cin >> n >> k;

	for (LL i = 0; i < n; i++) {
		LL x, y; char c; cin >> x >> y >> c;
		if (c == 'W')y += k;

		y %= (2 * k);
		x %= (2 * k);

		tb[y][x]++;
	}

	//累積和の構築
	for (LL i = 0; i < 2 * k; i++) {
		for (LL j = 0; j < 2 * k; j++) {
			s[i + 1][j + 1] = s[i][j + 1] + s[i + 1][j] - s[i][j] + tb[i][j];
		}
	}

	//集計
	//a:左上
	//b:右上
	//c:中央
	//d:左下
	//e:右下

	LL ans = 0;
	for (LL i = 0; i < k + 1; i++) {
		for (LL j = 0; j < k + 1; j++) {
			LL a = get(i, j, 0, 0);
			LL b = get(i, 2 * k, 0, j + k);
			LL c = get(i + k, j + k, i, j);
			LL d = get(2 * k, j, i + k, 0);
			LL e = get(2 * k, 2 * k, i + k, j + k);
			ans = max(ans, a + b + c + d + e);
			ans = max(ans, n - (a + b + c + d + e));
		}
	}


	cout << ans << endl;

	return 0;
}

