int grid[2010][2010] = {};

void imos(int x1, int y1, int x2, int y2) {
    grid[x1][y1]++;
    grid[x2 + 1][y2 + 1]++;
    grid[x1][y2 + 1]--;
    grid[x2 + 1][y1]--;
}

int main() {
    int n, k;
    cin >> n >> k;

    rep(i, n) {
        int x, y;
        char c;
        cin >> x >> y >> c;
        if (c == 'W') x += k;
        x %= 2 * k;
        y %= 2 * k;
        if ((x < k && y < k) || (x >= k && y >= k)) {
            if (x >= k) {
                x -= k;
                y -= k;
            }
            imos(0, 0, x, y); //左下
            imos(x + 1, y + 1, x + k, y + k); //中央
            imos(0, y + k + 1, x, 2 * k - 1); //左上
            imos(x + k + 1, 0, 2 * k - 1, y); //右下
            imos(x + k + 1, y + k + 1, 2 * k - 1, 2 * k - 1); //右上
        } else {
            if (y >= k) {
                x += k;
                y -= k;
            }
            imos(x - k + 1, 0, x, y); //下
            imos(0, y + 1, x - k, y + k); //左
            imos(x - k + 1, y + k + 1, x, 2 * k - 1); //上
            imos(x + 1, y + 1, 2 * k - 1, y + k); //右
        }
    }

    rep(i, 2 * k) rep(j, 2 * k - 1) grid[i][j + 1] += grid[i][j];
    rep(i, 2 * k - 1) rep(j, 2 * k) grid[i + 1][j] += grid[i][j];

    int Max = 0;

    rep(i, 2 * k) rep(j, 2 * k) Max = max(Max, grid[i][j]);

    cout << Max << endl;

    return 0;
}

