using namespace std;

int calc(int i, int j, int k, vector<vi> &mp) {
  int l = min(2 * k, max(j, 0));
  int r = min(j + k, 2 * k);

  int b = min(2 * k, max(i, 0));
  int t = min(i + k, 2 * k);
  // cout << l << " " << r << "  " << b << " " << t << endl;
  return mp[t][r] - mp[b][r] - mp[t][l] + mp[b][l];
}

int main() {
  int n, k;
  cin >> n >> k;
  vector<vi> w(2 * k + 1, vi(2 * k + 1, 0)), b(2 * k + 1, vi(2 * k + 1, 0));

  REP(i, n) {
    int x, y;
    char c;
    cin >> x >> y >> c;
    x %= 2 * k;
    y %= 2 * k;
    x++;
    y++;
    if (c == 'W') {
      w[y][x]++;
    } else {
      b[y][x]++;
    }
  }

  FOR(i, 1, 2 * k + 1) {
    FOR(j, 1, 2 * k + 1) {
      w[i][j] += w[i - 1][j] + w[i][j - 1] - w[i - 1][j - 1];
      b[i][j] += b[i - 1][j] + b[i][j - 1] - b[i - 1][j - 1];
    }
  }

  int ans = 0;
  REP(i, 2 * k + 1) {
    REP(j, 2 * k + 1) {
      int white = calc(i, j, k, w) + calc(i + k, j + k, k, w) +
                  calc(i - k, j - k, k, w) + calc(i + k, j - k, k, w) +
                  calc(i - k, j + k, k, w);
      int black = calc(i + k, j, k, b) + calc(i, j + k, k, b) +
                  calc(i - k, j, k, b) + calc(i, j - k, k, b);

      ans = max(ans, white + black);
    }
  }
  cout << ans << endl;

  return 0;
}

