struct Node {
	int x;
	int y;
	bool want;
	Node() {this->x = 0;this->y = 0;this->want = false;}
};

Node node[MAXN + 1];

int main() {
	int n;
	int k;
	scanf("%d%d", &n, &k);
	for (int i = 1; i <= n; i++) {
		char buff[10];
		scanf("%d%d%s", &node[i].x, &node[i].y, buff);
		if (buff[0] == 'B') node[i].want = true;
	}
	int minNo = 0x7fffffff;
	for (int i = 1; i <= n; i++) {
		Node t = node[i];
		int bNo = 0;
		int wNo = 0;
		//printf("If Node %d is black:\n", i);
		for (int j = 1; j <= n; j++) {
			Node s = node[j];
			bool color;
			bool xColor;
			bool yColor;
			if (s.x >= t.x) xColor = !(((s.x - t.x) / k) % 2);
			else xColor = (((t.x - s.x - 1) / k) % 2);
			if (s.y >= t.y) yColor = !(((s.y - t.y) / k) % 2);
			else yColor = ((t.y - s.y - 1) / k) % 2;
			color = !(xColor ^ yColor);
			//printf("	Node %d is %s\n", j, color ? "black" : "white");
			if (color != node[j].want) bNo++;
			else wNo++;
			if (bNo >= minNo && wNo >= minNo) break;
		}
		minNo = min(minNo, min(bNo, wNo));
		if (!minNo) break;
	}
	printf("%d\n", n - minNo);
	return 0;
}

