	int n = in, k = in;
	VI x(n), y(n); vector<char> c(n);
	rep(i, n) { x[i] = in; y[i] = in; c[i] = in; }
	rep(i, n)if (c[i] == 'W')x[i] += k;
	rep(i, n)if (x[i] >= k) {
		int m = x[i] / k * k;
		x[i] -= m; y[i] -= m;
	}
	rep(i, n)if (y[i] >= k * 2) {
		int m = y[i] / (k * 2) * (k * 2);
		y[i] -= m;
	}
	rep(i, n)if (y[i] < 0) {
		int m = Age2(0 - y[i], k * 2);
		y[i] += m;
	}
	rep(i, n) {
		assert(0 <= x[i] && x[i] < k);
		assert(0 <= y[i] && y[i] < k * 2);
	}

	VVI g(k * 2, VI(k));
	rep(i, n) {
		g[y[i]][x[i]]++;
	}
	CulSum2D<int> s(g);

	int ans = 0;
	rep(y, k)rep(x, k) {
		chmax(ans,
			s(y - k, y, x - k, x) +
			s(y, y + k, x, x + k) +
			s(y + k, y + k * 2, x - k, x)
		);
	}
	out(ans);
}

