int main() {
    int n, k;
    cin >> n >> k;
    vl x(n), y(n);
    vector<char> c(n);
    vvi b(4 * k, vi(4 * k, 0));
    vvi w(4 * k, vi(4 * k, 0));
    for (int i = 0; i < n; ++i) {
        cin >> y[i] >> x[i] >> c[i];
        if (c[i] == 'B')
            b[y[i] % (2 * k)][x[i] % (2 * k)]++;
        else if (c[i] == 'W')
            w[y[i] % (2 * k)][x[i] % (2 * k)]++;
    }
    for (int i = 1; i < 4 * k; ++i) {
        for (int j = 0; j < 4 * k; ++j) {
            b[i][j] += b[i - 1][j];
            w[i][j] += w[i - 1][j];
        }
    }
    for (int i = 1; i < 4 * k; ++i) {
        for (int j = 0; j < 4 * k; ++j) {
            b[j][i] += b[j][i - 1];
            w[j][i] += w[j][i - 1];
        }
    }
    ll ret = 0;
    for (int i = 0; i <= k; ++i) {
        for (int j = 0; j <= k; ++j) {
            ll black = b[i + 2 * k - 1][j + 2 * k - 1] - b[i + 2 * k - 1][j + k - 1] - b[i + k - 1][j + 2 * k - 1] +
                       2 * b[i + k - 1][j + k - 1];
            if (i != 0)
                black += b[i - 1][j + 2 * k - 1] - 2 * b[i - 1][j + k - 1];
            if (j != 0)
                black += b[i + 2 * k - 1][j - 1] - 2 * b[i + k - 1][j - 1];
            if (i != 0 && j != 0)
                black += 2 * b[i - 1][j - 1];

            ll white = w[i + 2 * k - 1][j + 2 * k - 1] - w[i + 2 * k - 1][j + k - 1] - w[i + k - 1][j + 2 * k - 1] +
                       2 * w[i + k - 1][j + k - 1];
            if (i != 0)
                white += w[i - 1][j + 2 * k - 1] - 2 * w[i - 1][j + k - 1];
            if (j != 0)
                white += w[i + 2 * k - 1][j - 1] - 2 * w[i + k - 1][j - 1];
            if (i != 0 && j != 0)
                white += 2 * w[i - 1][j - 1];
            white = w[3 * k][3 * k] - white;
            chmax(ret, black + white);
        }
    }
    cout << ret << "\n";

    return 0;
}

