signed main() {
	cin >> n >> k;
	int k2 = 2 * k;
	for (int i = 0; i < n; i++) {
		int x, y;
		char c;
		cin >> x >> y >> c;
		x %= k2; y %= k2;
		if (c == 'B') {
			b[x][y]++;
			b[x + k2][y]++;
			b[x][y + k2]++;
			b[x + k2][y + k2]++;
		}
		else {
			w[x][y]++;
			w[x + k2][y]++;
			w[x][y + k2]++;
			w[x + k2][y + k2]++;
		}
	}
	for (int i = 0; i < k2 * 2; i++) {
		for (int j = 0; j < k2 * 2; j++) {
			bb[i + 1][j + 1] += b[i][j] + bb[i + 1][j] + bb[i][j + 1] - bb[i][j];
			wb[i + 1][j + 1] += w[i][j] + wb[i + 1][j] + wb[i][j + 1] - wb[i][j];
		}
	}
	int ans = 0;
	for (int i = 0; i < k2; i++) {
		for (int j = 0; j < k2; j++) {
			int x = i + k, y = j + k;
			int sum = bsum(i, j, x, y) + bsum(x, y, x + k, y + k);
			sum += wsum(i + k, j, x + k, y) + wsum(i, j + k, x, y + k);
			ans = max(ans, sum);
		}
	}
	cout << ans << endl;
