  iw[0]=w[0];

  rep1(i,KK-1){
    ib[i]=ib[i-1]+b[i];
    iw[i]=iw[i-1]+w[i];
  }
  // rep(i,KK){
  //   cout<<b[i]<<" ";
  // }
  // cout<<endl;
  //
  // rep(i,KK){
  //   cout<<w[i]<<" ";
  // }
  // cout<<endl;
  ll res = 0;
  rep(i,KK){
    ll r = 0;
    if(i<K){
      r += IW(i+K-1) - IW(i-1);
      r += IB(i-1);
      r += IB(KK-1) - IB(i+K-1);
    }
    else{
      r += IW(KK-1) - IW(i-1);
      r += IB(i-1) - IB(i-K-1);
      r += IW(i-K-1);
    }
    res = max(res,r);
  }
  return res;
}

