int main() {
  ll N, K;
  cin >> N >> K;
  vector<ll> x(N), y(N);
  vector<char> c(N);
  map<char, char> m;
  m['B'] = 'W';
  m['W'] = 'B';
  vector<vector<int>> W(K, vector<int>(K));
  vector<vector<int>> B(K, vector<int>(K));
  rep(i, N) {
    cin >> x[i] >> y[i] >> c[i];
    if ((x[i] / K) & 1)
      c[i] = m[c[i]];
    if ((y[i] / K) & 1)
      c[i] = m[c[i]];
    x[i] %= K;
    y[i] %= K;
    if (c[i] == 'W') {
      W[x[i]][y[i]]++;
    } else if (c[i] == 'B') {
      B[x[i]][y[i]]++;
    }
  }

  vector<vector<int>> Wsum(K + 1, vector<int>(K + 1));
  vector<vector<int>> Bsum(K + 1, vector<int>(K + 1));
  repp(i, 1, K) {
    repp(j, 1, K) {
      Wsum[i][j] = W[i - 1][j - 1] + Wsum[i - 1][j] + Wsum[i][j - 1] -
                   Wsum[i - 1][j - 1];
      Bsum[i][j] = B[i - 1][j - 1] + Bsum[i - 1][j] + Bsum[i][j - 1] -
                   Bsum[i - 1][j - 1];
    }
  }

  int ans = 0;
  repp(i, 0, K) {
    repp(j, 0, K) {
      int temp = 0;
      temp += Wsum[K][K] - Wsum[i][K] - Wsum[K][j] + 2 * Wsum[i][j];
      temp += Bsum[i][K] + Bsum[K][j] - 2 * Bsum[i][j];
      chmax(ans, temp);
    }
  }
  cout << ans << endl;
}

