    */

    int row[2*k][2] = {}; // 0 is true, 1 is false.
    rep(i,2*k){
        rep(j,2*k){
            if((i<k&&j<k)||(k<=i&&k<=j)){
                row[j][0] += a[i][j][0];
                row[j][1] += a[i][j][1];
            }else{
                row[j][0] += a[i][j][1];
                row[j][1] += a[i][j][0];
            }
        }
    }


    int dp[2*k][2*k];
    dp[0][0] = 0;
    rep(j,2*k){
        dp[0][0] += row[j][0];
    }

    rep(i,2*k){
        rep(j,2*k){
            if(i==0&&j==0){
                continue;
            }else if(j==0){
                swap(row[2*k-1][0],row[2*k-1][1]);
                swap(row[(j-1+k)%(2*k)][0],row[(j-1+k)%(2*k)][1]);
                dp[i][j] = 0;
                rep(l,2*k){
                    if(l<k){
                        row[l][0] -= a[i-1][l][0];
                        row[l][0] += a[i-1][l][1];
                        row[l][1] += a[i-1][l][0];
                        row[l][1] -= a[i-1][l][1];
                        row[l][0] -= a[(i+k-1)%(2*k)][l][1];
                        row[l][0] += a[(i+k-1)%(2*k)][l][0];
                        row[l][1] += a[(i+k-1)%(2*k)][l][1];
                        row[l][1] -= a[(i+k-1)%(2*k)][l][0];
                    }else{
                        row[l][0] -= a[i-1][l][1];
                        row[l][0] += a[i-1][l][0];
                        row[l][1] += a[i-1][l][1];
                        row[l][1] -= a[i-1][l][0];
                        row[l][0] -= a[(i+k-1)%(2*k)][l][0];
                        row[l][0] += a[(i+k-1)%(2*k)][l][1];
                        row[l][1] += a[(i+k-1)%(2*k)][l][0];
                        row[l][1] -= a[(i+k-1)%(2*k)][l][1];
                    }

                    dp[i][j] += row[l][0];
                }
            }else{
                dp[i][j] = dp[i][j-1];
                dp[i][j] -= row[j-1][0];
                dp[i][j] += row[j-1][1];
                swap(row[j-1][0],row[j-1][1]);
                dp[i][j] -= row[(j-1+k)%(2*k)][0];
                dp[i][j] += row[(j-1+k)%(2*k)][1];
                swap(row[(j-1+k)%(2*k)][0],row[(j-1+k)%(2*k)][1]);
            }
        }
    }

    int ans = 0;
    rep(i,2*k){
        rep(j,2*k){
            //cout << i << ' ' << j << ' ' << dp[i][j] << endl;
            ans = max(ans,dp[i][j]);
        }
    }

    cout << ans << endl;
    return 0;
}

