    cout<<"B"<<endl;
    for(i = 0; i<4*k; i++){
        for(j = 0; j<4*k; j++){
            cout<<b[i][j]<<" ";
        }
        cout<<endl;
    }

    for(i = 1; i<4*k; i++){
        w[i][0] += w[i-1][0];
        w[0][i] += w[0][i-1];
        b[i][0] += b[i-1][0];
        b[0][i] += b[0][i-1];
    }
    for(i = 1; i<4*k; i++){
        for(j = 1; j<4*k; j++){
            w[i][j] += (w[i-1][j] + w[i][j-1] - w[i-1][j-1]);
            b[i][j] += (b[i-1][j] + b[i][j-1] - b[i-1][j-1]);

        }
    }
    cout<<"W"<<endl;
    for(i = 0; i<4*k; i++){
        for(j = 0; j<4*k; j++){
            cout<<w[i][j]<<" ";
        }
        cout<<endl;
    }

    cout<<"B"<<endl;
    for(i = 0; i<4*k; i++){
        for(j = 0; j<4*k; j++){
            cout<<b[i][j]<<" ";
        }
        cout<<endl;
    }

    int totw = 0;
    for(i = 0; i<4*k; i++)
        for(j = 0; j<4*k; j++)
        totw += w[i][j];
    int ans = 0;
    for(i = k; i<2*k; i++){
        for(j = k; j<2*k; j++){
            // find starting points done.
            int bc = getBCount(i-k, j-k) + getBCount(i+k, j-k)+ getBCount(i-k, j+k) + getBCount(i+k, j+k) + getBCount(i, j);
            int wc = getWCount(i-k, j-k)+getWCount(i+k, j-k)+getWCount(i-k, j+k)+getWCount(i+k, j+k)+getWCount(i, j);
            ans = max(ans, bc+totw-wc);
        }
    }
    cout<<ans<<endl;





    return 0;
}

