    rep(i,n){
        int a,b; cin>>a>>b; 
        char c; cin>>c;

        if(c == 'W') {wl[a%(2*k)][b%(2*k)]++; wc++;}
        else bl[a%(2*k)][b%(2*k)]++;
    }

    vector <vector<int>> rw(2*k+1,vector <int>(2*k+1)), rb(2*k+1,vector <int>(2*k+1));
    for (int i = 0; i < 2*k; ++i)
        for (int j = 0; j < 2*k; ++j){
            rw[i+1][j+1] = rw[i][j+1] + rw[i+1][j] - rw[i][j] + wl[i][j];
            rb[i+1][j+1] = rb[i][j+1] + rb[i+1][j] - rb[i][j] + bl[i][j];
        }

    int ans = 0;
    rep(i, k-1){
        rep(j, k-1){

            int tmp = 0, tmpw=0;

            tmp += rb[i][j];
            tmpw += rw[i][j];
            tmp += rb[i+k][j+k] - rb[i][j+k] - rb[i+k][j] + rb[i][j];
            tmpw += rw[i+k][j+k] - rw[i][j+k] - rw[i+k][j] + rw[i][j];
            tmp += rb[2*k][2*k] - rb[2*k][j+k] - rb[i+k][2*k] + rb[i+k][j+k];
