            tmp += rb[2*k][j] - rb[i+k][j];
            tmpw += rw[2*k][j] - rw[i+k][j];
            tmp += rb[i][2*j] - rb[i][j+k];
            tmpw += rw[i][2*j] - rw[i][j+k];

            ans = max(ans, tmp + wc-tmpw);
        }
    }
    cout<<ans<<endl;
}

