    rep(i, N) {
        int x, y;
        char c;
        cin >> x >> y >> c;
        if (c == 'B') x += K;
        ++bk[x % (2 * K)][y % (2 * K)];
    }
    rep(i,4*K)rep(j,4*K){
        bk[i][j] = bk[i%(2*K)][j%(2*K)];
    }

    rep(i, 4 * K-1) rep(j, 4 * K) {
        bk[i + 1][j] += bk[i][j];
    }
    rep(i, 4 * K) rep(j, 4 * K-1) {
        bk[i][j+1] += bk[i][j];
    }


    int ans = 0;
    rep(i,2*K)rep(j,2*K){
        int tmp = 0;
        tmp+=bk[i+K-1][j+K-1];
        if(i>0) tmp-=bk[i-1][j+K-1];
        if(j>0) tmp-=bk[i+K-1][j-1];
        if(i>0&&j>0) tmp+=bk[i-1][j-1];

        tmp+=bk[i+2*K-1][j+2*K-1];
        tmp-=bk[i+K-1][j+2*K-1];
        tmp-=bk[i+2*K-1][j+K-1];
        tmp+=bk[i+K-1][j+K-1];

        ans = max(ans,tmp);
    }
    cout << ans << endl;
}

