int main(){


    cin >> n >> k;
    int x,y,ban,iro;
    char c;
    for(int i = 0;i < n;i++){
        scanf("%d %d %c",&x,&y,&c);
        ban = 0;
        iro = (x/k + y/k)%2;
        if(iro == 0 && c == 'B' or iro == 1 && c == 'W'){
            ban = 2; 
        }
        ch[x%k][y%k][iro+ban] += 1;
    }

    int tmp1,tmp2,ans = 0,ans2 = 0;
    for(int i = 0;i < 4;i++){
        for(int j = 0;j < k;j++){
            tmp1 = 0;
            tmp2 = 0;
            for(int l = 0;l < k;l++){
                tmp1 += ch[j][l][i];
                tmp2 += ch[l][j][i];
            }
            ch[j][k][i] = tmp1;
            ch[k][j][i] = tmp2;
            if(i < 2){
                ans += tmp1;
            }
            if(i >= 2){
                ans2 += tmp1;
            }
        }
    }




    dp[0][0][0] = ans;
    dp[0][0][1] = ans2;
    ans = max(ans,ans2);
    for(int i = 0;i < k;i++){
        if(i != 0){
            dp[0][i][0] = (dp[0][i-1][0] + ch[k][i-1][2] + ch[k][i-1][3] - ch[k][i-1][0] - ch[k][i-1][1]);
            dp[0][i][1] = (dp[0][i-1][1] - ch[k][i-1][2] - ch[k][i-1][3] + ch[k][i-1][0] + ch[k][i-1][1]);
        }
        ans = max(ans,max(dp[0][i][0],dp[0][i][1]));
        for(int j = 1;j < k;j++){
            dp[j][i][0] = (dp[j-1][i][0] + ch[j-1][k][2] + ch[j-1][k][3] - ch[j-1][k][0] - ch[j-1][k][1]);
            dp[j][i][1] = (dp[j-1][i][1] - ch[j-1][k][2] - ch[j-1][k][3] + ch[j-1][k][0] + ch[j-1][k][1]);
            ans = max(ans,max(dp[j][i][0],dp[j][i][1]));
        }
    }


    cout << ans << endl;

    return 0;
}

