ll s[2001][2001] = {};

int main()
{
	cin >> n >> k;
	ll X, Y;
	char C;
	ll sum = 0;
	ll white = 0;
	rep(i, 0, n) {
		cin >> X >> Y >> C;
		X = X % (2 * k);
		Y = Y % (2 * k);

		if (C == 'B') {
			s[X + 1][Y + 1]++; sum++;
		}
		else if (C == 'W') {
			s[X + 1][Y + 1]--; sum--; white++;
		}
	}

	repe(i, 1, 2 * k) repe(j, 1, 2 * k) s[i][j] += s[i][j - 1];
	repe(j, 1, 2 * k) repe(i, 1, 2 * k) s[i][j] += s[i - 1][j];

	ll maxV = -(1 << 25);
	rep(i, 0, k) {
		rep(j, 0, k) {
			ll a = s[i][j];
			ll b = s[i + k][j + k] - s[i + k][j] - s[i][j + k] + a;
			ll c = s[2 * k][j] - s[i + k][j];
			ll d = s[i][2 * k] - s[i][j + k];
			ll e = s[2 * k][2 * k] - s[2 * k][j + k] - s[i + k][2 * k] + s[i + k][j + k];
			ll tmp = a + b + c + d + e;
			maxV = max(maxV, max(tmp, sum - tmp));
		}
	}
	maxV += white;

	cout << maxV << endl;

	return 0;
}

