#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// const int INF = 2147483647;
// const ll INF = 9223372036854775807;
// const ll MOD = 1e9 + 7;

int N, K;
int h[4000][4000];
int cum[4001][4001];

int main() {
	cin >> N >> K;

	for (int i=0; i<N; i++) {
		int x, y;
		char c;
		cin >> x >> y >> c;

		// W to B
		if (c == 'W') x += K;

		// 0 < x < K*2, 0 < y < K*2 の範囲に変換
		x = x % (K*2);
		y = y % (K*2);

		h[x][y]++;

		// 二次元累積和の算出を楽にするために
		// 0 < x < K*4, 0 < y < K*4 の範囲でループさせる
		h[x + K*2][y]++;
		h[x][y + K*2]++;
		h[x + K*2][y + K*2]++;
	}

	/*
	// **** debug ****
	for (int y=0; y<K*4; y++) {
		for (int x=0; x<K*4; x++) {
			cout << h[x][y] << " ";
		}
		cout << endl;
	}
	*/

	for (int y=0; y<K*4; y++) {
		for (int x=0; x<K*4; x++) {
			cum[x+1][y+1] = cum[x][y+1] + cum[x+1][y] - cum[x][y] + h[x][y];
		}
	}

	int ans = 0;
	for (int y=0; y<K*2; y++) {
		for (int x=0; x<K*2; x++) {
			int ok1 = cum[x + K][y + K] - cum[x][y + K] - cum[x + K][y] + cum[x][y];
			int ok2 = cum[x + K*2][y + K*2] - cum[x + K][y + K*2] - cum[x + K*2][y + K] + cum[x + K][y + K];
			ans = max(ans, ok1 + ok2);
		}
	}

	cout << ans << endl;

	return 0;
}

