#define all(t) t.begin(), t.end()
#define mat(type, row, col, init) vector<vector<type>>(row, vector<type>(col, init));
#define inrange(n, lb, ub) ((lb)<=(n) && (n) <=(ub))
int rec(vector<vector<int>> &mos, int k, int xl, int yl, int xr, int yr) {
	int left = inrange(xr, 0, 2 * k - 1) && inrange(yl - 1, 0, 2 * k - 1) ? mos[xr][yl - 1] : 0;
	int up = inrange(xl - 1, 0, 2 * k - 1) && inrange(yr, 0, 2 * k - 1) >= 0 ? mos[xl - 1][yr] : 0;
	int corner = inrange(xl - 1, 0, 2 * k - 1) && inrange(yl - 1, 0, 2 * k - 1) ? mos[xl - 1][yl - 1] : 0;
	int body = inrange(xr, 0, 2 * k - 1) && inrange(yr, 0, 2 * k - 1) ? mos[xr][yr] : 0;
	return body - left - up + corner;
}
int main() {
	int n, k;
	cin >> n >> k;
	auto t = mat(int, 2 * k, 2 * k, 0);
	rep(i, n) {
		ll x, y;
		string c;
		cin >> x >> y >> c;
		if (c == "B") t[x % (2 * k)][y % (2 * k)]++;
		else t[(x + k) % (2 * k)][y % (2 * k)]++;
	}
	auto mos = t;
	rep(i, 2 * k)rep(j, 2 * k - 1)mos[i][j + 1] += mos[i][j];
	rep(i, 2 * k)rep(j, 2 * k - 1)mos[j + 1][i] += mos[j][i];
	int ma = 0;
	rep(i, k)rep(j, k) {
		int xl = i;
		int xr = i + k - 1;
		int yl = j;
		int yr = j + k - 1;
		int center = rec(mos, k, xl, yl, xr, yr);
		int upleft = rec(mos, k, 0, 0, xl - 1, yl - 1);
		int upright = rec(mos, k, 0, yr + 1, xl - 1, 2 * k - 1);
		int lowleft = rec(mos, k, xr + 1, 0, 2 * k - 1, yl - 1);
		int lowright = rec(mos, k, xr + 1, yr + 1, 2 * k - 1, 2 * k - 1);
		int num = center + upleft + upright + lowleft + lowright;
		ma = max({ ma, num, n - num });
	}
	cout << ma;
	return 0;

}

