int check_num(int N, int K, int x0, int y0, int *x, int *y, char *c) {
  int num = 0;
  for (int i = 0; i < N; ++i) {
    int x_i = x[i] + x0;
    int y_i = y[i] + y0;
    bool black = (((x_i / K) + (y_i / K)) % 2 == 0);
    if ((black && c[i] == 'B') || (!black && c[i] == 'W')) {
      ++num;
    }
  }
  return max(num, N - num);
}

int main() {
  int N, K;
  cin >> N >> K;
  int x[N], y[N];
  char c[N];
  for (int i = 0; i < N; ++i) {
    cin >> x[i] >> y[i] >> c[i];
  }

  int max_n = 0;
  for (int i = 0; i < K; ++i) {
    for (int j = 0; j < K; ++j) {
      max_n = max(max_n, check_num(N, K, i, j, x, y, c));
    }
  }

  cout << max_n << endl;

  return 0;
}

