    }
    for (int v = 1; v <= s; v++) {
        for (int u = 1; u <= s; u++) {
            imos[u][v] += imos[u-1][v];
        }
    }
    for (int u = 1; u <= s; u++) {
        for (int v = 1; v <= s; v++) {
            imos[u][v] += imos[u][v-1];
        }
    }

    int ans = 0;
    for (int u = 0; u < s; u++) {
        for (int v = 0; v < s; v++) {
