#define _overload3(_1, _2, _3, name, ...) name
#define _rep(i, n) repi(i, 0, n)
#define repi(i, a, b) for (int i = int(a); i < int(b); ++i)
#define REP(...) _overload3(__VA_ARGS__, repi, _rep, )(__VA_ARGS__)
#define ALL(obj) (obj).begin(), (obj).end()
#define ALLR(obj) (obj).rbegin(), (obj).rend()
const int MAX_N = 2001;
int r[MAX_N][MAX_N], s[MAX_N][MAX_N];

int query(int x1, int y1, int x2, int y2) {
    // return sum(x1<=x<=x2,y1<=y<=y2)
    if (x1 > x2 || y1 > y2)
        return 0;
    else
        return s[x2][y2] - s[x1 - 1][y2] - s[x2][y1 - 1] + s[x1 - 1][y1 - 1];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int N, K;
    cin >> N >> K;
    REP(i, N) {
        int x, y;
        char c;
        cin >> x >> y >> c;
        if (c == 'B')
            y += K;
        x %= 2 * K;
        y %= 2 * K;
        r[x + 1][y + 1]++;
    }
    // 2次元累積和
    REP(x, 1, 2 * K + 2)
    REP(y, 1, 2 * K + 2)
    s[x][y] = r[x][y] + s[x - 1][y] + s[x][y - 1] - s[x - 1][y - 1];

    int ans = 0;
    REP(x, 1, K + 1) REP(y, 1, K + 1) {
        int temp = query(x, y, x + K - 1, y + K - 1) +
                   query(x + K, y + K, 2 * K, 2 * K) +
                   query(1, 1, x - 1, y - 1) + query(x + K, 1, 2 * K, y - 1) +
                   query(1, y + K, x - 1, 2 * K);
        ans = max(ans, max(temp, N - temp));
    }
    cout << ans << endl;

    return 0;
}

