    for(int j = 1; j < 2 * K; j++){
      sum_b[i][j] = sum_b[i-1][j] + sum_b[i][j-1] - sum_b[i-1][j-1] + dist_b[i][j];
      sum_w[i][j] = sum_w[i-1][j] + sum_w[i][j-1] - sum_w[i-1][j-1] + dist_w[i][j];      
    }
  }



  // for debug
  // for(int i = 0; i < 2 *K; i++){
  //   for(int j = 0; j < 2 *K; j++){
