    rsw.build();
    int ans = -INF;
    for (int y = 0; y < k; y++) {
        for (int x = 0; x < k; x++) {
            ans = max(ans, cntw + rsb.get(0, 0, y, x) +
                               rsb.get(y, x, y + k, x + k) +
                               rsb.get(y + k, x + k, 2 * k, 2 * k) +
                               rsb.get(y + k, 0, 2 * k, x) +
