using namespace std;

int main(){
    long N, K;
    cin >> N >> K;
    long x[N], y[N];
    for(long i=0; i<N; i++){
        char c;
        cin >> x[i] >> y[i] >> c;
        if(c == 'W'){
            x[i] += K;
        }
    }
    long pos[3 * K][3 * K];
    for(long i=0; i<3 * K; i++){
        for(long j=0; j<3 * K; j++) pos[i][j] = 0;
    }
    for(long i=0; i<N; i++){
        pos[x[i] % (2*K)][y[i] % (2*K)]++;
        if(x[i] % (2 * K) < K) pos[x[i] % (2*K) + 2 * K][y[i] % (2*K)]++;
        if(y[i] % (2 * K) < K) pos[x[i] % (2*K)][y[i] % (2*K) + 2 * K]++;
        if(x[i] % (2 * K) < K && y[i] % (2 * K) < K) pos[x[i] % (2*K) + 2 * K][y[i] % (2*K) + 2 * K]++;
    }

    long dp[3 * K][3 * K];
    for(long i=0; i<3 * K; i++){
        for(long j=0; j<3 * K; j++){
            if(i == 0){
                if(j == 0) dp[i][j] = pos[i][j];
                else dp[i][j] = dp[i][j-1] + pos[i][j];
            }
            else{
                if(j == 0) dp[i][j] = dp[i-1][j] + pos[i][j];
                else dp[i][j] = dp[i-1][j] + dp[i][j-1] - dp[i-1][j-1] + pos[i][j];
            }
        }
    }

    long ans = 0;
    long inv = 200000;
    for(long i=K-1; i<2 * K; i++){
        for(long j=K-1; j<2 * K; j++){
            long temp = 2 * dp[i][j] + dp[i + K][j + K] - dp[i][j + K] - dp[i + K][j];
            if(j != K-1) temp -= dp[i][j - K];
            if(i != K-1) temp -= dp[i - K][j];
            if(i != K-1 && j != K-1) temp += dp[i-K][j-K];
            ans = max(ans, temp);
            inv = min(inv, N - temp);
        }
    }
    ans = max(ans, N - inv) ;
    cout << ans << endl;
    return 0;
}

