template<class T> inline bool chmin(T &a,const T &b){if(a>b){a=b; return 1;} return 0;}

class cumsum2{
private:
  ll m,n;
  vector<vector<ll>> S;
public:
  cumsum2(ll m,ll n):m(m),n(n),S(m+1,vector<ll>(n+1)){};
  void add(ll i,ll j,ll w){ S[i+1][j+1]+=w;};
  void cumulate(){ rep(i,m)rep(j,n) S[i+1][j+1]+=S[i][j+1]+S[i+1][j]-S[i][j];};
  ll sum(ll i0,ll j0,ll i1,ll j1){return S[i1][j1]-S[i0][j1]-S[i1][j0]+S[i0][j0];};
};

void solve(){
  ll n,k; cin>>n>>k;
  cumsum2 white(2*k,2*k), black(2*k,2*k);
  rep(_,n){
    ll x,y;
    char c;
    cin>>x>>y>>c;
    x%=2*k; y%=2*k;
    if(c=='W') white.add(x,y,1);
    else black.add(x,y,1);
  }
  white.cumulate();
  black.cumulate();

  ll ans=0;
  rep(i,k)rep(j,k){
    // white
    ll score=0;
    score+=white.sum(i+k,j+k,2*k,2*k);
    score+=white.sum(0,j+k,i,2*k);
    score+=white.sum(i,j,i+k,j+k);
    score+=white.sum(0,0,i,j);
    score+=white.sum(i+k,0,2*k,j);
    score+=black.sum(i,j+k,i+k,2*k);
    score+=black.sum(0,j,i,j+k);
    score+=black.sum(i+k,j,2*k,j+k);
    score+=black.sum(i,0,i+k,j);
    chmax(ans,score);
    // black
    score=0;
    score+=black.sum(i+k,j+k,2*k,2*k);
    score+=black.sum(0,j+k,i,2*k);
    score+=black.sum(i,j,i+k,j+k);
    score+=black.sum(0,0,i,j);
    score+=black.sum(i+k,0,2*k,j);
    score+=white.sum(i,j+k,i+k,2*k);
    score+=white.sum(0,j,i,j+k);
    score+=white.sum(i+k,j,2*k,j+k);
    score+=white.sum(i,0,i+k,j);
    chmax(ans,score);
  }
  cout<<ans<<"\n";
}

