            int Sr3 = 1;
            int Sc3 = 1;
            int Er3 = Sr1 - 1;
            int Ec3 = Sc1 - 1;
            if (Ec3 >= Sc3 && Er3 >= Sr3) {
                count_b += Sb[Er3][Ec3] - Sb[Sr3 - 1][Ec3] - Sb[Er3][Sc3 - 1] + Sb[Sr3 - 1][Sc3 - 1];
                count_w += Sw[Er3][Ec3] - Sw[Sr3 - 1][Ec3] - Sw[Er3][Sc3 - 1] + Sw[Sr3 - 1][Sc3 - 1];
            }

            int Sr4 = 1;
            int Sc4 = Sc2;
            int Er4 = Sr1 - 1;
            int Ec4 = 2 * K;
            if (Ec4 >= Sc4 && Er4 >= Sr4) {
                count_b += Sb[Er4][Ec4] - Sb[Sr4 - 1][Ec4] - Sb[Er4][Sc4 - 1] + Sb[Sr4 - 1][Sc4 - 1];
                count_w += Sw[Er4][Ec4] - Sw[Sr4 - 1][Ec4] - Sw[Er4][Sc4 - 1] + Sw[Sr4 - 1][Sc4 - 1];
            }

            int Sr5 = Sr2;
            int Sc5 = 1;
            int Er5 = 2 * K;
            int Ec5 = Sc1 - 1;
            if (Ec5 >= Sc5 && Er5 >= Sr5) {
                count_b += Sb[Er5][Ec5] - Sb[Sr5 - 1][Ec5] - Sb[Er5][Sc5 - 1] + Sb[Sr5 - 1][Sc5 - 1];
                count_w += Sw[Er5][Ec5] - Sw[Sr5 - 1][Ec5] - Sw[Er5][Sc5 - 1] + Sw[Sr5 - 1][Sc5 - 1];
            }

            ll score = count_b + (white_num - count_w);
            max_score = max(max_score, score);
        }
    }
    cout << max_score << endl;
    return 0;
}

