int maxAvailable(vector<ll>& X, vector<ll>& Y, vector<char>& C, int N, int K, int type) {
  vector<vector<int> > B(2*K+1, vector<int>(2*K+1));
  rep(i, N) {
    ll x = X[i], y = Y[i];
    char c = C[i];
    if(c == 'W') {
      if(type == 0) {
        x = (x + K) % (2 * K);
        y = y % (2 * K);
      } else {
        x = x % (2 * K);
        y = (y + K) % (2 * K);
      }
    } else {
      x = x % (2 * K);
      y = y % (2 * K);
    }
    if(x >= K) {
      if(y >= K) {
        B[x-K+1][y-K+1]++;
        B[x+1][y+1]++;
        B[x+1][y-K+1]--;
        B[x-K+1][y+1]--;
      } else {
        B[x-K+1][0]++;
        B[x+1][y+1]++;
        B[x+1][0]--;
        B[x-K+1][y+1]--;

        B[x-K+1][y+K+1]++;
        B[x+1][y+K+1]--;
      }
    } else {
      if(y > K) {
        B[0][y-K+1]++;
        B[x+1][y+1]++;
        B[x+1][y-K+1]--;
        B[0][y+1]--;

        B[x+K+1][y-K+1]++;
        B[x+K+1][y+1]--;
      } else {
        B[0][0]++;
        B[x+1][y+1]++;
        B[x+1][0]--;
        B[0][y+1]--;

        B[0][y+K+1]++;
        B[x+1][y+K+1]--;

        B[x+K+1][0]++;
        B[x+K+1][y+1]--;

        B[x+K+1][y+K+1]++;
      }
    }
  }
  rep(i, 2*K) rep(j, 2*K) if(j != 0) B[i][j] += B[i][j-1];
  rep(j, 2*K) rep(i, 2*K) if(i != 0) B[i][j] += B[i-1][j];
  int ans = 0;
  rep(i, 2*K) rep(j, 2*K) ans = max(ans, B[i][j]);
  // rep(i, 2*K) {
  //   rep(j, 2*K) {
  //     cout << B[i][j] << ' ';
  //     ans = max(ans, B[i][j]);
  //   }
  //   cout << endl;
  // }
  return ans;
}

