  memset(wcnt, 0, sizeof(wcnt));
  memset(bcnt, 0, sizeof(bcnt));
  for (int i=0;i<N;++i){
    wcnt[x[i]][y[i]]+=c[i];
    bcnt[x[i]][y[i]]+=1-c[i];
  }


  int rwcum[K][K+1];
  int rbcum[K][K+1];
  memset(rwcum, 0, sizeof(rwcum));
  memset(rbcum, 0, sizeof(rbcum));

  for (int i=0;i<K;++i){
    for (int j=0;j<K;++j){
      rwcum[i][j+1]=rwcum[i][j]+wcnt[i][j];
      rbcum[i][j+1]=rbcum[i][j]+bcnt[i][j];
    }
  }

  int wcum[K+1][K+1];
  int bcum[K+1][K+1];
  memset(wcum, 0, sizeof(wcum));
  memset(bcum, 0, sizeof(bcum));

  for (int i=0;i<K;++i){
    for (int j=1;j<=K;++j){
      wcum[i+1][j]=wcum[i][j]+rwcum[i][j];
      bcum[i+1][j]=bcum[i][j]+rbcum[i][j];
    }
  }



  int best_score=0;
  for (int i=1;i<=K;++i){
