      int ul=bcum[K][j-1]-bcum[i-1][j-1];
      int lr=bcum[i-1][K]-bcum[i-1][j-1];
      int lol=wcum[i-1][j-1];
      best_score=max(best_score, ur+ul+lr+lol);
      ur=bcum[K][K]-bcum[K][j-1]-bcum[i-1][K]+bcum[i-1][j-1];
      ul=wcum[K][j-1]-wcum[i-1][j-1];
      lr=wcum[i-1][K]-wcum[i-1][j-1];
      lol=bcum[i-1][j-1];
      best_score=max(best_score, ur+ul+lr+lol);
    }
  }
  cout << best_score << endl;
  return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

typedef vector<int> vi;
int N, K;
vi X, Y;
vector<vi> C;

void input_data(void) {
	cin >> N >> K;
	X.resize(N);
	Y.resize(N);
	C.resize(2 * K + 1, vi(2 * K + 1, 0));
	for (int i = 0; i < N; ++i) {
		int x, y; char c;
		cin >> x >> y >> c;
		X[i] = (c == 'B') ? x : x + K;
		Y[i] = y;
		++C[(Y[i] % (2 * K)) + 1][(X[i] % (2 * K)) + 1];
	}
}

int solve(void) {
	for (int j = 1; j <= 2 * K; ++j) {
		for (int i = 1; i <= 2 * K; ++i)
			C[j][i] += C[j][i - 1];
	}
	for (int i = 1; i <= 2 * K; ++i) {
		for (int j = 1; j <= 2 * K; ++j)
			C[j][i] += C[j - 1][i];
	}
	int max_cnt1 = -1;
	int max_cnt2 = -1;
	for (int y = 1; y <= K; ++y) {
		for (int x = 1; x <= K; ++x) {
			int s1 = C[y + K][x] - C[y][x];
			int s2 = C[2 * K][x + K] - C[y + K][x + K] - (C[2 * K][x] - C[y + K][x]);
			int s3 = C[y][x + K] - C[y][x];
			int s4 = C[y + K][2 * K] - C[y + K][x + K] - (C[y][2 * K] - C[y][x + K]);
			int cnt1 = s1 + s2 + s3 + s4;
			int cnt2 = N - cnt1;
			max_cnt1 = max(cnt1, max_cnt1);
			max_cnt2 = max(cnt2, max_cnt2);
		}
	}
	return max(max_cnt1, max_cnt2);
}

int main(void) {
	cin.tie(0);
	ios::sync_with_stdio(false);

	input_data();
	int ans = solve();

	cout << ans << '\n';
	return 0;
}

