using namespace std;

int N,K;
int s[4002][4002];
int w[4002][4002];

int calc(int x,int y){
	return w[x][y]-w[x-K][y]-w[x][y+K]+w[x-K][y+K];
}

int main(){
	cin >> N >> K;

	FOR(i,N){
		int x,y;
		char c;
		cin >> x >> y >> c;

		if(c=='W') s[(x+K)%(2*K)+K][y%(2*K)+K]+=1;
		else s[x%(2*K)+K][y%(2*K)+K]+=1; 
	}


	FOR(y,4*K) FOR(x,4*K){
		if(x==0) w[x][y]=s[x][y];
		else	  w[x][y]=w[x-1][y]+s[x][y];
	}

	FOR(x,4*K) FORR(y,4*K-1){
		if(y==4*K-1) w[x][y]=w[x][y];
		else	     w[x][y]=w[x][y+1]+w[x][y];
	}


	int ans=0;
	int tmp=0;

	for(int y=K; y<2*K; y++){
		for(int x=2*K; x<3*K; x++){
			tmp=calc(x,y)+calc(x-K,y-K)+calc(x+K,y-K)+calc(x+K,y+K)+calc(x-K,y+K);
			ans=max( ans, max(N-tmp,tmp) );
		}
	}

	cout << ans <<  endl;
	return 0;
}

