vector<vector<int>> li, li2;

int main(){
	cin >> n >> k;
	li.resize(4 * k + 1, vector<int>(4 * k + 1));
	li2.resize(4 * k + 1, vector<int>(4 * k + 1));
	for(int i = 0; i < n; i++){
		int a, b; char c; cin >> a >> b >> c;

		if(c == 'W') li[a % (2 * k)][b % (2 * k)]++;
		else if(c == 'B') li2[a % (2 * k)][b % (2 * k)]++;
	}

	for(int i = 0; i < 2 * k; i++){
		for(int j = 0; j < 2 * k; j++){
			li[i + 2 * k][j] += li[i][j];
			li[i][j + 2 * k] += li[i][j];
			li[i + 2 * k][j + 2 * k] += li[i][j];

			li2[i + 2 * k][j] += li2[i][j];
			li2[i][j + 2 * k] += li2[i][j];
			li2[i + 2 * k][j + 2 * k] += li2[i][j];
		}
	}

	for(int i = 0; i < 4 * k; i++){
		for(int j = 0; j < 4 * k; j++){
			li[i + 1][j + 1] += li[i + 1][j] + li[i][j + 1] - li[i][j];
			li2[i + 1][j + 1] += li2[i + 1][j] + li2[i][j + 1] - li2[i][j];
		}
	}

	int ma = 0;
	for(int K = 0; K < 2; K++){
		for(int i = 0; i < k; i++){
			for(int j = 0; j < k; j++){
				int A = li[i + k][j + k] - li[i + k][j] - li[i][j + k] + li[i][j];
				int B = li[i + 2 * k][j + 2 * k] - li[i + 2 * k][j + k] - li[i + k][j + 2 * k] + li[i + k][j + k];
				int C = li2[i + 2 * k][j + k] - li2[i + 2 * k][j] - li2[i + k][j + k] + li2[i + k][j];
				int D = li2[i + k][j + 2 * k] - li2[i][j + 2 * k] - li2[i + k][j + k] + li2[i][j + k];

				ma = max(ma, A + B + C + D);
			}
		}

		swap(li, li2);
	}

	cout << ma << endl;
	return 0;
}

