// (x, y)を左上に持つ1辺Kの正方形内の値の和
int sum(int (&a)[4010][4010], int y, int x){
    x += K - 1;
    int x2 = x - K, y2 = y - K;
    // if(x2 < 0 || y2 < 0){
    //     std::cout << x << ", " << y << ", " << x2 << ", " << y2 << std::endl;
    // }
    return a[y][x] - (x2 > 0 ? a[y][x2] : 0) - (y2 > 0 ? a[y2][x] : 0) + (x2 > 0 && y2 > 0 ? a[y2][x2] : 0);
}

int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    std::cin >> N >> K;
    int L = 2 * K;

    for(int i=0;i<N;++i){
        int x, y;
        char c;
        std::cin >> x >> y >> c;

        if(c == 'W'){
            ++w[y % L][x % L];
            ++w[y % L + L][x % L + L];
        }else{
            ++b[y % L][x % L];
            ++b[y % L + L][x % L + L];
        }
    }

    for(int i=0;i<2*L;++i){
        for(int j=0;j+1<2*L;++j){
            w[i][j+1] += w[i][j];
            b[i][j+1] += b[i][j];
        }
    }

    for(int j=0;j<2*L;++j){
        for(int i=0;i+1<2*L;++i){
            w[i+1][j] += w[i][j];
            b[i+1][j] += b[i][j];
        }
    }

    int res = 0;
    for(int i=K-1;i<L+K;++i){
        for(int j=0;j<L+K;++j){
            int x = sum(b, i, j) + sum(b, i+K, j+K) + sum(w, i+K, j) + sum(w, i, j+K);
            res = max(res, x);
        }
    }

    std::cout << res << std::endl;
}

