int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	ll n, k;
	cin >> n >> k;
	vector<ll> x(n), y(n);
	vector<char> c(n);
	rep(i, n) {
		cin >> x[i] >> y[i] >> c[i];
	}

	// マス(i,j)とマス(i + k,j)の色は異なる
	// マス(i,j)とマス(i j + k)の色も異なる
	// すべて左端に寄せる

	int sum = 0;

	vector<vector<ll>> wNum(2 * k + 1, vector<ll>(2 * k + 1, 0));
	int black = 0;

	rep(i, n) {
		if (x[i] >= 2 * k) {
			x[i] %= 2 * k;
		}
		if (y[i] >= 2 * k) {
			y[i] %= 2 * k;
		}
		if (c[i] == 'B') {
			wNum[x[i] + 1][y[i] + 1]--;
			sum--;
			black++;
		}
		else {
			wNum[x[i] + 1][y[i] + 1]++;
			sum++;
		}
	}

	Rep(i, 1, 2 * k + 1) {
		Rep(j, 1, 2 * k + 1) {
			wNum[i][j] += wNum[i][j - 1];
		}
	}

	Rep(i, 1, 2 * k + 1) {
		Rep(j, 1, 2 * k + 1) {
			wNum[i][j] += wNum[i - 1][j];
		}
	}

	int ans = 0;

	rep(i, k + 1) {
		rep(j, k + 1) {
			int tmp = 0;
			int a = wNum[i][j];
			int b = wNum[i + k][j + k] - wNum[i + k][j] - wNum[i][j + k] + a;
			int c = wNum[i][2 * k] - wNum[i][j + k];
			int d = wNum[2 * k][j] - wNum[i + k][j];
			int e = wNum[2 * k][2 * k] - wNum[2 * k][j + k]
				- wNum[i + k][2 * k] + wNum[i + k][j + k];
			tmp = a + b + c + d + e;
			ans = max(ans, black + sum - tmp);
		}
	}

	cout << ans << endl;
	return 0;
}

