        temp += dsum[i+k-1][j+k-1] - dsum[i-1][j+k-1];
      }else{
        temp += dsum[i+k-1][j+k-1] - dsum[i+k-1][j-1] - dsum[i-1][j+k-1] + dsum[i-1][j-1];
      }
      if(i != 0 && j!= 0){
        temp += dsum[i-1][j-1];
      }
      if(i != 0){
        temp += dsum[i-1][2*k-1] - dsum[i-1][j+k-1];
      }
      if(j != 0){
        temp += dsum[2*k-1][j-1] - dsum[i+k-1][j-1];
      }
      temp += dsum[2*k-1][2*k-1] - dsum[i+k-1][2*k-1] - dsum[2*k-1][j+k-1] + dsum[i+k-1][j+k-1];

      ans = max(temp, n-temp);
    }
  }
  cout<<ans<<endl;
  return 0;
}

