	vector<vector<int>> wboard(2 * k + 1, vector<int>(2 * k + 1, 0));
	for (int i = 0; i < n; ++i) {
		int x, y;
		char c;
		cin >> x >> y >> c;
		if (c == 'B')bboard[x % (2 * k)][y % (2 * k)]++;
		if (c == 'W')wboard[x % (2 * k)][y % (2 * k)]++;
	}
	for (int i = 0; i <= 2 * k; ++i) for (int j = 1; j <= 2 * k; ++j) bboard[j][i] += bboard[j - 1][i], wboard[j][i] += wboard[j - 1][i];
	for (int i = 0; i <= 2 * k; ++i) for (int j = 1; j <= 2 * k; ++j) bboard[i][j] += bboard[i][j - 1], wboard[i][j] += wboard[i][j - 1];
	auto f = [](vector<vector<int>> & board, int x1, int y1, int x2, int y2) {
		return board[x2][y2] - (x1 ? board[x1 - 1][y2] : 0) - (y1 ? board[x2][y1 - 1] : 0) + (x1 && y1 ? board[x1 - 1][y1 - 1] : 0);
	};
	for (int x = 0; x < k; ++x)for (int y = 0; y < k; ++y) {
		int cnt = 0;
		cnt += f(bboard, x, y, x + k - 1, y + k - 1);
		cnt += f(bboard, x + k, y + k, 2 * k - 1, 2 * k - 1);
		cnt += (x && y ? f(bboard, 0, 0, x - 1, y - 1) : 0);
		cnt += (x ? f(bboard, 0, y + k, x - 1, 2 * k - 1) : 0);
		cnt += (y ? f(bboard, x + k, 0, 2 * k, y - 1) : 0);

		cnt += (y ? f(wboard, x, 0, x + k - 1, y - 1) : 0);
		cnt += (x ? f(wboard, 0, y, x - 1, y + k - 1) : 0);
		cnt += f(wboard, x, y + k, x + k - 1, 2 * k - 1);
		cnt += f(wboard, x + k, y, 2 * k - 1, y + k - 1);
		res = max(res, max(abs(cnt), n - abs(cnt)));
	}
	cout << res;
};

