template<class T> using V = vector<T>;
template<class T> using V2 = vector<vector<T>>;
template<class T, int W=255> using A = array<T, W>;
template<class T, int W=255, int H=255> using A2 = array<array<T, W>, W>;

template<typename T = int>
struct S2D {
    const int w, h;
    V<V<T>> f;

    S2D(int w, int h, T z) : f(h+1, V<T>(w+1,z)), w(w+1), h(h+1) {}

    void build() {
        for(int i = 1; i < h; i++) {
            for(int j = 1; j < w; j++) {
                f[i][j] = f[i][j] + f[i][j-1] + f[i-1][j] - f[i-1][j-1];
            }
        }
    }

    void add(int x, int y, T val) {
        x++; y++;
        if(x >= w || h <= y) return ;
        f[y][x] += val;
    }

    T query(int lx, int ly, int rx, int ry) {
        return f[ry][rx] - f[ly][rx] - f[ry][lx] + f[ly][lx];
    }
};

int N, K;

int main(){
    INIT;
    cin >> N >> K;
    S2D<LL> s2d(2*K+1,2*K+1,0);

    REP(i,N) {
        LL x, y; char c;
        cin >> x >> y >> c;
        if(c == 'W') s2d.add((x+K)%(2*K), (y)%(2*K), 1);
        else s2d.add(x%(2*K), y%(2*K), 1);
    }

    int ans = 0;
    REP(i,2*K+1) {
        FOR(j,0,2*K+1) {
            int rx = (2*K <= i+K ? 2*K : i+K);
            int ry = (2*K <= j+K ? 2*K : j+K);
            int cnt = s2d.query(i,j,rx,ry);
            cnt += s2d.query(0,0,i,j);
            cnt += s2d.query(rx,0,2*K+1,j);
            cnt += s2d.query(0,ry,i,2*K+1);
            cnt += s2d.query(rx,ry,2*K+1,2*K+1);
            ans = std::max(ans, cnt);
        }
    }
    cout << ans;
}

