bool inside(int x, int y){
  return (1 <= x && x <= 2 * k) && (1 <= y && y <= 2 * k);
}

ll rangeSum(int x, int y, int u, int v){
  if(x > u || y > v || !inside(x, y) || !inside(u, v))
    return 0;

  return psum[u][v] - psum[x - 1][v] - psum[u][y - 1] + psum[x - 1][y - 1];
}

