template<int VW, int VH> struct add2D {
	int v[VH][VW];
	void set(int x,int y,int c){v[y][x]=c;}
	void build(){
	int i,j;
	for(i=0;i<VH;i++){
		for(j=0;j<VW;j++){
			if(i>0){v[i][j]+=v[i-1][j];}
			if(j>0){v[i][j]+=v[i][j-1];}
			if(i>0&&j>0){v[i][j]-=v[i-1][j-1];}
		}
	}
	}
	int get(int sx,int sy,int tx,int ty){
	int ret=v[ty][tx];
	if(sy>0){ret-=v[sy-1][tx];}
	if(sx>0){ret-=v[ty][sx-1];}
	if(sy>0&&sx>0){ret+=v[sy-1][sx-1];}
	return ret;
	}
};

add2D<4005,4005>BR,WR;

int main() {

	int N,K;

	cin>>N>>K;

	int i,j;

	for(i=0;i<N;i++){
