#include <iostream>

class Check {
    uint32_t ** m;
    int k;
    std::string c;
public:
    Check(int k, const std::string &c) {
        this->c = c;
        this->k = k;
        this->m = new uint32_t *[k+1];
        for (int i = 0; i < this->k + 1; ++i) {
            this->m[i] = new uint32_t[k + 1]();
        }
    }

    void inc(int xMin, int xMax, int yMin, int yMax) {
        for (int i = xMin; i < xMax; ++i) {
            for (int j = yMin; j < yMax; ++j) {
                this->m[i][j]++;
            }
        }
    }

    void addDesire(int x, int y, const std::string &c) {
        int cx = x + 1;
        int cy = y + 1;

        if (c == this->c) {
            this->inc(0, cx, 0, cy);
            this->inc(cx, this->k+1, cy, this->k+1);
        } else {
            this->inc(0, cx, cy, this->k+1);
            this->inc(cx, this->k+1, 0, cy);
        }
    }

    int getMax() {
        uint32_t _max = 0;
        for (int i = 0; i < this->k + 1; ++i) {
            for (int j = 0; j < this->k + 1; ++j) {
                if (this->m[i][j] > _max){
                    _max = this->m[i][j];
                }
            }
        }

        return _max;
    }

    ~Check() {
        for (int i = 0; i < this->k+1; ++i) {
            delete[](this->m[i]);
        }
        delete[](this->m);
    }
};

int main() {
    uint32_t n, k;
    std::cin >> n >> k;
    Check checkW = Check(k, "W");

    for (int i = 0; i < n; ++i) {
        uint32_t x, y;
        std::string c;
        std::cin >> x >> y >> c;

        x = x < 0 ? -1*x+k-1 : x;
        y = y < 0 ? -1*y+k-1 : y;

        uint32_t bigX = x/k;
        uint32_t bigY = y/k;

        uint32_t localX = x%k;
        uint32_t localY = y%k;
        std::string localC = c;

        if ((bigX+bigY)% 2 != 0) {
            localC = localC == "W" ? "B" : "W";
        }

        checkW.addDesire(localX, localY, localC);
    }

    std::cout << checkW.getMax() << std::endl;

    return 0;
}

