int n, k;
int cnt[1000][2000][2];
int dp[1000][2000];
int sum[1000][2000];

int main() {
    scanf("%d %d", &n, &k);
    for (int i = 0; i < n; i++) {
        int x, y;
        char c;
        scanf("%d %d %c", &x, &y, &c);
        int a = x % (2 * k);
        int b = y % (2 * k);
        if (a < k) cnt[a][b][c == 'W']++;
        else if (b < k) cnt[a - k][b + k][c == 'W']++;
        else cnt[a - k][b - k][c == 'W']++;
    }

    for (int i = 0; i < k; i++) {
        for (int j = 0; j < k; j++) {
            dp[i][0] += cnt[i][j][1];
        }
        for (int j = k; j < 2 * k; j++) {
            dp[i][0] += cnt[i][j][0];
        }
    }

    for (int i = 0; i < k; i++) {
        for (int j = 1; j < 2 * k; j++) {
            dp[i][j] = dp[i][j - 1] - cnt[i][j - 1][1]
                     + cnt[i][j - 1][0]
                     + cnt[i][(j + k - 1) % (2 * k)][1]
                     - cnt[i][(j + k - 1) % (2 * k)][0];
        }
    }

    int ans = 0;
    for (int j = 0; j < 2 *k; j++) {
        for (int i = 0; i < k; i++) {
            sum[0][j] += dp[i][j];
        }
        ans = (ans < sum[0][j]) ? sum[0][j] : ans;
    }
    for (int i = 1; i < k; i++) {
        for (int j = 0; j < 2 * k; j++) {
            sum[i][j] = sum[i - 1][j] - dp[i - 1][j]
                      + dp[i - 1][(j + k) % (2 * k)];
            ans = (ans < sum[i][j]) ? sum[i][j] : ans;
        }
    }

    printf("%d\n", ans);
    return 0;
}

