int N, K;
int acc[2010][2010];


void makeAcc(){
	rep(i, 0, 2*K)
		rep(j, 1, 2*K) acc[i][j] += acc[i][j-1];
	rep(i, 1, 2*K)
		rep(j, 0, 2*K) acc[i][j] += acc[i-1][j];
}


int Acc(int y1, int x1, int y2, int x2){
	if(y1 > y2 || x1 > x2) return 0;
	if(y1 == 0 && x1 == 0) return acc[y2][x2];
	if(y1 == 0) return acc[y2][x2]-acc[y2][x1-1];
	if(x1 == 0) return acc[y2][x2]-acc[y1-1][x2];
	return acc[y2][x2]-acc[y1-1][x2]-acc[y2][x1-1]+acc[y1-1][x1-1];
}


int solve(){
	int ans = 0;
	rep(i, 0, 2*K){
		rep(j, 0, 2*K){
			int cnt = 0;
			int y1 = i;
			int x1 = j;
			int y2 = min(i+K-1, 2*K-1);
			int x2 = min(j+K-1, 2*K-1);
			cnt += Acc(y1, x1, y2, x2);
			y1 = 0;
			x1 = 0;
			y2 = i-1;
			x2 = j-1;
			cnt += Acc(y1, x1, y2, x2);
			y1 = 0;
			x1 = j+K;
			y2 = i-1;
			x2 = 2*K-1;
			cnt += Acc(y1, x1, y2, x2);
			y1 = i+K;
			x1 = 0;
			y2 = 2*K-1;
			x2 = j-1;
			cnt += Acc(y1, x1, y2, x2);
			y1 = i+K;
			x1 = j+K;
			y2 = 2*K-1;
			x2 = 2*K-1;
			cnt += Acc(y1, x1, y2, x2);
			ans = max(ans, cnt);
			if(ans == N) return ans;
		}
	}
	return ans;
}


signed main(){
