	vector<char> c(N);
	for (int i = 0; i < N; i++) {
		cin >> x[i] >> y[i] >> c[i];
	}

	ll size = 3 * K;
	vector<vector<ll>> tile(size, vector<ll>(size, 0));
	for (int i = 0; i < N; i++) {
		ll xx = x[i], yy = y[i];
		if (c[i] == 'W') xx += K;

		xx %= (2 * K);
		yy %= (2 * K);

		tile[xx][yy]++;
		tile[xx + K][yy]--;
		tile[xx][yy + K]--;
		tile[xx + K][yy + K]++;

		if (xx < K) xx += K;
		else xx -= K;

		if (yy < K) yy += K;
		else yy -= K;

		tile[xx][yy]++;
		tile[xx + K][yy]--;
		tile[xx][yy + K]--;
		tile[xx + K][yy + K]++;
	}

	for (int i = 0; i < size; i++) {
		for (int j = 1; j < size; j++) {
			tile[i][j] += tile[i][j - 1];
		}
	}
	for (int j = 0; j < size; j++) {
		for (int i = 1; i < size; i++) {
			tile[i][j] += tile[i - 1][j];
		}
	}

	for (int i = 0; i < size; i++) {
		for (int j = 0; j < size; j++) {
			if ((i >= 2 * K) || (j >= 2 * K)) {
				ll xx = i % (2 * K);
				ll yy = j % (2 * K);

				tile[xx][yy] += tile[i][j];
			}
		}
	}

	ll res = 0;
	for (int i = 0; i < 2 * K; i++) {
		for (int j = 0; j < 2 * K; j++) {
			res = max(res, tile[i][j]);
		}
	}

	cout << res << endl;
	return 0;
}

