    b[x0][y0]++;
    if(x0 < K && y0 < K){
        b[x0 + K][y0]--;
        b[x0][y0 + K]--;
        b[x0 + K][y0 + K]++;
    }
    if(x0 >= K && y0 < K){
        b[x0][y0 + K]--;
        b[0][y0]++;
        b[0][y0 + K]--;
        b[x0 - K][y0]--;
        b[x0 - K][y0 + K]++;
    }
    if(x0 < K && y0 >= K){
        b[x0 + K][y0]--;
        b[x0][0]++;
        b[x0 + K][0]--;
        b[x0][y0 - K]--;
        b[x0 + K][y0 - K]++;
