int k;

bool inside(int p) {
    return 0 <= p && p < 2 * k;
}

int calc_sum(int y1, int x1, int y2, int x2, const vector<vector<int>> &grid) {
    if (inside(y1) && inside(x1) && inside(y2) && inside(x2)) {
        int ret = grid[y2][x2];
        if (y1 > 0)
            ret -= grid[y1 - 1][x2];
        if (x1 > 0)
            ret -= grid[y2][x1 - 1];
        if (y1 > 0 && x1 > 0)
            ret += grid[y1 - 1][x1 - 1];
        return ret;
    } else
        return 0;
}

int request_num(const vector<vector<int>> &grid, int y, int x) {
    int ret = calc_sum(y, x, min(y + k - 1, 2 * k - 1), min(x + k - 1, 2 * k - 1), grid);
    return ret + calc_sum(0, 0, y - 1, x - 1, grid) + calc_sum(y + k, x + k, 2 * k - 1, 2 * k - 1, grid) + calc_sum(0, x + k, y - 1, 2 * k - 1, grid) + calc_sum(y + k, 0, 2 * k - 1, x - 1, grid);
}

