int n, m;
#define int ll
ll bp(ll d, ll st) {
    if (st == 0) return 1;
    if (st == 1) return d;
    ll gg = bp(d, st / 2);
    if (st & 1) return gg * gg % mod * d % mod;
    return gg * gg % mod;
}

void solve() {
    cin >> n >> m;
    ll ans = 0;
    vector<vector<ll>> a(n + 1), b(n + 1);
    for (int i = 0; i <= n; ++i) {
        a[i].resize(m + 1);
        b[i].resize(m + 1);
    }
    for (int i =1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            cin >> a[i][j];
        }
    }
    for (int i = 1; i <= n; ++i) {
        vector<ll> hsh(m + 1, 0), rhsh(m + 2, 0);
        for (int j = 1; j <= m; ++j) {
            hsh[j] = (hsh[j - 1] + bp(p, a[i][j] + 1) * pw[j] % mod) % mod;
        }
        for (int j = m; j >= 1; --j) {
            rhsh[j] = (rhsh[j + 1] + bp(p, a[i][j] + 1) * pw[m - j] % mod) % mod;
        }
        for (int j = 1; j <= m; ++j) {
            int lef = 0, rig = min(j, m - j + 1);
            while (rig - lef > 1) {
                int mid = (lef + rig) / 2;
                int lef1 = j - mid;
                int rig2 = j + mid;
                ll hsh1 = (hsh[j - 1] - hsh[lef1 - 1] + mod) % mod;
                ll hsh2 = (rhsh[j + 1] - rhsh[rig2 + 1] + mod) % mod;
                //cout << mid << ' ' << lef1 << ' ' << rig2 << ' ' << hsh1 << ' ' << hsh2 << '\n';
                hsh1 *= pw[m - rig2];
                hsh2 *= pw[lef1];
                hsh1 %= mod;
                hsh2 %= mod;
                //cout << mid << ' ' << lef1 << ' ' << rig2 << ' ' << hsh1 << ' ' << hsh2 << '\n';
                if (hsh1 == hsh2) {
                    lef = mid;
                } else {
                    rig = mid;
                }
            }
            //if (i == 1 && j == 2) {
            //    return;
            //}
            b[i][j] = lef + 1;
            //cout << i << ' ' << j << ' ' << lef + 1 << '\n';
        }
    }
    for (int i = 1; i <= m; ++i) {
        vector<ll> hsh(n + 1, 0), rhsh(n + 2, 0);
        for (int j = 1; j <= n; ++j) {
            hsh[j] = (hsh[j - 1] + bp(p, a[j][i] + 1) * pw[j] % mod) % mod;
        }
        for (int j = n; j >= 1; --j) {
            rhsh[j] = (rhsh[j + 1] + bp(p, a[j][i] + 1) * pw[n - j] % mod) % mod;
        }
        for (int j = 1; j <= n; ++j) {
            int lef = 0, rig = min(j, n - j + 1);
            while (rig - lef > 1) {
                int mid = (lef + rig) / 2;
                int lef1 = j - mid;
                int rig2 = j + mid;
                ll hsh1 = (hsh[j - 1] - hsh[lef1 - 1] + mod) % mod;
                ll hsh2 = (rhsh[j + 1] - rhsh[rig2 + 1] + mod) % mod;
                hsh1 *= pw[n - rig2];
                hsh2 *= pw[lef1];
                hsh1 %= mod;
                hsh2 %= mod;
                if (hsh1 == hsh2) {
                    lef = mid;
                } else {
                    rig = mid;
                }
            }
            //cout << i << ' ' << j << ' ' << lef + 1 << '\n';
            ans += min((ll)lef + 1, b[j][i]);
        }
    }
    cout << ans;
}

