  }

  std::vector<std::vector<int> > b0 = Imos2D(b[0]), w0 = Imos2D(w[0]), b1 = Imos2D(b[1]), w1 = Imos2D(w[1]);

  //cerr << "OK" << endl;

  for (int i = 0; i < K; ++i) {
    for (int j = 0; j < K; ++j) {
