template <typename T>
struct twodimBIT
{
// 1-indexed
// http://judge.u-aizu.ac.jp/onlinejudge/review.jsp?rid=3095512#1
// https://www.slideshare.net/hcpc_hokudai/binary-indexed-tree
private:
	vector< vector<T> > array;
	const ll n;
	const ll m;

public:
	twodimBIT(ll _n,ll _m):
		array(_n+1,vector<T>(_m+1,0)), n(_n),m(_m){}

	// (1,1) ~ (x,y) ruisekiwa
	T sum(ll x,ll y) {
		T s = 0;
		for(ll i=x;i>0;i-=i&(-i))
			for(ll j=y;j>0;j-=j&(-j))
				s += array[i][j];
		return s;
	}

	// [(x1,y1),(x2,y2)] no souwa (x1<x2,y1<y2)
	T sum(ll x1,ll y1,ll x2,ll y2){
		return sum(x2,y2) - sum(x1-1,y2) - sum(x2,y1-1) + sum(x1-1,y1-1);
	}

	void add(ll x,ll y,T k) {
		for(ll i=x;i<=n;i+=i&(-i))
			for(ll j=y;j<=m;j+=j&(-j))
				array[i][j] += k;
	}
};

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	ll N,K;
	cin >> N >> K;
	twodimBIT<ll> hope(3*K+3,3*K+3);
	FOR(i,0,N){
		ll x,y;
		char c;
		cin >> x >> y >> c;
		if(c=='W')y+=K;
		x %= 2*K;
		y %= 2*K;
		if(x<0)x += 2*K;
		if(y<0)y += 2*K;
		hope.add(x+1,y+1,1ll);
	}
	ll ans = 0;
	FOR(i,1,K+2){
		FOR(j,1,K+2){
			ll t = hope.sum(i,j,i+K-1,j+K-1);
			t += hope.sum(i+K,j+K,i+2*K-1,j+2*K-1);
			t += hope.sum(max(0ll,i-K),max(0ll,j-K),i-1,j-1);
			t += hope.sum(max(0ll,i-K),j+K,i-1,j+2*K-1);
			t += hope.sum(i+K,max(j-K,0ll),i+2*K-1,j-1);
			ans = max( ans , t );
		}
	}
	cout << ans << endl;
}

