// 正方形[i+1, i+k] * [j+1, j+k]の区間にある条件を満たすものを調べる
int calc(int i, int j, int k, vector<vi> &mp) {
  if (i >= 2 * k || j >= 2 * k)
    return 0;
  int right = min(j + k, 2 * k);
  int left = max(j, 0);

  int top = min(i + k, 2 * k);
  int bottom = max(i, 0);

  return mp[top][right] - mp[bottom][right] - mp[top][left] + mp[bottom][left];
}

int main() {
  int n, k;
  cin >> n >> k;
  vector<vi> w(2 * k + 1, vi(2 * k + 1, 0)), b(2 * k + 1, vi(2 * k + 1, 0));

  // [1,2k]の区間に全部収める
  REP(i, n) {
    int x, y;
    char c;
    cin >> x >> y >> c;
    x %= 2 * k;
    y %= 2 * k;
    x++;
    y++;
    if (c == 'W') {
      w[y][x]++;
    } else {
      b[y][x]++;
    }
  }

  // 累積和を取る.
  FOR(i, 1, 2 * k + 1) {
    FOR(j, 1, 2 * k + 1) {
      w[i][j] += w[i - 1][j] + w[i][j - 1] - w[i - 1][j - 1];
      b[i][j] += b[i - 1][j] + b[i][j - 1] - b[i - 1][j - 1];
    }
  }

  // 2k*2kのマスの内部にある正方形のうち、それぞれの左下を指定してあげることで計算する。
  int ans = 0;
  REP(i, 2 * k + 1) {
    REP(j, 2 * k + 1) {
      int white = calc(i, j, k, w) + calc(i + k, j + k, k, w) +
                  calc(i - k, j - k, k, w) + calc(i + k, j - k, k, w) +
                  calc(i - k, j + k, k, w);
      int black = calc(i + k, j, k, b) + calc(i, j + k, k, b) +
                  calc(i - k, j, k, b) + calc(i, j - k, k, b);

      ans = max(ans, white + black);
    }
  }

  REP(i, 2 * k + 1) {
    REP(j, 2 * k + 1) {
      int white = calc(i, j, k, b) + calc(i + k, j + k, k, b) +
                  calc(i - k, j - k, k, b) + calc(i + k, j - k, k, b) +
                  calc(i - k, j + k, k, b);
      int black = calc(i + k, j, k, w) + calc(i, j + k, k, w) +
                  calc(i - k, j, k, w) + calc(i, j - k, k, w);

      ans = max(ans, white + black);
    }
  }
  cout << ans << endl;
  return 0;
}

