using namespace std;

int black[2'000][2'000];
int white[2'000][2'000];

int blackSum[2'000][2'000];
int whiteSum[2'000][2'000];

int rect(int tbl[][2'000], int x, int y, int w, int h, int k)
{
    if (w == 0 || h == 0)
    {
        return 0;
    }
    int s = 0;
    s += tbl[x + w - 1][y + h - 1];
    s -= y == 0 ? 0 : tbl[x + w - 1][y - 1];
    s -= x == 0 ? 0 : tbl[x - 1][y + h - 1];
    s += x == 0 || y == 0 ? 0 : tbl[x - 1][y - 1];

    return s;
}

int rectRepeat(int tbl[][2'000], int x, int y, int w, int h, int k)
{
    int ww = min(w, 2 * k - x);
    int hh = min(h, 2 * k - y);
    int lb = rect(tbl, x, y, ww, hh, k);
    int lt = rect(tbl, x, 0, ww, h - hh, k);
    int rt = rect(tbl, 0, 0, w - ww, h - hh, k);
    int rb = rect(tbl, 0, y, w - ww, hh, k);

    return lb + lt + rt + rb;
}

int main()
{
    int n, k;
    cin >> n >> k;

    for (int i = 0; i < 2 * k; i++)
        for (int j = 0; j < 2 * k; j++)
        {
            black[i][j] = white[i][j] = 0;
        }

    for (int i = 0; i < n; i++)
    {
        int x, y;
        char c;
        cin >> x >> y >> c;
        if (c == 'W')
        {
            white[x % (2 * k)][y % (2 * k)]++;
        }
        else
        {
            black[x % (2 * k)][y % (2 * k)]++;
        }
    }

    for (int i = 0; i < 2 * k; i++)
    {
        for (int j = 0; j < 2 * k; j++)
        {
            blackSum[i][j] = 0;
            whiteSum[i][j] = 0;
            if (j != 0)
            {
                blackSum[i][j] += blackSum[i][j - 1];
                whiteSum[i][j] += whiteSum[i][j - 1];
            }
            if (i != 0)
            {
                blackSum[i][j] += blackSum[i - 1][j];
                whiteSum[i][j] += whiteSum[i - 1][j];
            }
            if (i != 0 && j != 0)
            {
                blackSum[i][j] -= blackSum[i - 1][j - 1];
                whiteSum[i][j] -= whiteSum[i - 1][j - 1];
            }
            blackSum[i][j] += black[i][j];
            whiteSum[i][j] += white[i][j];
        }
    }

    int result = 0;
    for (int i = 0; i < 2 * k; i++)
    {
        for (int j = 0; j < 2 * k; j++)
        {
            int s = 0;
            s += rectRepeat(blackSum, i, j, k, k, k);
            s += rectRepeat(blackSum, (i + k) % (2 * k), (j + k) % (2 * k), k, k, k);
            s += rectRepeat(whiteSum, (i + k) % (2 * k), j, k, k, k);
            s += rectRepeat(whiteSum, i, (j + k) % (2 * k), k, k, k);

            result = max(result, s);
        }
    }

    cout << result << endl;
    return 0;
}

