template <class T> struct CumulativeSum2D {
  int H, W;
  vector<vector<T>> data;

  CumulativeSum2D(int h, int w) : H(h + 1), W(w + 1), data(h + 1, vector<T>(w + 1, 0)) {}

  void add(int y, int x, T z) {
    ++x, ++y;
    if (y >= H || x >= W) return;
    data[y][x] += z;
  }

  void build() {
    for (int i = 1; i < H; i++)
      for (int j = 1; j < W; j++) {
        data[i][j] += data[i][j - 1] + data[i - 1][j] - data[i - 1][j - 1];
      }
  }

  // [sx, gx), [sy, gy) (Half-open section e.g. Not include gx and gy)
  T query(int sy, int sx, int gy, int gx) {
    return (data[gy][gx] - data[sy][gx] - data[gy][sx] + data[sy][sx]);
  }
};

int main(int argc, char* argv[]) {
  long long N;
  scanf("%lld", &N);
  long long K;
  scanf("%lld", &K);
  std::vector<long long> x(N);
  std::vector<long long> y(N);
  std::vector<std::string> c(N);
  for (int i = 0; i < N; i++) {
    scanf("%lld", &x[i]);
    scanf("%lld", &y[i]);
    std::cin >> c[i];
  }

  CumulativeSum2D<int> b2(K * 4, K * 4);
  CumulativeSum2D<int> w2(K * 4, K * 4);

  vector<i_i> diff{{0, 0}, {K * 2, 0}, {0, K * 2}, {K * 2, K * 2}};
  rep(i, 0, N) {
    int px = x[i] % (K * 2);
    int py = y[i] % (K * 2);
    auto& table = (c[i][0] == 'B') ? b2 : w2;

    for (i_i d : diff) {
      table.add(py + d.first, px + d.second, 1);
    }
  }

  w2.build();
  b2.build();
  ll ans = 0;
  rep(i, 0, K + 1) rep(j, 0, K + 1) {
    ll tmp = 0;
    tmp += b2.query(0 + i, 0 + j, K + i, K + j);
    tmp += b2.query(K + i, K + j, K + K + i, K + K + j);

    tmp += w2.query(K + i, 0 + j, K + K + i, K + j);
    tmp += w2.query(0 + i, K + j, K + i, K + K + j);

    chmax(ans, tmp);
  }

  put(ans);

  return 0;
}

