bool is_same_color(const int &x, const int &y, const int &x0, const int &y0, const int &K)
{
    int x_mod = (x - x0) % (2 * K);
    int y_mod = (y - y0) % (2 * K);
    if (0 <= x_mod && x_mod < K && 0 <= y_mod && y_mod < K)
    {
        return true; //same
    }
    else
    {
        return false; //not
    }
}

