int w[2000][2000];
int b[2000][2000];
int w_acc[2001][2001];
int b_acc[2001][2001];

int main() {
  int n, k;
  cin>>n>>k;

  int l = 2 * k;
  for (int i=0; i<l; i++) {
    for (int j=0; j<l; j++) {
      w[i][j] = 0;
      b[i][j] = 0;
    }
  }

  for (int i=0; i<n; i++) {
    int x, y;
    char c;
    cin>>x>>y>>c;
    if (c == 'B') {
      ++b[y % l][x % l];
    } else {
      ++w[y % l][x % l];
    }
  }

  for (int i=0; i<l+1; i++) {
    for (int j=0; j<l+1; j++) {
      w_acc[i][j] = 0;
      b_acc[i][j] = 0;
    }
  }
  for (int i=1; i<l+1; i++) {
    for (int j=1; j<l+1; j++) {
      w_acc[i][j] = w_acc[i-1][j] + w_acc[i][j-1] - w_acc[i-1][j-1] + w[i-1][j-1];
      b_acc[i][j] = b_acc[i-1][j] + b_acc[i][j-1] - b_acc[i-1][j-1] + b[i-1][j-1];
    }
  }
  int ans = 0;
  for (int i=0; i<l; i++) {
    for (int j=0; j<l; j++) {
      int score = 0;
      for (int y=-1; y<=2; y++) {
        for (int x=-1; x<=2; x++) {
          int rty = i + k * y;
          int rtx = j + k * x;
          int lby = i + k * y - k + 1;
          int lbx = j + k * x - k + 1;

          if (rty < 0 || rtx < 0) {
            continue;
          }
          if (lby > l || lbx > l) {
            continue;
          }
          rty = min(rty, l - 1);
          rtx = min(rtx, l - 1);
          lby = max(lby, 0);
          lbx = max(lbx, 0);
          if ((y + x + 2) % 2 == 0) {
            score += b_acc[rty+1][rtx+1] - b_acc[lby][rtx+1] - b_acc[rty+1][lbx] + b_acc[lby][lbx];
          } else {
            score += w_acc[rty+1][rtx+1] - w_acc[lby][rtx+1] - w_acc[rty+1][lbx] + w_acc[lby][lbx];
          }
        }
      }
      ans = max(score, ans);
    }
  }
  cout<<ans<<endl;
}

