        cb += ru[1][2 * k][2 * k] + ru[1][i + k][j + k] - ru[1][2 * k][j + k] -
              ru[1][i + k][2 * k];
        cb += ru[1][i][2 * k] - ru[1][i][j + k];
        cb += ru[1][2 * k][j] - ru[1][i + k][j];

        ans = max({ans, cw + (ru[1][2 * k][2 * k] - cb),
                   cb + (ru[0][2 * k][2 * k] - cw)});
