template<typename T>
struct CumSum2D {
    int xnum, ynum;
    vector<vector<T>> data;
    vector<vector<T>> cumsum;

    CumSum2D(int xnum, int ynum) : xnum(xnum), ynum(ynum) {
        ndarray(data, xnum+1, ynum+1);
        ndarray(cumsum, xnum+1, ynum+1);
    }

    int add(int x, int y, T value) {
        //x,y 1~_num
        if (x > xnum || y > ynum) return -1;
        data[x][y] += value;
        return 0;
    }

    int add_imos(int startx, int starty, int endx, int endy) {
        //x,y 1~_num
        if (add(endx, endy, (T) 1) == 1) return -1;
        if (add(startx-1, endy, (T) 1) == -1) return -1;
        if (add(endx, starty-1, (T) 1) == -1) return -1;
        if (add(startx-1, starty-1, (T) 1) == 1) return -1;
        return 0;
    }

    void build() {
        for (int i = 0; i < xnum; i++) {
            for (int j = 0; j < ynum; j++) {
                cumsum[i+1][j+1] = data[i+1][j+1] + cumsum[i+1][j] + cumsum[i][j+1] - cumsum[i][j];
            }
        }
    }

    T get(int startx, int starty, int endx, int endy) {
        //x,y 1~_num
        //(startx, starty) ~ (endx, endy)の範囲のdataの和を返す
        return (cumsum[endx][endy] - cumsum[endx][starty-1] - cumsum[startx-1][endy] - cumsum[startx-1][starty-1]);
    }

    void print() {
        for (auto vec : cumsum) {
            for (auto val : vec) {
                std::cout << val << " ";
            }
            std::cout << std::endl;
        }
    }
};

