        imos[(x + k) % (2 * k) + 1][(y + k) % (2 * k) + 1]++;
    }

    for(int i = 1; i <= 2 * k; i++){
        for(int j = 1; j <= 2 * k; j++){
            imos[i][j] += imos[i - 1][j] + imos[i][j - 1] - imos[i - 1][j - 1];
        }
    }

    ll ans = 0;
    for(int i = 1; i <= k; i++){
        for(int j = 1; j <= k; j++){
            ll t = imos[i][j] - imos[i + k][j] - imos[i][j + k] + imos[i + k][j + k];
            ans = max({ans, t, n - t});
        }
    }

    cout << ans << endl;
}

