template<typename T>
struct CumulativeSum2D {
    vector<vector<T>> acc;
    CumulativeSum2D(int h = 0, int w = 0) : acc(h + 1, vector<T>(w + 1)) { }
    void add(int i, int j, int x) { acc[i + 1][j + 1] += x; }
    void build() {
        int H = acc.size(), W = acc[0].size();
        for (int i = 1; i < H; i++) for (int j = 1; j < W; j++) {
            acc[i][j] += acc[i][j - 1] + acc[i - 1][j] - acc[i - 1][j - 1];
        }
    }
    T sum(int si, int sj, int ti, int tj) {     // [si, ti) x [sj, tj)
        return acc[ti][tj] - acc[si][tj] - acc[ti][sj] + acc[si][sj];
    }
};

const int INF = (int)1e9 + 7;
int main() {
    int n, k; cin >> n >> k;
    int sz = k * 2;
    CumulativeSum2D<int> acc(sz, sz);
    int white = 0, sum = 0;
    while (n--) {
        int x, y; char c; cin >> x >> y >> c;
        int pt = c == 'B' ? 1 : -1;
        acc.add(x % sz, y % sz, pt);
        white += c == 'W';
        sum += pt;
    }
    acc.build();
    int ma = -INF;
    for (int i = 0; i < k; i++) for (int j = 0; j < k; j++) {
        int tmp = white;
        tmp += acc.sum(0, 0, i, j);
        tmp += acc.sum(i + k, 0, sz, j);
        tmp += acc.sum(0, j + k, i, sz);
        tmp += acc.sum(i, j, i + k, j + k);
        tmp += acc.sum(i + k, j + k, sz, sz);
        ma = max({ma, tmp, sum - tmp});
    }
    cout << ma << endl;
    return 0;
}

