void fill(vector<vector<LL>> &v, LL x, LL y, LL K) {
    LL right = min<LL>(x + 1, 2*K);
    LL left = max<LL>(0, x + 1 - K);
    LL top = min<LL>(y + 1, 2*K);
    LL bot = max<LL>(0, y + 1 - K);
    if(right < 0 || top < 0 || 2*K < bot || 2*K < left) {
        return;
    }
    v[right][top]++;
    v[left][bot]++;
    v[left][top]--;
    v[right][bot]--;
}

