        char ch;
        cin>>x>>y>>ch;
        if(ch=='B')y-=k;
        x=(x+2*k)%(2*k);
        y=(y+2*k)%(2*k);
        vec.pb(mp(x,y));
        s[x+1][y+1]++;
    }
    auto qry = [&] (int x0,int y0,int x1,int y1)
    {
        return s[y1][x1]-s[y1][x0-1]-s[y0-1][x1]+s[y0-1][x0-1];
    };
    f(i,1,2*k)
    {
        f(j,1,2*k)
        {
            s[i][j]+=s[i-1][j];
            s[i][j]+=s[i][j-1];
            s[i][j]-=s[i-1][j-1];
        }
    }
    int ses=0;
    f(x,1,k)
    {
        f(y,1,k)
        {
            int cnt=0;
            cnt+=qry(x,y,x+k-1,y+k-1);
            cnt+=qry(1,1,x-1,y-1);
            cnt+=qry(1,y+k,x-1,2*k);
            cnt+=qry(x+k,y+k,2*k,2*k);
            cnt+=qry(x+k,1,2*k,y-1);
            ses=max(ses,max(cnt,n-cnt));
        }
    }
    cout<<ses<<endl;
    return 0;

}

