int main() {
  std::cin.tie(nullptr);
  std::ios::sync_with_stdio(false);

  ll n,k;
  std::cin>>n>>k;

  //sum[i][j]= 長方形[0,i)*[0,j)のsum
  std::vector<std::vector<ll>> sum(2*k+1,std::vector<ll>(2*k+1,0));

  rep(i,0,n){
    ll x,y;
    std::cin>>x>>y;
    char c;
    std::cin>>c;

    if(c=='W')x+=k;//Bの条件に帰着

    x%=2*k;
    y%=2*k;
    sum[x+1][y+1]++;
  }

  rep(i,1,2*k+1){
    rep(j,1,2*k+1){
      sum[i][j]+=sum[i][j-1]+sum[i-1][j]-sum[i-1][j-1];
    }
  }

  ll ans=0;

  auto calc=[&](ll x1,ll y1,ll x2,ll y2)->ll{
    return sum[x2][y2]+sum[x1][y1]-sum[x2][y1]-sum[x1][y2];
  };

  // i,jを[0,k+1)*[0,k+1)で全探索し
  //ある黒正方形の左下を(i,j)に固定したときのスコアを計算

  rep(i,0,k+1){
    rep(j,0,k+1){
      ll val=0;
      val+=calc(0,0,i,j);
      val+=calc(i,j,i+k,j+k);
      val+=calc(0,j+k,i,2*k);
      val+=calc(i+k,0,2*k,j);
      val+=calc(i+k,j+k,2*k,2*k);
      chmax(ans,std::max(val,n-val));
    }
  }

  std::cout<<ans<<"\n";

  return 0;
}

