	Y.resize(N);
	for (int i = 0; i < N; ++i) {
		int x, y; char c;
		cin >> x >> y >> c;
		X[i] = (c == 'B') ? x : x + K;
		Y[i] = y;
	}
}

int solve(void) {
	int max_cnt1 = -1;
	int max_cnt2 = -1;
	for (int dy = 0; dy < K; ++dy) {
		for (int dx = 0; dx < K; ++dx) {
			int cnt1 = 0;
			int cnt2 = 0;
			for (int i = 0; i < N; ++i) {
				int x = (X[i] + dx) % (2 * K);
				int y = (Y[i] + dy) % (2 * K);
				if ((x < K && y < K) || (x >= K && y >= K))
					++cnt1;
				if ((x < K && y >= K) || (x >= K && y < K))
					++cnt2;
			}
			max_cnt1 = max(cnt1, max_cnt1);
			max_cnt2 = max(cnt2, max_cnt2);
		}
	}
	return max(max_cnt1, max_cnt2);
}

