int getSquare(int x, int y, int xx, int yy) {
  int ans = a[xx][yy];
  if (x > 0) ans -= a[x - 1][yy];
  if (y > 0) ans -= a[xx][y - 1];
  if (x > 0 && y > 0) ans += a[x - 1][y - 1];
  return ans;
}

int main() {
