        rep(j, k+1){
            // 黒の範囲は i~i+k ( (i+k) % 2*k)&& j~j+k
            //2次元累積でO(1)で答える
            int tmp = 0, tmpw=0;
            //メイン区間

            tmp += rb[2*k][2*k] - rb[2*k][j+k] - rb[i+k][2*k] + rb[i+k][j+k];
            tmpw += rw[2*k][2*k] - rw[2*k][j+k] - rw[i+k][2*k] + rw[i+k][j+k];
            tmp += rb[i][j] - rb[i][max(j-k, 0LL)] - rb[max(i-k, 0LL)][j] + rb[max(0LL,i-k)][max(0LL, j-k)];
            tmpw += rw[i][j] - rw[i][max(j-k, 0LL)] - rw[max(i-k, 0LL)][j] + rw[max(0LL,i-k)][max(0LL, j-k)];
