    for(int i=0; i<N; i++){
        ll x, y;
        char c;
        cin >> x >> y >> c;
        if(c=='B') y+=K;
        x = x%(2*K);
        y = y%(2*K);
        v[x][y] += 1;
        v[(x+K)%(2*K)][(y+K)%(2*K)] += 1;
    }
    vector<vector<int> > cum(2*K, vector<int>(2*K));
    for(int i=0; i<2*K; i++){
        for(int j=0; j<2*K; j++){
            cum[i][j] = v[i][j];
            if(i>0&&j>0) cum[i][j] += cum[i-1][j]+cum[i][j-1]-cum[i-1][j-1];
            else if(i>0) cum[i][j] += cum[i-1][j];
            else if(j>0) cum[i][j] += cum[i][j-1];
            // cout << i << " " << j << " " << v[i][j] << " " << cum[i][j] << endl;
            // cout << v[i][j] << " ";
        }
        // cout << endl;
    }

    int ans = 0;
    for(int i=0; i<K; i++){
        for(int j=0; j<K; j++){
            int s = cum[i+K-1][j+K-1];
            if(i>0&&j>0) s+=-cum[i-1][j+K-1]-cum[j+K-1][j-1]+cum[i-1][j-1];
            else if(i>0) s-=cum[i-1][j+K-1];
            else if(j>0) s-=cum[i+K-1][j-1];
