ll d[2010][2010];
long long K;

ll nor(ll n) {
	return max(min(n, 2*K+1), 0LL);
}

void dplus(ll x, ll y) {
	ll le = nor(x), ri = nor(x+K), dw = nor(y), up = nor(y+K);
	d[le][dw]++;
	d[ri][dw]--;
	d[le][up]--;
	d[ri][up]++;
}

int main(){	
	long long N;
	scanf("%lld",&N);
	vector<char> c(N-1+1);
	vector<long long> y(N-1+1);
	vector<long long> x(N-1+1);
	scanf("%lld",&K);
	for(int i = 0 ; i <= N-1 ; i++){
		scanf("%lld",&x[i]);
		scanf("%lld",&y[i]);
		cin >> c[i];
	}
	rep(i, N) {
		if (c[i] == 'B') {
			x[i] = x[i]%(2*K)+1;
			y[i] = y[i]%(2*K)+1;
		} else {
			x[i] = x[i]%(2*K)+1;
			y[i] = (y[i]+K)%(2*K)+1;
		}
	}

	rep(i, N) {
		dplus(x[i]-K, y[i]-K);
		dplus(x[i]+K, y[i]-K);
		dplus(x[i], y[i]);
		dplus(x[i]-K, y[i]+K);
		dplus(x[i]+K, y[i]+K);
	}

	rep(i, 2*K+1) {
		rep(j, 2*K+1) {
			d[i+1][j] += d[i][j];
		}
	}

	rep(i, 2*K+1) {
		rep(j, 2*K+1) {
			d[i][j+1] += d[i][j];
		}
	}

	ll res = 0;
	repn(i, 2*K) {
		repn(j, 2*K) {
			res = max(res, d[i][j]);
		}
	}

	cout << res << endl;

	return 0;
}

