LL N, K;

bool is_even(LL num) {
	return (num % 2LL) == 0;
}

bool is_black(LL X, LL Y) {

	if (is_even(X / K)) {
		if (is_even(Y / K)) {
			return true;
		}
		else {
			return false;
		}
	}
	else {
		if (is_even(Y / K)) {
			return false;
		}
		else {
			return true;
		}
	}

}

int main() {
	LL Xstart, Ystart;

	cin >> N >> K;
	vector<LL> Xs(N), Ys(N);
	vector<bool> Cs(N);

	REP(i, N) {
		char a;
		cin >> Xs[i] >> Ys[i] >> a;
		Cs[i] = (a == 'B');
	}


	int maxnum = -1;
	for (Xstart = 0; Xstart < 2 * K;Xstart++) {
		for (Ystart = 0; Ystart < 2 * K; Ystart++) {

			int num = 0;

			REP(i, N) {
				bool black = is_black(Xstart + Xs[i], Ystart + Ys[i]);
				if (Cs[i]&&black) {
					num++;
				}
