int imos[2005][2005] = {};

int query(int x1, int y1, int x2, int y2){
    if (x1 > x2 || y1 > y2) return 0;
    else{
        return imos[y2][x2] + imos[y1-1][x1-1] - imos[y1-1][x2] - imos[y2][x1-1];
    }
}

int main()
{
    ios::sync_with_stdio(false);
    int N, K, tmp, max_color;
    int max_hope = 0;
    int x, y;
    char c;
    cin >> N >> K;
    int KK = 2*K;
    REP(i, N){
        cin >> x >> y >> c;
        if (c == 'W'){
            y += K;
        }
        x %= KK;
        y %= KK;
        imos[y][x] = 1;
    }
    REP(i, KK){
        REP(j, KK-1){
            imos[i][j+1] += imos[i][j];
        }
    }
    REP(i, KK-1){
        REP(j, KK){
            imos[i+1][j] += imos[i][j];
        }
    }
    REP(i, K){
        REP(j, K){
            tmp = query(i, j, i+K-1, j+K-1) + query(0, 0, i-1, j-1) + query(i+K, j+K, KK-1, KK-1) + query(0, j+K, i-1, KK-1) + query(i+K, 0, KK-1, j-1);
            max_color = max(tmp, N - tmp);
            max_hope = max(max_hope, max_color);
        }
    }
    cout << max_hope << "\n";
    return 0;
}

