int n,k,d[2][1001][2002],m=0;

int f(int z, int y, int x, int w, int v){
    int u=d[z][y][x];
    if(w<=0&&v<=0)return u;
    if(v>0)u-=f(z, y, v-1, w, 0);
    if(w>0)u-=f(z, w-1, x, 0, v);
    if(v>0&&w>0)u-=f(z, w-1, v-1, 0, 0);
    return u;
}

int main(void){
    int w=0;
    cin>>n>>k;
    for(int i=0;i<k;i++){
        fill(d[0][i], d[0][i]+k*2, 0);
        fill(d[1][i], d[1][i]+k*2, 0);
    }
    for(int i=0;i<n;i++){
        int x,y;
        char c;
        cin>>y>>x>>c;
        x%=k*2;
        y%=k*2;
        if(y>=k){
            y-=k;
            x=(x+k)%k;
        }
        if(c=='B'){
            d[0][y][x]++;
        }else{
            d[1][y][x]++;
            w++;
        }
    }
    for(int i=0;i<k;i++){
        for(int j=1;j<k*2;j++){
            d[0][i][j]+=d[0][i][j-1];
            d[1][i][j]+=d[1][i][j-1];
        }
    }
    for(int j=0;j<k*2;j++){
        for(int i=1;i<k;i++){
            d[0][i][j]+=d[0][i-1][j];
            d[1][i][j]+=d[1][i-1][j];
        }
    }
    for(int i=0;i<k;i++){
        for(int j=0;j<k*2;j++){
            int v=0;
            for(int l=0;l<2;l++){
                int p=0;
                if(i==k-1){
                    if(j<k){
                        p=f(l, k-1, j, 0, 0)+f(l, k-1, k*2-1, 0, k+j+1);
                    }else{
                        p=f(l, k-1, j, 0, j-k+1);
                    }
                }else{
                    if(j<k){
                        p=f(l, i, j, 0, 0)+f(l, k-1, j+k, i+1, j+1);
                        if(j<k-1)p+=f(l, i, k*2-1, 0, j+k-1);
                    }else{
                        p=f(l, i, j, 0, j-k+1)+f(l, k-1, j-1, i+1, 0);
                        if(j<k*2-1)p+=f(l, k-1, k*2-1, i+1, j+1);
                    }
                }
                if(l==0){
                    v=p;
                }else{
                    v+=w-p;
                }
            }
            m=max(m,v);
        }
    }
    cout<<m<<endl;
}

