int y1[10*MAXK+5];//记录y=y1行黑色格子的个数 

struct point{
	int x;
	int y;
	int c;
}a[100000];

int main(int argc, char *argv[]) {
	int N,K;
	while(cin>>N>>K) {
		int Max=0,cnt=0;//cnt记录黑色格子的总个数 
		int i;
		for(i=0;i<N;i++) {
			char ch;
			cin>>a[i].x>>a[i].y>>ch;
			a[i].x%=(2*K);//降维,*2k或%2k都仅仅是改变了它的位置，而没有改变它的颜色。
			a[i].y%=(2*K);
			if(ch=='W')
				a[i].c=1;//白色格子标记为1
			else
				a[i].c=0;
		}

		for(i=0;i<K;i++) {//在那个2k*2k的格子里枚举长度为k的横竖边 
			cnt=0;
			memset(y1,0,sizeof(y1));
			int j;
			for(j=0;j<N;j++) {//依次遍历各点 
				int p=(i<=a[j].x&&a[j].x<i+K);
				int q=(0<=a[j].y&&a[j].y<K); 
				//cout<<"p="<<p<<" "<<"q="<<q<<endl;
				if(p^q==a[j].c) {//通过异或运算，被两条边都覆盖了的和都没被覆盖是一个颜色，其它的格子是另一个颜色。  
					cnt++;
					y1[a[j].y]++; 
				} 
				else
					y1[a[j].y]--;
				//cout<<"y1[a["<<j<<"].y]="<<y1[a[j].y]<<endl;
			}
			for(j=0;j<K;j++) {
				if(cnt>Max)
					Max=cnt;
				if(N-cnt>Max)//若白色格子比黑色格子多，则让Max取白色格子的个数 
					Max=N-cnt;
				if(j!=K)
					cnt=cnt-y1[j]-y1[j+K];
			}
		}

		cout<<Max<<endl; 
	}

	return 0;
}

