int main() {
  int n, k;
  cin>>n>>k;

  int l = 2 * k;
  map<pair<int,int>, int> b, w;

  for (int i=0; i<n; i++) {
    int x, y;
    char c;
    cin>>x>>y>>c;
    if (c == 'B') {
      ++b[make_pair(x%l, y%l)];
    } else {
      ++w[make_pair(x%l, y%l)];
    }
  }
  int max_k = 0;
  for (int i=0; i<=k; i++) {
    for (int j=0; j<=k; j++) {
      int tmp = 0;
      for (auto bi: b) {
        auto f = bi.first;
        int x = (f.first + i) % l;
        int y = (f.second + j) % l;
        if (x >= 0 && x < k && y >= 0 && y< k) {
          ++tmp;
        } else if (x >= k && x < l && y >= k && y< l) {
          ++tmp;
        }
      }
      for (auto wi: w) {
        auto f = wi.first;
        int x = (f.first + i) % l;
        int y = (f.second + j) % l;
        if (x >= 0 && x < k && y >= k && y< l) {
          ++tmp;
        } else if (x >= k && x < l && y >= 0 && y< k) {
          ++tmp;
        }
      }
      max_k = max(tmp, max_k);
    }
  }
  cout<<max_k<<endl;
}

