// Number of points as white. Area [(0,0)..(2K,2K)]
int plane[2'010][2'010];
// cumulative[x][y] := Number of points in [(0,0)..(x,y))
int cumulative[2'010][2'010];

/* Return number of points in
 * [(lx,ly)..(hx..hy))
 * lx/ly: low x/y
 * hx/hy: high x/y
 */
int query(int lx, int ly, int hx, int hy) {
	if(lx > hx || ly > hy) return 0;
	return cumulative[hx][hy]
			- cumulative[lx][hy]
			- cumulative[hx][ly]
			+ cumulative[lx][ly];
}

int main() {
	// Input
	int N;
	int K;
	cin >> N >> K;
	const int k2 = 2 * K;
	// ... and Preparation
	for(int i = 0; i < N; ++i) {
		int x, y;
		char c;
		cin >> x >> y >> c;
		if(c == 'B') x += K;
		x %= k2;
		y %= k2;
		++plane[x][y];
	}
	// Preparation
	for(int x = 1; x <= k2; ++x) {
	for(int y = 1; y <= k2; ++y) {
		cumulative[x][y] = cumulative[x-1][y]
							+ cumulative[x][y-1]
							- cumulative[x-1][y-1]
							+ plane[x-1][y-1];
	}
	}
	// Calculation
	int ans = 0;
	for(int x = 0; x <= K; ++x) {
	for(int y = 0; y <= K; ++y) {
		// 0       x           x+K 2K
		// +---+---+---+---+---+---+ 0
		// |/A/|///|   |   |   |/B/|
		// +---+---+---+---+---+---+ y
		// |   |   |/D/|///|///|   |
		// +---+---+---+---+---+---+
		// |   |   |///|///|///|   |
		// +---+---+---+---+---+---+
		// |   |   |///|///|///|   |
		// +---+---+---+---+---+---+ y+K
		// |/C/|///|   |   |   |/E/|
		// +---+---+---+---+---+---+
		// |///|///|   |   |   |///|
		// +---+---+---+---+---+---+ 2K
		int a = query(0,   0,   x,   y);
		int b = query(x+K, 0,   k2,  y);
		int c = query(0,   y+K, x,   k2);
		int d = query(x,   y,   x+K, y+K);
		int e = query(x+K, y+K, k2,  k2);
		int w = a + b + c + d + e;
		ans = max(ans, w);
	}
	}
	// Output
	cout << ans << endl;
	return 0;
}

