int pp[2000][1000];

void ps(int x, int y, int k){
  if (x < k){
    pp[x][y] += 1;
    pp[x+k][y] += -1;
    if (y == 0) return;
    pp[0][0] += 1;
    pp[0][y] += -1;
    pp[x][0] += -1;
    pp[x][y] += 1;
    pp[x+k][0] += 1;
    pp[x+k][y] += -1;
  }
  else {
    pp[x][y] += 1;
    pp[0][y] += 1;
    pp[x-k][y] += -1;
    if (y == 0) return;
    pp[x-k][0] += 1;
    pp[x-k][y] += -1;
    pp[x][0] += -1;
    pp[x][y] += 1;
  }
}

