    scanf("%d %d %c", &x, &y, s);
     x = x % (2*k);
     y = y % (2*k);
    if ((s[0] - 'B') != 0){
      y = (y + k) % (2*k);
    }
    if (y >= k) {
      y = y - k;
      x = (x + k) % (2 * k);
    }
    ps(x, y, k);
  }

  for (int i = 0; i < 2*k; i++){
    for (int j = 1; j < k; j++){
      pp[i][j] += pp[i][j-1];
    }
  }


  for (int i = 1; i < 2*k; i++){
    for (int j = 0; j < k; j++){
      pp[i][j] += pp[i-1][j];
    }
  }

  int m = 0;
  for (int i = 0; i < 2*k; i++){
    for (int j = 0; j < k; j++){
      m = max(m, pp[i][j]);
