void ruiseki(int x,int y){
    int a=max(0,x-k+1);
    int b=max(0,y-k+1);
    if(2*k<=a||2*k<=b)return;
    int c=min(x+1,2*k);
    int d=min(y+1,2*k);
    g[a][b]++;//左下
    g[c][d]++;//右上
    g[a][d]--;//左上
    g[c][b]--;//右下
}

int main(){
    int n;cin>>n>>k;
