        cin>>x[i]>>y[i]>>c;
        if(c=='W')y[i]+=k;
        x[i]%=2*k;y[i]%=2*k;
        ruiseki(x[i],y[i]);
        ruiseki(x[i]+2*k,y[i]);
        ruiseki(x[i]+k,y[i]+k);
        ruiseki(x[i],y[i]+2*k);
        ruiseki(x[i]+2*k,y[i]+2*k);
    }
    int ans=g[0][0];
    rep(i,2*k){
        g[0][i+1]+=g[0][i];
        g[i+1][0]+=g[i][0];
        ans=max(ans,max(g[0][i+1],g[i+1][0]));
