int main() {
    int N, K;
    cin >> N >> K;
    vi X(N), Y(N);
    vector<char> C(N);
    rep(i, N) {
        cin >> X[i] >> Y[i] >> C[i];
    }

    // wをbにする
    rep(i, N) {
        if (C[i] == 'W') {
            Y[i] += K;
        }
    }

    // 2Kを取り除く
    rep(i, N) {
        X[i] %= (2 * K);
        Y[i] %= (2 * K);
    }

    vector<vector<int>> sum(2 * K + 1, vector<int>(2 * K + 1));
    rep(i, N) sum[X[i] + 1][Y[i] + 1]++;

    // 2次元累積和
    for (int i = 1; i < 2 * K + 1; i++) {
        for (int j = 1; j < 2 * K + 1; j++) {
            sum[i][j] += sum[i - 1][j] + sum[i][j - 1] - sum[i - 1][j - 1];
        }
    }

    int ans = 0;
    // Kで全探索
    for (int i = 1; i <= K; i++) {
        for (int j = 1; j <= K; j++) {
            // (i,j)が左上の頂点の場合

            if (i == 1 && j == 1) {
                int x = sum[K][K] + sum[2 * K][2 * K] - sum[2 * K][K] - sum[K][2 * K] + sum[K][K];
                // 反転させた数
                int y = N - x;
                ans = max(ans, max(x, y));
// cout << "i: " << i << ", j: " << j << ", x: " << x << ", y: " << y << endl;
            } else if (i == 1) {
                int x = sum[i + K - 1][j + K - 1] - sum[i - 1][j + K - 1];
                x += sum[i - 1][2 * K] - sum[i - 1][j + K - 1];
                x += sum[2 * K][2 * K] - sum[i + K - 1][2 * K] - sum[2 * K][j + K - 1] + sum[i + K - 1][j + K - 1];
                int y = N - x;
                ans = max(ans, max(x, y));
// cout << "i: " << i << ", j: " << j << ", x: " << x << ", y: " << y << endl;
            } else if (j == 1) {
                int x = sum[i + K - 1][j + K - 1] - sum[i + K - 1][j - 1];
                x += sum[2 * K][j - 1] - sum[i + K - 1][j - 1];
                x += sum[2 * K][2 * K] - sum[i + K - 1][2 * K] - sum[2 * K][j + K - 1] + sum[i + K - 1][j + K - 1];
                int y = N - x;
                ans = max(ans, max(x, y));
// cout << "i: " << i << ", j: " << j << ", x: " << x << ", y: " << y << endl;
            } else {
                int x = sum[2 * K][2 * K] + sum[i + K - 1][j + K - 1] - sum[2 * K][j + K - 1] - sum[i + K - 1][2 * K];
                x += sum[i + K - 1][j + K - 1] + sum[i - 1][j - 1] - sum[i - 1][j + K - 1] - sum[i + K - 1][j - 1];
                x += sum[i - 1][j - 1];
                x += sum[2 * K][j - 1] - sum[i + K - 1][j - 1];
                x += sum[i - 1][2 * K] - sum[i - 1][j + K - 1];
                int y = N - x;
                ans = max(ans, max(x, y));
// cout << "i: " << i << ", j: " << j << ", x: " << x << ", y: " << y << endl;
            }

        }
    }

    // rep(i, 2 * K + 1) {
    //     rep(j, 2 * K + 1) {
    //         cout << sum[i][j] << " ";
    //     }
    //     cout << endl;
    // }

    cout << ans << endl;

}

