pair<ll, ll> XY[100100];
int T[3100][3100];
int TSUM[3100][3100];

int get_sum(int x1, int y1, int x2, int y2){
    ll ret = 0;
    ret = TSUM[x2][y2];
    if(x1-1 >= 0) ret -= TSUM[x1-1][y2];
    if(y1-1 >= 0) ret -= TSUM[x2][y1-1];
    if(x1-1 >= 0 && y1-1 >= 0) ret += TSUM[x1-1][y1-1];
    return ret;
}

int main(){
    int N,K;
    cin >> N >> K;
    ll x, y;
    REP(i,N){
        ll x, y;
        char c;
        cin >> x >> y >> c;
        x %= 2*K;
        y %= 2*K;
        if(c == 'B'){
            x += K;
            x %= 2*K;
        }
        if(x >= K){
            x -= K;
            y = (y+K)%(2*K);
        }
        //printf("x:%d, y:%d\n", x, y);
        XY[i] = make_pair(x,y);
        T[y][x]++;
    }

    TSUM[0][0] = T[0][0];
    for(int i = 1; i < 2*K; i++) TSUM[0][i] = T[0][i] + TSUM[0][i-1];
    for(int i = 1; i < 2*K; i++) TSUM[i][0] = T[i][0] + TSUM[i-1][0];
    for(int i = 1; i < 2*K; i++){
        for(int j = 1; j < 2*K; j++){
            TSUM[i][j] = T[i][j] + TSUM[i-1][j] + TSUM[i][j-1] - TSUM[i-1][j-1];
        }
    }

    //for(int i = 2*K-1; i >= 0; i--){
    //    REP(j,K){
    //        printf("%d ", T[i][j]);
    //    }
    //    printf("\n");
    //}
    //REP(i,2*K){
    //    REP(j,K){
    //        printf("%d ", TSUM[i][j]);
    //    }
    //    printf("\n");
    //}

    ll ans = 0;
    //(0, 0) white
    for(int i = 0; i < 2*K; i++){
        for(int j = 0; j < K; j++){
            ll tmp = 0;
            if(j == 0){
                if(i <= K){
                   tmp = get_sum(i, j, i+K-1, j+K-1);
                }
                else{
                    tmp += get_sum(i, j, 2*K-1, j+K-1);
                    tmp += get_sum(0, 0, (i+K)%(2*K), (j+K)%(2*K));
                }
            }else{
                if(i == 0){
                    tmp += get_sum(i, j, i+K-1, K-1);
                    tmp += get_sum(K, 0, 2*K-1, j-1);
                }
                else if(i <= K){
                    tmp += get_sum(i, j, i+K-1, K-1);
                    tmp += get_sum(i+K, 0, 2*K-1, j-1);
                    tmp += get_sum(0, 0, i-1, j-1);
                }
                else{
                    tmp += get_sum(i, j, 2*K-1, K-1);
                    tmp += get_sum(0, j, (i+K)%(2*K), K-1);
                    tmp += get_sum((i+K)%(2*K)+1, 0, i-1, j-1);
                }
            }
            //printf("(%d, %d) : %d\n", i, j, tmp);
            ans = max(ans, tmp);
        }
    }

    cout << ans << endl;
    return 0;
}

