  for (unsigned y = 0; y < M; ++y) {
    for (unsigned x = 0; x < M; ++x) {
      sum[y + 1][x + 1] = (table[y][x] ? 1 : 0) 
                        + sum[y + 1][x] 
                        + sum[y][x + 1] 
                        - sum[y][x];
    }
  }

  unsigned max = 0;

  for (unsigned py = 0; py < K; ++py) {
    for (unsigned px = 0; px < K; ++px) {
      unsigned S = 0;

      S += count(sum, 0, px, py, py + K);
      S += count(sum, px, px + K, 0, py);
      S += count(sum, px, px + K, py + K, M - 1);
      S += count(sum, px + K, M - 1, py, py + K);

      max = std::max(max, std::max(S, N - S));
    }
  }

  std::cout << max << std::endl;

  return 0;
}

