using namespace std;

struct req {
	int x, y;
	bool w;
};

int main() {
	int n, k;
	cin >> n >> k;

	int x, y;
	char c;
	vector<req> r(n);

	for (int i = 0; i< n; i++) {
		cin >> x >> y >> c;
		r[i].x = x - 2*k * (x/(2*k));
		r[i].y = y - 2*k * (y/(2*k));
		r[i].w = c == 'W';
	}

	int cx = 0;
	int ix = 0;
	for (int i = 0; i < k+1; i++) {
		int cw = 0;
		int cb = 0;
		for (int ii = 0; ii< n; ii++) {
			bool xx = ((r[ii].x+i) / k) % 2 == 0;
			if (xx ^ r[ii].w) {
				cw++;
			} else {
				cb++;
			}
		}
		int c = max(cw, cb);
		if (c > cx) {
			cx = c;
			ix = i;
		}
	}
	int ans = 0;
	for (int j = 0; j < k+1; j++) {
		int c = 0;
		for (int ii = 0; ii< n; ii++) {
			bool xx = ((r[ii].x+ix) / k) % 2 == 0;
			bool yy = ((r[ii].y+j) / k) % 2 == 0;
			if (xx ^ yy ^ r[ii].w) c++;
		}
		if (c > ans) ans = c;
	}

	cout << ans << endl;
	return 0;
}

