    vector<vector<int>> imos(k+1, vector<int>(k+1));
    for (int i=0; i<n; ++i) {
        int x = xy.at(i).first, y = xy.at(i).second;
        if (x/k == y/k) {
            ++imos.at(0).at(0);
            --imos.at(0).at(y%k+1);
            --imos.at(x%k+1).at(0);
            ++imos.at(x%k+1).at(y%k+1);
            ++imos.at(x%k+1).at(y%k+1);
            --imos.at(k).at(y%k+1);
            --imos.at(x%k+1).at(k);
            ++imos.at(k).at(k);
        } else {
            ++imos.at(x%k+1).at(0);
            --imos.at(x%k+1).at(y%k+1);
            --imos.at(k).at(0);
            ++imos.at(k).at(y%k+1);
            ++imos.at(0).at(y%k+1);
            --imos.at(x%k+1).at(y%k+1);
            --imos.at(0).at(k);
            ++imos.at(x%k+1).at(k);
        }
    }
    for (int i=0; i<k+1; ++i) {
        for (int j=0; j<k+1; ++j) {
            if (i > 0) imos.at(i).at(j) += imos.at(i-1).at(j);
            if (j > 0) imos.at(i).at(j) += imos.at(i).at(j-1);
            if (i > 0 && j > 0) imos.at(i).at(j) -= imos.at(i-1).at(j-1);
        }
    }
    int res = 0;
    for (int i=0; i<k; ++i) for (int j=0; j<k; ++j) chmax(res, imos.at(i).at(j));
    cout << res << '\n';
}

