    q[i][0] %= 2*k, q[i][1] %= 2*k;
    d[q[i][0]][q[i][1]]++;
  }
  ll ans = 0;
  segtree seg(d);
  for(int i=0;i<k;i++){
    for(int j=0;j<k;j++){
      ll now = seg.minimum(i, j, i+k, j+k)
        + seg.minimum(i+k, j+k, 2*k, 2*k) + seg.minimum(0, 0, i, j);
      ans = max({ans, now, n-now});
    }
  }
  std::cout << ans << '\n';
  return 0;
}

