		cin >> x >> y >> ch;
		((ch == 'W') ? cntW : cntB)[1 + x % k2][1 + y % k2]++;
	}
	// calculate the 2D prefix sum
	rep(i, 1, k2 + 1) {
		rep(j, 1, k2 + 1) {
			cntW[i][j] += cntW[i - 1][j] + cntW[i][j - 1] - cntW[i - 1][j - 1];
			cntB[i][j] += cntB[i - 1][j] + cntB[i][j - 1] - cntB[i - 1][j - 1];
		}
	}

	/*
	REP(i, k2 + 1) {
		REP(j, k2 + 1) cerr << cntW[i][j] << " ";
		cerr << endl;
	}
	*/

	int nw = cntW[k2][k2];
	int nb = cntB[k2][k2];

	assert(nw + nb == N);

	int ans = 0;

	// now try every possible primitive start.
	for (int i = 1; i <= K; i++) {
		for (int j = 1; j <= K; j++) {
			// take (i, j) as the beginning of a whole square
			/*
			int kw = nw
				- (cntW[i + K][k2] + cntW[k2][j + K])
				+ (cntW[i][k2] + cntW[k2][j])
				+ 2 * sumW(i, i + K, j, j + K);

			int kb = nb
				- (cntB[i + K][k2] + cntB[k2][j + K])
				+ (cntB[i][k2] + cntB[k2][j])
				+ 2 * sumB(i, i + K, j, j + K);
			*/

			int kw = sumW(i + K, k2, j + K, k2)
					+ sumW(0, i, j + K, k2)
					+ sumW(i + K, k2, 0, j)
					+ sumW(0, i, 0, j)
					+ sumW(i, i + K, j, j + K);
			int kb = sumB(i + K, k2, j + K, k2)
					+ sumB(0, i, j + K, k2)
					+ sumB(i + K, k2, 0, j)
					+ sumB(0, i, 0, j)
					+ sumB(i, i + K, j, j + K);

			// cerr << "PRIM AT " << i << ", " << j << ": " << kw << ", " << kb << endl;

			int Kw = kw + (nb - kb);
			int Kb = kb + (nw - kw);

			ans = max(ans, max(Kw, Kb));
		}
	}
	cout << ans << endl;
}

