   }

   C.build();
   int ans = 0;

   for(int i = 0;i <= k;i++)for(int j = 0;j <= k;j++){
      int count = 0;

      count += C.query(i,j,i+k,j+k);//真ん中
      count += C.query(i+k,j+k,2*k,2*k);//右下
      count += C.query(0,0,i,j);//左上
      count += C.query(i+k,0,2*k,j);//左下
      count += C.query(0,j+k,i,2*k);//右上

      maxs(ans,count);
      //if(i == 0  && j == 0)cout << count << endl;
   }
   cout << ans << endl;
}

