    if (c == 'B') b[x][y]++;
    if (c == 'W') w[x][y]++;
  }
  reps(i, 2005) reps(j, 2005) b[i][j] += b[i - 1][j];
  reps(i, 2005) reps(j, 2005) b[i][j] += b[i][j - 1];
  reps(i, 2005) reps(j, 2005) w[i][j] += w[i - 1][j];
  reps(i, 2005) reps(j, 2005) w[i][j] += w[i][j - 1];
  i64 ans = 0;
  rep(i, k + 1) rep(j, k + 1) {
    amax(ans, calcs(i, j, k, true));
    amax(ans, calcs(i, j, k, false));
    amax(ans, calcs(j, i, k, true));
