//    std::cout << "s:" <<s<<" c:"<<c<<" bw:" << bw << std::endl;
    if (c == bw) {
      ok[y][x] += 1;
//      std::cout << "ok("<<y<<","<<x<<")" << std::endl;
    } else {
      ng[y][x] += 1;
//      std::cout << "ng("<<y<<","<<x<<")" << std::endl;
    }
  }
  int m = 0;
  std::vector<int> hoksum(K2,0);
  std::vector<int> hngsum(K2,0);
  for (int y=0; y<K2; ++y) {
    for (int x=0; x<K2; ++x) {
      hoksum[y] += ok[y][x];
      hngsum[y] += ng[y][x];
    }
    m += hoksum[y];
  }
//  std::cout << "hoksum " << std::accumulate(hoksum.begin(), hoksum.end(),0) << std::endl;
//  std::cout << "hngsum " << std::accumulate(hngsum.begin(), hngsum.end(),0) << std::endl;
//  std::cout << "initial m = " << m << std::endl;
  for (int x=0; x<K2; ++x) {
    int tm = std::accumulate(hoksum.begin(), hoksum.end(),0);
    // 縦に一周
    for (int y=0; y<K2; ++y) {
      {
        int diff = hngsum[y] - hoksum[y];
        std::swap(hoksum[y], hngsum[y]);
        tm += diff;
      }
      {
        int yyy = (y + K) % K2;
        int diff = hngsum[yyy] - hoksum[yyy];
        std::swap(hoksum[yyy], hngsum[yyy]);
        tm += diff;
      }
      if (m < tm) {
        m = tm;
      }
//      std::cout << " y:" << y << " tm:" << tm << " m:" << m << std::endl;
    }
//    std::cout << "x:" << x << " m:" << m << std::endl;
    // 横に１ずらす
    for (int y=0; y<K2; ++y) {
      {
        int diff = ng[y][x] - ok[y][x];
        std::swap(ng[y][x], ok[y][x]);
        hoksum[y] += diff;
        hngsum[y] -= diff;
      }
      {
        int xx = (x + K) % K2;
        int diff = ng[y][xx] - ok[y][xx];
        std::swap(ng[y][xx], ok[y][xx]);
        hoksum[y] += diff;
        hngsum[y] -= diff;
      }
    }
  }
  std::cout << m << std::endl;      
}

