};
vector<p> l;

int count(int x,int y,int K){
  int ret = 0;
  for(p v:l){
    int xx = (v.x-x+2*K)%(2*K);
    int yy = (v.y-y+2*K)%(2*K);
    if(xx<K && yy<K){
      ret++;
    }else if(xx>=K && yy>=K){
      ret++;
    }
  }
  return ret;
}

