ll valFunc(mat &M, pa pos, ll n)
{

  if (pos.first >= n && pos.second >= n)
  {
    //return M[pos.first - n][pos.second - n] + M[pos.first - n][n - 1] + M[n - 1][pos.second - n] - M[n - 1][n - 1];
    return M[pos.first - n][pos.second - n] + valFunc(M, make_pair(pos.first, n - 1), n) + valFunc(M, make_pair(n - 1, pos.second), n) - M[n - 1][n - 1];
  }
  else if (pos.first >= n)
  {
    return M[pos.first - n][pos.second] + M[n - 1][pos.second];
  }
  else if (pos.second >= n)
  {
    return M[pos.first][pos.second - n] + M[pos.first][n - 1];
  }
  else
  {
    return M[pos.first][pos.second];
  }
}

ll cntMat(mat &M, pa tl, pa br)
{
  ll n = M.size();
  if (tl.first == 0 && tl.second == 0)
  {
    //return M[br.first][br.second];
    return valFunc(M, br, n);
  }
  else if (tl.first == 0)
  {
    return valFunc(M, br, n) - valFunc(M, make_pair(br.first, tl.second - 1), n);
  }
  else if (tl.second == 0)
  {
    return valFunc(M, br, n) - valFunc(M, make_pair(tl.first - 1, br.second), n);
  }
  else
  {

    return valFunc(M, br, n) - valFunc(M, make_pair(br.first, tl.second - 1), n) - valFunc(M, make_pair(tl.first - 1, br.second), n) + valFunc(M, make_pair(tl.first - 1, tl.second - 1), n);
  }
}

