/* constant */

const int MAX_K = 1000;
const int MAX_K2 = MAX_K * 2;

/* typedef */

/* global variables */

int bfs[MAX_K2 + 1][MAX_K2 + 1], wfs[MAX_K2 + 1][MAX_K2 + 1];

/* subroutines */

inline int box(int flds[MAX_K2 + 1][MAX_K2 + 1],
	       int x0, int y0, int x1, int y1) {
  return flds[y1][x1] - flds[y1][x0] - flds[y0][x1] + flds[y0][x0];
}

inline int count(int flds[MAX_K2 + 1][MAX_K2 + 1],
		 int k, int k2, int x0, int y0) {
  int x1 = x0 + k, y1 = y0 + k;
  return
    box(flds, 0, 0, x0, y0) +
    box(flds, x1, 0, k2, y0) +
    box(flds, x0, y0, x1, y1) +
    box(flds, 0, y1, x0, k2) +
    box(flds, x1, y1, k2, k2);
}

/* main */

int main() {
  int n, k;
  scanf("%d%d", &n, &k);
  int k2 = k * 2;

  for (int i = 0; i < n; i++) {
    int x, y;
    char cs[2];
    scanf("%d%d%s", &x, &y, cs);
    x %= k2, x++;
    y %= k2, y++;
    if (cs[0] == 'B') bfs[y][x]++;
    else wfs[y][x]++;
  }

  for (int y = 0; y < k2; y++)
    for (int x = 0; x < k2; x++) {
      bfs[y + 1][x + 1] += bfs[y + 1][x] + bfs[y][x + 1] - bfs[y][x];
      wfs[y + 1][x + 1] += wfs[y + 1][x] + wfs[y][x + 1] - wfs[y][x];
    }

  int ball = bfs[k2][k2], wall = wfs[k2][k2];
  int maxd = 0;

  for (int y = 0; y <= k; y++)
    for (int x = 0; x <= k; x++) {
      int d0 = count(bfs, k, k2, x, y) + (wall - count(wfs, k, k2, x, y));
      int d1 = count(wfs, k, k2, x, y) + (ball - count(bfs, k, k2, x, y));
      int d = max(d0, d1);
      if (maxd < d) maxd = d;
    }
  printf("%d\n", maxd);
  return 0;
}

