      }
    }

    else if (x[i]-K+1 < 0 && y[i]-K+1 >= 0) {
      for (int j = y[i]-K+1; j <= y[i]; j++) {
        dx[x[i]][j]++; dx[x[i]+K][j]--;
      }
      for (int j = 0; j <= x[i]; j++) {
        if (y[i]-K >= 0) {dy[j][y[i]-K]++;}
        if (y[i] < 2*K-1) {dy[j][y[i]]--;}
