    else if (x[i]-K+1 >= 0 && y[i]-K+1 < 0) {
      for (int j = 0; j <= y[i]; j++) {
        if (x[i]-K >= 0) {dx[x[i]-K][j]++;}
        if (x[i] < 2*K-1) {dx[x[i]][j]--;}
      }
      for (int j = y[i]+K+1; j <= 2*K-1; j++) {
        if (x[i]-K >= 0) {dx[x[i]-K][j]++;}
        if (x[i] < 2*K-1) {dx[x[i]][j]--;}
      }
      for (int j = x[i]-K+1; j <= x[i]; j++) {
        dy[j][y[i]]++; dy[j][y[i]+K]--;
      }
    }

    else if (x[i]-K+1 < 0 && y[i]-K+1 < 0) {
      for (int j = 0; j <= y[i]; j++) {
        dx[x[i]][j]++; dx[x[i]+K][j]--;
      }
      for (int j = y[i]+K+1; j <= 2*K-1; j++) {
        dx[x[i]][j]++; dx[x[i]+K][j]--;
      }
      for (int j = 0; j <= x[i]; j++) {
        dy[j][y[i]]++; dy[j][y[i]+K]--;
      }
      for (int j = x[i]+K+1; j <= 2*K-1; j++) {
        dy[j][y[i]]++; dy[j][y[i]+K]--;
      }
    }

  }

  int ans = hope[0][0];
  for (int i = 0; i < 2*K-1; i++) {
    hope[i+1][0] = hope[i][0] + dx[i][0];
