      int tmp=wcum.Query(r,c,r+k-1,c+k-1)+wcum.Query(r+k,c+k,r+2*k-1,c+2*k-1)+bcum.Query(r+k,c,r+2*k-1,c+k-1)+bcum.Query(r,c+k,r+k-1,c+2*k-1);
