#define ll long long

int check(int p, int k) {
	if (-2 * k <= p && p <= -k - 1) return 1;
	if (-k <= p && p <= -1) return 0;
	if (0 <= p && p <= k - 1) return 1;
	if (k <= p && p <= 2 * k - 1) return 0;
}

int main() {
	int N, K; scanf("%d%d", &N, &K);
	vector<int> X, Y;

	for (int i = 0; i < N; i++) {
		ll x, y; char s[5]; scanf("%lld%lld%s", &x, &y, &s);
		if (s[0] == 'B') {
			X.push_back(x % (2 * K)); Y.push_back(y % (2 * K));
		}
		else {
			X.push_back(x % (2 * K)); Y.push_back((y + K) % (2 * K));
		}
	}

	int cnt_m = 0;

	for (int i = 0; i < 2 * K; i++) {
		for (int j = 0; j < 2 * K; j++) {
			int cnt = 0;
			for (int k = 0; k < N; k++) {
				int c = check(X[k] - i, K) + check(Y[k] - j, K);
				if (c % 2 == 0) cnt++;
			}
			if (cnt_m < cnt) cnt_m = cnt;
		}
	}

	printf("%d\n", cnt_m);
	return 0;
}

