int cusum[2020][2020];

int main() {
    cin.tie(0); ios_base::sync_with_stdio(false);
    // in
    int N, K; cin >> N >> K;
    int x[101010], y[101010];
    char c[101010];
    for(int i=0; i < N; ++i) cin >> x[i] >> y[i] >> c[i];

    // calc
    // 基本方針：二次元累積和
    // しかしx, yは大きい。
    // 市松模様なので(0, 0)から2 * Kの位置で全探索すると
    // 他の場所の状態は一意にさだまる
    // つまりx, yをmod 2 * Kで場合分けすればよい？（白ならKずらす）
    for(int i=0; i < N; ++i) {
        if(c[i] == 'W') x[i] += K;
        int mx = x[i] % (K * 2);
        int my = y[i] % (K * 2);
        ++cusum[my  ][mx  ];
        ++cusum[(my+K) % (K * 2)][(mx+K) % (K * 2)];
    }

    for(int i = 0; i < K * 2; ++i) 
        for(int j = 0; j < K * 2; ++j) 
            cusum[i+1][j+1] = cusum[i+1][j+1] + cusum[i][j+1] + cusum[i+1][j] - cusum[i][j];

    // out
    int ans = 0;
    for(int i=0; i < K; ++i) {
        for(int j=0; j < K; ++j) {
            int unko = cusum[i+K][j+K] - cusum[i+K][j] - cusum[i][j+K] + cusum[i][j];
            ans = max(ans, unko);
            ans = max(ans, N-unko);
        }
    }

    cout << ans << endl;
    return 0;
}

