int const maxk = 1005;
int pref[2][4 * maxk][4 * maxk];
int k, ans = 0;

inline void add(int x, int y, char c) {
    int ok = 0;
    if (c == 'B') ok = 1;
    pref[ok][x][y]++;
    pref[ok][x + 2 * k][y]++;
    pref[ok][x][y + 2 * k]++;
    pref[ok][x + 2 * k][y + 2 * k]++;
}

inline int get_s(int x1, int y1, int x2, int y2, int c) {
    return pref[c][x2][y2] - pref[c][x2][y1 - 1] - pref[c][x1 - 1][y2] + pref[c][x1 - 1][y1 - 1];
}

inline void check(int x, int y, int c) {
    /*if (get_s(x, y, x + k - 1, y + k - 1, (1^c)) == 0 && get_s(x + k, y + k, x + 2 * k - 1, y + 2 * k - 1, (1^c)) == 0) {
        if (get_s(x + k, y, x + 2 * k - 1, y + k - 1, c) == 0 && get_s(x, y + k, x + k - 1, y + 2 * k - 1, c) == 0) ans++;
    }*/
    ans = max(ans, get_s(x, y, x + k - 1, y + k - 1, c) + get_s(x + k, y + k, x + 2 * k - 1, y + 2 * k - 1, c)
    + get_s(x + k, y, x + 2 * k - 1, y + k - 1, (1^c)) + get_s(x, y + k, x + k - 1, y + 2 * k - 1, (1^c)));
}

main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    int n, x, y;
    cin >> n >> k;
    char c;
    for (int i = 1; i <= n; ++i) {
        cin >> x >> y >> c;
        x %= (2 * k), y %= (2 * k);
        x++, y++;
        add(x, y, c);
    }
    for (int z = 0; z <= 1; ++z) {
        for (int i = 1; i <= 4 * k; ++i) {
            for (int j = 1; j <= 4 * k; ++j) {
                pref[z][i][j] += pref[z][i - 1][j] + pref[z][i][j - 1] - pref[z][i - 1][j - 1];
            }
        }
    }
    for (int i = 1; i <= k; ++i) {
        for (int j = 1; j <= k; ++j) {
            check(i, j, 0);
            check(i, j, 1);
        }
    }
    cout << ans << '\n';
    return 0;
}

