int main() {
    int N, K;
    cin >> N >> K;
    vint R(N), C(N);
    vector<char> T(N);
    v2int field_black(K, vint(2 * K, 0));
    v2int field_white(K, vint(2 * K, 0));
    int white_num = 0; 
    rep(i, N) {
        cin >> C[i] >> R[i] >> T[i];

        int c = (C[i]) % (2 * K);
        int r = (R[i]) % (2 * K);
        if (c < K && r < K) {
            C[i] = c;
            R[i] = r;
        }
        else if (c < K && r >= K) {
            R[i] = r - K;
            C[i] = c + K;
        }
        else if (c >= K && r < K) {
            R[i] = r ;
            C[i] = c ;
        }
        else {
            R[i] = r - K;
            C[i] = c - K;
        }

        if (T[i] == 'W') {
            field_white[R[i]][C[i]]++;
            white_num++;
        }
        else {
            field_black[R[i]][C[i]]++;
        }
    }
    v2int Sb(K + 1, vint(2 * K + 1, 0));
    v2int Sw(K + 1, vint(2 * K + 1, 0));

    REP(i, 1,  K + 1) {
        REP(j, 1, 2 * K + 1) {
            Sb[i][j] = Sb[i - 1][j] + Sb[i][j - 1] - Sb[i - 1][j - 1] + field_black[i - 1][j - 1];
            Sw[i][j] = Sw[i - 1][j] + Sw[i][j - 1] - Sw[i - 1][j - 1] + field_white[i - 1][j - 1];
        }
    }

    int count_b, count_w;
    int max_score = 0;
    REP(i, 1, K + 2) {
        REP(j, 1, K + 2) {
            int Or = i - 1;
            int Er = min(i + K - 1, K);
            int Ec = min(j + K - 1, 2 * K);
            count_b = Sb[Er][Ec] - Sb[i - 1][Ec] - Sb[Er][j - 1] + Sb[i - 1][j - 1];
            count_w = Sw[Er][Ec] - Sw[i - 1][Ec] - Sw[Er][j - 1] + Sw[i - 1][j - 1];
            count_b += Sb[Or][j - 1];
            count_w += Sw[Or][j - 1];
            //if (Or > 0) {
            count_b += Sb[Or][2 * K] - Sb[0][2 * K] - Sb[Or][K + j - 1] + Sb[0][K + j - 1];
            count_w += Sw[Or][2 * K] - Sw[0][2 * K] - Sw[Or][K + j - 1] + Sw[0][K + j - 1];
            //}
            int score = count_b + (white_num - count_w);
            max_score = max(max_score, score);
            //Sb[i][j] - S
        }
    }
    cout << max_score << endl;
    return 0;
}

