template <typename T>
struct twodimBIT
{
// 1-indexed
// http://judge.u-aizu.ac.jp/onlinejudge/review.jsp?rid=3095512#1
// https://www.slideshare.net/hcpc_hokudai/binary-indexed-tree
private:
	vector< vector<T> > array;
	const int n;
	const int m;

public:
	twodimBIT(int _n,int _m):
		array(_n+1,vector<T>(_m+1,0)), n(_n),m(_m){}

	// (1,1) ~ (x,y) ruisekiwa
	T sum(int x,int y) {
		T s = 0;
		for(int i=x;i>0;i-=i&(-i))
			for(int j=y;j>0;j-=j&(-j))
				s += array[i][j];
		return s;
	}

	// [(x1,y1),(x2,y2)] no souwa (x1<x2,y1<y2)
	T sum(int x1,int y1,int x2,int y2){
		return sum(x2,y2) - sum(x1-1,y2) - sum(x2,y1-1) + sum(x1-1,y1-1);
	}

	void add(int x,int y,T k) {
		for(int i=x;i<=n;i+=i&(-i))
			for(int j=y;j<=m;j+=j&(-j))
				array[i][j] += k;
	}
};

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	int N,K;
	cin >> N >> K;
	twodimBIT<int> hope(3*K+3,3*K+3);
	FOR(i,0,N){
		int x,y;
		char c;
		cin >> x >> y >> c;
		if(c=='W')y+=K;
		x %= 2*K;
		y %= 2*K;
		if(x<0)x += 2*K;
		if(y<0)y += 2*K;
		hope.add(x+1,y+1,1);
	}
	int ans = 0;
	FOR(i,1,K+2){
		FOR(j,1,K+2){
			int t = hope.sum(i,j,i+K-1,j+K-1);
			t += hope.sum(i+K,j+K,i+2*K-1,j+2*K-1);
			t += hope.sum(max(0,i-K),max(0,j-K),i-1,j-1);
			t += hope.sum(max(0,i-K),j+K,i-1,j+2*K-1);
			t += hope.sum(i+K,max(j-K,0),i+2*K-1,j-1);
			ans = max( ans , t );
		}
	}
	cout << ans << endl;
}

