      wgrid[k+x][k+y]++;
    }
  }
  auto set_grid = [k](auto& grid) {
    for (int i = k; i < 4*k; i++) {
      for (int j = k; j < 4*k; j++) {
        grid[i][j] += grid[i-1][j];
        grid[i][j] += grid[i][j-1];
        grid[i][j] -= grid[i-1][j-1];
      }
    }
    for (int i = 4*k-1; i >= k; i--) {
      for (int j = 4*k-1; j >= k; j--) {
        grid[i][j] += -grid[i-k][j] - grid[i][j-k] + grid[i-k][j-k];
      }
    }
  };
  set_grid(bgrid);
  set_grid(wgrid);
  auto area_sum = [](int x, int y, auto& grid) -> int {
    return grid[x][y];
  };
  int ans = 0;
  for (int i = k; i < 2*k; i++) {
    for (int j = k; j < 2*k; j++) {
      for (int ltb = 0; ltb < 2; ltb++) {
        bool bw = ltb;
        auto& ag = bw?bgrid:wgrid;
        auto& bg = bw?wgrid:bgrid;
        int res = 0;
        res += area_sum(i-1, j-1, ag);
        res += area_sum(i-1, j+2*k-1, ag);
        res += area_sum(i+k-1, j+k-1, ag);
        res += area_sum(i+2*k-1, j-1, ag);
        res += area_sum(i+2*k-1, j+2*k-1, ag);
        res += area_sum(i-1, j+k-1, bg);
        res += area_sum(i+k-1, j-1, bg);
        res += area_sum(i+k-1, j+2*k-1, bg);
        res += area_sum(i+2*k-1, j+k-1, bg);
        ans = max(ans, res);
      }
    }
  }
  cout << ans << endl;

  return 0;
}

