int K;
int f(vector<vector<int>>A, int x1, int y1, int x2, int y2) {
	if (x2 < 0 || y2 < 0) {
		return 0;
	}
	if (x1 >= 2 * K || y1 >= 2 * K) {
		return 0;
	}

	if (x1 < 0)x1 = 0;
	if (y1 < 0) {y1 = 0;}
	if (x2 >= 2 * K)x2 = 2 * K - 1;
	if (y2 >= 2 * K)y2 = 2 * K - 1;

	if (x2 >= 2 * K) {
		x2 = 2 * K - 1;
	}
	if (y2 >= 2 * K) {
		y2 = 2 * K - 1;
	}
	int ans = 0;
	ans = A[x2][y2];
	if (x1) {
		ans -= A[x1 - 1][y2];
	}
	if (y1) {
		ans -= A[x2][y1 - 1];
	}
	if (x1 > 0 && y1 > 0) {
		ans += A[x1 - 1][y1 - 1];
	}
	return ans;
}
void solve() {
	int N;
	cin >> N >> K;

	vector<vector<int>> B(2 * K, vector<int>(2 * K, 0));
	vector<vector<int>> W(2 * K, vector<int>(2 * K, 0));

	for (int i = 0; i < N; ++i) {
		int X, Y; char w;
		cin >> X >> Y >> w;
		X %= 2 * K;
		Y %= 2 * K;
		if (w == 'B') {
			B[X][Y] += 1;
		}
		else {
			W[X][Y] += 1;
		}
	}
	//片方
	for (int x = 1; x < 2 * K; ++x) {
		for (int y = 0; y < 2 * K; ++y) {
			B[x][y] += B[x - 1][y];
			W[x][y] += W[x - 1][y];
		}
	}

	for (int y = 1; y < 2 * K; ++y) {
		for (int x = 0; x < 2 * K; ++x) {
			B[x][y] += B[x][y-1];
			W[x][y] += W[x][y-1];
		}
	}

	LL ans = 0;
	for (int x = 0; x < 2 * K; ++x) {
		for (int y = 0; y < 2 * K; ++y) {
			LL res = 0;
			res += f(B, x-K, y+K, x - 1, y + 2*K - 1);
			res += f(B, x, y, x + K - 1, y + K - 1);
			res += f(B, x+K, y+K, x + 2*K - 1, y + 2*K - 1);
			res += f(B, x+K, y-K, x + 2*K - 1, y - 1);
			res += f(B, x-K, y-K, x - 1, y - 1);

			//Wもやる
			res += f(W, x + K, y, x + 2 * K - 1, y + K - 1);
			res += f(W, x, y+K, x +K-1, y + K - 1);
			res += f(W, x, y-K, x + K - 1,y-1 );
			res += f(W, x - K, y, x - 1,y+K-1 );
			chmax(ans, res);
		}
	}
	cout << ans << endl;
}

signed main(void) {
	std::cin.tie(0);
	std::ios::sync_with_stdio(false);
	std::cout << std::fixed;//小数を10進数表示
	cout << setprecision(16);//小数点以下の桁数を指定//coutとcerrで別	

	solve();
}

