  for (int i = 0; i < N; i++) {
    int x, y;
    string c;
    cin >> x >> y >> c;
    x = x % (2 * K), y = y % (2 * K);
    if (c == "B") {
      board[x + 1][y + 1]++;
      sum++;
    }
    if (c == "W") {
      board[x + 1][y + 1]--;
      sum--;
      white++;
    }
  }

  for (int i = 1; i <= 2 * K; i++) {
    for (int j = 1; j <= 2 * K; j++) {
      board[i][j] += board[i][j - 1];
    }
  }
  for (int i = 1; i <= 2 * K; i++) {
    for (int j = 1; j <= 2 * K; j++) {
      board[i][j] += board[i - 1][j];
    }
  }

  int res = -(1 << 28);
  for (int i = 0; i <= K; i++) {
    for (int j = 0; j <= K; j++) {
      int a = board[i][j];
      int b =
          board[i + K][j + K] - board[i + K][j] - board[i][j + K] + board[i][j];
