void solve(int ca){
    int N,K;cin>>N>>K;
    int x,y; char c;
    int white=0;
    for (int i = 0; i < N; ++i) {
        cin>>x>>y>>c;
        if(c=='B') bcnt[x%(2*K)][y%(2*K)]++;
        else {
            wcnt[x % (2 * K)][y % (2 * K)]++;
            white++;
        }
    }

    for (int i = 0; i < 2 * K; ++i) {
        for (int j = 0; j < 2 * K; ++j) {
            bruiseki[i+1][j+1]=bcnt[i][j]+bruiseki[i+1][j]+bruiseki[i][j+1]-bruiseki[i][j];
            wruiseki[i+1][j+1]=wcnt[i][j]+wruiseki[i+1][j]+wruiseki[i][j+1]-wruiseki[i][j];
        }
    }

    int ans=0;
    for (int i = 0; i < K; ++i) {
        for (int j = 0; j < K; ++j) {
            int btmp=0,wtmp=0;
            //black

            btmp+=bruiseki[i+K][j+K]-bruiseki[i][j+K]-bruiseki[i+K][j]+bruiseki[i][j];
            btmp+=bruiseki[2*K][2*K]-bruiseki[i+K][2*K]-bruiseki[2*K][j+K]+bruiseki[i+K][j+K];
            btmp+=bruiseki[i][j];
            btmp+=bruiseki[i][2*K]-bruiseki[i][K+j];
            btmp+=bruiseki[2*K][j]-bruiseki[K+i][j];
            //white
            wtmp+=wruiseki[i+K][j+K]-wruiseki[i][j+K]-wruiseki[i+K][j]+wruiseki[i][j];
            wtmp+=wruiseki[2*K][2*K]-wruiseki[i+K][2*K]-wruiseki[2*K][j+K]+wruiseki[i+K][j+K];
            wtmp+=wruiseki[i][j];
            wtmp+=wruiseki[i][2*K]-wruiseki[i][K+j];
            wtmp+=wruiseki[2*K][j]-wruiseki[K+i][j];

            ans=max(ans,max(btmp+white-wtmp,wtmp+N-white-btmp));
        }
    }

    cout<<ans<<endl;


}

