int N, K;

long long int x[100005], y[100005];

int c[100005];

long long int B[4050][4050], W[4050][4050];

long long int diff[4050][4050];
long long int sum_diff[4050][4050];

int main(void) {

	cin >> N >> K;
	long long int tmp;
	string str;
	for (int i = 1; i <= N; i++) {
		cin >> tmp; x[i] = tmp;
		cin >> tmp; y[i] = tmp;
		cin >> str; if (str == "B") { c[i] = 1; }
		else { c[i] = 0; }
	}

	for (int i = 1; i <= N; i++) {
		if (c[i] == 1) { B[x[i] % (2 * K)][y[i] % (2 * K)]++; }
		else { W[x[i] % (2 * K)][y[i] % (2 * K)]++; }
	}

	for (int i = 0; i <= 4 * K - 1; i++) {
		for (int j = 0; j <= 4 * K - 1; j++) {
			W[i][j] = W[i % (2 * K)][j % (2 * K)];
			B[i][j] = B[i % (2 * K)][j % (2 * K)];
		}
	}

	//====== diff ============================//
	for (int i = 0; i <= 4 * K - 1; i++) {
		for (int j = 0; j <= 4 * K - 1; j++) {
			diff[i][j] = B[i][j] - W[i][j];
		}
	}

	//=== sum_diff ===============================//

	for (int i = 0; i <= 4* K ; i++) {
		sum_diff[i][4 * K] = 0;
	}
	for (int j = 0; j <= 4 * K; j++) {
		sum_diff[0][j] = 0;
	}

	for (int i = 4 * K - 1; i >= 0; i--) {
		for (int j = 4 * K - 1; j >= 0; j--) {
			sum_diff[i][j] = diff[i][j] + sum_diff[i + 1][j] + sum_diff[i][j + 1] - sum_diff[i+1][j+1];
		}
	}

	//==========================================//

/*	for (int i = 0; i <= 4 * K; i++) {
		for (int j = 0; j <= 4 * K; j++) {
			cout << " " << sum_diff[i][j];
		}cout << endl;
	}
	*/
	//====== W ================================//
	long long int count_W = 0;
	for (int i = 0; i <= 2 * K - 1; i++) {
		for (int j = 0; j <= 2 * K - 1; j++) {
			count_W += W[i][j];
		}
	}
	//==========================================//

	long long int ans = 0;

	long long int count;

	for (int I = 0; I <= 2*K-1; I++) {
		for (int J = 0; J <= 2*K-1; J++) {
			count = 0;

			count += sum_diff[I][J] - sum_diff[I + K][J] - sum_diff[I][J + K] + sum_diff[I + K][J + K];
			count += sum_diff[I + K][J + K] - sum_diff[I + 2 * K][J + K] - sum_diff[I + K][J + 2 * K] + sum_diff[I + 2 * K][J + 2 * K];

			count += count_W;

			ans = max(ans, count);
		}//J-loop fin
	}//I-loop

	cout << ans << endl;

	//system("pause");
	return 0;
}

