		int cnt = 0;
		cnt += f(x, y, x + k - 1, y + k - 1);
		cnt += f(x + k, y + k, 2 * k - 1, 2 * k - 1);
		cnt += (x && y ? f(0, 0, x - 1, y - 1) : 0);
		cnt += (x ? f(0, y + k, x - 1, 2 * k - 1) : 0);
