      b*=2;
    seg=vector<int>(2*b-1,0);
    fo(i,a.sz){
      seg[i+b-1]=a[i];
    }
    for(int i=b-2;i>=0;i--){
      seg[i]=seg[2*i+1]+seg[2*i+2];
    }
  }
  void update(int i,int a){
    i+=b-1;
    seg[i]=a;
    while(i){
      i=(i-1)/2;
      seg[i]=seg[2*i+1]+seg[2*i+2];
    }
  }
  //最初呼び出すときは要求区間x,y+1(yは添え字+1)とa=0,l=0,r=INFで
  //l,rは探すところ
  int getadd(int x,int y,int a,int l,int r){
    if(r==INF)
      r=b;
    if(r<=x||y<=l)
      return 0;
    if(x<=l&&r<=y)
      return seg[a];
    int a1=getadd(x,y,2*a+1,l,(l+r)/2);
    int a2=getadd(x,y,2*a+2,(l+r)/2,r);
    return a1+a2;
  }
};
signed main(){
  int a,b;
  cin>>a>>b;
  V<P<P<int,int>,int>> c(a);
  fo(i,a){
    char d;
    cin>>c[i].ff>>c[i].fs>>d;
    c[i].se=(d=='B');
  }
  int x=b-1;
  V<V<P<int,int>>> f(b*2-1,V<P<int,int>>(b*2-1));
  fo(i,a){
    int d=c[i].ff/b%2;
    int d1=c[i].ff%b;
    int e=c[i].fs/b%2;
    int e1=c[i].fs%b;
    int g=(c[i].se+d+e)%2;
    for(int i=d1;i+x>=0;i-=b){
      for(int j=d2;j+x>=0;j-=b){
        if(g)
          f[i+x][j+x].se++;
        else
          f[i+x][j+x].fi++;
      }
    }
    int d=0;
    V<V<P<int,int>>> f1(b*2,V<P<int,int>>(b*2));
    fo(i,b*2-1){
      fo(j,b*2-1){
        f1[i+1][j+1].fi=f[i][j].fi+f1[i][j+1].fi+f1[i+1][j].fi-f1[i][j].fi;
        f1[i+1][j+1].se=f[i][j].se+f1[i][j+1].se+f1[i+1][j].se-f1[i][j].se;
      }
    }
    for(int i=b;i<b*2;i++){
      for(int j=b;j<b*2;j++){
        d=max(d,f1[i][j].se-f1[i-b][j].se-f1[i][j-b].se+f1[i-b][j-b].se);
        d=max(d,f1[i][j].fi-f1[i-b][j].fi-f1[i][j-b].fi+f1[i-b][j-b].fi);
      }
    }
    cout<<d<<endl;
  }
}

