using std::cout;
using std::endl;
using std::cin;
using std::max;

int X[100'010];
int Y[100'010];
const bool WHITE = true;
const bool BLACK = !WHITE;
bool C[100'010];

// Number of points as white. Area [(0,0)..(2K,2K)]
int plane[2'010][2'010];
// cumulative[x][y] := Number of points in [(0,0)..(x,y))
int cumulative[2'010][2'010];

/* Return number of points in
 * [(lx,ly)..(hx..hy))
 * lx/ly: low x/y
 * hx/hy: high x/y
 */
int query(int lx, int ly, int hx, int hy) {
	if(lx > hx || ly > hy) return 0;
	return cumulative[hx][hy]
			- cumulative[lx][hy]
			- cumulative[hx][ly]
			+ cumulative[lx][ly];
}

int main() {
	// Input
	int N;
	int K;
	cin >> N >> K;
	const int k2 = 2 * K;
	for(int i = 0; i < N; ++i) {
		char c;
		cin >> X[i] >> Y[i] >> c;
		C[i] = c == 'W'? WHITE : BLACK;
	}
	// Preparation
	for(int i = 0; i < N; ++i) {
		int x = X[i];
		int y = Y[i];
		if(C[i] == BLACK) x += K;
		x %= k2;
		y %= k2;
		++plane[x][y];
	}
	for(int x = 1; x <= k2; ++x) {
	for(int y = 1; y <= k2; ++y) {
		cumulative[x][y] = cumulative[x-1][y] + cumulative[x][y-1] - cumulative[x-1][y-1] + plane[x-1][y-1];
	}
	}
	// Calculation
	int ans = 0;
	for(int x = 0; x < K; ++x) {
	for(int y = 0; y < K; ++y) {
		int w = query(x, y, x+K+1, y+K+1);
		ans = max(ans, w);
	}
	}
	// Output
	cout << ans << endl;
	return 0;
}

