using namespace std;
const int MAX = 1024;

int main() {
	int n, k;
	cin >> n >> k;
	int a[MAX][MAX] = {}, b[MAX][MAX] = {};
	for (int i = 0; i < n; i++) {
		int x, y;
		char c;
		cin >> x >> y >> c;
		int ci = c == 'B' ? 1 : 0;
		x %= 2*k; y %= 2*k;
		if (x >= k) x -= k, ci = 1 - ci;
		if (y >= k) y -= k, ci = 1 - ci;
		if (ci == 0) a[x][y] += 1;
		else b[x][y] += 1;
	}
	int sa[MAX][MAX] = {}, sb[MAX][MAX] = {};
	for (int i = 0; i < k; i++) {
		for (int j = 0; j < k; j++) {
			sa[i+1][j+1] = a[i][j];
			sb[i+1][j+1] = b[i][j];
		}
	}
	for (int i = 1; i <= k; i++) {
		for (int j = 1; j <= k; j++) {
			sa[i][j] += sa[i][j-1];
			sb[i][j] += sb[i][j-1];
		}
	}
	for (int i = 1; i <= k; i++) {
		for (int j = 1; j <= k; j++) {
			sa[i][j] += sa[i-1][j];
			sb[i][j] += sb[i-1][j];
		}
	}
	auto sum_rect_a = [&](int x0, int y0, int x1, int y1) {
		return sa[x1][y1] - sa[x0][y1] - sa[x1][y0] + sa[x0][y0];
	};
	auto sum_rect_b = [&](int x0, int y0, int x1, int y1) {
		return sb[x1][y1] - sb[x0][y1] - sb[x1][y0] + sb[x0][y0];
	};
	int ans = 0;
	for (int i = 0; i < k; i++) {
		for (int j = 0; j < k; j++) {
			int now = sum_rect_a(0,0,i,j) + sum_rect_a(i,j,k,k);
			now += sum_rect_b(i,0,k,j) + sum_rect_b(0,j,i,k);
			now = max(now, n-now);
			ans = max(ans, now);
		}
	}
	cout << ans << endl;
	return 0;
}

