        x %= k;
        y %= k;
        if(s == 'W')cw[y][x]++;
        else cb[y][x]++;
    }
    vector<vector<int>> w(k, vector<int>(k, 0)), b(k, vector<int>(k, 0));
    w[0][0] = cw[0][0];
    b[0][0] = cb[0][0];
    rep(x, k)rep(y, k){
        if(x == 0 && y == 0)continue;
        else if(x == 0){
            w[y][x] = w[y-1][x] + cw[y][x];
            b[y][x] = b[y-1][x] + cb[y][x];
        }else if(y == 0){
            w[y][x] = w[y][x-1] + cw[y][x];
            b[y][x] = b[y][x-1] + cb[y][x];
        }else{
            w[y][x] = w[y-1][x] + w[y][x-1] - w[y-1][x-1] + cw[y][x];
            b[y][x] = b[y-1][x] + b[y][x-1] - b[y-1][x-1] + cb[y][x];
        }
    }

    int ans = 0;
    rep(x, k)rep(y, k){
        int sum1 = w[k-1][k-1] - w[k-1][x] - w[y][k-1] + 2 * w[y][x];
        sum1 += b[k-1][x] + b[y][k-1] - 2 * b[y][x];
        int sum2 = b[k-1][k-1] - b[k-1][x] - b[y][k-1] + 2 * b[y][x];
        sum2 += w[k-1][x] + w[y][k-1] - 2 * w[y][x];
        ans = max({ans, sum1, sum2});
    }
    cout << ans << endl;
}

