template <class T>
struct CumlativeSum2 {
    vector<vector<T>> sum;
    CumlativeSum2(int h, int w):sum(h+1, vector<T>(w+1, 0)){};

    // 1-indexedだとそのままの入力でOK
    void add(int x, int y, T z) {
        sum[x][y] += z;
    }

    void build() {
        for(int i = 1; i < size(sum); i++) {
            for(int j = 1; j < size(sum[i]); j++) {
                sum[i][j] += sum[i][j-1]+sum[i-1][j]-sum[i-1][j-1];
            }
        }
    }

    //1-indexだとsx, syの方を-1する必要あり, 0-indexedだとgx, gyの方を+1
    T q(int sx, int sy, int gx, int gy) {
        return sum[gx][gy]-sum[sx][gy]-sum[gx][sy]+sum[sx][sy];
    }
};

