    vector<char> c(n);
    for (int i = 0; i < n; ++i) {
        cin >> x[i] >> y[i] >> c[i];
    }
    vvl white(k, vl(k, 0));
    vvl black(k, vl(k, 0));
    for (int i = 0; i < n; ++i) {
        if (c[i] == 'W') {
            if ((y[i] / k + x[i] / k) % 2 == 0)
                white[y[i] % k][x[i] % k]++;
            else
                black[y[i] % k][x[i] % k]++;
        }
        if (c[i] == 'B') {
            if ((y[i] / k + x[i] / k) % 2 == 0)
                black[y[i] % k][x[i] % k]++;
            else
                white[y[i] % k][x[i] % k]++;
        }
    }
    for (int i = 1; i < k; ++i) {
        for (int j = 0; j < k; ++j) {
            white[i][j] += white[i - 1][j];
            black[i][j] += black[i - 1][j];
        }
    }
    for (int i = 1; i < k; ++i) {
        for (int j = 0; j < k; ++j) {
            white[j][i] += white[j][i - 1];
            black[j][i] += black[j][i - 1];
        }
    }
    int ret = 0;
    for (int i = 0; i < k; ++i) {
        for (int j = 0; j < k; ++j) {
            int temp = 0;
            temp += black[k - 1][k - 1];
            if (i - 1 >= 0) {
                temp -= black[i - 1][k - 1];
                temp += white[i - 1][k - 1];
            }
            if (j - 1 >= 0) {
                temp -= black[k - 1][j - 1];
                temp += white[k - 1][j - 1];
            }
            if (i - 1 >= 0 && j - 1 >= 0) {
                temp += 2 * black[i - 1][j - 1];
                temp -= white[i - 1][j - 1];
            }
            chmax(ret, temp);
        }
    }
    cout << ret << "\n";

    return 0;
}

