			//y.push_back(j);
		//}
        for (size_t j = (v[i][0] + 1); j < 4 * K; j+=K) {
            x.push_back(j);
        }
        for (size_t j = (v[i][1] + 1); j < 4 * K; j+=K) {
            y.push_back(j);
        }
		// K * Kになるものだけを重みに加算する
		for (size_t j = 0; j < x.size(); j++) {
			for (size_t k = 0; k < y.size()/2; k++) {
                int xx = x[j];
                int yy = y[k*2+k%2];
				xy[xx][yy]++;
				if (yy + K < 4 * K) {
					xy[xx][yy+K]--;
				}
				if (xx + K < 4 * K) {
					xy[xx+K][yy]--;
				}
				if (xx + K < 4 * K && yy + K < 4 * K) {
					xy[xx+K][yy+K]++;
				}
			}
		}
