	int ans = 0;
	char color;
	int count;
	int a, b, c, d, e;

	cin >> N >> K;
	K2 = K * 2;
	int black[K2 + 1][K2 + 1] = {};

	for (int i = 0; i < N; i++)
	{
		cin >> x >> y >> color;
		if (color == 'B')
		{
			black[x % K2 + 1][y % K2 + 1]++;
		}
		else
		{
			black[(x + K) % K2 + 1][y % K2 + 1]++;
		}
	}

	for (int i = 0; i <= K2; i++)
		for (int j = 0; j <= K2 - 1; j++)
			black[i][j + 1] = black[i][j + 1] + black[i][j];

	for (int i = 0; i <= K2; i++)
		for (int j = 0; j <= K2 - 1; j++)
			black[j + 1][i] = black[j + 1][i] + black[j][i];

	for (int i = 0; i <= K; i++)
		for (int j = 0; j <= K; j++)
		{
			count = 0;

			count += black[i][j];
			count += black[K2][j] - black[i + K][j];
			count += black[i][K2] - black[i][j + K];
			count += black[K2][K2] - black[K2][j + K] - black[i + K][K2] + black[i + K][j + K];
			count += black[i + K][j + K] - black[i][j + K] - black[i + K][j] + black[i][j];

			ans = max(ans, count);
		}

	cout << ans << endl;
}

