struct D2SUM {

  /*　使い方まとめ　*/

  /*

  D2SUM iisum(mapp) // 宣言 mappは求めたい累積和のやつ
  iisum.sum(a,b,c,d) // 縦a~b、横c~dの和を求める(0-index)

  */

  VVi d2;

  D2SUM (VVi a) : d2(0,Vi(0)) {
    int h = a.size() + 1;
    int w = a[0].size() + 1;
    d2 = VVi(h,Vi(w,0));
    rep(i,0,h-1){
      rep(j,0,w-1){
        d2[i+1][j+1] = a[i][j];
      }
    }
    rep(i,1,h){
      rep(j,1,w){
        d2[i][j] += d2[i][j-1] + d2[i-1][j] - d2[i-1][j-1];
      }
    }
  }

  int sum(int h1,int h2,int w1,int w2) {
    int ret = d2[h2+1][w2+1]-d2[h1][w2+1]-d2[h2+1][w1]+d2[h1][w1];
    return ret;
  }

};

signed main() {
  cin.tie(0);cout.tie(0);ios::sync_with_stdio(false);cout<<fixed<<setprecision(12);
  int n,k;
  cin >> n >> k;
  //VVi mapp(2*k,Vi(2*k));

  int m = 2*k;
  Vi a(n),b(n),c(n);
  char ch;

  rep(i,0,n){
    cin >> a[i] >> b[i] >> ch;
    if(ch=='B') c[i] = 1; // 1がB
    else c[i] = 0;
    a[i] %= m;
    b[i] %= m;
  }

  VVi mappW(k,Vi(k)),mappB;
  mappB = mappW;

  rep(i,0,n){

    if( (a[i]<k && b[i]<k) || (a[i]>=k && b[i]>=k) ){
      if(c[i]){
        mappB[(a[i]%k)][(b[i]%k)]++;
      }
      else {
        mappW[(a[i]%k)][(b[i]%k)]++;
      }
    }

    else {
      if(!c[i]){
        mappB[(a[i]%k)][(b[i]%k)]++;
      }
      else {
        mappW[(a[i]%k)][(b[i]%k)]++;
      }
    }
  }

  /*　使い方まとめ　*/

  /*

  D2SUM iisum(mapp) // 宣言 mappは求めたい累積和のやつ
  iisum.sum(a,b,c,d) // 縦a~b、横c~dの和を求める(0-index)

  */
  int ans = 0;

  D2SUM wh(mappW),bl(mappB);

  rep(i,0,k){
    rep(j,0,k){
      int ct1=0,ct2=0;
      if(i==0 && j==0){
        ct1 = wh.sum(0,k-1,0,k-1);
        ct2 = bl.sum(0,k-1,0,k-1);
      }
      else if(i==0){
        ct1 = wh.sum(0,k-1,0,j-1)+bl.sum(0,k-1,j,k-1);
        ct2 = bl.sum(0,k-1,0,j-1)+wh.sum(0,k-1,j,k-1);
      }
      else if(j==0){
        ct1 = wh.sum(0,i-1,0,k-1)+bl.sum(i,k-1,0,k-1);
        ct2 = bl.sum(0,i-1,0,k-1)+wh.sum(i,k-1,0,k-1);
      }
      else {
        ct1 = wh.sum(0,i-1,0,j-1)+wh.sum(i,k-1,j,k-1);
        ct1 += bl.sum(0,i-1,j,k-1)+bl.sum(i,k-1,0,j-1);
        ct2 = bl.sum(0,i-1,0,j-1)+bl.sum(i,k-1,j,k-1);
        ct2 += wh.sum(0,i-1,j,k-1)+wh.sum(i,k-1,0,j-1);
      }
      //cerr << ct1 <<' ' << ct2 << endl;
      ans = max({ans,ct1,ct2});
    }
  }

  cout << ans << endl;
  return 0;
}

