//i=j=0の時にはget(i,j)でk～2k四角形、get(i+k,j+k)で0～k(2k～3k)の四角形を探索している。

int get(int x , int y){
    return Cumulative_sum[x+k-1][y+k-1] + Cumulative_sum[x-1][y-1] - Cumulative_sum[x-1][y+k-1] - Cumulative_sum[x+k-1][y-1];
