			++res[i];
		}
	}
	if (n != 1) ++res[n];
	return res;
}

class CumculativeSum2D {
private:

	vector<vector<int>> dat;

public:

	CumculativeSum2D(const vector<vector<int>>& vec) {
		const int h = vec.size(), w = vec[0].size();

		dat.resize(h + 1, vector<int>(w + 1));

		for (int i = 0; i < h; ++i) {
			for (int j = 0; j < w; ++j) {
				dat[i + 1][j + 1] 
					= dat[i][j + 1] + dat[i + 1][j] - dat[i][j] + vec[i][j];
			}
		}
	}

	// [0, x) × [0, y)
	int get_sum(int x, int y) const {
		return get_sum(0, 0, x, y);
	}

	// [x1, x2) × [y1, y2)
	int get_sum(int x1, int y1, int x2, int y2) const {
		return dat[x2][y2] - dat[x1][y2] - dat[x2][y1] + dat[x1][y1];
	}
};

