			if (c == 'W') c = 'B';
			else c = 'W';
		}

		x %= k; y %= k;

		if (c == 'W') ++white[x][y];
		else ++black[x][y];
	}

	const CumculativeSum2D white_sum(white), black_sum(black);

	rep(i, k + 1) {
		rep(j, k + 1) {
			const int cnt1
				= white_sum.get_sum(0, 0, i, j) 
				+ white_sum.get_sum(i, j, k, k)
				+ black_sum.get_sum(0, j, i, k)
				+ black_sum.get_sum(i, 0, k, j);

			// 白黒反転
			const int cnt2
				= black_sum.get_sum(0, 0, i, j)
				+ black_sum.get_sum(i, j, k, k)
				+ white_sum.get_sum(0, j, i, k)
				+ white_sum.get_sum(i, 0, k, j);

			ans = max({ ans,cnt1,cnt2 });
		}
	}

	cout << ans << endl;
}

#include <iostream>

class Check {
    uint32_t ** m;
    int k;
    std::string c;
public:
    Check(int k, const std::string &c) {
        this->c = c;
        this->k = k;
        this->m = new uint32_t *[k+1];
        for (int i = 0; i < this->k + 1; ++i) {
            this->m[i] = new uint32_t[k + 1]();
        }
    }

    void inc(int xMin, int xMax, int yMin, int yMax) {
        for (int i = xMin; i < xMax; ++i) {
            for (int j = yMin; j < yMax; ++j) {
                this->m[i][j]++;
            }
        }
    }

    void addDesire(int x, int y, const std::string &c) {
        int cx = x + 1;
        int cy = y + 1;

        if (c == this->c) {
            this->inc(0, cx, 0, cy);
            this->inc(cx, this->k+1, cy, this->k+1);
        } else {
            this->inc(0, cx, cy, this->k+1);
            this->inc(cx, this->k+1, 0, cy);
        }
    }

    int getMax() {
        int _max = 0;
        for (int i = 0; i < this->k + 1; ++i) {
            for (int j = 0; j < this->k + 1; ++j) {
                if (this->m[i][j] > _max){
                    _max = this->m[i][j];
                }
            }
        }

        return _max;
    }

    ~Check() {
        for (int i = 0; i < this->k; ++i) {
            delete[](this->m[i]);
        }
        delete[](this->m);
    }
};

int main() {
    int n, k;
    std::cin >> n >> k;
    Check checkW = Check(k, "W");

    for (int i = 0; i < n; ++i) {
        int x, y;
        std::string c;
        std::cin >> x >> y >> c;

        x = x < 0 ? -1*x+k-1 : x;
        y = y < 0 ? -1*y+k-1 : y;

        int bigX = x/k;
        int bigY = y/k;

        int localX = x%k;
        int localY = y%k;
        std::string localC = c;

        if ((bigX+bigY)% 2 != 0) {
            localC = localC == "W" ? "B" : "W";
        }

        checkW.addDesire(localX, localY, localC);
    }

    std::cout << checkW.getMax() << std::endl;

    return 0;
}

