// 二次元累積和
int sum[2005][2005];

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    for(int i = 0; i < n; ++i){
        int x, y;
        char c;
        cin >> x >> y >> c;

        // すべて(c='B')にして、([0, 2k), [0, 2k))に圧縮
        if(c == 'W'){
            y += k;
        }
        x %= 2 * k;
        y %= 2 * k;

        ++sum[x + 1][y + 1];
    }

    // 二次元累積和
    // 横方向の累積和
    for(int i = 0; i <= 2 * k; ++i){
        for(int j = 0; j <= 2 * k; ++j){
            sum[i][j+1] += sum[i][j];
        }
    }
    // 縦方向の累積和
    for(int i = 0; i <= 2 * k; ++i){
        for(int j = 0; j <= 2 * k; ++j){
            sum[i+1][j] += sum[i][j];
        }
    }

    int res = 0;
    // (0, 0) ~ (2k-1, 2k-1)
    for(int tx = 0; tx < 2 * k; ++tx){
        for(int ty = 0; ty < 2 * k; ++ty){
                int temp = 0;

                // ([0, 2k), [0, 2k))内の5つの黒に塗る部分に関して、点の数を足し合わせる
                if(tx < k && ty < k){
                    temp += sum[tx][ty];
                    temp += sum[tx+k][ty+k] - sum[tx+k][ty] - sum[tx][ty+k] + sum[tx][ty];
                    temp += sum[2*k][ty] - sum[tx+k][ty];
                    temp += sum[tx][2*k] - sum[tx][ty+k];
                    temp += sum[2*k][2*k] - sum[2*k][ty+k] - sum[tx+k][2*k] + sum[tx+k][ty+k];
                }
                else if(tx >= k && ty >= k){
                    temp += sum[tx-k][ty-k];
                    temp += sum[tx][ty] - sum[tx][ty-k] - sum[tx-k][ty] + sum[tx-k][ty-k];
                    temp += sum[2*k][ty-k] - sum[tx][ty-k];
                    temp += sum[tx-k][2*k] - sum[tx-k][ty];
                    temp += sum[2*k][2*k] - sum[2*k][tx] - sum[ty][2*k] + sum[tx][ty];
                }
                else if(tx < k){
                    temp += sum[tx][ty] - sum[tx][ty-k];
                    temp += sum[tx+k][ty-k] - sum[tx][ty-k];
                    temp += sum[tx+k][2*k] - sum[tx][2*k] - sum[tx+k][ty] + sum[tx][ty];
                    temp += sum[2*k][ty] -sum[tx+k][ty] - sum[2*k][ty-k] + sum[tx+k][ty-k];
                }
                else{   // ty < k
                    temp += sum[tx][ty] - sum[tx-k][ty];
                    temp += sum[tx-k][ty+k] - sum[tx-k][ty];
                    temp += sum[2*k][ty+k] - sum[2*k][ty] - sum[tx][ty+k] + sum[tx][ty];
                    temp += sum[tx][2*k] - sum[tx][ty+k] - sum[tx-k][2*k] + sum[tx-k][ty+k];
                }

                res = max(res, temp);
        }
    }

    cout << res << endl;
}

