const int MAXK = 1000;
int a[2 * MAXK + 5][2 * MAXK + 5][2];
int Sum(int x1,int x2,int y1,int y2,int t) {
	return a[x2][y2][t] - a[x1-1][y2][t] - a[x2][y1-1][t] + a[x1-1][y1-1][t];
}
int main() {
	int N, K, Max = 0, cnt = 0;
	scanf("%d%d",&N,&K);
	for(int i=1;i<=N;i++) {
		int x, y;char ch;
		scanf("%d%d %c",&x,&y,&ch);
		x = x % (2*K);y = y % (2*K);
		if( ch == 'W' ) a[x][y][1]++;
		else a[x][y][0]++;
	}
	for(int i=0;i<2*K;i++) {
		for(int j=0;j<2*K;j++) {
			a[i][j][0] += a[i][j-1][0] + a[i-1][j][0] - a[i-1][j-1][0];
			a[i][j][1] += a[i][j-1][1] + a[i-1][j][1] - a[i-1][j-1][1];
		}
	}
	for(int i=0;i<=K;i++) {
		for(int j=0;j<=K;j++) {
			int ii = i+K-1, jj = j+K-1;
			int cntb = 0, cntw = 0;
			if( i != 0 ) {
				if( j != 0 )
					cntb += Sum(0,i-1,0,j-1,1);
				if( j != K )
					cntb += Sum(0,i-1,jj+1,2*K-1,1);
				cntw += Sum(0,i-1,j,jj,0);
			}
			if( j != 0 )
				cntw += Sum(i,ii,0,j-1,0);
			if( j != K )
				cntw += Sum(i,ii,jj+1,2*K-1,0);
			cntb += Sum(i,ii,j,jj,1);
			if( i != K ) {
				if( j != 0 )
					cntb += Sum(ii+1,2*K-1,0,j-1,1);
				if( j != K )
					cntb += Sum(ii+1,2*K-1,jj+1,2*K-1,1);
				cntw += Sum(ii+1,2*K-1,j,jj,0);
			}
			if( cntw + cntb > Max ) Max = cntw + cntb;
			if( N - cntw - cntb > Max ) Max = N - cntw - cntb;
		}
	}
	printf("%d\n",Max);
}

