int cW(int i, int j)
{
    int n = 2 * k, m = 2 * k;
    if (i < 0 || j < 0) return 0;
    int res = 0;
    if (i < n && j < m) return w[i][j];
    if (i >= n && j < m) return w[n - 1][j] + w[i - n][j];
    if (i < n && j >= m) return w[i][m - 1] + w[i][j - m];
    if (i >= n && j >= m) return w[n - 1][m - 1] + w[i - n][j - m] + w[n - 1][j - m] + w[i - n][m - 1];
}

int cB(int i, int j)
{
    int n = 2 * k, m = 2 * k;
    if (i < 0 || j < 0) return 0;
    int res = 0;
    if (i < n && j < m) return b[i][j];
    if (i >= n && j < m) return b[n - 1][j] + b[i - n][j];
    if (i < n && j >= m) return b[i][m - 1] + b[i][j - m];
    if (i >= n && j >= m) return b[n - 1][m - 1] + b[i - n][j - m] + b[n - 1][j - m] + b[i - n][m - 1];
}

int getW(int i1, int j1, int i2, int j2)
{
    return cW(i2, j2) - cW(i1 - 1, j2) - cW(i2, j1 - 1) + cW(i1 - 1, j1 - 1);
}

int getB(int i1, int j1, int i2, int j2)
{
    return cB(i2, j2) - cB(i1 - 1, j2) - cB(i2, j1 - 1) + cB(i1 - 1, j1 - 1);
}

int main()
{
    cin >> n >> k;
    for (int i = 0; i < n; i++)
    {
        char c;
        cin >> x[i] >> y[i] >> c;
        x[i] %= 2 * k;
        y[i] %= 2 * k;
        if (c == 'W')
            w[x[i]][y[i]]++;
        else
            b[x[i]][y[i]]++;
    }
    for (int i = 0; i < 2 * k; i++)
    {
        for (int j = 0; j < 2 * k; j++)
        {
            w[i][j] += (i > 0) ? w[i - 1][j] : 0;
            w[i][j] += (j > 0) ? w[i][j - 1] : 0;
            w[i][j] -= (i > 0 && j > 0) ? w[i - 1][j - 1] : 0;
            b[i][j] += (i > 0) ? b[i - 1][j] : 0;
            b[i][j] += (j > 0) ? b[i][j - 1] : 0;
            b[i][j] -= (i > 0 && j > 0) ? b[i - 1][j - 1] : 0;
        }
    }
    for (int i = 0; i < 2 * k; i++)
    {
        for (int j = 0; j < 2 * k; j++)
        {
            int res = getW(i, j, i + k - 1, j + k - 1) + getW(i + k, j + k, i + 2 * k - 1, j + 2 * k - 1);
            res += getB(i + k, j, i + 2 * k - 1, j + k - 1) + getB(i, j + k, i + k - 1, j + 2 * k - 1);
            ans = max(ans, res);
        }
    }
    cout << ans;
}

