// カウント
ll C[4000][4000] = {};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    // input
    ll N, K;
    cin >> N >> K;

    ll K2 = 2 * K;
    ll K4 = 4 * K;

    FOR(i, 0, N){
        ll x, y;
        char c;
        cin >> x >> y >> c;

        // すべてBに変換する
        if(c=='W'){
            x += K;
            c = 'B';
        }

        // 2K x 2K の領域に収める
        x = x % (2*K);
        y = y % (2*K);

        C[y][x]++;
    }

    // 4K x 4Kの領域にコピー
    FOR(i, 0, K2){
        FOR(j, 0, K2){
            C[j+K2][i] = C[j][i];
            C[j][i+K2] = C[j][i];
            C[j+K2][i+K2] = C[j][i];
        }
    }

    // Cをそのまま累積和にする

    // 1. 横の累積和
    FOR(i, 0, K4){
        FOR(j, 1, K4){
            C[i][j] += C[i][j-1];
        }
    }

    // 2. 縦の累積和
    FOR(j, 0, K4){
        FOR(i, 1, K4){
            C[i][j] += C[i-1][j];
        }
    }

    ll count_max = 0;
    // 左下の点を2K, 2Kの領域で動かしながらそれぞれカウントする
    FOR(i, 0, K2){
        FOR(j, 0, K2){
            // 右上のカウント
            ll count0 = C[i+K2][j+K2] - C[i+K][j+K2] - C[i+K2][j+K] + C[i+K][j+K];
            // 左下のカウント
            ll count1 = C[i+K][j+K] - C[i+K][j] - C[i][j+K] + C[i][j];
            ll count = count0 + count1;

            count_max = max(count_max, count);
        }
    }

    p(count_max);

    return 0;
}

