int main()
{
    int n, k;
    int i, j, l, p, judge = 0, max = 0;

    cin >> n >> k;

    int x[n], y[n];
    char c[n];
    int countx[2*k], county[2*k];

    for(i = 0; i < 2*k; i++) {
        countx[i] = 0;
        county[i] = 0;
    }

    for(i = 0; i < n; i++) {
        cin >> x[i] >> y[i] >> c[i];

        x[i] = x[i] % (2*k);
        y[i] = y[i] % (2*k);

        if(c[i] == 'B') {
            if((x[i] >= k) && (y[i] >= k)) {
                x[i] = x[i] - k;
                y[i] = y[i] - k;
            } else if((x[i] < k) && (y[i] >= k)) {
                x[i] = x[i] + k;
                y[i] = y[i] - k;
            }
        } else {
            if(x[i] >= k) {
                x[i] = x[i] - k;
            } else {
                x[i] = x[i] + k;
            }

            if(y[i] >= k) {
                y[i] = y[i] - k;
            } else {
                y[i] = y[i] + k;
            }
        }

        countx[x[i]]++;
        county[y[i]]++;
    }

    for(j = 0; j < k; j++) {
        judge = judge + countx[j];
    }

    p = judge;
    max = judge;

    for(l = 0; l < k; l++) {
        judge = judge - countx[l] + countx[k+l];

        if(judge > max) {
            max = judge;
        }
    }

    judge = p;

    for(l = 0; l < k; l++) {
        judge = judge - county[l] + county[k+l];

        if(judge > max) {
            max = judge;
        }
    }


    cout << max << endl;

    return 0;
}

