			int tmp = csum.sum(0, 0, i, j) + csum.sum(i, j, k, k) +
					  csum.sum(i + k, 0, 2 * k - (i + k), j) +
					  csum.sum(0, j + k, i, 2 * k - (j + k)) +
					  csum.sum(i + k, j + k, 2 * k - (i + k), 2 * k - (j + k));
			ans = max(ans, tmp);
