int main(){
  int N, K;
  cin >> N >> K;
  vector< vector<int> > B(2*K+1,vector<int>(2*K+1,0)), W = B;
  for(int i = 0; i < N; ++i){
    int x, y;
    char c;
    cin >> x >> y >> c;
    x %= 2*K;
    y %= 2*K;
    ++x;
    ++y;
    if(c == 'B') ++B[x][y];
    else ++W[x][y];
  }
  for(int i = 0; i <= 2*K; ++i){
    for(int j = 0; j < 2*K; ++j){
      W[i][j+1] += W[i][j];
      B[i][j+1] += B[i][j];
    }
  }
  for(int i = 0; i < 2*K; ++i){
    for(int j = 0; j <= 2*K; ++j){
      W[i+1][j] += W[i][j];
      B[i+1][j] += B[i][j];
    }
  }
  int ans = 0;
  for(int i = 1; i <= K; ++i){
    for(int j = 1; j <= K; ++j){
      int t = W[i+K-1][j+K-1] - W[i-1][j+K-1] - W[i+K-1][j-1] + W[i-1][j-1]
        + W[i-1][j-1]
        + B[i-1][j+K-1] - B[i-1][j-1]
        + B[i+K-1][j-1] - B[i-1][j-1]
        + W[2*K][j-1] - W[i+K-1][j-1]
        + W[i-1][2*K] - W[i-1][j+K-1]
        + B[2*K][j+K-1] - B[i+K-1][j+K-1] - B[2*K][j-1] + B[i+K-1][j-1]
        + B[i+K-1][2*K] - B[i+K-1][j+K-1] - B[i-1][2*K] + B[i-1][j+K-1]
        + W[2*K][2*K] - W[2*K][j+K-1] - W[i+K-1][2*K] + W[i+K-1][j+K-1];
      ans = max({ans, t, N-t});
    }
  }
  cout << ans << endl;
  return 0;
}

