int cnt[2][4005][4005];

int getCount(int xmax, int ymax, int xmin, int ymin, int color){
    if (xmin == 0 && ymin == 0) return cnt[color][xmax][ymax];
    if (xmin == 0) return cnt[color][xmax][ymax]-cnt[color][xmax][ymin-1];
    if (ymin == 0) return cnt[color][xmax][ymax]-cnt[color][xmin-1][ymax];
    return cnt[color][xmax][ymax] + cnt[color][xmin-1][ymin-1] - cnt[color][xmin-1][ymax] - cnt[color][xmax][ymin-1];
}
int main(){
    int n, k;
    scanf("%d%d",&n, &k);
    char str[2];
    int x, y;
    for(int i = 0; i < n; i ++){
        scanf("%d%d%s", &x, &y, str);
        x %= 2*k;
        y %= 2*k;
        int color = (str[0]=='W')?0:1;
        cnt[color][x][y] ++;
        cnt[color][x+2*k][y] ++;
        cnt[color][x][y+2*k] ++;
        cnt[color][x+2*k][y+2*k] ++;
    }
    for(int color = 0; color < 2; color ++){
        for(int i = 1; i < 4*k; i ++){
            cnt[color][0][i] += cnt[color][0][i-1];
        }
        for(int i = 1; i < 4*k; i ++){
            for(int j = 0; j < 4*k; j ++){
                if (j == 0) cnt[color][i][j] += cnt[color][i-1][j];
                else cnt[color][i][j] += cnt[color][i][j-1] + cnt[color][i-1][j] - cnt[color][i-1][j-1];
            }
        }
    }
    int ans = 0;
    for(int i = 0; i < 2*k; i ++){
        for(int j = 0; j < k; j ++){
            int a = getCount(i+k-1, j+k-1, i, j, 0);
            int b = getCount(i+k-1, j+2*k-1, i, j+k, 1);
            int c = getCount(i+2*k-1, j+k-1, i+k, j, 1);
            int d = getCount(i+2*k-1, j+2*k-1, i+k, j+k, 0);
            ans = max(ans, a+b+c+d);
        }
    }
    printf("%d\n", ans);

}

