int N, K;

void prepare(void) {
    rep(i, K * 2 + 2) {
        rep(j, K * 2 + 2) {
            sum[i+1][j+1] = dot[i+1][j+1] + sum[i][j+1] + sum[i+1][j] - sum[i][j];
            //cout << "s[" << i+1 << "][" << j+1 << "] = " << sum[i+1][j+1] << endl;
        }
    }
}

int query(int x1, int y1, int x2, int y2) {
    if(x1 > x2 || y1 > y2) return 0;
    else return sum[x2][y2] - sum[x1-1][y2] - sum[x2][y1-1] + sum[x1-1][y1-1]; 
}


