    for(int x = 1; x <= K; x++) {
        for(int y = 1; y <= K; y++) {
            tmp = query(x, y, x+K-1, y+K-1) + query(x + K, y + K, K*2, K*2) + query(1,1,x-1,y-1)
                  + query(x+K, 1, K*2, y-1) + query(1, y+K, x-1, K*2); 
