        REP(j, 1, 2 * K + 1) {
            Sb[i][j] = Sb[i - 1][j] + Sb[i][j - 1] - Sb[i - 1][j - 1] + field_black[i - 1][j - 1];
            Sw[i][j] = Sw[i - 1][j] + Sw[i][j - 1] - Sw[i - 1][j - 1] + field_white[i - 1][j - 1];
        }
