            int Ec5 = Sc1 - 1;
            if (Ec5 >= Sc5 && Er5 >= Sr5) {
                count_b += Sb[Er5][Ec5] - Sb[Sr5 - 1][Ec5] - Sb[Er5][Sc5 - 1] + Sb[Sr5 - 1][Sc5 - 1];
                count_w += Sw[Er5][Ec5] - Sw[Sr5 - 1][Ec5] - Sw[Er5][Sc5 - 1] + Sw[Sr5 - 1][Sc5 - 1];
            }

            ll score = count_b + (white_num - count_w);
            max_score = max(max_score, score);
        }
    }
    cout << max_score << endl;
    return 0;
}

