#include <bits/stdc++.h>
using namespace std;

int calc_accumulate(const vector<vector<vector<int>>> &f, int c, int x, int y, int k)
{
    int ret = 0;
    ret += f[c][x + k - 1][y + k - 1];
    if (x > 0)
    {
        ret -= f[c][x - 1][y + k - 1];
    }
    if (y > 0)
    {
        ret -= f[c][x + k - 1][y - 1];
    }
    if (x > 0 && y > 0)
    {
        ret += f[c][x - 1][y - 1];
    }
    return ret;
}

int main()
{
    int N, K;
    cin >> N >> K;

    long long x, y;
    char c;
    vector<vector<vector<int>>> field(2, vector<vector<int>>(4 * K, vector<int>(4 * K, 0)));
    for (int i = 0; i < N; i++)
    {
        cin >> x >> y >> c;
        x %= 2 * K;
        y %= 2 * K;
        if (c == 'B')
        {
            field[0][x][y]++;
            field[0][x + 2 * K][y]++;
            field[0][x][y + 2 * K]++;
            field[0][x + 2 * K][y + 2 * K]++;
        }
        else
        {
            field[1][x][y]++;
            field[1][x + 2 * K][y]++;
            field[1][x][y + 2 * K]++;
            field[1][x + 2 * K][y + 2 * K]++;
        }
    }

    for (int i = 0; i < 4 * K; i++)
    {
        for (int j = 0; j < 4 * K; j++)
        {
            for (int k = 0; k < 2; k++)
            {
                if (i > 0)
                {
                    field[k][i][j] += field[k][i - 1][j];
                }
                if (j > 0)
                {
                    field[k][i][j] += field[k][i][j - 1];
                }
                if (i > 0 && j > 0)
                {
                    field[k][i][j] -= field[k][i - 1][j - 1];
                }
            }
        }
    }

    int ans = 0;
    int tmp;
    for (int i = 0; i < 2 * K; i++)
    {
        for (int j = 0; j < 2 * K; j++)
        {
            tmp = 0;
            tmp += calc_accumulate(field, 0, i, j, K);
            tmp += calc_accumulate(field, 1, i + K, j, K);
            tmp += calc_accumulate(field, 1, i, j + K, K);
            tmp += calc_accumulate(field, 0, i + K, j + K, K);
            ans = max(ans, tmp);
        }
    }
    cout << ans << endl;
}

