#define MAXN 2000
int N,K;
int memo[MAXN+1][MAXN+1];

void Add(int x, int y, int x2, int y2)
{
	++memo[x][y];
	--memo[x][y2+1];
	--memo[x2+1][y];
	++memo[x2+1][y2+1];
}

int main()
{
	scanf("%d%d", &N, &K);
	for (int i = 0; i < N; i++)
	{
		int x, y; char c;
		scanf("%d %d %c", &x, &y, &c);
		x %= 2*K; y %= 2*K;

		if (((x < K && y < K) || (x >= K && y >= K)) == (c == 'B'))
		{
			int x_ = x % K, y_ = y % K;

			Add(0, 			0, 			x_		 , y_		);

			Add(x_ + K + 1, 0, 			2 * K - 1, y_		);
			Add(0, 			y_ + K + 1, x_		 , 2 * K - 1);

			Add(x_ + K + 1, y_ + K + 1, 2 * K - 1, 2 * K - 1);
			Add(x_ + 1	  , y_ + 1	  , x_ + K	 , y_ + K	);
		}
		else
		{
			int x_ = x % K, y_ = y % K;

			Add(x_ + 1	  , 0		  , x_ + K	 , y_		);
			Add(x_ + 1	  , y_ + K + 1, x_ + K	 , 2 * K - 1);

			Add(0		  , y_ + 1	  , x_		 , y_ + K	);
			Add(x_ + K + 1, y_ + 1	  , 2 * K - 1, y_ + K	);
