    vector<vector<bool>> black(k*2, vector<bool>(k*2));
    int num_white = 0;
    int num_black = 0;
    rep(i, n) {
        cin >> c[i].first.first >> c[i].first.second >> c[i].second;
        c[i].first.first %= (k*2);
        c[i].first.second %= (k*2);
        if (c[i].second=='W') {
            white[c[i].first.first][c[i].first.second] = true;
            num_white++;
        }
        else {
            black[c[i].first.first][c[i].first.second] = true;
            num_black++;
        }
    }
    vector<vector<int>> sumw(k*2, vector<int>(k*2));
    vector<vector<int>> sumb(k*2, vector<int>(k*2));
    rep(i, 2*k) rep(j, 2*k) {
        sumw[i][j] = white[i][j];
        sumb[i][j] = black[i][j];
        if (i>0) {
            sumw[i][j] += sumw[i-1][j];
            sumb[i][j] += sumb[i-1][j];
        }
        if (j>0) {
            sumw[i][j] += sumw[i][j-1];
            sumb[i][j] += sumb[i][j-1];
        }
        if (i>0 && j>0) {
            sumw[i][j] -= sumw[i-1][j-1];
            sumb[i][j] -= sumb[i-1][j-1];
        }
        //debug(sumw[i][j]);
        //debug(sumb[i][j]);
    }

    int ans = 0;

    rep(i, k+1) rep(j, k+1) {
        int nw = 0;
        int nb = 0;
        if (i>0) {
            nw += sumw[i-1][j+k-1];
            nb += sumb[i-1][j+k-1];
            if (j>0) {
                nw -= sumw[i-1][j-1];
                nb -= sumb[i-1][j-1];
            }
        }
        if (j>0) {
            nw += sumw[i+k-1][j-1];
            nb += sumb[i+k-1][j-1];
            if (i>0) {
                nw -= sumw[i-1][j-1];
                nb -= sumb[i-1][j-1];
            }
        }
        if (i<k) {
            nw += sumw[2*k-1][j+k-1]-sumw[i+k-1][j+k-1];
            nb += sumb[2*k-1][j+k-1]-sumb[i+k-1][j+k-1];
            if (j>0) {
                nw -= sumw[2*k-1][j-1]-sumw[i+k-1][j-1];
                nb -= sumb[2*k-1][j-1]-sumb[i+k-1][j-1];
            }
        }
        if (j<k) {
            nw += sumw[i+k-1][2*k-1]-sumw[i+k-1][j+k-1];
            nb += sumb[i+k-1][2*k-1]-sumb[i+k-1][j+k-1];
            if (i>0) {
                nw -= sumw[i-1][2*k-1]-sumw[i-1][j+k-1];
                nb -= sumb[i-1][2*k-1]-sumb[i-1][j+k-1];
            }
        }
        chmax(ans, nw+num_black-nb);
        chmax(ans, nb+num_white-nw);
    }
    cout << ans << endl;
    return 0;
}

