int main(void){
  int n, k;
  cin >> n >> k;
  vector<vector<int>> b(k, vector<int>(k, 0)), w(k, vector<int>(k, 0));
  REP(i, n){
    int x, y;
    char c;
    cin >> x >> y >> c;
    bool f = (c == 'B');
    x %= 2*k;
    y %= 2*k;
    if(x >= k){
      x -=k;
      f = !f;
    }
    if(y >= k){
      y -= k;
      f = !f;
    }
    if(f) b[x][y]++;
    else w[x][y]++;
  }
  vector<vector<int>> bsum(k+1, vector<int>(k+1, 0)), wsum(k+1, vector<int>(k+1, 0));
  REP(i, k) REP(j, k){
    bsum[i+1][j+1] = b[i][j]+bsum[i+1][j]+bsum[i][j+1]-bsum[i][j];
    wsum[i+1][j+1] = w[i][j]+wsum[i+1][j]+wsum[i][j+1]-wsum[i][j];
  }
  int ans = 0;
  REP(i, k+1) REP(j, k+1){
    int p = bsum[i][j];
    p += wsum[k][j] - wsum[i][j];
    p += wsum[i][k] - wsum[i][j];
    p += bsum[k][k] - bsum[k][j] - bsum[i][k] + bsum[i][j];
    int q = wsum[i][j];
    q += bsum[k][j] - bsum[i][j];
    q += bsum[i][k] - bsum[i][j];
    q += wsum[k][k] - wsum[k][j] - wsum[i][k] + wsum[i][j]; 
    chmax(ans, max(p, q));
  }
  cout << ans << endl;
  return 0;
}

