			y -= k;
			c = change_c(c);
		}
		d[i] = col(x,y,c);
	}
	VVL b(k+1, VL(k+1,0));
	VVL w(k+1, VL(k+1,0));
	for (int i = 0; i < n; i++) {
		if (d[i].c == 'W') {
			w[d[i].y][d[i].x] += 1;
		} else {
			b[d[i].y][d[i].x] += 1;
		}
	}
	for (int i = 0; i < k+1; i++) {
		for (int j = 0; j < k; j++) {
			w[i][j+1] += w[i][j];
			b[i][j+1] += b[i][j];
		}
	}
	for (int i = 0; i < k; i++) {
		for (int j = 0; j < k+1; j++) {
			w[i+1][j] += w[i][j];
			b[i+1][j] += b[i][j];
		}
	}
	LL ans = 0;
	for (int i = 0; i <= k; i++) {
		for (int j = 0; j <= k; j++) {
			// (j,i)は黒の右下とする
			LL tmp0 = 0;
			LL tmp1 = 0;
			tmp0 += b[k][k] - b[i][k] - b[k][j] + 2*b[i][j];
			tmp0 += w[i][k] + w[k][j] - 2*w[i][j];
			tmp1 += w[k][k] - w[i][k] - w[k][j] + 2*w[i][j];
			tmp1 += b[i][k] + b[k][j] - 2*b[i][j];
			ans = max(ans, max(tmp0, tmp1));
		}
	}
	cout << ans << endl;
	return 0;
}

