const int H = 2001;
const int W = 2001;
vector<vector<int>> v(H, vector<int>(W, 0));
vector<vector<int>> sum(H+1, vector<int>(W+1, 0));
void init() {
    for (int i = 0; i < H; ++i)
        for (int j = 0; j < W; ++j)
            sum[i+1][j+1] = sum[i][j+1] + sum[i+1][j] - sum[i][j] + v[i][j];
}
//[x1, x2) × [y1, y2) の長方形区域の和
int get_sum(int x1, int x2, int y1, int y2) {
    return sum[y2][x2] - sum[y1][x2] - sum[y2][x1] + sum[y1][x1];
}

