                int x1 = to_inside(j + dx[d]), x2 = to_inside(j + dx[d] + k);

                cnt += get_sum(x1, x2, y1, y2);
            }
            maxi = max(maxi, cnt);
        }
    }
    cout << maxi << endl;
}

