int cal(int x1, int y1, int x2, int y2, vector<vector<int>>& grid)
{
  return grid[y2][x2] - grid[y2][x1] - grid[y1][x2] + grid[y1][x1];
}

int main()
{
  int N, K; scanf("%d %d", &N, &K);
  vector<vector<int> > grid(2 * K + 5, vector<int>(2 * K + 5, 0));
  int x, y;
  char ch;
  for (int i = 0; i < N; ++i) {
    scanf("%d %d %c", &x, &y, &ch);
    if (ch == 'W') { x += K; }
    x %= 2 * K;
    y %= 2 * K;
    ++grid[y + 1][x + 1];
  }

  int K2 = 2 * K;
  for (int i = 1; i <= K2; ++i) {
    for (int j = 1; j <= K2; ++j) {
      grid[i][j] += grid[i][j - 1];
    }
  }
  for (int i = 1; i <= K2; ++i) {
    for (int j = 1; j <= K2; ++j) {
      grid[i][j] += grid[i - 1][j];
    }
  }
  int ans = 0;
  for (int y = 1; y <= K2; ++y) {
    for (int x = 1; x <= K2; ++x) {
      // (x, y) is on the right-bottom cell of the target squre
      int x1 = 0, x2 = max(0, x - K), x3 = x, x4 = min(K2, x + K), x5 = K2;
      int y1 = 0, y2 = max(0, y - K), y3 = y, y4 = min(K2, y + K), y5 = K2;
      int cnt = cal(x1, y1, x2, y2, grid) + cal(x3, y1, x4, y2, grid) +
        cal(x2, y2, x3, y3, grid) + cal(x4, y2, x5, y3, grid) +
        cal(x1, y3, x2, y4, grid) + cal(x3, y3, x4, y4, grid) +
        cal(x2, y4, x3, y5, grid) + cal(x4, y4, x5, y5, grid);
      ans = max(ans, cnt);
    }
  }
  printf("%d\n", ans);
  return 0;
}

