int cal(int x1, int y1, int x2, int y2, vector<vector<int>>& imos)
{
  int ret =  imos[y2][x2] - imos[y2][x1] - imos[y1][x2] + imos[y1][x1];
  return ret;
}

int main()
{
  int N, K; scanf("%d %d", &N, &K);
  int x, y;
  char ch;
  vector<vector<int>> imos(K + 5, vector<int>(2 * K + 5, 0));
  for (int i = 0; i < N; ++i) {
    scanf("%d %d %c", &x, &y, &ch);
    if (ch == 'B') { x += K; }
    x %= 2 * K;
    y %= 2 * K;
    if (y >= K) {
      x = (x + K) % (2 * K);
      y %= K;
    }
    ++imos[y + 1][x + 1];
  }

  for (int i = 1; i <= K; ++i) {
    for (int j = 1; j <= 2 * K; ++j) {
      imos[i][j] += imos[i][j - 1] + imos[i - 1][j] - imos[i - 1][j - 1];
    }
  }

  int ans = 0;
  for (int y = 1; y <= K; ++y) {
    for (int x = 1; x <= 2 * K; ++x) {
      int val = cal(max(0, x - K), max(0, y - K), x, y, imos) +
                cal(x, y, min(2 * K, x + K), K, imos) +
                cal(min(2 * K, x + K), max(0, y - K), 2 * K, y, imos) +
                cal(0, y, max(0, x - K), K, imos);
      ans = max(ans, val);
    }
  }
  printf("%d\n", ans);
  return 0;
}

