    y=y+K; 
  }
  x=x%(2*K); y=y%(2*K); 
  G[x][y]=1;
}

for(int j=0; j<2*K; j++){
  if(G[0][j]) m[0][j]=1;
}

for(int j=0; j<2*K; j++){
for(int i=1; i<2*K; i++){
  if(G[i][j]){
    m[i][j]=m[i-1][j]+1;
  }
  else{
    m[i][j]=m[i-1][j];
  }
}
}

for(int i=0; i<2*K; i++){
  M[i][0]=m[i][0];
}

for(int i=0; i<2*K; i++){
for(int j=1; j<2*K; j++){
  M[i][j]=M[i][j-1]+m[i][j];
}
}

int ans=0;

for(int j=0; j<2*K; j++){
for(int i=0; i<2*K; i++){
  ans=max(ans,cnt(i,j));
