int q(int x1,int y1,int x2,int y2){//半開区間での中のruiを返す

	if(x1>x2||y1>y2)return 0;
	int ret=0;
	ret=rui[y2][x2]-rui[y2][x1-1]-rui[y1-1][x2]+rui[y1-1][x1-1];

	return ret;
}

