    rep(i, n){
        int x, y; char c; cin >> x >> y >> c;
        if(c == 'W') x += k;
        x %= (2*k), y %= (2*k);
        int dx[] = {-1, 1, 0, -1, 1}, dy[] = {-1, -1, 0, 1, 1};
        // 0 1
        //  2
        // 3 4
        rep(j, 5){
            board[min(max(0, y + k*dy[j]), 2*k - 1)][min(max(0, x + k*dx[j]), 2*k - 1)]++;
            board[min(max(0, y + k + k*dy[j]), 2*k - 1)][min(max(0, x + k + k*dx[j]), 2*k - 1)]++;
            board[min(max(0, y + k*dy[j]), 2*k - 1)][min(max(0, x + k + k*dx[j]), 2*k - 1)]--;
            board[min(max(0, y + k + k*dy[j]), 2*k - 1)][min(max(0, x + k*dx[j]), 2*k - 1)]--;
       }
    }
    rep(i, 2*k) rep(j, 2*k - 1) board[i][j + 1] += board[i][j];
    rep(i, 2*k - 1) rep(j, 2*k) board[i + 1][j] += board[i][j];
