int main() {
	int N, K;
	cin >> N >> K;
	VVI xy(4*K,VI(4*K,0));
	REP(i, N) {
		ll xx, yy;
		string cc;
		cin >> xx >> yy >> cc;
		if (cc == "W") xx += (ll)K;
		xx %= (ll)(2 * K);
		yy %= (ll)(2 * K);
		xy[(int)xx][(int)yy]++;
		xy[(int)xx+ 2 * K][(int)yy]++;
		xy[(int)xx][(int)yy+2 * K]++;
		xy[(int)xx + 2 * K][(int)yy + 2 * K]++;
	}

	VVI s(2 * K, VI(2 * K, 0));
	REP(i, K) REP(j, K) s[0][0] += xy[i][j];

	REP(i,2*K) {
