			int R = 0, L = 0;

			if ((i == 0) && (j != 0)) {
				int T = 0, B = 0;
				FOR(l, i, i + K) {
					B += xy[l][j - 1];
					T += xy[l][j - 1 + K];
				}
				s[0][j] = s[0][j - 1] + T - B;
			}

