template <class T>
class cumulativeSum
{
private:
    int ny, nx;
    vector<vector<T> > sum;
public:
    cumulativeSum(const vector<vector<T> >& a)
    {
        ny = a.size();
        nx = a[0].size();
        sum.assign(ny+1, vector<T>(nx+1, 0));
        for(int i=0; i<ny; ++i){
            for(int j=0; j<nx; ++j){
                sum[i+1][j+1] = a[i][j] + sum[i][j+1] + sum[i+1][j] - sum[i][j];
            }
        }
    }
    T getSum(int y1, int x1, int y2, int x2)
    {
        y1 = max(y1, 0);
        x1 = max(x1, 0);
        y2 = min(y2, ny-1);
        x2 = min(x2, nx-1);
        if(y1 > y2 || x1 > x2)
            return 0;
        return sum[y2+1][x2+1] - sum[y1][x2+1] - sum[y2+1][x1] + sum[y1][x1];
    }
};

int main()
{
    int n, k;
    cin >> n >> k;
    vector<vector<vector<int>>> v(2, vector<vector<int>>(k*2, vector<int>(k*2, 0)));
    for(int i=0; i<n; ++i){
        int x, y;
        char c;
        cin >> x >> y >> c;
        y %= k * 2;
        x %= k * 2;
        int a = (c == 'B') ? 0 : 1;
        ++ v[a][y][x];
    }

    int ans = 0;
    vector<cumulativeSum<int>> cs = {v[0], v[1]};
    for(int y=0; y<2*k; ++y){
        for(int x=0; x<2*k; ++x){
            int sum = 0;
            for(int i=0; i<4; ++i){
                for(int j=0; j<4; ++j){
                    int a = (i + j) % 2;
                    int y2 = y + (i - 2) * k;
                    int x2 = x + (j - 2) * k;
                    sum += cs[a].getSum(y2, x2, y2+k-1, x2+k-1);
                }
            }
            ans = max(ans, sum);
        }
    }
    cout << ans << endl;

    return 0;
}

