// 二次元累積和
int sum[2005][2005];

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<int> x(n), y(n);
    for(int i = 0; i < n; ++i){
        char c;
        cin >> x[i] >> y[i] >> c;

        // すべて(c='B')にして、([0, 2k), [0, 2k))に圧縮
        if(c == 'W'){
            y[i] += k;
        }
        x[i] %= 2 * k;
        y[i] %= 2 * k;

        ++sum[x[i] + 1][y[i] + 1];
    }

    // 二次元累積和
    // 横方向の累積和
    for(int i = 0; i <= 2 * k; ++i){
        for(int j = 0; j < 2 * k; ++j){
            sum[i][j+1] += sum[i][j];
        }
    }
    // 縦方向の累積和
    for(int i = 0; i <= 2 * k; ++i){
        for(int j = 0; j <= 2 * k; ++j){
            sum[i+1][j] += sum[i][j];
        }
    }

    int res = 0;
    // (0, 0) ~ (2, 2)
    for(int i = 0; i < k; ++i){
        for(int j = 0; j < k; ++j){
            for(int d = 0; d < 3; ++d){
                int temp = 0;
                int tx = i * dx[d], ty = j * dy[d];

                // ([0, 2k), [0, 2k))内の5つの黒に塗る部分に関して、点の数を足し合わせる
                temp += sum[tx+1][ty+1];
                temp += sum[tx+k+1][ty+k+1] - sum[tx+k+1][ty+1] - sum[tx+1][ty+k+1] + sum[tx+1][ty+1];
                temp += sum[2*k][ty+1] - sum[tx+k+1][ty+1];
                temp += sum[tx+1][2*k] - sum[tx+1][ty+k+1];
                temp += sum[2*k][2*k] - sum[2*k][ty+k+1] - sum[tx+k+1][2*k] + sum[tx+k+1][ty+k+1];

                res = max(res, temp);
            }
        }
    }

    // (0, 5) ~ (2, 3)
    for(int i = 0; i < k; ++i){
        for(int j = 0; j < k; ++j){
            for(int d = 0; d < 3; ++d){
                int temp = 0;
                int tx = i * dx[d], ty = 2 * k - 1 - j * dy[d];

                temp += sum[tx+1][ty-k];
                temp += sum[tx+k+1][ty] - sum[tx+k+1][ty-k] - sum[tx+1][ty] + sum[tx+1][ty-k];
                temp += sum[tx+1][2*k] - sum[tx+1][ty];
                temp += sum[2*k][ty-k] - sum[tx+k+1][ty-k];
                temp += sum[2*k][2*k] - sum[2*k][ty] - sum[tx+k+1][2*k] + sum[tx+k+1][ty];

                res = max(res, temp);
            }
        }
    }

    cout << res << endl;
}

