	bool xflag,yflag;
	if((int)floor((x+ofx) / k) %2 ==0 || (int)floor((x+ofx) / k) == 0){
		xflag = false;
	}
	else xflag = true;

	if((int)floor((y+ofy) / k) %2 ==0 || (int)floor((y+ofy) / k) == 0){
		yflag = false;
	}
	else yflag = true;

	if(xflag == yflag)return false;
	else return true;

}

