auto check(int k, int x, int y, int dx, int dy) -> bool {
    int cx = (x - dx) / k;
    int cy = (y - dy) / k;
    if ( (x - dx) < 0 ) {
        cx = (k - 1 + abs(x - dx)) / k;
    }
    if ( (y - dy)  < 0 ) {
        cy = (k - 1 + abs(y - dy)) / k;
    }

    bool fx = cx % 2 == 0;
    bool fy = cy % 2 == 0;

    return fx == fy;
}

