            ys[i] = (y + k) % (2 * k);
        }
    }

    int d = 2*k;
    int res = 0;
    REP(i, d) {
        REP(j, d) {
            int sum = 0;
            REP(t, n) {
                if ( check(k, xs[t], ys[t], i, j) ) {
                    ++sum;
                }
            }
            res = max(res, sum);
        }
    }

    cout << res << endl;


    return 0;
}

