struct RectangleSum {
	vector<vector<T>>imos;

	RectangleSum(vector<vector<T>>in) :imos(in.size(), vector<T>(in.size(), 0)) {
		for (int i = 1; i < in.size(); i++) {
			for (int j = 1; j < in.size(); j++) {
				imos[i][j] = in[i][j] + imos[i - 1][j] + imos[i][j - 1] - imos[i - 1][j - 1];
			}
		}
	}

	////xy平面を見て(p1,p2)が右上
	T GetRectangle(T p1, T p2, T q1, T q2) {
		return imos[p1][p2] - imos[q1 - 1][p2] - imos[p2][q2 - 1] + imos[q1 - 1][q2 - 1];
	}
};

