void fill(vector<vector<int>> &v, int x, int y, int K) {
    int right = min(x + 1, 2*K);
    int left = max(0, x + 1 - K);
    int top = min(y + 1, 2*K);
    int bot = max(0, y + 1 - K);
    if(right < 0 || top < 0 || 2*K < bot || 2*K < left) {
        return;
    }
    v[right][top]++;
    v[left][bot]++;
    v[left][top]--;
    v[right][bot]--;
}

