int main(){
  int n, k; cin >> n >> k;
  for(int i = 0; i < n; i++){
    int x, y; char c; cin >> x >> y >> c;
    x %= 2*k;
    y %= 2*k;
    p[c == 'W'][x][y] += 1;
  }
  for(int rot = 0; rot < 2; rot++) for(int i = 0; i < maxn; i++) for(int j = 0; j < maxn; j++) {
    if(i) p[rot][i][j] += p[rot][i - 1][j];
    if(j) p[rot][i][j] += p[rot][i][j - 1];
    if(i && j) p[rot][i][j] -= p[rot][i - 1][j - 1];
  }
  auto query = [&](int rot, int a, int b, int c, int d){
    int res = p[rot][c][d];
    if(a) res -= p[rot][a - 1][d];
    if(b) res -= p[rot][c][b - 1];
    if(a && b) res += p[rot][a - 1][b - 1];
    return res;
  };
  int ans = 0;
  for(int i = 0; i < k; i++) for(int j = 0; j < k; j++){
    for(int rot = 0; rot < 2; rot++){
      int now = 0;
      now += query(rot, 0, 0, i, j);
      now += query(rot ^ 1, i + 1, 0, i + k, j);
      now += query(rot, i + k + 1, 0, i + 2 * k, j);

      now += query(rot ^ 1, 0, j + 1, i, j + k);
      now += query(rot, i + 1, j + 1, i + k, j + k);
      now += query(rot ^ 1, i + k + 1, j + 1, i + 2 * k, j + k);

      now += query(rot, 0, j + k + 1, i, j + 2 * k);
      now += query(rot ^ 1, i + 1, j + k + 1, i + k, j + 2 * k);
      now += query(rot, i + k + 1, j + k + 1, i + 2 * k, j + 2 * k);
      ans = max(ans, now);
    }
  }
  cout << ans << endl;
  return 0;
}

