long calc(const vector<long>& s, long M, long x, long y, long w, long h){
    return s[(x+w)+(y+h)*M] - s[(x+w)+y*M] - s[x+(y+h)*M] + s[x+y*M];
}

int main(void){
    long n, k;
    cin >> n >> k;
    vector<wish_t> w(n);
    for(long i=0; i<n; i++){
        cin >> w[i].x >> w[i].y >> w[i].c;
    }
    vector<long> b(4*k*k);
    fill(b.begin(), b.end(), 0);
    for(long i=0; i<n; i++){
        if(w[i].c=='W'){
            w[i].x += k;
            w[i].c = 'B';
        }
        w[i].y %= 2*k;
        if(w[i].y>=k){
            w[i].y-=k;
            w[i].x+=k;
        }
        w[i].x %= 2*k;
        b[w[i].x+w[i].y*2*k]++;
    }
    /*
    for(long y=0; y<2*k; y++){
        for(long x=0; x<2*k; x++){
            cout << b[x+y*2*k] << " ";
        }
        cout << endl;
    }
    cout << endl;
    */
    const long M = 2*k+1;
    vector<long> s((2*k+1)*(2*k+1));
    fill(s.begin(), s.end(), 0);
    s[1+1*M] = b[0];
    for(long i=1; i<2*k; i++){
        s[(i+1)+1*M] = s[(i-1+1)+1*M] + b[i];
    }
    for(long i=1; i<2*k; i++){
        s[1+(i+1)*M] = s[1+(i-1+1)*M] + b[2*k*i];
    }
    for(long x=1; x<2*k; x++){
        for(long y=1; y<2*k; y++){
            s[x+1+(y+1)*M] = b[x+y*2*k] + s[(x-1+1)+(y+1)*M] + s[x+1+(y-1+1)*M] - s[(x-1+1)+(y-1+1)*M];
        }
    }
    /*
    for(long y=1; y<M; y++){
        for(long x=1; x<M; x++){
            cout << s[x+y*M] << " ";
        }
        cout << endl;
    }
    cout << endl;
    */
    long max = 0;
    for(long x=0; x<k; x++){
        for(long y=0; y<k; y++){
            //long t = s[(x+k)+(y+k)*M] - s[(x+k)+y*M] - s[x+(y+k)*M] + s[x+y*M];
            long t = calc(s, M, x, y, k, k);
            t += calc(s, M, 0, 0, x, y);
            t += calc(s, M, x+k, 0, k-x, y);
            t += calc(s, M, 0, y+k, x, k-y);
            t += calc(s, M, x+k, y+k, k-x, k-y);
            t = t<n/2 ? n-t : t;
            //printf("%ld %ld %ld\n", x, y, t);
            max = t>max ? t : max;
        }
    }
    cout << max;
    return 0;
}

