SINT64 count (SINT64 x1, SINT64 y1 ,SINT64 x2, SINT64 y2) {
	if (x1 > x2) {
		return 0;
	}
	if (y1 > y2) {
		return 0;
	}

	SINT64 buf = 0;
	x1--;
	y1--;

	if ((x2 >= 0) && (y2 >= 0)) {
		buf += data[x2][y2];
	}
	if ((x1 >= 0) && (y1 >= 0)) {
		buf += data[x1][y1];
	}
	if ((x1 >= 0) && (y2 >= 0)) {
		buf -= data[x1][y2];
	}
	if ((x2 >= 0) && (y1 >= 0)) {
		buf -= data[x2][y1];
	}

	return buf;

}


