using namespace std;

long count(long n, long k, const vector<long>& x, const vector<long>& y, const vector<char>& c, long i, long j){
    long count = 0;
    for(long ii=0; ii<n; ii++){
        long s=(i+x[ii])/k;
        long t=(j+y[ii])/k;
        bool f=(s+t)%2==0;
        if(f ^ (c[ii]=='B')){
            count++;
        }
    }
    return count<n/2 ? n-count : count;
}

int main(int argc, char const* argv[]){
    long n, k;
    cin >> n >> k;
    vector<char> c(n);
    vector<long> x(n), y(n);
    for(long i=0; i<n; i++){
        cin >> x[i] >> y[i] >> c[i];
    }
    long max = 0;
    for(long i=0; i<k; i++){
        for(long j=0; j<k; j++){
            long t = count(n,k,x,y,c,i,j);
            //printf("%ld %ld %ld\n", i, j, t);
            max = t>max ? t : max;
            if(max==n){
                cout << max;
                return 0;
            }
        }
    }
    cout << max;
    return 0;
}

