    int ans=0;
    for(int i = 0 ;i < N ; i++){
        cin >> xi >> yi >> C;
        if(C == 'B') xi += K;
        XY[xi % (2*K)][yi % (2*K)]++;
        XY[xi % (2*K)+2*K][yi % (2*K)]++;
        XY[xi % (2*K)][yi % (2*K)+2*K]++;
        XY[xi % (2*K)+2*K][yi % (2*K)+2*K]++;
    }

    for(int i=1;i<=4*K;i++){
		for(int j=1;j<=4*K;j++){
			XY[i][j]+=XY[i-1][j]+XY[i][j-1]-XY[i-1][j-1];
		}
	}
	for(int i=1;i<=K;i++){
		for(int j=1;j<=K;j++){
			s=XY[i+K][j+K]-XY[i][j+K]-XY[i+K][j]+XY[i][j];
            s+= XY[i+K+2*K][j+K+2*K]-XY[i+2*K][j+K+2*K]-XY[i+K+2*K][j+2*K]+XY[i+2*K][j+2*K];
            ans = max(ans, s);
		}
	}
