#include <cstdio>

int b[2001][2001];
int w[2001][2001];

int main()
{
  int n, k;
  scanf("%d%d", &n, &k);
  const int kk = 2 * k;
  for (int i = 0; i < n; ++i)
  {
    int x, y;
    char c;
    scanf("%d%d %c", &x, &y, &c);
    if (c == 'B')
    {
      b[y % kk + 1][x % kk + 1] += 1;
    }
    else
    {
      w[y % kk + 1][x % kk + 1] += 1;
    }
  }

  for (int y = 1; y <= kk; ++y)
  {
    for (int x = 2; x <= kk; ++x)
    {
      b[y][x] += b[y][x - 1];
      w[y][x] += w[y][x - 1];
    }
  }
  for (int x = 1; x <= kk; ++x)
  {
    for (int y = 2; y <= kk; ++y)
    {
      b[y][x] += b[y - 1][x];
      w[y][x] += w[y - 1][x];
    }
  }
  int ans = 0;
  const int black = b[kk][kk];
  for (int y = 0; y <= k; ++y)
  {
    for (int x = 0; x <= k; ++x)
    {
      int r = (w[y + k][x + k] - w[y][x + k] - w[y + k][x] + w[y][x]) +
        black - (b[y + k][x + k] - b[y][x + k] - b[y + k][x] + b[y][x]);
      if (r > ans) ans = r;
    }
  }
  printf("%d", ans);
  return 0;
}

