  x = x%(k*2);
  y = y%(k*2);
  return make_pair(x, y);
}

char get_color(int x, int y){
  // if 0, 0 is black
  x = x/k;
  y = y/k;
  // if both are odd or even it's black
  // if both are different it's white
  if (x%2 == 1 && y%2 == 1){
    return 'B';
  }
  if (x%2 == 0 && y%2 == 0){
    return 'B';
  }
  return 'W';
}

