        dp[i][y][x] += dp[i][y-1][x] + dp[i][y][x-1] - dp[i][y-1][x-1];
    }

    int res = 0;
    rep1(y,k)rep1(x,k)rep(i,2){
        int cnt1 = dp[i][k][k] - dp[i][y][k] - dp[i][k][x] + 2*dp[i][y][x];
        int cnt2 = dp[!i][y][k] + dp[!i][k][x] - 2*dp[!i][y][x];
        res = max(res, cnt1+cnt2);
    }
    cout<<res<<endl;
    return 0;
}

