            int rx = (2*K <= i+K ? 2*K+1 : i+K);
            int ry = (2*K <= j+K ? 2*K+1 : j+K);
            int cnt = s2d.query(i,j,rx,ry);
            cnt += s2d.query(0,0,i,j);
            cnt += s2d.query(rx,0,2*K+1,j);
            cnt += s2d.query(0,ry,i,2*K+1);
            cnt += s2d.query(rx,ry,2*K+1,2*K+1);
            ans = std::max(ans, cnt);
        }
    }
    cout << ans;
}

