	vvl prefB(k+1, vl(k+1, 0));
	for (int i = 1; i <= k; i++) {
		for (int j = 1; j <= k; j++) {
			prefW[i][j] = prefW[i-1][j] + prefW[i][j-1] - prefW[i-1][j-1] + W[i-1][j-1];
			prefB[i][j] = prefB[i-1][j] + prefB[i][j-1] - prefB[i-1][j-1] + B[i-1][j-1];
