mat b(N,vec(N,0));
ll n,k,kk;

ll area(ll x,ll y) {
  ll tmp=0;
  if(x+k-1<=kk) {
    if(y+k-1<=kk) {
      tmp+=b[x+k-1][y+k-1];
      tmp+=b[x-1][y-1];
      tmp-=b[x-1][y+k-1];
      tmp-=b[x+k-1][y-1];
    }
    else {
      tmp+=b[x+k-1][kk];
      tmp-=b[x+k-1][y-1];
      tmp-=b[x-1][kk];
      tmp+=b[x-1][y-1];
      tmp+=b[x+k-1][y+k-1-kk];
      tmp-=b[x-1][y+k-1-kk];
    }
  }
  else {
    if(y+k-1<=kk) {
      tmp+=b[kk][y+k-1];
      tmp-=b[x-1][y+k-1];
      tmp-=b[kk][y-1];
      tmp+=b[x-1][y-1];
      tmp+=b[x+k-1-kk][y+k-1];
      tmp-=b[x+k-1-kk][y-1];
    }
    else {
      tmp+=b[kk][kk];
      tmp-=b[x-1][kk];
      tmp-=b[kk][y-1];
      tmp+=b[x-1][y-1];
      tmp+=b[x+k-1-kk][y+k-1-kk];
    }
  }
  return tmp;
}

