  }
  for(ll i=0;i<kk;i++) {
    for(ll j=0;j<=kk;j++) {
      b[i+1][j]+=b[i][j];
    }
  }
  for(ll i=0;i<=kk;i++) {
    for(ll j=0;j<kk;j++) {
      b[i][j+1]+=b[i][j];
    }
  }
  ll ans=0;
