inline int f(int sum[SIZE][SIZE], int x1, int y1, int x2, int y2, int xd, int yd) {
  x1 += xd; x2 += xd; y1 += yd; y2 += yd;
  int ret = sum[x2][y2];
  ret -= sum[x1][y2];
  ret -= sum[x2][y1];
  ret += sum[x1][y1];
  //  printf("%d %d %d %d %d\n", x1, x2, y1, y2, ret);                                  
