int solve(vector<vector<int>> v,int K) {
	vector<vector<int>> map;
	map.resize(4 * K);
	for (int i = 0; i < map.size(); i++) {
		for (int j = 0; j < 4 * K; j++) {
			map[i].push_back(0);
		}
	}

	for (int i = 0; i < v.size(); i++) {
		for (int j = 0; j < 4 * K; j += K) {
			for (int a = 0; a < 4 * K; a += K) {
				int x = v[i][0] % K + j + 1;
				int y = v[i][1] % K + a + 1;
				if ((x + y) % (2 * K) == (v[i][0] + 1 + v[i][1] + 1) % (2 * K)) {
					if (x + K < 4 * K&&y + K < 4 * K) {
						map[x][y]++;
						map[x][y + K]--;
						map[x + K][y]--;
						map[x + K][y + K]++;
					}
				}
			}
		}
	}

	for (int i = 0; i < map.size(); i++) {
		for (int j = 1; j < map.size(); j++) {
			map[i][j] += map[i][j - 1];
		}
	}

	for (int j = 0; j < map.size(); j++) {
		for (int i = 1; i < map.size(); i++) {
			map[i][j] += map[i-1][j];
		}
	}

	int ans = -2000;
	for (int i = 0; i < map.size(); i++) {
		for (int j = 0; j < map.size(); j++) {
			ans = max(ans, map[i][j]);
		}
	}
	return ans;
}




