      int c = board[2 * K][j] - board[i + K][j];
      int d = board[i][2 * K] - board[i][j + K];
      int e = board[2 * K][2 * K] - board[2 * K][j + K] - board[i + K][2 * K] +
              board[i + K][j + K];
      int tmp = a + b + c + d + e;
      res = max({res, tmp, sum - tmp});
    }
  }
  res += white;
  cout << res << '\n';
  return 0;
}

