int N, K;

int B[3001][3001], W[3001][3001];

int diff[3001][3001];
long long int sum_diff[3001][3001];

int main(void) {

	cin >> N >> K;
	long long int tmp_x, tmp_y;
	string str;
	for (int i = 1; i <= N; i++) {
		cin >> tmp_x; 
		cin >> tmp_y; 
		cin >> str; if (str == "B") { B[tmp_x % (2 * K)][tmp_y % (2 * K)]++; }
		else { W[tmp_x % (2 * K)][tmp_y % (2 * K)]++; }
	}

	for (int i = 0; i <= 3 * K - 1; i++) {
		for (int j = 0; j <= 3 * K - 1; j++) {
			W[i][j] = W[i % (2 * K)][j % (2 * K)];
			B[i][j] = B[i % (2 * K)][j % (2 * K)];
		}
	}

	//====== diff ============================//
	for (int i = 0; i <= 3 * K - 1; i++) {
		for (int j = 0; j <= 3 * K - 1; j++) {
			diff[i][j] = B[i][j] - W[i][j];
		}
	}

	//=== sum_diff ===============================//

	for (int i = 0; i <= 3* K ; i++) {
		sum_diff[i][3 * K] = 0;
	}
	for (int j = 0; j <= 3 * K; j++) {
		sum_diff[0][j] = 0;
	}

	for (int i = 3 * K - 1; i >= 0; i--) {
		for (int j = 3 * K - 1; j >= 0; j--) {
			sum_diff[i][j] = diff[i][j] + sum_diff[i + 1][j] + sum_diff[i][j + 1] - sum_diff[i+1][j+1];
		}
	}

	//==========================================//

/*	for (int i = 0; i <= 3 * K; i++) {
		for (int j = 0; j <= 3 * K; j++) {
			cout << " " << sum_diff[i][j];
		}cout << endl;
	}
	*/
	//====== W ================================//
	long long int count_W = 0;
	for (int i = 0; i <= 2 * K - 1; i++) {
		for (int j = 0; j <= 2 * K - 1; j++) {
			count_W += W[i][j];
		}
	}
	//==========================================//

	long long int ans = 0;

	long long int count;

	for (int I = 0; I <= 2*K-1; I++) {
		for (int J = 0; J <= 2*K-1; J++) {
			count = 0;

			count += sum_diff[I][J] - sum_diff[I + K][J] - sum_diff[I][J + K] + sum_diff[I + K][J + K];
			count += sum_diff[I + K][J + K] - sum_diff[I + 2 * K][J + K] - sum_diff[I + K][J + 2 * K] + sum_diff[I + 2 * K][J + 2 * K];

			count += count_W;

			ans = max(ans, count);
		}//J-loop fin
	}//I-loop

	cout << ans << endl;

	//system("pause");
	return 0;
}

