		cin>>x[i]>>y[i]>>c;

		if(c=='W'){W[y[i]%(2*K)][x[i]%(2*K)]++;}
		else{B[y[i]%(2*K)][x[i]%(2*K)]++;}
	}
	for(i=0;i<4*K;i++){
		for(j=0;j<4*K;j++){
		BR.set(j,i,B[i%(2*K)][j%(2*K)]);
		WR.set(j,i,W[i%(2*K)][j%(2*K)]);
		}
	}
	BR.build();
	WR.build();

	int ans=0;

	for(i=0;i<2*K;i++){
		for(j=0;j<2*K;j++){
			int b=BR.get(j,i,j+K-1,i+K-1)+BR.get(j+K,i+K,j+(2*K)-1,i+(2*K)-1);
			int w=WR.get(j+K,i,j+(2*K)-1,i+K-1)+WR.get(j,i+K,j+K-1,i+(2*K)-1);
			if(ans<w+b){ans=w+b;}
		}
	}
	cout<<ans<<endl;

	return 0;
}

