            y += k;
        }
        x %= 2 * k;
        y %= 2 * k;

        ++sum[x + 1][y + 1];
    }

    // 二次元累積和
    // 横方向の累積和
    for(int i = 0; i <= 2 * k; ++i){
        for(int j = 0; j <= 2 * k; ++j){
            sum[i][j+1] += sum[i][j];
        }
    }
    // 縦方向の累積和
    for(int i = 0; i <= 2 * k; ++i){
        for(int j = 0; j <= 2 * k; ++j){
            sum[i+1][j] += sum[i][j];
        }
    }

    int res = 0;
    // (0, 0) ~ (k-1, k-1)
    for(int tx = 0; tx < 2*k; ++tx){
        for(int ty = 0; ty < k; ++ty){
                int temp = 0;

                // ([0, 2k), [0, 2k))内の5つの黒に塗る部分に関して、点の数を足し合わせる
                temp += sum[tx][ty];
                temp += sum[tx+k][ty+k] - sum[tx+k][ty] - sum[tx][ty+k] + sum[tx][ty];
                temp += sum[2*k][ty] - sum[tx+k][ty];
                temp += sum[tx][2*k] - sum[tx][ty+k];
                temp += sum[2*k][2*k] - sum[2*k][ty+k] - sum[tx+k][2*k] + sum[tx+k][ty+k];

                res = max(res, temp);
        }
    }

    cout << res << endl;
}

