typedef long long ll;
const int MAXN = 1e5+10;
const int MAXK = 2010;

int n, k;
ll x[MAXN], y[MAXN];
char c[MAXN];

int board[MAXK][MAXK];

int get(int sx, int sy, int ex, int ey) {
  int tmp = board[ey][ex];
  if (sx >= 0) {
    tmp -= board[sy][ex];
  }
  if (sy >= 0) {
    tmp -= board[ey][sx];
  }
  if (sx >= 0 && sy >= 0) {
    tmp += board[sy][sx];
  }

  return tmp;
}

void solve() {
  for (int i=0;i<n;i++) {
    if (c[i] == 'W') {
      x[i] += k;
    }
    x[i] = x[i] % (2 * k);
    y[i] = y[i] % (2 * k);
  }

  memset(board, 0, sizeof(board));

  for (int i=0;i<n;i++) {
    board[y[i]][x[i]]++;
  }

  for (int y=0;y<2*k;y++) {
    for (int x=1;x<2*k;x++) {
      board[y][x] += board[y][x-1];
    }
  }
  for (int y=1;y<2*k;y++) {
    for (int x=0;x<2*k;x++) {
      board[y][x] += board[y-1][x];
    }
  }

  int maxCnt = 0;
  for (int y=0;y<k;y++) {
    for (int x=0;x<k;x++) {
      int cnt = get(0, 0, x, y) +
                get(x + k, 0, 2 * k - 1, y) +
                get(0, y + k, x, 2 * k - 1) +
                get(x, y, x + k, y + k) +
                get(x + k, y + k, 2 * k - 1, 2 * k - 1);
      maxCnt = max(maxCnt, (max(cnt, n - cnt)));
    }
  }

  cout << maxCnt << endl;
}

int main() {
  cin >> n >> k;
  for (int i=0;i<n;i++) {
    cin >> x[i] >> y[i] >> c[i];
  }
  solve();
}

