        tmp+=b[x+k-1][(y+k-1-1)%kk+1];
        tmp+=b[x-1][y-1];
        tmp-=b[x-1][(y+k-1-1)%kk+1];
        tmp-=b[x+k-1][y-1];
        tmp+=b[x+k-1][kk];
        tmp-=b[x-1][kk];
      }
    }
    else {
      if(y+k-1<=kk) {
        tmp+=b[(x+k-1-1)%kk+1][y+k-1];
        tmp+=b[x-1][y-1];
        tmp-=b[x-1][y+k-1];
        tmp-=b[(x+k-1-1)%kk+1][y-1];
        tmp+=b[kk][y+k-1];
        tmp-=b[kk][y-1];
      }
      else {
        tmp+=b[(x+k-1-1)%kk+1][(y+k-1-1)%kk+1];
        tmp+=b[x-1][y-1];
        tmp-=b[x-1][kk];
        tmp-=b[kk][y-1];
        tmp+=b[kk][kk];
      }
