  }
  else {
    if(x+k-1<=kk) {
      if(y+k-1<=kk) {
        tmp+=w[x+k-1][y+k-1];
        tmp+=w[x-1][y-1];
        tmp-=w[x-1][y+k-1];
        tmp-=w[x+k-1][y-1];
