        tmp+=w[x-1][y-1];
        tmp-=w[x-1][(y+k-1-1)%kk+1];
        tmp-=w[x+k-1][y-1];
        tmp+=w[x+k-1][kk];
        tmp-=w[x-1][kk];
      }
    }
    else {
      if(y+k-1<=kk) {
        tmp+=w[(x+k-1-1)%kk+1][y+k-1];
        tmp+=w[x-1][y-1];
        tmp-=w[x-1][y+k-1];
