class CumulativeSum {
  private:
    int H_, W_;
    std::vector<std::vector<long long>> s;

  public:
    explicit CumulativeSum (int H, int W) : H_(H), W_(W) {
      s.resize(H+1); for(int i=0; i<=H; i++) s[i].resize(W+1);
      s[0][0] = 0;
      for(int i=0; i<=H_; i++) s[i][0] = 0;
      for(int i=0; i<=W_; i++) s[0][i] = 0;
    }

    void set(int i, int j, long long a) {
      s[i+1][j+1] += a;
      return;
    }

    void build() {
      for(int i=0; i<=H_; i++) for(int j=1; j<=W_; j++) s[i][j] += s[i][j-1];
      for(int i=1; i<=H_; i++) for(int j=0; j<=W_; j++) s[i][j] += s[i-1][j];
    }

    void build ( const std::vector<std::vector<long long>> &a ) {
      for(int i=1; i<=H_; i++) for(int j=1; j<=W_; j++) s[i][j] = a[i-1][j-1];
      for(int i=0; i<=H_; i++) for(int j=1; j<=W_; j++) s[i][j] += s[i][j-1];
      for(int i=1; i<=H_; i++) for(int j=0; j<=W_; j++) s[i][j] += s[i-1][j];
    }

    // h : [i,j],  w : [k,m]
    long long Get(int i, int j, int k, int m) {
      return s[j+1][m+1] - s[i][m+1] + s[i][k] - s[j+1][k];
    }
};


int main (void) {
  std::cin.tie(0);  std::ios::sync_with_stdio(false);
  ll N, K; std::cin >> N >> K;
  std::vector<ll> x(N), y(N);
  std::vector<char> c(N);
  rep(i,N) std::cin >> x[i] >> y[i] >> c[i];

  rep(i,N) if ( c[i] == 'W' ) y[i] += K;

  rep(i,N) x[i] %= (2*K);
  rep(i,N) y[i] %= (2*K);

  CumulativeSum S(4*K, 4*K);
  rep(i,N) {
    S.set(x[i], y[i], 1);
    S.set(x[i]+2*K, y[i], 1);
    S.set(x[i], y[i]+2*K, 1);
    S.set(x[i]+2*K, y[i]+2*K, 1);
  }
  S.build();

  int ans = 0;
  for(int x=0; x<2*K; x++) for(int y=0; y<2*K; y++) {
    int a = S.Get(x,   x+K-1,   y,   y+K-1);
    int b = S.Get(x+K, x+K+K-1, y+K, y+K+K-1);
    ans = std::max(ans, a+b);
  }
  std::cout << ans << std::endl;

  return 0;
}

