		// +---+---+---+---+---+---+
		// |///|///|   |   |   |///|
		// +---+---+---+---+---+---+ 2K
		int a = query(0,     0,   x,   y);
		int b = query(x+K+1, 0,   k2,  y);
		int c = query(0,     y+K, x,   k2);
		int d = query(x,     y,   x+K, y+K);
		int e = query(x+K+1, y+K, k2,  k2);
		int w = a + b + c + d + e;
		ans = max(ans, w);
	}
	}
	// Output
	cout << ans << endl;
	return 0;
}

