int solve(int C[MAX][MAX], int x, int y, int K) {
	int cnt = 0;
	int x1, x2, x3, y1, y2, y3;

	if (x == 0) x1 = NULL;
	else x1 = x - 1;

	if (x + K - 1 >= 2 * K) x2 = 2 * K - 1;
	else x2 = x + K - 1;

	if (x2 == 2 * K - 1) x3 = NULL;
	else x3 = 2 * K - 1;

	if (y == 0) y1 = NULL;
	else y1 = y - 1;

	if (y + K - 1 >= 2 * K) y2 = 2 * K - 1;
	else y2 = y + K - 1;

	if (y2 == 2 * K - 1) y3 = NULL;
	else y3 = 2 * K - 1;

	if ((x1 != NULL) && (y1 != NULL)) cnt += C[x1][y1];

	if ((x1 != NULL) && (y3 != NULL)) {
		cnt += C[x1][y3];
		cnt -= C[x1][y2];
	}

	if ((x3 != NULL) && (y1 != NULL)) {
		cnt += C[x3][y1];
		cnt -= C[x2][y1];
	}

	cnt += C[x2][y2];
	if (x1 != NULL) cnt -= C[x1][y2];
	if (y1 != NULL) cnt -= C[x2][y1];
	if ((x1 != NULL) && (y1 != NULL)) cnt += C[x1][y1];

	if ((x3 != NULL) && (y3 != NULL)) {
		cnt += C[x3][y3];
		cnt -= C[x2][y3];
		cnt -= C[x3][y2];
		cnt += C[x2][y2];
	}

	return cnt;
}

int main() {
	int N, K; scanf("%d%d", &N, &K);
	int C[MAX][MAX]; FOR(i, 0, MAX) FOR(j, 0, MAX) C[i][j] = 0;

	FOR(i, 0, N) {
		ll x, y; char s[5]; scanf("%lld%lld%s", &x, &y, &s);
		if (s[0] == 'B') C[x % (2 * K)][y % (2 * K)]++;
		else C[x % (2 * K)][(y + K) % (2 * K)]++;
	}

	FOR(i, 0, 2 * K) FOR(j, 1, 2 * K) C[i][j] += C[i][j - 1];
	FOR(i, 0, 2 * K) FOR(j, 1, 2 * K) C[j][i] += C[j - 1][i];

	int m = 0;

	FOR(i, 0, 2 * K) FOR(j, 0, 2 * K) if (m < solve(C, i, j, K)) m = solve(C, i, j, K);

	printf("%d\n", m);

	return 0;
}

