template <typename T>
class CumulativeSum {
private:
	int n;
	vector<vector<T>> data;

public:
	CumulativeSum(vector<vector<T>>& init) : n(init.size()) {
		data = vector<vector<T>>(n + 1, vector<T>(n + 1, 0));
		for (int i = 0; i < n; i++)
			for (int j = 0; j < n; j++)
				data[i + 1][j + 1] += init[i][j] + data[i + 1][j] + data[i][j + 1] - data[i][j];
	}

	T get(int i, int j, int h, int w) {
		if (i + h >= n + 1 || j + w >= n + 1) {
			cerr << "Cumulatice Sum range error." << endl;
			exit(EXIT_FAILURE);
		}
		//if (h == 0 || w == 0) return 0;
		return data[i + h][j + w] - data[i][j + w] - data[i + h][j] + data[i][j];
	}
};


