template<class T> struct SegmentTree{
	using F = function<T(T, T)>;
	vector<T> dat; //第i要素 dat[i+n-1]
	ll n; //要素数以上の最小の 2のべき乗
	F f;
	T ti;
	SegmentTree(){}
	SegmentTree(vector<T> &v, F f, T ti){ Init(v, f, ti); }
	void Init(vector<T> &v, F f, T ti){
		this->f=f; this->ti=ti;
		for (n = 1; n < (ll)v.size(); n *= 2);
		dat.resize(2*n-1, ti);
		REP(i, (ll)v.size()) { dat[i+n-1] = v[i]; }//初期化
		DEP(i, n-1) { dat[i] = f(dat[2*i+1], dat[2*i+2]); }//構築
	}
	void Set(ll i, T x){ //第i要素にxをセット
		i += n-1;  dat[i] = x;
		while (i>0) { i=(i-1)/2; dat[i]=f(dat[2*i+1], dat[2*i+2]); }
	}
	T Range(ll a, ll b) { return range(a, b, 0, 0, n); }
	T operator [] (ll i) { return dat[i+n-1]; }
	void Dump(ll w=5){
		REP(i, n) for (ll k=i+n-1, m=1, p=1; k>=0; p=m, m*=k%2, k=(k==0)?-1:(k-1)/2){
			if (m) cerr << ((k<n-1)?" ┬ ":"") << setw(w) << dat[k];
			else   cerr << ((p&~m) ?" ┘ ":"");
			if (k==0) cerr << '\n';
		} cerr << '\n';
	}
	T range(ll a, ll b, ll k, ll l, ll r){ //注目ノードk=[l,r)
		if (r<=a || b<=l) return ti; //完全に外
		if (a<=l && r<=b) return dat[k];//完全に含まれる
		return f(range(a, b, k*2+1, l, (l+r)/2), range(a, b, k*2+2, (l+r)/2, r));
	}
};


void solve()
{
	ll N, K;  cin >> N >> K;
	vector<tuple<ll, ll, char>> xyc = cinv3<ll, ll, char>(N);

	vvpll x_yc(2*K);

	ll B=0, W=0;
	EACH(e, xyc){
		get<0>(e) %= 2*K;
		get<1>(e) %= 2*K;
		if (get<2>(e) == 'B'){
			B++;
			x_yc[get<0>(e)].push_back(pll(get<1>(e), 1));
		}
		else{
			W++;
			x_yc[get<0>(e)].push_back(pll(get<1>(e), -1));
		}
	}

	vll iniL(2*K);
	vll iniR(2*K);
	rep(i, 0, 2*K-1){
		EACH(e, x_yc[i]){
			ll y; ll c;  tie(y, c) = e;
			if (i<=K-1){
				iniL[y] = c;
			}
			else{
				iniR[y] = c;
			}
		}
	}

	SegmentTree<ll> sgtL(iniL, [](ll x, ll y){return x+y; }, 0);
	SegmentTree<ll> sgtR(iniR, [](ll x, ll y){return x+y; }, 0);

	ll ans = 0;
	rep(i, 0, K-1){
		rep(j, 0, K-1){
			ll val = 0;
			val += sgtL.Range(j, j+K);
			val += sgtR.Range(0, j);
			val += sgtR.Range(j+K, 2*K);
			ll p = val+W;
			ll q = max(p, N-p);
			chmax(ans, q);
		}

		EACH(e, x_yc[i]){
			ll y; ll c;  tie(y, c) = e;
			sgtL.Set(y, 0);
			sgtR.Set(y, c);
		}
	}
	cout << ans << '\n';
}


int main(){
	solve();
	return 0;
}

