    cntb=sumb[i-1][j-1]+(sumb[2*k][j-1]-sumb[i+k-1][j-1])+(sumb[i+k-1][j+k-1]-sumb[i+k-1][j-1]-sumb[i-1][j+k-1]+sumb[i-1][j-1]);
    cntb+=(sumb[2*k][2*k]-sumb[2*k][j+k-1]-sumb[i+k-1][2*k]+sumb[i+k-1][j+k-1])+(sumb[i-1][2*k]-sumb[i-1][j+k-1]);
    cntw=(sumw[i+k-1][j-1]-sumw[i-1][j-1])+(sumw[2*k][j+k-1]-sumw[i+k-1][j+k-1]-sumw[2*k][j-1]+sumw[i+k-1][j-1]);
    cntw+=(sumw[i-1][j+k-1]-sumw[i-1][j-1])+(sumw[i+k-1][2*k]-sumw[i+k-1][j+k-1]-sumw[i-1][2*k]+sumw[i-1][j+k-1]);
    return cntb+cntw;
}

