struct sq {
    int y; int x; bool white;
};
int pl (sq e, int k, int i) {
    int K = 2 * k;
    return ((((e.y + K - i) % K >= k ? k : 0) + (e.white ? k : 0) + e.x) % K);
}
int main (void)
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n, k; cin >> n >> k;
    int K = 2 * k;
    vector<sq> squ(n);
    for (auto &e : squ) {
        char col; cin >> e.y >> e.x >> col;
        e.y %= K; e.x %= K;
        e.white = (col == 'W');
    }
    sort(all(squ), [](sq a, sq b){return (a.y != b.y ? a.y < b.y : a.x < b.x);});

    vector<int> check(K);
    int mae = 0, ushiro = 0;
    while (ushiro < n && squ[ushiro].y < k) ushiro++;
    for (auto &e : squ) check[pl(e, k, 0)]++;
    for (int i : check) eprintf("%d ", i); eprintf("\n");
    int ans = 0;
    int tmp = 0;
    rep (i, k) tmp += check[i]; chmax(ans, tmp);
    rep (i, K) {
        tmp += check[(i + k) % K] - check[i % K];
        chmax(ans, tmp);
    }
    rep (i, 1, k + 1) {
        while (mae < n && squ[mae].y < i) {
            check[pl(squ[mae], k, i - 1)]--;
            check[pl(squ[mae], k, i)]++;
            mae++;
        }
        while (ushiro < n && squ[ushiro].y < i + k) {
            check[pl(squ[ushiro], k, i - 1)]--;
