        for (int i : check) eprintf("%d ", i); eprintf("\n");
        tmp = 0;
        rep (i, k) tmp += check[i]; chmax(ans, tmp);
        rep (i, K) {
            tmp += check[(i + k) % K] - check[i % K];
            chmax(ans, tmp);
        }
    }

    cout << ans << "\n";
    return 0;
}

