                if( (posx<K && posy<K) || (posx>=K && posy>=K) ){
                        int x_ = x % K, y_ = y % K;
                        imos(table, 0, 0, x_ + 1, y_ + 1);
                        imos(table, x_ + K + 1, 0, 2 * K, y_ + 1);

                        imos(table, 0, y_ + K + 1, x_ + 1, 2 * K);
                        imos(table, x_ + K + 1, y_ + K + 1, 2 * K, 2 * K);

                        imos(table, x_ + 1, y_ + 1, x_ + K + 1, y_ + K + 1);
                }else{
                        int x_ = x % K, y_ = y % K;
                        imos(table, x_ + 1, 0, x_ + K + 1, y_ + 1);
