/* [(x1,y1), (x2,y2)]の範囲の累積和を返す */
int calc(vector<vector<int>> (&r), int x1, int y1, int x2, int y2) {
    return r[x2+1][y2+1] - r[x2+1][y1] - r[x1][y2+1] + r[x1][y1];
}

void solve(){
    int N, K;
    cin >> N >> K;
    int grid[1005][2005];

    for (int i=0; i<N; i++) {
        int x, y;
        char c;
        cin >> x >> y >> c;

        // 全部'B'に変換する
        if (c == 'W') {
            x += K;
        }
        // x,yを[0,2K)の範囲に変換する
        x = x%(2*K);
        y = y%(2*K);
        // [(0,0), (K,2K))の範囲に変換する
        // (変換1) (x+K, y+K) -> (x,y)
        // (変換2) (x+K, y) -> (x, y+K)
        if (x>=K && y>=K) {  // 変換1
            x = x-K;
            y = y-K;
        }
        if (x>=K) {  // 変換2
            x = x-K;
            y = y+K;
        }
        grid[x][y] += 1;  // 希望の位置を+1する
    }

    /* 2次元累積和rを作る */
    vector<vector<int>> r(1005, vector<int>(2005, 0));
    r[1][1] = grid[0][0];
    for (int x=1; x<K; x++) {
        r[x+1][1] = r[x][1] + grid[x][0];
    }
    for (int y=1; y<2*K; y++) {
        r[1][y+1] = r[1][y] + grid[0][y];
    }
    for (int x=1; x<K; x++) {
        for (int y=1; y<2*K; y++) {
            r[x+1][y+1] = r[x+1][y] + r[x][y+1] - r[x][y] + grid[x][y];
        }
    }

    /* 答えを探索する */
    ll ans = 0;
    for (int x=0; x<K; x++) {
        for (int y=0; y<2*K; y++) {
            ll total = 0;
            int x1, x2, x3, x4, x5, x6;
            int y1, y2, y3, y4, y5, y6;

            if (y+K-1 >= 2*K && x+K-1 >= K) {
                /* xとyが境界をまたぐ場合 */
                x1 = x; y1 = y;
                x2 = K-1; y2 = 2*K-1;
                total += calc(r, x1, y1, x2, y2);

                x3 = x; y3 = 0;
                x4 = K-1; y4 = (y+K-1)%(2*K);
                total += calc(r, x3, y3, x4, y4);

                x5 = 0; y5 = y4+1;
                x6 = x1-1; y6 = y1-1;
                total += calc(r, x5, y5, x6, y6);
            }
            else if (y+K-1 >= 2*K) {
                /* yのみが境界をまたぐ場合 */
                x1 = 0; y1 = y;
                x2 = K-1; y2 = 2*K-1;
                total += calc(r, x1, y1, x2, y2);

                x3 = 0; y3 = 0;
                x4 = K-1; y4 = (y+K-1)%(2*K);
                total += calc(r, x3, y3, x4, y4);
            }
            else if (x+K-1 >= K) {
                /* xのみが境界をまたぐとき */
                x1 = x; y1 = y;
                x2 = K-1; y2 = y+K-1;
                total += calc(r, x1, y1, x2, y2);

                if (y2+1 < 2*K) {
                    x3 = 0; y3 = y2+1;
                    x4 = x-1; y4 = 2*K-1;
                    total += calc(r, x3, y3, x4, y4);

                    x5 = 0; y5 = 0;
                    x6 = x-1; y6 = y-1;
                    total += calc(r, x5, y5, x6, y6);
                }
                else {
                    x3 = 0; y3 = y2+1;
                    x4 = x-1; y4 = 2*K-1;
                    total += calc(r, x3, y3, x4, y4);
                }
            }
            else {
                /* xもyもまたがない場合 */
                x1 = x; y1 = y;
                x2 = x+K-1; y2 = y+K-1;
                total += calc(r, x1, y1, x2, y2);
            }
            ans = max(ans, total);
        }
    }
    cout << ans << endl;
}


int main(int argc, char const *argv[]){
    solve();
    return 0;
}

