inline int get_sum(int t, int lx, int ly, int rx, int ry) {
    return sum[t][rx][ry] - sum[t][rx][ly - 1] - sum[t][lx - 1][ry] + sum[t][lx - 1][ly - 1];
}

main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    int n, k, x, y, ans = 0;
    char c;
    cin >> n >> k;
    for (int i = 1; i <= n; ++i) {
        cin >> x >> y >> c;
        x = x % (2 * k) + 1, y = y % (2 * k) + 1;
        if (c == 'B') sum[0][x][y]++, sum[0][x + 2 * k][y]++, sum[0][x][y + 2 * k]++, sum[0][x + 2 * k][y + 2 * k]++;
        else sum[1][x][y]++, sum[1][x + 2 * k][y]++, sum[1][x][y + 2 * k]++, sum[1][x + 2 * k][y + 2 * k]++;
    }
    for (int i = 1; i <= 4 * k; ++i) {
        for (int j = 1; j <= 4 * k; ++j) {
            for (int t = 0; t < 2; ++t) {
                sum[t][i][j] = sum[t][i - 1][j] + sum[t][i][j - 1] - sum[t][i - 1][j - 1] + sum[t][i][j];
            }
        }
    }
    for (int i = 1; i <= k; ++i) {
        for (int j = 1; j <= k; ++j) {
            for (int t = 0; t < 2; ++t) {
                int cur = get_sum(t, i, j, i + k - 1, j + k - 1) + get_sum(t, i + k, j + k, i + 2 * k - 1, j + 2 * k - 1) + get_sum((1^t), i + k, j, i + 2 * k - 1, j + k - 1) + get_sum((1^t), i, j + k, i + k - 1, j + 2 * k - 1);
                ans = max(ans, cur);
            }
        }
    }
    cout << ans << '\n';
    return 0;
}

