template<typename T>
struct Imos2D {
	vector<vector<T>> board;
	const int h, w;
	Imos2D(int h, int w) : 
		board(vector<vector<T>>(h + 2, vector<T>(w + 2, 0))),
		w(w + 2),
		h(h + 2)
		{}
	// 範囲外許さないマン
	bool able(int y, int x) {
		if(y <= 0 or h < y) return false;
		if(x <= 0 or w < x) return false;
		return true;
	}
	bool able(int y1, int x1, int y2, int x2) {
		if(not able(y1, x1)) return false;
		if(not able(y2, x2)) return false;
		if(make_pair(y1, x1) > make_pair(y2, x2)) return false;
		return true;
	}
	// 1点加算
	void add(int y, int x, T z) {
		assert(able(y, x));
		board[y][x] += z;
	}
	// 矩形加算
	void add(int y1, int x1, int y2, int x2, T z) {
		assert(able(y1, x1, y2, x2));
		board[y1][x1] += z;
		board[y1][x2 + 1] -= z;
		board[y2 + 1][x1] -= z;
		board[y2 + 1][x2 + 1] += z;
	}
	// 累積和
	void build() {
		for(int y = 1; y < h; ++y) {
			for(int x = 1; x < w; ++x) {
				board[y][x] += board[y][x - 1];
			}
		}
		for(int y = 1; y < h; ++y) {
			for(int x = 1; x < w; ++x) {
				board[y][x] += board[y - 1][x];
			}
		}
	}
	// 1点取得
	T get(int y, int x) {
		assert(able(y, x));
		return board[y][x];
	}
	// 矩形取得
	T get(int y1, int x1, int y2, int x2) {
		assert(able(y1, x1, y2, x2));
		return board[y2][x2] - board[y2][x1 - 1] - board[y1 - 1][x2]+board[y1 - 1][x1 - 1];
	}
	void debug() {
		for(int y = 1; y < h - 1; ++y) {
			for(int x = 1; x < w - 1; ++x) {
				cout << board[y][x] << " ";
			}
			cout << '\n';
		}
	}
};

int main() {
	int n, k; cin >> n >> k;
	int x[n], y[n];
	for(int i = 0; i < n; ++i) {
		cin >> x[i] >> y[i];
		char c; cin >> c;
		if(c == 'W') {
			y[i] += k;
		}
		x[i] %= 2 * k;
		y[i] %= 2 * k;
	}
	Imos2D<int> imos(2 * k, 2 * k);
	for(int i = 0; i < n; ++i) {
		imos.add(y[i] + 1, x[i] + 1, 1);
	}
	imos.build();
	int ans = 0;
	for(int y = 1; y <= k; ++y) {
		for(int x = 1; x <= k; ++x) {
			int cnt = 0;
			cnt += imos.get(y, x, y + k - 1, x + k - 1);
			int ny = y + k, nx = x + k;
			cnt += imos.get(ny, nx, 2 * k, 2 * k);
			if(ny + k - 1 > 2 * k) {
				cnt += imos.get(1, nx, 2 * k - ny + 1, 2 * k);
			}
			if(nx + k - 1 > 2 * k) {
				cnt += imos.get(ny, 1, 2 * k, 2 * k - nx + 1);
			}
			if(ny + k - 1 > 2 * k and nx + k - 1 > 2 * k) {
				cnt += imos.get(1, 1, y - 1, x - 1);
			}
			ans = max(ans, max(cnt, n - cnt));
		}
	}
	cout << ans << '\n';
	return 0;
}

