int main(){
    ll N,K;
    cin >> N >> K;
    vector<vector<ll>> B(K,vector<ll>(K,0)),W(K,vector<ll>(K,0));
    rep(i,N){
        ll x,y;
        char c;
        cin >> x >> y >> c;
        ll a=x%K,b=y%K;
        ll z=(x-a)/K+(y-b)/K;
        if (c=='B'){
            if (z%2==0){
                B[a][b]++;
            }
            else {
                W[a][b]++;
            }
        }
        else {
            if (z%2==0){
                W[a][b]++;
            }
            else {
                B[a][b]++;
            }
        }
    }
    rep(i,K){
        rep(j,K-1){
            B[i][j+1]+=B[i][j];
            W[i][j+1]+=W[i][j];
        }
    }
    rep(i,K-1){
        rep(j,K){
            B[i+1][j]+=B[i][j];
            W[i+1][j]+=W[i][j];
        }
    }
    ll ans=0;
    rep(i,K){
        rep(j,K){
            ll count=0;
            count+=2*B[i][j];
            count+=W[i][K-1]-W[i][j];
            count+=W[K-1][j]-W[i][j];
            count+=B[K-1][K-1]-B[K-1][j]-B[i][K-1];
            count=max(count,N-count);
            ans=max(ans,count);
        }
    }
    cout << ans << endl;
}

