int main(){
  ll N,K; cin >> N >> K;
  //(x,y)が白　と　(x,y+K)が黒は同値
  vector<ll> x(N), y(N);
  REP(i,N){
    char t;
    cin >> x[i] >> y[i] >> t;
    if(t=='W') y[i] += K;
    x[i] %= 2*K;
    y[i] %= 2*K;
  }
  ll ans = 0;
  //(+K,+K)平行移動
  vector<vector<ll>> sum(5*K+1, vector<ll>(5*K+1,0));
  //左下(i,j)として加算
  auto add_cnt = [&](ll i, ll j){
    sum[i][j]++;
    sum[i+K][j+K]++;
    sum[i][j+K]--;
    sum[i+K][j]--;
  };
  REP(i,N){
    add_cnt(x[i]+2*K,y[i]);
    add_cnt(x[i],y[i]+2*K);
    REP(j,3) {
      add_cnt(x[i]+j*K,y[i]+j*K);
    }
  }
  //累積和とる
  REP(i,5*K) REP(j,5*K){
    sum[i][j+1] += sum[i][j];
  }
  REP(j,5*K)REP(i,5*K){
    sum[i+1][j] += sum[i][j];
  }
  REP(i,5*K+1) REP(j,5*K+1){
    ans = max(ans,sum[i][j]);
  }
  cout << ans << endl;
}

