template<class T>
inline bool chmax(T& x, T y){
    if(x < y){
        x = y;
        return true;
    }
    return false;
}
template<class T>
inline bool chmin(T& x, T y){
    if(x > y){
        x = y;
        return true;
    }
    return false;
}

template<class T>
struct CumulativeSum2D{
    vector<vector<T>> data;

    CumulativeSum2D(int W, int H) : data(W + 1, vector<int>(H + 1, 0)) {}

    void add(int x, int y, T z){
        ++x, ++y;
        if(x >= data.size() || y >= data[0].size()) return;
        data[x][y] += z;
    }

    void build(){
        for(int i = 1; i < data.size(); ++i){
            for(int j = 1; j < data[i].size(); ++j){
                data[i][j] += data[i][j - 1] + data[i - 1][j] - data[i - 1][j - 1];
            }
        }
    }

    T query(int sx, int sy, int gx, int gy){
        return (data[gx][gy] - data[sx][gy] - data[gx][sy] + data[sx][sy]);
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    CumulativeSum2D<int> S(k * 2, k * 2);
    for(int i = 0; i < n; ++i){
        int x, y;
        char c;
        cin >> x >> y >> c;
        if(c == 'B')    x += k;
        x %= k * 2, y %= k * 2;
        S.add(x, y, 1);
    }
    S.build();
    int ans = 0;
    for(int i = 0; i <= k; ++i){
        for(int j = 0; j <= k; ++j){
            int X = S.query(i, j, i + k, j + k);
            X += S.query(0, 0, i, j);
            X += S.query(i + k, 0, k * 2, j);
            X += S.query(0, j + k, i, k * 2);
            X += S.query(i + k, j + k, k * 2, k * 2);
            chmax(ans, X);
        }
    }
    for(int i = k; i <= k * 2; ++i){
        for(int j = 0; j <= k; ++j){
            int X = S.query(i, j, k * 2, j + k);
            X += S.query(i - k, 0, i, j);
            X += S.query(i - k, j + k, i, k * 2);
            X += S.query(0, j, i - k, j + k);
            chmax(ans, X);
        }
    }
    for(int i = 0; i <= k; ++i){
        for(int j = k; j <= k * 2; ++j){
            int X = S.query(i, j, i + k, k * 2);
            X += S.query(0, j - k, i, j);
            X += S.query(i + k, j - k, k * 2, j);
            X += S.query(i, 0, i + k, j - k);
            chmax(ans, X);
        }
    }
    cout << ans << endl;
}

