LL N, K;

bool is_even(LL num) {
	return (num % 2LL) == 0;
}

bool is_black(LL X, LL Y) {

	if (is_even(X / K)) {
		if (is_even(Y / K)) {
			return true;
		}
		else {
			return false;
		}
	}
	else {
		if (is_even(Y / K)) {
			return false;
		}
		else {
			return true;
		}
	}

}

int main() {
