	{
		cnt=0;
		fill(y1,y1+2*k+1,0);
		for(int j=1;j<=n;j++)
		{
			bool p=(i<=x[j]&&x[j]<i+k);
			bool q=(0<=y[j]&&y[j]<k);
			if(p^q==c[j])
				cnt++,y1[y[j]]++;
			else
				y1[y[j]]--;
		}
		for(int j=0;j<=k;j++)
		{
			Max=max(Max,max(cnt,n-cnt));
			if(j!=k)
				cnt=cnt-y1[j]-y1[k+j];
		}
	}
	printf("%d\n",Max);
