void solve(int ca){
    int N,K;cin>>N>>K;
    int x,y; char c;
    int white=0;
    for (int i = 0; i < N; ++i) {
        cin>>x>>y>>c;
        if(c=='B') bcnt[x%(2*K)][y%(2*K)]++;
        else {
            wcnt[x % (2 * K)][y % (2 * K)]++;
            white++;
        }
    }

    for (int i = 0; i < 2 * K; ++i) {
        for (int j = 0; j < 2 * K; ++j) {
            bruiseki[i+1][j+1]=bcnt[i][j]+bruiseki[i+1][j]+bruiseki[i][j+1]-bruiseki[i][j];
            wruiseki[i+1][j+1]=wcnt[i][j]+wruiseki[i+1][j]+wruiseki[i][j+1]-wruiseki[i][j];
        }
    }

    int ans=0;
    for (int i = 0; i < K; ++i) {
        for (int j = 0; j < K; ++j) {
            int tmp=0;
            //black
            tmp+=bruiseki[i+K][j+K]-bruiseki[i][j+K]-bruiseki[i+K][j]+bruiseki[i][j];
            tmp+=bruiseki[2*K][2*K]-bruiseki[i+K][2*K]-bruiseki[2*K][j+K]+bruiseki[i+K][j+K];
