            tmp+=bruiseki[i][2*K]-bruiseki[i][K+j]-bruiseki[0][2*K]+bruiseki[0][K+j];
            tmp+=bruiseki[2*K][j]-bruiseki[2*K][0]-bruiseki[K+i][j]+bruiseki[K+i][0];
            //white
            tmp+=white;
            tmp-=wruiseki[i+K][j+K]-wruiseki[i][j+K]-wruiseki[i+K][j]+wruiseki[i][j];
            tmp-=wruiseki[2*K][2*K]-wruiseki[i+K][2*K]-wruiseki[2*K][j+K]+wruiseki[i+K][j+K];
            tmp-=wruiseki[i][j]-wruiseki[i][0]-wruiseki[0][j];
            tmp-=wruiseki[i][2*K]-wruiseki[i][K+j]-wruiseki[0][2*K]+wruiseki[0][K+j];
            tmp-=wruiseki[2*K][j]-wruiseki[2*K][0]-wruiseki[K+i][j]+wruiseki[K+i][0];

            ans=max(ans,tmp);
        }
    }

    cout<<ans<<endl;


