using namespace std;

const int MAXN = 1010;
int G[MAXN*2][MAXN*2];

int calc(int x1, int y1, int x2, int y2)
{
    return G[x2][y2] - G[x1][y2] - G[x2][y1] + G[x1][y1];
}

int main()
{
    int n,k,x,y;
    char ch;
    scanf("%d %d",&n,&k);
    for(int i = 0; i < n; ++i)
    {
        scanf("%d %d %c",&x,&y,&ch);
        x = x%(2*k);
        y = y%(2*k);
        if(ch == 'W')
            y += k;
        ++G[x%(2*k)+1][y%(2*k)+1];
    }
    for(int i = 1; i <= 2*k; ++i)
        for(int j = 1; j <= 2*k; ++j)
            G[i][j] = G[i][j] + G[i-1][j] + G[i][j-1] - G[i-1][j-1];

    int res = 0, sum;
    for(int i = 1; i <= k; ++i)
    {
        for(int j = 1; j <= k; ++j)
        {
            sum = calc(0,0,i,j);
            sum += calc(i,j,i+k,j+k);
            sum += calc(i+k,j+k,2*k,2*k);
            sum += calc(i+k,0,2*k,j);
            sum += calc(0,j+k,i,2*k);
            sum = max(sum,n-sum);
            res = max(res,sum);
        }
    }
    printf("%d\n",res);
    return 0;
}

