int safe(int x, int T) {
    return max(0, min(x, T));
}

void fill(vector<vector<int>> &v, int x, int y, int K) {
    int right = safe(x + 1, 2*K);
    int left = safe(x + 1 - K, 2*K);
    int top = safe(y + 1, 2*K);
    int bot = safe(y + 1 - K, 2*K);

    v[right][top]++;
    v[left][bot]++;
    v[left][top]--;
    v[right][bot]--;
}

