template <class T> struct Sum2d {
    vector<vector<T>> data;
    Sum2d(int h, int w) : data(h + 1, vector<T>(w + 1, 0)) {}
    void add(int y, int x, T val) {
        y++, x++;
        if(y >= (int)data.size() || x >= (int)data[0].size()) {
            return;
        }
        data[y][x] += val;
    }
    void build() {
        for(int i = 1; i < (int)data.size(); i++) {
            for(int j = 1; j < (int)data[i].size(); j++) {
                data[i][j] +=
                    (data[i][j - 1] + data[i - 1][j] - data[i - 1][j - 1]);
            }
        }
    }
    // [sx, gx) × [sy, gy)
    T get(int sx, int sy, int gx, int gy) {
        return (data[gy][gx] - data[sy][gx] - data[gy][sx] + data[sy][sx]);
    }
};

int main() {
