                sum.add(y + a * 2 * k, x + b * 2 * k, 1);
            }
        }
    }
    sum.build();
    int ans = 0;
    for(int i = 0; i < 2 * k; i++) {
        for(int j = 0; j < 2 * k; j++) {
            chmax(ans, sum.get(i, j, i + k, j + k) +
                           sum.get(i + k, j + k, i + 2 * k, j + 2 * k));
        }
    }
    cout << ans << endl;
}

