int mat(int x1,int y1,int x2,int y2){

  int p,q,r;

  if(x2<0||y2<0) return 0;
  if((x1>2*K-1)||(y1>2*K-1)) return 0;
  if(x1<0) x1=0; 
  if(y1<0) y1=0;
  if(x2>2*K-1) x2=2*K-1; 
  if(y2>2*K-1) y2=2*K-1;

  if(x1-1>=0){
    p=M[x1-1][y2];
  }
  else{
    p=0;
  }

  if(y1-1>=0){
    q=M[x2][y1-1];
  }
  else{
    q=0;
  }

  if((x1-1>=0)&&(y1-1>=0)){
    r=M[x1-1][y1-1];
  }else{
    r=0;
  }

  return M[x2][y2]-q-p+r;

}

int add(int i,int j){
  int a1,a2,a3;
  a1=mat(i-K,j+K,i-1,j+2*K-1);
  a2=mat(i-K,j-K,i-1,j-1);
  a3=mat(i+K,j-K,i+2*K-1,j-1);
  return a1+a2+a3;
}

int cnt(int i,int j){
