using namespace std;

int order[2001][2001] = {};

int sum_square(int px, int py, int K) {
	int cnt = 0;
	int l = max(0, px - 1);
	int r = min(px + K - 1, 2 * K - 1);
	int b = max(0, py - 1);
	int t = min(py + K - 1, 2 * K - 1);
	if (t < 0 || r < 0 || b > 2 * K - 1 || l > 2 * K - 1) return 0;
	cnt += order[r][t];
	if (px > 0) cnt -= order[l][t];
	if (py > 0) cnt -= order[r][b];
	if (px > 0 && py > 0) cnt += order[l][b];
	return cnt;
}

int main(int argc, char *argv[]) {
	int N, K;
	cin >> N >> K;

	for (int i = 0; i < N; i++) {
		int x, y;
		string c;
		cin >> x >> y;
		cin >> c;
		if (c[0] == 'W')
			x += K;
		order[x % (2 * K)][y % (2 * K)] += 1;
	}


	for (int y = 0; y < 2 * K + 1; y++) {
		for (int x = 0; x < 2 * K; x++) {
			order[x + 1][y] += order[x][y];
		}
	}

	for (int y = 0; y < 2 * K; y++) {
		for (int x = 0; x < 2 * K + 1; x++) {
			order[x][y + 1] += order[x][y];
		}
	}

	int max = 0;
	for (int px = 0; px < 2 * K; px++) {
		for (int py = 0; py < 2 * K; py++) {
			int cnt = 0;
			cnt += sum_square(px, py, K);
			cnt += sum_square(px + K, py + K, K);
			cnt += sum_square(px - K, py + K, K);
			cnt += sum_square(px + K, py - K, K);
			cnt += sum_square(px - K, py - K, K);

			if (cnt > max) max = cnt;
		}
	}

	cout << max << endl;
	return 0;
}

