ll SW(ll y2,ll x2,ll y1,ll x1){
  // for(int i = max(0LL,y1);i<=min(KK-1,y2);i++)
  //   for(int j = max(0LL,x1);j<=min(KK-1,x2);j++) g[i][j]=0;

  return IW(y2,x2) - IW(y2,x1-1) - IW(y1-1,x2) + IW(y1-1,x1-1);
}

ll SB(ll y2,ll x2,ll y1,ll x1){
  // for(ll i = max(0LL,y1);i<=min(KK-1,y2);i++) for(ll j = max(0LL,x1);j<=min(KK-1,x2);j++) g[i][j]=1;
  // cout<<max(0LL,y1)<<"a"<<min(KK-1,y2)<<"b"<<max(0LL,x1)<<"c"<<min(KK-1,x2)<<endl;
  // cout<<y2<<" "<<x2<<" "<<y1<<" "<<x1<<endl;
  return IB(y2,x2) - IB(y2,x1-1) - IB(y1-1,x2) + IB(y1-1,x1-1);
}


ll calc(ll y,ll x){
  // cout<<KK<<"~~~~~~~~~~~~~~~"<<endl;
  ll res = 0;
  // rep(i,KK) rep(j,KK) g[i][j] = 0;
  // cout<<"abs "<<KK-1<<" abw "<<x+K-1<<endl;
  res += SB(y+K-1,min(KK-1,x+K-1),y,x)-SW(y+K-1,min(KK-1,x+K-1),y,x);
  if(y>0 && x>0) res+= SB(y-1,x-1,0,x-K)-SW(y-1,x-1,0,x-K);
  if(x>0) res += SB(KK-1,x-1,y+K,x-K)-SW(KK-1,x-1,y+K,x-K);
  if(x<K && y>0) res += SB(y-1,KK-1,0,x+K)-SW(y-1,KK-1,0,x+K);
  if(x<K) res += SB(KK-1,KK-1,y+K,x+K)-SW(KK-1,KK-1,y+K,x+K);
  if(x>K) res += SB(y+K-1,x-K-1,y,0)-SW(y+K-1,x-K-1,y,0);
  res += SW(KK-1,KK-1,0,0);
  // cout<<y<<" "<<x<<" "<<res<<endl;
  // rep(i,10){
