void solve() {
    ll n, k;
    cin >> n >> k;
    vector<pair<ll, ll>> xy(n);
    for (int i=0; i<n; ++i) {
        char c;
        cin >> xy.at(i).first >> xy.at(i).second >> c;
        if (c == 'B') xy.at(i).first += k;
        xy.at(i).first %= 2 * k;
        xy.at(i).second %= 2 * k;
    }

    vector<vector<ll>> imos(k+2, vector<ll>(k+2));
    for (int i=0; i<n; ++i) {
        ll x = xy.at(i).first, y = xy.at(i).second;
        if (x/k == y/k) {
            ++imos.at(0).at(0);
            --imos.at(0).at(y%k+1);
            --imos.at(x%k+1).at(0);
            ++imos.at(x%k+1).at(y%k+1);
            ++imos.at(x%k+1).at(y%k+1);
            --imos.at(x%k+1).at(k+1);
            --imos.at(k+1).at(y%k+1);
            ++imos.at(k+1).at(k+1);
        } else {
            ++imos.at(x%k+1).at(0);
            --imos.at(k+1).at(0);
            --imos.at(x%k+1).at(y%k+1);
            ++imos.at(k+1).at(y%k+1);
            ++imos.at(0).at(y%k+1);
            --imos.at(x%k+1).at(y%k+1);
            --imos.at(0).at(k+1);
            ++imos.at(x%k+1).at(k+1);
        }
    }
    for (int i=0; i<k+2; ++i) {
        for (int j=0; j<k+2; ++j) {
            if (i > 0) imos.at(i).at(j) += imos.at(i-1).at(j);
            if (j > 0) imos.at(i).at(j) += imos.at(i).at(j-1);
            if (i > 0 && j > 0) imos.at(i).at(j) -= imos.at(i-1).at(j-1);
        }
    }
    ll res = 0;
    for (int i=0; i<k+1; ++i) for (int j=0; j<k+1; ++j) chmax(res, imos.at(i).at(j));
    cout << res << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(20);

    solve();

    return 0;
}

