class Imos2D {
public:
	//vectorの要素数
	ll H, W;
	//[Lx[i], Rx[i]) x [Ly[i], Ry[i])の範囲に1を加算する
	vector<ll> Lx, Rx, Ly, Ry;
	//累積和したvector
	vector<vector<ll>> rui;

	Imos2D(ll H, ll W, vector<ll> &Lx, vector<ll> &Rx, vector<ll> &Ly, vector<ll> &Ry)
	 : H(H), W(W), Lx(Lx), Rx(Rx), Ly(Ly), Ry(Ry) {
		assert(Lx.size() == Rx.size());
		assert(Ly.size() == Ry.size());
		assert(Lx.size() == Ly.size());
		rui.assign(H, vector<ll>(W, 0));
		build();
	}

	Imos2D(ll H, ll W, vector<tuple<ll, ll, ll, ll>> &range) : H(H), W(W) {
		rui.assign(H, vector<ll>(W, 0));
		ll rsize = range.size();
		Lx.assign(rsize, 0);
		Rx.assign(rsize, 0);
		Ly.assign(rsize, 0);
		Ry.assign(rsize, 0);
		for (ll i = 0; i < rsize; ++i) {
			tie(Lx[i], Rx[i], Ly[i], Ry[i]) = range[i];
		}
		build();
	}

	void build() {
		// 重みの加算
		for (ll i = 0, N = Lx.size(); i < N; ++i) {
			rui[Lx[i]][Ly[i]]++;
			if(Rx[i] < H) rui[Rx[i]][Ly[i]]--;
			if(Ry[i] < W) rui[Lx[i]][Ry[i]]--;
			if(Rx[i] < H && Ry[i] < W) rui[Rx[i]][Ry[i]]++;
		}
		// 横方向への累積和
		for (ll i = 0; i < H; ++i) 
			for (ll j = 1; j < W; ++j) 
				rui[i][j] += rui[i][j-1];
		// 縦方向の累積和
		for (ll i = 1; i < H; ++i) 
			for (ll j = 0; j < W; ++j) 
				rui[i][j] += rui[i-1][j];		
	}

	// ruiの[x1, x2) x [y1, y2)に対して関数fを適用した結果を返却する
	template<typename F>
	ll query(F f, ll x1, ll x2, ll y1, ll y2) {
		ll val = rui[x1][y1];
		for (ll i = 0; i < x2; ++i)
			for (ll j = 0; j < y2; ++j) 
				if(i>x1 || j>y1) val = f(val, rui[i][j]);
		return val;
	}

	// ruiの全域に対して関数fを適用した結果を返却する
	template<typename F>
	ll query(F f) {
		return query(f, 0, H, 0, W);
	}
};

