const ll MAX_N = 1e5 + 10;

int main(){
  int N, K;
  ll x[MAX_N], y[MAX_N];
  char c[MAX_N];
  cin >> N >> K;
  for (int i = 0; i < N; i++) {
  	cin >> x[i] >> y[i] >> c[i];
  	if (c[i]=='W') {
  		c[i] = 'B';
  		y[i] += K;
  	}
  	x[i] %= 2*K;
  	y[i] %= 2*K;
  }
  int ans = 0;
  for (ll sx = 0; sx < 2*K; ++sx)
  {
  	for (ll sy = 0; sy < 2*K; ++sy)
  	{
  		int cnt = 0;
  		for (int i = 0; i < N; ++i) {
  			if ((sx<=x[i] && x[i]<sx+K) && (sy<=y[i] && y[i]<sy+K)) cnt++;
  			else if ((sx<=x[i]+2*K && x[i]+2*K<sx+K) && (sy<=y[i] && y[i]<sy+K)) cnt++;
  			else if ((sx<=x[i] && x[i]<sx+K) && (sy<=y[i]+2*K && y[i]+2*K<sy+K)) cnt++;
  			else if ((sx<=x[i]+K && x[i]+K<sx+K) && (sy<=y[i]+K && y[i]+K<sy+K)) cnt++;
  			else if ((sx<=x[i]-2*K && x[i]-2*K<sx+K) && (sy<=y[i] && y[i]<sy+K)) cnt++;
  			else if ((sx<=x[i] && x[i]<sx+K) && (sy<=y[i]-2*K && y[i]-2*K<sy+K)) cnt++;
  			else if ((sx<=x[i]-K && x[i]-K<sx+K) && (sy<=y[i]-K && y[i]-K<sy+K)) cnt++;
  		}
  		ans = max(ans, cnt);
  	}
  }

  cout << ans << endl;

  return 0;
}

