long long cnt[4005][4005];

void cntinc(int x,int xend,int y,int yend){
  cnt[x][y]++;
  cnt[xend][y]--;
  cnt[x][yend]--;
  cnt[xend][yend]++;
}

int main(){
  int n,k;
  cin>>n>>k;
  for(int i=0;i<n;i++){
    int x,y;
    char cc;
    cin>>x>>y>>cc;
    if(cc == 'W') x += k;

    x %= 2*k;
    y %= 2*k;

    bool even = (x >= k) ^ (y >= k);

    x %= k;
    y %= k;

    if(even){
      cntinc(0,x+1,y+1,y+1+k);
      cntinc(x+1,x+k+1,0,y+1);
      cntinc(x+1,x+k+1,y+k+1,2*k);
      cntinc(x+k+1,2*k,y+1,y+k+1);
    } else {
      cntinc(0,x+1,0,y+1);
      cntinc(0,x+1,y+k+1,2*k);
      cntinc(x+k+1,2*k,0,y+1);
      cntinc(x+k+1,2*k,y+k+1,2*k);
      cntinc(x+1,x+k+1,y+1,y+k+1);
    }

  }


  for(int i=0;i<=2*k;i++){
    for(int j=1;j<=2*k;j++){
      cnt[i][j] += cnt[i][j-1];
    }
  }

  for(int i=0;i<=2*k;i++){
    for(int j=1;j<=2*k;j++){
      cnt[j][i] += cnt[j-1][i];
    }
  }

  /*for(int i=0;i<=k;i++){
    for(int j=0;j<=2*k;j++)cout<<cnt[i][j]<<" ";cout<<endl;
  }*/

  long long ma = 0;
  for(int i=0;i<=2*k;i++){
    for(int j=0;j<=2*k;j++){
      ma = max(ma,cnt[i][j]);
    }
  }


  cout<<ma<<endl;

}

