int mat[3000][3000];

int main()
{
	int N, K;
	cin >> N >> K;
	memset(mat, 0, sizeof(mat));

	for (auto i = 0; i < N; ++i)
	{
		long long x, y;
		char c;
		cin >> x >> y >> c;

		x %= 2 * K;
		y %= 2 * K;
		if (c == 'B')
		{
			auto sx = max((int)x - K + 1, 0);
			auto sy = max((int)y - K + 1, 0);
			auto ex = min((int)x + 1, 2 * K);
			auto ey = min((int)y + 1, 2 * K);
			++mat[sy][sx];
			--mat[ey][sx];
			--mat[sy][ex];
			++mat[ey][ex];
			if (x >= K && y >= K)
			{
				sx = max((int)x - 2 * K + 1, 0);
				sy = max((int)y - 2 * K + 1, 0);
				ex = (int)x - K + 1;
				ey = (int)y - K + 1;
				++mat[sy][sx];
				--mat[ey][sx];
				--mat[sy][ex];
				++mat[ey][ex];
			}
			else if (x < K && y < K)
			{
				sx = (int)x + 1;
				sy = (int)y + 1;
				ex = (int)x + K + 1;
				ey = (int)y + K + 1;
				++mat[sy][sx];
				--mat[ey][sx];
				--mat[sy][ex];
				++mat[ey][ex];
			}
		}
		else
		{
			if (y >= K)
			{
				auto sx = max((int)x - K + 1, 0);
				auto sy = max((int)y - 2 * K + 1, 0);
				auto ex = min((int)x + 1, 2 * K);
				auto ey = (int)y - K + 1;
				++mat[sy][sx];
				--mat[ey][sx];
				--mat[sy][ex];
				++mat[ey][ex];
			}
			else
			{
				auto sx = max((int)x - K + 1, 0);
				auto sy = (int)y + 1;
				auto ex = min((int)x + 1, 2 * K);
				auto ey = (int)y + K + 1;
				++mat[sy][sx];
				--mat[ey][sx];
				--mat[sy][ex];
				++mat[ey][ex];
			}
			if (x >= K)
			{
				auto sx = max((int)x - 2 * K + 1, 0);
				auto sy = max((int)y - K + 1, 0);
				auto ex = (int)x - K + 1;
				auto ey = min((int)y + 1, 2 * K);
				++mat[sy][sx];
				--mat[ey][sx];
				--mat[sy][ex];
				++mat[ey][ex];
			}
			else
			{
				auto sx = (int)x + 1;
				auto sy = max((int)y - K + 1, 0);
				auto ex = (int)x + K + 1;
				auto ey = min((int)y + 1, 2 * K);
				++mat[sy][sx];
				--mat[ey][sx];
				--mat[sy][ex];
				++mat[ey][ex];
			}
		}
	}

	for (auto i = 0; i <= 2 * K; ++i)
	{
		for (auto j = 1; j <= 2 * K; ++j)
		{
			mat[i][j] += mat[i][j - 1];
		}
	}

	for (auto i = 0; i <= 2 * K; ++i)
	{
		for (auto j = 1; j <= 2 * K; ++j)
		{
			mat[j][i] += mat[j - 1][i];
		}
	}

	auto result = 0;
	for (auto i = 0; i < 2 * K; ++i)
	{
		for (auto j = 0; j < 2 * K; ++j)
		{
			result = max(result, mat[i][j]);
		}
	}

	cout << result << endl;

	return 0;
}

