    int a[2*k+1][2*k+1];
    for(int i=0; i<n; i++){
        int x, y;
        char c;
        cin >> x >> y >> c;
        if(c == 'W') y += k;
        x = x%2*k;
        y = y%2*k;
        a[x][y]++;  
    }

    // x direction
    for(int i=0; i<2*k; i++){
        for(int j=0; j<2*k-1; j++){
            a[i][j+1] += a[i][j];
        }
    }
    // y direction
    for(int j=0; j<2*k; j++){
        for(int i=0; i<2*k-1; i++){
            a[i+1][j] +=a[i][j];
        }
    }
    int ans = 0;
    for(int i=0; i<k; i++){
        for(int j=0; j<k; j++){
            int tmp=0;
            tmp += a[i+k][j+k]- a[i][j];
            tmp += a[i-1][j-1] - a[0][0];
            tmp += a[2*k-1][2*k-1] - a[i+k][j+k];
            tmp += a[2*k-1][j-1] - a[i+k][0];
            tmp += a[i-1][2*k-1] - a[0][j+k];
            tmp = max(ans, tmp);
        }
    }

    cout << ans << endl;
    return 0;
}

