int main(){
  	int N, K;
  	std::cin >> N >> K;
  	int Npix = 4*K*K, Naxis = 2*K;
  	std::vector<int> x(N), y(N), map(Npix), master(Npix);
  	std::vector<char> c;
  	for(int i = 0; i < Npix; i++){
      	int a = i%(Naxis);
      	int b = i/(Naxis);
      	if((a < K && b < K) || (a >= K && b >= K)) master[i] = 1;
    }
  	for(int i = 0; i < N; i++){
      	std::cin >> x[i] >> y[i] >> c[i];
      	if(c[i] == 'w') y[i] += K;
      	x[i] %= Naxis;
      	y[i] %= Naxis;
      	for(int j = 0; j < Npix; j++) map[(Naxis*(y[i]+1)+x[i]+1+j)%(Npix)] += master[j];
    }
	std::vector<int>::iterator iter = std::max_element(map.begin(), map.end());
	std::cout << int(std::distance(map.begin(), iter)) << std::endl;
}

