      if (i != k - 1 && j != k - 1) t1 += csw.Get(i + 1 + k, j + 1 + k, k - 1 + k, k - 1 + k);
      t2 = csb.Get(0 + k, 0 + k, k - 1 + k, k - 1 + k) - csb.Get(0 + k, 0 + k, i + k, j + k);
      if (i != k - 1 && j != k - 1) t2 -= csb.Get(i + 1 + k, j + 1 + k, k - 1 + k, k - 1 + k);

      tw += t1, tb += t2;
      t1 = 0, t2 = 0;

      t2 += csb.Get(0 + k, 0, i + k, j);
      if (i != k - 1 && j != k - 1) t2 += csb.Get(i + 1 + k, j + 1, k - 1 + k, k - 1);
      t1 = csw.Get(0 + k, 0, k - 1 + k, k - 1) - csw.Get(0 + k, 0, i + k, j);
      if (i != k - 1 && j != k - 1) t1 -= csw.Get(i + 1 + k, j + 1, k - 1 + k, k - 1);

      tw += t1, tb += t2;
      t1 = 0, t2 = 0;

      t2 += csb.Get(0, 0 + k, i, j + k);
      if (i != k - 1 && j != k - 1) t2 += csb.Get(i + 1, j + 1 + k, k - 1, k - 1 + k);
      t1 = csw.Get(0, 0 + k, k - 1, k - 1 + k) - csw.Get(0, 0 + k, i, j + k);
      if (i != k - 1 && j != k - 1) t1 -= csw.Get(i + 1, j + 1 + k, k - 1, k - 1 + k);      

      tw += t1, tb += t2;
      ans = max(ans, tw + tb);
    }
  }

  for (int i = 0; i < k; ++i) {
    for (int j = 0; j < k; ++j) {
      int tb = 0, tw = 0;
      int t1 = 0, t2 = 0;

