}

int getcheck2(int x,int y,int c) {
    int ret = getrect(x,0,x+k,y,c) + getrect(0,y,x,y+k,c) + getrect(x+k,y,2*k,y+k,c) + getrect(x,y+k,x+k,2*k,c);
