            white[x%K+1][y%K+1]++;
    }
    for(int i = 0; i < K+1; ++i) {
        for(int j = 1; j < K+1; ++j) {
            black[i][j] += black[i][j-1];
            white[i][j] += white[i][j-1];
        }
    }
    for(int i = 1; i < K+1; ++i) {
        for(int j = 0; j < K+1; ++j) {
