			z[i][j] += (i?z[i-1][j]:0) + (j?z[i][j-1]:0) - (i&&j?z[i-1][j-1]:0);
			maxq(u, -m[i][j]);
			maxq(u, -z[i][j]);
		}
	}
	cout << u;
	return 0;
}

