template<class T>
struct CumulativeSum2D{
    vector<vector<T>> data;

    CumulativeSum2D(int W, int H) : data(W + 1, vector<int>(H + 1, 0)) {}

    void add(int x, int y, T z){
        ++x, ++y;
        if(x >= data.size() || y >= data[0].size()) return;
        data[x][y] += z;
    }

    void build(){
        for(int i = 1; i < data.size(); ++i){
            for(int j = 1; j < data[i].size(); ++j){
                data[i][j] += data[i][j - 1] + data[i - 1][j] - data[i - 1][j - 1];
            }
        }
    }

    T query(int sx, int sy, int gx, int gy){
        return (data[gx][gy] - data[sx][gy] - data[gx][sy] + data[sx][sy]);
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<int> x(n), y(n);
    int sz = k * 2;
    CumulativeSum2D<int> sum(sz, sz);
    for(int i = 0; i < n; ++i){
        char c;
        cin >> x[i] >> y[i] >> c;
        if(c == 'W')    y[i] += k;
        x[i] %= sz;
        y[i] %= sz;
        sum.add(x[i], y[i], 1);
    }
    sum.build();
    int ans = 0;
    for(int i = 0; i <= k; ++i){
        for(int j = 0; j <= k; ++j){
            int foo = sum.query(i, j, i + k, j + k);
            foo += sum.query(max(0, i - k), max(0, j - k), i, j);
            foo += sum.query(i + k, max(0, j - k), min(sz, i + sz), j);
            foo += sum.query(max(0, i - k), j + k, i, min(sz, j + sz));
            foo += sum.query(i + k, j + k, min(sz, i + sz), min(sz, j + sz));
            chmax(ans, foo);
        }
    }
    cout << ans << endl;
}

