int f(const vector<vector<int>>& v, int x1, int y1, int x2, int y2) {
    int kk = v.size(), k = v.size() / 2;
    if (x1 >= kk || y1 >= kk || x2 < 0 || y2 < 0) return 0;
    x1 = max(0, min(x1, kk - 1));
    y1 = max(0, min(y1, kk - 1));
    x2 = max(0, min(x2, kk - 1));
    y2 = max(0, min(y2, kk - 1));
    int res = v[x2][y2];
    if (x1 > 0) {
        res -= v[x1 - 1][y2];
    }
    if (y1 > 0) {
        res -= v[x2][y1 - 1];
    }
    if (x1 > 0 && y1 > 0) {
        res += v[x1 - 1][y1 - 1];
    }
    return res;
}

int main() {
    int n, k;
    cin >> n >> k;
    vector<vector<int>> black(2 * k, vector<int> (2 * k, 0));
    vector<vector<int>> white(2 * k, vector<int> (2 * k, 0));
    int kk = 2 * k;
    int c1 = 0, c2 = 0;
    for (int i = 0; i < n; i++) {
        int x, y;
        cin >> x >> y;
        char color;
        cin >> color;
        x %= kk, y %= kk;
        if (color == 'W') {
            white[x][y]++;
            c1++;
        } else {
            black[x][y]++;
            c2++;
        }
    }

    for (int i = 0; i < kk; i++) {
        for (int j = 0; j < kk; j++) {
            if (i > 0) {
                white[i][j] += white[i - 1][j];
                black[i][j] += black[i - 1][j];
            }
            if (j > 0) {
                white[i][j] += white[i][j - 1];
                black[i][j] += black[i][j - 1];
            }
            if (i > 0 && j > 0) {
                white[i][j] -= white[i - 1][j - 1];
                black[i][j] -= black[i - 1][j - 1];
            }
        }
    }

    int res = 0;
    for (int i = 0; i <= k; i++) {
        for (int j = 0; j <= k; j++) {
            int cc1 = 0, cc2 = 0;
            cc1 += f(white, i, j, i + k - 1, j + k - 1);
            cc1 += f(white, i + k, j + k, i + kk - 1, j + kk - 1);
            cc1 += f(white, i + k, j - k, i + kk - 1, j - 1);
            cc1 += f(white, i - k, j + k, i - 1, j + kk - 1);
            cc1 += f(white, i - k, j - k, i - 1, j - 1);
            cc2 += f(black, i, j, i + k - 1, j + k - 1);
            cc2 += f(black, i + k, j + k, i + kk - 1, j + kk - 1);
            cc2 += f(black, i + k, j - k, i + kk - 1, j - 1);
            cc2 += f(black, i - k, j + k, i - 1, j + kk - 1);
            cc2 += f(black, i - k, j - k, i - 1, j - 1);

            res = max(res, cc1 + c2 - cc2);
            res = max(res, cc2 + c1 - cc1);
        }
    }
    cout << res << endl;
}

