        x0 = (x + K) % (2 * K);
        y0 = (y + K) % (2 * K);
        b[x0][y0]++;
        if(x0 < K) b[x0 + K][y0]--;
        if(y0 < K) b[x0][y0 + K]--;
        if(x0 < K && y0 < K) b[x0 + K][y0 + K]++;
    }

    s[0][0] = b[0][0];
    int ans = s[0][0];

    FOR(j, 1, 2 * K){
        s[0][j] = s[0][j - 1] + b[0][j];
        ans = max(ans, s[0][j]);
    }
    FOR(i, 1, 2 * K){
        int tmp = 0;
        FOR(j, 0, 2 * K){
            tmp += b[i][j];
            s[i][j] = s[i - 1][j] + tmp;
            ans = max(ans, s[i][j]);
        }
    }

    cout << ans;


    return 0;
}


