using namespace std;

int main()
{
    int N, K;
    cin >> N >> K;

    // スコア行列：score[y][x]は白チェッカー左下が(x, y)のときの正解数-誤答数
    int score[K][K] = {};
    // 白チェッカー左下が(0, 0)のときの希望の数
    int base_hope = 0;
    for (int i = 0; i < N; i++) {
        int x, y, x_div, y_div, x_mod, y_mod;
        char c;
        cin >> x >> y >> c;
        x_div = x / K, y_div = y / K;
        x_mod = x % K, y_mod = y % K;
        if (((x_div + y_div) % 2 == 0 && c == 'W') || ((x_div + y_div) % 2 == 1 && c == 'B')) {
            base_hope++;
            score[y_mod][x_mod]++;
        } else {
            score[y_mod][x_mod]--;
        }
    }

    //スコア行列の累積和を求める
    for (int y = 0; y < K; y++) {
        for (int x = 0; x < K; x++) {
            int accum = score[y][x];
            if (x > 0)          accum += score[y][x-1];
            if (y > 0)          accum += score[y-1][x];
            if (x > 0 && y > 0) accum -= score[y-1][x-1];
            score[y][x] = accum;
        }
    }

    // 白チェッカー左下を移動させたときの希望の数を計算
    int max_hope = 0;
    for (int y = 0; y < K; y++) {
        for (int x = 0; x < K; x++) {
            int diff = 0, hope = base_hope;
            if (x > 0)          diff += score[K-1][x-1];
            if (y > 0)          diff += score[y-1][K-1];
            if (x > 0 && y > 0) diff -= 2 * score[y-1][x-1];
            hope -= diff;
            int larger_hope = hope > N - hope ? hope : N - hope;
            if (larger_hope > max_hope)
                max_hope = larger_hope;
        }
    }

    cout << max_hope << endl;
}

