void solve() {
    int n,K;
    cin >> n >> K;
    int x,y;
    char c;
    REP(i,0,n) {
        cin >> x >> y >> c;
        cnt[x%(2*K)][y%(2*K)][c == 'W']++;
    }
    REP(i,0,2*K) REP(j,0,2*K) REP(k,0,2) ru[i+1][j+1][k] = ru[i+1][j][k] + cnt[i][j][k];
    REP(j,0,2*K) REP(i,0,2*K) REP(k,0,2) ru[i+1][j+1][k] += ru[i][j+1][k];
    int ans = 0;
    REP(i,0,K) REP(j,0,K) {
        int b = 0, w = 0;
        b += ru[i][j][0];
        b += ru[i+K][j+K][0] - ru[i][j+K][0] - ru[i+K][j][0] + ru[i][j][0];
        b += ru[2*K][2*K][0] - ru[i+K][2*K][0] - ru[2*K][j+K][0] + ru[i+K][j+K][0];
        w += ru[i][j][1];
        w += ru[i+K][j+K][1] - ru[i][j+K][1] - ru[i+K][j][1] + ru[i][j][1];
        w += ru[2*K][2*K][1] - ru[i+K][2*K][1] - ru[2*K][j+K][1] + ru[i+K][j+K][1];
        w = ru[2*K][2*K][1] - w;
        ans = max(ans, b + w);
    }
