  std::vector<std::vector<int>> cntW(2 * K + 1, std::vector<int>(2 * K + 1, 0));
  for (int i = 0; i < N; ++i) {
    int x, y;
    char c;
    std::cin >> x >> y >> c;
    if (c == 'B') {
      ++cntB[x % (2 * K) + 1][y % (2 * K) + 1];
    } else {
      ++cntW[x % (2 * K) + 1][y % (2 * K) + 1];
    }
  }
  for (int i = 0; i <= 2 * K; ++i) {
    for (int j = 0; j + 1 <= 2 * K; ++j) {
      cntB[i][j + 1] += cntB[i][j];
      cntW[i][j + 1] += cntW[i][j];
    }
  }
  for (int i = 0; i + 1 <= 2 * K; ++i) {
    for (int j = 0; j <= 2 * K; ++j) {
      cntB[i + 1][j] += cntB[i][j];
      cntW[i + 1][j] += cntW[i][j];
    }
  }
  // K^2 個のstart positionについてその正方形に含まれる数を数えたい
  int ans = 0;
  auto allB = cntB[K * 2][K * 2];
  auto allW = cntW[K * 2][K * 2];
  auto get_squareB = [&](unsigned l, unsigned r, unsigned t, unsigned b) -> int {
    return cntB[r][b] + cntB[l][t] - cntB[l][b] - cntB[r][t];
  };
  auto get_squareW = [&](unsigned l, unsigned r, unsigned t, unsigned b) -> int {
    return cntW[r][b] + cntW[l][t] - cntW[l][b] - cntW[r][t];
  };
  for (int i = 0; i < K; ++i) {
    for (int j = 0; j < K; ++j) {
      auto pointB = get_squareB(i, i + K, 0, j) + get_squareB(0, i, j, j + K)
          + get_squareB(i, i + K, j + K, 2 * K) + get_squareB(i + K, 2 * K, j, j + K);
      auto pointW = get_squareW(i, i + K, 0, j) + get_squareW(0, i, j, j + K)
          + get_squareW(i, i + K, j + K, 2 * K) + get_squareW(i + K, 2 * K, j, j + K);
      ans = std::max({ans, pointB + allW - pointW, pointW + allB - pointB});
    }
  }
  std::cout << ans << std::endl;
  return 0;
}

