int main() {
	int N, K; cin >> N >> K;
	int x[100100], y[100100], c[100100];
	for (int i = 0; i < N; ++i) {
		char sc;
		cin >> x[i] >> y[i] >> sc;
		x[i] %= K * 2;
		y[i] %= K * 2;
		c[i] = (sc == 'W');
	}
	int white[1010][1010];
	memset(white, 0, sizeof(white));
	//white[x][y]=マス(x,y)を右上とした長方形に含まれている白マスー黒マスの総数
	int bnum = 0;
	//含まれている黒マスの数
	//k*kの範囲に絞る
	//座標をkで割った値の偶奇で色が変わる
	for (int i = 0; i < N; ++i) {
		c[i] += x[i] / K + y[i] / K;
		c[i] %= 2;
		x[i] %= K;
		y[i] %= K;
		white[x[i]][y[i]] += (c[i] ? 1 : -1);
		if (c[i] == 0)++bnum;
	}
	//二次元いもすの要領で展開
	for (int x = 0; x < K; ++x) {
		for (int y = 1; y < K; ++y) {
			white[x][y] += white[x][y - 1];
		}
	}
	for (int x = 1; x < K; ++x) {
		for (int y = 0; y < K; ++y) {
			white[x][y] += white[x - 1][y];
		}
	}
	int ans = 0;
	for (int x = 0; x < K; ++x) {
		for (int y = 0; y < K; ++y) {
			int w = white[K - 1][K - 1] - white[x][K - 1] - white[K - 1][y] + white[x][y] * 2 + bnum;
			ans = max(ans, max(w, N - w));
		}
	}
	cout << ans << endl;
	return 0;
}

