#define int long long

int pos(int x, int y, int k) {
  int x0, y0, ret;
  if (x < 0) x += (-x / (2 * k) + 1) * 2 * k;
  if (y < 0) y += (-y / (2 * k) + 1) * 2 * k;

  if (x % (2 * k) < k)
    x0 = 0;
  else
    x0 = 1;
  if (y % (2 * k) < k)
    y0 = 0;
  else
    y0 = 1;
  if (x0 == y0)
    return 1;
  else
    return 0;
}

signed main() {
  int n, k;
  cin >> n >> k;
  vector<int> x(n), y(n), z(n);
  for (int i = 0; i < n; i++) {
    int x0, y0;
    char c;
    cin >> x0 >> y0 >> c;
    x[i] = x0 % (2 * k);
    y[i] = y0 % (2 * k);
    if (c == 'B')
      z[i] = 0;
    else if (c == 'W')
      z[i] = 1;
  }
  int ans = 0;
  for (int i = 0; i < 2 * k; i++) {
    for (int j = 0; j < 2 * k; j++) {
      int same = 0;
      for (int l = 0; l < n; l++) {
        if (pos(x[l] + i, y[l] + j, k) == 1)
          same += (z[l] == 1);
        else
          same += (z[l] == 0);
      }
      ans = max(ans, same);
    }
  }
  cout << ans << endl;
  //  cout << -5 % 3 << endl;
}

