    cin >> constraints[i][0] >> constraints[i][1] >> c;
    constraints[i][0] = (constraints[i][0] % k + k) % k;
    constraints[i][1] = (constraints[i][1] % k + k) % k;
    constraints[i][2] = c == 'B';
  }
  sort(constraints.begin(), constraints.end(), [&](auto lhs, auto rhs) {
    return lhs[0] < rhs[0];
  });
  auto add = [&](vector<int> &bit, int point, int val) {
    for (; point < (int) bit.size(); point |= point + 1) {
      bit[point] += val;
    }
  };
  auto get = [&](vector<int> &bit, int p) {
    int ans = 0;
    for (; p >= 0; p = (p & (p + 1)) - 1) {
      ans += bit[p];
    }
    return ans;
  };
  int ans = 0;
  vector<vector<int>> bits(4, vector<int>(k, 0));
  for (int i = 0; i < n; ++i) {
    add(bits[2 * constraints[i][2] + 1], constraints[i][1], 1);
  }
  for (int x = 0, l = 0, r = 0; x < k / 2; ++x) {
    // [l, r)
    while (r < n && constraints[r][0] <= x + k / 2) {
      add(bits[2 * constraints[r][2]], constraints[r][1], 1);
      add(bits[2 * constraints[r][2] + 1], constraints[r][1], -1);
      ++r;
    }
    while (l < r && constraints[l][0] < x) {
      add(bits[2 * constraints[l][2]], constraints[l][1], -1);
      add(bits[2 * constraints[l][2] + 1], constraints[l][1], 1);
      ++l;
    }
    for (int y = 0; y < k / 2; ++y) {
      int a1 = get(bits[2], y + k / 2 - 1) - get(bits[2], y - 1);
      int a2 = get(bits[0], k - 1) - get(bits[0], y + k / 2 - 1) + get(bits[0], y - 1);
      int a3 = get(bits[1], y + k / 2 - 1) - get(bits[1], y - 1);
      int a4 = get(bits[3], k - 1) - get(bits[3], y + k / 2 - 1) + get(bits[3], y - 1);

      int b1 = get(bits[0], y + k / 2 - 1) - get(bits[0], y - 1);
      int b2 = get(bits[2], k - 1) - get(bits[2], y + k / 2 - 1) + get(bits[2], y - 1);
      int b3 = get(bits[3], y + k / 2 - 1) - get(bits[3], y - 1);
      int b4 = get(bits[1], k - 1) - get(bits[1], y + k / 2 - 1) + get(bits[1], y - 1);

      ans = max({ans, a1 + a2 + a3 + a4, b1 + b2 + b3 + b4});
    }
  }
  cout << ans << '\n';
  return 0;
}

