template<typename A, typename B> inline bool chmax(A &a, B b) { if (a<b) { a=b; return 1; } return 0; }
template<typename A, typename B> inline bool chmin(A &a, B b) { if (a>b) { a=b; return 1; } return 0; }
typedef long long ll;
typedef pair<int, int> pii;
const ll INF = 1e9+100;
const ll MOD = 1e9+7;
const bool debug = 1;
//-----------------------------------------------//

int N, K;
int sum[2][2001][2001];

int func(int y2, int x2, int y1, int x1, int col) {
	chmin(x2, 2*K-1); chmin(y2, 2*K-1);
	chmax(x1, 0); chmax(y1, 0);
	if (x1 > x2 || y1 > y2) return 0;
	return sum[col][y2+1][x2+1] - sum[col][y1][x2+1] - sum[col][y2+1][x1] + sum[col][y1][x1];
}

int main() {
	cin >> N >> K;
	REP(i, N) {
		int x, y;
		char c;
		scanf("%d %d %c", &x, &y, &c);
		x %= 2*K;
		y %= 2*K;
		sum[c=='W'][y + 1][x + 1]++;
	}

	REP(k, 2) {
		REP(i, 2*K+1) REP(j, 2*K) sum[k][i][j + 1] += sum[k][i][j];
		REP(j, 2*K+1) REP(i, 2*K) sum[k][i + 1][j] += sum[k][i][j];
	}

	int ans = 0;
	REP(y, K+1) {
		REP(x, K+1) {
			int cur = func(2*K-1, 2*K-1, 0, 0, 1);
			REP(k, 2) {
				int s = 0;
				s += func(y+K-1, x+K-1, y, x, k);
				s += func(y+2*K-1, x+2*K-1, y+K, x+K, k);
				s += func(y+2*K-1, x-1, y+K, x-K, k);
				s += func(y-1, x-1, y-K, x-K, k);
				s += func(y-1, x+2*K-1, y-K, x+K, k);
				if (k) s = -s;
				cur += s;
			}
			chmax(ans, cur);
		}
	}
	cout << ans << endl;

	return 0;
}

