int N, K;
int x, y;
char c;
vector<pair<int,int>> requests;

int main() {
  scanf("%d%d", &N, &K);
  for (int i = 0; i < N; ++i) {
    scanf("%d %d %c", &x, &y, &c);
    if (c == 'B') x += K;

    x = x % (2 * K);
    y = y % (2 * K);
    requests.push_back(make_pair(x, y));
  }

  // exhaustive search
  //   (i, j): lower left position of white area
  int maxval = 0;
  for (int i = 0; i < K; ++i) {
    for (int j = 0; j < K; ++j) {
      int val = 0;
      for (int r = 0; r < N; ++r) {
        x = (requests[r].first + K - i) / K;
        y = (requests[r].second + K - j) / K;

        if (x % 2 == y % 2) ++val;
      }
      if (val > maxval) maxval = val;
      if (N - val > maxval) maxval = N - val;
    }
  }

  printf("%d\n", maxval);
  return 0;
}

