typedef long long ll;

const int MAXK = 1000;

int c[2*MAXK+1][2*MAXK+1];
int sum[2*MAXK+1][2*MAXK+1];

int query(int x1, int y1, int x2, int y2){
  if(x1 >= x2 || y1 >= y2) return 0;
  // return sum of x1 <= x <= x2 && y1 <= y <= y2
  return sum[x2][y2] - sum[x1 - 1][y2] - sum[x2][y1 - 1] + sum[x1 - 1][y1 - 1];
}

int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);
  int N, K; cin >> N >> K;
  for(int i=0;i<N;i++){
    int x, y;
    char color;
    cin >> x >> y >> color;
    if(color == 'B'){
      c[x %(2*K) + 1][y %(2*K) + 1]++;
    }else{
      c[x %(2*K) + 1][(y + K) %(2*K) + 1]++;
    }
  }

  for(int i=1;i<=2*K;i++){
    for(int j=1;j<=2*K;j++){
      sum[i][j] = c[i][j] + sum[i-1][j] + sum[i][j-1] - sum[i-1][j-1];
      cout << sum[i][j] << " ";
    }
    cout << endl;
  }

  int maxnum = 0;
  for(int x=1;x<=K+1;x++){
    for(int y=1;y<=K+1;y++){
      // count num in five black squares
      int num = query(1, 1, x-1, y-1) + query(1, y+K, x-1, 2*K)
      + query(x, y, x+K-1, y+K-1) + query(x+K, 1, 2*K, y-1) + query(x+K, y+K, 2*K, 2*K);
      maxnum = max(max(num, N-num), maxnum);
    }
  }
  cout << maxnum << endl;
}

