int b[4010][4010], w[4010][4010];

int sumb(int p, int q, int r, int s) {
  int res = b[r][s];
  if (p > 0 && q > 0) res += b[p-1][q-1];
  if (p > 0) res -= b[p-1][s];
  if (q > 0) res -= b[r][q-1];
  return res;
}
int sumw(int p, int q, int r, int s) {
  int res = w[r][s];
  if (p > 0 && q > 0) res += w[p-1][q-1];
  if (p > 0) res -= w[p-1][s];
  if (q > 0) res -= w[r][q-1];
  return res;
}

int main() {
  cin.tie(0);
  ios_base::sync_with_stdio(false);
  cout << fixed << setprecision(10);

  cin >> N >> K;
  K2 = K << 1;
  for (int i = 0; i < N; i++) {
    cin >> x[i] >> y[i] >> c[i];
    x[i] %= K2;
    y[i] %= K2;
  }
  for (int i = 0; i < N; i++) {
    if (c[i] == 'B') {
      b[y[i]][x[i]]++;
      b[y[i]+K2][x[i]]++;
      b[y[i]][x[i]+K2]++;
      b[y[i]+K2][x[i]+K2]++;
    } else {
      w[y[i]][x[i]]++;
      w[y[i]+K2][x[i]]++;
      w[y[i]][x[i]+K2]++;
      w[y[i]+K2][x[i]+K2]++;
    }
  }
  for (int i = 0; i < 2*K2; i++) {
    for (int j = 0; j+1 < 2*K2; j++) {
      b[i][j+1] += b[i][j];
      w[i][j+1] += w[i][j];
    }
  }
  for (int j = 0; j < 2*K2; j++) {
    for (int i = 0; i+1 < 2*K2; i++) {
      b[i+1][j] += b[i][j];
      w[i+1][j] += w[i][j];
    }
  }
  int ans = 0;
  for (int i = 0; i < 2*K; i++) {
    for (int j = 0; j < 2*K; j++) {
      ans = max(ans, sumb(i, j, i+K-1, j+K-1)+sumb(i+K, j+K, i+2*K-1, j+2*K-1) + sumw(i+K, j, i+2*K-1, j+K-1) + sumw(i, j+K, i+K-1, j+2*K-1));
    }
  }
  cout << ans << endl;

  return 0;
}

