int pp[2000][1000];

void ps(int x, int y, int k){
  if (x < k){
    pp[x][y] += 1;
    pp[x+k][y] += -1;
    if (y == 0) return;
    pp[x+k][0] += 1;
    pp[x+k][y] += -1;
  }
  else {
    pp[x][y] += 1;
    pp[0][y] += 1;
    pp[x-k][y] += -1;
    if (y == 0) return;
    pp[x-k][0] += 1;
    pp[x-k][y] += -1;
  }
}

int main(){
  int n, k;
  cin >> n >> k;
  for (int i = 0; i < 2 * k; i++){
    for (int j = 0; j < k; j++){
      pp[i][j] = 0;
    }
  }

  for (int i = 0; i < n; i++){
    int x, y; char s[1];
    scanf("%d %d %c", &x, &y, s);
     x = x % (2*k);
     y = y % (2*k);
    if ((s[0] - 'B') != 0){
      y = (y + k) % (2*k);
    }
    if (y >= k) {
      y = y - k;
      x = (x + k) % (2 * k);
    }
    ps(x, y, k);
  }

  for (int i = 0; i < 2*k; i++){
    for (int j = 1; j < k; j++){
      pp[i][j] += pp[i][j-1];
    }
  }


  for (int i = 1; i < 2*k; i++){
    for (int j = 0; j < k; j++){
      pp[i][j] += pp[i-1][j];
    }
  }

  int m = 0;
  for (int i = 0; i < 2*k; i++){
    for (int j = 0; j < k; j++){
      m = max(m, pp[i][j]);
