            x += k;
        }
        if(y>=k){
            y-=k;
            x+=k;
        }
        x %= 2*k;
        s[x+1][y+1]++;
    }
    for(long x=0; x<2*k; x++){
        for(long y=0; y<k; y++){
            s[x+1][y+1] = s[x+1][y+1] + s[x][y+1] + s[x+1][y] - s[x][y];
        }
    }
    long max = 0;
    for(long x=0; x<k; x++){
        for(long y=0; y<k; y++){
            long t = calc(x, y, k, k-y)+calc(0, 0, x, y)+calc(x+k, 0, k-x, y);
            t = t<n/2 ? n-t : t;
            max = t>max ? t : max;
        }
    }
