int Max3(int a, int b, int c) {
	return (a)>(b) ? ((a)>(c) ? (a) : (c)) : ((b)>(c) ? (b) : (c));
}

int main() {
	int N, K;
	int x[100000], y[100000];
	char c[100000];
	scanf("%d %d", &N, &K);
	REP(i, N) {
		scanf("%d %d %c", &x[i], &y[i], &c[i]);
	}
	int ans=0;

	REP(i, K*K) {
		int anstmpw = 0, anstmpb = 0;
		REP(j, N) {
			int tmpx = x[j], tmpy = y[j];//元の位置
			if (tmpx < 0) {
				tmpx = -tmpx + ((K-1) - (i % K));//元の位置と基準点の差に
			}
			else {
				tmpx = tmpx + i % K;
			}
			if (tmpy < 0) {
				tmpy = tmpy + (K - 1) - i / K;
			}
			else {
				tmpy = tmpy + i / K;
			}
			int tmp = ((tmpx / K) % 2 + (tmpy / K) % 2) % 2;
