int check_BW(int x,int y,int K,int i,int j){

    if((x>=j && x<j+K) || (x<j-K)){
        if((y>=i && y<i+K) || (y<i-K)){
            return 1;
        }else{
            return 0;
        }
    }else{
        if((y>=i && y<i+K) || (y<i-K)){
            return 0;
        }else{
            return 1;
        }
    }
}

