int main(){
  int N, K;
  scanf("%d %d ", &N, &K);
  int white[2 * K + 1][2 * K + 1];
  int black[2 * K + 1][2 * K + 1];
  for(int x = 0; x <= 2 * K; x++){
    for(int y = 0; y <= 2 * K; y++){
      white[x][y] = 0;
      black[x][y] = 0;
    }
  }

  for(int i = 0; i < N; i++){
    int x, y;
    char c;
    scanf("%d %d %c ", &x, &y, &c);
    if(c == 'W') white[x % (2 * K) + 1][y % (2 * K) + 1]++;
    else black[x % (2 * K) + 1][y % (2 * K) + 1]++;
  }

  for(int y = 0; y <= 2 * K; y++){
    for(int x = 1; x <= 2 * K; x++){
      white[x][y] += white[x - 1][y];
      black[x][y] += black[x - 1][y];
    }
  }

  for(int x = 0; x <= 2 * K; x++){
    for(int y = 1; y <= 2 * K; y++){
      white[x][y] += white[x][y - 1];
      black[x][y] += black[x][y - 1];
    }
  }

  int w[4][4];
  int b[4][4];

  int count = 0;
  for(int x = 0; x <= 2 * K; x++){
    for(int y = 0; y <= 2 * K; y++){
      int cnt = 0;

      for(int i = 0; i < 4; i++){
        for(int j = 0; j < 4; j++){
          int xi = min(max(x - K + i * K, 0), 2 * K);
          int yj = min(max(y - K + j * K, 0), 2 * K);
          w[i][j] = white[xi][yj];
          b[i][j] = black[xi][yj];
        }
      }

      for(int i = 0; i < 4; i++){
        for(int j = 0; j < 4; j++){
          if((i + j) & 1){
            if(i < 3 && j < 3)
              cnt += 2 * w[i][j] - 2 * b[i][j];
            else
              cnt += w[i][j] - b[i][j];
          }else{
            if(i < 3 && j < 3)
              cnt += - 2 * w[i][j] + 2 * b[i][j];
            else if(i == 3 && j == 3)
              cnt += b[i][j];
            else
              cnt += -w[i][j] + b[i][j];
          }
        }
      }
      count = max(cnt, count);
    }
  }

  printf("%d\n", count);

  return 0;
}

