    val-=ruiseki[en_y][st_x];
    val-=ruiseki[st_y][en_x];
    val+=ruiseki[st_y][st_x];
    return val;
}


void cha(ll *a, ll *b, ll k, ll white){
    if(white==0){
        *a-=k;
    }
    ll x=mod_p(*a,k);
    ll y=mod_p(*b,k);
    if( llabs((*a+*b)-(x+y))/k %2 ){
        y+=k;
    }
    *a=x;
    *b=y;
}


