#include <stdlib.h>

int main(void){
    int N, K;

    scanf("%d%d", &N, &K);

    int i, j;

    int *x = (int *) malloc(sizeof(int) * N);
    int *y = (int *) malloc(sizeof(int) * N);
    char *c = (char *) malloc(sizeof(char) * N);

    for(i = 0; i < N; i ++){
        scanf("%d%d%*c%c", x + i, y + i, c + i);
    }

    int **count_B = (int **) malloc(sizeof(int *) * K);
    int **count_W = (int **) malloc(sizeof(int *) * K);

    for(i = 0; i < K; i ++){
        count_B[i] = (int *) malloc(sizeof(int) * K);
        count_W[i] = (int *) malloc(sizeof(int) * K);

        for(j = 0; j < K; j ++){
            count_B[i][j] = count_W[i][j] = 0;
        }
    }
    // K * K に落とす
    for(i = 0; i < N; i ++){
        if(c[i] == 'B'){
            if((x[i] / K + y[i] / K) % 2 == 0){
                count_B[x[i] % K][y[i] % K] ++;
            }else{
                count_W[x[i] % K][y[i] % K] ++;
            }
        }else{
            if((x[i] / K + y[i] / K) % 2 == 0){
                count_W[x[i] % K][y[i] % K] ++;
            }else{
                count_B[x[i] % K][y[i] % K] ++;
            }
        }
    }
    // 累積和
    for(j = 1; j < K; j ++){
        count_B[0][j] += count_B[0][j - 1];
        count_W[0][j] += count_W[0][j - 1];
    }
    for(i = 1; i < K; i ++){
        count_B[i][0] += count_B[i - 1][0];
        count_W[i][0] += count_W[i - 1][0];

        for(j = 1; j < K; j ++){
            count_B[i][j] += count_B[i][j - 1] + count_B[i - 1][j] - count_B[i - 1][j - 1];
            count_W[i][j] += count_W[i][j - 1] + count_W[i - 1][j] - count_W[i - 1][j - 1];
        }
    }
    // 最大値を求める
    int max_sum = 0;

    for(i = 0; i < K; i ++){
        for(j = 0; j < K; j ++){
            int sum = count_B[K - 1][K - 1];

            if(i > 0){
                sum += - count_B[i - 1][K - 1] + count_W[i - 1][K - 1];
            }
            if(j > 0){
                sum += - count_B[K - 1][j - 1] + count_W[K - 1][j - 1];
            }
            if(i > 0 && j > 0){
                sum += 2 * (count_B[i - 1][j - 1] - count_W[i - 1][j - 1]);
            }
            if(sum > max_sum){
                max_sum = sum;
            }
        }
    }
    for(i = 0; i < K; i ++){
        for(j = 0; j < K; j ++){
            int sum = count_W[K - 1][K - 1];

            if(i > 0){
                sum += - count_W[i - 1][K - 1] + count_B[i - 1][K - 1];
            }
            if(j > 0){
                sum += - count_W[K - 1][j - 1] + count_B[K - 1][j - 1];
            }
            if(i > 0 && j > 0){
                sum += 2 * (count_W[i - 1][j - 1] - count_B[i - 1][j - 1]);
            }
            if(sum > max_sum){
                max_sum = sum;
            }
        }
    }
    printf("%d\n", max_sum);

    return 0;
}

