        char c = p->c;
        if (color(x + xi, y + yi, k) == c) {
          h += 1;
        }
      }
      if (h > maxH) {
        maxH = h;
      }
      if (maxH == n) {
        return maxH;
      }
    }
  }
  return maxH;
}

