			tmp -= count[0][x][y] - count[1][x][y] - count[0][x][y-K] + count[1][x][y-K];
		}
		for (; x < K * 2; x++) {
			diff[x] -= (count[0][x][y] - count[1][x][y] - count[0][x][y-K] + count[1][x][y-K]) * 2;
			tmp += count[0][x][y] - count[1][x][y] - count[0][x][y-K] + count[1][x][y-K];
		}
		for (x = 0; x < K; x++) {
			tmp += diff[x] + diff[x+K];
			if (tmp > ans) ans = tmp;
		}
		for (; x < K * 2; x++) {
			tmp -= diff[x] + diff[x-K];
			if (tmp > ans) ans = tmp;
		}
	}

	printf("%d\n", ans);
	fflush(stdout);
	return 0;
}

