void solve(void){
    int n, k;
    scanf("%d%d\n",&n, &k);
    int xs[n], ys[n];
    char cs[n];
    rep (n, i) scanf("%d %d %s\n", &xs[i], &ys[i], &cs[i]);

    int ans = 0;
    rep (k, x){
        if (ans == n) break;
        rep(k, y){
            int temp_ans = 0;
            rep(n, i){
                char temp_c;
                if (((xs[i] + x) / k + (ys[i] + y) / k) % 2 == 0) temp_c = 'B';
                else temp_c = 'W';
                if (temp_c == cs[i]) temp_ans++;
            }
            ans = MAX(ans, MAX(temp_ans, n-temp_ans));
            if (ans == n) break;
        }
    }
  printf("%d\n", ans);
}

