#include<stdio.h>
#include<stdlib.h>
#include<stdint.h>
#include<inttypes.h>

typedef int32_t i32;

#define POS(i, j) ((i) * (2 * k + 1) + (j))

//[a,b) * [c, d)
i32 calc (i32 *sum, i32 k, i32 a, i32 b, i32 c, i32 d) {
  return sum[POS(b, d)] - sum[POS(b, c)] - sum[POS(a, d)] + sum[POS(a, c)];
}

void run (void) {
  i32 n, k;
  scanf ("%" SCNi32 "%" SCNi32, &n, &k);
  i32 *cnt = (i32 *) calloc ((2 * k + 1) * (2 * k + 1), sizeof (i32));
  for (i32 i = 0; i < n; ++i) {
    i32 x, y;
    char s[5];
    scanf ("%" SCNi32 "%" SCNi32 "%s", &x, &y, s);
    if (s[0] == 'B') x += k;
    cnt[POS(x % (2 * k), y % (2 * k))]++;
  }
  i32 *sum = (i32 *) calloc ((2 * k + 1) * (2 * k + 1), sizeof (i32));
  for (i32 i = 1; i <= 2 * k; ++i) {
    for (i32 j = 1; j <= 2 * k; ++j) {
      sum[POS(i, j)] = sum[POS(i - 1, j)] + sum[POS(i, j - 1)] - sum[POS(i - 1, j - 1)] + cnt[POS(i - 1, j - 1)];
    }
  }
  i32 max = 0;
  for (i32 i = 0; i <= k; ++i) {
    for (i32 j = 0; j <= k; ++j) {
      i32 a = calc (sum, k, 0    , i    , 0    , j    );
      i32 b = calc (sum, k, i    , i + k, j    , j + k);
      i32 c = calc (sum, k, i + k, 2 * k, 0    , j    );
      i32 d = calc (sum, k, 0    , i    , j + k, 2 * k);
      i32 e = calc (sum, k, i + k, 2 * k, j + k, 2 * k);
      i32 q = a + b + c + d + e;
      if (max < q) max = q;
    }
  }
  printf ("%" PRIi32 "\n", max);
}

int main (void) {
  run();
  return 0;
}

