class Program {
    fun solve() {
        val sc = MyScanner()
        val (n, k) = sc.intList()
        val imos = Array(2 * k + 1) { Array(3 * k + 1) { 0 } }
        for (i in 1..n) {
            var x = sc.nextInt()
            val y = sc.nextInt()
            val c = sc.nextChar()
            if (c == 'B') {
                x += k
            }

            val dx = x / k
            val mx = x % k

            val dy = y / k
            val my = y % k

            if (dx % 2 == dy % 2) {
                imos[mx][my]++
                imos[mx + k][my]--
                imos[mx][my + k]--
                imos[mx + k][my + k]++
            } else {
                imos[mx][my + k]++
                imos[mx + k][my + k]--
                imos[mx][my + 2 * k]--
                imos[mx + k][my + 2 * k]++
            }
        }

        for (i in 0..2 * k) {
            for (j in 0 until 3 * k) {
                imos[i][j + 1] += imos[i][j]
            }
        }

        for (i in 0 until 2 * k) {
            for (j in 0..3 * k) {
                imos[i + 1][j] += imos[i][j]
            }
        }


        var ans = 0
        for (i in 0 until k) {
            for (j in 0 until k) {
                ans = Math.max(ans, imos[i][j] + imos[i + k][j + k] + imos[i][j + 2 * k])
                ans = Math.max(ans, imos[i + k][j] + imos[i][j + k] + imos[i + k][j + 2 * k])
            }
        }

        println(ans)
    }
}

