			long x = sc.nextLong();
			long y = sc.nextLong();
			String c = sc.next();
			if(c.charAt(0)=='W'){
				x+=k;
			}
			x%=2*k;
			y%=2*k;
			dp[(int)y][(int)x]++;
		}
		for(int i = 0; i<2*k; i++){
			for(int j = 1; j<2*k; j++){
				dp[i][j]+=dp[i][j-1];
			}
		}
		for(int i = 0; i<2*k; i++){
			for(int j = 1; j<2*k; j++){
				dp[j][i]+=dp[j-1][i];
			}
		}
		long ans = 0;
		for(int i = 0; i<k; i++){
			for(int j = 0; j<k; j++){
				long an=0;
				an+=dp[i][j];
				an+=dp[i+k][j+k]-dp[i][j+k]-dp[i+k][j]+dp[i][j];
				an+=dp[i][2*k-1]-dp[i][j+k];
