            String[] xyc = sc.nextLine().split(" ");
            int x = Integer.parseInt(xyc[0]);
            int y = Integer.parseInt(xyc[1]);
            if(xyc[2].charAt(0) == 'W'){
                y += k;
            }
            grd[y%(k*2)+1][x%(k*2)+1] += 1;
        }

        /*
        for(int i=0; i<k*2; i++){
            for(int j=0; j<k*2; j++){
                System.out.print(grd[i][j]);
            }
            System.out.println("");
        }
        */

        for(int i=0; i<k*2+1; i++){
            for(int j=0; j<k*2; j++){
                grd[i][j+1] += grd[i][j];
            }
        }

        for(int i=0; i<k*2; i++){
            for(int j=0; j<k*2+1; j++){
                grd[i+1][j] += grd[i][j];
            }
        }

        int ans = 0;
        for(int i=0; i<k; i++){
            for(int j=0; j<k; j++){
                int cnt = 0;
                //iki jkj
                cnt += njrisum(grd, i, j, k, k);
                //i0 j0
                cnt += njrisum(grd, 0, 0, i, j);
                //k2i j0
                cnt += njrisum(grd, i+k, 0, k-i, j);
                //i0 k2j
                cnt += njrisum(grd, 0, j+k, i, k-j);
                //k2i k2j
                cnt += njrisum(grd, i+k, j+k, k-i, k-j);

                if(ans < cnt) ans = cnt;
            }
        }

        System.out.println(ans);
    }

    public static int njrisum(int[][]grd, int i, int j, int h, int w){
        return grd[i + h][j + w] - grd[i][j + w] + grd[i][j] - grd[i + h][j];
    }
}

import java.util.Scanner;

class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        int[] xs = new int[n];
        int[] ys = new int[n];
        boolean[] cs = new boolean[n];

        int max_x = 0;
        int max_y = 0;
        for (int i = 0; i < n; i++) {
            xs[i] = scanner.nextInt();
            if (xs[i] > max_x) {
                max_x = xs[i];
            }
            ys[i] = scanner.nextInt();
            if (ys[i] > max_y) {
                max_y = ys[i];
            }

            cs[i] = scanner.next().equals("B"); // black -> true, white -> false
        }

        boolean[][] BWFlags = new boolean[max_x + k * 2][max_y + k];
        for (int i_y = 0; i_y < max_y + k; i_y++) {
            for (int i_x = 0; i_x < max_x + k * 2; i_x++) {
                if ((i_y / k) % 2 == 0) {
                    if ((i_x / k) % 2 == 1) {
                        BWFlags[i_x][i_y] = true;
                    }
                } else {
                    if ((i_x / k) % 2 == 0) {
                        BWFlags[i_x][i_y] = true;
                    }
                }
            }
        }

        int max_able = 0;
        for (int k_x = 0; k_x < k * 2; k_x++) {
            for (int k_y = 0; k_y < k; k_y++) {

                int sum_able = 0;
                for (int i_n = 0; i_n < n; i_n++) {
                    int x = xs[i_n];
                    int y = ys[i_n];
                    boolean c = cs[i_n];

                    if (BWFlags[x + k_x][y + k_y] == c) {
                        sum_able++;
                    }
                }
                if (sum_able > max_able) {
                    max_able = sum_able;
                }
            }
        }

        System.out.print(max_able);
    }
