import java.util.Scanner;

public class Main {
    private static final int B = 1;
    private static final int W = 2;

    public static void main(String args[]) {
        try (Scanner in = new Scanner(System.in)) {
            int N = in.nextInt();
            int K = in.nextInt();
            int[] x = new int[N];
            int[] y = new int[N];
            int[] c = new int[N];

            for (int i = 0; i < N; i++) {
                x[i] = in.nextInt();
                y[i] = in.nextInt();
                c[i] = in.next().charAt(0) == 'B' ? B : W;
            }

            int[][] Bs = new int[2 * K][2 * K];
            int[][] Ws = new int[2 * K][2 * K];
            for (int i = 0; i < N; i++) {
                x[i] %= 2 * K;
                y[i] %= 2 * K;
                if (c[i] == B) {
                    Bs[y[i]][x[i]]++;
                } else {
                    Ws[y[i]][x[i]]++;
                }
            }

            int[][] sumB = new int[2 * K + 1][2 * K + 1];
            int[][] sumW = new int[2 * K + 1][2 * K + 1];
            for (int r = 0; r < 2 * K; r++) {
                for (int c2 = 0; c2 < 2 * K; c2++) {
                    sumB[r + 1][c2 + 1] = sumB[r + 1][c2] + sumB[r][c2 + 1] - sumB[r][c2] + Bs[r][c2];
                    sumW[r + 1][c2 + 1] = sumW[r + 1][c2] + sumW[r][c2 + 1] - sumW[r][c2] + Ws[r][c2];
                }
            }

            int max = 0;
            for (int r = 0; r < 2 * K; r++) {
                for (int c2 = 0; c2 < 2 * K; c2++) {
                    int r3 = Math.min(r + K, 2 * K);
                    int c3 = Math.min(c2 + K, 2 * K);
                    int num = sum(sumB, 0, 0, r, c2) //
                            + sum(sumW, 0, c2, r, c3)//
                            + sum(sumB, 0, c3, r, 2 * K)//
                            + sum(sumW, r, 0, r3, c2) //
                            + sum(sumB, r, c2, r3, c3) //
                            + sum(sumW, r, c3, r3, 2 * K) //
                            + sum(sumB, r3, 0, 2 * K, c2) //
                            + sum(sumW, r3, c2, 2 * K, c3) //
                            + sum(sumB, r3, c3, 2 * K, 2 * K);
                    max = Math.max(max, num);
                }
            }

            System.out.println(max);
        }
    }

    private static int sum(int[][] sum, int r, int c, int r2, int c2) {
        return sum[r][c] - sum[r2][c] - sum[r][c2] + sum[r2][c2];
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintStream;
import java.util.Arrays;
import java.util.NoSuchElementException;
public class Main {
    private static final PrintStream ps     = System.out;
    private static final InputStream IS     = System.in;
    private static final byte[]      BUFFER = new byte[1024];
    private static int               ptr    = 0;
    private static int               buflen = 0;

    public static void main(String[] args) {
        int n = ni();
        int k = ni();
        int[][] wishB = new int[k][k];
        int[][] wishW = new int[k][k];
        for (int i = 0; i < n; i++) {
            int x = ni();
            int y = ni();
            int c = n().charAt(0);
            if (x >= k) {
                x = x % k;
                c = c == 'B' ? 'W' : 'B';
            }
            if (y >= k) {
                y = y % k;
                c = c == 'B' ? 'W' : 'B';
            }

            if (c == 'B')
                wishB[x][y]++;
            else 
                wishW[x][y]++;

        }

        int[][] sum = new int[k+1][k+1];
        for (int i = 0; i < k; i++) {
            for (int j = 0; j < k; j++) {
                sum[0][0] += wishB[i][j];
            }
        }

        for (int isum = 1; isum <= k; isum++) {
            sum[isum][0] = sum[isum-1][0];
            for (int j = 0; j < k; j++) {
                sum[isum][0] -= wishB[isum-1][j];
                sum[isum][0] += wishW[isum-1][j];
            }
        }

        for (int jsum = 1; jsum <= k; jsum++) {
            sum[0][jsum] = sum[0][jsum-1];
            for (int i = 0; i < k; i++) {
                sum[0][jsum] += (-wishB[i][jsum-1] + wishW[i][jsum-1]);
            }
        }

        for (int isum = 1; isum <= k; isum++) {
            for (int jsum = 1; jsum <= k; jsum++) {
                sum[isum][jsum] = sum[isum][jsum-1];

                for (int i = isum; i < k; i++) {
                    sum[isum][jsum] -= wishB[i][jsum-1];
                    sum[isum][jsum] += wishW[i][jsum-1];
                }
                for (int i = 0; i < isum; i++) {
                    sum[isum][jsum] -= wishW[i][jsum-1];
                    sum[isum][jsum] += wishB[i][jsum-1];
                }
            }
        }

        int max = 0;
        for (int i = 0; i <= k; i++) {
            for (int j = 0; j <= k; j++) {
                max = Math.max(max, sum[i][j]);
            }
        }

        ps.println(max);
    }

    private static boolean hasNextByte() {
        if (ptr < buflen)
            return true;
        else {
            ptr = 0;
            try {
                buflen = IS.read(BUFFER);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0)
                return false;
        }
        return true;
    }

    private static int readByte() {
        if (hasNextByte())
            return BUFFER[ptr++];
        else
            return -1;
    }

    private static boolean isPrintableChar(int c) {
        return 33 <= c && c <= 126;
    }

    public static boolean hasNext() {
        while (hasNextByte() && !isPrintableChar(BUFFER[ptr]))
            ptr++;
        return hasNextByte();
    }

    public static String n() {
        if (!hasNext())
            throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public static long nl() {
        if (!hasNext())
            throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b)
            throw new NumberFormatException();
        while (true) {
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            } else if (b == -1 || !isPrintableChar(b))
                return minus ? -n : n;
            else
                throw new NumberFormatException();
            b = readByte();
        }
    }

    public static int ni() {
        long nl = nl();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE)
            throw new NumberFormatException();
        return (int) nl;
    }

    public static double nextDouble() {
        return Double.parseDouble(n());
    }

    private static int[] nia(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++)
            a[i] = ni();
        return a;
    }
}

