/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author vikas.k
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        int[][] white;
        int[][] black;
        int K;
        int[][] whiteBoard;
        int[][] blackBoard;

        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int N = in.nextInt();
            K = in.nextInt();
            int m = 2 * K;
            white = new int[m + 1][m + 1];
            black = new int[m + 1][m + 1];
            whiteBoard = new int[m + 1][m + 1];
            blackBoard = new int[m + 1][m + 1];
            for (int i = 0; i < N; i++) {
                int x = in.nextInt();
                int y = in.nextInt();

                int z = in.next().charAt(0) == 'W' ? 1 : 2;
                if (z == 1) white[x % m + 1][y % m + 1] += 1;
                else black[x % m + 1][y % m + 1] += 1;
            }

            for (int i = 1; i <= m; i++) {
                for (int j = 1; j <= m; j++) {
                    whiteBoard[i][j] += white[i][j];
                    if (j > 0) whiteBoard[i][j] += whiteBoard[i][j - 1];
                    if (i > 0) whiteBoard[i][j] += whiteBoard[i - 1][j];
                    if (i > 0 && j > 0) whiteBoard[i][j] -= whiteBoard[i - 1][j - 1];
                }
//            for(int j = 1; j <= m; j++) {
//                out.print(whiteBoard[i][j] + " ");
//            }
//            out.println();
            }
//        out.println();
            for (int i = 1; i <= m; i++) {
                for (int j = 1; j <= m; j++) {
                    blackBoard[i][j] += black[i][j];
                    if (j > 0) blackBoard[i][j] += blackBoard[i][j - 1];
                    if (i > 0) blackBoard[i][j] += blackBoard[i - 1][j];
                    if (i > 0 && j > 0) blackBoard[i][j] -= blackBoard[i - 1][j - 1];
                }
//            for(int j = 1; j <= m; j++) {
//                out.print(blackBoard[i][j] + " ");
//            }
//            out.println();
            }

            int ans = 0;
            for (int i = 1; i <= m; i++) {
                for (int j = 1; j <= m; j++) {
                    int count = foundAllBlackPoints(i, j) + foundAllWhitePoints(i, j);
//                out.println(i + " " + j + " " + count);
                    ans = Math.max(count, ans);
                }
            }
            out.println(ans);
        }

        private int foundAllBlackPoints(int x, int y) {
            int C = 1;
            int count = 0;
            int x1 = x + K - 1;
            int y1 = y + K - 1;
            count += countGrid(x, y, Math.min(2 * K, x1), Math.min(2 * K, y1), C);
//        System.out.println(x + " " + y + " " + x1 + " " + y1 + " " + count);

            int x2 = x - K;
            int y2 = y - K;
            count += countGrid(Math.max(x2, 1), Math.max(y2, 1), Math.max(x - 1, 0), Math.max(y - 1, 0), C);
//        System.out.println(x2 + " " + y2 + " " + (x-1) + " " + (y-1) + " " + count);

            int x3 = x + K;
            int y3 = x - K;
            int x4 = x + 2 * K - 1;
            int y4 = y;
            count += countGrid(Math.min(x3, 2 * K + 1), Math.max(y3, 1), Math.min(x4, 2 * K), Math.max(y4 - 1, 0), C);
//        System.out.println(x3 + " " + y3 + " " + x4 + " " + (y4-1) + " " + count);

            int x5 = x - K;
            int y5 = y + K;
            int x6 = x;
            int y6 = y + 2 * K - 1;
            count += countGrid(Math.max(x5, 1), Math.min(y5, 2 * K + 1), Math.max(x6 - 1, 0), Math.min(y6, 2 * K), C);
//        System.out.println(x5 + " " + y5 + " " + (x6-1) + " " + y6 + " " + count);

            count += countGrid(Math.min(x + K, 2 * K + 1), Math.min(y + K, 2 * K + 1), Math.min(x + 2 * K - 1, 2 * K), Math.min(y + 2 * K - 1, 2 * K), C);
//        System.out.println((x+K) + " " + (y+K) + " " + (x + 2*K - 1) + " " + (y+2*K - 1) + " " + count);
            return count;
        }

        private int foundAllWhitePoints(int x, int y) {
            int C = 2;
            int count = 0;

            int x1 = x;
            int y1 = y - K;
            int x2 = x + K - 1;
            int y2 = y - 1;
            count += countGrid(x1, Math.max(y1, 1), Math.min(2 * K, x2), Math.max(y2, 0), C);
            //System.out.println(x1 + " " + y1 +  " " + x2 + " " + y2 +  " " + count);

            x1 = x - K;
            y1 = y;
            x2 = x - 1;
            y2 = y + K - 1;
            count += countGrid(Math.max(x1, 1), y1, Math.max(0, x2), Math.min(y2, 2 * K), C);
            //System.out.println(x1 + " " + y1 +  " " + x2 + " " + y2 + " " + count);

            x1 = x;
            y1 = y + K;
            x2 = x + K - 1;
            y2 = y + 2 * K - 1;
            count += countGrid(x1, Math.min(y1, 2 * K + 1), Math.min(2 * K + 1, x2), Math.min(y2, 2 * K), C);
            //System.out.println(x1 + " " + y1 +  " " + x2 + " " + y2 + " " + count);

            x1 = x + K;
            y1 = y;
            x2 = x + 2 * K - 1;
            y2 = y + K - 1;
            count += countGrid(Math.min(x1, 2 * K + 1), y1, Math.min(2 * K + 1, x2), Math.min(y2, 2 * K), C);
            //System.out.println(x1 + " " + y1 +  " " + x2 + " " + y2 + " " + count);
            return count;
        }

        private int countGrid(int tx, int ty, int bx, int by, int C) {
            if (tx > 2 * K || ty > 2 * K || bx < 1 || by < 1) return 0;
            if (C == 1) {
                return whiteBoard[bx][by] - whiteBoard[bx][ty - 1] - whiteBoard[tx - 1][by] + whiteBoard[tx - 1][ty - 1];
            }
            return blackBoard[bx][by] - blackBoard[bx][ty - 1] - blackBoard[tx - 1][by] + blackBoard[tx - 1][ty - 1];
        }

    }

    static class FastScanner {
        private BufferedReader bufferedReader;
        private StringTokenizer stringTokenizer;

        public FastScanner(InputStream inputStream) {
            bufferedReader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            if (stringTokenizer == null || !stringTokenizer.hasMoreElements()) {
                try {
                    stringTokenizer = new StringTokenizer(bufferedReader.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return stringTokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.util.*;

public class Main {
    int data[][], k2;

    private class Point {
        int x, y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public void main(Scanner sc) {
        int n = sc.nextInt();
        int k = sc.nextInt();
        k2 = 2 * k;
        Point p[] = new Point[n];
        for (int i = 0; i < n; i++) {
            int x = sc.nextInt() % k2;
            int y = sc.nextInt() % k2;
            if (!sc.next().equals("B")) {
                y = (y + k) % k2;
            }
            p[i] = new Point(x, y);
        }

        data = new int[k2][k2];
        for (int i = 0; i < n; i++) {
            add(-p[i].x, -p[i].y, 1);
            add(k - p[i].x, k - p[i].y, 1);
            add(-p[i].x, k - p[i].y, -1);
            add(k - p[i].x, -p[i].y, -1);
            add(k - p[i].x, k - p[i].y, 1);
            add(k2 - p[i].x, k2 - p[i].y, 1);
            add(k - p[i].x, k2 - p[i].y, -1);
            add(k2 - p[i].x, k - p[i].y, -1);
        }

        for (int i = 0; i < k2; i++) {
            for (int j = 1; j < k2; j++) {
                data[i][j] += data[i][j - 1];
            }
        }

        int ans = 0;
        for (int i = 0; i < k2; i++) {
            for (int j = 1; j < k2; j++) {
                data[j][i] += data[j - 1][i];
                ans = Math.max(ans, data[j][i]);
            }
        }
        System.out.println(ans);
    }

    private void add(int x, int y, int n) {
        if (x >= 0 && x < k2) {
            if (!(y >= 0 && y < k2)) {
                data[0][x] += n;
            }
            data[(k2 + y) % k2][x] += n;
        } else if (x < 0) {
            if (y >= 0 && y < k2) {
                data[y][0] += n;
                data[y][k2 + x] += n;
            } else if (y < 0) {
                data[0][0] += n;
                data[0][k2 + x] += n;
                data[k2 + y][0] += n;
                data[k2 + y][k2 + x] += n;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        new Main().main(sc);
        sc.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {

        Scanner scn = new Scanner(System.in);

        int numLines = scn.nextInt();
        int sideLength = scn.nextInt();

        int[][] Bins = new int[sideLength*2][sideLength*2];

        for (int i = 0; i < numLines; i++) {
            int x = scn.nextInt();
            int y = scn.nextInt();
            char c = scn.next().charAt(0);

            for (int j = 0; j < sideLength*2; j++) {
                for (int k = 0; k < sideLength*2; k++) {
                    boolean White = false;
                    if (j >= sideLength) {
                        White = !White;
                    }
                    if (k >= sideLength) {
                        White = !White;
                    }
                    if (c == 'W') {
                        if (White) {
                            Bins[(x + j) % (sideLength*2)][(y + k) % (sideLength*2)]++;
                        }
                    } else {
                        if (!White) {
                            Bins[(x + j) % (sideLength*2)][(y + k) % (sideLength*2)]++;
                        }
                    }
                }
            }
        }

        int max = 0;
        for (int x = 0; x < sideLength*2; x++) {
            for (int y = 0; y < sideLength *2; y++) {
                if (Bins[x][y] > max) {
                    max = Bins[x][y];
                }
            }
        }

        System.out.println(max);
}
}

