        for (int num = 0; num < n; num++) {
            String[] d = in.nextLine().split(" ");
            point[num][0] = new Integer(d[0]);
            point[num][1] = new Integer(d[1]);
            point[num][2] = (d[2].equals("B")) ? 1 : 0;

        }

        int maxS = 0;
        for (int i = 0; i < k; i++) {
            for (int j = 0; j < k; j++) {
                int count = 0;
                for (int[] p : point) {
                    int xx = (p[0] - i < 0) ? (p[0] - i) / k - 1 : (p[0] - i) / k;
                    int yy = (p[1] - j < 0) ? (p[1] - j) / k - 1 : (p[1] - j) / k;
                    if (((xx + yy) & 1) == p[2]) {
                        count++;
                    }
                }
                maxS = Math.max(maxS, Math.max(count, n - count));
                if (maxS == n) {
                    System.out.println(n);
