			int j = sc.nextInt() % k2;
			char c = sc.next().charAt(0);
			if (c == 'W')
				i += i < k ? k : -k;
			bb[i][j]++;
			bb[k2 + i][j]++;
			bb[i][k2 + j]++;
			bb[k2 + i][k2 + j]++;
		}
		for (int i = 0; i < k4; i++)
			for (int j = 1; j < k4; j++)
				bb[i][j] += bb[i][j - 1];
		for (int i = 1; i < k4; i++)
			for (int j = 0; j < k4; j++)
				bb[i][j] += bb[i - 1][j];
		int ans = 0;
		for (int i_ = 0; i_ < k2; i_++)
			for (int j_ = 0; j_ < k2; j_++) {
				int i, j, cnt = 0;
				i = i_; j = j_;
				cnt += bb[i + k][j + k] - bb[i][j + k] - bb[i + k][j] + bb[i][j];
				i = i_ + k; j = j_ + k;
				cnt += bb[i + k][j + k] - bb[i][j + k] - bb[i + k][j] + bb[i][j];
				ans = Math.max(ans, cnt);
			}
		println(ans);
	}
