				int Q4B = Bpref[i][j-K]-Bpref[i-K][j-K]-Bpref[i][j-2*K]+Bpref[i-K][j-2*K];

				int val = Math.max(Q1W+Q3W+Q2B+Q4B,Q1B+Q3B+Q2W+Q4W);
