import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;
import static java.lang.Math.max;



public class Main {
    public static void main(String[] args) {
        FastScanner fsc = new FastScanner();
        int n = fsc.nextInt();
        int k = fsc.nextInt();
        int[][] f = new int[2 * k][2 * k];
        for (int i = 0; i < n; i++) {
            int x = fsc.nextInt();
            int y = fsc.nextInt();
            char c = fsc.next().toCharArray()[0];
            if (c == 'W') {
                f[x % (2 * k)][y % (2 * k)]++;
            } else {
                f[(x + k) % (2 * k)][y % (2 * k)]++;
            }
        }
        int[][] s = ArrayUtil.cumsum(f);
        int max=0;
        for(int i=0;i<=k;i++){
            for(int j=0;j<=k;j++){
                max=max(max, u(s, k, i, j));
            }
        }
        System.out.println(max);
    }

    public static int t(int[][] s, int x1, int y1, int x2, int y2) {
        return s[x2][y2] - s[x1][y2] - s[x2][y1] + s[x1][y1];
    }

    public static int u(int[][] s, int k, int i, int j) {
        return t(s, 0, 0, i, j) + t(s, i, j, i + k, j + k) + t(s, 0, j + k, i, 2 * k) + t(s, i + k, 0, 2 * k, j) + t(s, i + k, j + k, 2 * k, 2 * k);
    }
}


