            for (int i = 0; i < N; i++) {
                x[i] = in.nextInt();
                y[i] = in.nextInt();
                bw[i] = in.next().charAt(0) == 'B' ? B : W;
            }

            int[][] b = new int[2 * K][2 * K];
            int[][] w = new int[2 * K][2 * K];
            for (int i = 0; i < N; i++) {
                x[i] %= 2 * K;
                y[i] %= 2 * K;
                if (bw[i] == B) {
                    b[y[i]][x[i]]++;
                } else {
                    w[y[i]][x[i]]++;
                }
