/**
 * 解説どおりに作成したソースコード<br/>
 * https://atcoder.jp/contests/abc086/submissions/2279952 にも参照
 */
public class Main {

	/** 白の定数 */
	private static final String WHITE = "W";

	/** 四角の差分を計算用 */
	private static final int[] X_DIFFS = { 0, 0, 1, 1, 1, 1, 2, 2 };
	private static final int[] Y_DIFFS = { 0, 1, 0, 1, 1, 2, 1, 2 };
	private static final int[] COUNT_DIFFS = { 1, -1, -1, 1, 1, -1, -1, 1 };

	public static void main(String[] args) {
		try (Scanner scanner = new Scanner(System.in)) {
			int n = scanner.nextInt();
			int k = scanner.nextInt();
			int w = 4 * k + 1;
			int k2 = 2 * k;
			int[][] count = new int[w][w];
			IntStream.range(0, n).forEach(i -> {
				int x = scanner.nextInt();
				int y = scanner.nextInt();
				if (WHITE.equals(scanner.next())) {
					y += k;
				}
				x %= 2 * k;
				y %= 2 * k;
				for (int j = 0; j < X_DIFFS.length; j++) {
					count[x + X_DIFFS[j] * k][y + Y_DIFFS[j] * k] += COUNT_DIFFS[j];
				}
			});
			// 横方向への累積和
			IntStream.range(0, w).forEach(i -> IntStream.range(1, w).forEach(j -> count[i][j] += count[i][j - 1]));
			// 縦方向への累積和
			IntStream.range(1, w).forEach(i -> IntStream.range(0, w).forEach(j -> count[i][j] += count[i - 1][j]));
			// 2k x 2k 範囲を超えたcountを2k x 2k範囲に加算
			IntStream.range(1, w).forEach(i -> IntStream.range(0, w).filter(j -> (i >= k2) || (j >= k2))
					.forEach(j -> count[i % k2][j % k2] += count[i][j]));
			// 2k x 2k 範囲の最大値を出力
			System.out.println(IntStream.range(0, k2)
					.map(i -> IntStream.range(0, k2).map(j -> count[i][j]).max().getAsInt()).max().getAsInt());
		}
	}
}

import java.util.Scanner;

public class Main {

  private static final int Black = 0;
  private static final int White = 1;

  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt();
    int K = scanner.nextInt();
    int[] x = new int[N];
    int[] y = new int[N];
    int[] c = new int[N];

    final String BlackColor = "B";
    final int K2 = 2 * K;
    for (int i = 0; i < N; i++) {
      x[i] = scanner.nextInt() % K2;
      y[i] = scanner.nextInt() % K2;
      c[i] = BlackColor.equals(scanner.next()) ? Black : White;
    }
    new Main().execute(N, K, x, y, c);
  }

  public void execute(int N, int K, int[] x, int[] y, int[] c) {
    final int K2 = 2 * K;
    int maxDesires = 0;
    for (int i = 0; i < K2; i++) {
      for (int j = 0; j < K2; j++) {
        // Assumes cell (i,j) is black and bottom-left corner of (K,K) square
        int count = 0;
        for (int n = 0; n < N; n++) {
          if (c[n] == getColor(K, i, j, x[n], y[n])) {
            count++;
          }
        }

        if (maxDesires < count) {
          maxDesires = count;
        }
      }
    }

    System.out.println(maxDesires);
  }

  /**
   * Assume bottom-left black corner is (rootX, rootY), get color of cell (x,y)
   */
  public int getColor(int K, int rootX, int rootY, int x, int y) {
    int dx = x - rootX;
    int dy = y - rootY;
    if (dx < 0) {
      dx -= K - 1;
    }
    if (dy < 0) {
      dy -= K - 1;
    }

    return ((dx / K + dy / K) & 1) == 1 ? Black : White;
  }

}

