					int pos = 0;
					for(int j=0;j<N;j++){
						if(c.get(i).equals(c.get(j))){
							if(((((((a.get(j)+w)/K)%2)+((b.get(j)+h)/K)%2)))%2==0){
								pos++;
							}
						}
						else{
							if(((((((a.get(j)+w)/K)%2)+((b.get(j)+h)/K)%2)))%2!=0){
								pos++;
							}
						}
					}
					if(max<pos){
						max = pos;
					}
				}
			}
		}
