import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt();
    int K = scanner.nextInt();

    int count = 0;
    int[][] delta = new int[K][K];
    for (int i = 0; i < N; i++) {
      int x = scanner.nextInt();
      int y = scanner.nextInt();
      char c = scanner.next().charAt(0);
      int p = x / K + y / K;

      delta[x % K][y % K]++;
      if ((p % 2 == 0 && c == 'W') || (p % 2 == 1 && c == 'B')) {
        delta[x % K][y % K] -= 2;
        count++;
      }
    }

    for (int i = 0; i < K; i++) for (int j = 1; j < K; j++) delta[i][j] += delta[i][j - 1];
    for (int j = 0; j < K; j++) for (int i = 1; i < K; i++) delta[i][j] += delta[i - 1][j];

    int max = count;
    for (int i = 0; i <= K; i++) {
      for (int j = 0; j <= K; j++) {
        int c1 = count, c2 = count + delta[K - 1][K - 1];
        if (i > 0) {
          c1 += delta[i - 1][K - 1];
          c2 -= delta[i - 1][K - 1];
        }
        if (j > 0) {
          c1 += delta[K - 1][j - 1];
          c2 -= delta[K - 1][j - 1];
        }
        if (i > 0 && j > 0) {
          c1 -= 2 * delta[i - 1][j - 1];
          c2 += 2 * delta[i - 1][j - 1];
        }
        max = Math.max(max, c1);
        max = Math.max(max, c2);
      }
    }

    System.out.println(max);
  }
}

import java.io.*;
import java.util.*;

class Solver {
  final int n, k;
  final int[] xs, ys;
  final char[] cs;

  Solver(int n, int k, int[] xs, int[] ys, char[] cs) {
    this.n = n;
    this.k = k;
    this.xs = xs;
    this.ys = ys;
    this.cs = cs;
  }

  public int solve() {
    int[][] whiteTopLeftIncrementalTable = new int[k][2 * k];
    for (int i = 0; i < n; i++) {
      // [0, 0] - [2k, 2k]
      int normX = xs[i] % (2 * k);
      int normY = ys[i] % (2 * k);
      // [0, 0] - [3k, 2k]
      int whiteNormX = normX + (cs[i] == 'B' ? k : 0);
      int whiteNormY = normY;
      // [-k, -k] - [2k, 1k]
      int topLeftWhiteNormX = whiteNormX - (k - 1);
      int topLeftWhiteNormY = whiteNormY - (k - 1);

      // [whiteNormX - (k - 1), whiteNormY - (k - 1)] - [whiteNormX, whiteNormY]
      for (int a = -4; a <= 4; a++) {
        for (int b = -4; b <= 4; b++) {
          if ((a + b) % 2 != 0) {
            continue;
          }
          int topLeftX = topLeftWhiteNormX + a * k;
          int topLeftY = topLeftWhiteNormY + b * k;
          int bottomRightX = topLeftX + k - 1;
          int bottomRightY = topLeftY + k - 1;
          // [(topLeftX, topLeftY) - (bottomRightX, bottomRightY)] - [(0, 0) - (2k-1, k-1)]
          if (bottomRightX < 0) continue;
          if (bottomRightY < 0) continue;
          if (2 * k - 1 < topLeftX) continue;
          if (k - 1 < topLeftY) continue;
          whiteTopLeftIncrementalTable[Math.max(topLeftY, 0)][Math.max(topLeftX, 0)] += 1;
          if (topLeftY + k < k) {
            whiteTopLeftIncrementalTable[topLeftY + k][Math.max(topLeftX, 0)] += -1;
          }
          if (topLeftX + k < 2 * k) {
            whiteTopLeftIncrementalTable[Math.max(topLeftY, 0)][topLeftX + k] += -1;
          }
        }
      }
      /*
        System.err.println("---");
      for (int y = 0; y < k; y++) {
        for (int x = 0; x < 2 * k; x++) {
          System.err.printf("%3d", whiteTopLeftIncrementalTable[y][x]);
        }
        System.err.println();
      }
      */
    }

    int[] line = new int[2 * k];
    int answer = 0;
    for (int i = 0; i < k; i++) {
      for (int j = 0; j < 2 * k; j++) {
        line[j] += whiteTopLeftIncrementalTable[i][j];
      }
      int count = 0;
      for (int j = 0; j < 2 * k; j++) {
        count += line[j];
        answer = Math.max(answer, count);
      }
    }
    return answer;
  }
}

public class Main {
  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int k = reader.nextInt();
    int[] xs = new int[n];
    int[] ys = new int[n];
    char[] cs = new char[n];
    for (int i = 0; i < n; i ++) {
      xs[i] = reader.nextInt();
      ys[i] = reader.nextInt();
      cs[i] = reader.next().charAt(0);
