			int a = Integer.parseInt(sa[0]);
			int b = Integer.parseInt(sa[1]);
			if (sa[2].equals("W")) {
				a += k;
			}
			x[i] = a % k2 + 1;
			y[i] = b % k2 + 1;
		}
		br.close();

		int[] dx = {-k, -k, k, k};
		int[] dy = {-k, k, -k, k};
