					}
				}
			}
			void init(long[][] val) {
				for(int i = 0; i < h; i ++) {
					for(int j = 0; j < w; j ++) {
						gs[i][j].val = val[i][j];
					}
				}
			}

			int dx[] = {0, -1, 1, 0, 0, -1, 1, -1, 1};
			int dy[] = {0, 0, 0, -1, 1, -1, -1, 1, 1};
			Grid next(Grid g, int i) {
				return isValid(g.x + dx[i], g.y + dy[i], g.h, g.w)
					? gs[g.x + dx[i]][g.y + dy[i]]
					: null;
			}
		}
		class Grid implements Comparable<Grid> {
			int x;
			int y;
			int h;
			int w;
			int i;
			boolean b;
			long val;

			Grid() {  }
			Grid(int x, int y, int h, int w) { init(x, y, h, w, false, 0); }
			Grid(int x, int y, int h, int w, boolean b) { init(x, y, h, w, b, 0); }
			Grid(int x, int y, int h, int w, long val) { init(x, y, h, w, false, val); }
			Grid(int x, int y, int h, int w, boolean b, long val) { init(x, y, h, w, b, val); }

			void init(int x, int y, int h, int w, boolean b, long val) {
				this.x = x;
				this.y = y;
				this.h = h;
				this.w = w;
				this.b = b;
				this.val = val;
				i = x * w + y;
			}

			@Override
			public int compareTo(Grid g) {
				return Long.compare(this.val, g.val);
			}
		}

		boolean isValid(int x, int y, int h, int w) {
			return x >= 0 && x < h && y >= 0 && y < w;
		}
		boolean isValid(Grid g) {
			return isValid(g.x, g.y, g.h, g.w);
		}

		// graph
		class Graph {
			int numNode;
			int numEdge;
			boolean directed;
			Edge edges[];
			Node nodes[];
			Node reversedNodes[];

			Graph(int numNode, int numEdge, Edge edges[], boolean directed) {
				this.numNode = numNode;
				this.numEdge = numEdge;
				this.directed = directed;
				this.edges = edges;
				nodes = new Node[numNode];
				reversedNodes = new Node[numNode];
				for(int i = 0; i < numNode; i ++) {
					nodes[i] = new Node(i);
					reversedNodes[i] = new Node(i);
				}

				for(Edge edge : edges) {
					nodes[edge.source].add(edge.target, edge.cost);
					if(directed) {
						reversedNodes[edge.target].add(edge.source, edge.cost);
					}else {
						nodes[edge.target].add(edge.source, edge.cost);
					}
				}
			}

			void clearNodes() {
				for(Node n : nodes) { n.clear(); }
				for(Node n : reversedNodes) { n.clear(); }
			}
		}

		class Node {
			int id;
			ArrayList<Edge> edges = new ArrayList<Edge>();

			Node(int id) {
				this.id = id;
			}
			void add(int target, long cost) {
				edges.add(new Edge(id, target, cost));
			}
			void clear() {
				edges.clear();
			}
		}

		class Edge implements Comparable<Edge> {
			int source;
			int target;
			long cost;
			Edge(int source, int target, long cost) {
				this.source = source;
				this.target = target;
				this.cost = cost;
			}

			@Override
			public int compareTo(Edge e) {
				return Long.compare(this.cost, e.cost);
			}
		}

public void solve() {
	int num = ni();
	int k = ni();
	long cntB[][] = new long[k + 1][k + 1];
	fill(cntB, 0);
	long cntW[][] = new long[k + 1][k + 1];
	fill(cntW, 0);
	for(int i = 0; i < num; i ++) {
		int x = ni();
		int y = ni();
		boolean b = ns().equals("B");
		b ^= x / k % 2 != 0;
		x %= k;
		x ++;
		b ^= y / k % 2 != 0;
		y %= k;
		y ++;
		if(b) {
			cntB[x][y] ++;
		}else {
			cntW[x][y] ++;
		}
	}
	errprtln(cntB);
	errprtln(cntW);

	for(int i = 1; i <= k; i ++) {
		for(int j = 1; j <= k; j ++) {
			cntB[i][j] += cntB[i - 1][j];
			cntB[i][j] += cntB[i][j - 1];
			cntB[i][j] -= cntB[i - 1][j - 1];
		}
	}
	for(int i = 1; i <= k; i ++) {
		for(int j = 1; j <= k; j ++) {
			cntW[i][j] += cntW[i - 1][j];
			cntW[i][j] += cntW[i][j - 1];
			cntW[i][j] -= cntW[i - 1][j - 1];
		}
	}
	long max = 0;
	for(int i = 0; i <= k; i ++) {
		for(int j = 0; j <= k; j ++) {
		max = max(max,
			cntB[k][k] - cntB[i][k] - cntB[k][j] + cntB[i][j] * 2
			+ cntW[i][k] + cntW[k][j] - cntW[i][j] * 2);
		}
	}
	assert(max <= num);
	prtln(max);
}



