	fill(cntB, 0);
	long cntW[][] = new long[k + 1][k + 1];
	fill(cntW, 0);
	for(int i = 0; i < num; i ++) {
		int x = ni();
		int y = ni();
		boolean b = ns().equals("B");
		b ^= x / k % 2 != 0;
		x %= k;
