		y %= k;
		y ++;
		if(b) {
			cntB[x][y] ++;
		}else {
			cntW[x][y] ++;
		}
	}
	errprtln(cntB);
	errprtln(cntW);

	for(int i = 1; i <= k; i ++) {
		for(int j = 1; j <= k; j ++) {
			cntB[i][j] += cntB[i - 1][j];
			cntB[i][j] += cntB[i][j - 1];
			cntB[i][j] -= cntB[i - 1][j - 1];
