        static int[][] gridPoint;
        static int getBlock(int x, int y) {
            int xx = Math.min(x + k - 1, 4 * k);
            int yy = Math.min(y + k - 1, 4 * k);
            int t = countLD[xx][yy] - countLD[x - 1][yy] - countLD[xx][y - 1] + countLD[x - 1][y - 1];
