                y %= (2 * k);
                gridPoint[x + 1][y + 1]++;
            }
            for (int i = 1 + k; i <= 4 * k; i++) {
                for (int j = 1 + k; j <= 4 * k; j++) {
                    countLD[i][j] = countLD[i - 1][j] + countLD[i][j - 1] - countLD[i - 1][j - 1];
                    if (i - k <= 2 * k + 1 && j - k <= 2 * k + 1) {
                        countLD[i][j] += gridPoint[i - k][j - k];
                    }
