                    c += getBlock(i, j);
                    c += getBlock(i - k, j - k);
                    c += getBlock(i + k, j - k);
                    c += getBlock(i - k, j + k);
                    c += getBlock(i + k, j + k);
                    max = Math.max(max, c);
                }
            }
            pw.println(max);
        }

    }

    static class MyScanner {
        StringTokenizer st;
        BufferedReader br;

