public void solve() {
	int num = ni();
	int k = ni();
	long cntB[][] = new long[k + 1][k + 1];
	fill(cntB, 0);
	long cntW[][] = new long[k + 1][k + 1];
	fill(cntW, 0);
	for(int i = 0; i < num; i ++) {
		int x = ni();
		int y = ni();
		boolean b = ns().equals("B");
		b ^= x / k % 2 != 0;
		x %= k;
		x ++;
		b ^= y / k % 2 != 0;
		y %= k;
		y ++;
		if(b) {
			cntB[x][y] ++;
		}else {
			cntW[x][y] ++;
		}
	}
	errprtln(cntB);
	errprtln(cntW);

	for(int i = 1; i <= k; i ++) {
		for(int j = 1; j <= k; j ++) {
			cntB[i][j] += cntB[i - 1][j];
			cntB[i][j] += cntB[i][j - 1];
			cntB[i][j] -= cntB[i - 1][j - 1];
		}
	}
	for(int i = 1; i <= k; i ++) {
		for(int j = 1; j <= k; j ++) {
			cntW[i][j] += cntW[i - 1][j];
			cntW[i][j] += cntW[i][j - 1];
			cntW[i][j] -= cntW[i - 1][j - 1];
		}
	}
	long max = 0;
	for(int i = 0; i <= k; i ++) {
		for(int j = 0; j <= k; j ++) {
		max = max(max,
			cntB[k][k] - cntB[i][k] - cntB[k][j] + cntB[i][j] * 2
			+ cntW[i][k] + cntW[k][j] - cntW[i][j] * 2);
		max = max(max,
			cntW[k][k] - cntW[i][k] - cntW[k][j] + cntW[i][j] * 2
			+ cntB[i][k] + cntB[k][j] - cntB[i][j] * 2);
		}
	}
	assrt(max <= num);
	prtln(max);
}



