				sumW2[j][i] = sumW2[j-1][i] + sumW[(j-1+k)%(2*k)][i] - sumW[j-1][i];
			}
		}
		int ans = 0;
		for(int i=0;i<k;i++) {
			for(int j=0;j<2*k;j++) {
