                max_y = ys[i];
            }

            cs[i] = scanner.next().equals("B"); // black -> true, white -> false
        }

        boolean[][] BWFlags = new boolean[max_x + k * 2][max_y + k];
        for (int i_y = 0; i_y < max_y + k; i_y++) {
            for (int i_x = 0; i_x < max_x + k * 2; i_x++) {
                if ((i_y / k) % 2 == 0) {
                    if ((i_x / k) % 2 == 1) {
                        BWFlags[i_x][i_y] = true;
                    }
                } else {
                    if ((i_x / k) % 2 == 0) {
                        BWFlags[i_x][i_y] = true;
