            int n = in.nextInt(), k = in.nextInt(), k2 = k * 2;
            int[][] w = new int[k2][k2];
            for (int i = 0; i < n; i++) {
                int x = in.nextInt(), y = in.nextInt();
                if (in.next().charAt(0) == 'B') {
                    y += k;
                }
                w[y % k2][x % k2]++;
            }

            cumSum = new int[k2 + 1][k2 + 1];
            for (int i = 1; i <= k2; i++) {
                for (int j = 1; j <= k2; j++) {
                    cumSum[i][j] = cumSum[i - 1][j] + cumSum[i][j - 1] - cumSum[i - 1][j - 1] + w[i - 1][j - 1];
                }
            }

            int max = 0;
            for (int i = 0; i < k2; i++) {
                for (int j = 0; j < k2; j++) {
                    int y0 = k2, x0 = k2;
                    int y1 = Math.min(i + k, k2), x1 = Math.min(j + k, k2);
                    int y2 = i, x2 = j;
                    int y3 = Math.max(i - k, 0), x3 = Math.max(j - k, 0);
                    int y4 = 0, x4 = 0;

                    int sum = sum(y1, y0, x1, x0)
                              + sum(y1, y0, x3, x2)
                              + sum(y2, y1, x2, x1)
                              + sum(y2, y1, x4, x3)
                              + sum(y3, y2, x3, x2)
                              + sum(y3, y2, x1, x0)
                              + sum(y4, y3, x4, x3)
                              + sum(y4, y3, x2, x1);
                    max = Math.max(sum, max);
                }
            }
            System.out.println(max);
        }
    }

    private int sum(int ya, int yb, int xa, int xb) {
        return cumSum[ya][xa] + cumSum[yb][xb] - cumSum[yb][xa] - cumSum[ya][xb];
    }
}

import java.util.Scanner;

public class Main {

  private static final int Black = 0;
  private static final int White = 1;

  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt();
    int K = scanner.nextInt();
    int[] x = new int[N];
    int[] y = new int[N];
    int[] c = new int[N];

    final String BlackColor = "B";
    final int K2 = 2 * K;
    for (int i = 0; i < N; i++) {
      x[i] = scanner.nextInt() % K2;
      y[i] = scanner.nextInt() % K2;
      c[i] = BlackColor.equals(scanner.next()) ? Black : White;
    }
    new Main().execute(N, K, x, y, c);
  }

  public void execute(int N, int K, int[] x, int[] y, int[] c) {
    final int K2 = 2 * K;
    int maxDesires = 0;
    for (int i = 0; i < K2; i++) {
      for (int j = 0; j < K2; j++) {
        // Assumes cell (i,j) is black and bottom-left corner of (K,K) square
        int count = 0;
        for (int n = 0; n < N; n++) {
          if (c[n] == getColor(K, i, j, x[n], y[n])) {
            count++;
          }
        }

        if (maxDesires < count) {
          maxDesires = count;
        }
      }
    }

    System.out.println(maxDesires);
  }

  /**
   * Assume bottom-left black corner is (rootX, rootY), get color of cell (x,y)
   */
  public int getColor(int K, int rootX, int rootY, int x, int y) {
    int dx = x - rootX;
    int dy = y - rootY;
    if (dx < 0) {
      dx -= K - 1;
    }
    if (dy < 0) {
      dy -= K - 1;
    }

    return (dx / K + dy / K) % 2 == 0 ? Black : White;
  }

}

