import java.util.Scanner;

public class Main {
	static int [][]_2Cum_sum;
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = Integer.parseInt(sc.next());
		int k = Integer.parseInt(sc.next());
		int k2 = k*2;
		long[][] Hope = new long [n][3];
		int[][] map = new int [k2][k2];
		//二次元累積和
		_2Cum_sum = new int[k2+1][k2+1];

		//W=-1,B=1としてHope[i][2]にいれる
		for(int i=0;i<n;i++) {
			Hope[i][0] = Long.parseLong(sc.next());
			Hope[i][1] = Long.parseLong(sc.next());
			Hope[i][2] = sc.next().equals("W")?-1:1;
		}
		sc.close();

		for(int i=0;i<n;i++) {
			//y: -1("W")ならば+kして黒と同じ扱いに
			long x = Hope[i][0];
			long y = Hope[i][2]==-1?Hope[i][1]+k:Hope[i][1];
			//(0,0)=(0+k*2,0+k*2)のため(x%(k*2),y%(k*2))
			map[(int)y%k2][(int)x%k2]++;
		}

		//二次元累積和
		for (int i = 1; i <= k*2; i++) {
		    for (int j = 1; j <= k*2; j++) {
		        _2Cum_sum[i][j] = _2Cum_sum[i-1][j] + _2Cum_sum[i][j-1]  + map[i - 1][j - 1] -_2Cum_sum[i - 1][j - 1];
		    }
		}

        int max = 0;
        for (int i = 0; i < k2; i++) {
            for (int j = 0; j < k2; j++) {
                int y0 = k2, x0 = k2;
                int y1 = Math.min(i + k, k2), x1 = Math.min(j + k, k2);
                int y2 = i, x2 = j;
                int y3 = Math.max(i - k, 0), x3 = Math.max(j - k, 0);
                int y4 = 0, x4 = 0;

                int sum = _2Cum_sum_sum(y1, y0, x1, x0)+ _2Cum_sum_sum(y1, y0, x3, x2)+ _2Cum_sum_sum(y2, y1, x2, x1)
                          + _2Cum_sum_sum(y2, y1, x4, x3)+ _2Cum_sum_sum(y3, y2, x3, x2)+ _2Cum_sum_sum(y3, y2, x1, x0)
                          + _2Cum_sum_sum(y4, y3, x4, x3)+ _2Cum_sum_sum(y4, y3, x2, x1);

                max = Math.max(sum, max);
            }
        }
        System.out.println(max);

	}
    private static int _2Cum_sum_sum(int ya, int yb, int xa, int xb) {
        return _2Cum_sum[ya][xa] + _2Cum_sum[yb][xb] - _2Cum_sum[yb][xa] - _2Cum_sum[ya][xb];
    }

}

import java.io.*;
import java.util.*;

class Solver {
  final int n, k;
  final int[] xs, ys;
  final char[] cs;

  Solver(int n, int k, int[] xs, int[] ys, char[] cs) {
    this.n = n;
    this.k = k;
    this.xs = xs;
    this.ys = ys;
    this.cs = cs;
  }

  public int solve() {
    int[][] whiteTopLeftIncrementalTable = new int[k][2 * k];
    for (int i = 0; i < n; i++) {
      // [0, 0] - [2k, 2k]
      int normX = xs[i] % (2 * k);
      int normY = ys[i] % (2 * k);
      // [0, 0] - [3k, 2k]
      int whiteNormX = normX + (cs[i] == 'B' ? k : 0);
      int whiteNormY = normY;
      // [-k, -k] - [2k, 1k]
      int topLeftWhiteNormX = whiteNormX - (k - 1);
      int topLeftWhiteNormY = whiteNormY - (k - 1);

      // [whiteNormX - (k - 1), whiteNormY - (k - 1)] - [whiteNormX, whiteNormY]
      for (int a = -4; a <= 4; a++) {
        for (int b = -4; b <= 4; b++) {
          if ((a + b) % 2 != 0) {
            continue;
          }
          int topLeftX = topLeftWhiteNormX + a * k;
          int topLeftY = topLeftWhiteNormY + b * k;
          int bottomRightX = topLeftX + k - 1;
          int bottomRightY = topLeftY + k - 1;
          // [(topLeftX, topLeftY) - (bottomRightX, bottomRightY)] - [(0, 0) - (2k-1, k-1)]
          if (bottomRightX < 0) continue;
          if (bottomRightY < 0) continue;
          if (2 * k - 1 < topLeftX) continue;
          if (k - 1 < topLeftY) continue;
          whiteTopLeftIncrementalTable[Math.max(topLeftY, 0)][Math.max(topLeftX, 0)] += 1;
          if (topLeftY + k < k) {
            whiteTopLeftIncrementalTable[topLeftY + k][Math.max(topLeftX, 0)] += -1;
          }
          if (topLeftX + k < 2 * k) {
            whiteTopLeftIncrementalTable[Math.max(topLeftY, 0)][topLeftX + k] += -1;
          }
          if (topLeftY + k < k && topLeftX + k < 2 * k) {
            whiteTopLeftIncrementalTable[topLeftY + k][topLeftX + k] += 1;
          }
        }
      }
      /*
        System.err.println("---");
      for (int y = 0; y < k; y++) {
        for (int x = 0; x < 2 * k; x++) {
          System.err.printf("%3d", whiteTopLeftIncrementalTable[y][x]);
        }
        System.err.println();
      }
      */
    }

    int[] line = new int[2 * k];
    int answer = 0;
    for (int i = 0; i < k; i++) {
      for (int j = 0; j < 2 * k; j++) {
        line[j] += whiteTopLeftIncrementalTable[i][j];
      }
      int count = 0;
      for (int j = 0; j < 2 * k; j++) {
        count += line[j];
        answer = Math.max(answer, count);
      }
    }
    return answer;
  }
}

public class Main {
  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int k = reader.nextInt();
    int[] xs = new int[n];
    int[] ys = new int[n];
    char[] cs = new char[n];
