import java.util.Scanner;

public class Main {
    private static final int B = 1;
    private static final int W = 2;

    public static void main(String args[]) {
        try (Scanner in = new Scanner(System.in)) {
            int N = in.nextInt();
            int K = in.nextInt();
            int[] x = new int[N];
            int[] y = new int[N];
            int[] bw = new int[N];

            for (int i = 0; i < N; i++) {
                x[i] = in.nextInt();
                y[i] = in.nextInt();
                bw[i] = in.next().charAt(0) == 'B' ? B : W;
            }

            int[][] b = new int[2 * K][2 * K];
            int[][] w = new int[2 * K][2 * K];
            for (int i = 0; i < N; i++) {
                x[i] %= 2 * K;
                y[i] %= 2 * K;
                if (bw[i] == B) {
                    b[y[i]][x[i]]++;
                } else {
                    w[y[i]][x[i]]++;
                }
            }

            int[][] sumB = new int[2 * K + 1][2 * K + 1];
            int[][] sumW = new int[2 * K + 1][2 * K + 1];
            for (int r = 0; r < 2 * K; r++) {
                for (int c = 0; c < 2 * K; c++) {
                    sumB[r + 1][c + 1] = sumB[r + 1][c] + sumB[r][c + 1] - sumB[r][c] + b[r][c];
                    sumW[r + 1][c + 1] = sumW[r + 1][c] + sumW[r][c + 1] - sumW[r][c] + w[r][c];
                }
            }

            int max = 0;
            for (int r = 0; r < K; r++) {
                for (int c = 0; c < K; c++) {
                    int r0 = 0;
                    int r1 = r;
                    int r2 = Math.min(r + K, 2 * K);
                    int r3 = 2 * K;

                    int c0 = 0;
                    int c1 = c;
                    int c2 = Math.max(c + K, 2 * K);
                    int c3 = 2 * K;

                    int num = sum(sumB, r0, c0, r1, c1) //
                            + sum(sumW, r0, c1, r1, c2)//
                            + sum(sumB, r0, c2, r1, c3)//
                            + sum(sumW, r1, c0, r2, c1) //
                            + sum(sumB, r1, c1, r2, c2) //
                            + sum(sumW, r1, c2, r2, c3) //
                            + sum(sumB, r2, c0, r3, c1) //
                            + sum(sumW, r2, c1, r3, c2) //
                            + sum(sumB, r2, c2, r3, c3);

                    max = Math.max(max, num);

                    int num2 = sum(sumW, r0, c0, r1, c1) //
                            + sum(sumB, r0, c1, r1, c2)//
                            + sum(sumW, r0, c2, r1, c3)//
                            + sum(sumB, r1, c0, r2, c1) //
                            + sum(sumW, r1, c1, r2, c2) //
                            + sum(sumB, r1, c2, r2, c3) //
                            + sum(sumW, r2, c0, r3, c1) //
                            + sum(sumB, r2, c1, r3, c2) //
                            + sum(sumW, r2, c2, r3, c3);

                    max = Math.max(max, num2);
                }
            }

            System.out.println(max);
        }
    }

    private static int sum(int[][] sum, int r, int c, int r2, int c2) {
        return sum[r][c] - sum[r2][c] - sum[r][c2] + sum[r2][c2];
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), k = sc.nextInt();
        int sum[][] = new int[2*k+1][2*k+1];
        int t[][] = new int[2*k][2*k];
        for(int i=0;i<n;i++){
            int x = sc.nextInt(), y = sc.nextInt();
            String c = sc.next();
            x %= 2*k;
            y %= 2*k;
            if(x>=k&&y>=k){
                x-=k;
                y-=k;
            }
            if(c.equals("B")){
                if(x>y) x = (x + k) % k;
                else y = (y + k) % k;
            }
            if(y>x){
                int tmp = x;
                x = y;
                y = tmp;
            }
            t[x][y]++;
        }


        for(int i=0;i<2*k;i++){
            for(int j=0;j<k;j++){
                sum[i+1][j+1] = sum[i+1][j] + sum[i][j+1] -sum[i][j] + t[i][j];
            }
        }

        int ans = 0;
        for(int i=0;i<=k;i++){
            int t_ans = sum[k+i][k] - sum[i][k];
            ans = Math.max(ans , t_ans); 
        }
        System.out.println(ans);
    }
}

