		int[][] ans = new int[2*K][K];
		for(int i=0; i<2*K; ++i){
			for(int j=0; j<K; ++j){
				ans[i][j] = 0;
			}
		}

		for(int i=0; i<N; ++i){
			int x = (int)(sc.nextLong()%(2*K));
			int y = (int)(sc.nextLong()%K);
			String s = sc.next();
			if(s.equals("B")){
				for(int j=x; j<x+K; j++){
					for(int k=y; k<y+K; k++){
						ans[j%(2*K)][k%K]++;
					}					
				}
			}else{
				for(int j=x; j<x+K; j++){
					for(int k=y+K; k<y+2*K; k++){
						ans[j%(2*K)][k%K]++;
					}					
				}
			}
		}

		int max = 0;
		for(int i=0; i<2*K; ++i){
