    public static Pair translate(Pair p, boolean isBlack, int k){
        int x = p.x;
        int y = p.y;
        if(!isBlack) y+=k;
        x = x%(2*k);
        y = y%(2*k);
        if (x==0) x+= 2*k;
        if (y==0) y+= 2*k;
        return new Pair(x,y);
    }
}

class Pair{
    int x;
    int y;
    public Pair(int x,int y) {
        this.x = x;
        this.y = y;
    }
}
class CumSum{
    int[][] ct;
    public int get(int ix,int iy, int fx, int fy){
        return(ct[fx][fy]-ct[ix-1][fy]-ct[fx][iy-1]+ct[ix-1][iy-1]);
    }
    public CumSum(int[][] ct){
        this.ct = ct;
    }

    public static Pair translate(Pair p, boolean isBlack, int k){
        int x = p.x;
        int y = p.y;
        if(!isBlack) y+=k;
        x = x%(2*k);
        y = y%(2*k);
        if (x==0) x+= 2*k;
        if (y==0) y+= 2*k;
        return new Pair(x,y);
    }
}

