public class Main {

	public static void main(String[] args) {

		InputScanner in = new InputScanner(System.in);
		PrintWriter out = new PrintWriter(System.out);

		int N = in.nextInt();
		int K = in.nextInt();

		int[] x = new int[N];
		int[] y = new int[N];
		String[] c = new String[N];
		for (int i = 0; i < N; i++) {
			x[i] = in.nextInt();
			y[i] = in.nextInt();
			c[i] = in.next();

			if (c[i].equals("W")) {
				y[i] += K;
			}

			x[i] %= 2 * K;
			y[i] %= 2 * K;
		}

		int[][] count = new int[2 * K][2 * K];
		for (int i = 0; i < N; i++) {
			count[x[i]][y[i]]++;
		}

		int[][] countSum = new int[2 * K + 1][2 * K + 1];
		countSum[0][0] = 0;
		countSum[1][0] = 0;
		countSum[0][1] = 0;
		for (int i = 1; i <= 2 * K; i++) {
			for (int j = 1; j <= 2 * K; j++) {
				countSum[i][j] += count[i - 1][j - 1] + countSum[i - 1][j] + countSum[i][j - 1];
				countSum[i][j] -= countSum[i - 1][j - 1];
			}
		}

		int ans = 0;
		for (int i = 0; i < K; i++) {
			for (int j = 0; j < K; j++) {
				int blackNum = countSum[K + i][K + i] - countSum[i][i + K] - countSum[K + i][K] + countSum[K][K];
				int max = Math.max(blackNum, N - blackNum);
				ans = Math.max(ans, max);
			}
		}

