import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int N = scanner.nextInt();
        int K = scanner.nextInt();
        int count = 0;
        int[][] delta = new int[K][K];
        for (int i = 0; i < N; i = Math.incrementExact(i)) {
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            char c = scanner.next().charAt(0);
            int p = Math.addExact(x / K, y / K);
            delta[x % K][y % K] = Math.incrementExact(delta[x % K][y % K]);
            if ((p % 2 == 0 && c == 'W') || (p % 2 == 1 && c == 'B')) {
                delta[x % K][y % K] = Math.subtractExact(delta[x % K][y % K], 2);
                count = Math.incrementExact(count);
            }
        }
        for (int i = 0; i < K; i = Math.incrementExact(i)) for (int j = 1; j < K; j = Math.incrementExact(j)) delta[i][j] = Math.addExact(delta[i][j], delta[i][j - 1]);
        for (int j = 0; j < K; j = Math.incrementExact(j)) for (int i = 1; i < K; i = Math.incrementExact(i)) delta[i][j] = Math.addExact(delta[i][j], delta[i - 1][j]);
        int max = count;
        for (int i = 0; i <= K; i = Math.incrementExact(i)) {
            for (int j = 0; j <= K; j = Math.incrementExact(j)) {
                int c = count;
                if (i > 0)
                    c = Math.addExact(c, delta[i - 1][K - 1]);
                if (j > 0)
                    c = Math.addExact(c, delta[K - 1][j - 1]);
                if (i > 0 && j > 0)
                    c = Math.subtractExact(c, 2 * delta[i - 1][j - 1]);
                max = Math.max(max, c);
            }
        }
        System.out.println(max);
    }
}

import java.util.Arrays;
import java.util.Scanner;
import java.util.stream.IntStream;

/**
 * 解説通りに作成したソースコード
 * 
 * https://atcoder.jp/contests/abc086/submissions/2279952 にも参照
 */
public class Main {

	/** 白の定数 */
	private static final String WHITE = "W";

	/** 四角の差分を計算用 */
	private static final int[] X_DIFFS = { 0, 0, 1, 1, 1, 1, 2, 2 };
	private static final int[] Y_DIFFS = { 0, 1, 0, 1, 1, 2, 1, 2 };
	private static final int[] COUNT_DIFFS = { 1, -1, -1, 1, 1, -1, -1, 1 };

	public static void main(String[] args) {
		try (Scanner scanner = new Scanner(System.in)) {
			int n = scanner.nextInt(), k = scanner.nextInt();
			int w = 4 * k + 1, k2 = 2 * k;
			int[][] count = new int[w][w];
			IntStream.range(0, w).forEach(i -> Arrays.fill(count[i], 0));
			IntStream.range(0, n).forEach(i -> {
				int x = scanner.nextInt(), y = scanner.nextInt();
				if (WHITE.equals(scanner.next())) {
					// 黒へ変換
					y += k;
				}
				x %= k2;
				y %= k2;
				for (int j = 0; j < X_DIFFS.length; j++) {
					count[x + X_DIFFS[j] * k][y + Y_DIFFS[j] * k] += COUNT_DIFFS[j];
				}
			});
			// 横方向への累積和
			IntStream.range(0, w).forEach(i -> IntStream.range(1, w).forEach(j -> count[i][j] += count[i][j - 1]));
			// 縦方向への累積和
			IntStream.range(1, w).forEach(i -> IntStream.range(0, w).forEach(j -> count[i][j] += count[i - 1][j]));
			// 2k x 2k 範囲を超えたcountを2k x 2k範囲に加算
			IntStream.range(0, w).forEach(i -> IntStream.range(0, w).filter(j -> (i >= k2) || (j >= k2))
					.forEach(j -> count[i % k2][j % k2] += count[i][j]));
			// 2k x 2k 範囲の最大値を出力
			System.out.println(IntStream.range(0, k2)
					.map(i -> IntStream.range(0, k2).map(j -> count[i][j]).max().getAsInt()).max().getAsInt());
		}
	}
}

