public void solve() {
	int num = ni();
	int k = ni();
	long cnt[][] = new long[k + 1][k + 1];
	long cnt2 = 0;
	fill(cnt, 0);
	for(int i = 0; i < num; i ++) {
		int x = ni();
		int y = ni();
		boolean b = ns().equals("B");
		b ^= x / k % 2 != 0;
		x %= k;
		x ++;
		b ^= y / k % 2 != 0;
		y %= k;
		y ++;
		cnt[x][y] += b ? 1 : -1;
		cnt2 += b ? 0 : 1;
	}
	errprtln(cnt);

	for(int i = 1; i <= k; i ++) {
		for(int j = 1; j <= k; j ++) {
			cnt[i][j] += cnt[i - 1][j];
			cnt[i][j] += cnt[i][j - 1];
			cnt[i][j] -= cnt[i - 1][j - 1];
		}
	}
	long max = 0;
	for(int i = 0; i <= k; i ++) {
		for(int j = 0; j <= k; j ++) {
		long tmp = cnt[k][k] - cnt[i][k] - cnt[k][j] + cnt[i][j] * 2 + cnt2;
		max = max(max, tmp, num - tmp);
		}
	}
	assrt(max <= num);
	prtln(max);
}



