class ABC086_C_Calc extends Thread {
	int heightSlide;
	public ABC086_C_Calc(int i) {
		heightSlide = i;
	}
	@Override
	public void run() {
		int answer = 0;
		int answer2 = 0;
		for (int widthSlide = 0; widthSlide < Main.K; widthSlide++) {
