	class Imos2D{
		//0-indexed
		int h = 0, w = 0;
		long[][] s;
		boolean isBuilt = true;

		public Imos2D(int h, int w){
			this.h = h;
			this.w = w;
			this.s = new long[h+1][w+1];
		}

		/*横に[l,r)縦に[u,d)の範囲の加算*/
		public void add(int d, int u, int l, int r, long a){
			s[l][d] += a;
			s[r][d] -= a;
			s[l][u] -= a;
			s[r][u] += a;
			isBuilt = false;
		}

		public void build(){
			for(int i = 0; i < h; i++){
				for(int j = 1; j < w; j++){
					s[i][j] += s[i][j-1];
				}
			}
			for(int i = 1; i < h; i++){
				for(int j = 0; j < w; j++){
					s[i][j] += s[i-1][j];
				}
			}
			isBuilt = true;
		}

		public long get(int y, int x){
			if(!isBuilt) System.err.println("Error : vector is not built .");
			return s[y][x];
		}
	}

