        		else if(x2+k<z && y1-k>=0){
        			im[y1-k][x2] += b[i][j];
        			im[y1][x2] -= b[i][j];
        			im[y1-k][x2+k] -= b[i][j];
        			im[y1][x2+k] += b[i][j];
        		}
        		else if(x1-k>=0 && y2+k<z){
        			im[x1-k][y2] += b[i][j];
        			im[x1-k][y2+k] += b[i][j];
        			im[x1][y2] += b[i][j];
        			im[x1][y2+k] += b[i][j];
        		}
        	}
        }

