            }
        }
        for(int i=0;i<k*2;i++){
            for(int j=1;j<k*2+1;j++){
                hsum[j][i]=hsum[j-1][i]+input[j-1][i];
                wsum[i][j]=wsum[i][j-1]+input[i][j-1];
            }
        }
        int[] ans=new int[k*2];
        int finalans=0;
        int tmp;
        for(int i=0;i<k;i++){
            ans[0]+=hsum[k][i]-hsum[0][i];
            ans[0]+=hsum[k*2][i+k]-hsum[k][i+k];
        }
        finalans=ans[0];
        int[]movex1={0,-1,-2};
        int[]movey1={0,1,0};
        int[]movex2={0,1,-1};
        int[]movey2={0,1,1};
