						ans[j%(2*K)][k%(2*K)]++;
					}					
				}
				for(int j=x+K; j<x+2*K; j++){
					for(int k=y+K; k<y+2*K; k++){
						ans[j%(2*K)][k%(2*K)]++;
					}					
				}
			}else{
				for(int j=x; j<x+K; j++){
					for(int k=y+K; k<y+2*K; k++){
						ans[j%(2*K)][k%(2*K)]++;
					}					
				}
				for(int j=x+K; j<x+2*K; j++){
					for(int k=y; k<y+K; k++){
						ans[j%(2*K)][k%(2*K)]++;
					}					
				}
			}
		}

