@SuppressWarnings("unused")
public class Main {
	FastScanner in = new FastScanner(System.in);
	PrintWriter out = new PrintWriter(System.out);
	final int MOD = (int)1e9+7;
	void printlnYN(boolean b){out.println((b ? "Yes" : "No"));}

	//https://atcoder.jp/contests/abc086/tasks/arc089_b

	//System.out.println();はつかわない！！
	void solve() throws Exception{
		int N = in.nextInt(), K = in.nextInt();
		Imos2D imos = new Imos2D(6*K+2, 6*K+2);
		for(int i = 0; i < N; i++){
			int x = in.nextInt(), y = in.nextInt();
			x %= 2*K; y %= 2*K;
			x += 2*K; y += 2*K;

			boolean isW = (in.nextChar() == 'W');
				if(isW){
					imos.add(y+1, y+K+1, x-2*K+1, x-K+1, 1);
					imos.add(y-K+1, y+1, x-K+1, x+1, 1);
					imos.add(y+1, y+K+1, x+1, x+K+1, 1);
					imos.add(y-K+1, y+1, x+K+1, x+2*K+1, 1);
				}else{
					imos.add(y+1, y+K+1, x-2*K, x-K, 1);
					imos.add(y-K+1, y+1, x-K, x, 1);
					imos.add(y+1, y+K+1, x, x+K, 1);
					imos.add(y-K+1, y+1, x+K, x+2*K, 1);
				}
		}
		imos.build();

		long max = 0;
		for(int i = 0; i < 6*K+2; i++){
			for(int j = 0; j < 6*K+2; j++){
				max = Math.max(max, imos.get(i, j));
			}
		}
		out.println(max);
	}

	class Imos2D{
		//0-indexed
		int h = 0, w = 0;
		long[][] s;
		boolean isBuilt = true;

		public Imos2D(int h, int w){
			this.h = h;
			this.w = w;
			this.s = new long[h+1][w+1];
		}

		/*横に[l,r)縦に[u,d)の範囲の加算*/
		public void add(int d, int u, int l, int r, long a){
			s[l][d] += a;
			s[r][d] -= a;
			s[l][u] -= a;
			s[r][u] += a;
			isBuilt = false;
		}

		public void build(){
			for(int i = 0; i < h; i++){
				for(int j = 1; j < w; j++){
					s[i][j] += s[i][j-1];
				}
			}
			for(int i = 1; i < h; i++){
				for(int j = 0; j < w; j++){
					s[i][j] += s[i-1][j];
				}
			}
			isBuilt = true;
		}

		public long get(int y, int x){
			if(!isBuilt) System.err.println("Error : vector is not built .");
			return s[y][x];
		}
	}

