class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n, k;
        sc.Multi(out n, out k);
        var w = new int[k * 2][];
        var b = new int[k * 2][];
        for (int i = 0; i < k * 2; i++)
        {
            w[i] = new int[k * 2];
            b[i] = new int[k * 2];
        }
        for (int i = 0; i < n; i++)
        {
            int x, y;
            char c;
            sc.Multi(out x, out y, out c);
            x %= k * 2;
            y %= k * 2;
            if (c == 'W') {
                ++w[x][y];
            }
            else {
                ++b[x][y];
            }
        }
        var imw = new int[k * 2 + 1][];
        var imb = new int[k * 2 + 1][];
        for (int i = 0; i < k * 2 + 1; i++)
        {
            imw[i] = new int[k * 2 + 1];
            imb[i] = new int[k * 2 + 1];
        }
        for (int i = 0; i < k * 2; i++)
        {
            for (int j = 0; j < k * 2; j++)
            {
                imw[i + 1][j + 1] += imw[i + 1][j] + w[i][j];
                imb[i + 1][j + 1] += imb[i + 1][j] + b[i][j];
            }
            for (int j = 0; j < k * 2; j++)
            {
                imw[i + 1][j + 1] += imw[i][j + 1];
                imb[i + 1][j + 1] += imb[i][j + 1];
            }
        }
        int ans = 0;
        for (int i = 0; i < k; i++)
        {
            for (int j = 0; j < k; j++)
            {
                {
                    int sum = 0;
                    sum += imw[i + k][j + k] - imw[i + k][j] - imw[i][j + k] + imw[i][j];
                    sum += imw[k + k][k + k] - imw[k + k][j + k] - imw[i + k][k + k] + imw[i + k][j + k];
                    sum += imw[k + k][j] - imw[i + k][j];
                    sum += imw[i][k + k] - imw[i][j + k];
                    sum += imw[i][j];
                    sum += imb[k + k][j + k] - imb[k + k][j] - imb[i + k][j + k] + imb[i + k][j];
                    sum += imb[i + k][k + k] - imb[i + k][j + k] - imb[i][k + k] + imb[i][j + k];
                    sum += imb[i + k][j] - imb[i][j];
                    sum += imb[i][j + k] - imb[i][j];
                    ans = Math.Max(ans, sum);
                }
                {
                    int sum = 0;
                    sum += imb[i + k][j + k] - imb[i + k][j] - imb[i][j + k] + imb[i][j];
                    sum += imb[k + k][k + k] - imb[k + k][j + k] - imb[i + k][k + k] + imb[i + k][j + k];
                    sum += imb[k + k][j] - imb[i + k][j];
                    sum += imb[i][k + k] - imb[i][j + k];
                    sum += imb[i][j];
                    sum += imw[k + k][j + k] - imw[k + k][j] - imw[i + k][j + k] + imw[i + k][j];
                    sum += imw[i + k][k + k] - imw[i + k][j + k] - imw[i][k + k] + imw[i][j + k];
                    sum += imw[i + k][j] - imw[i][j];
                    sum += imw[i][j + k] - imw[i][j];
                    ans = Math.Max(ans, sum);
                }
            }
        }
        Prt(ans);
    }
}

class pair<T, U> : IComparable<pair<T, U>> {
    public T v1;
    public U v2;
    public pair() : this(default(T), default(U)) {}
    public pair(T v1, U v2) { this.v1 = v1; this.v2 = v2; }
    public int CompareTo(pair<T, U> a) {
        int c = Comparer<T>.Default.Compare(v1, a.v1);
        return c != 0 ? c : Comparer<U>.Default.Compare(v2, a.v2);
    }
    public override string ToString() => v1 + " " + v2;
    public void Deconstruct(out T a, out U b) { a = v1; b = v2; }
}
