	string[] Strs => ReadLine().Split();
	int K, L;
	readonly int[,,] sum;
	public _K()
	{
		var I = G;
		K = I[1];
		L = 4 * K;
		sum = new int[L + 1, L + 1, 2];
		for (var i = 0; i < I[0]; i++)
		{
			var S = Strs;
			Add(int.Parse(S[0]) % (2 * K) + 1, int.Parse(S[1]) % (2 * K) + 1, S[2] == "B" ? 0 : 1);
		}
		for (var c = 0; c < 2; c++)
		{
			for (var x = 0; x < L; x++) for (var y = 0; y <= L; y++) sum[x + 1, y, c] += sum[x, y, c];
			for (var x = 0; x <= L; x++) for (var y = 0; y < L; y++) sum[x, y + 1, c] += sum[x, y, c];
		}
		var max = 0;
		for (var i = 0; i < 2 * K; i++) for (var j = 0; j < K; j++) max = Max(max, Sum(i, j));
		WriteLine(max);
	}
	void Add(int x, int y, int c)
	{
		sum[x, y, c]++;
		sum[x + 2 * K, y, c]++;
		sum[x + 2 * K, y + 2 * K, c]++;
		sum[x, y + 2 * K, c]++;
	}
	int Sum(int i, int j) => Sum(i, j, 0) + Sum(i + K, j + K, 0) + Sum(i, j + K, 1) + Sum(i + K, j, 1);
	int Sum(int i, int j, int c) => sum[i + K, j + K, c] - sum[i + K, j, c] - sum[i, j + K, c] + sum[i, j, c];
