    class Program
    {
        static void Main(string[] args)
        {
            String[] nktmp = Console.ReadLine().Split(' ');
            int n = int.Parse(nktmp[0]);
            int k = int.Parse(nktmp[1]);
            int[,] hope = new int[n, 3];
            int max = 0;


            //希望の読み込み
            for (int i = 0; i < n; i++)
            {
                string[] tmphope = Console.ReadLine().Split(' ');
                hope[i, 0] = int.Parse(tmphope[0]) % (2*k);//2K*2Kの座標に転写
                hope[i, 1] = int.Parse(tmphope[1]) % (2 * k);//2K*2Kの座標に転写
                if (tmphope[2] == "W") hope[i, 2] = 0; else { hope[i, 2] = 1; }//WBを01に変換
            }


            //希望合致数チェック
            for (int xm = 0; xm < k; xm++)
            {
                for(int ym =0; ym<k; ym++)
                {
                    int count = 0;
                    for(int p=0; p<n; p++)
                    {
                        if (chk(hope[p, 0], hope[p, 1], xm, ym, k) == hope[p, 2]){ count++; }
                    }
                    if(n - count > count) { count = n - count; }//色反転と比較して多い方を採用
                    if(count > max) { max = count; }//最大なら更新
                    if (max >= n) { break; }//打ち切り                        
                }
                if (max >= n) { break; }//打ち切り
            }

            Console.WriteLine(max);

        }


        /* 座標(xi,yi)の色を返す　白なら0 黒なら1  
         * xm,ym:市松模様が0,0からどれくらいずれているか  k:市松模様の一辺 */
        static int chk(int xi, int yi, int xm, int ym, int k)
        {
            if (  k+xm < xi && k+ym < yi) { return 0; }
            if (xm <= xi && xi < k + xm
                && ym <= yi && yi < k + ym) { return 0; }
            return 1;
        }

    }




