            Read();
        }

        static void Solve()
        {
            var (N, K) = Slice2<long>();
            var KKB = new long[K, K];
            var KKW = new long[K, K];
            for (var i = 0; i < N; ++i)
            {
                var xyc = ReadLine().Split();
                var x = long.Parse(xyc[0]);
                var y = long.Parse(xyc[1]);
                var c = xyc[2][0] == 'B';
                var rev = false;
                if ((x / K % 2) != 0) rev = !rev;
                if ((y / K % 2) != 0) rev = !rev;
                x = x % K;
                y = y % K;
                c = rev ? !c : c;
                if (c)
                    ++KKB[x, y];
                else
                    ++KKW[x, y];
            }
            var ruiB = new long[K + 1, K + 1];
            var ruiW = new long[K + 1, K + 1];
            for (var i = 1; i <= K; ++i)
                for (var j = 1; j <= K; ++j)
                {
                    ruiB[i, j] = KKB[i - 1, j - 1] + ruiB[i, j - 1] + ruiB[i - 1, j] - ruiB[i - 1, j - 1];
                    ruiW[i, j] = KKW[i - 1, j - 1] + ruiW[i, j - 1] + ruiW[i - 1, j] - ruiW[i - 1, j - 1];
                }
            var ans = 0L;
            for (var i = 0; i <= K; ++i)
                for (var j = 0; j <= K; ++j)
                {
                    var num = 0L;
                    num += ruiB[K, K] - ruiB[i, K] - ruiB[K, j] + 2 * ruiB[i, j];
                    num += ruiW[i, K] + ruiW[K, j] - 2 * ruiW[i, j];
                    ans = Max(ans, Max(num, N - num));
                }
            WriteLine(ans);
        }
