    class Solver
    {
        private long N;
        private long K;
        private List<long> x;
        private List<long> y;
        private List<char> c;

        public void Solve()
        {
            @in(out N, out K);
            @in(N, out x, out y, out c);

            // 2K * 2Kの正方形のどこに黒が来れば何点取れるか、を表す配列に座圧する
            // 400万通りしかないので、累積和が取れるはず

            long sq = K * 2;
            int[][] black = new int[sq][];
            for (int i = 0; i < sq; i++)
            {
                black[i] = new int[sq];
            }

            for (int i = 0; i < N; i++)
            {
                if (c[i] == 'B')
                {
                    black[x[i] % sq][y[i] % sq]++;
                    black[(x[i] + K) % sq][(y[i] + K) % sq]++;
                }
                else
                {
                    black[(x[i]) % sq][(y[i] + K) % sq]++;
                    black[(x[i] + K) % sq][(y[i]) % sq]++;
                }
            }

            int[][] sum = new int[sq][];
            for (int i = 0; i < sq; i++)
            {
                sum[i] = new int[sq];
            }

            for (int i = 1; i <= K; i++)
            {
                for (int j = 1; j <= K; j++)
                {
                    sum[0][0] += black[(i + K) % sq][(j + K) % sq];
                }
            }


            for (int i = 1; i < sq; i++)
            {
                sum[0][i] = sum[0][i - 1];
                sum[i][0] = sum[i - 1][0];
                for (int j = 0; j < K; j++)
                {
                    sum[0][i] += black[(j + K + 1) % sq][i];
                    sum[0][i] -= black[(j + K + 1) % sq][(i + K) % sq];
                    sum[i][0] += black[i][(j + K + 1) % sq];
                    sum[i][0] -= black[(i + K) % sq][(j + K + 1) % sq];
                }
            }

            for (int i = 1; i < sq; i++)
            {
                for (int j = 1; j < sq; j++)
                {
                    sum[i][j] = sum[i - 1][j]
                                + sum[i][j - 1]
                                - sum[i - 1][j - 1]
                                - black[(i + K) % sq][j]
                                - black[i][(j + K) % sq]
                                + black[(i + K) % sq][(j + K) % sq]
                                + black[i][j];
                }
            }

            long ans = 0;
            for (int i = 0; i < sq; i++)
            {
                for (int j = 0; j < sq; j++)
                {
                    ans = Math.Max(ans, sum[i][j]);
                }
            }

            Console.WriteLine(ans);
        }
    }
