    class Program
    {
        static void Main(string[] args)
        {
            String[] nktmp = Console.ReadLine().Split(' ');
            int n = int.Parse(nktmp[0]);
            int k = int.Parse(nktmp[1]);
            int[,] hope = new int[n, 3];
            int max = 0;

            //希望の読み込み
            for (int i = 0; i < n; i++)
            {
                string[] tmphope = Console.ReadLine().Split(' ');
                hope[i, 0] = int.Parse(tmphope[0]) % (2*k);//2K*2Kの座標に写像
                hope[i, 1] = int.Parse(tmphope[1]) % (2 * k);//2K*2Kの座標に写像
                if (tmphope[2] == "W") hope[i, 2] = 0; else { hope[i, 2] = 1; }//WBを01に変換
            }

            //希望数を列ごとに数える hopenum[yi]:yi列の希望数
            int[] hopenum = Enumerable.Repeat<int>(0, 2*k).ToArray();
            for (int p = 0; p < n; p++){ hopenum[hope[p, 1]]++; }

            //合致数チェック
            for (int xm = 0; xm < k; xm++)
            {
                int[] countline= Enumerable.Repeat<int>(0, 2*k).ToArray();// countline[yi]:yi列の合致数
                int sum =0;//合致数合計

                //ym==0のときの合致数を列ごとに数える
                for(int p=0; p<n; p++)
                {
                    if( Chk(hope[p,0],hope[p,1],xm,0,k)==hope[p,2]) 
                    {
                        countline[ hope[p,1] ]++;
                        sum++;
                    }



                    //Console.Write("xi:"+ hope[p, 0]+" yi:"+ hope[p, 1]+" xm:"+ xm+ " ym:" + 0 + " k:" + k + " -- Chk;");
                    //Console.WriteLine( +Chk(hope[p, 0], hope[p, 1], xm, 0, k) == hope[p, 2]);



                }
                if (max < sum) { max = sum; }

                /*
                Console.Write("hopenum[ ");
                for (int ym = 0; ym < k * 2; ym++)
                {
                    Console.Write(hopenum[ym] + ", ");
                }
                Console.Write(" ]");
                Console.Write("countline[ ");
                for (int ym = 0; ym < k * 2; ym++)
                {
                    Console.Write(countline[ym] + ", ");
                }
                Console.Write(" ]");
                Console.WriteLine();
                */

                //列ごとに合致と非合致を反転させることで平行移動と同じ状態にする
                for (int ym =0; ym<k; ym++)
                {

                    //Console.WriteLine("sum:" + sum + " hopenum[ym]:" + hopenum[ym] + " countlinr[ym]" + countline[ym]);
                    //Console.WriteLine("sum:" + sum + " hopenum[ym+k]:" + hopenum[ym+k] + " countlinr[ym+k]" + countline[ym+k]);
                    sum = sum + hopenum[ym] - countline[ym] * 2;//ym列を反転
                    sum = sum + hopenum[ym+k] - countline[ym+k] * 2;//ym+k列を反転
                    if (max < sum) { max = sum; }
                }
                if(max >= n) { break; }
            }
            Console.WriteLine(max);
        }


        /* 座標(xi,yi)の色を返す　0,1の2色  
         * xm,ym:市松模様が0,0からどれくらいずれているか  k:市松模様の一辺 */
        private static int Chk(int xi, int yi, int xm, int ym, int k)
        {
            if(xm <= xi && xi < k+xm && ym <= yi && yi < k + ym) { return 0; }
            if(k+xm <= xi && k+ym <= yi) { return 0; }
            if(k+xm <= xi && yi< ym) { return 0; }
            if (xi < xm && k + ym <= yi) { return 0; }
            if (xi < xm && yi < ym) { return 0; }
            return 1;
        }

    }

}

