            arr[x % K2][y % K2]++;
        }
        bsums = new Sums2D(brr);
        wsums = new Sums2D(wrr);
        var max = 0;
        for (int i = 0; i <= K; i++)
            for (int j = 0; j <= K; j++)
                UpdateMax(ref max,
                      Count(bsums, i, j)
                    + Count(bsums, i - K, j - K)
                    + Count(bsums, i + K, j - K)
                    + Count(bsums, i - K, j + K)
                    + Count(bsums, i + K, j + K)
                    + Count(wsums, i, j + K)
                    + Count(wsums, i + K, j)
                    + Count(wsums, i, j - K)
                    + Count(wsums, i - K, j)
                    );
        for (int i = 0; i <= K; i++)
            for (int j = 0; j <= K; j++)
                UpdateMax(ref max,
                      Count(wsums, i, j)
                    + Count(wsums, i - K, j - K)
                    + Count(wsums, i + K, j - K)
                    + Count(wsums, i - K, j + K)
                    + Count(wsums, i + K, j + K)
                    + Count(bsums, i, j + K)
                    + Count(bsums, i + K, j)
                    + Count(bsums, i, j - K)
                    + Count(bsums, i - K, j)
                    );
        return max;
    }

    int Count(Sums2D sums, int left, int top)
    {
        int rightExclusive = Math.Min(left + K, K2);
        int bottomExclusive = Math.Min(top + K, K2);
        if (left < 0) left = 0;
        if (top < 0) top = 0;
        return sums[left, rightExclusive, top, bottomExclusive];
    }

