public class SumTable2D {
    private readonly int[,] sumArray;
    public readonly int Height, Width;

    public SumTable2D(int[,] array) {
        Height = array.GetLength(0);
        Width = array.GetLength(1);
        sumArray = new int[Height + 1, Width + 1];

        for (int i = 0; i < Height; i++) {
            for (int j = 0; j < Width; j++) {
                sumArray[i + 1, j + 1] = sumArray[i, j + 1] + sumArray[i + 1, j] - sumArray[i, j] + array[i, j];
            }
        }
    }

    public long Sum(int beginRow, int endRow, int beginCol, int endCol) {
        return sumArray[endRow, endCol]
            - sumArray[beginRow, endCol]
            - sumArray[endRow, beginCol]
            + sumArray[beginRow, beginCol];
    }
}
