    public void Solve()
    {
        int N, K;
        sc.Make(out N, out K);
        var imos = Create(3 * K + 1, () => new int[3 * K + 1]);
        for (var i = 0; i < N; i++)
        {
            int x, y; char c;
            sc.Make(out x, out y, out c);
            if (c == 'W') x += K;
            x %= 2 * K; y %= 2 * K;
            imos[x][y]++; imos[x][y + K]--;
            imos[x + K][y]--; imos[x + K][y + K]++;
        }
        for (var i = 0; i < imos.Length; i++)
            for (var j = 0; j < imos.Length - 1; j++)
                imos[i][j + 1] += imos[i][j];
        for (var j = 0; j < imos.Length; j++)
            for (var i = 0; i < imos.Length - 1; i++)
                imos[i + 1][j] += imos[i][j];
        var res = 0;
        for (var i = 0; i < 2*K; i++)
            for (var j = 0; j < 2*K; j++)
            {
                var c = imos[i][j];
                if (i >= K) c += imos[i - K][j + K];
                if (i < K) c += imos[i + 2 * K][j];
                c += imos[i + K][j + K];
                chmax(ref res, c);
            }
        WriteLine(res);

    }
}

