                var blackCount = blackAccum[k][j] + blackAccum[i][k] - blackAccum[i][j] * 2;
                res = Max(res, Max(whiteCount + (totalBlack - blackCount), blackCount + (totalWhite - whiteCount)));
            }
        }

        Console.WriteLine(res);
    }
}

