using System;
using System.Linq;
using CompLib.Util;

public class Program
{
    int N, K;
    int[] X, Y;
    char[] C;
    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        K = sc.NextInt();
        X = new int[N];
        Y = new int[N];
        C = new char[N];
        for (int i = 0; i < N; i++)
        {
            X[i] = sc.NextInt();
            Y[i] = sc.NextInt();
            C[i] = sc.NextChar();
        }
        int[,] imos = new int[3 * K + 1, 2 * K + 1];
        for (int i = 0; i < N; i++)
        {
            int my = K - Y[i] % K;
            int mx = K - X[i] % K;
            int dx = X[i] / K;
            int dy = Y[i] / K;
            var f = (dx % 2 == 1) ^ (dy % 2 == 1) ^ (C[i] == 'B');
            if (f) my += K;
            imos[my, mx]++;
            imos[my + K, mx]--;
            imos[my, mx + K]--;
            imos[my + K, mx + K]++;
        }

        for (int i = 0; i <= 3 * K; i++)
        {
            for (int j = 0; j < 2 * K; j++)
            {
                imos[i, j + 1] += imos[i, j];
            }
        }

        for (int i = 0; i < 3 * K; i++)
        {
            for (int j = 0; j <= 2 * K; j++)
            {
                imos[i + 1, j] += imos[i, j];
            }
        }
        int ans = 0;
        for (int i = 0; i < K; i++)
        {
            for (int j = 0; j < K; j++)
            {
                int a = imos[i, j] + imos[i + K, j + K] + imos[i + 2 * K, j];
                int b = imos[i, j + K] + imos[i + K, j] + imos[i + 2 * K, j + K];
                ans = Math.Max(ans, Math.Max(a, b));
            }
        }

        Console.WriteLine(ans);
    }

    public static void Main(string[] args) => new Program().Solve();
}

