namespace atcoder_practice1
{
    class _086D0
    {


        static int[,] memo;
        static void Main()
        {
            string[] string_array;
            int N, K;
            string_array = Console.ReadLine().Split(' ');
            N = int.Parse(string_array[0]);
            K = int.Parse(string_array[1]);

            memo = new int[2*K + 1, 2*K + 1];

            for (int i=0;i < N; i++)
            {
                int x, y, x_, y_;
                string c;
                string_array = Console.ReadLine().Split(' ');
                x = int.Parse(string_array[0]);
                y = int.Parse(string_array[1]);
                c = string_array[2];

                if(c == "W")
                {
                    x += K;
                }

                x %= 2 * K;
                y %= 2 * K;

                x_ = x % K;
                y_ = y % K;

                if((x<K && y<K) || (x>=K && y >= K))
                {
                    imos(0, 0, x_ + 1, y_ + 1);
                    imos(x_ + K + 1, 0, 2 * K, y_ + 1);

                    imos(0, y_ + K + 1, x_ + 1, 2 * K);
                    imos(x_ + K + 1, y_ + K + 1, 2 * K, 2 * K);

                    imos(x_ + 1, y_ + 1, x_ + K + 1, y_ + K + 1);
                }
                else
                {
                    imos(x_ + 1, 0, x_ + K + 1, y_ + 1);
                    imos(x_ + 1, y_ + K + 1, x_ + K + 1, 2 * K);

                    imos(0, y_ + 1, x_ + 1, y_ + K + 1);
                    imos(x_ + K + 1, y_ + 1, 2 * K, y_ + K + 1);
                }
            }

            for (int i = 0; i < 2*K + 1; i++)
            {
                for (int j = 1; j < 2 * K + 1; j++)
                {
                    memo[i,j] += memo[i,j - 1];
                }
            }

            for (int i = 1; i < 2*K + 1; i++)
            {
                for (int j = 0; j < 2 * K + 1; j++)
                {
                    memo[i,j] += memo[i - 1,j];
                }
            }

            int m = 0;
            for (int i = 0; i < 2 * K; i++)
            {
                for (int j = 0; j < 2 * K; j++)
                {
                    m = Math.Max(m, memo[i,j]);
                }
            }

            Console.WriteLine(m);
        }

        static void imos(int x, int y, int x2, int y2 )
        {
            memo[x, y]++;
            memo[x, y2]--;
            memo[x2, y]--;
            memo[x2, y2]++;
        }

    }
}

