namespace AtCoder
{
    class Program
    {
        public static void Main()
        {
            new Program().Solve();
        }

        void Solve()
        {
            var tmp = Console.ReadLine().Split().Select(s => int.Parse(s)).ToArray();
            int n = tmp[0];
            int k = tmp[1];
            var info = new Info[n];
            for (int i = 0; i < n; i++)
            {
                var input = Console.ReadLine().Split();
                int x = int.Parse(input[0]);
                int y = int.Parse(input[1]);
                info[i] = new Info() { X = x, Y = y, Color = input[2] };
            }

            int max = int.MinValue;

            //(0,0) が k * kの模様のどの位置にあるか　k*kの左下が(0,0) 黒と白
            for (int kx = 0; kx < k; kx++)
            {
                for (int ky = 0; ky < k; ky++)
                {
                    int bCount = 0;//black
                    int wCount = 0;//white
                    foreach (var item in info)
                    {
                        //same with (0,0)area tile color
                        if ((item.X + kx) / k % 2 == 0 && (item.Y + ky) / k % 2 == 0)
                        {
                            if (item.Color == "B")
                                bCount++;
                            else
                                wCount++;
                        }
                        else
                        {
                            if (item.Color == "W")
                                bCount++;
                            else
                                wCount++;
                        }
                    }
                    max = Math.Max(max, bCount);
                    max = Math.Max(max, wCount);
                }
            }

            Console.WriteLine(max);
        }


        class Info
        {
            public int X { get; set; }
            public int Y { get; set; }
            public string Color { get; set; }
        }

    }
