            if (c == 'W') x += K;
            x %= 2 * K; y %= 2 * K;
            imos[x][y]++; imos[x][y + K]--;
            imos[x + K][y]--; imos[x + K][y + K]++;
        }
        for (var i = 0; i < imos.Length; i++)
            for (var j = 0; j < imos.Length - 1; j++)
                imos[i][j + 1] += imos[i][j];
        for (var j = 0; j < imos.Length; j++)
            for (var i = 0; i < imos.Length - 1; i++)
                imos[i + 1][j] += imos[i][j];
        var res = 0;
        for (var i = 0; i < 2*K; i++)
            for (var j = 0; j < 2*K; j++)
            {
                var c = imos[i][j];
                if (i >= K) c += imos[i - K][j + K];
                if (j >= K) c += imos[j - K][i + K];
                if (i >= 2 * K) c += imos[i - 2 * K][j];
                if (j >= 2 * K) c += imos[i][j - 2 * K];
                c += imos[i + 2 * K][j] + imos[i][j + 2 * K];
                c += imos[i + K][j + K] + imos[i + 2 * K][j + 2 * K];
                chmax(ref res, c);
            }
        WriteLine(res);

    }
}

