namespace Abc086D
{
    class Program
    {
        static int N, K;
        static List<Desire> Desires = new List<Desire>();
        struct Desire
        {
            public int X, Y;
            public char Color;
            public Desire(int x, int y, char color) {
                X = x <= (K + K) ? x : x - (x / (K + K)) * (K + K);
                Y = y <= (K + K) ? y : y - (y / (K + K)) * (K + K);
                Color = color;
            }
        }
        static void InitializeProblem(System.IO.TextReader reader) {
            var buffer = reader.ReadLine().Split();
            N = int.Parse(buffer[0]);
            K = int.Parse(buffer[1]);
            for(var i = 0; i != N; ++i) {
                buffer = reader.ReadLine().Split();
                Desires.Add(new Desire(int.Parse(buffer[0]), int.Parse(buffer[1]), buffer[2][0]));
            }
        }

        static int GetNumberOfSatisfaction(int bottom, int left, int width, int height, char color) {
            return Desires.Where(d => (left <= d.X && d.X <= left + width - 1
            && bottom <= d.Y && d.Y <= bottom + height - 1
            && d.Color == color)).Count();
        }
        internal static int SolveProblem(System.IO.TextReader reader) {
            InitializeProblem(reader);
            var satisfactionMax = 0;
            for(var w = K; w >= 1; ++w) {
                for(var h = K; h >= 1; ++h) {
                    var numberOfSatisfactions = GetNumberOfSatisfaction(0, 0, w, h, 'W')
                        + GetNumberOfSatisfaction(w, 0, K, h, 'B')
                        + GetNumberOfSatisfaction(w + K, 0, K - w, h, 'W')
                        + GetNumberOfSatisfaction(0, h, w, K, 'B')
                        + GetNumberOfSatisfaction(w, h, K, K, 'W')
                        + GetNumberOfSatisfaction(w + K, h, K - w, K, 'B')
                        + GetNumberOfSatisfaction(0, h + K, w, K - h, 'W')
                        + GetNumberOfSatisfaction(w, h + K, K, K - h, 'B')
                        + GetNumberOfSatisfaction(w + K, h + K, K - w, K - h, 'W');
                    satisfactionMax = Math.Max(numberOfSatisfactions, N - numberOfSatisfactions);
                    if(satisfactionMax == N) {
                        return N;
                    }
                }
            }
            return satisfactionMax;
        }

        static void Main(string[] args) {
            Console.WriteLine(SolveProblem(Console.In));
        }
    }
}

