namespace AtCoder
{
    class Program
    {
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        static long Mod = (long)1e9 + 7;
        static void Main(string[] args)
        {
            SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            Out.Flush();
            Read();
        }
        static void Solve()
        {
            var NK = Sarray();
            var N = NK[0];
            var K = NK[1];
            var K2 = 2 * K;
            var black = new long[K2, K2];
            var white = new long[K2, K2];
            for (var i = 0; i < N; ++i)
            {
                var xyc = ReadLine().Split();
                var x = long.Parse(xyc[0]) % K2;
                var y = long.Parse(xyc[1]) % K2;
                if (xyc[2] == "B")
                    ++black[x, y];
                else
                    ++white[x, y];
            }
            var bRui = new long[K2 + 1, K2 + 1];
            var wRui = new long[K2 + 1, K2 + 1];
            for (var x = 0; x < K2; ++x)
                for (var y = 0; y < K2; ++y)
                {
                    bRui[x + 1, y + 1] = bRui[x, y + 1] + bRui[x + 1, y] - bRui[x, y] + black[x, y];
                    wRui[x + 1, y + 1] = wRui[x, y + 1] + wRui[x + 1, y] - wRui[x, y] + white[x, y];
                }
            var max = 0L;
            for (var x = 0; x < K2; ++x)
                for (var y = 0; y < K2; ++y)
                {
                    var sum = 0L;
                    sum += Get2DRui(bRui, x, y, x + K, y + K);
                    sum += Get2DRui(bRui, x + K, y + K, x + K2, y + K2);
                    sum += Get2DRui(wRui, x + K, y, x + K2, y + K);
                    sum += Get2DRui(wRui, x, y + K, x + K, y + K2);
                    max = Max(max, sum);
                }
            WriteLine(max);
        }
        //[xl,xr)x[yd,yu)の範囲の累積和
        static long Get2DRui(long[,] rui,long xl,long yd, long xr, long yu)
        {
            var xLim = rui.GetLength(0) - 1;
            var yLim = rui.GetLength(1) - 1;
            long xpr = 0, xpl = 0, ypu = 0, ypd = 0;
            if (xLim <= xl)
            {
                xl %= xLim;
                xr %= xLim;
            }
            if (yLim <= yd)
            {
                yd %= yLim;
                yu %= yLim;
            }
            if (xLim < xr)
            {
                xpr = xr % xLim;
                xr = xLim;
            }
            if (yLim < yu)
            {
                ypu = yu % yLim;
                yu = yLim;
            }

            var men = 0L;
            men += rui[xr,   yu] - rui[xl,   yu] - rui[xr,   yd] + rui[xl,   yd];
            men += rui[xr,  ypu] - rui[xl,  ypu] - rui[xr,  ypd] + rui[xl,  ypd];
            men += rui[xpr,  yu] - rui[xpl,  yu] - rui[xpr,  yd] + rui[xpl,  yd];
            men += rui[xpr, ypu] - rui[xpl, ypu] - rui[xpr, ypd] + rui[xpl, ypd];
            return men;
        }
    }
}

using System;
using System.Linq;

class D
{
	static void Main()
	{
		var h = Console.ReadLine().Split().Select(int.Parse).ToArray();
		var k = h[1];

		var bw = new int[k, k, 2];
		foreach (var x in new int[h[0]].Select(_ => Console.ReadLine().Split()))
		{
			var p = x.Take(2).Select(int.Parse).ToArray();
			bw[p[0] % k, p[1] % k, (p[0] / k + p[1] / k + (x[2] == "B" ? 0 : 1)) % 2]++;
		}

		var ti = new int[k, 2];
		for (int c = 0; c < 2; c++)
			for (int i = 0; i < k; i++)
				for (int j = 0; j < k; j++)
					ti[i, c] += bw[i, j, c];
		var tj = new int[k, 2];
		for (int c = 0; c < 2; c++)
			for (int j = 0; j < k; j++)
				for (int i = 0; i < k; i++)
					tj[j, c] += bw[i, j, c];
		var s = new int[2];
		for (int c = 0; c < 2; c++)
			for (int i = 0; i < k; i++)
				s[c] += ti[i, c];

		var M = 0;
		for (int j = 0; j < k; j++)
		{
			for (int i = 0; i < k; i++)
			{
				M = Math.Max(M, s[0]);
				M = Math.Max(M, s[1]);
				s[0] += ti[i, 1] - ti[i, 0];
				s[1] += ti[i, 0] - ti[i, 1];
			}

			for (int i = 0; i < k; i++)
			{
				ti[i, 0] += bw[i, j, 1] - bw[i, j, 0];
				ti[i, 1] += bw[i, j, 0] - bw[i, j, 1];
			}
			Array.Reverse(s);
			s[0] += tj[j, 1] - tj[j, 0];
			s[1] += tj[j, 0] - tj[j, 1];
		}
		Console.WriteLine(M);
	}
}

