    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Yes" : "No"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        var N = cr.Int;
        K = cr.Int;
        K2 = 2 * K;
        var brr = NewArray(K2, K2, 0);
        var wrr = NewArray(K2, K2, 0);
        for (int i = 0; i < N; i++)
        {
            var x = cr.Int;
            var y = cr.Int;
            int[][] arr;
            switch (cr.Ascii[0])
            {
                case 'B':
                    arr = brr;
                    break;
                default:
                    arr = wrr;
                    break;
            }
            arr[x % K2][y % K2]++;
        }
        bsums = new Sums2D(brr);
        wsums = new Sums2D(wrr);
        var max = 0;
        for (int i = 0; i < K; i++)
            for (int j = 0; j < K; j++)
                UpdateMax(ref max,
                      Count(bsums, i    , j)
                    + Count(bsums, i - K, j - K)
                    + Count(bsums, i + K, j - K)
                    + Count(bsums, i - K, j + K)
                    + Count(bsums, i + K, j + K)
                    + Count(wsums, i    , j + K)
                    + Count(wsums, i + K, j)
                    + Count(wsums, i    , j - K)
                    + Count(wsums, i - K, j)
                    );
        return max;
    }

    int Count(Sums2D sums, int left, int top)
    {
        int rightExclusive = Math.Min(left + K, K2);
        int bottomExclusive = Math.Min(top + K, K2);
        if (left < 0) left = 0;
        if (top < 0) top = 0;
        return sums[left, rightExclusive, top, bottomExclusive];
    }

    Sums2D bsums, wsums;
    int K, K2;
}
class Sums2D
{
    private int[][] impl;
    public int Length1 { get; }
    public int Length2 { get; }
    public Sums2D(int[][] arr)
    {
        this.Length1 = arr.Length;
        this.Length2 = arr[0].Length;
        impl = NewArray(Length1 + 1, Length2 + 1, 0);
        for (var i = 0; i < Length1; i++)
            for (var j = 0; j < Length2; j++)
                impl[i + 1][j + 1] = impl[i + 1][j] + impl[i][j + 1] - impl[i][j] + arr[i][j];
    }
    public int this[int left, int rightExclusive, int top, int bottomExclusive]
    {
        get
        {
            return impl[rightExclusive][bottomExclusive]
              - impl[left][bottomExclusive]
              - impl[rightExclusive][top]
              + impl[left][top];
        }
    }
}

