namespace Abc086D
{
    class Program
    {
        static int N, K;
        static List<Desire> Desires = new List<Desire>();
        struct Desire
        {
            public int X, Y;
            public char Color;
            public Desire(int x, int y, char color) {
                X = color == 'W' ? x % (K + K) : (x + K) % (K + K);
                Y = y % (K + K);
                Color = 'W';
            }
        }
        static void InitializeProblem(System.IO.TextReader reader) {
            var buffer = reader.ReadLine().Split();
            N = int.Parse(buffer[0]);
            K = int.Parse(buffer[1]);
            Desires.Clear();
            for(var i = 0; i != N; ++i) {
                buffer = reader.ReadLine().Split();
                Desires.Add(new Desire(int.Parse(buffer[0]), int.Parse(buffer[1]), buffer[2][0]));
            }
        }

        static int GetNumberOfSatisfaction(int left, int bottom, int width, int height, char color) {
            var n = Desires.Where(d => (left <= d.X && d.X <= left + width - 1
             && bottom <= d.Y && d.Y <= bottom + height - 1
             && d.Color == color)).Count();
            return n;
        }
        internal static int SolveProblem(System.IO.TextReader reader) {
            InitializeProblem(reader);
            var maxNumberOfSatisfied = 0;
            for(var w = K; w >= 1; --w) {
                for(var h = K; h >= 1; --h) {
                    var numberOfSatisfiedWhenBottomLeftIsWhite
                        = GetNumberOfSatisfaction(0, 0, w, h, 'W')
                        + GetNumberOfSatisfaction(w + K, 0, K - w, h, 'W')
                        + GetNumberOfSatisfaction(w, h, K, K, 'W')
                        + GetNumberOfSatisfaction(0, h + K, w, K - h, 'W')
                        + GetNumberOfSatisfaction(w + K, h + K, K - w, K - h, 'W');
                    var numberOfSatisfied = Math.Max(numberOfSatisfiedWhenBottomLeftIsWhite, N - numberOfSatisfiedWhenBottomLeftIsWhite);
                    if(numberOfSatisfied > maxNumberOfSatisfied) {
                        maxNumberOfSatisfied = numberOfSatisfied;
                    }
                    if(maxNumberOfSatisfied == N) {
                        return N;
                    }
                }
            }
            return maxNumberOfSatisfied;
        }

        static void Main(string[] args) {
            Console.WriteLine(SolveProblem(Console.In));
        }
    }
}

