                    Console.WriteLine();
                    */

                }
                if (max < sum) { max = sum; }


                //列ごとに合致と非合致を反転させることで平行移動と同じ状態にする
                for (int ym =0; ym<k; ym++)
                {
                    sum = sum + hopenum[ym] - countline[ym] * 2;//ym列を反転
                    sum = sum + hopenum[ym+k] - countline[ym+k] * 2;//ym+k列を反転
                    if (max < sum) { max = sum; }
                }
                if(max >= n) { break; }
            }
            Console.WriteLine(max);
        }


        /* 座標(xi,yi)の色を返す　0,1の2色  
         * xm,ym:市松模様が0,0からどれくらいずれているか  k:市松模様の一辺 */
        private static int Chk(int xi, int yi, int xm, int ym, int k)
        {
            if(xm <= xi && xi < k+xm && ym <= yi && yi < k + ym) { return 0; }
            if(k+xm <= xi && k+ym <= yi) { return 0; }
            if(k+xm <= xi && yi< ym) { return 0; }
            if(xi<xm && k+ym <= yi) { return 0; }
            return 1;
        }

    }

