public class Solver
{
	private int N;
	private int K;
	private int[] x;
	private int[] y;
	private int[] c;

	private int[,] csum;

	public Solver()
	{
		N = GetInt();
		K = GetInt();
		x = new int[N];
		y = new int[N];
		c = new int[N];
		for(int i = 0; i < N; i++)
		{
			x[i] = GetInt();
			y[i] = GetInt();
			c[i] = (GetString()[0] == 'B') ? 1 : 0;
		}
	}

	public void Solve()
	{
		int KK = 2 * K;
		int[] u = new int[N];
		int[] v = new int[N];
		for(int i = 0; i < N; i++)
		{
			u[i] = (x[i] % KK) + 1;
			v[i] = (c[i] == 1) ? (y[i] % KK) + 1 : ((y[i] + K) % KK) + 1;
		}

		csum = new int[KK + 1, KK + 1];
		for(int i = 0; i < N; i++)
			csum[u[i], v[i]]++;

		for(int i = 0; i <= KK; i++)
			for(int j = 0; j < KK; j++)
				csum[i, j + 1] += csum[i, j];

		for(int i = 0; i < KK; i++)
			for(int j = 0; j <= KK; j++)
				csum[i + 1, j] += csum[i, j];

		int ans = 0;
		for(int lowX = 1; lowX <= K + 1; lowX++)
		{
			int highX = lowX + K - 1;
			for(int lowY = 1; lowY <= K + 1; lowY++)
			{
				int highY = lowY + K - 1;
				int tmp = sum(lowX, lowY, highX, highY);

				if(lowX > 1 && lowY > 1)
					tmp += sum(1, 1, lowX - 1, lowY - 1);

				if(lowX > 1 && highY < KK)
					tmp += sum(1, highY + 1, lowX - 1, KK);

				if(highX < KK && lowY > 1)
					tmp += sum(highX + 1, 1, KK, lowY - 1);

				if(highX < KK && highY < KK)
					tmp += sum(highX + 1, highY + 1, KK, KK);

				ans = Math.Max(ans, tmp);
			}
		}

		Console.WriteLine(ans);
	}

	private int sum(int lowX, int lowY, int highX, int highY)
	{
		return csum[highX, highY] + 
		       csum[lowX - 1, lowY - 1] -
		       csum[highX, lowY - 1] - 
			   csum[lowX - 1, highY];
	}
}


