			var k2 = K * 2;
			// 2次元累積和計算用のmod grid
			var bg = new int[k2 * 2, k2 * 2];   // 黒
			var wg = new int[k2 * 2, k2 * 2];	// 白
			for (int i = 0; i < N; i++) {
				var sary = ReadStringArray();
				var x = int.Parse(sary[0]) % k2;
				var y = int.Parse(sary[1]) % k2;
				var s = sary[2];

				if (s == "B") {
					var cnt = bg[x, y] + 1;
					bg[x, y] = bg[x + k2, y] = bg[x, y + k2] = bg[x + k2, y + k2] = cnt;
				} else {
					var cnt = wg[x, y] + 1;
					wg[x, y] = wg[x + k2, y] = wg[x, y + k2] = wg[x + k2, y + k2] = cnt;
				}
			}

			// 2次元累積和
			var bs = new int[k2 * 2 + 1, k2 * 2 + 1];
			var ws = new int[k2 * 2 + 1, k2 * 2 + 1];
			for (int x = 0; x < k2 * 2; x++) {
				for (int y = 0; y < k2 * 2; y++) {
					bs[x + 1, y + 1] = bs[x, y + 1] + bs[x + 1, y] - bs[x, y] + bg[x, y];
					ws[x + 1, y + 1] = ws[x, y + 1] + ws[x + 1, y] - ws[x, y] + wg[x, y];
				}
			}

			// 黒マス左上座標の範囲で総当たり
			int ans = 0;
			for (int x = 0; x < k2; x++) {
				for (int y = 0; y < k2; y++) {
					// 黒マスは(x, y) (x+k, y+k)
					var bcnt = bs[x + K, y + K] - bs[x + K, y] - bs[x, y + K] + bs[x, y];
					bcnt += bs[x + k2, y + k2] - bs[x + k2, y + K] - bs[x + K, y + k2] + bs[x + K, y + K];
					// 白マスは (x+k, y) (x, y+k)
					var wcnt = ws[x + k2, y + K] - ws[x + k2, y] - ws[x + K, y + K] + ws[x + K, y];
					wcnt += ws[x + K, y + k2] - ws[x + K, y + K] - ws[x, y + k2] + ws[x, y + K];

					ReplaceIfBigger(ref ans, bcnt + wcnt);
				}
			}

			WriteLine(ans);
		}
