    Scanner cin;

    void calc()
    {
        cin = new Scanner();
        int N = cin.nextInt();
        int K = cin.nextInt();
        int[] x = new int[N];
        int[] y = new int[N];
        int[] z = new int[N];
        for (int i = 0; i < N; i++)
        {
            x[i] = cin.nextInt() % (2 * K) + (2 * K) % (2 * K);
            y[i] = cin.nextInt() % (2 * K) + (2 * K) % (2 * K);
            z[i] = cin.next() == "B" ? 0 : 1;
        }

        int bestAns = 0;
        for (int X = 0; X < K; X++)
        {
            List<int> num = new List<int>();
            int[] now = new int[N];
            int tmp = 0;
            for (int i = 0; i < N; i++)
            {
                int first = ((x[i] + X) / K % 2) ^ z[i] ^ (y[i] / K);
                int Y = y[i] % K;
                if(first == 1)
                {
                    num.Add(Y * 2 + 0);
                    num.Add((K + Y) * 2 + 1);
                }
                else
                {
                    num.Add(Y * 2 + 1);
                    num.Add((K + Y) * 2 + 0);
                }
                tmp += first;
            }
            int ans = tmp;
            num.Sort();
            foreach (var item in num)
            {
                if ((item & 1) == 1) tmp++;
                else tmp--;
                ans = Math.Max(tmp, ans);
            }


            bestAns = Math.Max(bestAns, ans);
        }

        Console.WriteLine(bestAns);
    }
}




