class Solver
{
    Scanner sc = new Scanner();
    //

    public void Solve()
    {
        int N, K;
        sc.Make(out N, out K);
        var imos = Create(2 * K + 1, () => new int[2 * K + 1]);
        var w = 0;
        for (var i = 0; i < N; i++)
        {
            int x, y; char c;
            sc.Make(out x, out y, out c);
            if (c == 'W') x += K;
            int m;
            if ((x / K + y / K) % 2 == 0) m = 1;
            else { m = -1; w++; }
            x %= K;y %= K;
            imos[x][y]+=m; imos[x][y + K]-=m;
            imos[x + K][y]-=m; imos[x + K][y + K]+=m;
        }
        for (var i = 0; i < imos.Length; i++)
            for (var j = 0; j < imos.Length - 1; j++)
                imos[i][j + 1] += imos[i][j];
        for (var j = 0; j < imos.Length; j++)
            for (var i = 0; i < imos.Length - 1; i++)
                imos[i + 1][j] += imos[i][j];
        var res = 0;
        for (var i = 0; i < K; i++)
            for (var j = 0; j < K; j++)
                chmax(ref res, Max(imos[i][j] + w, -imos[i][j] + N - w));
        WriteLine(res);
    }
}

