namespace D
{
	internal class Program
	{
		public static void Main(string[] args)
		{
			var line = Console.ReadLine().Split().Select(int.Parse).ToArray();
			var n = line[0];
			var k = line[1];
			var xn = new List<int>(n);
			var yn = new List<int>(n);
			var cn = new List<bool>(n); // 'W'ならtrue
			var xMods = new bool[k]; // kで割った余りがiのx座標が存在するか
			var yMods = new bool[k]; // kで割った余りがiのy座標が存在するか
			for (var i = 0; i < n; i++)
			{
				var line2 = Console.ReadLine().Split().ToArray();
				var x = int.Parse(line2[0]);
				var y = int.Parse(line2[1]);
				xn.Add(x);
				yn.Add(y);
				xMods[x % k] = true;
				yMods[y % k] = true;
				cn.Add(line2[2][0] == 'W');
			}

			var result = 0;
			for (var leftBottomX = 0; leftBottomX < k; leftBottomX++)
			{
				if (!xMods[leftBottomX]) { continue; }

				for (var leftBottomY = 0; leftBottomY < k; leftBottomY++)
				{
					if (!yMods[leftBottomY]) { continue; }

					var groupNum = 0;
					for (var i = 0; i < n; i++)
					{
						var tmp = (int) (Math.Floor((xn[i] - leftBottomX) / (double) k)) % 2 +
						          (int) (Math.Floor((yn[i] - leftBottomY) / (double) k)) % 2;
						if ((tmp % 2 == 0) ^ cn[i]) { groupNum++; }
					}

					if (groupNum * 2 < n) { groupNum = n - groupNum; }

					if (result < groupNum) { result = groupNum; }

					if (result == n)
					{
						Console.WriteLine(result);
						return;
					}
				}
			}

			Console.WriteLine(result);
		}
	}
}

