function Judge(x,y,c,k,tx,ty) {
	var col = c;
	if( Math.floor((tx-x)/k) % 2 != 0 )
	{
		col ^= 1;
	}
	if( Math.floor((ty-y)/k) % 2 != 0 )
	{
		col ^= 1;
	}
	return col;
}


