func countRegion(y, x int) int {
	limY, limX := y+K-1, x+K-1
	if limY >= len(board) {
		limY = len(board) - 1
	}

	if limX >= len(board[0]) {
		limX = len(board[0]) - 1
	}

	minLimY, minLimX := y-1, x-1
	if minLimY < 0 {
		minLimY = 0
	}
	if minLimY >= len(board) {
		minLimY = len(board) - 1
	}
	if minLimX < 0 {
		minLimX = 0
	}
	if minLimX >= len(board[0])-1 {
		minLimX = len(board[0]) - 1
	}

	return board[limY][limX] - board[limY][minLimX] - board[minLimY][limX] + board[minLimY][minLimX]
}

