		return b
	}
	return a
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func rect(x, y int, g graph) int {
	tx := min(x+K-1, len(g)-1)
	ty := min(y+K-1, len(g)-1)
	if tx < 0 || ty < 0 {
		return 0
	}

	nums := g[tx][ty]
	if x > 0 && y > 0 {
		nums += g[x-1][y-1]
	}
	if x > 0 {
		nums -= g[x-1][ty]
	}
	if y > 0 {
		nums -= g[tx][y-1]
	}
	return nums
}

func main() {
	fmt.Scan(&N, &K)

	g := make(graph, 2*K)
	for i := range g {
		g[i] = make([]int, 2*K)
	}

