			imos(0, ldd, x+1, k, matrix)
			imos(ldl+mod, ldd, -ldl, k, matrix)
		} else if ldd < -1 {
			imos(ldl, -1, k, y+1, matrix)
			imos(ldl, ldd+mod, k, -ldd-1, matrix)
		} else {
			imos(ldl, ldd, k, k, matrix)
		}
		if rul+k-1 >= mod && rud+k >= mod {
			imos(rul, rud, mod-rul, mod-rud-1, matrix)
			imos(rul, -1, mod-rul, k-mod+rud+1, matrix)
			imos(0, rud, k-mod+rul, mod-rud-1, matrix)
			imos(0, -1, k-mod+rul, k-mod+rud+1, matrix)
		} else if rul+k-1 >= mod {
			imos(rul, rud, mod-rul, k, matrix)
			imos(0, rud, k-mod+rul, k, matrix)
		} else if rud+k >= mod {
			imos(rul, rud, k, mod-rud-1, matrix)
			imos(rul, -1, k, k-mod+rud+1, matrix)
		} else {
			imos(rul, rud, k, k, matrix)
