		*/
	}
	for i := 0; i < mod; i++ {
		for j := 1; j < mod; j++ {
			matrix[i][j] += matrix[i][j-1]
		}
	}
	for i := mod - 2; i >= 0; i-- {
		for j := 0; j < mod; j++ {
			matrix[i][j] += matrix[i+1][j]
		}
	}
	maximum := 0
	for i := 0; i < mod; i++ {
		for j := 0; j < mod; j++ {
			if matrix[i][j] > maximum {
