func imos(ldl int, ldd int, wx int, wy int, matrix [][]int) {
	update(ldl, ldd+wy, 1, matrix)
	update(ldl, ldd, -1, matrix)
	update(ldl+wx, ldd+wy, -1, matrix)
	update(ldl+wx, ldd, 1, matrix)
}

func update(x int, y int, d int, matrix [][]int) {
	if x < 0 || x >= len(matrix) || y < 0 || y >= len(matrix) {
		return
	}
	matrix[y][x] += d
}

