var dots [][]int
var cumsum [][]int

func main() {
	tmp := NextIntsLine()
	n, k = tmp[0], tmp[1]
	for i := 0; i < n; i++ {
		strs := NextStringsLine()
		x, _ := strconv.Atoi(strs[0])
		y, _ := strconv.Atoi(strs[1])
		c := rune(strs[2][0])

		if c == 'W' {
			c = 'B'
			y += k
		}
		x %= 2 * k
		y %= 2 * k
		X = append(X, x)
		Y = append(Y, y)
		C = append(C, c)
	}

	for i := 0; i < 2*k; i++ {
		row := make([]int, 2*k)
		dots = append(dots, row)
	}
	for i := 0; i < n; i++ {
		y, x := Y[i], X[i]
		dots[y][x] = 1
	}

	initialize()
	//	fmt.Println(X, Y)
	//	fmt.Println(cumsum)

	ans := -1
	for y := 0; y < k; y++ {
		for x := 0; x < k; x++ {
			tmpans := getSum(y, x, y+(k-1), x+(k-1))
			tmpans += getSum(0, 0, y-1, x-1)
			tmpans += getSum(0, x+(k-1)+1, y-1, 2*k-1)
			tmpans += getSum(y+(k-1)+1, 0, 2*k-1, x-1)
			tmpans += getSum(y+(k-1)+1, x+(k-1)+1, 2*k-1, 2*k-1)
			ans = Max(ans, tmpans)
		}
	}
	fmt.Println(ans)
}

func initialize() {
	for i := 0; i < 2*k; i++ {
		tmp := make([]int, 2*k)
		cumsum = append(cumsum, tmp)
	}

	for y := 0; y < 2*k; y++ {
		for x := 0; x < 2*k; x++ {
			cumsum[y][x] = dots[y][x]
			if y > 0 {
				cumsum[y][x] += cumsum[y-1][x]
			}
			if x > 0 {
				cumsum[y][x] += cumsum[y][x-1]
			}
			if y > 0 && x > 0 {
				cumsum[y][x] -= cumsum[y-1][x-1]
			}
		}
	}
}

func getSum(bottom, left, top, right int) int {
	tmp := []int{bottom, left, top, right}
	for _, t := range tmp {
		if t < 0 || 2*k <= t {
			return 0
		}
	}

	res := cumsum[top][right]
	if bottom > 0 {
		res -= cumsum[bottom-1][right]
	}
	if left > 0 {
		res -= cumsum[top][left-1]
	}
	if bottom > 0 && left > 0 {
		res += cumsum[bottom-1][left-1]
	}
	return res
}

