	if a < b {
		return a
	}
	return b
}

func in(x, y int) bool {
	return 0 <= x && x < 2*K && 0 <= y && y < 2*K
}

func rect(x, y int, g graph) int {
	tx := min(x+K-1, len(g)-1)
	ty := min(y+K-1, len(g)-1)
	if !in(tx, ty) {
		return 0
	}

	nums := g[tx][ty]
	if in(x-1, y-1) {
		nums += g[x-1][y-1]
	}

	if in(x-1, ty) {
		nums -= g[x-1][ty]
	}

	if in(tx, y-1) {
		nums -= g[tx][y-1]
	}
	return nums
}

