			white[yy+K2][xx]++
			white[yy][xx+K2]++
			white[yy+K2][xx+K2]++
		}
	}

	bimos := make([][]int, K4+1)
	wimos := make([][]int, K4+1)
	for i := 0; i <= K4; i++ {
		bimos[i] = make([]int, K4+1)
		wimos[i] = make([]int, K4+1)
	}

	for i := 0; i < K4; i++ {
		for j := 0; j < K4; j++ {
			bimos[i+1][j+1] = bimos[i][j+1] + bimos[i+1][j] - bimos[i][j] + black[i][j]
			wimos[i+1][j+1] = wimos[i][j+1] + wimos[i+1][j] - wimos[i][j] + white[i][j]
		}
	}
	res := 0
	calc2 := func(x1, y1, x2, y2 int, a [][]int) int {
		return a[y2][x2] + a[y1][x1] - a[y2][x1] - a[y1][x2]
	}

	for i := 0; i < K2; i++ {
		for j := 0; j < K2; j++ {
			val := 0
			val += calc2(i + K, j + K, i, j, bimos)
			val += calc2(i + K2, j + K2, i + K, j + K, bimos)
			val += calc2(i + K2, j + K, i + K, j, wimos)
			val += calc2(i + K, j + K2, i, j + K, wimos)
			res = max(res, val)
		}
	}

	fmt.Println(res)
}

