var hopes [2][2001][2001]int

func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(os.Stdout)

	n := getNextInt(scanner)
	k := getNextInt(scanner)

	cmap := map[string]int{
		"W": 0,
		"B": 1,
	}

	for i := 0; i < n; i++ {
		x := getNextInt(scanner) % (k << 1)
		y := getNextInt(scanner) % (k << 1)
		c := getNextString(scanner)
		hopes[cmap[c]][y+1][x+1]++
	}

	for i := 0; i < 2; i++ {
		for y := 0; y <= k<<1; y++ {
			for x := 0; x < k<<1; x++ {
				hopes[i][y][x+1] += hopes[i][y][x]
			}
		}
	}
	for i := 0; i < 2; i++ {
		for x := 0; x <= k<<1; x++ {
			for y := 0; y < k<<1; y++ {
				hopes[i][y+1][x] += hopes[i][y][x]
			}
		}
	}

	ans := 0
	var wb [2][3][3]int

	for y := 0; y < k; y++ {
		for x := 0; x < k; x++ {
			for i := 0; i < 2; i++ {
				wb[i][0][0] = count(i, 0, 0, y, x)
				wb[i][0][1] = count(i, 0, x, y, x+k)
				wb[i][0][2] = count(i, 0, x+k, y, k*2)
				wb[i][1][0] = count(i, y, 0, y+k, x)
				wb[i][1][1] = count(i, y, x, y+k, x+k)
				wb[i][1][2] = count(i, y, x+k, y+k, k*2)
				wb[i][2][0] = count(i, y+k, 0, k*2, x)
				wb[i][2][1] = count(i, y+k, x, k*2, x+k)
				wb[i][2][2] = count(i, y+k, x+k, k*2, k*2)
			}

			for i := 0; i < 2; i++ {
				done := 0
				for yy := 0; yy < 3; yy++ {
					for xx := 0; xx < 3; xx++ {
						done += wb[i^((yy+xx)%2)][yy][xx]
					}
				}

				if ans < done {
					ans = done
				}
			}
		}
	}

	fmt.Fprintln(writer, ans)
	writer.Flush()
}

func count(i, y1, x1, y2, x2 int) int {
	return hopes[i][y2][x2] - hopes[i][y1][x2] - hopes[i][y2][x1] + hopes[i][y1][x1]
}

