func sum(f [][]int, x, y, dx, dy int) int {
	K := len(f)
	var ans int
	if x+dx > K {
		ans += sum(f, 0, y, (x+dx)%K, dy)
		dx = K - x
	}
	if y+dy > K {
		ans += sum(f, x, 0, dx, (y+dy)%K)
		dy = K - y
	}

	x2 := x + dx - 1
	y2 := y + dy - 1

	ans += f[x2][y2]
	if y > 0 {
		ans -= f[x2][y-1]
	}
	if x > 0 {
		ans -= f[x-1][y2]
	}
	if x > 0 && y > 0 {
		ans += f[x-1][y-1]
	}
	return ans
}

func main() {
	defer stdout.Flush()
	n := readInt()
	k := readInt()

	K := 2 * k
	f := make([][]int, K)
	for i := 0; i < K; i++ {
		f[i] = make([]int, K)
	}

	for i := 0; i < n; i++ {
		x := readInt() % (2 * k)
		y := readInt() % (2 * k)
		c := readString()
		if c == "W" {
			y += k
		}
		f[x%K][y%K]++
	}

	for i := 0; i < K; i++ {
		for j := 0; j+1 < K; j++ {
			f[i][j+1] += f[i][j]
		}
	}

	for i := 0; i < K; i++ {
		for j := 0; j+1 < K; j++ {
			f[j+1][i] += f[j][i]
		}
	}

	max := 0
	for i := 0; i < K; i++ {
		for j := 0; j+1 < K; j++ {
			v := sum(f, i, j, k, k) + sum(f, (i+k)%K, (j+k)%K, k, k)
			if max < v {
				max = v
			}
		}
	}

	println(max)
}

