func main() {
	solve(os.Stdin, os.Stdout)
}

func solve(in io.Reader, out io.Writer) {
	var bs = NewBufScanner(in)
	var bw = NewBufWriter(out)
	defer bw.w.Flush()

	line := strings.Split(bs.Scan(), " ")
	N, _ := strconv.Atoi(line[0])
	K, _ := strconv.Atoi(line[1])

	m := make([][]int, 4*K+1)
	sum := make([][]int, 4*K+1)

	for i := 0; i <= 4*K; i++ {
		m[i] = make([]int, 4*K+1)
		sum[i] = make([]int, 4*K+1)
	}

	for i := 0; i < N; i++ {
		line = strings.Split(bs.Scan(), " ")
		x, _ := strconv.Atoi(line[0])
		y, _ := strconv.Atoi(line[1])
		if line[2] == "W" {
			y += K
		}

		m[x%(2*K)][y%(2*K)]++
	}


	for x := 0; x <= 4*K; x++ {
		for y := 0; y <= 4*K; y++ {
			m[x][y] = m[x%(2*K)][y%(2*K)]
		}
	}

	// 2次元累積和
	for i := 0; i <= 4*K; i++ {
		for j := 0; j <= 4*K; j++ {
			sum[i][j] = m[i][j]
			if i > 0 {
				sum[i][j] += sum[i-1][j]
			}
			if j > 0 {
				sum[i][j] += sum[i][j-1]
			}
			if i > 0 && j > 0 {
				sum[i][j] -= sum[i-1][j-1]
			}
		}
	}

	max := 0
	for x := 0; x <= 2*K; x++ {
		for y:= 0; y <= 2*K; y++ {
			tmp := get(x, y, x+K-1, y+K-1, sum)
			tmp += get(x+K, y+K, x+2*K-1, y+2*K-1, sum)
			max = int(math.Max(float64(max), float64(tmp)))
		}
	}

	bw.Printf("%d\n", max)
}

func get(x1, y1, x2, y2 int, sum [][]int) int {
	tmp := sum[x2][y2]
	if x1 > 0 {
		tmp -= sum[x1-1][y2]
	}
	if y1 > 0 {
		tmp -= sum[x2][y1-1]
	}
	if x1 > 0 && y1 > 0 {
		tmp += sum[x1-1][y1-1]
	}
	return tmp
}

