var N, K int
var board [][]int

func max(slice ...int) int {
	sort.Ints(slice)
	return slice[len(slice)-1]
}

func countRegion(y, x int) int {
	limY, limX := y+K-1, x+K-1
	if limY >= len(board) {
		limY = len(board) - 1
	}

	if limX >= len(board[0]) {
		limX = len(board[0]) - 1
	}

	minLimY, minLimX := y-1, x-1
	if minLimY < 0 {
		minLimY = 0
	}
	if minLimY >= len(board) {
		minLimY = len(board) - 1
	}
	if minLimX < 0 {
		minLimX = 0
	}
	if minLimX >= len(board[0])-1 {
		minLimX = len(board[0]) - 1
	}

	return board[limY][limX] - board[limY][minLimX] - board[minLimY][limX] + board[minLimY][minLimX]
}

func main() {
	fmt.Scan(&N, &K)

	board = make([][]int, 2*K+2)
	for i := range board {
		board[i] = make([]int, 2*K+2)
	}

	for i := 0; i < N; i++ {
		var x, y int
		var c string
		fmt.Scan(&x, &y, &c)
		if c == "B" {
			y += K
		}
		board[(y%(2*K))+1][(x%(2*K))+1]++
	}

	for i := range board {
		for j := range board[i] {
			if j+1 < len(board[i]) {
				board[i][j+1] += board[i][j]
			}
		}
	}

	for i := range board {
		for j := range board[i] {
			if i+1 < len(board[i]) {
				board[i+1][j] += board[i][j]
			}
		}
	}

	ans := 0
	for i := 1; i < len(board)-1; i++ {
		for j := 1; j < len(board[i])-1; j++ {
			count := countRegion(i, j)
			count += countRegion(i+K, j+K)
			count += countRegion(i+K, j-K)
			count += countRegion(i-K, j+K)
			count += countRegion(i-K, j-K)
			// fmt.Println(i, j, count)
			ans = max(ans, count)
		}
	}

	// for i := len(board) - 1; i >= 0; i-- {
	// 	fmt.Println(board[i])
	// }

	fmt.Println(ans)
}

