		for j := range board[i] {
			if j+1 < len(board[i]) {
				board[i][j+1] += board[i][j]
			}
		}
	}

	for i := range board {
		for j := range board[i] {
			if i+1 < len(board[i]) {
				board[i+1][j] += board[i][j]
			}
		}
	}

	ans := 0
	for i := 0; i < len(board)-K; i++ {
		for j := 0; j < len(board[i])-K; j++ {
			count := 0
			if i > 0 && j > 0 {
				count += board[i+K-1][j+K-1] - board[i+K-1][j-1] - board[i-1][j+K-1] + board[i-1][j-1] //middle
			} else {
				count += board[i+K-1][j+K-1]
			}

			if i > 0 && j > 0 {
				count += board[i-1][j-1] //lower left
			}

			if j > 0 {
				count += board[k-1][j-1] - board[i+K-1][j-1] //upper left
			}

			if i > 0 {
				count += board[i-1][k-1] - board[i-1][j+K-1] //lower right
			}

			if i+K-1 < len(board) && j+K-1 < len(board[i]) {
				count += board[k-1][k-1] - board[k-1][j+K-1] - board[i+K-1][k-1] + board[i+K-1][j+K-1] //upper right
			}

			ans = max(ans, count)
		}
	}

	fmt.Println(ans)
}

