var N, K int
var board [][]int

func max(slice ...int) int {
	sort.Ints(slice)
	return slice[len(slice)-1]
}

func countRegion(y, x int) int {
	limY, limX := y+K-1, x+K-1
	if limY >= 2*K {
		limY = 2*K - 1
	}

	if limX >= 2*K {
		limX = 2*K - 1
	}

	return board[limY][limX] - board[limY][x-1] - board[y-1][limX] + board[y-1][x-1]
}

func main() {
	fmt.Scan(&N, &K)

	k := 2 * K
	board = make([][]int, k+1)
	for i := range board {
		board[i] = make([]int, k+1)
	}

	for i := 0; i < N; i++ {
		var x, y int
		var c string
		fmt.Scan(&x, &y, &c)
		if c == "B" {
			x += K
		}
		board[y%k+1][x%k+1]++
	}

	for i := range board {
		for j := range board[i] {
			if j+1 < len(board[i]) {
				board[i][j+1] += board[i][j]
			}
		}
	}

	for i := range board {
		for j := range board[i] {
			if i+1 < len(board[i]) {
				board[i+1][j] += board[i][j]
			}
		}
	}

	ans := 0
	for i := 1; i < len(board); i++ {
		for j := 1; j < len(board[i]); j++ {
			count := countRegion(i, j)
			if i+K < len(board) && j+K < len(board[j]) {
				count += countRegion(i+K, j+K)
			}

			if i+K < len(board) {
				count += countRegion(i+K, j)
			}

			if j+K < len(board[i]) {
				count += countRegion(i, j+K)
			}

			if i > 0 && j > 0 {
				count += board[i-1][j-1]
			}

			ans = max(ans, count)
		}
	}

	fmt.Println(ans)
}

