func initialize() {
	for i := 0; i < 2*k; i++ {
		tmp := make([]int, 2*k)
		cumsum = append(cumsum, tmp)
	}

	for y := 0; y < 2*k; y++ {
		for x := 0; x < 2*k; x++ {
			cumsum[y][x] = dots[y][x]
			if y > 0 {
				cumsum[y][x] += cumsum[y-1][x]
			}
			if x > 0 {
				cumsum[y][x] += cumsum[y][x-1]
			}
			if y > 0 && x > 0 {
				cumsum[y][x] -= cumsum[y-1][x-1]
			}
		}
	}
}

/*
top < 0 || right < 0 -> return 0
bottom >= 2*k || left >= 2*k -> return 0

左下:
x < 0 -> x = 0
y < 0 -> y = 0
右上:
x >= 2*k -> x = 2*k-1
y >= 2*k -> y = 2*k-1
*/
func getSum(bottom, left, top, right int) int {
	//	tmp := []int{bottom, left, top, right}
	//	for _, t := range tmp {
	//		if t < 0 || 2*k <= t {
	//			return 0
	//		}
	//	}
	if top < 0 || right < 0 || bottom >= 2*k || left >= 2*k {
		return 0
	}

	if left < 0 {
		left = 0
	}
	if bottom < 0 {
		bottom = 0
	}
	if right >= 2*k {
		right = 2*k - 1
	}
	if top >= 2*k {
		top = 2*k - 1
	}

	res := cumsum[top][right]
	if bottom > 0 {
		res -= cumsum[bottom-1][right]
	}
	if left > 0 {
		res -= cumsum[top][left-1]
	}
	if bottom > 0 && left > 0 {
		res += cumsum[bottom-1][left-1]
	}
	return res
}

