func solve(in io.Reader, out io.Writer) {
	var bs = NewBufScanner(in)
	var bw = NewBufWriter(out)
	defer bw.w.Flush()

	line := strings.Split(bs.Scan(), " ")
	N, _ := strconv.Atoi(line[0])
	K, _ := strconv.Atoi(line[1])

	pList := make([]Place, 0, N)
	for i := 0; i < N; i++ {
		line = strings.Split(bs.Scan(), " ")
		x, _ := strconv.Atoi(line[0])
		y, _ := strconv.Atoi(line[1])
		c := line[2]
		pList = append(pList, NewPlace(x, y, c))
	}

	max := 0
	for i := 0; i < K; i++ {
		for j := 0; j < K; j++ {
			count := 0
			for _, p := range pList {
				t := (p.x - i) / K + (p.y - j) / K
				dx := p.x - i
				dy := p.y - j
				c := ""
				if t % 2 == 1 {
					c = "W"
				} else {
					c = "B"
				}
				if dx < 0 && dy < 0 {
					c = "W"
				} else if dx < 0 || dy < 0 {
					c = "B"
				}
				if p.c == c {
					count++
				}
			}
			if max < count {
				max = count
			}
			if max < (N - count) {
				max = N - count
			}
		}
	}
	bw.Printf("%d\n", max)
