type cumulativesum2d struct{ d [][]int } //
func NewCumulativesum2d(raw [][]int) *cumulativesum2d {
	cs := new(cumulativesum2d)
	cs.build(raw)
	return cs
}
func (cs *cumulativesum2d) build(a [][]int) {
	h, w := len(a), len(a[0])
	cs.d = make([][]int, h+1)
	for i := range cs.d {
		cs.d[i] = make([]int, w+1)
	}
	for i := 1; i < h+1; i++ {
		for j := 1; j < w+1; j++ {
			cs.d[i][j] = cs.d[i-1][j] + cs.d[i][j-1] - cs.d[i-1][j-1] + a[i-1][j-1]
		}
	}
}
func (cs *cumulativesum2d) Query(x1, x2, y1, y2 int) int {
	return cs.d[y2][x2] - cs.d[y1][x2] - cs.d[y2][x1] + cs.d[y1][x1]
}

func solve() {
	n, k := ri(), ri()
	s := make([][]int, 2*k)
	for i := range s {
		s[i] = make([]int, 2*k)
	}
	for i := 0; i < n; i++ {
		x, y, c := ri(), ri(), rs()
		if c == "W" {
			y += k
		}
		x %= 2 * k
		y %= 2 * k
		s[y][x]++
	}
	c := NewCumulativesum2d(s)
	maxScore := 0
	for i := 0; i+k <= 2*k; i++ {
		for j := 0; j+k <= 2*k; j++ {
			score := 0
			score += c.Query(i, i+k, j, j+k)
			score += c.Query(0, i, 0, j)
			score += c.Query(i+k, 2*k, 0, j)
			score += c.Query(0, i, j+k, 2*k)
			score += c.Query(i+k, 2*k, j+k, 2*k)
			chmax(&maxScore, score)
		}
	}
	pln(maxScore)
}

