	fmt.Scan(&N, &K)

	poss := make([]pos_t, N)
	for i := 0; i < N; i++ {
		var x, y int
		var c string
		fmt.Scan(&x, &y, &c)
		if c == "B" {
			x += K
		}
		poss[i].x = x % (2 * K)
		poss[i].y = y % (2 * K)
	}

	sums := make([][]int, 2*K)
	for i := 0; i < 2*K; i++ {
		sums[i] = make([]int, 2*K)
		for j := 0; j < 2*K; j++ {
			sums[i][j] = 0
		}
	}

	for k := 0; k < N; k++ {
		x := poss[k].x
		y := poss[k].y
		sums[x][y] += 1
	}

	for i := 0; i < 2*K; i++ {
		for j := 0; j < 2*K-1; j++ {
			sums[i][j+1] += sums[i][j]
		}
	}

	for i := 0; i < 2*K; i++ {
		for j := 0; j < 2*K-1; j++ {
			sums[j+1][i] += sums[j][i]
		}
	}

	max_val := 0
	for i := 0; i < K; i++ {
		for j := 0; j < K; j++ {
			count1 := 0
			count2 := 0
			for k := 0; k < N; k++ {
				x := poss[k].x
				y := poss[k].y
				if (x < i && y < j) || (i <= x && x < K+i && j <= y && y < K+j) || (K+i <= x && y < j) ||
					(x < i && K+j <= y) || (K+i <= x && K+j <= y) {
					count1++
				} else {
					count2++
				}
				max_val = max(max_val, max(count1, count2))
			}
		}
	}

	fmt.Println(max_val)
}

