	y = make([]int, N)
	c = make([]string, N)

	for i := 0; i < N; i++ {
		fmt.Scanf("%d %d %s", &x[i], &y[i], &c[i])
	}

	max := 0
	for i := 0; i < K; i++ {
		for j := 0; j < K; j++ {
			tmp := 0
			for k := 0; k < N; k++ {
				dx := (x[k] - x[0] + i) / K
				dy := (y[k] - y[0] + j) / K
				if dx%2 == 0 {
					if dy%2 == 0 { // 同じ
						if c[k] == "W" {
							tmp++
						}
					} else { // 違う
						if c[k] == "B" {
							tmp++
						}
					}
				} else {
					if dy%2 == 0 { // 違う
						if c[k] == "B" {
							tmp++
						}
					} else { // 同じ
						if c[k] == "W" {
							tmp++
						}
					}
				}
			}
			max = Max(max, Max(N-tmp, tmp))
		}
	}

	fmt.Println(max)
}

