let calPattern = (arr, K, geta = 0) => {
  let count = [0, 0]
  arr.map((r, i) => {
    if (!r) {
      return
    }
    fl = Math.ceil((i + geta) / K) % 2
    count[fl] += r
  })
  return count
}
// Calc
// arr => K
// max => K -> K^2
let getMost = (arr1, arr2, end, K) => {
  let max = 0
  for (let startPoint = 0; startPoint < end; startPoint++) {
    let r1 = calPattern(arr1, K, startPoint)
    let r2 = calPattern(arr2, K, startPoint)
    max = Math.max(max, r1[0] + r2[1], r1[1] + r2[0])
  }
  return max
}

function solve(input) {
  const [head, ...wish] = input.split("\n")
  const [N, K] = head.split(" ")
  const xWGroup = []
  const xBGroup = []
  const yWGroup = []
  const yBGroup = []

  // Calc: N
  wish.map((w) => {
    const [_x, _y, color] = w.split(" ")
    const x = Number(_x)
    const y = Number(_y)
    if (color == "W") {
      xWGroup[x] = xWGroup[x] ? xWGroup[x] + 1 : 1
      yWGroup[y] = yWGroup[y] ? yWGroup[y] + 1 : 1
    } else {
      xBGroup[x] = xBGroup[x] ? xBGroup[x] + 1 : 1
      yBGroup[y] = yBGroup[y] ? yBGroup[y] + 1 : 1
    }
  })
  // console.log(xWGroup, xBGroup, yWGroup, yBGroup)
  // Calc: max -> K
  const xMax = Math.max(xWGroup.length - 1, xBGroup.length - 1)
  const yMax = Math.max(yWGroup.length - 1, yBGroup.length - 1)

  const xMin = Math.min(
    xWGroup.findIndex((a) => !!a),
    xBGroup.findIndex((a) => !!a)
  )
  const yMin = Math.min(
    yWGroup.findIndex((a) => !!a),
    yBGroup.findIndex((a) => !!a)
  )
  // most bad -> 0, 1000000 / 0, 1000000
  // console.log(xMin, xMax, yMin, yMax)
  const calcEnd = Math.max(Math.min(K, xMax - xMin, yMax - yMin), 1)
  return Math.min(
    getMost(xWGroup, xBGroup, calcEnd, K),
    getMost(yWGroup, yBGroup, calcEnd, K)
  )
}

