struct Cell{
    long black, white;
    ref long opIndex(char c)
    {
        return c=='B'?black:white;
    }
}
void main()
{
    auto N = scanElem;
    auto K = scanElem;

    auto grid = new Grid!Cell(K*2,K);
    long countWhite;

    Data2 calcIndex(long x, long y){
        if(x<0) x = K-x;
        if(y<0) y = K-y;
        return Data2((x/K+y/K)%2 * K + x%K, y%K);
    }
    foreach(i; 0..N)
    {
        auto x = scanElem;
        auto y = scanElem;
        auto c = scanElem!char;
        if(c=='W')countWhite++;

        grid[calcIndex(x, y)][c]++;
    }

    auto sumGrid = new Grid!Cell(K*3,K*3);
    foreach(y; 0..K*3)
    {
        foreach(x; 0..K*3)
        {
            sumGrid[x, y] = grid[calcIndex(x,y)];
            if(x!=0){
                sumGrid[x, y].black += sumGrid[x-1, y].black;
                sumGrid[x, y].white += sumGrid[x-1, y].white;
            }
            if(y!=0){
                sumGrid[x, y].black += sumGrid[x, y-1].black;
                sumGrid[x, y].white += sumGrid[x, y-1].white;
            }
            if(x!=0&&y!=0){
                sumGrid[x, y].black -= sumGrid[x-1, y-1].black;
                sumGrid[x, y].white -= sumGrid[x-1, y-1].white;
            }
        }
    }
    long res;
    foreach(y; K-1..K*3)
    {
        foreach(x; K-1..K*3)
        {
            auto b = sumGrid[x, y].black;
            auto w = sumGrid[x, y].white;
            if(x-K>=0){
                b -= sumGrid[x-K, y].black;
                w -= sumGrid[x-K, y].white;
            }

            if(y-K>=0)
            {
                b -= sumGrid[x, y-K].black;
                w -= sumGrid[x, y-K].white;
            }

            if(x-K>=0&&y-K>=0)
            {
                b += sumGrid[x-K, y-K].black;
                w += sumGrid[x-K, y-K].white;
            }
            res = max(res, b+(countWhite-w));
            // if(b+(countWhite-w)==3)
            // {
            //     print("b: ", b);
            //     print(" w: ", w);
            //     print(" x: ", x);
            //     print(" y: ", y);
            //     print("\n");
            // }
        }
    }
    // println(grid);
    // println(sumGrid);
    writeln(res);
}

enum MOD=pow(10,9)+7L;

class GridIter(T){
    private const T[] grid;
    size_t count;

    this(T[] g)
    {
        grid = g;
    }

    void popFront(){
        count++;
    }
    bool empty(){
        return count>=grid.length;
    }
    T front(){
        return grid[count];
    }
}
class Grid(T){
    T[] grid;
    size_t width, height;

    private this(){

    }

    this(size_t w, size_t h)
    {
        width = w;
        height = h;
        grid.length = width*height;
    }

    GridIter!T iter(){
        return new GridIter!T(grid);
    }

    ref T opIndex(size_t x, size_t y)
    {
        return grid[x+width*y];
    }
    ref T opIndex(E)(E e)
        if(
            isIntegral!(typeof(e.x)) &&
            isIntegral!(typeof(e.y)))
    {
        return this[e.x, e.y];
    }

    Grid!T opIndex(size_t[2] r1, size_t[2] r2)
    {
        auto res = new Grid!T();
        auto startOffset = r1[0] + r2[0]*width;
        auto endOffset = r1[1] + (r2[1] - 1)*width;
        res.grid = grid[startOffset .. endOffset];

        res.width = r1[1] - r1[0];
        res.height = r2[1] - r2[0];
        return res;
    }

    Grid!T opIndex(size_t[2] r1, size_t j) { return opIndex(r1, [j, j+1]); }
    Grid!T opIndex(size_t i, size_t[2] r2) { return opIndex([i, i+1], r2); }

    size_t[2] opSlice(size_t dim)(size_t start, size_t end)
    if (dim == 0 || dim == 1)
    in { assert(start >= 0 && end <= this.opDollar!dim); }
    body{
        return [start, end];
    }

    size_t opDollar(size_t dim : 0)() { return width; }
    size_t opDollar(size_t dim : 1)() { return height; }

    override string toString(){
        string res = "\n";
        foreach_reverse(line; 0..height)
        {
            res ~= grid[line*width..(line+1)*width].to!string ~ '\n';
        }
        return res;
    }
}

