void main()
{
  int n, k; readV(n, k);
  int[] x, y; string[] s; readM(n, x, y, s);

  foreach (i; 0..n) if (s[i] == "W") x[i] += k;
  auto k2 = k*2;
  x[] %= k2; y[] %= k2;

  auto c = new int[][](k2*2+1, k2*2+1);
  auto setImos(int x, int y)
  {
    c[y][x]++;
    c[y][x+k]--;
    c[y+k][x]--;
    c[y+k][x+k]++;
  }

  foreach (xi, yi; lockstep(x, y)) {
    setImos(xi+1, yi+1);
    setImos(xi+k+1, yi+k+1);
  }

  foreach (i; 0..k2*2+1)
    foreach (j; 1..k2*2+1)
      c[i][j] += c[i][j-1];
  foreach (j; 0..k2*2+1)
    foreach (i; 1..k2*2+1)
      c[i][j] += c[i-1][j];

  auto d = new int[][](k2, k2);
  foreach (i; 0..k2*2)
    foreach (j; 0..k2*2)
      d[i%k2][j%k2] += c[i][j];

  auto r = 0;
  foreach (i; 0..k2)
    foreach (j; 0..k2)
      r = max(r, d[i][j]);

  writeln(r);
}

