auto parse( Range )( Range input )
if( isInputRange!Range && is( ElementType!Range == string ) )
{
	auto nk = input.front.split.to!( int[] );
	auto xycs = new Tuple!( int, int, char )[ nk[ 0 ] ];
	foreach( ref xyc; xycs )
	{
		input.popFront;
		auto ts = input.front.split.to!( char[][] );
		xyc = tuple( ts[ 0 ].to!( int ), ts[ 1 ].to!( int ), ts[ 2 ].front );
	}
	return tuple( nk[ 1 ], xycs );
}

auto solve( int k, Tuple!( int, int, char )[] xycs )
{
	auto kk = 2 * k;

	// 各希望を市松模様4セットの中にプロット
	auto bss = new int[][]( 1 + kk * 2, 1 + kk * 2 );
	auto wss = new int[][]( 1 + kk * 2, 1 + kk * 2 );
	foreach( xyc; xycs )
	{
		auto x = xyc[ 0 ] % kk;
		auto y = xyc[ 1 ] % kk;
		if( xyc[ 2 ] == 'B' )
		{
			bss[ 1 + x      ][ 1 + y      ]++;
			bss[ 1 + x + kk ][ 1 + y      ]++;
			bss[ 1 + x      ][ 1 + y + kk ]++;
			bss[ 1 + x + kk ][ 1 + y + kk ]++;
		}
		else
		{
			wss[ 1 + x      ][ 1 + y      ]++;
			wss[ 1 + x + kk ][ 1 + y      ]++;
			wss[ 1 + x      ][ 1 + y + kk ]++;
			wss[ 1 + x + kk ][ 1 + y + kk ]++;
		}
	}

	// 二次元累積和表に変換
	for( auto x = 1; x < bss.length; x++ )
	{
		for( auto y = 1; y < bss[ x ].length; y++ )
		{
			bss[ x ][ y ] += bss[ x - 1 ][ y ] + bss[ x ][ y - 1 ] - bss[ x - 1 ][ y - 1 ];
			wss[ x ][ y ] += wss[ x - 1 ][ y ] + wss[ x ][ y - 1 ] - wss[ x - 1 ][ y - 1 ];
		}
	}

	// 市松模様をずらして希望を叶えられる最大数を検索
	auto ans = 0;
	for( auto x = kk; x < bss.length; x++ )
	{
		for( auto y = kk; y < bss[ x ].length; y++ )
		{
			auto bc = bss[ x      ][ y      ] - bss[ x - k  ][ y      ] - bss[ x      ][ y - k  ] + bss[ x - k  ][ y - k  ]
			        + bss[ x - k  ][ y - k  ] - bss[ x - kk ][ y - k  ] - bss[ x - k  ][ y - kk ] + bss[ x - kk ][ y - kk ];
			auto wc = wss[ x - k  ][ y      ] - wss[ x - kk ][ y      ] - wss[ x - k  ][ y - k  ] + wss[ x - kk ][ y - k  ]
			        + wss[ x      ][ y - k  ] - wss[ x      ][ y - kk ] - wss[ x - k  ][ y - k  ] + wss[ x - k  ][ y - kk ];
			ans = max( ans, bc + wc );
		}
	}
	return ans;
}

