void main()
{
  int n, k; readV(n, k);
  int[] x, y; string[] s; readM(n, x, y, s);

  foreach (i; 0..n) if (s[i] == "W") x[i] += k;
  auto k2 = k*2;
  x[] %= k2; y[] %= k2;

  auto c = new int[][](k2*2, k2*2);
  foreach (xi, yi; lockstep(x, y)) {
    auto xs1 = max(0, xi-k+1), ys1 = max(0, yi-k+1);
    c[ys1][xs1]++;
    c[ys1][xi+1]--;
    c[yi+1][xs1]--;
    c[yi+1][xi+1]++;
    c[yi+1][xi+1]++;
    c[yi+1+k][xi+1]--;
    c[yi+1][xi+1+k]--;
    c[yi+1+k][xi+1+k]++;
  }

  foreach (i; 0..k2)
    foreach (j; 1..k2)
      c[i][j] += c[i][j-1];
  foreach (j; 0..k2)
    foreach (i; 1..k2)
      c[i][j] += c[i-1][j];

  auto r = 0;
  foreach (i; 0..k2)
    foreach (j; 0..k2)
      r = max(r, c[i][j]);

  writeln(r);
}

