    Data2 calcIndex(long x, long y){
        if(x<0) x = K-x;
        if(y<0) y = K-y;
        return Data2((x/K+y/K)%2 * K + x%K, y%K);
    }
    foreach(i; 0..N)
    {
        auto x = scanElem;
        auto y = scanElem;
        auto c = scanElem!char;
        if(c=='W'){
            x+=K;
        }

        grid[calcIndex(x, y)]++;
    }

    auto sumGrid = new Grid!long(K*3,K*3);
    foreach(y; 0..K*3)
    {
        foreach(x; 0..K*3)
        {
            sumGrid[x, y] = grid[calcIndex(x,y)];
            if(x!=0){
                sumGrid[x, y] += sumGrid[x-1, y];
            }
            if(y!=0){
                sumGrid[x, y] += sumGrid[x, y-1];
            }
            if(x!=0&&y!=0){
                sumGrid[x, y] -= sumGrid[x-1, y-1];
            }
        }
    }
    long res;
    foreach(y; K-1..K*3)
    {
        foreach(x; K-1..K*3)
        {
            auto b = sumGrid[x, y];
            if(x-K>=0){
                b -= sumGrid[x-K, y];
            }

            if(y-K>=0)
            {
                b -= sumGrid[x, y-K];
            }

            if(x-K>=0&&y-K>=0)
            {
                b += sumGrid[x-K, y-K];
            }
            res = max(res, b);
        }
    }
    writeln(res);
}

