def solve(n, k, inputs_):
    inputs = list(inputs_)
    inputs = [[int(i[0]) % (2 * k), int(i[1]) % (2 * k), i[2]] for i in inputs]
    points = [[i[0], i[1] + k if i[2] == 'W' else 0] for i in inputs]
    ans = 0
    for x in range(k):
        for y in range(k):
            interim_ans = 0
            for p in points:
                p = [(p[0] - x) % (2 * k), (p[1] - y) % (2 * k)]
                condition = (0 <= p[0] <= (k - 1) and 0 <= p[1] <= (k - 1)) or (k <=  p[0] <=  (2 * k - 1) and k <= p[1] <= (2 * k - 1))
                if condition:
                    interim_ans = interim_ans + 1
            if interim_ans > ans:
                ans = interim_ans
    return ans

