def det(x,K):
  return x % (2*K) in range(K)

def isblack(x,y,K):
  return (det(x,K) and det(y,K)) or (not (det(x,K) or det(y,K)))

def solve():
  raw = list(map(int,input().split(" ")))
  N = raw[0]
  K = raw[1]
  x=[]
  y=[]
  c=[]

  gain={}

  for i in range(N):
    raw = list(input().split(" "))
    x = int(raw[0])
    y = int(raw[1]) % (2*K)
    c = raw[2].strip('\r\n')
    if c == 'W':
      x = x + K
    x = x % (2*K)

    if (x,y) in gain:
      gain[(x,y)] = gain[(x,y)] + 1
    else:
      gain[(x,y)] = 1

  score = 0

  for i in range(2*K):
    for j in range(2*K):
      newscore = 0
      for keys in gain:
        k,l = keys
        if isblack(k-i,l-j,K):
          newscore = newscore + gain[(k,l)]
      score = max(score,newscore)

  return score

