def cumulativeSum(table):
#数値からなる2次元配列を受け取る:NxMのマトリックスでなければならない
#左上[0][0]要素から開始する累積和の2次元配列を返却する
#もとのtableが変更され、かつ返却される（副作用がある）ことに注意

  N = len(table)
  M = len(table[0])
  for i in range(N):
    for j in range(M):
      if i == 0:
        if j!=0:
          table[i][j] = table[i][j] + table[i][j-1]
      else:
        if j == 0:
          table[i][j] = table[i][j] + table[i-1][j]
        else:
          table[i][j] = table[i][j] + table[i][j-1] + table[i-1][j] - table[i-1][j-1]
  return table

def calcSum(i1,j1,i2,j2,ctable):
  #2つの座標と計算済み2次元累積和テーブルを受け取って、2つの座標によってつくられる長方形内の和を返す。副作用なし。
  #i1
  #j1
  #i2
  #j2
  I1 = min(i1,i2)
  J1 = min(j1,j2)
  I2 = max(i1,i2)
  J2 = max(j1,j2)

  A=0
  B=0
  C=0
  if J1 != 0:
    A = ctable[I2][J1-1]
  if I1 != 0 :
    B = ctable[I1-1][J2]
  if I1 != 0 and J1 != 0:
    C = ctable[I1-1][J1-1]

  return ctable[I2][J2] - A - B + C

def getIntervals(i,K):
  #0から2K-1の間のiとKを受け取る。区間とパリティのペアを返す。
  if i == 0:
    return [(0,K-1,0),(K,2*K-1,1)]
  elif i < K:
    return [(0,i-1,1),(i,i+K-1,0),(i+K,2*K-1,1)]
  elif i == K:
    return [(0,K-1,1),(K,2*K-1,0)]
  else:
    return [(0,i-K-1,0),(i-K,i-1,1),(i,2*K-1,0)]

def bTuples(i,j,K):
  #黒領域の左上の座標およびKの値を入力すると、calcSumに与えるべき座標値をtupleのリストとして返す。副作用なし。
  list = []
  xlist = getIntervals(i,K)
  ylist = getIntervals(j,K)

  for x in xlist:
    for y in ylist:
      i1,i2,px=x
      j1,j2,py=y
      if (px + py) % 2 == 0:
        list.append((i1,j1,i2,j2))

  return list

def solve():
  raw = list(map(int,input().split(" ")))
  N = raw[0]
  K = raw[1]

  length = 2*K
  gain=[[0 for _ in range(length)] for _ in range(length)]
