def count_up(y1, x1, y2, x2):
    global acc, l
    if y1 >= l or x1 >= l or y2 < 0 or x2 < 0:
        return 0
    y2 = min(y2 + 1, l)
    x2 = min(x2 + 1, l)
    ret = acc[y2][x2]
    if y1 > 0:
        ret -= acc[y1][x2]
    if x1 > 0:
        ret -= acc[y2][x1]
    if y1 > 0 and x1 > 0:
        ret += acc[y1][x1]
    return  ret

def main():
    global acc, k, l
    n, k = map(int, sys.stdin.readline().split())
    xycs = (map(lambda x: int(x) if x != 'B' and x != 'W' else x,
                 line.split()) for line in sys.stdin.readlines())

    l = k * 2
    yxs = (((y + k) % l, x % l) if c == 'W' else (y % l, x % l) for x, y, c in xycs)

    acc = [[0] * (l + 1) for _ in range(l + 1)]
    for y, x in yxs:
        acc[y + 1][x + 1] += 1
    for j in range(l):
        for i in range(l):
            acc[j + 1][i + 1] += acc[j + 1][i] + acc[j][i + 1] - acc[j][i]

    max_cnt = 0
    for j in range(k):
        for i in range(k):
            cnt = count_up(j, i, j + k - 1, i + k - 1) + count_up(j - k, i - k, j - 1, i - 1) + count_up(j - k, i + k, j - 1, i + l - 1) + count_up(j + k, i - k, j + l - 1, i - 1) + count_up(j + k, i + k, j + l - 1, i + l - 1)
            max_cnt = max(max_cnt, cnt)

