            if 0 <= offx-1:
                tot -= black[offx-1][offy-1+K]
            if 0 <= offy-1:
                tot -= black[offx-1+K][offy-1]
            if 0 <= offx-1 and 0 <= offy-1:
                tot += black[offx-1][offy-1]
            # 領域6
            if offx+K < 2*K:
                tot += white[-1][offy-1+K]
                tot -= white[offx-1+K][offy-1+K]
                if 0 <= offy-1:
                    tot -= white[-1][offy-1]
                    tot += white[offx-1+K][offy-1]
            # 領域7
