class RectangleSum(object):
    def __init__(self, dat, H, W):
        self.H = H
        self.W = W
        self.sum = [[0 for _ in range(W)] for _ in range(H)]
        for y in range(H):
            for x in range(W):
                self.sum[y][x] = dat[y][x]
                if y > 0:
                    self.sum[y][x] += self.sum[y - 1][x]
                if x > 0:
                    self.sum[y][x] += self.sum[y][x - 1]
                if y > 0 and x > 0:
                    self.sum[y][x] -= self.sum[y - 1][x - 1]

    def get(self, left, top, right, buttom):
        val = self.sum[buttom][right]
        if left > 0:
            val -= self.sum[buttom][left - 1]
        if top > 0:
            val -= self.sum[top - 1][right]
        if left > 0 and top > 0:
            val += self.sum[top - 1][left - 1]
        return val


