    solve(N, K, X, Y, C)

def solve(N, K, X, Y, C):
    M = np.zeros((K*2+1, K*4), dtype=np.int64)
    for x, y, c in zip(X, Y, C):
        if c:
            x += K
        x %= 2*K
        y %= 2*K
        if x >= K and y >= K:
            x -= K
            y -= K
        elif y >= K:
            y -= K
            x += K
        M[y, x] += 1
        M[y, (x+2*K)%(4*K)] += 1
        M[y+K, x+K] += 1
        M[y+K, (x+3*K)%(4*K)] += 1
        if y == 0:
            M[2*K, x] += 1
            M[2*K, (x+2*K)%(4*K)] += 1
    for y in range(2*K):
        for x in range(4*K):
            M[y+1, x] += M[y, x]
    for y in range(2*K+1):
        for x in range(4*K-1):
            M[y, x+1] += M[y, x]
    ans = max([M[y+K, x+K]+M[y, x]-M[y+K, x]-M[y, x+K] for y in range(K+1) for x in range(2*K+1)])
    print(ans)

