class Checkered:

    def __init__(self,x,y,k):
        self.x=x
        self.y=y
        self.k=k

    def getColor(self,x,y):
        """
        return 1:black 0:white
        """
        if self.x==x:
            dif = abs(y-self.y)
            color = math.floor(dif/self.k)%2
            if y>=self.y:
                if color==0:
                    return 1
                else:
                    return 0
            else:
                if color==0:
                    return 0
                else:
                    return 1
        elif self.y==y:
            dif = abs(x-self.x)
            color = math.floor(dif/self.k)%2
            if x>=self.x:
                if color==0:
                    return 1
                else:
                    return 0
            else:
                if color==0:
                    return 0
                else:
                    return 1
        else:
            mid = self.getColor(self.x,y)
            dif = abs(x-self.x)
            color = math.floor(dif/self.k)%2
            if mid == 1:
                if color==0:
                    return 1
                else:
                    return 0
            else:
                if color==0:
                    return 0
                else:
                    return 1

