fn imos(v: &mut Vec<Vec<i32>>, lb: (usize, usize), rt: (usize, usize)) {
    v[lb.0][lb.1] += 1;
    v[lb.0][rt.1] -= 1;
    v[rt.0][lb.1] -= 1;
    v[rt.0][rt.1] += 1;
}

fn solve(k: usize, cells: Vec<(usize, usize, char)>) -> usize {

    let cs = cells.iter().map(|&(x, y, c)| {
        if c == 'B' {
            (x%(2*k),y%(2*k))
        } else {
            (x%(2*k), (y+k)%(2*k))
        }
    });

    let mut v = vec![vec![0; 2*k+1]; 2*k+1];

    for (x,y) in cs {
        if (x<k && y<k) || (k<=x && k<=y) {
            let x = x%k; let y = y%k;

            imos(&mut v, (0, 0), (x+1, y+1)); // left bottom
            imos(&mut v, (x+k+1, 0), (2*k, y+1)); // right bottom
            imos(&mut v, (0, y+k+1), (x+1, 2*k)); // left top
            imos(&mut v, (x+k+1, y+k+1), (2*k, 2*k)); // right top
            imos(&mut v, (x+1, y+1), (x+k+1, y+k+1)); // center
        } else {
            let x = x%k; let y = y%k;

            imos(&mut v, (x+1, 0), (x+k+1, y+1)); // bottom
            imos(&mut v, (0, y+1), (x+1, y+k+1)); // left
            imos(&mut v, (x+k+1, y+1), (2*k, y+k+1)); // right
            imos(&mut v, (x+1, y+k+1), (x+k+1, 2*k)); // top
        }
    }

    for y in 0..(2*k+1) {
        for x in 1..(2*k+1) {
            let x = x as usize; let y = y as usize;
            v[x][y] += v[x-1][y];
        }
    }

    for x in 0..(2*k+1) {
        for y in 1..(2*k+1) {
            let x = x as usize; let y = y as usize;
            v[x][y] += v[x][y-1];
        }
    }

    let mut max = 0;
    for x in 0..(2*k) {
        for y in 0..(2*k) {
            let x = x as usize; let y = y as usize;
            if max < v[x][y] {
                max = v[x][y];
            }
        }
    }

    max as usize
}

fn main() {
    let (n, k) = parse_line!(usize, usize);

    println!("{}", solve(k, (0..n).map(|_| {
        let (x,y,c) = parse_line!(usize, usize, String);
        (x,y,c.chars().next().unwrap())
    }).collect()));
}

