fn solve() {
    let (n,k) = get!(usize, usize);
    let xyc = get!(usize, usize, String; n);

    let (white, black): (Vec<_>, Vec<_>) = xyc.into_iter()
        .map(|(x,y,c)| (x,y,c.chars().next().unwrap()=='W'))
        .map(|(x,y,c)| (x%(2*k),y%(2*k),c))
        .map(|(x,y,c)| if x>=k && y>=k {
            (x-k,y-k,c)
        } else if x<k && y>=k {
            (x+k,y-k,c)
        } else {
            (x,y,c)
        })
        .partition(|&(x,y,c)| x<k);
    let black = black.into_iter().map(|(x,y,c)| (x-k,y,c)).collect::<Vec<_>>();

    let mut wa = vec![vec![None; k];k];
    let mut ba = vec![vec![None; k];k];
    for (x,y,c) in white {
        if wa[x][y].is_none() {
            wa[x][y] = Some((0,0));
        }
        if let Some(v) = wa[x][y].as_mut() {
            if c {
                (*v).0 += 1;
            } else {
                (*v).1 += 1;
            }
        }
    }
    for (x,y,c) in black {
        if ba[x][y].is_none() {
            ba[x][y] = Some((0,0));
        }
        if let Some(v) = ba[x][y].as_mut() {
            if c {
                (*v).0 += 1;
            } else {
                (*v).1 += 1;
            }
        }
    }
    let mut wsums = vec![vec![vec![0;2];k+1];k+1];
    let mut bsums = vec![vec![vec![0;2];k+1];k+1];
    for i in 0..k {
        for j in 0..k {
            if let Some((w,b)) = wa[i][j] {
                wsums[i+1][j+1][1] = wsums[i+1][j][1]+w;
                wsums[i+1][j+1][0] = wsums[i+1][j][0]+b;
            } else {
                for l in 0..2 {
                    wsums[i+1][j+1][l] = wsums[i+1][j][l];
                }
            }
            if let Some((w,b)) = ba[i][j] {
                bsums[i+1][j+1][1] = bsums[i+1][j][1]+b;
                bsums[i+1][j+1][0] = bsums[i+1][j][0]+w;
            } else {
                for l in 0..2 {
                    bsums[i+1][j+1][l] = bsums[i+1][j][l];
                }
            }
        }
        for j in 0..k+1 {
            for l in 0..2 {
                wsums[i+1][j][l] += wsums[i][j][l];
                bsums[i+1][j][l] += bsums[i][j][l];
            }
        }
    }

    let mut mx = 0;
    for i in 0..k+1 {
        for j in 0..k+1 {
            let wval = wsums[k][k][1]+2*wsums[i][j][1]-wsums[i][k][1]-wsums[k][j][1]
                +wsums[i][k][0]+wsums[k][j][0]-2*wsums[i][j][0];
            let bval = bsums[k][k][1]+2*bsums[i][j][1]-bsums[i][k][1]-bsums[k][j][1]
                +bsums[i][k][0]+bsums[k][j][0]-2*bsums[i][j][0];
            let val = wval+bval;
            mx = max!(mx,val,n-val);
        }
    }
    println!("{}", mx);
}

