}

#[allow(unused_macros)]
macro_rules! vec_md {
    ( $ init : expr ; $ ( $ dim : expr ) ;* ) => { vec_md ! ( $ ( $ dim ) ;* => $ init ) };
    ( $ head : expr ; $ ( $ tail : expr ) ;* => $ init : expr ) => { vec ! [ vec_md ! ( $ ( $ tail ) ;* => $ init ) ; $ head ] };
    ( $ head : expr => $ init : expr ) => { vec ! [ $ init ; $ head ] };
}

fn main() {
    input! {
        n: usize,
        k: usize,
        xyc: [(u64, u64, chars); n]
    }

    let blacks = xyc.into_iter().map(|(x,y,c)| match c[0] {
        'W' => (x+k as u64,y),
        _ => (x,y)
    }).map(|(x,y)| ((x % (2*k as u64)) as usize, (y % (2*k as u64)) as usize));

    let mut black_pos = vec_md![0u64;2*k;2*k];
    for (x,y) in blacks {
        black_pos[y][x] += 1;
    }

    let mut s = vec_md![0u64;2*k+1;2*k+1];
    for i in 0..2*k {
        for j in 0..2*k {
            s[i+1][j+1] = s[i][j+1] + s[i+1][j] - s[i][j] + black_pos[i][j];
        }
    }

    let mut max = 0;
    for y in 0..k+1 {
        for x in 0..k+1 {
            let a = s[2*k][2*k]+s[y+k][x+k]-s[2*k][x+k]-s[y+k][2*k];
            let b = s[y][2*k] - s[y][x+k];
            let c = s[2*k][x] - s[y+k][x];
            let d = s[y+k][x+k] + s[y][x] - s[y+k][x] - s[y][x+k];
            let e = s[y][x];
            max = std::cmp::max(
                max,
                a+b+c+d+e
            );
        }
    }
    println!("{}", max);
}

use std::io;

fn main() {
    let mut buf: String = String::new();
    io::stdin().read_line(&mut buf).unwrap();
    let mut iter = buf.trim().split_whitespace();
    let n: i64 = iter.next().unwrap().parse::<i64>().unwrap();
    let k: i64 = iter.next().unwrap().parse::<i64>().unwrap();
    let mut vs: Vec<(i64, i64)> = Vec::new();
    for _ in 0..n {
        let mut buf = String::new();
        io::stdin().read_line(&mut buf).unwrap();
        let mut iter = buf.trim().split_whitespace();
        let x: i64 = iter.next().unwrap().parse::<i64>().unwrap();
        let y: i64 = iter.next().unwrap().parse::<i64>().unwrap();
        let c: char = iter.next().unwrap().chars().next().unwrap();
        if c == 'B' {
            vs.push((x % (2 * k), y % (2 * k)));
        } else {
            vs.push((x % (2 * k), (y + k) % (2 * k)));
        }
    }
    let mut max_c: i32 = 0;
    for i in 0..k {
        for j in 0..k {
            let mut c: i32 = 0;
            for l in 0..(n as usize) {
                let (xx, yy) = vs[l];
                c += if ((i <= xx && xx < k + i ) && (j <= yy && yy < k + j)) ||
                    ((xx < i || k + i <= xx) && (yy < j || k + j <= yy)) { 1 }
                else { 0 };
            }
            max_c = if max_c > c { max_c } else {c};
        }
    }
    println!("{}", max_c);
}

use std::io::*;
use std::cmp;

fn read<T: std::str::FromStr>() -> T {
    let stdin = stdin();
    let mut buf = String::new();
	stdin.lock().read_line(&mut buf);
	buf.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
	read::<String>().trim().split_whitespace()
        .map(|w| w.parse().ok().unwrap()).collect()
}

fn read_mat<T: std::str::FromStr>(n: usize) -> Vec<Vec<T>> {
    (0..n).map(|_| read_vec()).collect()
}

fn main() {
    let v = read_vec::<usize>();
    let (n,k) = (v[0],v[1]);
    let mut map: Vec<Vec<i64>> = vec![vec![0;2*k];k];
    for i in 0..n {
        let s = read::<String>();
        let w: Vec<&str> = s.trim().split_whitespace().collect();
        let x: usize = w[0].parse().ok().unwrap();
        let y: usize = w[1].parse().ok().unwrap();
        let xi = x % (2*k);
        let mut yi = y % (2*k);
        if w[2] == "W" {
            yi = (yi + k) % (2 * k);
        }
        if xi >= k {
            map[xi-k][(yi+k)%(2*k)] += 1;
        } else {
            map[xi][yi] += 1;
        }
    }

    for i in 1..k {
        map[i][0] += map[i-1][0];
    }
    for i in 1..2*k {
        map[0][i] += map[0][i-1];
    }
    for i in 1..k {
        for j in 1..2*k {
            map[i][j] += map[i-1][j] + map[i][j-1] - map[i-1][j-1];
        }
    }

    let mut max = map[k-1][k-1];
    for i in 1..k {
        let sum = map[k-1][k-1] + map[i-1][2*k-1] - 2*map[i-1][k-1];
        max = cmp::max(max,cmp::max(sum,n as i64 - sum));
    }
    for i in 0..k {
        let sum = map[k-1][i+k] - map[k-1][i];
        max = cmp::max(max,cmp::max(sum,n as i64 - sum));
        for j in 1..k {
            let sum = map[k-1][i+k] - map[k-1][i] + map[j-1][2*k-1] + 2*map[j-1][i] - 2*map[j-1][i+k];
            max = cmp::max(max,cmp::max(sum,n as i64 - sum));
        }
    }
    println!("{}",max);
}

use std::io::*;
use std::str::FromStr;

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn square_sum(sy: usize, sx: usize, k: usize, c: usize, sums: &Vec<Vec<Vec<usize>>>) -> usize {
    sums[c][sy + k][sx + k] +
    sums[c][sy][sx] -
    sums[c][sy][sx + k] -
    sums[c][sy + k][sx]

}

fn main() {
    let n: usize = read();
    let k: usize = read();
    let mut ps = vec![(0, 0, 0); n];
    for i in 0..n {
        let x: i64 = read();
        let y: i64 = read();
        let c: String = read();
        let x = (x + k as i64 * 100000000000) as usize % (2 * k);
        let y = (y + k as i64 * 100000000000) as usize % (2 * k);
        ps[i] = (x, y, if c == 'W'.to_string() { 0 } else { 1 });
    }
    let mut sums = vec![vec![vec![0 as usize; 4 * k + 1]; 4 * k + 1]; 2];
    for i in 0..n {
        let x = ps[i].0;
        let y = ps[i].1;
        let c = ps[i].2;
        sums[c][y + 1][x + 1] += 1;
        sums[c][y + 1][2 * k + x + 1] += 1;
        sums[c][2 * k + y + 1][x + 1] += 1;
        sums[c][2 * k + y + 1][2 * k + x + 1] += 1;
    }
    for c in 0..2 {
        for y in 0..4 * k {
            for x in 0..4 * k {
                sums[c][y + 1][x + 1] += sums[c][y + 1][x] + sums[c][y][x + 1] - sums[c][y][x];
            }
        }
    }
    let mut ans = 0;
    for offset_y in 0..k {
        for offset_x in 0..k {
            let mut sum = 0;
            sum += square_sum(offset_y, offset_x, k, 0, &sums);
            sum += square_sum(k + offset_y, offset_x, k, 1, &sums);
            sum += square_sum(offset_y, k + offset_x, k, 1, &sums);
            sum += square_sum(k + offset_y, k + offset_x, k, 0, &sums);
            ans = std::cmp::max(ans, sum);
        }
    }
    println!("{}", ans);
}

