use cumulative2::*;
use std::collections::BTreeSet;

fn main() {
    input! {
        n: usize,
        m: usize,
        xs: [(usize,usize,char_); n],
    }
    let mut xss = vec![vec![0i64; m]; m];
    let mut yss = vec![vec![0i64; m]; m];
    for &(x, y, c) in &xs {
        // eprintln!("c = {}", c);
        let x2 = x % (2 * m);
        let y2 = y % (2 * m);
        let c = if (x2 / m + y2 / m) % 2 == 0 {
            if c == 'B' {
                -1
            } else {
                1
            }
        } else {
            if c == 'B' {
                1
            } else {
                -1
            }
        };
        if c == 1 {
            xss[y % m][x % m] += 1;
        } else {
            yss[y % m][x % m] += 1;
        }
    }
    let xss_cu2 = gen_cu2(0, &xss);
    let yss_cu2 = gen_cu2(0, &yss);
    let mut res = 0;
    for y in 0..m + 1 {
        for x in 0..m + 1 {
            let t = range2(&xss_cu2, 0, 0, x, y)
                + range2(&xss_cu2, x, y, m, m)
                + range2(&yss_cu2, x, 0, m, y)
                + range2(&yss_cu2, 0, y, x, m);
            //// eprintln!("x = {}, y = {}, t = {}", x, y, t);
            res = max(res, t);
            let u = range2(&yss_cu2, 0, 0, x, y)
                + range2(&yss_cu2, x, y, m, m)
                + range2(&xss_cu2, x, 0, m, y)
                + range2(&xss_cu2, 0, y, x, m);
            //// eprintln!("x = {}, y = {}, t = {}", x, y, t);
            res = max(res, u);
        }
    }
    //// eprintln!("{:?}", xss_cu2);
    println!("{}", res);
}

