fn main() {
    input! {
        n: usize,
        k: usize,
        xyc: [(u64, u64, chars); n]
    }

    let blacks = xyc.iter().map(|(x,y,c)| match c[0] {
        'W' => (*x+k as u64,*y),
        _ => (*x,*y)
    }).map(|(x,y)| ((x % (2*k as u64)) as usize, (y % (2*k as u64)) as usize));

    let mut black_pos = vec_md![0u64;2*k;2*k];
    for (x,y) in blacks {
        black_pos[y][x] += 1;
    }

    let mut s = vec_md![0u64;2*k+1;2*k+1];
    for i in 0..2*k {
        for j in 0..2*k {
            s[i+1][j+1] = s[i][j+1] + s[i+1][j] - s[i][j] + black_pos[i][j];
        }
    }

    let mut max = 0;
    for y in 0..k+1 {
        for x in 0..k+1 {
            let a = s[2*k][2*k]+s[y+k][x+k]-s[2*k][x+k]-s[y+k][2*k];
            let b = s[y][2*k] - s[y][x+k];
            let c = s[2*k][x] - s[y+k][x];
            let d = s[y+k][x+k] + s[y][x] - s[y+k][x] - s[y][x+k];
            let e = s[y][x];
            max = std::cmp::max(
                max,
                a+b+c+d+e
            );
        }
    }
    println!("{}", max);
}

use std::io::*;
use std::str::FromStr;

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn square_sum(sy: usize, sx: usize, k: usize, c: usize, sums: &Vec<Vec<Vec<usize>>>) -> usize {
    sums[c][sy + k][sx + k] +
    sums[c][sy][sx] -
    sums[c][sy][sx + k] -
    sums[c][sy + k][sx]
}

fn main() {
    let n: usize = read();
    let k: usize = read();
    let mut ps = vec![(0, 0, 0); n];
    for i in 0..n {
        let x: usize = read();
        let y: usize = read();
        let c: String = read();
        let x = x % (2 * k);
        let y = y % (2 * k);
        ps[i] = (x, y, if c == 'W'.to_string() { 0 } else { 1 });
    }
    let mut sums = vec![vec![vec![0 as usize; 3 * k + 2]; 3 * k + 2]; 2];
    for i in 0..n {
        let x = ps[i].0;
        let y = ps[i].1;
        let c = ps[i].2;
        for dy in [0, 2 * k].iter() {
            for dx in [0, 2 * k].iter() {
                let nx = x + dx;
                let ny = y + dy;
                if ny > 3 * k || nx > 3 * k { continue; }
                sums[c][ny + 1][nx + 1] += 1;
            }
        }
    }
    for c in 0..2 {
        for y in 0..3 * k+1 {
            for x in 0..3 * k+1 {
                sums[c][y + 1][x + 1] += sums[c][y + 1][x] + sums[c][y][x + 1] - sums[c][y][x];
            }
        }
    }
    let mut ans = 0;
    for offset_y in 0..k+2 {
        for offset_x in 0..k+2 {
            let mut sum = 0;
            sum += square_sum(offset_y, offset_x, k, 0, &sums);
            sum += square_sum(k + offset_y, offset_x, k, 1, &sums);
            sum += square_sum(offset_y, k + offset_x, k, 1, &sums);
            sum += square_sum(k + offset_y, k + offset_x, k, 0, &sums);
            ans = std::cmp::max(ans, sum);
        }
    }
    println!("{}", ans);
}

