type Graph = Vec<Vec<usize>>;

fn main() {
    input! {
        n: usize,
        k: usize,
        p: [(usize, usize, chars); n],
    }

    let k2 = k * 2;

    let p = p
        .into_iter()
        .map(|(x, y, c)| (x % k2, y % k2, c[0]))
        .collect::<Vec<_>>();

    let mut w = vec![vec![0; k2 + 1]; k2 + 1];
    let mut b = vec![vec![0; k2 + 1]; k2 + 1];

    for &(x, y, c) in &p {
        if c as char == 'W' {
            w[y][x] += 1;
        } else {
            b[y][x] += 1;
        }
    }

    let mut wsum = vec![vec![0; k2 + 1]; k2 + 1];
    let mut bsum = vec![vec![0; k2 + 1]; k2 + 1];

    for i in 1..k2 + 1 {
        for j in 1..k2 + 1 {
            wsum[i][j] += wsum[i][j - 1] + w[i - 1][j - 1];
            bsum[i][j] += bsum[i][j - 1] + b[i - 1][j - 1];
        }
    }

    for j in 1..k2 + 1 {
        for i in 1..k2 + 1 {
            wsum[i][j] += wsum[i - 1][j];
            bsum[i][j] += bsum[i - 1][j];
        }
    }

    let mut ans = 0;

    for i in 1..k + 1 {
        for j in 1..k + 1 {
            let mut s1 = 0;
            let mut s2 = 0;
            for ii in 0..3 {
                let i2 = i + ii * k;
                for jj in 0..3 {
                    let j2 = j + jj * k;
                    // println!("{} {} {} {}", i, j, i2, j2);
                    let (add1, add2) = if (ii + jj) % 2 == 0 {
                        (&wsum, &bsum)
                    } else {
                        (&bsum, &wsum)
                    };
                    s1 += add1[min(i2, k2)][min(j2, k2)];
                    s2 += add2[min(i2, k2)][min(j2, k2)];
                    if i2 >= k {
                        s1 -= add1[i2 - k][min(j2, k2)];
                        s2 -= add2[i2 - k][min(j2, k2)];
                    }
                    if j2 >= k {
                        s1 -= add1[min(i2, k2)][j2 - k];
                        s2 -= add2[min(i2, k2)][j2 - k];
                    }
                    if i2 >= k && j2 >= k {
                        s1 += add1[i2 - k][j2 - k];
                        s2 += add2[i2 - k][j2 - k];
                    }
                }
            }
            ans = max(ans, s1);
            ans = max(ans, s2);
        }
    }

    println!("{}", ans);
}

use std::io::*;
use std::str::FromStr;

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn square_sum(sy: usize, sx: usize, k: usize, c: usize, sums: &Vec<Vec<Vec<usize>>>) -> usize {
    sums[c][sy + k][sx + k] +
    sums[c][sy][sx] -
    sums[c][sy][sx + k] -
    sums[c][sy + k][sx]

}

fn main() {
    let n: usize = read();
    let k: usize = read();
    let mut ps = vec![(0, 0, 0); n];
    for i in 0..n {
        let x: i64 = read();
        let y: i64 = read();
        let c: String = read();
        let x = (x + k as i64 * 100000000000) as usize % (2 * k);
        let y = (y + k as i64 * 100000000000) as usize % (2 * k);
        ps[i] = (x, y, if c == 'W'.to_string() { 0 } else { 1 });
    }
    let mut sums = vec![vec![vec![0 as usize; 3 * k + 1]; 3 * k + 1]; 2];
    for i in 0..n {
        let x = ps[i].0;
        let y = ps[i].1;
        let c = ps[i].2;
        for dy in [0, 2 * k].iter() {
            for dx in [0, 2 * k].iter() {
                let nx = x + dx;
                let ny = y + dy;
                if nx >= 3 * k || ny >= 3 * k { continue; }
                sums[c][ny + 1][nx + 1] += 1;
            }
        }
    }
    for c in 0..2 {
        for y in 0..3 * k {
            for x in 0..3 * k {
                sums[c][y + 1][x + 1] += sums[c][y + 1][x] + sums[c][y][x + 1] - sums[c][y][x];
            }
        }
    }
    let mut ans = 0;
    for offset_y in 0..k+1 {
        for offset_x in 0..k+1 {
            let mut sum = 0;
            sum += square_sum(offset_y, offset_x, k, 0, &sums);
            sum += square_sum(k + offset_y, offset_x, k, 1, &sums);
            sum += square_sum(offset_y, k + offset_x, k, 1, &sums);
            sum += square_sum(k + offset_y, k + offset_x, k, 0, &sums);
            ans = std::cmp::max(ans, sum);
        }
    }
    println!("{}", ans);
}

