use input::*;

fn main() {
    let (n, k): (usize, usize);
    input!(n, k);
    let mut v = vec![vec![0; 2 * k + 1]; 2 * k + 1];
    let mut w = vec![vec![0; 4 * k + 1]; 4 * k + 1];
    for _ in 0..n {
        let (x, y, c): (usize, usize, String);
        input!(x, y, c);
        if c == "B" {
            v[x % (2 * k) + 1][y % (2 * k) + 1] += 1_usize;
        } else {
            v[((x + k) % (2 * k)) + 1][(y % (2 * k)) + 1] += 1;
        }
    }

    for i in 1..4 * k + 1 {
        for j in 1..4 * k + 1 {
            w[i][j] = w[i - 1][j] + v[(i - 1) % (2 * k) + 1][(j - 1) % (2 * k) + 1];
        }
    }
    for i in 1..4 * k + 1 {
        for j in 1..4 * k + 1 {
            w[i][j] += w[i][j - 1];
        }
    }

    let mut ans = 0;
    for i in 1..k + 1 {
        for j in 1..k + 1 {
            let buf = w[i + k - 1][j + k - 1] + v[i - 1][j - 1]
                - w[i - 1][j + k - 1]
                - w[i + k - 1][j - 1]
                + w[i + k + k - 1][j + k + k - 1]
                + w[i - 1 + k][j - 1 + k]
                - w[i - 1 + k][j + k - 1 + k]
                - w[i + k - 1 + k][j - 1 + k];
            ans = std::cmp::max(ans, buf);
        }
    }
    println!("{}", ans);
}

