        for j in 0..k2 {
            ba[i + 1][j + 1] = ba[i + 1][j] + ba[i][j + 1] - ba[i][j] + b[i][j]
        }
    }
    let get2a = |x1: usize, x2: usize, y1: usize, y2: usize| {
        ba[x2][y2] - ba[x1][y2] - ba[x2][y1] + ba[x1][y1]
    };
    for i in 0..k {
        for j in 0..k {
            let x = get2a(i, i + k, 0, k2) + get2a(0, k2, j, j + k) - 2 * get2a(i, i + k, j, j + k);
