fn main() {
    let (n, k): (usize, usize) = read();

    let l = k*2;
    let mut white_tbl = vec![vec![0; l]; l];
    let mut black_tbl = vec![vec![0; l]; l];

    for _i in 0..n {
        let (x, y, c): (usize, usize, String) = read();
        if c.chars().nth(0).unwrap() == 'B' {
            black_tbl[x%l][y%l] += 1;
        } else {
            white_tbl[x%l][y%l] += 1;
        }
    }

    let mut white_tbl_sum = vec![vec![0; l+1]; l+1];
    let mut black_tbl_sum = vec![vec![0; l+1]; l+1];

    for i in 1..l+1 {
        for j in 1..l+1 {
            black_tbl_sum[i][j] = black_tbl[i-1][j-1] - black_tbl_sum[i-1][j-1] + black_tbl_sum[i-1][j] + black_tbl_sum[i][j-1];
            white_tbl_sum[i][j] = white_tbl[i-1][j-1] - white_tbl_sum[i-1][j-1] + white_tbl_sum[i-1][j] + white_tbl_sum[i][j-1];
        }
    }

    let mut best = 0;
    for i in 0..k {
        for j in 0..k {
            best = max(best, solve(i, j, &black_tbl_sum, &white_tbl_sum));
        }
    }
    println!("{}", best);
}

fn solve(i: usize, j: usize, black_tbl: &Vec<Vec<i32>>, white_tbl: &Vec<Vec<i32>>) -> i32 {
    let l = black_tbl.len()-1;
    let k = l / 2;

    square_sum(i, j, k, black_tbl) + square_sum((i+k)%l, (j+k)%l, k, black_tbl)
     + square_sum((i+k)%l, j, k, white_tbl) + square_sum(i, (j+k)%l, k, white_tbl)
}



fn square_sum(fi: usize, fj: usize, k: usize, tbl: &Vec<Vec<i32>>) -> i32 {
    let l = k*2;
    let ti = min(fi+k, l);
    let tj = min(fj+k, l);
    let mut ret = rect_sum(fi, fj, ti, tj, tbl);
    if fi+k > l || fj+k > l {
        let ti2 = (fi+k)%l;
        let tj2 = (fj+k)%l;
        let fi2 = if fi+k > l { 0 } else { fi };
        let fj2 = if fj+k > l { 0 } else { fj };
        ret += rect_sum(fi2, fj2, ti2, tj2, tbl);
    }
    ret
}

fn rect_sum(fi: usize, ti: usize, fj: usize, tj: usize, tbl: &Vec<Vec<i32>>) -> i32 {
    tbl[ti][tj] - tbl[fi][tj] - tbl[ti][fj] + tbl[fi][fj]
}

