use std::cmp::*;
use std::collections::*;
use std::mem::*;

fn main() {
    let (r, w, e) = (std::io::stdin(), std::io::stdout(), std::io::stderr());
    let mut io = IO::new(r.lock(), w.lock(), e.lock());
    /*
    2K * 2K 通り試す.座標は mod 2K としてよい
    二次元累積和でよさそう
    */
    let (N, K) = (io.read::<usize>(), io.read::<usize>());
    // let mut b = vec![vec![0; 2020]; 2020];
    // let mut s = vec![vec![0; 4040]; 4040];

    let mut xy = vec![vec![0; K * 2 + 1]; K * 2 + 1];
    for i in 0..N {
        let (mut x, mut y, c) = (io.read::<usize>(), io.read::<usize>(), io.read::<char>());
        if c == 'W' {
            xy[x % (2 * K)][y % (K * 2)] += 1;
        // y += K;
        } else {
            xy[(x + K) % (K * 2)][y % (2 * K)] += 1;
        }
        // b[x % (2 * K)][y % (2 * K)] += 1;
    }

    for xx in 0..2 * K {
        for yy in 1..2 * K {
            xy[xx][yy] += xy[xx][yy - 1];
        }
    }
    for yy in 0..2 * K {
        for xx in 1..2 * K {
            xy[xx][yy] += xy[xx - 1][yy];
        }
    }
    let mut ans = 0;
    let check = |x: usize, y: usize| -> usize {
        let kk = K * 2 - 1;

        xy[kk][kk]
            + if x > 0 { xy[x - 1][kk] } else { 0 }
            + if y > 0 { xy[kk][y - 1] } else { 0 }
            + 2 * xy[x + K - 1][y + K - 1]
            + 2 * if x > 0 && y > 0 { xy[x - 1][y - 1] } else { 0 }
            - xy[x + K - 1][kk]
            - xy[kk][y + K - 1]
            - 2 * if x > 0 { xy[x - 1][y + K - 1] } else { 0 }
            - 2 * if y > 0 { xy[x + K - 1][y - 1] } else { 0 }
    };
    for xx in 0..K {
        for yy in 0..K {
            let tmp = check(xx, yy);
            ans = max(ans, tmp);
            ans = max(ans, N - tmp);
        }
    }
    io.writeln(ans);
}

