            let buf = v[i + k - 1][j + k - 1] + v[i - 1][j - 1]
                - v[i - 1][j + k - 1]
                - v[i + k - 1][j - 1]
                + v[i - 1][j - 1]
                + v[2 * k][j - 1]
                - v[i][j - 1]
                + v[i - 1][2 * k]
                - v[i - 1][j]
                + v[2 * k][2 * k]
                + v[i + k - 1][j + k - 1]
                - v[2 * k][j + k - 1]
                - v[i + k - 1][2 * k];
            ans = std::cmp::max(ans, buf);
        }
    }
    println!("{}", ans);
}

