use std::io::prelude::*;

fn input<T>() -> T
where
    T: std::str::FromStr,
{
    let stdin = std::io::stdin();
    let token: String = stdin
        .lock()
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

fn main() {
    let n: usize = input();
    let k: usize = input();
    let xyc: Vec<(usize, usize, String)> = (0..n)
        .map(|_| {
            let x = input();
            let y = input();
            let c: String = input();
            (x, y, c)
        })
        .collect();

    let kk = 2 * k;
    let mut p = vec![vec![0; kk + 1]; kk + 1];
    for (x, y, c) in xyc {
        if c == "W" {
            p[x % kk][(y + k) % kk] += 1;
        } else {
            p[x % kk][y % kk] += 1;
        }
    }

    let mut sum = vec![vec![0; kk + 1]; kk + 1];
    for i in 1..kk + 1 {
        for j in 1..kk + 1 {
            sum[i][j] = sum[i - 1][j] + sum[i][j - 1] - sum[i - 1][j - 1] + p[i - 1][j - 1];
        }
    }

    let mut ans = 0;
    for i in 1..k + 1 {
        for j in 1..k + 1 {
            let mut temp = 0;
            temp += sum[i - 1][j - 1];
            temp += sum[i - 1][kk] - sum[i - 1][j - 1 + k];
            temp += sum[i - 1 + k][j - 1 + k] - sum[i - 1][j - 1 + k] - sum[i - 1 + k][j - 1]
                + sum[i - 1][j - 1];
            temp += sum[kk][j - 1] - sum[i - 1 + k][j - 1];
            temp +=
                sum[kk][kk] - sum[i - 1 + k][kk] - sum[kk][j - 1 + k] + sum[i - 1 + k][j - 1 + k];
            ans = std::cmp::max(ans, temp);
        }
    }

    println!("{}", ans);
}

