            B2[i+1][j+1] += B[i][j] + B2[i+1][j] + B2[i][j+1] - B2[i][j];
            W2[i+1][j+1] += W[i][j] + W2[i+1][j] + W2[i][j+1] - W2[i][j];
        }
    }
    let mut res = 0;
    for i in 0..2*k{

        for j in 0..2*k{
            let mut tmp = 0;
            tmp += B2[i+k][j+k] - B2[i+k][j] - B2[i][j+k] + B2[i][j]; 
            tmp += B2[i+2*k][j+2*k] - B2[i+2*k][j+k] - B2[i+k][j+2*k] + B2[i+k][j+k];

            tmp += W2[i+2*k][j+k] - W2[i+2*k][j] - W2[i+k][j+k] + W2[i+k][j]; 
            tmp += W2[i+k][j+2*k] - W2[i][j+2*k] - W2[i+2*k][j+k] + W2[i][j+k];
            res = cmp::max(res, tmp);
        }
    }
    println!("{}", res);
}

