        } else {
            w[x % (2 * k)][y % (2 * k)] += 1;
        }
    }
    let cs_b = CumSum2D::new(&b);
    let cs_w = CumSum2D::new(&w);

    let mut ans = 0;
    for s in 0..k + 1 {
        for t in 0..k + 1 {
            let a =
                  cs_b.sum(0..t, 0..s)
                + cs_w.sum(0..t, s..s+k)
                + cs_b.sum(0..t, s+k..k)
                + cs_w.sum(t..t+k, 0..s)
                + cs_b.sum(t..t+k, s..s+k)
                + cs_w.sum(t..t+k, s+k..k+k)
                + cs_b.sum(t+k..k+k, 0..s)
                + cs_w.sum(t+k..k+k, s..s+k)
                + cs_b.sum(t+k..k+k, s+k..k+k);
            ans = max!(ans, a);
            let a =
                  cs_w.sum(0..t, 0..s)
                + cs_b.sum(0..t, s..s+k)
                + cs_w.sum(0..t, s+k..k)
                + cs_b.sum(t..t+k, 0..s)
                + cs_w.sum(t..t+k, s..s+k)
                + cs_b.sum(t..t+k, s+k..k+k)
                + cs_w.sum(t+k..k+k, 0..s)
                + cs_b.sum(t+k..k+k, s..s+k)
                + cs_w.sum(t+k..k+k, s+k..k+k);
            ans = max!(ans, a);
        }
