#[derive(Debug, Clone, PartialEq)]
enum Color {
    W,
    B,
}

#[derive(Debug, Clone, PartialEq)]
struct Data {
    x: i64,
    y: i64,
    c: Color,
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let output = run(input.trim().to_string());
    println!("{}", output);
}

fn run(input: String) -> String {
    let k = input
        .split_whitespace()
        .nth(1)
        .unwrap()
        .parse::<i64>()
        .unwrap();
    let list = input
        .split("\n")
        .skip(1)
        .map(|x| {
            let l = x.split_whitespace().collect::<Vec<_>>();
            Data {
                x: l[0].parse::<i64>().unwrap(),
                y: l[1].parse::<i64>().unwrap(),
                c: if l[2] == "W" { Color::W } else { Color::B },
            }
        })
        .collect::<Vec<_>>();

    let mut max = 0;
    //x,yをずらす
    for (true_color, false_color) in vec![(Color::B, Color::W), (Color::W, Color::B)] {
        for dx in 0..k {
            for dy in 0..k {
                let count = list.iter()
                    .filter(|&d| {
                        let xm = (d.x + dx) % (k * 2) >= k;
                        let ym = (d.y + dy) % (k * 2) >= k;
                        //色
                        let m = xm == ym;
                        d.c == if m {
                            true_color.clone()
                        } else {
                            false_color.clone()
                        }
                    })
                    .count();

                if max < count {
                    max = count;
                }
            }
        }
    }

    max.to_string()
}

