fn main() {
    let (n, k): (usize, usize);
    input!(n, k);
    let mut v = vec![vec![0; 2 * k + 1]; 2 * k + 1];
    for _ in 0..n {
        let (x, y, c): (usize, usize, String);
        input!(x, y, c);
        if c == "B" {
            v[x % (2 * k) + 1][y % (2 * k) + 1] += 1_usize;
        } else {
            v[((x + k) % (2 * k)) + 1][(y % (2 * k)) + 1] += 1;
        }
    }

    for i in 1..2 * k + 1 {
        for j in 1..2 * k + 1 {
            v[i][j] += v[i - 1][j] + v[i][j - 1] - v[i - 1][j - 1];
        }
    }

    let mut ans = 0;
    for i in 1..k + 1 {
        for j in 1..k + 1 {
            let buf = v[i + k - 1][j + k - 1] + v[i - 1][j - 1]
                - v[i - 1][j + k - 1]
                - v[i + k - 1][j - 1]
                + v[i - 1][j - 1]
                + v[2 * k][j - 1]
                - v[i + k - 1][j - 1]
                + v[i - 1][2 * k]
                - v[i - 1][j + k - 1]
                + v[2 * k][2 * k]
                + v[i + k - 1][j + k - 1]
                - v[2 * k][j + k - 1]
                - v[i + k - 1][2 * k];
            ans = std::cmp::max(ans, buf);
        }
    }
