use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet, VecDeque};
fn main() {
    input! {
        N: usize,
        K: usize,
        kibo: [(usize, usize, char); N],
    }
    let mut candidate = vec![ vec![0_isize; 2*K]; 2*K];
    for &mut(mut row, mut col, c) in kibo.iter_mut() {
        if c == 'W' {
            row += K;
        }
        row %= 2*K;
        col %= 2*K;

        let i = row.saturating_sub(K-1);
        let j = col.saturating_sub(K-1);
        candidate[i][j] += 1;
        match (i+K < 2*K, j+K < 2*K) {
            (true, true) => {
                candidate[i+K][j+K] -= 1;
                candidate[i+K][j] -= 1;
                candidate[i][j+K] -= 1;
            },
            (true, false) => {
                candidate[i+K][j] -= 1;
            },
            (false, true) => {
                candidate[i][j+K] -= 1;
            },
            (false, false) => (),
        }
    }

    for row in 0..2*K {
        for col in 1..2*K {
            candidate[row][col] += candidate[row][col-1];
        }
    }
    for col in 0..2*K {
        for row in 1..2*K {
            candidate[row][col] += candidate[row-1][col];
        }
    }
    let mut max = 0;
    for row in 0..2*K {
        for col in 0..2*K {
            max = cmp::max(max, candidate[row][col]);
        }
    }
    println!("{}", max);
}

