    let p = p
        .iter()
        .map(|&(x, y, c)| (x % k2, y % k2, c))
        .collect::<Vec<_>>();

    let mut w = vec![vec![0; k2 + 1]; k2 + 1];
    let mut b = vec![vec![0; k2 + 1]; k2 + 1];

    for &(x, y, c) in &p {
        if c == 'W' {
            w[y][x] += 1;
        } else {
            b[y][x] += 1;
        }
    }

    let mut wsum = vec![vec![0; k2 + 1]; k2 + 1];
    let mut bsum = vec![vec![0; k2 + 1]; k2 + 1];

    for i in 1..k2 + 1 {
        for j in 1..k2 + 1 {
            wsum[i][j] += wsum[i][j - 1] + w[i - 1][j - 1];
            bsum[i][j] += bsum[i][j - 1] + b[i - 1][j - 1];
        }
    }

    for j in 1..k2 + 1 {
        for i in 1..k2 + 1 {
            wsum[i][j] += wsum[i - 1][j];
            bsum[i][j] += bsum[i - 1][j];
        }
    }

    let mut ans = 0;

    for i in 1..k + 1 {
        for j in 1..k + 1 {
            let mut s1 = 0;
            let mut s2 = 0;
            for ii in 0..3 {
                let i2 = i + ii * k;
                for jj in 0..3 {
                    let j2 = j + jj * k;
                    // println!("{} {} {} {}", i, j, i2, j2);
                    let (add1, add2) = if (ii + jj) % 2 == 0 {
                        (&wsum, &bsum)
                    } else {
                        (&bsum, &wsum)
                    };
                    s1 += add1[min(i2, k2)][min(j2, k2)];
                    s2 += add2[min(i2, k2)][min(j2, k2)];
                    if i2 >= k {
                        s1 -= add1[i2 - k][min(j2, k2)];
                        s2 -= add2[i2 - k][min(j2, k2)];
                    }
                    if j2 >= k {
                        s1 -= add1[min(i2, k2)][j2 - k];
                        s2 -= add2[min(i2, k2)][j2 - k];
                    }
                    if i2 >= k && j2 >= k {
                        s1 += add1[i2 - k][j2 - k];
                        s2 += add2[i2 - k][j2 - k];
                    }
                }
            }
            ans = max(ans, s1);
            ans = max(ans, s2);
        }
    }

    println!("{}", ans);
}

