    let (n, k) = (line[0], line[1]);
    let mut hopes: Vec<(usize, usize)> = vec![];
    for _ in 0..n{
        let mut line = read_as_string();
        let color = line.pop().unwrap();
        let line = line.trim().split_whitespace().map(|c| usize::from_str(c).unwrap())
            .collect::<Vec<usize>>();
        let (x, mut y) = (line[0], line[1]);

        if color == 'W'{
            y += k;
        }

        hopes.push(((x%(2*k))+k+1, (y%(2*k))+k+1));
    }

    let mut acc_map = vec![vec![0;4*k+1];4*k+1];

    for &hope in &hopes{
        acc_map[hope.1][hope.0] = 1;
    }

    //accumulate
    for i in k+1..4*k+1{
        for j in k+1..4*k+1{
            acc_map[i][j] += acc_map[i-1][j] + acc_map[i][j-1] - acc_map[i-1][j-1];
        }
    }
    /*
    for row in acc_map.iter().rev(){
        println!("{:?}", row);
    }
    */
    let mut ans = 0;

    for i in k+1..2*k+1{
        for j in k+1..2*k+1{
            let mut cur_ans = 0;
            let ru_list = vec![
                (j+k-1,   i+k-1),
                (j+2*k-1, i-1),
                (j+2*k-1, i+2*k-1),
                (j-1,     i+2*k-1),
                (j-1,     i-1)
            ];
            for ru in ru_list{
                cur_ans += acc_map[ru.0][ru.1] - acc_map[ru.0-k][ru.1] - acc_map[ru.0][ru.1-k] +
                    acc_map[ru.0-k][ru.1-k];
            }
            if cur_ans > ans{
                ans = cur_ans;
            }
        }
    }

    println!("{}", ans);
}

