macro_rules! input {
  (source = $s:expr, $($r:tt)*) => {
    let mut iter = $s.split_whitespace();
    input_inner!{iter, $($r)*}
  };
  ($($r:tt)*) => {
    #[allow(unused_mut)]
    let mut s = {
      use std::io::Read;
      let mut s = String::new();
      std::io::stdin().read_to_string(&mut s).unwrap();
      s
    };
    let mut iter = s.split_whitespace();
    input_inner!{iter, $($r)*}
  };
}

macro_rules! input_inner {
  ($iter:expr) => {};
  ($iter:expr, ) => {};

  ($iter:expr, $var:ident : $t:tt $($r:tt)*) => {
    let $var = read_value!($iter, $t);
    input_inner!{$iter $($r)*}
  };
}

macro_rules! read_value {
  ($iter:expr, ( $($t:tt),* )) => {
    ( $(read_value!($iter, $t)),* )
  };

  ($iter:expr, [ $t:tt ; $len:expr ]) => {
    (0..$len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
  };

  ($iter:expr, chars) => {
    read_value!($iter, String).chars().collect::<Vec<char>>()
  };

  ($iter:expr, usize1) => {
    read_value!($iter, usize) - 1
  };

  ($iter:expr, $t:ty) => {
    $iter.next().unwrap().parse::<$t>().expect("Parse error")
  };
}

fn main() {
  input! {
    n: usize,
    k: usize,
    query: [(usize, usize, chars); n],
  }
  let m = 2 * k;
  let mut field = vec![vec![0i64; m]; m];
  for &(x, y, ref c) in &query {
    let y = match &c.first().unwrap() {
      'B' => y,
      'W' => y + k,
      _ => unreachable!(),
    };
    field[y % m][x % m] += 1;
    field[(y + k) % m][(x % k) % m] += 1;
  }
  let mut total = vec![vec![0i64; m + 1]; m + 1];
  for i in 0 .. m {
    for j in 0 .. m {
      total[i+1][j+1] = total[i][j+1] + total[i+1][j] - total[i][j] + field[i][j];
    }
  }
  let mut ans = 0;
  for i in 1 .. k+1 {
    for j in 1 .. k+1 {
      ans = cmp::max(ans, total[i + k][j + k] - total[i][j + k] - total[i + k][j] + total[i][j]);
    }
  }

  println!("{}", ans);
}

