fn main(){
    input!{
        n:usize,
        k:usize,
        xyci:[(usize, usize, chars);n],
    }
    let mut xyc = xyci.clone();
    let mut B = vec![vec![0i32;k*4+1];k*4+1];
    let mut W = vec![vec![0i32;k*4+1];k*4+1];
    for i in 0..xyc.len(){
        if xyc[i].2[0] == 'B'{
            let x = xyc[i].0%(2*k);
            let y = xyc[i].1%(2*k);
            B[x][y]+=1;
            B[x + 2*k][y] +=1;
            B[x][y+2*k] += 1;
            B[x+2*k][y+2*k] += 1;
        }
        else{
            let x = xyc[i].0%(2*k);
            let y = xyc[i].1%(2*k);
            W[x][y]+=1;
            W[x + 2*k][y] +=1;
            W[x][y+2*k] += 1;
            W[x+2*k][y+2*k] += 1;


        }
    }
    let mut B2 = vec![vec![0i32;k*4+1];k*4+1];

    let mut W2 = vec![vec![0i32;k*4+1];k*4+1];

    for i in 0..k*4{
        for j in 0..k*4{
            B2[i+1][j+1] += B[i][j] + B2[i+1][j] + B2[i][j+1] - B2[i][j];
            W2[i+1][j+1] += W[i][j] + W2[i+1][j] + W2[i][j+1] - W2[i][j];
        }
    }
    let mut res = 0;
    for i in 0..2*k{

        for j in 0..2*k{
            let mut tmp = 0;
            let x1 = i;
            let y1 = j;
            let x2 = i+k;
            let y2 = j+k;
            tmp += B2[x2][y2] - B2[x1][y2] - B2[x2][y1] + B2[x1][y1]; 
            tmp += B2[x2+k][y2+k] - B2[x2][y2+k] - B2[x2+k][y2] + B2[x2][y2];

            tmp += W2[x2+k][y2] - W2[x2][y2] - W2[x2+k][y1] + W2[x2][y1]; 
            tmp += W2[x2][y2+k] - W2[x2][y2] - W2[x1][y2+k] + W2[x1][y2];
            res = cmp::max(res, tmp);
        }
    }
    println!("{}", res);
}

use std::str::FromStr;
use std::fmt::Debug;
use std::cmp;

#[allow(dead_code)]
fn read_as_vec<T>() -> Vec<T>
where T: FromStr, <T as FromStr>::Err : Debug{
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    s.trim().split_whitespace().map(|c| T::from_str(c).unwrap()).collect()

}

#[allow(dead_code)]
fn read_as_string() -> String{
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    s.trim().to_string()
}

fn main(){
    let line = read_as_vec::<usize>();

    let (n, k) = (line[0], line[1]);
    let mut hopes: Vec<(usize, usize)> = vec![];
    for _ in 0..n{
        let mut line = read_as_string();
        let color = line.pop().unwrap();
        let line = line.trim().split_whitespace().map(|c| usize::from_str(c).unwrap())
            .collect::<Vec<usize>>();
        let (x, mut y) = (line[0], line[1]);

        if color == 'W'{
            y += k;
        }

        hopes.push(((x%(2*k))+k+1, (y%(2*k))+k+1));
    }

    let mut acc_map = vec![vec![0;4*k+1];4*k+1];

    for &hope in &hopes{
        acc_map[hope.1][hope.0] += 1;
    }

    //accumulate
    for i in k+1..4*k+1{
        for j in k+1..4*k+1{
            acc_map[i][j] += acc_map[i-1][j] + acc_map[i][j-1] - acc_map[i-1][j-1];
        }
    }

    /*
    for row in acc_map.iter().rev(){
        println!("{:?}", row);
    }
    */
    let mut ans = 0;

    for i in k+1..2*k+1{
        for j in k+1..2*k+1{
            let mut cur_ans = 0;
            //println!("i = {}, j = {}", i, j);
            let ru_list = vec![
                (j+k-1,   i+k-1),
                (j+2*k-1, i-1),
                (j+2*k-1, i+2*k-1),
                (j-1,     i+2*k-1),
                (j-1,     i-1)
            ];
            //println!("{:?}", ru_list);
            for ru in ru_list{
                cur_ans += acc_map[ru.0][ru.1] + acc_map[ru.0-k][ru.1-k] - acc_map[ru.0-k][ru.1] - acc_map[ru.0][ru.1-k]
            }
            //println!("n = {}, cur_ans = {}, ans = {}", n, cur_ans, ans);
            ans = cmp::max(cmp::max(n- cur_ans, cur_ans), ans);
            //println!("n = {}, cur_ans = {}, ans = {} DONE", n, cur_ans, ans);
            /*
            if cur_ans > ans{
                ans = cur_ans;
            }
            */
        }
    }

    println!("{}", ans);
}
